window.PACK={"book":{"id":"diwan-radi","title":"ديوان الشريف الرضي","type":"diwan","author":"الشريف الرضي (ت ٤٠٦هـ)","source":"الموسوعة الشعرية / المكتبة الشاملة عبر مشروع OpenITI","optional":true,"era":"abbasi","packVersion":"9632af34a1ab"},"items":[{"id":"diwan-radi:1","bookId":"diwan-radi","type":"poem","seq":1,"chapter":"البحر: طويل","title":"جزاء أمير المؤمنين ثنائي","page":"","text":"جزاء أمير المؤمنين ثنائي … على نعم ما تنقضي وعطاء\nاقام الليالي عن بقايا فريستي … ولم يبق منها اليوم غير ذماء\nوأدنى أقاصي جاهه لوسائلي … وشد اواخي جوده برجائي\nوعلمني كيف الطلوع الى العلى … وكيف نعيم المرء بعد شقاء\nوكيف ارد الدهر عن حدثانه … وألقى صدور الخيل أي لقاء\nفما لي أغضي عن مطالب جمة … واعلم اني عرضة لفناء\nوأترك سمر الخط ظمأى خلية … وشر قنا ما كن غير رواء\nإذا ما جررت الرمح لم يثنني أب … يليح ولا ام تصيح ورائي\nوشيعني قلب اذا ما امرته … أطاع بعزم لا يروغ ورائي\nارى الناس يهوون الخلاص من الردى … وتكملة المخلوق طول عناء\nويستقبحون القتل والقتل راحة … وأتعب ميت من يموت بداء\nفلست ابن ام الخيل ان لم اعد بها … عوابس تأبى الضيم مثل ابائي\nوارجعها مفجوعة بحجولها … إذا انتعلت من مأزق بدماء\nإلى حي من كان الإمام عدوه … وصبحة من امره بقضاء\nهو الليث لا مستنهض عن فريسة … ولا راجع عن فرصة لحياء\nولا عزمه في فعله بمذلل … ولا مشيه في فتكه بضراء\nهو النابه النيران في كل ظلمة … ومجري دماء الكوم كل مساء\nومعلي حنين القوس في كل غارة … بسهم نضال أو بسهم غلاء\nفخار لو ان النجم اعطي مثله … ترفع ان يأوى اديم سماء\nووجه لو أن البدر يحمل شبهه … أضاء الليالي من سنى وسناء\nمغارس طالت في ربى المجد والتقت … على انبياء الله والخلفاء\nوكم صارخ ناداك لما تلببت … به السمر في يوم بغير ذكاء\nرددت عليه النفس والشمس فانثنى … بأنعم روح في أعم ضياء\nوكم صدر موتور تطلع غيظه … وقلب قولا عن لسان مراء\nيغطي على اضغانه بنفاقه … كذي العقر غطى ظهره بكفاء\nكررت عليه الحلم حتى قتلته … بغير طعان في الوغى ورماء\nاذا حمل الناس اللواء علامة … كفاك مثار النقع كل لواء\nوجيش مضر بالفلاة كانه … رقاب سيول أو متون نهاء\nكان الربى زرت عليه جيوبها … وردته من بوغائها برداء\nوخيل تغالى في السروج كأنها … صدور عوال أو قداح سراء\nلها السبق في الضمات والسبق وخدها … إذا غطيت من نقعها بغطاء\nوليس فتى من يدعي البأس وحده … اذا لم يعوذ بأسه بسخاء\nوما انت بالمنجوس حظا من العلى … ولا قانعا من عيشه بكفاء\nنصيبك من ذا العيد مثلك وافر … وسعدك فيه مؤذن ببقاء\nولو كان كل آخذا قدر نفسه … لكانت لك الدنيا بغير مراء\nوما هذه الاعياد الا كواكب … تغور وتولينا قليل ثواء\nفخذ من سرور ما استطعت وفز به … فللناس قسما شدة ورخاء\nوبادر إلى اللذات ، فالدهر مولع … بتنغيص عيش واصطلام علاء\nأبثك من ودي بغير تكلف … وأرضيك من نصحي بغير رياء\nواذكر ما اوليتني من صنيعة … فاصفيك رهني طاعة ووفاء\nأعني على دهر رماني بصرفه … ورد عناني ، وهو في الغلواء\nوحلأني عمن أعد بعاده … سقامي ومن قربي اليه شفائي\nفقدت وفي فقد الاحبة غربة … وهجران من احببت اعظم داء\nفلا تطمعن ، يا دهر ، في ، فإنه … ملاذي مما راعني ووقائي\nأرد به أيدي الأعادي ، وأتقي … نوافذ شتى من أذى وبلاء\nألذ بقلبي من مناي تقنعي … وأحسن عندي من غناي غنائي\nومن كان ذا نفس تطيع قنوعة … رضي بقليل من كثير ثراء\nحدوا بالمطايا يوم جالت غروضها … ويوم اتقت ركبانها برغاء\nتؤمك لا تلوي على كل روضة … يصيح بها حوذانها ، وأضاء\nولا تشرب الامواه الا تعلة … إذا عثرت أخفافهن بماء\nلها سائق يطغى عليها بسوطه … ويشدوا على آثارها بحداء\nغلام كاشلاء اللجام تجيزه … صدور القنا والبيض كل فضاء\nإذا بلغت ناديك نال رفاقها … عريض عطاء من طويل ثناء\nومثلك من يعشى إلى ضوء ناره … ويلفى قراه عند كل خباء\nوما كل فعال الندى بشبائه … ولا كل طلاب العلى بسواء"},{"id":"diwan-radi:2","bookId":"diwan-radi","type":"poem","seq":2,"chapter":"البحر: وافر تام","title":"بهاء الملك من هذا البهاء","page":"","text":"بهاء الملك من هذا البهاء … وضوء المجد من هذا الضياء\nوما يعلو على قلل المعالي … احق من المعرق في العلاء\nولا تعنو الرعاة لذي حسام … إذا ما لم يكن راعي رعاء\nوما انتظم الممالك مثل ماض … يتم له القضاء على القضاء\nاذا ابتدر الرهان مبادروه … تمطر دونهم يوم الجزاء\nوإن طلب الندى خرجت يداه … خروج الودق من خلل الغماء\nحذار ، إذا تلفع ثوب نقع … حذار ، إذا تعمم باللواء\nحذار من ابن غيطلة مدل … يسد مطالع البيد القواء\nإذا ألقى على لهوات ثغر … يدي غضبان مرهوب الرواء\nتمر قعاقع الرزين منه … كمعمعة اللهيب من الأباء\nومطراق على اللحظات صل … مريض الناظرين من الحياء\nتنكس كالاميم فان تسامى … مضى كالسهم شذ عن الرماء\nوما ينجي اللديغ به تداو … وقد أمسى بداء أي داء\nولا قضب الرجال الصيد فضلا … عن الأصوات في حلي النساء\nويوم وغى على الأعداء هول … تماز به السراع من البطاء\nرميت فروجه حتى تفرى … بايدي الجرد والاسل الظماء\nفمن غلب كأنهم أسود … على قب ضوامر كالظباء\nومن بيض كأن مجرديها … يمرون الاكف على الاضاء\nنواحل لم يدع ضرب الهوادي … بها ابدا مكانا للجلاء\nومن هاو ترنح في العوالي … وعار قد اقام على العراء\nوآخر مال كالنشوان مالت … بهامته شآبيب الطلاء\nوعدت وقد خبأت الحرب عنه … إلى سلم الرغائب والعطاء\nفيوم للمكارم والعطايا … ويوم للحمية والاباء\nتقود الخيل أرشق من قناها … شوازب كالقداح من السراء\nبغارات كولغ الذئب تترى … على الاعداء بينة العداء\nعزائم كالرياح مررن رهوا … على الاقطار من دان وناء\nوقلب كالشجاع يسور عزما … ويجذب بالعلى جذب الرشاء\nوكف كالغمام يفيض حتى … يعم الارض من كلإ وماء\nووجه ماج ماء الحسن فيه … ولاح عليه عنوان الوضاء\nيشارك في السنى قمر الدياجي … ويفضله بزائدة السناء\nومعتلج الجلال نزعت عنه … على عجل رداء الكبرياء\nفأصبح خارجا من كل عز … خروج العود بز من اللحاء\nوحزت جمام نعمته وكانت … غمارا لا تكدر بالدلاء\nبرأي ثقف الاقبال منه … فأقدم كالسنان إلى اللقاء\nاذا الشر القريب عليك فاقطع … بحد السيف قربى الاقرباء\nوكن ان عقك القرباء ممن … يميل الى الاخوة للاخاء\nفرب اخ خليق بالتقالي … ومغترب جدير بالصفاء\nولا تدن الحسود ، فذاك عر … مضيض لا يعالج بالهناء\nكفاك نوائب الأيام كاف … طرير العزم مشحوذ المضاء\nامين الغيب لا يوكي حشاه … لآمنه على الداء العياء\nاقام ينازل الابطال حتى … تفلل كل مشهور المضاء\nإزاء الحرب يعتنق العوالي … ويغتبق النجيع من الدماء\nإذا ما قيل : مل ، رأيت منه … نوازع تشرئب الى اللقاء\nفجربني تجدني سيف عزم … يصمم غربه وزناد راء\nوأسمر شارعا في كل نحر … شروع الصل في ينبوع ماء\nإذا علقت يداك به حفاظا … ملأت يديك من كنز الغناء\nيعاطيك الصواب بلا نفاق … ويمحضك السداد بلا رياء\nجري يوم تبعثه لحرب … وقور يوم تبحثه لراء\nاذا كان الكفاة لذا عبيدا … فذا كافي الكفاة ، بلا مراء\nبهاء الدولة المنصور إني … دعوتك بعد لأي من دعائي\nوكنت أظن أن غناك يسري … الي بما تبين من غناء\nفلم انا كالغريب وراء قوم … لو اختبروا لقد كانوا ورائي\nبعيد عن حماك ولي حقوق … قواض ان يطول به ثوائي\nأأبلى ثم يبدوا باصطناعي … كفاني ما تقدم من بلائي\nوذبى عن حمى بغداد قدما … بفضل العزم والنفس العصاء\nغداة أظلت الأقطار منها … مضرجة تبزل بالدماء\nدخان تلهب الهبوات منه … مدى بين البسيطة والسماء\nصبرت النفس ثم على المنايا … الى اقصى الثميلة والذماء\nرجاء أن تفوز قداح ظني … وتلوي بالنجاح قوى رجائي\nولي حق عليك فذاك جدي … قديم في رضاك وذا ثنائي\nومن شيم الملوك على الليالي … مجازات الولي على الولاء\nسيبلو منك هذا الصوم خرقا … رحيب الباع فضفاض الرداء\nتصوم فلا تصوم عن العطايا … وعن بذل الرغائب والحباء\nالا فاسعد به وبكل يوم … يفوقه الصباح الى المساء\nودم أبد الزمان ، فأنت أولى … بنى الدنيا بعارية البقاء\nعلي الجد ، مقترب الأماني … عزيز الجار مطروق الفناء"},{"id":"diwan-radi:3","bookId":"diwan-radi","type":"poem","seq":3,"chapter":"البحر: وافر تام","title":"أيا لله ! أي هوى أضاء","page":"","text":"أيا لله ! أي هوى أضاء … بريق بالطويلع اذ ترائى\nألم بنا كنبض العرق وهنا … فلما جازنا ملأ السماء\nكأن وميضه ايدي قيون … تعيد على قواضبها جلاء\nطربت إليه حتى قال صحبي … لأمر هاج منك البرق داء\nولم يك قبلها يقتاد طرفي … ولا يمضي بلبي حيث شاء\nخليلي اطلقا رسني فاني … اشدكما على عزم مضاء\nأبت لي صبوتي إلا التفاتا … إلى الدمن البوائد وانثناء\nفان تريا إذا ما سرت شخصي … امامكما فلي قلب وراء\nوربت ساعة حبست فيها … مطايا القوم امنعها النجاء\nعلى طلل كتوشيع اليماني … امح فخا لط البيد القواء\nقفاز لا تهاج الطير فيها … ولا غاد يروع بها الظباء\nفيا لي منه يصبيني أنيقا … بساكنه ، ويبكيني خلاء\nانادي الركب دونكم ثراه … لعل به لذي داء دواء\nتساقينا التذكر ، فانثنينا … كأنا قد تساقينا الطلاء\nوعجنا العيس توسعنا حنينا … تغنينا ، ونوسعها بكاء\nالى كم ذا التردد في التصابي … وفجر الشيب عندي قد اضاء\nفيا مبدي العيوب سقى سوادا … يكون على مقابحها غطاء\nشبابي ان تكن احسنت يوما … فقد ظلم المشيب وقد اساء\nويا معطي النعيم بلا حساب … أتاني من يقتر لي العطاء\nمتاع اسلفتناه الليالي … وأعجلنا ، فأسرعنا الأداء\nتسخطنا القضاء ولو عقلنا … فما يغني تسخطنا القضاء\nسامضي للتي لا عيب فيها … وان لم استفد الا عناء\nواطلب غاية ان طوحت بي … اصابت بي الحمام أو العلاء\nانا ابن السابقين الى المعالي … اذا الامد البعيد ثنى البطاء\nاذا ركبوا تضايقت الفيافي … وعطل بعض جمعهم الفضاء\nنماني من أبات الضيم نام … افاض علي تلك الكبرياء\nشأونا الناس أخلاقا لدانا … وايمانا رطابا واعتلاء\nونحن النازلون بكل ثغر … نريق على جوانبه الدماء\nونحن الخائضون بكل هول … اذا دب الجبان به الضراء\nونحن اللابسون لكل مجد … اذا شئنا ادراعا وارتداء\nأقمنا بالتجارب كل أمر … أبى إلا اعوجاجا والتواء\nنجر إلى العداة سلاف جيش … كعرض الليل يتبع اللواء\nنطيل به صدى الجرد المذاكي … إلى أن نورد الأسل الظماء\nإذا عجم العدا أدمى وأصمى … وطير عن قضيبهم اللحاء\nعجاج ترجع الارواح عنه … فلا هوجا يجيز ولا رخاء\nشواهق من جبال النقع ترمي … بها ابدا غدوا أو مساء\nوغر آكل بالغيب لحمي … وان لاكله داء عياء\nيسيء القول اما غبت عنه … ويحسن لي التجمل واللقاء\nعبأت له وسوف يعب فيها … من الضراء آنية ملاء\nومنا كل أغلب مستحين … إن أنت لددته بالذل قاء\nإذا ما ضيم نمر صفحتيه … وقام على براثنه اباء\nوإن نودي به ، والحلم يهفو … صغا كرما إلى الداعي ، وفاء\nونأبى أن ينال النصف منا … وأن نعطي مقارعنا السواء\nولو كان العداء يسوغ فينا … لما سمنا الورى الا العداء"},{"id":"diwan-radi:4","bookId":"diwan-radi","type":"poem","seq":4,"chapter":"البحر: كامل تام","title":"أي العيون تجانب الأقذاء","page":"","text":"أي العيون تجانب الأقذاء … ام اي قلب يقطع البرجاء\nوالموت يقنص جمع كل قبيلة … قنص المريع جأ ذرا وظباء\nيتناول الضب الخبيث من الكدى … ويحط من عليائها الشغواء\nتبكي على الدنيا رجال لم تجد … للعمر من داء المنون شفاء\nوالدهر مخترم تشن صروفه … في كل يوم ، غارة شعواء\nانا بنو الدنيا تسير ركابنا … وتغالط الإدلاج والإسراء\nوكأننا في العيش نطلب غاية … وجميعنا يدع السنين وراء\nاين المقاول والغطارفة الاولى … هجروا الديار ، وعطلوا الأفناء\nفاخلط بصوتك كل صوت واستمع … هل في المنازل من يجيب دعاء\nواشمم تراب الارض تعلم انها … جرباء تحدث كل يوم داء\nكم راحل وليت عنه ، وميت … رجعت يدي من تربة غبراء\nوكذا مضى قبلي القرون يكبهم … صرف الزمان تسرعا ونجاء\nهذا أمير المؤمنين ، وظله … يسع الورى ، ويجلل الأحياء\nنظرت إليه من الزمان ملمة … كالليث لا يغضي الجفون حياء\nواصابه صرف الردى برزية … كالرمح أنهر طعنة نجلاء\nماذا نؤمل في اليراع اذا نشت … ريح تدق الصعدة الصماء\nغصف الردى بمحمد ومذمم … فكانما وجد الرجال سواء\nومصاب ابلج من ذؤابة هاشم … ولج القبور وأزعج الخلفاء\nوتر الردى من لو تناول سيفه … يوما ، لنال من الردى ما شاء\nغصن طموح عطفته منية … للخابطين وطاوع النكباء\nيا راحلا ورد الثرى في ليلة … كاد الظلام بها يكون ضياء\nلما نعاك الناعيان مشى الجوى … بين القلوب وضعضع الأحشاء\nواسود شطر اليوم ترجف شمسه … قلقا ، وجر ضياؤه الظلماء\nوارتج بعدك كل حي باكيا … فكانما قلب الصهيل رغاء\nقبر تشبث بالنسيم ترابه … دون القبور ، وعقل الأنواء\nتلقاه ابكار السحاب وعونها … تلقى الحيا ، وتبدد الأنداء\nمتهلل الجنبات تضحك ارضه … فكأن بين فروجه الجوزاء\nأولى الرجال بري قبر ماجد … غمر الرجال تبرعا وعطاء\nولو أن دفاع الغمام يطيعني … لجرى على قبر اللئيم غثاء\nلا زال تنطف فوقه قطع الحيا … بمجلجل يدع الصخور رواء\nوتظن كل غمامة وقفت به … تبكي عليه توددا وولاء\nوإذا الرياح تعرضت بترابه … قلنا السماء تنفس الصعداء\nايها تمطر نحوك الداء الذي … قرض الرجال وفرق القرباء\nإن الرماح رزئن منك مشيعا … غمر الرداء مهذبا معطاء\nوطويل عظم الساعدين كانما … رفعت بعمته الجياد لواء\nولقين بعدك كل صبح ضاحك … يوما أغم وليلة ليلاء\nانعاك للخيل المغيرة شزبا … واليوم يضرب بالعجاج خباء\nولخوض سيفك والفوارس تدعى … حربا يجر نداؤها الأسماء\nوغيابة فرجتها ، ومقامة … سددت فيها حجة غراء\nوخلطت اقوال الرجال بمقول … ذرب كما خلط الضراب دماء\nومطية انضيتها وكلاكما … تتنازعان السير والإنضاء\nان البكاء عليك فرض واجب … والعيش لا يبكى عليه رياء\nبأبيك ، يطمح نحو كل عظيمة … طرف تعلم بعدك الاغضاء\nفاسلم امير المؤمنين ولا تزل … تجري الجياد وتحرز الغلواء\nفإذا سلمت من النوائب أصبحت … ترضى ، ونرضى أن يكون فداء\nولئن تسلطت المنون لقد أتت … ما رد لوم اللائمين ثناء\nوهبت لنا هذا الحسام المنتضى … فينا ، وهذي العزة القعساء\nنهنهت بادرة الدموع تجملا … والعين تؤنس عبرة وبكاء\nفاستبق دمعك في المصائب واعلمن … أن الردى لا يشمت الأعداء\nوتسل عن سيف طبعت غراره … وأعرت شفرته سنا ومضاء\n … أولى ، ولكن نندب الآباء\nفلقد رجعت عن المطيع بسلوة … من بعد ما جرت الدموع دماء\nوالابن للاب ان تعرض حادث … أولى الأنام بأن يكون وقاء\nوإذا ارتقى الآباء أمنع نجوة … فدع الردى يستنزل الابناء\nورد الزمان به وأورده الردى … بغيا ، فأحسن مرة ، وأساء\nورمى سنيه الى الحمام كانما … ألقى بها عن منكبيه رداء\nفلتعلم الايام انك لم تزل … تفري الخطوب وتكشف الغماء\nخضعت لك الأعداء يوم لقيتها … جلدا تجرد للمصاب عزاء\nوتمطت الزفرات ، حتى قومت … ضلعا على اضغانها عوجاء\nومضاغن ملآن يكتم غيظه … جزعا كما كتم المزاد الماء\nمتحرق ، فإذا رأتك لحاظه … نسيت مجامع قلبه الشحناء\nوأما وجودك انه قسم لقد … غمر القلوب وانطق الشعراء\nوانا الذي واليت فيك مدائحا … وعبأت للباغي عليك هجاء\nونفضت إلا من هواك خواطري … نفض المشمر بالعراء وعاء\nفاسلم ، ولا زال الزمان يعيرني … "},{"id":"diwan-radi:5","bookId":"diwan-radi","type":"poem","seq":5,"chapter":"البحر: كامل تام","title":"ابكيك لو نقع الغليل بكاءي","page":"","text":"ابكيك لو نقع الغليل بكاءي … وأقول لو ذهب المقال بدائي\nوأعوذ بالصبر الجميل تعزيا … لو كان بالصبر الجميل عزائي\nطورا تكاثرني الدموع وتارة … آوي الى اكرومتي وحيائي\nكم عبرة موهتها باناملي … وسترتها متجملا بردائي\nابدي التجلد للعدو ولو درى … بتململي لقد اشتفى أعدائي\nما كنت اذخر في فداك رغيبة … لو كان يرجع ميت بفداء\nلو كان يدفع ذا الحمام بقوة … لنكدست عصب وراء لوائي\nبمدربين على القراع تفيأوا … ظل الرماح لكل يوم لقاء\nقوم إذا مرهوا بأغباب السرى … كحلوا العيون بإثمد الظلماء\nيمشون في حلق الدروع كأنهم … صم الجلامد في غدير الماء\nببروق ادراع ورعد صوارم … وغمام قسطلة ووبل دماء\nفارقت فيك تماسكي وتجملي … ونسيت فيك تعززي وابائي\nوصنعت ما ثلم الوقار صنيعه … مما عراني من جوى البرحاء\nكم زفرة ضعفت فصارت انة … تممتها بتنفس الصعداء\nلهفان أنزو في حبائل كربة … ملكت علي جلادتي وغنائي\nوجرى الزمان على عوائد كيده … في قلب آمالي وعكس رجائي\nقد كنت آمل أن أكون لك الفدا … مما ألم ، فكنت أنت فدائي\nوتفرق البعداء بعد مودة … صعب فكيف تفرق القرباء\nوخلائق الدنيا خلائق مومس … للمنع آونة وللاعطاء\nطورا تباذلك الصفاء وتارة … تلقاك تنكرها من البغضاء\nوتداول الأيام يبلينا كما … يبلي الرشاء تطاوح الأرجاء\nوكأن طول العمر روحة راكب … قضى اللغوب وجد في الاسراء\nأنضيت عيشك عفة وزهادة … وطرحت مثقلة من الأعباء\nبصيام يوم القيظ تلهب شمسه … وقيام طول الليلة الليلاء\nما كان يوما بالغبين من اشترى … رغد الجنان بعيشة خشناء\nلو كان مثلك كل أم برة … غنى البنون بها عن الآباء\nكيف السلو وكل موقع لحظة … اثر لفضلك خالد بازائي\nفعلات معروف تقر نواظري … فتكون أجلب جالب لبكائي\nما مات من نزع البقاء ، وذكره … بالصالحات يعد في الأحياء\nفبأي كف استجن واتقي … صرف النوائب أم بأي دعاء\nومن الممول لي اذا ضاقت يدي … ومن المعلل لي من الادواء\nومن الذي ان ساورتني نكبة … كان الموقي لي من الأسواء\nأم من يلط علي ستر دعائه … حرما من البأساء والضراء\nرزآن يزدادان طول تجدد … أبد الزمان : فناؤها وبقائي\nشهد الخلائق انها لنجيبة … بدليل من ولدت من النجباء\nفي كل مظلم ازمة أو ضيقة … يبدو لها أثر اليد البيضاء\nذخرت لنا الذكر الجميل إذا انقضى … ما يذخر الآباء للابناء\nقد كنت آمل أن يكون أمامها … يومي وتشفق ان تكون ورائي\nآوي الى برد الظلال كأنني … لتحرقي آوي إلى الرمضاء\nواهب من طيب المنام تفزعا … فزع اللديغ نبا عن الاعفاء\nآباؤك الغر الذين تفجرت … بهم ينابيع من النعماء\nمن ناصر للحق أو داع إلى … سبل الهدى أو كاشف الغماء\nنزلوا بعرعرة السنام من العلى … وعلوا على الأثباج والأمطاء\nمن كل مستبق اليدين الى الندى … ومسدد الأقوال والآراء\nيرجى على النظر الحديد تكرما … ويخاف في الاطراق والاغضاء\nدرجوا على أثر القرون وخلفوا … طرقا معبدة من العلياء\nيا قبر امنحه الهوى واود لو … نزفت عليه دموع كل سماء\nلا زال مرتجز الرعود مجلجل … هزج البوارق مجلب الضوضاء\nيرغو رغاء العود جعجعه السرى … وينوء نوء المقرب العشراء\nيقتاد مثقلة تالغمام كانما … ينهضن بالعقدات والانقاء\nيهفو بها جنح الدجى ويسوقها … سوق البطاء بعاصف هوجاء\nيرميك بارقها بافلاذ الحيا … ويفض فيك لطائم الأنداء\nمتحليا عذراء كل سحابة … تغذو الجميم بروضة عذراء\nللومت ان لم اسقها بمدامعي … ووكلت سقياها إلى الأنواء\nلهفي على القوم الاولى غادرتهم … وعليهم طبق من البيداء\nمتوسدين على الخدود كأنما … كرعوا على ظمأ من الصهباء\nصور ضننت على العيون بلحظها … أمسيت أوقرها من البوغاء\nونواظر كحل التراب جفونها … قد كنت احرسها من الاقذاء\nقربت ضرائحهم على زوارها … ونأوا عن الطلاب اي تنائي\nوابئس ما تلقى بعقر ديارهم … أذن المصيخ بها وعين الرائي\nمعروفك السامي انيسك كلما … ورد الظلام بوحشة الغبراء\nوضياء ما قدمته من صالح … لك في الدجى بدل من الاضواء\nإن الذي أرضاه فعلك لا يزل … ترضيك رحمته صباح مساء\nصلى عليك ، وما فقدت صلاته … قبل الردى ، وجزاك أي جزاء\nلو كان يبلغك الصفيح رسائلي … او كان يسمعك التراب ندائي\nلسمعت طول تأوهي وتفجعي … وعلمت حسن رعايتي ووفائي\nكان ارتكاضي في حشاك مسببا … ركض الغليل عليك في أحشائي"},{"id":"diwan-radi:6","bookId":"diwan-radi","type":"poem","seq":6,"chapter":"البحر: كامل تام","title":"اترى السحاب اذا سرت عشراؤه","page":"","text":"اترى السحاب اذا سرت عشراؤه … يمرى على قبر ببابل ماؤه\nيا حادييه قفا ببزل مطيه … فإلى ثرى ذا القبر كان حداؤه\nيسقى هوى للقلب فيه ومعهدا … رقت منابته ورق هواؤه\nقد كان عاقدني الصفاء فلم ازل … عنه ، وما بقى علي صفاؤه\nولقد حفظت له فاين حفاظه … ولقد وفيت له ، فأين وفاؤه\nاوعى الدعاء فلم يجبه قطيعة … أم ضل عنه من البعاد دعاؤه\nهيهات أصبح سمعه وعيانه … في الترب قد حجبتهما اقذاؤه\nيمسي ، ولين مهاده حصباؤه … فيه ، ومؤنس ليله ظلماؤه\nقد قلبت اعيانه وتنكرت … أعلامه ، وتكسفت أضواؤه\nمغف وليس للذة اغفاؤه … مغض وليس لفكرة اغضاؤه\nوجه كلمح البرق غاض وميضه … قلب كصدر العضب فل مضاؤه\nحكم البلى فيه ، فلو يلقى به … اعداؤه لرثى له أعداؤه\nإن الذي كان النعيم ظلاله … أمسى يطنب بالعراء خباؤه\nقد خف عن ذاك الرواق حضوره … أبدا وعن ذاك الحمى ضوضاؤه\nكانت سوابقه طراز فنائه … يجلو جمال روائهن رواؤه\nورماحه سفراؤه وسيوفه … خفراؤه وجياده ندماؤه\nما زال يغدو ، والركاب حداؤه … بين الصوارم والعجاج رداؤه\nانظر إلى هذا الأنام بعبرة … لا يعجبنك خلقه وبهاؤه\nبيناه كالورق النضير تقصفت … أغصانه وتسلبت شجراؤه\nأني تحاماه المنون وإنما … خلقت مراعي للردى خضراؤه\nأم كيف تأمل فلتة أجساده … من ذا الزمان وحشوها ادواؤه\nلا تعجبن ، فما العجيب فناؤه … بيد المنون ، بل العجيب بقاؤه\nأنا لنعجب كيف حم حمامه … عن صحة ، ويغيب عنا داؤه\nمن طاح في سبل الردى آباؤه … فليسلكن طريقه ابناؤه\nومؤمر نزلوا به في سوقة … لا شكله فيهم ولا قرناؤه\nقد كان يفرق ظله اقرانه … ويغض دون جلاله اكفاؤه\nومحجب ضربت عليه مهابة … يغشي العيون بهاؤه وضياؤه\nنادته من خلف الحجاب منية … أمم فكان جوابها حوباؤه\nشقت إليه سيوفه ورماحه … واميط عنه عبيده وإماؤه\nلم يغنه من كان ود لو انه … قبل المنون من المنون فداؤه\nحرم عليه الذل إلا انه … أبدا ليشهد بالجلال بناؤه\nمتخشع بعد الانيس جنابه … متضائل بعد القطين فناؤه\nعريان تطرد كل ريح تربه … وتطيع أول امرها حصباؤه\nولقد مررت ببرزخ ، فسألته : … اين الأولى ضمتهم ارجاؤه\nمثل المطي بواركا أجداثه … تسفى على جنباتها بوغاؤه\nناديته فخفى علي جوابه … بالقول إلا ما زقت أصداؤه\nمن ناظر مطروفة ألحاظه … أو خاطر مطلولة سوداؤه\nأو واجد مكظومة زفراته … أو حاقد منسية شحناؤه\nومسندين على الجنوب كانهم … شرب تخاذل بالطلا أعضاؤه\nتحت الصعيد لغير اشفاق إلى … يوم المعاد تضمهم أحشاؤه\nأكلتهم الارض التي ولدتهم … أكل الضروس حلت له أكلاؤه\nحياك معتلج النسيم ولا يزل … سحرا تفاوح نوره اصباؤه\nيمري عليك من النعامى خلفه … من عارض متبرل اندؤاه\nفسقاك ما حمل الزلال سجاله … ونحاك ما حر الزحوف لواؤه\nلولا اتقاء الجاهلية سقته … ذودا تمور على ثراك دماؤه\nواطرت تحت السيف كل عشية … عرقوب مغتبط يطول رغاؤه\nلكن سيخلف عقرها ودماؤها … أبد الليالي ، مدمعي وبكاؤه\nأقني الحياء تجملا لو أنه … يبقى مع الدمع اللجوج حياؤه\nوإذا أعاد الحول يومك عادني … مثل السليم يعوده آناؤه\nداء بقلبي لا يعود طبيبه … يأسا إلي ، ولا يصاب دواؤه\nفاذهب فلا بقي الزمان وقد هوى … بك صرفه وقضى عليك قضاؤه"},{"id":"diwan-radi:7","bookId":"diwan-radi","type":"poem","seq":7,"chapter":"البحر: كامل تام","title":"مالي اودع كل يوم ظاعنا","page":"","text":"مالي اودع كل يوم ظاعنا … لو كنت آمل للوداع لقاء\nواروح اذكر ما اكون لعهده … فكأنني استودعته الاحشاء\nفرغت يدي منه ، وقد رجعت به … ايدي النوائب والخطوب ملاء\nتشكو القذى عيني فيكثر شكوها … حتى يعود قذى بها اقذاء\nشرق من الحدثان لو يرمي به … ذا الماء من الم أغص الماء\nأحبابي الأدنين كم ألقى بكم … داء يمض ، فلا أداوي الداء\nأحيا أخاءكم الممات وغيركم … جربتهم ، فثكلتهم أحياء\nإلا يكن جسدي أصيب ، فإنني … فرقته فدفعته اعضاء"},{"id":"diwan-radi:8","bookId":"diwan-radi","type":"poem","seq":8,"chapter":"البحر: خفيف تام","title":"حي ، بين النقا وبين المصلى","page":"","text":"حي ، بين النقا وبين المصلى … وقفات الركائب الأنضاء\nورواح الحجيج ليلة جمع … وبجمع مجامع الأهواء\nوتذكر عني مناخ مطيي … بأعالي منى ومرسى خبائي\nوتعمد ذكري اذا كنت بالخ … ف ، لظبي من بعض تلك الظباء\nقل له : هل تراك تذكر ما كا … ن بباب القبيبة الحمراء\nقال لي صاحبي غداة التقنيا … نتشاكى حر القلوب الظماء :\nكنت خبرتني بأنك في الوج … جد عقيدتي وان داءك دائي\nما ترى النفر والتحمل للبي … ن فماذا انتظارنا للبكاء\nلم يقلها حتى انثنيت لما بي … اتلقى دمعي بفضل ردائي"},{"id":"diwan-radi:9","bookId":"diwan-radi","type":"poem","seq":9,"chapter":"البحر: وافر تام","title":"خطوب لا يقاومها البقاء","page":"","text":"خطوب لا يقاومها البقاء … واحوال يدب لها الضراء\nودهر لا يصح به سقيم … وكيف يصح ، والأيام داء\nواملاك يرون القتل غنما … وفي الاموال لو قنعوا فداء\nهم استولوا على النخباء منا … كما استولى على العود اللحاء\nمقام لا يجاذبه رحيل … وليل لا يجاوره ضياء\nسيقطعك المثقف ما تمنى … ويطيعك المهند ما تشاء\nبلونا ما تجيء به الليالي … فلا صبح يدوم ولا مساء\nوأنضينا المدى طربا وهما … فما بقي النعيم ولا الشقاء\nإذا كان الأسى داء مقيما … ففي حسن العزاء لنا شفاء\nوما ينجي من الأيام فوت … ولا كد يطول ولا عناء\nتنال جميع ما تسعى إليه … فسيان السوابق والبطاء\nوما ينجي من الغمرات إلا … ضراب أو طعان أو رماء\nورمح تستطيل به المنايا … وصمصام تشافهه الدماء\nوأني لا أميل إلى خليل … سفيه الرأي شيمته الرياء\nيسومني الخصام وليس طبعي … وما من عادة الخيل الرغاء\nأقول لفتية زجروا المطايا … وخف بهم على الابل النجاء\nعلى غوراء تشتجر الاداوى … بعرضتها وتزدحم الدلاء\nردوا واستفضلوا نطفا ، فحسبي … من الغدران ما وسع الإناء\nوبعدكم أناخ إلى محل … يطلق عنده الدلو الرشاء\nتقلص عن سوائمه المراعي … وتحرز درة الضرع الرعاء\nإذا ما الحر اجدب في زمان … فعفته له زاد وماء\nارى خلقا سواسية ولكن … لغير العقل ما تلد النساء\nيشبه بالفصيل الطفل منهم … فسيان العقيقة والعفاء\nتصونهم الوهاد واي بيت … حمى اليربوع لولا النافقاء\nهم يوم الندى غيم جهام … وفي اللاواء ريح جربياء\nقرى لا يستجير به خميص … ونار لا يحس بها الصلاء\nوضيف لا يخاطبه أديب … وجار لا يلذ له الثواء\nهوى بدر التمام وكل بدر … ستقذفه الى الارض السماء\nوعلمي أنه يزداد نورا … ويجذبه عن الظلم الضياء\nأمر بداره فاطيل شوقا … ويمنعني من النظر البكاء\nتعرض لي فتنكرها لحاظي … معطلة كما نقض الخباء\nكأني قائف طلب المطايا … على جدد ابعثره الظباء\nفإن السيف يحبسه نجاد … ونبت الارض تنوم وآاء\nوقد كان الزمان يروق فيها … ويشرب حسنها الحدق الظماء\nودار لا يلذ بها مقيم … ولا يغشى لساكنها فناء\nتخيب في جوانبها المساعي … وينقص في مواطنها الإباء\nوما حبستك منقصة ، ولكن … كريم الزاد يحرزه الوعاء\nفلا تحزن على الأيام فينا … إذا غدرت ، وشيمتنا الوفاء\nفان السيف يحسبه نجاد … ويطلقه على القمم المضاء\nلئن قطع اللقاء غرام دهر … لما انقطع التودد والاخاء\nومابعث الزمان عليك إلا … وفور العرض والنفس العصاء\nولو جاهرته بالبأس يوما … لابرأ ذلك الجرب الهناء\nوكنت إذا وعدت على الليالي … تمطر في مواعدك الرجاء\nوأعجلك الصريخ إلى المعالي … كما يستعجل الابل الحداء\nوأي فتى أصاب الدهر منا … تصاب به المروءة والوفاء\nصقيل الطبع رقراق الحواشي … كما اصطفقت على الروض الاضاء\nينال المجد وضاح المحيا … طويل الباع عمته لواء\nكلام تستجيب له المعالي … ووجه يستبد به الحياء\nفلا زالت همومك آمرات … على الايام يخدمها القضاء\nتجول على ذوابلك المنايا … ويخطر في منازلك العلاء"},{"id":"diwan-radi:10","bookId":"diwan-radi","type":"poem","seq":10,"chapter":"البحر: وافر تام","title":"تعبرني فتاة الحي أني","page":"","text":"تعبرني فتاة الحي أني … حظيت من المروءة والفتاء\nوأني لا أميل إلى جواد … يعبد حر وجهي للعطاء\nلعمرك ما لغدرك في ذنب … وليس الذنب الا من وفائي\nوما جود الزفير عليك جودا … ولكن ذاك من لؤم العزاء\nمعاداة الرجال على الليالي … اطيق ولا مداراة النساء"},{"id":"diwan-radi:11","bookId":"diwan-radi","type":"poem","seq":11,"chapter":"البحر: متقارب تام","title":"رضينا الظبي من عناق الظبا","page":"","text":"رضينا الظبي من عناق الظبا … وضرب الطلا من وصال الطلا\nولم نرض بالبأس دون السماح … ولا بالمحامد دون الجدا\nوقمنا نجر ذيول الرجا … وترعى العيون بروق المنى\nإلى أن ظفرنا بكأس النجي … ع ، فالرمح يشرب حتى انتشى\nوملنا على القور من نقعنا … باوسع منها واعلى بنا\nوللخيل في ارضنا جولة … تحلل عنها نطاق الثرى\nاثرنا عليها صدور الرما … ح يمرح في ظلهن الردى\nفجاءت تدفق في جريها … كما افرغت في الحياض الدلا\nوليل مررنا بظلمائه … نضاوي كواكبه بالظبى\nإذا مدت النار باع الشعاع … مددنا اليها ذراع القرى\nويوم تعطف فيه الجيا … د تشرق الوانها بالدما\nفما برحت حلبة السابقا … ت توردنا عفوات المدى\nبركض يصدع صدر الوها … د ، حتى تئن قلوب الصفا\nيلوذ بأبياتنا الخائفو … ن ، حتى طرائد وحش الفلا\nوتصغى لنا فاريات الخطو … ب قواضب ما آجنت بالصدا\nيبشرها بعد هماتنا … بان الحمام قريب الخطا\nوجو تقلب فيه الريا … ح بين الجنوب وبين الصبا\nسللنا النواظر في عرضه … فطول من شأوها المنتضى\nتصافح منه لحاظ العيون … مريض النسيم أريض الربى\nوإني على شغفي بالوقار … احن الى خطرات الصبا\nومما يزهدني في الزمان … ويجذبني عن جميع الورى\nاخ ثقف المجد اخلاقه … وأشعر أيامه بالعلى\nوانكحه بهدي السنا … وطلقه من قبيح النشا\nوقور ، إذا زعزعته الخصو … م ، وانفرجت حلقات الحبى\nاذا هزهز الرمح روى السنا … ن ، واستمطر السيف هام العدى\nوما هو إلا شهاب الظلا … م صافح لحظي بحسن الروا\nيقص ومن غير سهم اصاب … ويرمي ، ومن غير قوس رمى\nفغيث يعانقني في السحاب … وبدر ينادمني في السما\nسقاني على القرب كاس الإخا … ء مطلولة بنسيم الصفا\nفلله كاس صرعت الهمو … م بسورتها وعقرت الاسا\nوسرب تنفره بالرماح … ووعد تعفره بالعطا\nوماء تصارعه بالركاب … وجيش تقارعه بالقنا\nويوم تسوده بالعجاج … وناد تبيضه بالندى\nسناء تبلد عنه السماء … ومجد سها عن مداه السها\nبني خلف أنتم في الزمان … غيوث العطاء ليوث الوغى\nبدور اذا ازدحمت في الظلا … م شمر برديه عنها الدجى\nحريون إن نسبوا بالسما … ح ، جريون في كل أمر عرا\nلهم كل يوم الى الغادرين … جمع تقلقل عنه الفضا\nحلفت بسابحة في الفجاج … تمزج اخفافها بالذرى\nوتنهض في صهوات الهجير … بين النعام وبين المها\nبخطو يمزق برد الصعيد … وركض يلطم وجه الملا\nهببن ، ولم تغرهن الحداة … فقام الهباب مقام الحدا\nتحط رحائلها بالمقام … وتلقي ازمتها بالصفا\nلقد حل ودك من مهجتي … بحيث يقيل الأسى والإسا\nوحاشاك ان تستسر الوداد … وترمد بالهجر طرف الهوى\nلبذل الندى ان ثويت الثوى … وفل العدى ان سريت السرى\nرايت عليا يرد الرسيل … حسير القوائم دامي القرى\nاذا الركب حط بابوابه … تنفض عنه غبار النوى\nوان سلك البر هز الرعا … ن ، حتى ينفر ذود القطا\nبكل معوذة بالحدي … د ، إن روعتها نبال العدى\nسأشدوا بذكرك ما استعبرت … مطي يثلم فيها الوجى\nوأصفيك ودي ، وبعض الرجا … ل يمزج بالود ماء القلا\nيخبط الضلوع على إحنة … ويرعى الاخاء بعين العما\nولما ذكرتك حن الفؤا … د واعتل في مقلتي الكرى\nفلا زلت في رقدات النعي … م تهفو بلا موقظ من أذى\nرياض تشق عليك النسيم … وليل ، يمج عليك الضحى"},{"id":"diwan-radi:12","bookId":"diwan-radi","type":"poem","seq":12,"chapter":"البحر: رمل تام","title":"كربلا ، لا زلت كربا وبلا","page":"","text":"كربلا ، لا زلت كربا وبلا … ما لقي عندك آل المصطفى\nكم على تربك لما صرعوا … من دم سال ومن دمع جرى\nكم حصان الذيل يروي دمعها … خدها عند قتيل بالظما\nتمسح الترب على اعجالها … عن طلى نحر رميل بالدما\nوضيوف لفلاة قفرة … نزلوا فيها على غير قرى\nلم يذوقوا المآء حتى اجتمعوا … بحدى السيف على ورد الردى\nتكسف الشمس شموسا منهم … لا تداينها ضياءوعلا\nوتنوش الوحش من اجسادهم … أرجل السبق وأيمان الندى\nووجوها كالمصابيح ، فمن … قمر غاب ، ونجم قد هوى\nغيرتهن الليالي ، وغدا … جاير الحكم عليهن البلا\nيا رسول الله لو عاينتهم … وهم ما بين قتلى وسبا\nمن رميض يمنع الظل ومن … عاطش يسقى انابيب القنا\nومسوق عاثر يسعى به … خلف محمول على غير وطا\nمتعب يشكو اذى السير على … نقب المنسم ، مجزول المطا\nلرأت عيناك منهم منظرا … للحشى شجوا ، وللعين قذى\nليس هذا لرسول الله يا … امة الطغيان والبغي جزا\nغارس لم يأل في الغرس لهم … فأذاقوا أهله مر الجنى\nجزروا جزر الاضاحي نسله … ثم ساقوا أهله سوق الإما\nمعجلات لا يوارين ضحى … سنن الوجه أو بيض الطلى\nهاتفات برسول الله في … بهر السعي ، وعثرات الخطى\nيوم لا كسر حجاب مانع … بذلة العين ولا ظل خبا\nأدرك الكفر بهم ثاراته … وأزيل الغي منهم فاشتفى\nيا قتيلا قوض الدهر به … عمد الدين وأعلام الهدى\nقتلوه بعد علم منهم … انه خامس اصحاب الكسا\nوصريعا عالج الموت بلا … شد لحيين ولا مد ردى\nغسلوه بدم الطعن ، وما … كفنوه غير بوغاء الثرى\nمرهقا يدعو ولا غوث له … بأب بر وجد مصطفى\nوبأم رفع الله لها … علما ما بين نسوان الورى\nأي جد وأب يدعوهما … جد ، يا جد ، أغثني يا أبا\nيا رسول الله يا فاطمة … يا أمير المؤمنين المرتضى\nكيف لم يستعجل الله لهم … بانقلاب الارض أو رجم السما\nلو بسبطي قيصر أو هرقل … فعلوا فعل يزيد ، ما عدا\nكم رقاب من بني فاطمة … عرقت ما بينهم ، عرق المدى\nواختلاها السيف حتى خلتها … سلم الابرق أو طلح العرا\nحملوا رأسا يصلون على … جده الاكرم طوعا وابا\nيتهادى بينهم لم ينقضوا … عمم الهام ولا حلو الحبى\nميت تبكي له فاطمة … وابوها وعلى ذو العلى\nلو رسول الله يحيا بعده … قعد اليوم عليه للعزا\nمعشر منهم رسول الله وال … كاشف الكرب اذا الكرب عرا\nصهره الباذل عنه نفسه … وحسام الله في يوم الوغى\nأول الناس إلى الداعي الذي … لم يقدم غيره لما دعا\nثم سبطاه الشهيدان ، فذا … بحسا السم وهذا بالظبى\nوعلي ، وابنه الباقر ، والص … ادق القول ، وموسى ، والرضا\nوعلي ، وأبوه وابنه … والذي ينتظر القوم غدا\nيا جبال المجد عزا وعلى … وبدور الارض نورا وسنا\nجعل الله الذي نابكم … سبب الوجد طويلا والبكا\nلا أرى حزنكم ينسى ، ولا … رزءكم يسلى ، وإن طال المدى\nقد مضى الدهر وعفى بعدكم … لا الجوى باخ ، ولا الدمع رقا\nانتم الشافون من دآ العمى … وغدا ساقون من حوض الروا\nنزل الدين عليكم بيتكم … وتخطى الناس طرا وطوى\nاين عنكم للذي يبغى بكم … ظل عدن دونها حر لظى\nاين عنكم لمضل طالب … وضح السبل واقمار الدجى\nاين عنكم للذي يرجو بكم … مع رسول الله فوزا ونجا\nيوم يغدو وجهه عن معشر … معرضا ممتنعا عند اللقا\nشاكيا منهم الى الله وهل … يفلح الجيل الذي منه شكا\nرب ! ما حاموا ، ولا آووا ، ولا … نصروا أهلي ، ولا أغنوا غنا\nبدلوا ديني ، ونالوا أسرتي … بالعظيمات ، ولم يرعوا ألى\n … قائم الشرك لأبقى ورعى\nنقضوا عهدي ، وقد أبرمته … وعرى الدين ، فما أبقوا عرى\nحرمي مستردفات وبنو … بنتي الأدنون ذبح للعدى\nاترى لست لديهم كامرئ … خلفوه بجميل اذ مضى\nرب ! إني اليوم خصم لهم … جئت مظلوما وذا يوم القضا"},{"id":"diwan-radi:13","bookId":"diwan-radi","type":"poem","seq":13,"chapter":"البحر: بسيط تام","title":"اشكو الى الله قلبا لا قرار له","page":"","text":"اشكو الى الله قلبا لا قرار له … قامت قيامته ، والناس أحياء\nان نال منكم وصالا زاده سقما … كأن كل دواء عنده داء\nكأن قلبي يوم البين طار به … من الرفاع نجيب الساق عداء"},{"id":"diwan-radi:14","bookId":"diwan-radi","type":"poem","seq":14,"chapter":"البحر: طويل","title":"كريم له يومان قد كفلا له","page":"","text":"كريم له يومان قد كفلا له … بنيل العلى من بأسه وسخائه\nفيوم نزال مشمس من سيوفه … ويوم نوال ماطر من عطائه"},{"id":"diwan-radi:15","bookId":"diwan-radi","type":"poem","seq":15,"chapter":"البحر: كامل تام","title":"لو كان قرنك من تعز بمنعه","page":"","text":"لو كان قرنك من تعز بمنعه … أو من يهاب تخمطا وإباء\nسالت محارمها عليك بأوجه … مثل السيوف مهابة وضياء"},{"id":"diwan-radi:16","bookId":"diwan-radi","type":"poem","seq":16,"chapter":"البحر: متقارب تام","title":"رجعت بهن دوام الصفا","page":"","text":"رجعت بهن دوام الصفا … ح ، ينزع منهن شوك القنا\nوضمخت اعناقها بالدما … وأوقرت أكفالها بالدمى"},{"id":"diwan-radi:17","bookId":"diwan-radi","type":"poem","seq":17,"chapter":"البحر: متقارب تام","title":"وهل أنجدن بعبدية","page":"","text":"وهل أنجدن بعبدية … تمد علابيبها للحدا\nواسمع ليلة اورادها … تداعي الرغاء وزجر الرعا"},{"id":"diwan-radi:18","bookId":"diwan-radi","type":"poem","seq":18,"chapter":"البحر: طويل","title":"غدا يهدم المجد المؤثل ما بنى","page":"","text":"غدا يهدم المجد المؤثل ما بنى … وتكسد أسواق الصوارم والقنا\nمضى المصدر الآراء والمورد النهى … فمن يعدل الميلاء أو يرأب الثنا"},{"id":"diwan-radi:19","bookId":"diwan-radi","type":"poem","seq":19,"chapter":"البحر: خفيف تام","title":"لو على قدر ما يحاول قلبي","page":"","text":"لو على قدر ما يحاول قلبي … طلبي لم يقر في الغمد عضبي\nهمة كالسماء بعدا ، وكالري … لريح هبوبا في كل شرق وغرب\nونزاع الى العلى يفطم العي … س عن الورد بين ماء وعشب\nرب بؤس غدا علي بنعما … ء وبعد افضى الي بقرب\nاتقري هذا الانام فيغدو … عجبي منهم طريقا لعجبي\nواذا قلب الزمان لبيب … ابصر الجد حرب عقل ولب\nأمقاما ألذ في غير عليا … ء وزادي من عيشتي زاد ضب\nدون أن اترك السيوف كقتلا … ها رزايا من حر قرع وضرب\nومن العجز إن دعا بك عزم … فرآك الحسام غير ملبي\nواذا ما الامام هذب دنيا … ي كفاني وصالح الغمد غربي\nيا جميلا جماله ملء عيني … وعظيما اعظامه ملء قلبي\nبك ابصرت كيف يصفو غديري … من صروف القذى ويأمن سربي\nانت افسدتني على كل مأمو … ل واعديتني على كل خطب\nفإذا ما أراد قربي مليك … قلت : قربي من الخليفة حسبي\nعز شعري إلا عليك ، وما زا … ل عزيزا يأبى على كل خطب\nاي ندب ما بين برديك والد … ر أجد اليدين من كل ندب\nبين كف تقي المطامع والآ … مال أو ذابل يغير ويسبي\nما تبالي بأي يوميك تغدو … يوم جود بالمال أو يوم حرب\nكم غداة صباحها في حداد … نسجته ايدي نزائع قب\nتتراءى السيوف فيها ، وتخفى … وينير الطعان فيها ، ويخبي\nفرجتها يداك والنقع قد س … د على العاصفات كل مهب\nومربي العلى اذا بلغ الغا … ية ، رباه في العلى ما يربي\nيا أمين الإله ، والنبأ الأع … ظم ، والعقب من مقاول غلب\nعادة المهرجان عندي ان … اروي بذكراك فيه قلبي ولبي\nهو عيد ولا يمر على وجهك … يوم الا يروق ويصبي\nراحل عنك ، وهو يرقب لقيا … ك الى الحول عن علاقة صب\nكيف انسى وقد محضتك اهوا … ي وحصيت عن عدوك حبي\nانت البستني العلى فأطلها … احسن اللبس ما يجلل عقبي\nانني عائذ بنعماك ان اكث … ر قولي وان اطول عتبي\nبي داء شفاؤه أنت ، لو تد … نو واين الطبيب للمستطب\nكيف أرضى ظما بقلبي وطرفي … يتجلى برق الرباب المرب\nنظرة منك ترسل الماء في عو … دي ، وتمطي ظلي وتنبت تربي\nما ترجيت غير جودك جودا … ايرجي القطار من غير سحب\nلا تدعني بين المطامع واليأ … س ووردي ما بين مر وعذب\nوارم بي عن يديك احدى الطريق … ين فما الشعر جل مالي وكسبي\nواذا حاجة نأت عن سؤالي … منك لم تنأ عن غلابي وعضبي"},{"id":"diwan-radi:20","bookId":"diwan-radi","type":"poem","seq":20,"chapter":"البحر: هزج","title":"يد في قائم العضب","page":"","text":"يد في قائم العضب … فما الانظار بالضرب\nوقد أمكنت الهام … ظبي المطرورة القضب\nوللأرماح بالقوم … حكاك الإبل الجرب\nينازعن نزاع الذو … د يرمين عن الشرب\nقوام الدين والدنيا … غياث الازل واللزب\nلزدت الملك أوضاحا … إلى أوضاحه الشهب\nوقررت مبانيه … على الذابل والعضب\nوأوضحت إلى المجد … منار اللقم اللجب\nرأينا الملك من بأس … ك قد دار على القطب\nفقل للخائن المغرو … ر : من أغراك بالشغب\nومن طوحك اليوم … بدار الأسد الغلب\nفاقبلت بمحفار … ك كي تصدع بالهضب\nوهيهات لقد طالعك … ك الحين من النقب\nضلالا لك من غاو … سليب الراي واللب\nأبى العز لبيت الص … ان يطرق بالضب\nوماذا آنس الكرد … بمن زلزل بالعرب\nشم السيف ، فقد قوت … ل أعداؤك بالرعب\nومذ أسخطك المغرو … ر ما قر على الجنب\nوقدما طله الخوف … مطال المخض للوطب\nبغى السلم ، وقد أشفى … على مزلقة الخطب\nوكم سلم ، وإن غر ال … عدى ادمى من الحرب\nنقلت الطعن في الجلد … الى طعنك في القلب\nتقوا من ربضة الليث … فقد يربض للوثب\nوخافوا نومة الأسيا … ف في الأغماد والقرب\nسترمون بها يقظى … إذا قال لها : هبي\nقضى اللة لراياتك … بالإظهار والغلب\nوأصفاك ، بملك الأر … ض من شرق إلى غرب\nوأغنى بك من عدم … واسقى بك من جدب\nوولى بأعاديك … مع الزعازع النكب\nعلى آثارهم حدو القنا … قنا بالضمر القب\nرفعت اليوم من قدري … وأوطئت العدى عفبي\nووطأت لي الرحل … على عرعرة الصعب\nوحليت لي العاطل … بالطوق وبالقلب\nووسعت لي الضيق … إلى المضطرب الرحب\nوزاوجت لي الطول … زواج الماء للعشب\nفكم من نعمة منك … كعرف المندل الرطب\nأتتني سمحة القود … ذلولا سهلة الركب\nمهناة كما ساغ … زلال البارد العذب\nولم أظفر بها منك … جذاب العلق بالعضب\nوما أنعامك الغمر … بزوار على الغب\nسقاني كرع الجم … بلا واسطة القعب\nوأرضاني على الأيا … م بعد اللوم والعتب\nوأعلى المدح ما يثني … به العبد على الرب ."},{"id":"diwan-radi:21","bookId":"diwan-radi","type":"poem","seq":21,"chapter":"البحر: مجزوء الرمل","title":"حييا ، دون الكثيب","page":"","text":"حييا ، دون الكثيب … مرتع الظبي الربيب\nواسألاني عن قريب … في الهوى غير قريب\nوارد ماء عيون … مصطل نار قلوب\nوقفه بالربع أقوى … بين أعقاد الكثيب\nوعفا اليوم على كر … ي قطار وجنوب\nبسوافي الترب البا … رح والترب الغريب\nوالذي بالربع من بع … دهم بعض الذي بي\nواحبسا الركب على حا … جة ذي القلب الطروب\nمستهام دله الشو … ق على دار الحبيب\nموقف ميز للركب … بريا من مريب\nيا غزال الرمل قلبي … باقيا ما اختلف النو\nهل سبيل لي الى را … حة قلب من وجيب\nنظرة يملكها الطر … ف على عين الرقيب\nما لقائي من عدوي … كلقائي من مشيب\nموقد نارا أضاءت … فوق فودي عيوبي\nوبياض هو عند … بيض من شر ذنوبي\nيا قوام الدين والقا … ئم من دون الخطوب\nوالذي يدعو الندى من … منه بداع مستجيب\nومغطي الذنب بالعف … ووكشاف الكروب\nبيديه ركدة السل … م ، وزلزال الحروب\nقرعت من عوده الأع … داء بالنبع الصليب\nبمهيب البشر في المح … فل مرجو القطوب\nقائد الخيل تساقى … بدم الطعن الصبيب\nكل احوى عاقص بال … دم اطراف السبيب\nمن رجال اسفروا با … لطول ايام الشحوب\nكثروا مجدا وطابوا … من نجيب ، فنجيب\nوترى الحي سواهم … مكثرا غير مطيب\nرب غاو طرق الم … جد طروق المستريب\nساور الأمر ، ولم … م يعلم باسرار الغيوب\nظلة يسلك منها … لقما غير ركوب\nأبدا يدحو به الغي … غي الى الامر المريب\nسار والامات يعدد … ن له شق الجيوب\nيسلف الدمع ، يقينا … بردى اليوم العصيب\nشامها وانصاع مح … ل عرى القلب النخيب\nمرهق الوقفة لا … يغمز ساقا من لغوب\nطارحا منخرق ال … ل إلى جول القليب\nمزق الجلد يرى ال … ب من الجرح الرغيب\nناجيا منقلب الا بغ … غث من باز طلوب\nيوم لا يثبت وجه … من كلوم وندوب\nنغرت قدر المنايا … من اوار ولهيب\nتقذف الموت اذا … حش لظاها بالكعوب\nاخسئي يا نوب الأيا … يام ما عشت وخيبي\nوارجعي ناصلة الا … ظفار بيضاء النيوب\nعجبا كيف تطاول … لت الى الليث المهيب\nوإلى طود من العز … ة مزلاق الجنوب\nظهر صعب يقص الرا … كب من قبل الركوب\nكم لبست الطول منكم … بدل البرد القشيب\nنعم كالمزن نقط … ثرى الروض الغريب\nنافحات بنسيم … سافيات بذنوب\nكل يوم انا منها … بين داع ومجيب\nانج من روعات ايا … م وغارات خطوب\nباقيا منا اختلف النو … ر على الغصن الرطيب\nهزة الريح سليما … من وصوم وعيوب\nلا لقاك الخطب إلا … راميا غير مصيب\nكلما أفنيت عقبا … جاء دهر بعقيب\nمهرجان عاد ألما … م محب بحبيب\nوافدا جاء من الإق … في زور غريب\nإن ريب الدهر أمسي … لك مأمون المغيب\nهل لداء بين جسم … وفؤاد من طبيب\nهو في الأجسام منكم … وهو منا في القلوب\nيا طلوع البدر ! لا … نالك محذور الغروب"},{"id":"diwan-radi:22","bookId":"diwan-radi","type":"poem","seq":22,"chapter":"البحر: بسيط تام","title":"ما يصنع السير بالجرد السراحيب","page":"","text":"ما يصنع السير بالجرد السراحيب … إن كان وعد الأماني غير مكذوب\nلله أمر من الأيام اطلبه … هيهات أطلب أمرا غير مطلوب\nلا تصحب الدهر إلا غير منتظر … فالهم يطرده قرع الظنابيب\nواقذف بنفسك في شعواء خابطة … كالسيل يعصف بالصوان واللوب\nإن حنت النيب شوقا وهي واقفة … فان عزمي مشتاق إلى النيب\nأو صارت البيض في الأغماد آجنة … فإنما الضرب ماء غير مشروب\nمتى أراني ودرعي غير محقبة … أجر رمحي وسيفي غير مقروب\nأيد تجانب دنيا لا بقاء لها … خباؤها بين تقويض وتطنيب\nقد كنت غرا وكان الدهر يسمح لي … إن الرقيب على دنياي تجريبي\nوعدت يا دهر شيئا بت أرقبه … وما أرى منك إلا وعد عرقوب\nوحاجة أتقاضاها وتمطلني … كأنها حاجة في نفس يعقوب\nلأتعبن على البيداء راحلة … والليل بالريح خفاق الجلابيب\nما كنت أرغب عن هوجاء تقذف بي … هام المرورى وأعناق الشناخيب\nفي فتية هجروا الأوطان واصطنعوا … إيدي المطايا بإدلاج وتأويب\nمن كل أشعث ملتاث اللثام ، له … لحظ تكرره أجفان مدؤوب\nيوسد الرحل خدا ما توسده … قبل المطالب غير الحسن والطيب\nإليك طارت بنا نجب مدفعة … تحت السياط رميضات العراقيب\nوردن منك سحابا غير منتقل … عن البلاد ، وبدرا غير محجوب\nما زلت ترغب في مجد تشيده … عفوا وغيرك في كد وتعذيب\nحتى بلغت من العلياء منزلة … تفدي الأعاجم فيها بالأعاريب\nإني رأيتك ممن لا يخادعه … حث الزجاجة بالغيد الرعابيب\nولا تحل يد الإقداح حبونه … اذا احتبى بين مطعون ومضروب\nيهاب سيفك مصقولا ومختضبا … وأهيب الشعر شيب غير مخضوب\nيأوي حسامك إن صاح الضراب به … الى لواء من العلياء منصوب\nويرتمي بك ، والأرماح والغة … طماح كل اسيل الخد يعبوب\nبلم يسل همك من مال تفرقه … إلا تعشق أطراف الأنابيب\nإذا منحت العوالي كف مستلب … أقطعت بذل العطايا كف مسلوب\nلا يركب الندب إلا كل معضلة … كأن ظهر الهوينا غير مركوب\nولا يرى الغدر اهلا ان يلم به … وانما الغدر مأخوذ عن الذيب\nما نال مدحي أبو نصر بنائلة … ولا بسلطان ترغيب وترهيب\nإلا بشيمة بسام وتكرمة … غراء تعدل عندي كل موهوب\nانت المعين على امر تصاوله … وحاجة شافهتنا بالأعاجيب\nومثل سمعك يدعوه إلى كرم … قول تشيعه أنفاس مكروب\nسبى فناؤك آمالا لطينتها … سبي الأزمة أعناق المصاعيب\nيا خيرمن قال بلغ خير مستمع … عني وحسبك من وصف وتلقيب\nلولاك يا ملك الأملاك سال بنا … من النوائب عراص الشآبيب\nزجرت عنا الليالي وهي رابضة … تقرو بأنيابها عقر المخاليب\nارعيتنا الكلأ الممطور ننشطه … نشط الخمائل بعد المربع الموبي\nفكنت كالغيث مس المحل ريقه … فهذب الأرض منه أي تهذيب\nهذا أتى قائلا ، والصدق ينصره … اقال عنقي وكان السيف يغري بي\nصدقت ظن العلى فيه ، وحاسده … يعطي الحقائق اطراف الاكاذيب\nتركته زاهدا في العيش منقطعا … عن القراين منا والاصاحيب\nوكان بالحرب يلقى من ينافره … فصار يلقى الأعادي بالمحاريب\nماقلت ما كان صرف الدهر ادبه … بلى قديما ، وهذا فضل تأديب\nالحمد لله لا أشكو الى أحد … قل الوفاء من الشبان والشيب\nهيأت مجدك يستوفي الزمان به … عزما حساما ، ورأيا غير مغلوب\nولا صبرت على ذل ومنقصة … ولا حذرت على عذل وتأنيب\nخطبت شعري إلى قلب يضن به … الا عليك فباشر خير مخطوب\nشببت بالعز اذ كان المديح له … فما اصول بمدحي دون تشبيب\nلا علق الموت نفسا انت صاحبها … ان الحمام محب غير محبوب"},{"id":"diwan-radi:23","bookId":"diwan-radi","type":"poem","seq":23,"chapter":"البحر: طويل","title":"أشوقا ، وما زالت لهن قباب","page":"","text":"أشوقا ، وما زالت لهن قباب … وذكر تصاب والمشيب نقاب\nوغير التصابي للكبير تعلة … وغير الغواني للبياض صحاب\nوما كل ايام المشيب مريرة … ولا كل ايام الشباب عذاب\nأؤمل ما لا يبلغ العمر بعضه … كأن الذي بعد المشيب شباب\nوطعم لبازي الشيب لا بد مهجتي … اسف على راسي وطار غراب\nلداتك إما شبت واتبعوا الردى … جميعا واما ان رديت وشابوا\nبكاء على الدنيا وليس غضارة … وماض من الدنيا وليس مآب\nاذا شئت قلبت الرمان وصافحت … لحاظي أمورا ، كلهن عجاب\nضلالا لقلبي ما يجن من الهوى … ومن عجب الايام كيف يصاب\nيعذل أحيانا ، ويعذر مثلها … ويستحسن البادي به ويعاب\nوان افظ المالكين خريدة … وان اضن الباذلين كعاب\nولما ابى الاظعان الا فراقنا … وللبين وعد ليس فيه كذاب\nرجعت ودمعي جازع من تجلدي … يروم نزولا للجوى فيهاب\nوأثقل محمول على العين دمعها … إذا بان أحباب وعز إياب\nفمن كان هذا الوجد يعمر قلبه … فقلبي من داء الغرام خراب\nومن لعبت بيض الثغور بعقله … فعندي احر الباردين رضاب\nيعف عن الفحشاء ذيلي ، كأنما … عليه نطاق دونها وحجاب\nاذا لم انل من بلدة ما اريده … فما سرني أن البلاد رحاب\nوهل نافعي أن يكثر الماء في الدنا … ولما يجرني ان ظمئت شراب\nولي ساعة في كل أرض ، كأنما … على الجو منها والعيون ضباب\nبعيدة أولى النفع من أخرياته … وللطعن فيها جيئة وذهاب\nوما بين خيلي والمطالب حاجز … ولا دون عزمي للظلام حجاب\nجياد الى غزو القبائل تمتطي … وأرض إلى نيل العلاء تجاب\nوابلج وطاء على خد ليله … كما فارق للنصل المضي قراب\nيعاف طعاما ما جناه حسامه … وخير من الطعم الذليل تراب\nوخذ ما صفا في كل دهر ، فإنما … ظلام الليالي ، والرماح جناب\nوما يبلغ الأعداء مني بفتكة … ودوني فناء للأمير وباب\nتساقط أطراف الأسنة دونه … وتنبو ، ولو أن النجوم حراب\nلبست به ثوبا من العز ، يتقى … طعان من البلوى به ، وضراب\nدعوت ، فلباني ، ولو كنت داعيا … سواه مضى قول وعي جواب\nوان الطعايا من يمين محمد … لأمطر من قطر مراه سحاب\nلحاظ كما شق العجاج مهند … ووجه كما جلى الظلام شهاب\nبلا شافع يعطي الذي انت طالب … وبعض مواعيد الرجال سراب\nفتى تقلق الأعداء منه ، كأنه … لظى ناجر ، والخالعون ضباب\nاذا شاء ناب القول عن فعلاته … وقام مقام العضب منه كتاب\nيعظم أحيانا ، وليس تجبر … وينظر غضبانا وليس سباب\nبغيض إلى قلبي سواه ، وإن غدت … له نعم تترى إلي رغاب\nوعبء على عيني رؤية غيره … ولو كان لي فيه منى وطلاب\nفلا جود إلا أن تمل مطامع … ولا عفو الا ان يطول عقاب\nفداؤك قوم انت عال عليهم … شداد على بذل النوال صعاب\nإذا بادروا مجدا برزت ، وبلدوا … وإن طالعوا عزا شهدت وغابوا\nوقاؤك من ذم العدى خلف نائل … يدر ، ولم تربط عليه عصاب\nوما كل من يعلو كقدرك قدره … ولا كل سام في السماء عقاب\nوما الملك المنصور إلا ضبارم … له منك ظفر في الزمان وناب\nبعزمك يمضي عزمه في عدوه … مضاء طرير أيدته كعاب\nتلافيت اسراب الرعية بعد ما … توقد اضغان لها وضباب\nولما طغى باد واضرم ناره … على الغدر ، إن الغادرين ذئاب\nبعثت له حتفا بغير طليعة … تخب به قب البطون عراب\nنزائع يعجمن الشكيم وقد جرى … على كل فيفاء دم ولعاب\nخواطر بالأيدي لواعب بالخطى … وللطعن في لباتهن لعاب\nولا أرض إلا وهي تحثو ترابها … عليه وترميه ربا وعقاب\nفولى ووليت الجياد طلابه … وسالت مروج بالقنا وشعاب\nتغامس في بحر الحديد وخلفه … لماء المنايا زخرة وعباب\nوقد كان ابدى توبة لو قبلتها … ولو نفع الجاني عليك متاب\nكاني بركب حابس هو منهم … اقاموا بارض والجذوع ركاب\nعواري إلا من دم فتأت به … معاصم من أسر الردى ورقاب\nولله عار في بنانك متنه … يشب ومن لون المداد خضاب\nامين على سر وليس حفيظة … وماض على قرن وليس ذباب\nوما مسه مجد بلى ان راحة … لها نسب في الماجدين قراب\nوإني لأرجو منك حالا عظيمة … وأمرا أرجي عنده وأهاب\nلعل زماني ينثني لي بعطفة … وترضى ملمات علي غضاب\nوما انا ممن يجعل الشعر سلما … الى الامر ان اغنى غناه خطاب\nوليس مديح ما قدرت فان يكن … مديح على رغمي فليس ثواب\nأبى لي علي والنبي وفاطم … جدودي أن يلوي بعرضي عاب\nفلا تغض عن يوم العدو وليله … وثم طلوع بالأذى وغياب\nفقد يحمل الباغي على الموت نفسه … اذا صفرت مما اراد وطاب\nوخذ ما صفا من كل دهر فانما … غضارته غنم لنا ونهاب\nوعش طالعا في العز كل ثنية … عليك خيام للعلى وقباب"},{"id":"diwan-radi:24","bookId":"diwan-radi","type":"poem","seq":24,"chapter":"البحر: طويل","title":"اماني نفس ما تناخ ركابها","page":"","text":"اماني نفس ما تناخ ركابها … وغيبة حظ لا يرجى إيابها\nووفد هموم ما اقمت ببلدة … وهن معي الا وضاقت رحابها\nوآمال دهر إن حسبت نجاحها … تراجع منقوضا على حسابها\nأهم ، وتثني بالمقادير همتي … ولا ينتهي داب الليالي ودابها\nفيا مهجة يفني غليلا ذماؤها … ويا لمة يمضي ضياعا شبابها\nوعندي إلى العلياء طرق كثيرة … لو انجاب من هذي الخطوب ضبابها\nعناد من الايام عكس مطالبي … اذا كان يوطيني النجاح اقترابها\nوحظي منها صابها دون شهدها … فلو كان عندي شهدها ثم صابها\nتميل بأطماع الرجال بروقها … وتوكى على غش الأنام عيابها\nولكنها الدنيا التي لا مجيئها … على المرء مأمون فيخشى ذهابها\nتفوه الينا بالخطوب فجاجها … وتجري إلينا بالرزايا شعابها\nالا ابلغا عني الموفق قولة … وظني أن الطول منه جوابها\nاترضى بان ارمي اليك بهمتي … فأحجب عن لقيا على أنت بابها\nوأظما إلى در الأماني ، فتنثني … باخلافها عني ومنك مصابها\nوليس من الإنصاف أن حلقت بكم … قوادم عز طاح في الجو قابها\nواصبحت محصوص الجناح مهضما … علي غواشي ذلة وثيابها\nتعد الأعادي لي مرامي قذافها … وتنبحني أنى مررت كلابها\nمقامي في اسر الخطوب تهزلي … قواضيها مطرورة وحرابها\nلقد كنت ارجو ان تكونوا ذرائعي … الى غيركم حيث العلى واكتسابها\nفهذي المعالي الآن طوعى لأمركم … وفي يدكم أرسانها ورقابها\nاذا لم ارد في عزكم طلب العلى … ففي عز من يجدي علي طلابها\nولولاكم ما كنت إلا بباحة … من العز مضروبا علي قبابها\nأجوب بلاد الله ، أو أبلغ التي … يسوء الأعادي أن يعب عبابها\nوكان مقامي ان اقمت ببلدة … مقام الضواري الغلب يحذر غابها\nواني لتراك المطالب ان نأى … بها قدر أو لط دوني حجابها\nوأعزل من دون التي لا أنالها … نوازع نفسي أو تذل صعابها\nواقرب ما بيني وبينك حرمة … تداني نفوس ودها وحبابها\nشواجر أرحام ، إذا ما وصلتها … فعند امير المؤمنين ثوابها\nوما بعد ذا من آصرات اذا انتهت … يكون الى آل النبي انتسابها\nوهل تطلب العلياء الالان يرى … ولي يرجيها وضد يهابها\nفجرد لأمري عزمة منك صدقة … كمطرورة الغربين يمضي ذبابها\nولا تتركني قاعدا أرقب المنى … وأرعى بروقا لا يجود سحابها\nوغيرك يقري النازلين ببابه … عدات كأرض القاع يجري سرابها\nيكفيك عقد المكرمات وحلها … وعندك اشراق العلى وغيابها\nوعندي لك الغر التي لا نظامها … يهي ابدا أو لا يبوخ شهابها\nوعندي للاعداء فيك اوابد … لعاب الأفاعي القاتلات لعابها"},{"id":"diwan-radi:25","bookId":"diwan-radi","type":"poem","seq":25,"chapter":"البحر: طويل","title":"ترى نوب الايام ترجى صعابها","page":"","text":"ترى نوب الايام ترجى صعابها … وتسأل عن ذي لمة ما أشابها\nوهل سبب للشيب من بعد هذه … فدأبك يا لون الشباب ودابها\nشربنا من الايام كأسا مريرة … تدار بأيد لا نرد شرابها\nنعاتبها والذنب منها سجية … ومن عاتب الخرقاء مل عتابها\nوقالوا : سهام الدهر خاط وصائب … فكيف لقينا يا لقوم صيابها\nأبت لقحة الدنيا درورا لعاصب … ويحلبها من لا يعاني عصابها\nوقد يلقح النعماء قوم أعزة … ويخسر قوم عاجزون سقابها\nوكنت اذا ضاقت مناديح خطة … دعوت ابن حمد دعوة فأجابها\nأخ لي إن أعيت علي مطالبي … رمى لي أغراض المنى ، فأصابها\nاذا استبهمت علياء لا يهتدي لها … قرعت به دون الأخلاء ، بابها\nبه خف عني ثقل فادحة النوى … وحبب عندي نأيها واغترابها\nثمانون من ليل التمام نجوبها … رفيقين تكسونا الدياجي ثيابها\nنؤم بكعب العامري نجومها … إذا ما نظرناها انتظرنا غيابها\nنقوم أيدي اليعملات وراءه … ونعدل منها اين أومى رقابها\nكأنا أنابيب القناة يؤمها … سنان مضى قدما ، فأمضى كعابها\nكذئب الغضا أبصرته عند مطمع … اذا هبط البيداء شم ترابها\nبعين ابن ليلى لا تداوى من القذى … يريب أقاصي ركبه ما أرابها\nتراه قبوعا بين شرخي رحاله … كمذروبة ضموا عليها نصابها\nفمن حلة نجتابها وقبيلة … نمر بها مستنبحين كلابها\nومن بارق نهفو إليه ، ونفحة … تذكرنا ايامها وشبابها\nولهفي على عهد الشباب ولمة … أطرت غداة الخيف عني غرابها\nومن دار أحباب نبل طلولها … بماء الأماقي أو نحيي جنابها\nومن رفقة نجدية بدوية … تفاوضنا أشجانها واكتئابها\nونذكرها الأشواق حتى تحنها … وتعدي باطراف الحنين ركابها\nإذا ما تحدى الشوق يوما قلوبنا … عرضنا له أنفاسنا والتهابها\nوملنا على الأكوار طربى ، كأنما … رأينا العراق ، أو نزلنا قبابها\nنشاق الى اوطاننا وتعوقنا … زيادات سير ما حسبنا حسابها\nوكم ليلة بتنا نكابد هولها … ونمزق حصباها اذا الغمر هابها\nوقد نصلت أنضاؤنا من ظلامها … نصول بنان الخود تنضو خضابها\nوهاجرة تلقي شرار وقودها … على الركب انعلنا المطي ظرابها\nإذا ما طلتنا بعد ظمء بمائها … وعج الظوامي اوردتنا سرابها\nتمنى الرفاق الورد والريق ناضب … فلا ريق إلا الشمس تلقي لعابها\nإلى أن وقفنا الموقفين وشافهت … بنا مكة أعلامها وهضابها\nوبتنا بجمع والمطي موقف … نؤمل ان نلقى منى وحصابها\nوطفنا بعادي البناء محجب … نرى عنده اعمالنا وثوابها\nوزرنا رسول الله ثم بعيده … قبور رجال ما سلونا مصابها\nوجزنا بسيف … بلجته حتى وطئنا عبابها\nخطوب يعن الشيب في كل لمة … وينسين ايام الصبا ولعابها\nعسى الله ان يأوي لشعث تناهبوا … هبات المطايا نصها وانجذابها\nوجاسوا بأيديها على علل السرى … حرار اماعيز الطريق ولابها\nفيرمي بها بغداد كل مكبر … إذا ما رأى جدرانها وقبابها\nفكم دعوة ارسلتها عند كربة … إليه فكان الطول منه جوابها"},{"id":"diwan-radi:26","bookId":"diwan-radi","type":"poem","seq":26,"chapter":"البحر: متقارب تام","title":"طلوع هداه الينا المغيب","page":"","text":"طلوع هداه الينا المغيب … ويوم تمزق عنه الخطوب\nلقيتك في صدره شاحبا … ومن حلية العربي الشحوب\nإليه تمج النفوس الصدور … وفيه تهنى العيون القلوب\nتعزيت مستأنسا البعاد … والليث في كل ارض غريب\nوأحرزت صبرك للنائبات … وللداء يوما يراد الطبيب\nلحا الله دهرا أرانا الديا … ر يندب فيها البعيد القريب\nوما كان موتا ، ولكنه … فراق تشق عليه الجيوب\nلئن كنت لم تسترب بالزمان … فقد كان من فعله ما يريب\nرمى بك والامر ذاوي النبات … فآل ، وغصن المعالي رطيب\nولما جذبت زمام الزمان … أطاع ، ولكن عصاك الحبيب\nولما استطال عليك البعاد … وذلل فيك المطي اللغوب\nرجوت البعاد على أنه … كفيل طلوع البدور الغروب\nرحلت ، وفي كل جفن دم … عليك ، وفي كل قلب وجيب\nولا نطق الا ومن دونه … عزاء يغور ودمع ربيب\nوأنت تعللنا بالإيا … ب ، والصبر مرتحل لا يؤوب\nوسر العدى فيك نقص العقول … واعلم ان لا يسر اللبيب\nاما علم الحاسد المستغر … أن الزمان عليه رقيب\nقدمت قدوم رقاق السحا … ب تخط والربع ربع جديب\nفما ضحك الدهر الا اليك … ك مذبان في حاجبيه القطوب\nحلفت بما ضمنته الحجون … وما ضم ذاك المقام الرحيب\nلقد سرك الدهر في الغادرين … بعذر تضاءل فيه الذنوب\nوأجلى رجوعك عن حاسدي … ك هذا قتيل وهذا سليب\nتحرق منك قلوب العدا … ة غيظا وانت ضحوك قطوب\nوأجهل ذا الناس مستنهض … دعاء إلى سمع من لا يجيب\nزعانف يستصرخون العلى … وما استلب العز الا نجيب\nوطال مقامك في منزل … تطلع من جانبيه الحروب\nبضرب كما اشترطته السيوف … وطعن كما اقترحته الكعوب\nونجل تغلغل فيها الطعان … ن ، وانشق عنها النجيع الصبيب\nوصحبة كل غلام علي … ه من سمة العز حسن وطيب\nاذا خضب الرمح ادمى به … كأن السنان بنان خضيب\nوقطعك كل بعيد النياط … كأن الجواد به مستريب\nوأرضا ، إذا ما اجتلاها الهجي … هجير طلقها من يديه الضريب\nوما زال منك على النائبات … مقام عظيم ويوم عصيب\nفيوم حسامك فيه الخطيب … ويوم لسانك فيه الخطيب\nطلبت لنفسك فاطلب لنا … من العز ، إن المحامي طلوب\nوان كنت تانف من حبه … فان العلاء الينا حبيب\nوما نحن انت وكل الى … دعاء العلى طرب مستجيب\nونحن قسام الينا الشباب … وانت قسام اليك المشيب\nعلى انه انت عين الزمان … وعيش بلا ناظر لا يطيب\nولولاك ما لذ طعم الفخار … ولا راق برد العلاء القشيب\nاترضى لمجدك ان لا يكون … لنا من عطايا المعالي نصيب\nفلا يقعدنك كيد الحسو … ود وانهض فكل مرام قريب\nوحث الطلاب فانا نجد … وامض الامور فانا نتوب\nولم لا يضيف العلى من له … غدير معين ومرعى خصيب\nلحياك مني ، عند اللقا … ء ، خلق عجيب وخلق أديب\nوخلفتني غرس مستثمر … فطال وأورق ذاك القضيب\nذخرت لك الغرر السائرات … يعبر عنها الفؤاد الكئيب\nتصون مناقبك الشاردات … ان تتخطى اليها العيوب\nإذا نثرتها شفاء الروا … ة راقك منها النظام العجيب\nوإني لأرجوك في النائبات … إذا جاءني الأمل المستثيب"},{"id":"diwan-radi:27","bookId":"diwan-radi","type":"poem","seq":27,"chapter":"البحر: طويل","title":"لغام المطايا من رضابك اعذب","page":"","text":"لغام المطايا من رضابك اعذب … ونبت الفيافي منك اشهى واطيب\nوما لي عند البيض يا قلب حاجة … وعند القنا والخيل والليل مطلب\nأحب خليلي الصفيين صارم … وأطيب داري الخباء المطنب\nذليل لريب الدهر من كان حاضرا … وحرب لدى الايام من يتغرب\nولي من ظهور الشدقميات مقعد … وفوق متون اللاحقيات مركب\nلثامي غبار الخيل في كل غارة … وثوبي العوالي والحديد المذرب\nأساكت بعض الناس والقول نافع … واغمد عن اشياء والضرب\nانجب واطمعني في العز اني مغامر … جري على الأعداء والقلب قلب\nوعندي مما خول الله سابح … وأسمر عسال وأبيض مقضب\nوليس الغنى في الخلق الا غنيمة … تحامي عليها ، والمعالي تغلب\nإذا قل مالي قل صحبي ، وإن نما … فلي من جميع الناس اهل ومرحب\nغنى المرء عز والفقير كانه … لدى الناس مهنوء الملاطين أجرب\nتطالبني نفسي بكل عظيمة … ارى دونها جاري دم يتصبب\nويأمرني الذلان ان لا اطيعها … وأعلم من طرق العلى أين أذهب\nاذا كان حب المرء للشي ضيعة … فأضيع شيء ما يقول المؤنب\nانا السيف الا انني في معاشر … أرى كل سيف فيهم لا يجرب\nولا علم لي بالغيب الا طليعة … من الحزم لا يخفى عليها المغيب\nأجرب من أهواه قبل فرافه … فيصدق منه الغدر والود يكذب\nتغير لي اخلاق من كنت اصطفي … وتغدرني أيام من كنت أصحب\nفلو لوحت لي بالبروق سحابة … لأغضيت علما أن ما بان خلب\nاذا شئت فارقت الحبيب وبيننا … من الشوق ما يملي علي واكتب\nوليس نسيبي أن في القلب لوعة … ولكنني أبكي زماني وأندب\nوما نافعي عند البعيد تقربي … ولا ضائري عند القريب التجنب\nقريب الفتى دون الأنام صديقه … وليس قريبا منه من لا يقرب\nوما في نجاد السيف زين لحامل … ولا الزين إلا للفتى يوم يضرب\nأخو الحرب من للسيف فيه علامة … وللطعن في جنبيه طرق وملعب\nوحسب غلام شاهدا بشجاعة … تغيظ العدى ، أن القنا منه تخضب\nالى غاية تجري الانام لنحوها … فماش بطيء مشيه ومقرب\nيغر الفتى ما طال من حبل عمره … وترخي المنايا برهة ، ثم تجذب\nيقولون عنقا مغرب مستحيلة … الاكل حي مات عنقاء مغرب\nيطول عناء العيس ما دمت فوقها … وما دام لي عزم ورأي ومذهب\nوهون عندي ما بقلبي من الصدى … ظماء تجافى مورد الماء لغب\nفما انا بالواني اذا كنت صاديا … ولا الماء يعطيني قوى يوم أشرب\nوما الورد بعد الورد بلا لغلتي … وإن بل ظمأ الداعريات مشرب\nوما لي الى غير الحسين وسيلة … وفي جوده دون الرغائب أرغب\nجريء على الأمر الذي لا يرومه … من القوم إلا حازم الرأي أغلب\nألا إن فحلا ساعدته نجيبة … فجاء بنجل كالحسين ، لمنجب\nوإن محلا حل فيه لواسع … وإن زمانا عاش فيه لطيب\nلك الله من مغض على جرم جارم … ولو شاء ما استولى على الذنب مذنب\nوفي كل يوم انت طالب غارة … تجرر اذيال العوالي وتسحب\nتنام على أمر ، وهمك ساهر … وتنزل عن أمر وعزمك يركب\nتحققت الأحياء أنك فخرها … وأغضت على علم نزار ويعرب\nإذا شئت أحيانا شفاك من العدى … سنان بصير بالطعان ومضرب\nوخيل لها في كل شرق ومغرب … عقير مدمى أو طعين مخضب\nإذا طلعت نجدا أضاءت وجوهها … وقدامها من سائق النقع غيهب\nيصيح القنا في كل حي ترومه … ويردي بك الأعداء يوم عصبصب\nألا رب حال ساعدتك وفتكة … رددت بها قرن الردى وهو أعضب\nرميت بها قلب العدو بخيفة … وأعرضت ، والمغرور يلهو ويلعب\nكما خرق الرامي بسهم رميه … وأعرض علما أنه سوف يعطب\nعدوان أما واحد فمكاشف … جري ، وأما آخر فمؤلب\nيمسح خلف الشر ذاك بخيفة … وهذا طويل الباع يمري فيحلب\nيرومون غيا ، والعوائق دونهم … ويرمون بغيا ، والمقادير تحجب\nسما بك طلاعا إلى العمر مشرق … وادبر بالباغي إلى الموت مغرب\nفذاك كما شاء الفسوق مبغض … وأنت كما شاء العفاف محبب\nأهنيك بالعيد الجديد تعلة … وغيرك بالأعياد واللهو يعجب\nفلا زال ممدودا عليك ظلاله … ولا زلت في نعمائه تتقلب\nولا ظفر الباغي عليك بفرصة … ولا طلب الأعداء ما كنت تطلب\nغمامك فياض ، وريحك غضة … وحوضك ملآن وروضك معشب\nإذا قلت فيك الشعر جود مادح … وأكثر وصاف واعرق مطنب\nوغيرك لا أطريه إلا تكلفا … وغير حنيني عند غيرك مصحب\nبغيض إلى الأيام أنك لي حمى … وغيظ بني الايام أنك لي أب\nابعد النبي والوصي تروقني … مناسب من يعزى لمجد وينسب\nيقر بفضلي كل باد وحاضر … ويحسدني هذا العظيم المحجب\nومن لي بأن يشتاق ما أنا قائل … ويسمع مني مايروق ويعجب\nولولا جزاء الشعر ممن يريده … وجدت كثيرا من أغنى ويطرب\nألا إن راعي الذود يعنى بذوده … حفاظا وراعي الناس حيران مغرب\nأحبكم ما دمت أعزى إليكم … وما دام لي فيكم مراد ومطلب\nوإني عن الربع الذي لا يضمكم … على كل حال نازح الود أجنب\nفلا تتركني عاطلا من مروة … ولا قانعا بالدون أرضى وأغضب\nفما انا بالواني إذا ما دعوتني … ولا موقفي عما شهدت مغيب\nامالي قرار في نعيم ولذة … فإني في الضراء أطفو وأرسب\nأريد من الله القضاء بحالة … تقر بها عين وقلب معذب\nوأسأل أن يعطيك في العمر فسحة … لعلمي أن العمر يعطي ويوهب"},{"id":"diwan-radi:28","bookId":"diwan-radi","type":"poem","seq":28,"chapter":"البحر: كامل تام","title":"مثواي أما صهوة أو غارب","page":"","text":"مثواي أما صهوة أو غارب … ومناي إما زاغف أو قاضب\nفي كل يوم تنتضيني عزمة … وتمد أعناق الرجاء مآرب\nقلب يصادقني الطلاب جراءة … ومن القلوب مصادق وموارب\nما مذهبي إلا التقحم بالقنا … بين الضلوع وللرجال مذاهب\nوعلي في هذا المقال عضاضة … إن لم يساعدني القضاء الغالب\nما لي أخوف بالردى ، فأخافه … هيهات لي في الخلق بعد عجائب\nوالعزم يطرحني بكل مفازة … متشابه فيها زبى وغوارب\nأعطي الهجير مراده من صفحتي … وتكد سمعي بالصرير جنادب\nاما اقيم صدور مجدي بالقنا … ويقر عضبي ، أو تقوم منادب\nمتأنقا وذرى الرمال كأنها … دون النواظر ، عارض متراكب\nأصبابة من بعد ما ذهب الهوى … طلقا ، وأعوز ما يرام الذاهب\nوعلي تضمير الجياد لغارة … فيها خضيب بالدماء وخاضب\nأرضا ، وذؤبان الخطوب تنوشني … والعزم ماض والرماح سوالب\nانا اكلة المغتاب ان لم اجنها … شعواء يحضرها العقاب الغائب\nوكانما فيها الرماح اراقم … وكانما فيها القسي عقارب\nقد عز من ضنت يداه بوجهه … إن الذليل من الرجال الطالب\nإن كان فقر فالقريب مباعد … او كان مال فالبعيد مقارب\nوارى الغني مطاعنا بثرائه … اعدائه والمال قرن غالب\nيشكو تبذ لي الصحاب ، وعاذر … أن ينبذ الماء المرنق شارب\nمن أجل هذا الناس أبعدت الهوى … ورضيت ان ابقى ومالي صاحب\nوأي الليالي ان غدرن فانه … ما سن أحباب لنا وحبائب\nالذنب اني جزعت وعنونت … عني دموع العين ، وهي سواكب\nدنيا تضر ولا تسر وذا الورى … كل يجاذبها ، وكل عاتب\nتلقي لنا طرفا ، فإن هي أعرضت … نزعت ولو ان الجبال جواذب\nهيهات يا دنيا وبرقك صادق … أرجو ، فكيف إذا وبرقك كاذب\nوالناس اما قانع أو طالب … لا ينتهي ، أو راغب أو راهب\nواذا نعمت فكل شيء ممكن … واذا شقيت فكل شيء عازب\nقد قلت للباغي علي ودونه … من فضل أحلامي ذرى وذوائب\nاحذر مباغضة الرجال فانها … تدمى وتقدر ان يقول العائب\nالبيد يا ايدي المطي فانني … للضيم ، إن أسرى إلي ، مجانب\nومجاهل الفلوات اطيب منزل … عندي ، وأوفى الواعدين نجائب\nوإذا بلغن بي الحسين ، فإنه … حق لهن على المطايا واجب\nفي بلدة فيها العيون حوافل … والروض غض والرياح لواعب\nعجب من الايام رؤية مثله … نجم العلى اذ كل نجم غارب\nاوردنه اطراف كل فضيلة … شيم تساندها على ومناقب\nوله اذا خبثت اصول عداته … في تربة العلياء عرق ضارب\nمتفيء الآراء في ظلل القنا … تجري إليه من العلاء مذانب\nانت المنوه في المحافل باسمه … واذ حضرت فكل لؤم غائب\nلك من حياض المجد زرق جمامها … فلما ينازعك الورود غرائب\nويروم شأوك من غبارك دونه … يوم الجزاء ، غياطل وغياهب\nنفحات كفك للولي غمائم … تهمي ، وهن على العدو نوائب\nفشمائل فيها الندى ، وضرائب … وكتائب فيها الردى ومقانب\nولقد وقفت على الأعادي وقفة … فيها لمن أبقى المنون تجارب\nتحت العجاج وللدروع قعاقع … ضربا ، وغربان الرماح نواعب\nومطاعن ولى بها ، وكأنه … مما يجر من العوامل حاطب\nمن كل نافذة المغار كأنها … في قلب حاملها فم متثاوب\nومزمجر قطع العجاج أمامه … للهام منه عمائم وذوائب\nيرمي الوحوش على الوحوش زهاؤه … والاكم فيه مع الجياد لواعب\nتهدي أوائله الأواخر كلما … طلع الجنيب طغى عليه الجانب\nشد كمعمعة الحريق وكبة … كالليل ، أنجمها قنا وقواضب\nوالنقع قد كتم الربى ، فكأنه … سيل تحدر ، والجياد قوارب\nولرب ليل قد طويت ردائه … وعلى الإكام من الظلام جلابب\nليل ترامى بالعبير نسيمه … والترب تحفزه صبا وجنائب\nوركبت أعجاز النجوم وفتية … مثل النجوم طوالع وغوارب\nخضنا الظلام وكلنا بجنانه … ماض على عجل ، وليس كواكب\nعلب كأنهم الصقور جوانحا … وكأن اكناف الجياد مراقب\nواذا قلوب لم تكن كعيوننا … لم يغننا ان النجوم ثواقب\nوأذل من قبر الخمول نشرته … فغدا يناهبك العلى ويجاذب\nاوسعته كرما فاوغرصدره … ان الاقارب بعدها لعقارب\nجود ضعيف ان تلم ملمة … لمؤمل واذى الد مشاغب\nولقد ملئت على عدوك جلده … حتى طمى جزع وضاق مذاهب\nبالعقل يبلغ ما تعذر بالقنا … وظبى القواضب والعقول مواهب\nأمنيل طالب نائل من جوده … كمنال صدر العضب يوم يضارب\nاليوم من فتيات دهرك ، فارعه … وجميع أيام الزمان أشائب\nوالعيد داعية السرور وليته … أبدا على بعض الرجال مصائب\nفتهن طماح العلاء ولا تزل … في غمر جودك للرجال رغائب\nخير من المال الذي يعطيكه … وأحد من غرب الحسام الضارب"},{"id":"diwan-radi:29","bookId":"diwan-radi","type":"poem","seq":29,"chapter":"البحر: طويل","title":"ألا حيها ، رب العلى ، من غوارب","page":"","text":"ألا حيها ، رب العلى ، من غوارب … تعرقني بين العلى والمطالب\nومالي وللامال من دونها القنا … تهز وسورات النوى والنوائب\nسئمت زمانا ، تنتحيني صروفه … وثوب الافاعي أو دبيب العقارب\nمقام الفتى عجز على ما يضيمه … وذل الجريء القلب إحدى العجائب\nساركبها بزلاء اما لمادح … يعدد افعالي واما لنادب\nإذا قل عزم المرء قل انتصاره … وأقلع عنه الضيم دامي المخالب\nوضاقت إلى ما يشتهي طرق نفسه … ونال قليلا مع كثير المعائب\nوما بلغ المرمى البعيد سوى امرىء … يروح ويغدو عرضة للجواذب\nوما جر ذلا مثل نفس جزوعة … ولا عاق عزما مثل خوف العواقب\nالا ليت شعري هل تسالمني النوى … وتخبو همومي من قراع المصائب\nالى كم اذود العين ان يستفزها … وميض الأماني والظنون الكواذب\nحسدت على أني قنعت فكيف بي … إذا ما رمى عزمي مجال الكواكب\nوما زال للإنسان حاسد نعمة … على ظاهر منها قليل وغائب\nوأبقت لي الأيام حزما وفطنة … ووقرن جاشي بالامور الغرائب\nتوزع لحمي في عواجم جمة … وبان على جنبي وسم التجارب\nوأرض بها بعت الصبابة والصبا … وناهض قلبي الهم من كل جانب\nوزور من الأضغان نحوي ، كأنما … يلاقيهم شخصي لقاء المحارب\nأناسيهم بغضاءهم غير غافل … وأسألهم معروفهم غير راغب\nوإني لأطويهم على عظم دائهم … واقعد منهم بين رام وجالب\nألا رب مجد قد ضرحت قذاته … وكان على الايام جم الشوائب\nوسر كتمت الناس حتى كتمته … ضلوعي ، ولم أطلع عليه مآربي\nواغيد محسود على نور وجهه … هجرت سوى لحظ البعيد المجانب\nوغيداء قيدت للعناق ملكتها … فنزهت عنها بعد وجد ترائبي\nوما عفة الانسان الا غباوة … اذا لم يكافح داء وجد مغالب\nوعزم كاطراف الاسنة في الحشا … طعنت به كيد العدو الموارب\nوضيم كما مض الجراح نجوته … إلى المنظر الأعلى نجاء الركائب\nوخطة خسف فتها غير لاحق … بي العار إلا ما نفضت ذوائبي\nعلى همة ، أيدي المنون سياطها … تسوق بها الآمال سوق النجائب\nالى قائم بالمجد يحمي فروجه … ويطعن عنه بالقنا والرغائب\nمقيم بطيب الذكر في كل بلدة … وقد عود الاكوار جب الغوارب\nفتى صحب البأس الندى في بنانه … بفيض العطايا والدماء السوارب\nلأمجد فرع في عرانين هاشم … وأنجب عود من لؤي بن غالب\nلهم سرة المجد التليد وسره … ومحض المعالي فيهم والمناقب\nيبيتون ، أغماد السيوف نحورهم … ويغدون جرار الرماح السوالب\nترقوا عليها كل مجد ونكسوا … بأطرافها عن عاقدات السباسب\nوخطب على الزوراء ألقى جرانه … مديد النواحي مدلهم الجوانب\nواضرمها حمراء ينزو شرارها … إلى جنبات الجو نزو الجنادب\nسللت عليه الحزم حتى جلوته … كما انجاب غيم العارض المتراكب\nوقد علم الأعداء أنك تحته … غلبت ، وما كان القضاء بغالب\nواقشعت عن بغداد يوما دويه … الى الان باق في الصبا والجنائب\nولولاك علي بالجماجم سورها … وخندق فيها بالدماء الذوائب\nوكم لك من يوم تركت به الظبى … مضاربها مشغولة بالضرائب\nسوابقه ما بين كاب وناهض … واقرانه ما بين هاو وواثب\nوقدت إليه الحيل يسببن بالقنا … ويسببن بوغاء الملا والسباسب\nثقالا باعباء العوالي كانما … يطأن الربى وطيء الإماء الحواطب\nمعاودة عض الشكيم يمصها … رشاش الجواني بالنبال الصوائب\nوقد شمر التحجيل عن جنباتها … وحجلها خوضا نجيع المقانب\nفقصرت فيه كل سمراء لدنة … وأنحلت فيه كل أبيض قاضب\nواصدرت عنه الجيش من بعد هبوة … توصل أعناق القنا والقواضب\nوأرعن دماغ الربى في مجره … يطبق عرض البيد ذات المناكب\nسريت به حتى تقلص نقعه … عن الفجر طلاعا جبال الغياهب\nوفي كل يوم انت بالعزم راكب … قراديد أمر لا تذل لراكب\nوليس عجيبا ان تمخط بازل … سرت فيه اعراق القروم المصاعب\nتداركت أطناب الخلافة بعدما … دنا الضيم حتى مسها بالرواجب\nوما زلت ترمي كل قلب مجاذب … تجاذبها حتى قلوب الاقارب\nهنيئا لك العيد الجديد فانه … يسل لك الإقبال عضب المضارب\nوعزك باق لا يزلزل طوده … وكل المعالي بين ماض وآيب\nوما راقت الاعياد الا بغرة … تبلج عن نور من المجد ثاقب\nوكيف يسر الفطر من عاش دهره … بعنوان معروف الجناجن شاحب\n … فما الشيب إلا سبة للأشائب\nانا القائل المرموق من كل ناظر … اذا صلصلت للسامعين غرائبي\nوما صنت شعري عنك زهدا ، وإنما … هو الدر لا يمري بغير الحوالب\nولي من قريضي منبه لضميره … ولكنني آبى دني المكاسب\nوما كل شغلي بالمقال أروضه … "},{"id":"diwan-radi:30","bookId":"diwan-radi","type":"poem","seq":30,"chapter":"البحر: وافر تام","title":"أرابك من مشيبي ما أرابا","page":"","text":"أرابك من مشيبي ما أرابا … وما هذا الباض علي عابا\nلئن ابغضت مني شيب راسي … فإني مبغض منك الشبابا\nيذم البيض من جزع مشيبي … ودل البيض اول ما اشابا\nوكانت سكرة ، فصحوت منها … وأنجب من أبى ذاك الشرابا\nيميل بي الهوى طربا وانأى … ويجذبني الصبا غزلا فآبا\nويمنعني العفاف كأن بيني … وبين مآربي منه هضابا\nنصلت عن الصبا ومصاحبيه … وأبدلني الزمان بهم صحابا\nولما جد جد البين فينا … وهبت له الظعائن والقبابا\nوماروعت من جزع جنانا … ولا رويت من دمع جنابا\nدعيني أطلب الدنيا ، فإني … ارى المسعود من رزق الطلابا\nومن ابقى لآجله حديثا … ومن عانى لعاجله اكتسابا\nوما المغبون إلا من دهته … ولا مجدا ولا جدة اصابا\nفلا والله اتركها خليا … ولما اجنب الاسد الغضابا\nواركبها محصنة شبوبا … تمانع غير فارسها الركابا\nاذا نهنهتها ارنت جماحا … إلى أملي ، تجاذبني جذابا\nفإما أملأ الدنيا علاء … وإما أملأ الدنيا مصابا\nسجية من رعى الايام حتى … أشاب جماجما منها ، وشابا\nوهل تشوي حقايق المعي … إذا ما ظن أغرض أو أصابا\nولم أر كالمآرب راميات … بنا الدنيا بعادا واقترابا\nتخوضنا البحار مزمجرات … وتسلكنا المضايق والعقابا\nواعظم من عباب … على الارزاق اركبنا العبابا\nوغلب كالقواضب من قريش … يروون القواضب والكعابا\nفما ولد الأجارب من تميم … نظيرهم ولا الشعر الرقابا\nوإن المجد قد علمت معد … ودار العز والنسب القرابا\nلأطولهم ، إذا ركبوا ، رماحا … واعلاهم اذا نزلوا قبابا\nوأغزرهم ، إذا سئلوا ، عطاء … وأوحاهم ، إذا غضبوا ، ضرابا\nبنو عم النبي واقربوه … والصقهم به عرقا لبابا\nعل ى بيد الحسين ذؤابتاها … وفرعاها اللذا كثرا وطابا\nوكانت لا تجار من الأعادي … فساند غربة ذاك النصابا\nوحصنها فليس ينال منها … ذنوبا ، من يهم ، ولا ذنابا\nهمام ما يزال بكل أرض … يبرقع تربها الخيل العرابا\nنزائع كالسهام كسين نحضا … خفيفا لا اللؤام ولا اللغابا\nمحبسة على الأهوال تلقى … بها العقبان رافعة الذنابا\nيوقرها ، فتحسبها أسودا … ويطلقها فتحسبها ذئابا\nوأعطته الرؤوس مسومات … تدق بها الجنادل والظرابا\nإذا قطعت به شأوأ بلاها … بأبعد غاية وأمد قابا\nتجاوزه المقاول وهو باق … يبذ رقاب غلبهم غلابا\nكنصل السيف تسلم شفرتاه … ويخلق كل أيام قرابا\nاذا اشتجر القنا فصل الهوادي … وإن قر الوغى فصل الخطابا\nبلى وبلت يداه من الأعادي … أراقم نزعا وقنا صلابا\nفقوم بالأذى منها صعادا … وذلل بالرقي منها صعابا\nوغادر كل أرقم ذي طلوع … على الاعداء يدرع الترابا\nحذار بني الضغائن من جري … اذا ما الريب بادهه ارابا\nيعض على لواحظ أفعوان … فان سيم الاذى طلب الوثابا\nوإن وراء ذاك الحلم صولا … وان لتلكم البقيا عقابا\nولو أن الضراغم نابذته … تولج خلفها أجما وغابا\nرماكم بالضوامر مقربات … يزاولن المحاني والشعابا\nويعجلن الصريخ وهن زور … الى الأعداء يرسلن اللعابا\nفارعى من جماجمكم جميعا … وامطر من دماءكم سحابا\nلك الهمم التاي عرف الاعادي … تشب بكل مظلمة شهابا\nاذا خفقت رياح العزم فيها … تبلج عارض منها ، فصابا\nومشرعة الأسنة ذات جرس … يقود عقاب رايتها العقابا\nتخوض الليل يلمع جانباها … كأن الصبح قد حدر النقابا\nلها في فرجة الفجر اختلاط … يرد الصبح من رهج غيابا\nوتغدو كالكواكب لامعات … تمزق من عجاجتها الحجابا\nيصافحها شعاع الشمس حتى … كأن على الظبى ذهبا مذابا\nصدمت بها العدو ، وأنت تدعو … نزال ، فأي داعية أجابا\nوقوضت الخيام تذب عنها … أسود وغى ، وأصفرت الوطابا\nرأينا الطايع الميمون بدءا … يسلك في النوائب ، واعتقابا\nولما جرت البيض المواضي … رآك من الظبي امضى ذبابا\nفالحمك العدى حتى تهاووا … ولا دمنا تحس ولا ضبابا\nهناك قدوم اعياد طراق … تصوب العز ما وجدت مصابا\nوايام تجوز عليك بيض … وقد قرعت من الإقبال بابا\nفكم يوم كيومك قدت فيه … على الغرر ، المقانب والركابا\nالى البلد الامين مقومات … يماطلها التعجل والإيابا\nبحيث تفرغ الكوم المطايا … حقائبها وتحتقب الثوابا\nمعالم إن أجال الطرف فيها … مصر القوم أقلع ، أو أنابا\nففزت بها ثماني معلمات … نصرت بها النبوة والكتابا\nبعثت لك الثناء على صنيع … إذا ما هبت دعوته أهابا\nرغائب قد قطعن حنين عيس … فلا نأيا اريغ ولا اغترابا\nوقبل اليوم ما أغمدن عني … من الايام نائبة ونابا"},{"id":"diwan-radi:31","bookId":"diwan-radi","type":"poem","seq":31,"chapter":"البحر: بسيط تام","title":"لكل مجتهد حظ من الطلب","page":"","text":"لكل مجتهد حظ من الطلب … فاسبق بعزمك سير الانجم الشهب\nوارق المعالي التي اوفى ابوك بها … فكم تناولها قوم بغير أب\nولا تجز بصروف الدهر في عصب … من القرائن غير السمر والقضب\nندعوك في سنة شابت ذوائبها … حتى تفرجها مسودة القصب\nولم تزل خدعات الدهر تطرقها … حتى تعانق عود النبع والغرب\nاتيت تحتلب الايام اشطرها … فكل حادثة منزوحة الحلب\nلولا وقارك في نصل سطوت به … فاضت مضاربه من خفة الطرب\nوحسن رأيك في الأرماح ينهضها … إلى الطعان ، ولولا ذاك لم تثب\nكن كيف شئت فان المجد محتمل … عنك المغافر في بدء وفي عقب\nما زال بشرك في الأزمان يؤنسها … حتى أضاءت سرورا أوجه الحقب\nيفديك كل بخيل مات خاطره … فان خطرت عددناه من الغيب\nإذا المطامع حامت حول موعده … انت اليه انين المدنف الوصب\nوعصبة جاذبوك العز فانقبضت … اكفهم عنم دراك المجد بالطلب\nشابهتهم منظرا اوفتهم خبرا … إن الرديني معدود من القصب\nهابوا ابتسامك في دهياء مظلمة … وليس يوصف ثغر الليث بالشنب\nسجية لك فاتت كل منزلة … وضعضعت جنبات الحادث الأشب\nنسيمها من طباع الروض مسترق … وطيب لذتها من شيمة الضرب\nتلقى الخميس إذا اسودت جوانبه … بالمستنيرين من رأي وذي شطب\nونثرة فوقها صبر تظاهره … أرد منها لأذراب القنا السلب\nلو لم يعوضك هجر العيش صالحة … ما كنت تخرج من أثوابه القشب\nيا ابن الذين ، إذا عدوا فضائلهم … عد الندى ضربهم في هامة النشب\nبألسن راضة لقول لو نضيت … نابت عن السمر في الابدان والحجب\nلا يستثيرون الاكل منصلت … حامي الحقيقة طلاع على النقب\nذي عزمة إن دعاها الروع منتصرا … تلفتت عن غرار الصارم الخشب\nيقرون حتى لو ان الضيف فاتهم … حثوا اليه صدور الاينق النجب\nأو أعوز الخطب في ليل بيوتهم … مدوا يد النار في الأعماد والطنب\nلو أن بأسهم جارى الزمان إذا … لارتد عن شأوه مسترخي اللبب\nإن أوردوا الماء لم تنهل جيادهم … حتى تعل برقراق الدم السرب\nقادوا السوابق محفاة مقودة … كأنها بحثت عن مضمر الترب\nاعطافها بالقنا الخطى مثقلة … تكاد تعصف بالساحات والرحب\nما انفك يطعن في اعقاب حافلة … بذابل من دم الاقران مختضب\nإذا امترى علق الأوداج عامله … اعشى العوالي فلم تنظر الى سلب\nولا يزال يجلي نقع قسطله … بمحرج الغرب ملآن من الغضب\nإذا انتضاه ليوم الروع تحسبه … يسل من غمده خيطا من الذهب\nأو إن أشاح به سال الحمام له … في مضربيه فلم يرقأ ولم يصب\nجذلان يركع ان مال الضراب به … مطربا في قباب البيض واليلب\nيا أيها الندب إن السعد متضح … بطلقة الوجه جلت سدفة الريب\nمولودة سقطت عن حجر والدة … جاءت بها ملء حجر المجد والحسب\nلما ظمئت إليها قبل رؤيتها … أعطيت لذة ماء الورد بالقرب\nباشر بطلعتها العلياء مقتبلا … فانها درة في حلية النسب\nواسعد بها واشكر الاقدار ان حملت … اليك قرة عين العجم والعرب\nوحث خيل كؤوس العز جامحة … إلى السرور بخيل اللهو واللعب\nوانثر على الشرب سمطا من فواقعها … وابن الغمام مسمى بابنة العنب\nواصدم بكاسك صدر الدهر معتقلا … بصارم اللهو يجلو قسطل الكرب\nكاس اذا خضبت بالماء لمتها … شابت وان زل عنها الماء لم تشب\nنفسي تقيك فكم وقيتني بيد … وقد ألظ بي الرامون عن كثب\nاذا اتقيت بك الاعداء رامية … فواجب أن أوقيك النوائب بي\nأبا الحسين أعر شعري إصاخة من … يروى مسامعه عن مسمع عجب\nإذا مدحتك لم أمتن عليك به … فالمدح باسمك والمعنى به نسبي"},{"id":"diwan-radi:32","bookId":"diwan-radi","type":"poem","seq":32,"chapter":"البحر: وافر تام","title":"الان جوانبي غمز الخطوب","page":"","text":"الان جوانبي غمز الخطوب … وأعجلني الزمان إلى المشيب\nوكم يبقى على عجم الليالي … وقرع الدهر جايرة الكعوب\nنبا ظهر الزمان وكنت منه … على جنبي موقعة ركوب\nوقالوا : الشيب زار ، فقلت : أهلا … بنور ذوائب الغصن الرطيب\nولم آك قبل وسمك لي محبا … فيبعد بي بياضك من حبيب\nولا ستر الشباب علي عيبا … فأجزع أن ينم على عيوبي\nولم اذمم طلوعك بي لشيء … سوى قرب الطلوع إلى شعوب\nواعظم ما الاقي ان دهري … يعد محاسني لي من ذنوبي\nأقول إذا امتلأت أسى لنفسي : … أيا نفس اصبري أبدا وطيبي\nدعى خوض الظلام بكل ارض … وإعمال النجيبة والنجيب\nوجر ضوامر الاحشاء تجري … كما تهوى الدلاء الى القليب\nمترفة الى الغايات حتى … ترنح في الشكيم من اللغوب\nفليس الحظ للبطل المحامي … ولا الاقبال للرجل المهيب\nونيل الرزق يؤخذ من بعيد … كنيل الرزق يؤخذ من قريب\nوغاية راكبي خطط المعالي … كغاية من اقام عن الركوب\nاليس الدهر يجمعنا جميعا … على مرعى من الحدثان موبي\nكلانا تضرب الأيام فيه … بجرح من نوائبها رغيب\nارى برد العفاف اغض حسنا … على رجل من البرد القشيب\nعلي سداد نبلي يوم ارمي … ورب النبل أعلم بالمصيب\nولي حث الركاب وشد رحلي … وما لي علم غامضة الغيوب\nوما يغني مضيك في صعود … إذا ما كان جدك في صبوب\nتطأطأت الذوائب للذنابى … وأسجدت الموارن للعجوب\nوخرق كالسماء خرجت منه … بجري أقب يركع في السهوب\nيجر عنانه في كل يوم … الى الاعداء معقود السبيب\nوخوص قد سريت بهن ، حتى … تقوضت النجوم إلى الغيوب\nوجرد قد دفعت بهن ، حتى … وطئن على الجماجم والتريب\nويوم ترعد الربلات منه … كما قطع الربى عسلان ذيب\nهتكت فروجه بالرمح لما … دعوا باسمي ، ويا لك من مجيب\nوعند تعانق الاقران يبلى … قراع النبع بالنبع الصليب\nاخاؤك يا علي اساغ ريقي … وودك يا علي جلى كروبي\nفيا عوني ، إذا عدت الليالي … علي ، ويا مجني في الحروب\nعجبت من الانام وانت منهم … ومثلك في الأنام من العجيب\nعلوت عليهم في كل أمر … بطول الباع والصدر الرحيب\nوفتهم مراحا في سفور … بلا نزق وجدا في قطوب\nخطاب مثل ماء المزن تبرى … مواقعه العليل من القلوب\nوعزم ان مضيت به جريا … هوى مطر القنا بدم صبيب\nوحلم إن عطفت به معيدا … أطار قوادم اليوم العصيب\nوالفاظ كما لعبت شمال … ملاعبها على الروض الخصيب\nبطرف لا يخفض من خضوع … وقلب لا يتعتع من وجيب\nتهن بمهرجانك ، واعل فيه … إلى العلياء أعناق الخطوب\nوعش صافي الغدير من الرزايا … به خالي الأديم من الندوب\nلعلي أن أهزك في مرام … فأبلو منك مندلق الغروب\nوحاج في الضمير معضلات … سأسلمها إلى عزم طلوب\nلأقضيهن ، أو أقضي بهمي … غريب الوجه في البلد الغريب\nمنازعة الى العلياء حتى … أزر على ذوائبها جيوبي\nفإما نيل جانبها ، وإما … لقاء مسندين على الجنوب"},{"id":"diwan-radi:33","bookId":"diwan-radi","type":"poem","seq":33,"chapter":"البحر: متقارب تام","title":"وفى ذا السرور بتلك الكرب","page":"","text":"وفى ذا السرور بتلك الكرب … وهذا المقام بذاك التعب\nقدمت ، فأطرق صرف الزمان … عناء واغضت عيون النوب\nومثلك من قذفته الخطو … ب في صدر كل خميس لجب\nقريب المراد ، بعيد المرام … عظيم العلاء جليل الحسب\nومن قلقل البين اطنابه … ونال اقاصي المنى بالطلب\nغدت تشتكيك كؤوس المدام … ويثنى عليك القنا والقضب\nوكنا نصانع فيك الهموم … فصرنا نصانع فيك الطرب\nاذا ما الفتى وصل الزائري … ن اثنوا عليه نأي أو قرب\nوكيف يهنيك لفظ امرىء … يهني بقربك أعلى الرتب\nوكنا بذكرك نشفي الغليل … وما بيننا امد منشعب\nإلى أن تهلل وجه الزمان … ومن بان مثلك عنه شحب\nرأينا بوجهك نور اليقي … ن ، حتى خلعنا ظلام الريب\nومازلت تمسح خد الصباح … وترحم قلب الظلام الأشب\nبمطرورة الصدر خفاقة … تطير مجاذيفها كالعذب\nتعانقك الريح في صدرها … ويشتاقك الماء حتى يثب\nتمر بشخصك مر الجياد … وتسري برحلك سير النجب\nاذا اطردت بك خلت القصو … ر ترعد بالبعد أو تحتجب\nيسر بها عاشق لا يلذ … ذ بالناي أو نازح يقترب\nوقد بلغتك الذي رمته … وحق المبلغ أن يصطحب\nأبا قاسم كان هذا البعاد … الى طرق القرب اقوى سبب\nفما كنت أول بدر أتى … ولا كنت أول نجم غرب\nألا إنني حسرة الحاسدين … وما حسرة العجم إلا العرب\nفلا لبسوا غير هذا الشعار … ولا رزقوا غير هذا اللقب\nمنحتك من منطقي تحفة … رأيت بها فرصة تستلب\nتصفقها بالنشيد الرواة … كما صفق الماء بنت العنب\nوأنت تساهمني في العلا … ء فخرا ، وتشركني في النسب"},{"id":"diwan-radi:34","bookId":"diwan-radi","type":"poem","seq":34,"chapter":"البحر: بسيط تام","title":"لأشكرنك ما ناحت مطوقة","page":"","text":"لأشكرنك ما ناحت مطوقة … وان عجزت عن الحق الذي وجبا\nفما التفت الى نعماء سابغة … إلا رأيتك فيها الأصل والسببا\nاخدمتني نوب الايام طائعة … وكان كل الرضى أن آمن النوبا\nولا لقيت يدا للدهر جارحة … إذا بقيت ، ولا ألقى لها السببا\nوقد أقمت عماد البيت راسخة … على القواعد فامدد بعدها الطنبا"},{"id":"diwan-radi:35","bookId":"diwan-radi","type":"poem","seq":35,"chapter":"البحر: طويل","title":"لغير العلى مني القلى والتجنب","page":"","text":"لغير العلى مني القلى والتجنب … ولولا العلى ما كنت في الحب ارغب\nإذا الله لم يعذرك فيما ترومه … فما الناس الا عاذل أو مؤنب\nملكت بحلمي فرصة ما استرقتها … من الدهر مفتول الذراعين أغلب\nفإن تك سني ما تطاول باعها … فلي من وراء المجد قلب مدرب\nفحسبي اني في الاعادي مبغض … وأني إلى غر المعالي محبب\nوللحلم اوقات وللجهل مثلها … ولكن أوقاتي إلى الحلم أقرب\nيصول علي الجاهلون ، وأعتلي … ويعجم في القائلون واعرب\nيرون احتمالي غصة ، ويزيدهم … لواعج ضغن انني لست اغضب\nوأعرض عن كأس النديم ، كأنها … وميض غمام ، عائر المزن خلب\nوقور ، فلا الألحان تأسر عزمتي … ولا تمكر الصهباء بي ، حين أشرب\nولا اعرف الفحشاء الا بوصفها … ولا انطق العوراء والقلب مغضب\nتحلم عن كر القوارض شيمتي … كان معيد المدح بالذم مطنب\nلساني حصاة يقرع الجهل بالحجى … إذا نال مني العاضه المتوثب\nولست براض ان تمس عزائمي … فضالات ما يعطى الزمان ويسلب\nغرائب آداب حباني بحفظها … زماني وصرف الدهر نعم المودب\nتريشنا الأيام ثم تهيضنا … الانعم ذا البادي وبئس المعقب\nنهيتك عن طبع اللئام ، فإنني … ارى البخل يأتي والمكارم تطلب\nتعلم فان الجود في الناس فطنة … تناقلها الاحرار والطبع اغلب\nتضافرني فيك الصوارم والقنا … ويصحبني منك العذيق المرجب\nنصحت وبعض النصح في الناس هجنة … وبعض التناجي بالعتاب تعتب\nفان انت لم تعط النصيحة حقها … فرب جموح كل عنه المؤنب\nسقى الله ارضا جاور القطر روضها … اذ المزن تسقي والاباطح تشرب\nذكرت بها عصر الشباب ، فحسرة … أفدت وقد فات الذي كنت أطلب\nسكنتك والايام بيض كانها … من الطيب في اثوابنا تتقلب\nويعجبني منك النسيم اذا هفا … الا كل ما سرى عن القلب معجب\nوفي الوطن المألوف للنفس لذة … وان لم ينلنا العز الا التقلب\nوبرق رقيق الطرتين لحظته … اذا الجو خوار المصابيح اكهب\nفمر كما مرت ذوائب عشوة … تقاد بأطراف الرماح وتجنب\nنظرت والحاظ النجوم كليلة … وهيهات دون البرق شأ ومغرب\nفما الليل إلا فحمة مستشفة … وما البرق إلا جمرة تتلهب\nأمن بعد أن أجللتها ورق الدجى … سراعا واغصان الازمة تجذب\nوعدنا بها ممغوطة بنسوعها … كما صافح الارض السراء المعبب\nكأن تراجيع الحداة وراءها … صفير تعاطاه اليراع المثقب\nوردن بها ماء الظلام سواغبا … ولليل جو بالدراري معشب\nتنفر ذود الطير عن وكراتها … فكل ، إذا لاقيته ، متغرب\nوتلتذ رشف الماء رنقا كأنه … مع العز ثغر بارد الظلم أشنب\nاذعنا له سر الكرى من عيوننا … وسر العلى بين الجوانح يحجب\nحرام على المجد ابتسامي لقربه … وما هزني فيه العناء المقطب\nتهر ظنوني في المآرب إربة … ويجنب عزمي في المطالب مطلب\nودهماء من ليل التمام قطعتها … أغني حداء ، والمراسيل تطرب\nولو شئت غنتني الحمام عشية … ولكنني من ماء عيني اشرب\nأقول إذا خاض السميران في الدجى … أحاديث تبدو طالعات وتغرب\nالا غنياني بالحديث فانني … رأيت الذ القول ما كان يطرب\nغناء اذا خاض المسامع لم يكن … امينا على جلبابه المتجلبب\nونشوان من خمر النعاس ذعرته … وطيف الكرى في العين يطفو ويرسب\nله مقلة يستنزل النوم جفنها … إليه كما استرخى على النجم هيدب\nسلكت فجاج الأرض غفلا ومعلما … تجد بها ايدي المطايا وتلعب\nوما شهوتي لوم الرفيق وانما … كما يلتقي في السير ظلف ومخلب\nعجبت لغيري كيف ساير نجمها … وسيري فيها ، يا ابنة القوم ، أعجب\nأسير وسرجي بالنجاد مقلد … وأثوي وبيتي بالعوالي مطنب\nومصقولة الأعطاف في جنباتها … مراح لاطراف العوالي وملعب\nتجر على متن الطريق عجاجة … يطارحها قرن من الشمس اعضب\nنهار بلألاء السيوف مفضض … وجو بحمراء الأنابيب مذهب\nترى اليوم محمر الخوافي كانما … على الجو غرب من دم يتصبب\nصدمنا بها الاعداء والليل ضارب … بارواقه جون الملاطين اخطب\nأخذنا عليهم بالصوارم والقنا … وراعي نجوم الليل حيران مغرب\nفلو كان امرا ثابتا عقلوا له … ولكنه الأمر الذي لا يجرب\nيراعون إسفار الصباح ، وإنما … وراء لثام الليل يوم عصبصب\nوكل ثقيل الصدر من جلب القنا … خفيف الشوى والموت عجلان مقرب\nيجم اذا ما استرعف الكر جهده … كما جمت الغدران والماء ينضب\nوما الخيل الا كالقداح نجيلها … لغنم ، فإما فائز أو مخيب\nدعوا شرف الاحساب يا آل ظالم … فلا الماء مورود ولا الترب طيب\nلئن كنتم في آل فهر كواكبا … إذا غاض منها كوكب فاض كوكب\nفنعتي كنعت البدر ينسب بينكم … جهارا ، وما كل الكواكب تنسب\nصحبتم خضاب الزاعبيات ناصلا … ومن علق الاقران ما لا يخضب\nأهذب في مدح اللئام خواطري … فاصدق في حسن المعاني واكذب\nوما المدح إلا في النبي وآله … يرام وبعض القول ما يتجنب\nوأولى بمدحي من أعز بفخره … ولا يشكر النعماء إلا المهذب\nارى الشعر فيهم باقيا وكانما … تحلق بالأشعار عنقاء مغرب\nوقالوا عجيب عجب مثلي بنفسه … واين على الايام مثل ابي اب\nلعمرك ما اعجبت الا بمدحهم … ويحسب أني بالقصائد معجب\nاعد لفخري في المقام محمدا … وأدعو عليا للعلى حين أركب"},{"id":"diwan-radi:36","bookId":"diwan-radi","type":"poem","seq":36,"chapter":"البحر: بسيط تام","title":"المجد يعلم أن المجد من أربي","page":"","text":"المجد يعلم أن المجد من أربي … ولو تماديت في غي وفي لعب\nإني لمن معشر إن جمعوا لعلى … تفرقوا عن نبي أو وصي نبي\nاذا هممت ففتش عن شبا هممي … تجده في مهجات الأنجم الشهب\nوان عزمت فعزمي يستحيل قذى … تدمى مسالكه في اعين النوب\nومعرك صافحت ايدي الحمام به … طلى الرجال على الخرصان من كثب\nحلت حباها المنايا في كتائبه … بالضرب فاجتثت الأجساد بالقضب\nتلاقت البيض في الاحشاء فاعتنقت … والسمهري من الماذي واليلب\nبكت على الأرض دمعا من دمائهم … فاستعربت من ثغور النور والعشب"},{"id":"diwan-radi:37","bookId":"diwan-radi","type":"poem","seq":37,"chapter":"البحر: وافر تام","title":"الا لله بادرة الطلاب","page":"","text":"الا لله بادرة الطلاب … وعزم لا يروع بالعتاب\nوكل مشمر البردين يهوي … هوي المصلتات إلى الرقاب\nاعاتبه على بعد التنائي … ويعذلني على قرب الاياب\nرأيت العجز يخضع لليالي … ويرضى عن نوائبها الغضاب\nولولا صولة الايام دوني … هجمت على العلى من كل باب\nومن شيم الفتى العربي فينا … وصال البيض والخيل العراب\nله كذب الوعيد من الأعادي … ومن عاداته صدق الضراب\nسأدرع الصوارم والعوالي … وما عريت من خلع الشباب\nواشتمل الدجى والركب يمضي … مضاء السيف شذ عن القراب\nوكم ليل عبأت له المطايا … ونار الحي حائرة الشهاب\nلقيت الارض شاحبة المحيا … تلاعب بالضراغم والذئاب\nفزعت الى الشحوب وكنت طلقا … كما فزع المشيب الى الخضاب\nولم نر مثل مبيض النواحي … تعذبه بمسود الاهاب\nأبيت مضاجعا أملي ، وإني … ارى الامال اشقى للركاب\nاذا ما اليأس خيبنا رجونا … فشجعنا الرجاء على الطلاب\nأقول إذا استطار من السواري … زفون القطر رقاص الحباب\nكأن الجو غص به ، فأومى … ليقذفه على قمم الشعاب\nجدير أن تصافحه الفيافي … ويسحب فوقها عذب الرباب\nإذا هتم التلاع رأيت منه … رضابا في ثنيات الهضاب\nسقى الله المدينة من محل … لباب الماء والنطف العذاب\nوجاد على البقيع وساكنيه … رخي الذيل ملآن الوطاب\nواعلام الغري وما استباحت … معالمها من الحسب اللباب\nوقبرا بالطفوف يضم شلوا … قضى ظمأ الى برد الشراب\nوسامرا ، وبغدادا ، وطوسا … هطول الودق منخرق العباب\nقبور تنطف العبرات فيها … كما نطف الصبير على الروابي\nفلو بخل السحاب على ثراها … لذابت فوقها قطع السراب\nسقاك فكم ظمئت اليك شوقا … على عدواء داري واقترابي\nتجافي يا جنوب الريح عني … وصوني فضل بردك عن جنابي\nولا تسري إلي مع الليالي … وما استحقبت من ذاك التراب\nقليل أن تقاد له الغوادي … وتنحر فيه اعناق السحاب\nاما شرق التراب بساكنيه … فيلفظهم الى النعم الرغاب\nفكم غدت الضغائن وهي سكرى … تدير عليهم كأس المصاب\nصلاة الله تخفق كل يوم … على تلك المعالم والقباب\nوإني لا أزال أكر عزمي … وإن قلت مساعدة الصحاب\nوأخترق الرياح إلى نسيم … تطلع من تراب أبي تراب\nبودي ان تطاوعني الليالي … وينشب في المنى ظفري ونابي\nفأرمي العيس نحوكم سهاما … تغلغل بين أحشاء الروابي\nترامي باللغام على طلاها … كما انحدر الغثاء عن العقاب\nوأجنب بينها خرق المذاكي … فأملي باللغام على اللغاب\nلعلي أن أبل بكم غليلا … تغلغل بين قلبي والحجاب\nفما لقياكم الا دليل … على كنز الغنيمة والثواب\nولي قبران بالزوراء أشفي … بقربهما نزاعي واكتئابي\nأقود إليهما نفسي وأهدي … سلاما لا يحيد عن الجواب\nلقاؤهما يطهر من جناني … ويدرأ عن ردائي كل عاب\nقسيم النار جدي يوم يلقى … به باب النجاة من العذاب\nوساقي الخلق والمهجات حرى … وفاتحة الصراط إلى الحساب\nومن سمحت بخاتمه يمين … تضن بكل عالية الكعاب\nاما في باب خيبر معجزات … تصدق ، أو مناجاة الحباب\nأرادت كيده ، والله يأبى … فجاء النصر من قبل الغراب\nأهذا البدر يكسف بالدياجي … وهذي الشمس تطمس بالضباب\nوكان اذا استطال عليه جان … يرى ترك العقاب من العقاب\nارى شعبان يذكرني اشتياقي … فمن لي أن يذكركم ثوابي\nبكم في الشعر فخري لا بشعري … وعنكم طال باعي في الخطاب\nأجل عن القبائح غير أني … لكم أرمي وأرمى بالسباب\nفاجهر بالولاء ولا اوري … وأنطق بالبراء ، ولا أحابي\nومن أولى بكم مني وليا … وفي ايديكم طرف انتسابي\nمحبكم ولو بغضت حياتي … وزائركم ولو عقرت ركابي\nتباعد بيننا غير الليالي … ومرجعنا إلى النسب القراب"},{"id":"diwan-radi:38","bookId":"diwan-radi","type":"poem","seq":38,"chapter":"البحر: مجزوء الكامل","title":"إنا نعيب ، ولا نعاب","page":"","text":"إنا نعيب ، ولا نعاب … ونصيب منك ولا نصاب\nآل النبي ومن تقلب … في حجورهم الكتاب\nخلقت لهم سمر القنا … والبيض والخيل العراب\nفاقني حياءك ، إن … ما الأيام غنم ، أو نهاب\nمن لذ ورد الموت لا … يصفو له ابدا شراب\nوتطر في حيث السما … ح الغمر والحسب اللباب\nفي حيث للراجي الثوا … ب ندى وللجاني العقاب\nقوم ، إذا غمز الزما … ن قنيهم كرموا وطابوا\nواذا دعوا والخيل في الاج … فال ، ثابوا ، أو أجابوا\nأبني عدي ! إنما … سالت بخيلكم الشعاب\nوشرفتم بالطعن ، والدن … ضرام أو ضراب\nما كنتم إلا البحو … ر توالغت فيها الذئاب\nوقرعتم بالبيض حت … تى ضاع في اللمم الشباب\nواليوم تستل السيو … ف به وتنسل الرقاب\nكتمت دمائكم الظبا … كالشيب يكتمه الخضاب\nفتنازعوا شمط الظ … م فخلفه الاسد الغضاب\nوتعلموا أن الصبا … ح ضبارم ، والليل غاب\nلا صلح حتى تطمئن … إلى مناسمها الركاب\nويعود وجه الشمس لا … نقع عليه ، ولا ضباب\nحتى تشبت بالظبا الا … ماد ، والجرد الرحاب\nوتمد أطناب البيو … ت ، وتضمر القوم القباب\nوتردف الأدراع مش … رجة ، عليهن العياب\nوترى الربا والروض ينش … شر من مطارفها السحاب\nما كان فضضه فضي … الطل اذهبه الذهاب\nكانت نجوم الليل يك … مها من النقع الغياب\nفالان اصحر في السما … ء البدر وانكشف النقاب\nوعلت إلى أوكارها العق … ان وانحط العقاب\nعودوا إلى ذاك الغدي … ير وقل ما غدر الرباب\nوتغنموا تلك المنا … زل وهي آمنة رغاب\nوتداركوا ذود المسا … رح وهي بينكم سقاب\nوكأن أيام الهوى … فيكم نشاوى أو طراب\nمتمنطقات بالحلي … وفي قلائدها الملاب\nإني على لين النقي … بة لا أعاب ولا أحاب\nما شد لي يوما على … ذل ولا طمع حقاب\nمن لي بغرة صاحب … لا يستطيل عليه عاب\nما حارب الأيام إ … لا كان لي وله الغلاب\nولكل قول سامع … ولكل داعية جواب\nهيهات أطلب ما يطو … ل به بعاد واقتراب\nقل الصحاب ، فإن ظفر … ت بنعمة كثر الصحاب\nمن لي به سمحا اذا … صفرت من القوم الوطاب\nغيران دون الجار لا … يطوي عزايمه الحجاب\nيستعذب المومات منز … لة وان بعد الاياب\nرقت حواشي بيته … مما يلاطمها السراب\nلا يستقل برحله … إلا الذوائب والهضاب\nتهفو بكفيه الصوا … رم أو تسيل بها الكعاب\nجذلان يلتقط النسيم … م ، إذا تساقطت الثياب\nيمى إليه الشيح ، وال … حوذان والإبل الجراب\nوكان غرته وراء ل … ثام ليلته شهاب\nمن لي به يا دهر والا … يام كالحة غضاب\nإن الصديق مشيع … ان جل خطب أو خطاب\nويجود عنك بنفسه … والحرب تقرعها الحراب\nوأخ حرمت الود من … ه ، وبيننا نسب قراب\nنازعته ثدي الرضاع … وما يلذ لنا الشراب\nيا سعد ! أعظم محنة … من لا يروعه العتاب\nيجني على جيرانه … حتى يعاقبه السباب\nحسبي من الايام ان … ابقى ويسعدني الطلاب"},{"id":"diwan-radi:39","bookId":"diwan-radi","type":"poem","seq":39,"chapter":"البحر: متقارب تام","title":"دوام الهوى في ضمان الشباب","page":"","text":"دوام الهوى في ضمان الشباب … وما الحب الا زمان التصابي\nاحين فشا الشيب في شعره … وكتم أوضاحه بالخضاب\nتروعين اوقاته بالصدود … وترمين أيامه بالسباب\nتخطى المشيب الى راسه … وقد كان اعلى قباب الشباب\nكذاك الرياح إذا استلأمت … تقصف أعلى الغصون الرطاب\nمشيب كما استل صدر الحسا … م ، لم يرو من لبثه في القراب\nنضى فاستباح حمى الملهيات … وراع الغواني بظفر وناب\nوألوى بجدة أيامه … فأصبح مقذى لعين الكعاب\nتستر منه مجال السوار … إذا ما بدا ومناط النقاب\nوكان ، إذا شردت نية … يرد رقاب الخطوب الغضاب\nوكنت أرقرق ماء الوصال … وبحر الشبيبة طاغي العباب\nوكأسي معودة بالسماع … تركض بين القلوب الطراب\nاذا نصفت فهي في مئزر … وتبرز ان اترعت في نقاب\nسمائي مذهبة بالبروق … وأرضي مفضضة بالحباب\nوروضي مطارفه غضة … تطرز اطرافها بالذهاب\nوليل ترى الفجر في عطفه … كما شاب بعض جناح الغراب\nيغار الظلام على شمسه … إلى أن يواريها بالحجاب\nوتصقل انجمه العاصفات … اذا صديت من غمود السحاب\nوبرق ينفض اطرافه … كما رمحت بلق خيل عراب\nوماء يضارع خيط السقاء … ويرمى به في وجوه الشعاب\nتزعزع ريح الصبا متنه … كما لطم المزج خد الشراب\nوذود يغادر وجه الصعيد م … ن حلة العشب عاري الإهاب\nفما تطلب البيد من ساهم … يثير عليها رقاب الركاب\nيساعدها في احتمال الصدى … ويشركها في ورود السراب\nيذكره أخذ أوتاره … صهيل السوابق حول القباب\nدفعن بخضخضة للمزاد … نجاء وخشخشة للعياب\nلبل أنابيبه بالطعان … وأنحل أسيافه بالضراب\nيبيت وثوب الدجى شاحب … طموح المعالم سامي الشهاب\nوم كنت أجري إلى غاية … فاسألها أين وجه الاياب\nاذا استنهضت هممي عزمة … عصفت بايدي المطي العراب\nتحريت اعجازها بالسياط … فخاضت صدور الامور الصعاب\nفكم قائف قد هدت لحظه … بدور مناسمها في التراب\nإذا مات في وخدهن المدى … لطمن خدود الربى والرحاب\nفداؤك نفسي يا من له … من القلب ربع منيع الجناب\nفلولاك ما عاق قلبي الهوى … وعز على كل شوق طلابي\nإذا ما صددت دعاني الهوى … فملت الى خدعات العتاب\nفيا جنتي إن رماني الزمان … ويا صاحبي ان جفاني صحابي\nدفعت بكفي زمامي إليك … وقد كنت ابطى على من حدابي\nفلا تحسبني ذليل القياد … فإني أبي على كل آبي\nوساع إلى الود شبهته … ويرتع مع أهله في جناب\nيؤمن سطوة ليث العرين … ومضجعه بين غيل وغاب\nحمته مذلته سطوتي … وكيف ينال ذبابا ذبابي\nوملتثم قال لي لثمه … عذاب الهوى في الثنايا العذاب\nنعاقر بالضم كاس العناق … ونسفك باللثم خمر الرضاب\nعناق كما ارتج ماء الغدير … ولثم كما استن ولغ الذئاب\nغدونا على صهوات الخطوب … جوادي رهان وسيفي قراب\nصقيلين تستلنا النائبات … فتثلم فيهن ، والدهر ناب\nوغصنين يلعب فينا النسيم … وتنطف عنا نطاف الرباب\nونجمين يقصر عن نيلنا … من الطالعات الذرى والروابي\nوكنا ، إذا مسنا حادث … نقلم بالصبر ظفر المصاب\nاليك تخطت فروج القلوب … بكر من الآنسات العراب\nأشبب فيها بذكر المشيب … وما استيأست لمتي من شبابي"},{"id":"diwan-radi:40","bookId":"diwan-radi","type":"poem","seq":40,"chapter":"البحر: وافر تام","title":"أغدرا يا زمان ويا شباب","page":"","text":"أغدرا يا زمان ويا شباب … اصاب بذا لقد عظم المصاب\nوما جزعي لان غرب التصابي … وحلق عن مفارقي الغراب\nفقبل الشيب أسلفت الغواني … قلى وامالني عنها اجتناب\nعففت عن الحسان ، فلم يرعني … المشيب ولم ينزقني الشباب\nتجاذبني يد الايام نفسي … ويوشك ان يكون لها الغلاب\nوتغدر بي الأقارب والأداني … فلا عجب اذا غدر الصحاب\nنهضت وقد قعدن بي الليالي … فلا خيل أعن ولا ركاب\nوما ذنبي اذا اتفقت خطوب … مغالبة ، وأيام غضاب\nوآمل أن تقي الأيام نفسي … وفي جنبي لها ظفر وناب\nفما لي والمقام على رجال … دعت بهم المطامع ، فاستجابوا\nولم أر كالرجاء اليوم شيئا … تذل له الجماجم والرقاب\nوكان الغبن لو ذلوا ونالوا … فكيف إذا وقد ذلوا وخابوا\nيريدون الغنى ، والفقر خير … اذا ما الذل اعقبه الطلاب\nوبعض العدم مأثرة وفخر … وبعض المال منقصة وعاب\nبناني والعنان اذا نبت بي … ربى أرض ورحلي والركاب\nوسابغة كأن السرد فيها … زلال الماء لمعه الحباب\nمن اللآئي يماط العيب عنها … إذا نثلت لدى الروع العياب\nاذا ادرعت تجنبت المواضي … معاجمها وقهقهت الكعاب\nومشرفة القذال تمر رهوا … كما عسلت على القاع الذئاب\nمجلية تشق بها يداها … كما جلى لغايته العقاب\nومرقبة ربأت على ذراها … ولليل انجفال وانجياب\nبقرب النجم عالية الهوادي … يبيت على مناكبها السحاب\nإلى أن لوح الصبح انفتاقا … كما جلي عن العضب القراب\nوقد عرفت توقلي المعالي … كما عرفت توقلي العقاب\nونقب ثنية سددت فيها … أصم كأن لهذمه شهاب\nلأمنع جانبا وأفيد عزا … وعز المرء ما عز الجناب\nإذا هول دعاك فلا تهبه … فلم يبق الذين ابوا وهابوا\nكليب عاقصته يد ، وأودى … عتيبة يوم أقعصه ذؤاب\nسواء من اقل الترب منا … ومن وارى معالمه التراب\nوإن مزايل العيش اختصارا … مساو للذين بقوا ، فشابوا\nفاولنا العناء اذا طلعنا … إلى الدنيا ، وآخرنا الذهاب\nإلى كم ذا التردد في الأماني … وكم يلوي بناظري السراب\nولا نقع يثار ولا قتام … ولا طعن يشب ولا ضراب\nولا خيل معقدة النواصي … يموج على شكائمها اللعاب\nعليها كل ملتهب الحواشي … يصيب من العدو ولا يصاب\nأمام مجلجل كالليل تهوي … أواخره ، الجمايل والقباب\nوأين يحيد عن مضر عدو … اذا زخرت وعب لها العباب\nوقد زأدت ضراغمها الضواري … وقد هدرت مصاعبها الصعاب\nهنالك لا قريب يرد عنا … ولا نسب نيط بنا قراب\nسأخطبها بحد السيف فعلا … إذا لم يغن قول ، أو خطاب\nوآخذها ، وإن رغمت أنوف … مغالبة ، وإن ذلت رقاب\nوإن مقام مثلي في الأعادي … مقام البدر تنبحه الكلاب\nرموني بالعيوب ملفقات … وقد علموا بأني لا أعاب\nوأني لا تدنسني المخازي … وأني لا يروعني السباب\nولما لم يلاقوا في عيبا … كسوني من عيوبهم وعابوا"},{"id":"diwan-radi:41","bookId":"diwan-radi","type":"poem","seq":41,"chapter":"البحر: متقارب تام","title":"اثرها على ما بها من لغب","page":"","text":"اثرها على ما بها من لغب … يقلقل أغراضها والحقب\nولا ترقب اليوم ميط الاذى … عن اخفافها واندماء الجلب\nإلى أن تعجعجها كالحني … تجتر بالدم لا بالعشب\nعليها أخامص مثل الصقور … طوال الرجاء جسام الارب\nوكل فتى حظ أجفانه … من الضيم مضمضة تستلب\nفبينا يقال كرى جفنه … بقطع من الليل إذ قيل : هب\nاذا وقعوا بعد طول الكلال … لم يغمزوا قدما من تعب\nولما يعافوا على عزهم … توسد أعضادها والركب\nوعرج على الغر من هاشم … فأهد السلام لهم من كثب\nوقل لبني عمنا الواجدين … بني عمنا ، بعض هذا الغضب\nاما آن للراقد المستمر … في ظلم الغي أن يستهب\nسرحتم سفاهتكم في العقوق … ولم تحفلوا الحلم لما غرب\nولما ارنتم اران الجموح … وماج بكم حبلكم واضطرب\nأقمنا أنابيبكم بالثقاف … وداوى الهناء مطال الجرب\nويا ربما عاد سوء العقاب … على المذنبين بحسن الأدب\n … مضيض من الداء ان يستطب\nأطال وأعرض ما بيننا … مبير الحياء مثير الريب\nافي كل يوم لرق الهوان … صبيبة انفسكم تنسكب\nإذا قادكم مثل قود الذلول … نفرنا نفور البعير الازب\nوفي كل يوم الى داركم … مزاحف من فيلق ذي لجب\nبوهوهة الخيل تحت الرماح … مكرهة ورغاء النجب\nسياط الجياد به إن ونين … وزجر الرحال بهال وهب\nوتلقونها كقداح السرا … ء ، قودا تجر العوالي وقب\nكان حوافزها والصخور … إذا ما ذرعن الدجى في صخب\nتسد على البيد خرق الشمال … بما نسجت من سحيل الترب\nوطئن النجيع بارساغهن … مما انتعلن الربى والذأب\nوكم قرع الدو من حافر … يخال على الارض قعبا يكب\nتهز السيوف لأعناقكم … فتأبى مضارب تلك القضب\nوتسفر احسابنا بيننا … فنلقي طوائلنا أو نهب\nيناشدنا الله في حربكم … عريق لكم في أبينا ضرب\nوما أحدث الدهر من نبوة … وقطع ما بيننا من سبب\nفإن النفوس إليكم تشاق … وإن القلوب عليكم تجب\nوإنا نرى لجوار الديار … حقوقا فكيف جوار النسب\nتماسس ارحامنا والذمام … م من دون ذاك علينا يجب\nفان نرع شركة احسابنا … جميعا ، فذلك دين العرب\nاذا لبست بقواها قوى … وإن طنب مس منها طنب\nأراح بني عامر ذلهم … وعرضنا عزنا للتعب\nوفرنا عليهم طريق البقاء … وخلوا لنا عن طريق العطب\nفقد اصبحوا في ذمام الخمول … لا تدريهم مرامي النوب\nأبى الناس إلا ذميم النفاق … إذا جربوا ، أو قبيح الكذب\nكلاب تبصبص خوف الهوان … وتنبح بين يدي من غلب\nاذم لوجهي على ما به … ولا يعدل الذل عندي النشب\nومن وجد الرزق عند السيوف … فلم يتحمل لذل الطلب\nوان منازل هذا الزمان … لانبائه نوب أو عقب\nلذلك يركب من قد سعى … طويلا ويرحل من قد ركب\nانا ابن الاناجب من هاشم … اذا لم يكن نجب من نجب\nتلاث برودهم بالرماح … وتلوى عمائمهم بالشهب\nعتاق الوجوه وعتق الجياد … في الضمر تعرفه والقبب\nيشف الوضاء خلال الشحو … ب منها ، وخلف الدخان اللهب\nوقار يهاب ، وناد يناب … وحلم يراح وراي يغب\nاذا استبق القوم طرق النجاء … وذم الجبان قعود الهرب\nرأيتهم في ظلال القنا … وقد ضاق للكرب عقد اللبب\nقد امتنعوا بحصون الدروع … ع ، واستعصموا بقباب اليلب\nأولئك قومي لم يغمزوا … بهجنة ام ولا لؤم اب\nومن قال : إن جميع الفخار … لغير ذوائب قومي كذب"},{"id":"diwan-radi:42","bookId":"diwan-radi","type":"poem","seq":42,"chapter":"البحر: طويل","title":"هل الطرف يعطي نظرة من حبيبه","page":"","text":"هل الطرف يعطي نظرة من حبيبه … ام القلب يلقى راحة من وجيبه\nوهل لليالي عطفة بعد نفرة … تعود فتلهى ناظرا عن غروبه\nولله ايام عفون كما عفى … ذوائب مياس العرار رطيبه\nاحن الى نور الربى في بطاحه … وأظما إلى ريا اللوى في هبوبه\nوذاك الحمى يغدو عليلا نسيمه … ويمسي صحيحا ماؤه في قليبه\nحببت لقلبي ظله في هجيره … إذا ما دجا أو شمسه في ضريبه\nوعهدي بذاك الظبي إبان زرته … رعاني ، ولم يحفل بعيني رقيبه\nوحكم ثغري في إناء رضابه … وأدنى جوادي من إناء حليبه\nهو الشوق مدلولا على مقتل الفتى … اذا لم يعد قلبا بلقيا حبيبه\nتعيرني تلويح وجهي ، وإنما … غضارته مدفونة في شحوبه\nفرب شقاء قد نعمنا بمره … ورب نعيم قد شقينا بطيبه\nولولا بواقي نائبات من الردى … غفرت لهذا الدهر ماضي ذنوبه\nواني لعرفان الزمان وغدره … أبيت وما لي فكرة في خطوبه\nواصبح لا مستعظما لعظيمه … بقلبي ولا مستعجبا لعجيبه\nيغم الفتى ذكر المشيب وربما … يلقى انقضاء العمر قبل مشيبه\nوينسيه بدء العيش ما في عقيبه … وجيئته تبدي لنا عن ذهوبه\nالى كم اشق الليل عن كل مهمه … وأرعى طلوع النجم حتى مغيبه\nأخط بأطراف القنا كل بلدة … واملي جلابيب الملا من ندوبه\nوكنت اذا خوى نجيب تركته … أسير عقال مؤلم من لغوبه\nرجاء لعز أقتنيه وحالة … تزيد عدوي من غواشي كروبه\nوبزلاء من جند الليالي لقيتها … بقلب بعيد العزم فيها قريبه\nنصبت لها وجهي وليس كعاجز … يوقيه حر الطعن من يتقى به\nوخيل كأمثال القنا تحمل القنا … على كل عنق عاقد من سبيبه\nحملت عليها كل طعان سربة … كما نهز الساقي بجنبي قليبه\nقضى وطر العلياء من ركب القنا … وأولغ بيضا من دم في صبيبه\nوكم قعدة مني أقمت ببأسها … إلى الطعن مياد القنا في كعوبه\nولما ركبت الهول لم أرض دونه … ومن ركب الليث اعتلى عن نجيبه\nتريح علينا ثلة المجد شزب … تغالى وايد من قنا في صليبه\nوأبيض من عليا معد ، بنانه … مقاوم ريان الغرار خصيبه\nأخف إلى يوم الوغى من سنانه … وأمضى على هام العدى من قضيبه\nهل السيف الا منتصى من لحاظه … أو البدر الا طالع من جيوبه\nإذا سئل انهال الندى من بنانه … كما انهال أذيال النقا من كثيبه\nجواد اذا ما مزق الذود عضبه … أذاع الندى من جرده بعد نيبه\nيسير امام النجم عند طلوعه … ويهوي أمام النجم عند غروبه\nرضيت به في صدر يوم عجاجه … على شمسه عارية من سهوبه\nمضى يحرس الأقران بالطعن في الطلى … وقد لج نعاب القنا في نعيبه\nأنا ابن نبي الله وابن وصيه … فخار علا عن نده وضريبه\nتأدب مني رائع الخطب بعدما … تجلى سفيه الجد لي عن أديبه\nفو الله لا ألقى الزمان بذلة … ولوحط في فودي أمضى غروبه\nقنعت فعندي كل ملك نزوله … عن العز والعلياء مثل ركوبه\nوما اسفي الا على ما جلوته … على سمع منزور النوالب نضوبه\nإذا ما رآني قطع اللحظ طرفه … وعنون لي اطراقه عن قطوبه\nومن لم يكن حمدي نصيبا لبشره … جعلت ضروب الذم أدنى نصيبه\nولو أن عضبي ممكن ما ذممته … وكان مكان الذم ردع جيوبه\nوإن عناء الناظرين كليهما … إذا طمعا من بارق في خلوبه\nأعاب بشعري ، والذي أنا قائل … يقلقل جنبي عائب من معيبه\nوكل فتى يرنو إلى عيب غيره … سريعا وتعمى عينه عن عيوبه\nوما قولي الأشعار إلا ذريعة … إلى أمل قد آن قود جنبيه\nوإني إذا ما بلغ الله منيتي … ضمنت له هجر القريض وحوبه\nفهل عائبي قول عقدت بفضله … فخارى وحصنت العلى بضروبه\nسأترك هذا الدهر يرغو رغاؤه … وتصرف من غيظي بوادي نيوبه\nوأجعل عضبي دون وجهي وقاية … ليا من عندي ماؤه من نضوبه"},{"id":"diwan-radi:43","bookId":"diwan-radi","type":"poem","seq":43,"chapter":"البحر: منسرح","title":"كان قضاء الاله مكتوبا","page":"","text":"كان قضاء الاله مكتوبا … لولاك كان العزاء مغلوبا\nما بقيت كفك الصناع لنا … فكل كسر يكون مرؤوبا\nما احتسبت المرء قد يهون وما … أوجع ما لا يكون محسوبا\nنهضا بها صابرا ، فأنت لها … والثقل لا يعجز المصاعيبا\nفقد ارتك الاسى وان قدمت … عن يوسف كيف صبر يعقوبا\nطمعت ، يا دهر ، أن تروعه … ظنا على الرغم منك مكذوبا\nما يؤمن المرء بعد مسمعه … قرع الليالي له الظنابيبا\nتنذر إحداثها ويأمنها … ما آن ان يستريب من ريبا\nشل بنان الزمان كيف رمى … مسوما للسباق مجنوبا\nطرف رهان رماه ذو غرر … نال طلوبا ، وفات مطلوبا\nكان هلال الكمال منتظرا … وكان نوء العلاء مرقوبا\nوأعجمي الأصول تنصره … بداهة تفضح الأعاريبا\nمدت إليه الظبا قوائمها … تعجله ضاربا ومضروبا\nمرشحا للجياد يطلعها … على العدى ضمرا سراحيبا\nوللمباتير في وغى وقرى … يولغها الهام والعراقيبا\nذوى كما يذبل القضيب ، وكم … مأمول قوم يصير مندوبا\nصبرا فراعي البهام إن كثرت … لابد من أن يحاذر الذبيا\nوإن دنيا الفتى وإن نظرت … خميلة تنبت الاعاجيبا\nنسيغ أحداثها على مضض … ما جدح الدهر كان مشروبا\nإذا السنان الطرير دام لنا … فدعه يستبدل الانابيبا\nوهل يخون الطعان يوم وغى … إن نقص السمهري انبوبا\nما هيبة السيف بالغمود ، ولا … أهيب من أن تراه مسلوبا\nوالبدر ما ضره تفرده … ولا خبا نوره ولا عيبا\nوما افتراق الشبول عن أسد … بمانع أن يكون مرهوبا\nوالفحل إن وافقت طروقته … ابدل مكن منجب مناجيبا\nوالعنبر الورد إن عبثت به … مثلما زاد عرفه طيبا\nيطيح مستصغر الشرار عن الز … د ، ويبقى الضرام مشبوبا\nمحصت النار كل شائبة … وزاد لون النضار تهذيبا\nإن زال ظفر ، فأنت تخلفه … والليث لا يخلف المخاليبا\nبقدر عز الفتى رزيته … من وتر الدهر بات مرعوبا\nواللؤلؤ الرطب في قلائده … ما كان لولا الجلال مثقوبا\nإن كنت مستسقيا لمنجعة … مجلجلا بالقطار اسكوبا\nفاستسق مستغنيا به أبدا … من قطر جدوى أبيه شؤبوبا\nوانتفاع النبات صوحه … هيف الردى أن يكون مهضوبا\nفاسلم مليك الملوك ما بقي ال … هر مبقى لنا وموهوبا\nلا خاف أبناؤك الذين بقوا … حدا من النائبات مذروبا\nولا ترى السوء فيهم أبدا … حتى يكونوا الدوالف الشيبا\nلا روعت سرحك المنون ولا … أصبح سرب حميت منهوبا\nلا يجد الدهر مسلكا أبدا … ولا طريقا إليك ملحوبا\nولا راينا الخطوب داخلة … رواق مجد عليك مضروبا"},{"id":"diwan-radi:44","bookId":"diwan-radi","type":"poem","seq":44,"chapter":"البحر: متقارب تام","title":"كذا يهجم القدر الغالب","page":"","text":"كذا يهجم القدر الغالب … ولا يمنع الباب والحاجب\nتغلغل يصدع شمل العلى … كما ذعذع الابل الخارب\nوقد كان سد ثنايا العدو … فمن اين اوضع ذا الراكب\nوهابت جوانبه النائبات … زمانا ، وقد يقدم الهائب\nطواك إلى غيرك المعتفي … وجاوز ابوابك الراغب\nوهل نحن إلا مرامي السهام … يحفزها نابل دائب\nنسر إذا جازنا طائش … ونجزع إن مسنا صائب\nففي يومنا قدر لابد … وعند غد قدر واثب\nطرائد تطلبها النائبات … ولا بد أن يدرك الطالب\nارى المرء يفعل فعل الحد … د ، وهو غدا حمأ لازب\nعواري من سلب الهالكين … يمد يدا نحوها السالب\nلنا بالردى موعد صادق … ونيل المنى واعد كاذب\nنصبح بالكاس مجدوحة … ولا علم لي اينا الشارب\nحبائل لدهر مبثوثة … يرد إلى جذبها الهارب\nوكيف يجاوز غاياتنا … وقد بلغ المورد القارب\nلقد كان رأيك حل العقال … إذا طلع المعضل الكارب\nوقط كان عندك فرج المضيق … إذا عض بالقتب الغارب\nيفيء اليك من القاصيات … مراح المناقب والعازب\nفيوم النهى مشرق شامس … ويوم الندى ماطر ساكب\nفاين الفيالق مجرورة … وقد عضل اللقم اللاحب\nواين القنا كبنان الهلوك … بماء الطلى أبدا خاضب\nكأن السوابق من تحتها … دبى طائر ، أو قطا سارب\nلها قسطل كنسيج السدوس … بهام الربى أبدا عاصب\nوملبونة في بيوت الغزي … يقدم إغباقها الحالب\nنزائع لاشوطها في المغار … قريب ولا غزوها حائب\nفسرج وغى ما له واضع … وجيش علي ما له غالب\nوكنت العميد لها والعماد … فضاع الحمى ووهى الجانب\nفماذا يشيد هتاف النعي … فيك ، وما يندب النادب\nامدت عليك القلوب العيون … فليس يرى مدمع ناضب\nارى الناس بعدك في حيرة … فذو لبهم حاضر غائب\nكما اختبط الركب جنح الظلام … وقد غور القمر الغارب\nولما سبقت عيوب الرجال … تعلل من بعدك العائب\nولم أر يوما كيوم به … خبا مثقب ، وهوى ثاقب\nتلوم الضواحك فيك البكاة … ويعجب للباسم القاطب\nسقاك وان كنت في شاغل … عن الري ، داني الندى صائب\nمرب اذا مخضته الجنوب … أبست به شمأل لاغب\nيجر ثقائل أردافه … كما بادر القرة الحاطب\nكسوق البطيء بسوط السريع … ينوء ويعجله الضارب\nيصيبك بالقطر شفانه … كما قرع الجمرة الحاصب\nولولا قوام الورى أصبحت … يرن على صدعها الشاعب\nوباتت وقد ضل عنها الرعاء … محفلة ما لها حالب\nوساق العدو أضاميمها … وما آب من طردها آيب\nوما بقي الجبل المشمخر … فما ضرنا الجبل الواجب\nوما ينقص الثلم في المضربين … إذا اهتز في القائم القاضب\nبمثل بقائك غيث الأنا … م يرضى عن الزمن العاتب\nلهان علينا ذهاب الرديف … ما بقي الظهر والراكب"},{"id":"diwan-radi:45","bookId":"diwan-radi","type":"poem","seq":45,"chapter":"البحر: طويل","title":"من اي الثنايا طالعتنا النوائب","page":"","text":"من اي الثنايا طالعتنا النوائب … واي حمى منا رعته المصائب\nخطون إلينا الخيل والبيض والقنا … فما منعت عنا القنا والقواضب\nوضل بنا قصد الطريق كانما … تؤم المنايا لا النجاء الركائب\nنروغ كما راغ الطرائد دونها … وتجلبنا عودا اليها الجوالب\nطوال رماح لا تقي ، وعقائل … من الجرد لا ينجو عليهن هارب\nفاين النفوس الآبيات مليحة … من الضيم والأيدي الطوال الغوالب\nواين الطعان الشزر يثنى بمثله … رقاب الأعادي دوننا والكتائب\nاذا لم يعنك الله يوما بنصرة … فاكبر اعوان عليك الاقارب\nوإن هو لم يعصمك منه بجنة … فقد اكتبت للضاربين المضارب\nتناهى بنا الآجال عن كل مدة … وما تنتهي بالطالبين المطالب\nنغر بإيعاد الردى ، وهو صادق … ونطمع في وعد المنى ، وهو كاذب\nأفي كل يوم لي صديق مصادق … يجيب المنايا ، أو قريب مقارب\nلعمري ، لقد أبقى علي بيومه … لواعج تمليها علي العواقب\nرماه الردى عن قوسه فاصابه … ولم يغننا ان درعتنا التجارب\nهو الوالج العادي الذي لا يروعه … من الباب بواب عليه وحاجب\nولا ناصر ، سيان من هو حاضر … إذا ما دعا منا ، ومن هو غائب\nنسير وللآجال فوق رؤوسنا … ومنه وراء الترب أبيض قاضب\nوما يعلم الانسان في اي جانب … من الارض يأوي منه في الترب جانب\nمصاب رمى من هاشم في صميمها … فأمست ذراها خشعا والغوارب\nوأطلق من وجد حباها ، ولم تكن … لهاشم لولاه العقول العوازب\nوزالت له الاقدام عن مستقرها … كما مال للبرك المطي اللواغب\nأطال به الشبان لطم خدودهم … وصك له غر الوجوه الاشايب\nيعضون منه بالأكف ، وإنما … تعض بأطراف البنان العجائب\nمضى املس الاثواب لم يخز مادح … بإطنابه فيه ، ولم يزر عائب\nوخلى فجاجا لا تسد بمثله … وتلك صدوع أعوزتها الشواعب\nلقد هز أحشاء البعيد مصابه … فكيف المداني والقريب المصاقب\nولم أنسه غاد ، وقد أحدقت به … أدان تروي نعشه وأقارب\nيحسون من أعواده ثقل وطئه … وما أثقل الأعناق إلا المناقب\nكأنا عرضنا زاعبيا مثقفا … على نعشه قد جربته المقانب\nتعاقد حاثو تربه أي نجدة … وهل ذاك مغن ، والمنايا الجواذب\nوقارعني دهري عليه ، فحازه … ألا إن أقران الليالي غوالب\nوكنت به ألقى الحروب ، وأتقي … فجاء من الاقدار ما لا احارب\nتعاقد حاثوا تربة اي نجدة … تلاقت عليها بالتراب الرواجب\nكأنهم أدلوا إلى القبر ضيغما … ينوء وتثنيه الاكف الحواصب\nواي حسام اغمدوا في ضريحه … كهمك لا يعصى به اليوم ضارب\nفآثاره محمرة في عدوه … ومنه الترب ابيض قاضب\nوما كان الا برهة ثم اسفرت … نزوعا عن الوجد الوجوه الشواحب\nوجفت عيون الباكيات وأنسيت … من الغد ما كانت تقول النوادب\nتسلوا ، ولولا اليأس ما كنت ساليا … وقد يصبر العطشان والورد ناضب\nألسنا بني الأعمام دنيا ، تمازجت … باخلاقهم اخلاقنا والضرائب\nجميعا نمانا في ربى المجد هاشم … وأنجب عرقينا لؤي وغالب\nإذا عمموا بالمجد لاثت بهامنا … عمائمهم اعراقنا والمناسب\nنرى الشم من انافنا في وجوههم … وأعناقنا طالت بهن المناصب\nوكم داخل ما بيننا بنميمة … تقطر لما زاحمته المصاعب\nسوى هبوات شابت الود بيننا … واي وداد لم تشبه الشوائب\nلنا الدوحة العليا التي نزعت لها … إلى المجد أغصان الجدود الأطايب\nاذا كان في جو السماء عروقها … فاين اعاليها واين الذوائب\nعلونا الى اثباجها ولغيرنا … عن المنكب العالي ، إذا رام ناكب\nفما حمل الآباء منا ، وساقطت … الى الارض منا المنجبات النجائب\nسيوف على الاعداء تمضي نفوسها … ولم تتبد لهن ايد ضوارب\nفان تر فينا صولة عجرفية … فقد عرفت فينا الجدود الاعارب\nفصبرا جميلا انما هي نومة … وتلحقنا بالاولين النوائب\nوليس لمن لم يمنع الله مانع … ولا لقضاء الله في الارض غالب\nولو رد ميتا وجد ذي الوجد بعده … لردك وجدي والدموع السوارب\nسيعطي رجال ما منعت ويشتفي … من الاقرباء الابعدون الاجانب\nلنا فيك عند الدهر ثار هزيعه … واني لثارات المقادير طالب\nأدرت عليك الساريات ورقرقت … على ذلك القبر الرياح الغرائب\nولا زال عن ذاك الضريح منور … من الروض تفليه الصبا والجنائب\nولا ، بل سقيناك الدموع ، وإننا … لنأنف ان قلنا سقتك السحائب"},{"id":"diwan-radi:46","bookId":"diwan-radi","type":"poem","seq":46,"chapter":"البحر: طويل","title":"لنا كل يوم رنة خلف ذاهب","page":"","text":"لنا كل يوم رنة خلف ذاهب … ومستهلك بين النوى والنوادب\nوقلعة اخوان كانا وراهم … نرامق أعجاز النجوم الغوارب\nنوادع احداث الليالي على شقى … من الحرب لو سالمن من لم يحارب\nونأمل من وعد المنى غير صادق … ونأمن من وعد الردى غير كاذب\nوما الناس إلا دارع مثل حاسر … يصاب ، وإلا داجن مثل سارب\nالى كم نمنى بالغرور وننثني … بأعناقنا للمطمعات الكواذب\nوهل ينفع المغرور قرب للنوى … تلوم مغرور بأرجاء جاذب\nلززنا من الدهر الخؤون بمصدم … يحطم اشلاء القرين المجاذب\nهو القدر المجلوب من حيث لا يرى … وأعيا علينا رد تلك الجوالب\nنراع إذا ما شيك أخمص بعضنا … وأقدامنا ما بين شوك العقارب\nونمسي بامال الدنيا سمام لطاعم … وخوف لمطلوب ، وهم لطالب\nتصدى لنا قرب الموامق ذي الهوى … ويختلنا كيد العدو المجانب\nوإنا لنهواها على الغدر والقلى … ونمدحها مع علمنا بالمعائب\nوحسبي من ضراء دهري انني … أقيم الأعادي لي مقام الحبائب\nألم يأن يا للناس هبة نائم … رأى سيرة الايام اوجد لاعب\nحدت بعصاها لآل ساسان والتوت … يداها بآل المنذرين الأشاهب\nوحلت على اطلال عاد وحمير … سنابكها حل الجياد اللواغب\nنزلن قباب المنذر بن محرق … واندية الشم الطوال بمارب\nنبا ببني العنقاء ناب وقعقعت … عماد بني الريان احدى الشواعب\nفقادتهم قود الايانق في البرى … وزمتهم زم القروم المصاعب\nأهبت عليهم قاصفا من رياحها … فطاروا كما ولى جفاء المذانب\nمسير مع الأقدار ما فيه ونية … ولا وقعة بعد اللغوب لراكب\nومن كانت الأيام ظهرا لرحله … فيا قرب ما بين المدى والركائب\nومن اصبح المقدار حادي مطيه … أجد بلا رزء ، ولا سوط ضارب\nعلى مثلها يدمي الحليم بنانه … عضاضا على أيدي المنايا السوالب\nعلى أي خلق آمن الدهر بعدما … تباعد ما بيني وبين الأقارب\nسنان على ، عزي ، قناتي ، ومضرب … من المجد مستثنى به من مضاربي\nولما طوى طي البرود واقبلوا … يهادونه بين الطلى والمناكب\nصبرت عليه اطلب النصر برهة … من الدهر ثم انقدت طوع الجواذب\nتقطعت الأسباب بيني وبينه … فلم تبق الا علقة للمناسب\nلئن لم نطل لدم الترائب لوعة … فان لنا لدما وراء الترائب\nيتم تمام الرمح زادت كعوبه … وتهتز للحمد اهتزتاز القواضب\nبمطرورة الأنياب عوج المخالب … ولا الريق في كر الرزايا بناضب\nيداهي ضباب القاع وهو كانه … من اللين غمر غير جم المذاهب\nإذا طبع الآراء ماطل غربها … فلم يمضها الا باذن العواقب\nمن القوم حلوا في المكارم والعلى … بملتف أعياص الفروع الأطايب\nاقاموا بمستن البطاح ومجدهم … مكان النواصي من لؤي بن غالب\nبهاليل ازوال تعاج اليهم … صدور القوافي أو صدور النجائب\nعظام المقاري يمطرون نوالهم … بايدي مساميح سباط الرواجب\nإذا طلبوا الأعداء كانوا نغيضة … ليوم الوغى من قبل جر الكتائب\nوباتوا مبيت الأسد تلتمس القرى … بمطورة الانياب عوج المخالب\nواضحوا على الاعواد تسمو لحاظهم … كلمح القطاميات فوق لمراقب\nفماشئت من داع إلى الله مسمع … ومن ناصر للحق ماضي الضرائب\nهم استخدموا الاملاك عزا وارهفوا … بصائرهم بعد الردى والمعاطب\nوهم أنزلوهم بعدما امتد غيهم … جماما على حكم من الدين واجب\nتساموا إلى العز الممنع ، وارتقوا … من المجد أنشاز الذرى والغوارب\nعلى ارث مجد الاولين تعلقوا … ذوائب اعناق العلى والمناصب\nبحيث ابتنت أم النجوم منارها … وأوفت ربايا الطالعات الثواقب\nلهم ورق من عهد عاد وتبع … حديد الظبى إلا انثلام المضارب\nفضالات ما ابقى الكلاب وطخفة … وما أسأر الابطال يوم الذنائب\nبهن فلول من وريدي عتيبة … ونضخ نجيع من ذؤاب بن قارب\nتقلقل في الأغماد هزلا ، وخطبها … جسيم إذا جربن بعض التجارب\nغدوا الى هدم الكواهل والطلى … وعود إلى حذف الذرى والعراقب\nلتبك قبور افرغ الموت تحتها … سجال العطايا بعدهم والرغائب\nوطاب ثراها ، والثرى غير طيب … وذاب نداها ، والندى غير ذائب\nكأن اليماني ذا العياب بأرضها … يقلب من دارين ما في الحقائب\nاذا اجتاز ركب كان اجود عندها … بعقر المطايا من سحيم وغالب\nافي كل يوم يعرق الدهر اعظمي … وينهس لحمي جانبا بعد جانب\nفيوما رزايا في صديق مصادق … ويوما رزايا في قريب مقارب\nفكم فل مني ساعدا بعد ساعد … وكم جب مني غاربا بعد غارب\nوفادحة يستهزم الصبر باسمها … وتظمى إلى ماء الدموع السواكب\nصبرنا لها صبر المناكب حسبة … إذا اضطرت الناس اضطراب الذوائب\nتعاصي أنابيب الحلوم جلادة … وتعهفوا يراعات العقول العوازب\nكظوما على مثل الجوائف اتعبت … نطاسيها من قارف بعد جالب\nتحل الرزايا بالرجال وتنجلي … ورب مصاب ينجلي عن مصائب\nمن اليوم يستدعي منازلك البكا … إذا ما طوى الأبواب مر المواكب\nوتضحك عنك الأرض أنسا وغبطة … وتبكيك أخدان العلى والمناقب\nسقاك الحيا إن كان يرضي لك الحيا … بغر الاعالي مظلمات الجوانب\nتمد بارداف ثقال وترتمي … على عجرفيات الصبا والجنايب\nكأن لواء يزد حمن وراءه … إذا اختلج البرق ازدحام المقانب\nبودق كاخلاق العشار استفاضها … تداعي رغاء من مبس وحالب\nيقر بعيني ان تطيل مواقفا … عليك مجر المدجنات الهواضب\nوإن ترقم الأنواء تربك بعدها … بكل جديد النور رقم الكواكب\nذكرتكم ، والعين غير محيلة … فانبطت غدران الدموع السواكب\nوما جالت الألحاظ إلا بقاطر … ولا امتدت الأنفاس إلا بحاصب\nوهل نافعي ذكر الأخلاء بعده … جرى بيننا مور النقا والسباسب"},{"id":"diwan-radi:47","bookId":"diwan-radi","type":"poem","seq":47,"chapter":"البحر: منسرح","title":"اي دموع عليك لم تصب","page":"","text":"اي دموع عليك لم تصب … واي قلب عليك لم يجب\nخبت إليك الخطوب معجلة … ضروب شد الجياد والخبب\nواعجبي للزمان كيف نبا … واعجب ان اقول واعجبي\nمالي وما وبللخطوب تسلبني … في كل يوم غرائب السلب\nاما فتى ناضر الصبا كاخي … عندي أو زائد المدى كابي\nوإنني للشقاء أحسبني … ألعب بالدهر ، وهو يلعب بي\nما نمت عنه الا وايقظني … من الرزايا بفيلق لجب\nولم أزعه ، إلا وأعقبني … سطوا كوقع الظبي على اليلب\nفي كل دار تعدوا المنون ومن … كل الثنايا مطالع النوب\nبفوز بالراحة الفقيد وللف … فاقد طول العناء والتعب\nيطيب نفسا عنا وواحدنا … إن طيب القلب عنه لم يطب\nاحمدكم لي عليك من كمد … باق ومن جود ادمع سرب\nولوعة تحطم الضلوع اذا … ذكرت قرباللقاء عن كثب\nإن قطع الموت بيننا ، فلقد … عشنا وما حبلنا بمنقضب\nكم مجلس صبحته السننا … تفض فيه لطائم الادب\nمن أثر يونق الفتى حسن … او خبر يبسط المنى عجب\nاو غرض اصبحت خواطرنا … تساقط الدر منه في الكتب\nكالبارد العذب روقته صبا ال … الظلم زين بالشنب\nغاض غدير الكلام ما بقي ال … دهر وقرت شقاشق الخطب\nيا علم المجد لم هويت وقد … كنت أمين العماد والطنب\nيا مقول الدهر لم صمت وقد … كنت زمانا أمضى من القضب\nيا ناظر الفضل لم غضضت وما … كنت قديما تغضي على الريب\nكنت قريني ولست من لدتي … كنت نسيبي ولست من نسبي\nمما يقوي العزاء عنك ، وإن … شرد قلبي العزاء بالكرب\nأنك أحرزتها ، وإن رغم ال … دهر ، ثمانين طلقة الحقب\nفان دموعي جرين نهنها … علمي بان قد ظفرت بالارب\nفليت عشرين بت أحسبها … باعدن بين الورود والقرب\nاني اظمى الى المشيب ومن … ينج قليلا من الردى يشب\nوإن يزر طالع البياض أقل … يا ليت ليل الشباب لم يغب\nمر على ذلك التراب من الم … زن خفوق الاعلام والعذب\nكالعير ذات الأوساق صاح بها … معتسف بالايانق النجب\nاذا خبا برقه استعان على … ايقاده بالمجلجل اللجب\nلترتوي ثم أعظم نزلت … داجي الدماميم موحش الحدب\nبحيث تزوى عن النسيم … تدرج عنا مطالع الشهب\nفثم بشر اصفى من الغدق ال … عذب وجود أندى من السحب\nواجبل كان يستذم به … من الليالي فساخ في الترب\nلا تحسبن الخلود بعدك لي … إن المنايا أعدى من الجرب\nإن انج منها وقد شربت بها … فان خيل المنون في طلبي"},{"id":"diwan-radi:48","bookId":"diwan-radi","type":"poem","seq":48,"chapter":"البحر: رجز تام","title":"لا لوم للدهر ولا عنابا","page":"","text":"لا لوم للدهر ولا عنابا … تغاب ان الجلد من تغابا\nصبرا على الضراء واحتسابا … اصبرنا اعظمنا ثوابا\nما الدمع مما يزع المصابا … ولا يرد القدر الغلابا\nأمضى الزمان حكمه غلابا … اصابنا وطال ما اصابا\nيولغ ظفرا للردى ونابا … لا يبكين حاضرنا من غابا\nما غاب منا غائب فأبا … ورب حي دعموا القبابا\nواستفسحوا الأعطان والرحابا … وطبقوا السهول والعقابا\nلا يرهبون للعدى ذبابا … أمسوا لقاحا ، وغدوا نهابا\nجر على دارهم ذنابا … واتبع القوادم الذنابا\nبمعجل ينتزع الأطنابا … يوطي الحمى ويهتك الحجابا\nكالباترات تبذر الرقابا … نسعى ، ويطوينا الردى وثابا\nكنم قطع الاقران والاسبابا … وفرق الجيران والاحبابا\nواستدرج العبيد والأربابا … سيل ردى قد ملأ الشعابا\nوجن موجا وطغى عبابا … قارعنا وانتزع اللبابا\nاعجب واخلق ان ترى عجابا … يبلد الافهام والالبابا\nإن الردى وإن رمى فصابا … وجاذبتنا يده جذابا\nيعجم من عيداننا صلابا … صعبا يلاقي انفسا صعابا\nلا تنكر الموت لها شرابا … ولا تعاف الصبر المذابا\nسوالب ومرة اسلابا … إذا أنا انقدت ولما آبى\nمنجفلا مع الردى منجابا … فلم سننت الصارم القرضابا\nولم ربطت الشرب العرابا … يمرين بالشكائم اللعابا\nخمايصا تحاضر الذيابا … يحملن اسدا في الوغى غضابا\nقد سلبوا السوابغ العيابا … ركبا وطورا للقنا ركابا\nيحمي الحمى ويمنع الجنابا … حتى إذا داعي الردى أهابا\nاسقط من ايماننا الكعابا … وبزنا أرواحنا إغصابا\nلا طعن تسطيع ولا ضرابا … مقتحم على الأسود الغابا\nورب إخوان مضوا شبابا … تلاحقوا الى الردى صحابا\nلا نترجى منهم ايابا … ولا نعد لهم الا حقابا\nلا يحفل الحجاب والابوابا … اذا دعوا لم يرجعوا جوابا\nولبسوا الجندل والظرابا … لقدر ما عمروا الخرابا\nيا غصنا طال وفرعا طابا … لما ذوى اودغته الترابا\nأراب من يومك ما أرابا … لا زلت أستسقي لك السحابا\nكل اغر يدق الذهابا … مجررا على الربى أهدابا\nيبقي بأجواز الثرى أندابا … وينثني مجولا جوابا\nوإن لبست للبلى جلبابا … ارى البكاء سفها وعابا\nلا تجعلنه ديدنا ودابا … وافق منا اجل كتابا"},{"id":"diwan-radi:49","bookId":"diwan-radi","type":"poem","seq":49,"chapter":"البحر: طويل","title":"لأظما معلينا وأروى المصائبا","page":"","text":"لأظما معلينا وأروى المصائبا … وأسخط آمالا وأرضى نوائبا\nمصاب نجوم المجد فيه نواجم … تركن نجوم الصبر عنه غواربا\nاصابت سهام الحادثات قلوبها … فكم اعقبت روعا يروع العواقبا\nلقد وعدتنا ، إذ رغبنا رغايبا … فلما أصبن الظن أعطت مصايبا\nوأرضعن أفواه المطامع فجعة … فطمن بها عند النجاح المطالبا\nبمفقودة ينهل ماء مصابها … دموعا على خد الزمان سواكبا\nإذا قعدت أحزانها في قلوبنا … أقمنا على الصبر الشفاه نوادبا\nصبرنا فغصصنا الزمان بريقه … على ان للايام فينا مضاربا\nولم نطرح الاسلاب يوما لنكبة … وإن جذب المقدار منا المجاذبا\nألا إن هذا الثاكل الحسب الذي … به ثكل المجد التليد المناقبا\nرمى في يمين الدهر درة سؤدد … فأحج بها يحنو عليها الرواجبا\nوقد شن فيها حادث الموت غارة … ثنتنا ولم تطلع إلينا كتائبا\nفلا تحسبن رزء الصغائر هينا … فإن وجى الأخفاف ينضي الغواربا\nسقى الله حصباء الثرى كل ليلة … سحائب ينزعن الرياح الحواصبا\nجنادل من قبر كأن صدورها … حباه الحيادون القبور محاربا\nاقامت به حتى لودت عيوننا … ولم تبق دمعا ان يكون سحائبا\nتراب يرى ان النجوم ترابه … ويحسب أحجار الصفيح الكواكبا\nوسيف نضي من جفنه ، غير أنه … رضي لحده من غمده الدهر صاحبا\nيغطي الثرى عنا وجوها مضيئة … كما كفر الغيم النجوم الثواقبا\nورزء رمى صدر الأماني بيأسها … وكن الى ورد المعالي قواربا\nألا رب ليل قلقلته عزائمي … إلى أن نضا عن منكبيه الغياهبا\nجذبت بضبع العزم من بين اضلعي … وزاحمت بالهم الدجى والسباسبا\nوجردا ضربن الدهر في أم رأسه … وجزن بنا أعجازه والمناكبا\nومرت حواميها على لمة الدجى … تجاذب بالادلاج منها الذوائبا\nواني لمن قوم اذا ركبوا الندى … الى الحمد باتوا يعسفون الركائبا\nإذا فاض رقراق المحامد صيروا … له جودهم دون اللئام نصائبا\nوإن ضاق صدر الخطب وسع بأسهم … لسمر القنا بين الضلوع مذاهبا\nبطعن كدفاع الغمام تحته … ذوابل يمطرن الدماء صوائبا\nله شرر يرمي الرماح بلفحه … يكاد يرى ماء الأسنة ذائبا\nإذا أنكروا في النقع ألوان خيلهم … أضاء لهم حتى يشيموا السبائبا\nأبا قاسم جاءت إليك قلائد … تقلد اعناق الكرام مناقبا\nقلائد من نظمي يود لحسنها … قلوب الأعادي أن تكون ترائبا\nاذا هدها راوي القريض حسبته … يقوم بها في ندوة الحي خاطبا\nفلو كن غدرانا لكن مشاربا … ولو كن احداثا لكن تجاربا"},{"id":"diwan-radi:50","bookId":"diwan-radi","type":"poem","seq":50,"chapter":"البحر: مجتث","title":"يا دين قلبك من با","page":"","text":"يا دين قلبك من با … رق ينير ويحبو\nعلى شريقي نجد … مرعى لعينك جدب\nكما تليح ذراع … فيها من النضر قلب\nكأنه نار عليا … اء للضيوف تشب\nأو ساطعات أراها … والليلداج ازب\nمراوح بيديه على … على الزناد مكب\nاو ام مثوى يلنجوج … هاعلى النار رطب\nالغور منه معان … وعاقل والهضب\nله حفيف رعاد … يراع منه السرب\nوبارقات كما … ت العجاج القضب\nاما ترى البرق يبدو … إلا لعينك غرب\nوللزفير هباب … بين الضلوع وهب\nيضيء بالطف قبرا … فيه الاعز الاحب\nيهمي السنان ، ويس … لا بل من القلب خلب\nما كنت احسب يوما … والدهر ضرب وضرب\nأني أبيت وبيني … وبين لقياك سهب\nوان تطارد مابينن … ننا زعازع نكب\nبحيث يرتع أدم … من الجوازي ، وحقب\nوكيف يكرع مستورد … رد القطا ويعب\nيا دار قومي أين الأ … بربعك لبوا\nمصاعب حطمتهم … ايدي المنون فخبوا\nيسوقهم للمقادي … ر سائق متلئب\nمقحم للجراثيم إن … ونوا ، أو أغبوا\nكانوا السيوف إذا عا … ينوا المقاتل هبوا\nوالزاغبيات إن أش … رعوا عن الدار ذبوا\nمنازل كان فيها … للقوم امن ورعب\nتكد فيها الأنابي … والرباجط القب\nرأي يغب لحزم … ونائل لا يغب\nينقاد فيكل يوم … منا الابي الصعب\nيجذ أصل وريق ال … ويدرج عقب\nلا مبغض القوم يبقى … ولا المجل المحب\nسواء الملس في غا … رة الردى والجرب\nيجري القضاء ويمضي … الطبيب والمستطيب\nكم ذا الامان … \nوبالزيال لغربا … نها شحيج ونعب\nيغر سلم الليالي … والسلم منهن حرب\nلنا من الدهر ربض … على وعيد ووثب\nيوما غرور ويوما … عدو علينا وشغب\nينحو المضيق ، وقد أع … الطريق اللحب\nأأخر اللعب جد … ام اخر الجد لعب\nشقيقتي ان خطبا … عدا عليك لخطب\nوان رزأ رماني … بالبعد عنك لصعب\nسهم اضصابك منه … للقدر فوق وغرب\nلا النصل منه بباب … يوما ولا الريش لغب\nيبيت بعدك في … جعي الجوى والكرب\nكما يبيت رميض … بعد السنام الاجب\nاني على قضض … م يطمئن الجنب\nلو رد عنك المنايا ال … ال طعن وضرب\nلخاض فيها سنان … ماض وطبق عضب\nوقام دون الردى … غلظ السواعد غلب\nوناقلت بالعوالي ذؤب … ذؤبان ليل تخب\nقضيت نحبا قضى بع … ده من المجد نحب\nولم يكن لك إلا … من المقادير خطب\nودون كل حجاب … من العفافة حجب\nوقبرك الصون من قب … ان يضمك ترب\nكانني كل يوم … قلبي اليك اصب\nكم ذا الأمان وللنا … قرح عاد قلبي ندب\nيكل واقع طرفي … عمن سواك وينبو\nأجل قبرك عن أن … أقول حياه ركب\nاو ان اقول سقاه … صوب الغمام المرب\nالا لحاجة نفس … تهفو اليك وتصبو\nاو ان يبل غليل … ان بل قبرك شرب\nوكيف يظمأ قبر … فيه الزلال العذب\nأم كيف تظلم أرض … أجن فيها الشهب\nنوارها المجد لا … وة الربى والعرب\nجاورت جارا تلقا … ك منه برور حب\nشعب غدا ، وهو لل … هوالملائك شعب\nيا نومة ثم منها … الى الجنان المهب\nإن كان للشخص بعد … فللعلائق قرب\nأغبه ، وبرغمي … إن الزيارة غب\nلئن خلا منك طرف … لقد ملي منك قلب\nوان غربت فلطا … لعات شرق وغرب\nخلاك ذم وذم … للدهر فيك وقصب\nولم يزل بعد يومي … مني على الدهر عتب\nفكم ابيت وعندي … لذي المقادير ذنب"},{"id":"diwan-radi:51","bookId":"diwan-radi","type":"poem","seq":51,"chapter":"البحر: متقارب تام","title":"اودع في كل يوم حبيبا","page":"","text":"اودع في كل يوم حبيبا … وأهدي إلى الأرض شخصا غريبا\nوارجع عنه جميل العزاء … أمسح عن ناظري الغروبا\nكأني لم أدر أن السبي … ل سبيلي ، وأني ملاق شعوبا\nوأن ورائي سوقا عنيفا … وأن أمامي يوما عصيبا\nولا انني بعد طول البقاء … اصاب كما ان غيري اصيبا\nاماني اوضع في غيها … لريح الغرور بها مستطيبا\nتذكر عواقب موبي النبات … ولا تتبع العين مرعى خصيبا\nقعدت بمدرجة النائبات … يمر الزمان علي الخطوبا\nعلى الهم أنفق شرخ الشباب … وأعطي المنايا حبيبا حبيبا\nتصاممت عن هتفات المنون … بغيري ولا بد من أن أجيبا\nواعلم اني ملاقي التي … شعبن قبائلنا والشعوبا\nألا إن قومي لورد الحمام … مضوا امما واجابوا المهيبا\nبمن أتسلى وأيدي المنون … تخالس فرعي قضيبا قضيبا\nنزعن قوادم ريش الجناح … وأثبتن في كل عضو ندوبا\nنجوم ، إذا شهدوا الأنديات … رجوم اذا ما اقاموا الحروبا\nإذا عقدوا للعطاء الحبى … وان زعزعوا للطعان الكعوبا\nعراعر لا ينطقون الخنا … ولا يحفظون الكلام المعيبا\nيرم الفتى منهم جهده … فإن قال قال بليغا خطيبا\nجلابيب لا تضمر الفاحشات … وأردية لا تضم العيوبا\nوبشر يهاب على حسنه … فتحسبه غضبا أو قطوبا\nلقد أرزمت إبلي بعدكم … وأبدى لها كل مرعى جدوبا\nنزعت أزمتها للمقام … واعفيت منها الذرى والجنوبا\nلمن اطلب المال من بعدكم … واحفى الحصان وانضى الجنيبا\nحوامي جبال رعاها الحمام … فسوى بهن الثرى والجنوبا\nوكم واضح منكم كالهلال … ل هالت يداي عليه الكثيبا\nونازعني الموت من شخصه … سنانا طريرا وعضبا مهيبا\nوحلما رزينا وأنفا حميا … وعزما جريا ورايا مصيبا\nصوارم اغمدتها في الصعيد … وفللت منها الظبا والغروبا\nأقول لركب خفاف المزاد … وقد بدلوا بالوضاء الشحوبا\nالموا باجواز تلك القبور … فعروا الجياد وجزوا السبيبا\nقفوا فامطروا كل عين دما … بها واملؤا كل قلب وجيبا\nولا تعقروا غير حب القلوب … ب ، إذا عقر الناس بزلا ونيبا\nوإني على أن رماني الزمان … واعقب بالقلب جرحا رغيبا\nلتعجم مني ضروس الخطو … ب قلبا جليدا وعودا صليبا\nوابقى العواجم من صعدتي … عشوزنة تستقل النيوبا\nأخلاء ! لا زال جم البروق … أجش الرعود يطيع الجنوبا\nإذا ما مطاياه جبن الفلا … انمنا عليها الوجا واللغوبا\nيشق الزاد على تربكم … ويمري على كل قبر ذنوبا\nوأسأل أين مصاب الغمام … شروقا ، إذا ما غدا ، أو غروبا\nأضن على القطر أن يستهل … على غير اجداثكم أو يصوبا\nغلبت عليكم فيا صفقة … غبنت بها العيش غصنا رطيبا\nفلولا الحياء لعط القلوب … عليكم عصائب عطوا الجيوبا\nولم يك قدر الرزايا بكم … جنانا مروعا ودمعا سكوبا\nوإن ضرايحكم في الصعيد … لتكسو الخبيث من الارض طيبا\nوهبنا لفيض الدموع الخدود … عليكم ، وحر الغرام القلوبا\nلقد شغلتني المراثي لكم … بوجدي عن ان اقول النسيبا\nوكنت أعد ذنوب الزمان … فبعدكم لا أعد الذنوبا\nأراب الردى فيكم جاهدا … وزاد ، فجاز مدى أن يريبا\nأأنشد من قد اضل الحمام … عناء لعمرك اعيا الطبيبا"},{"id":"diwan-radi:52","bookId":"diwan-radi","type":"poem","seq":52,"chapter":"البحر: مجزوء الكامل","title":"لو كان يعتبني الحمام","page":"","text":"لو كان يعتبني الحمام … م لطال بعد اليوم عتبي\nإني وما عاتبته … إلا وأعتبني بذنبي\nصبرا أخي ، فإنها … تمضى ولو وقعت بهضب\nهون عليك ، فقد يكو … ن الصعب عندك غير صعب\nوانهض فما حملت على … قصف الفقار ولا اجب\nكنت الطبيب لمثلها … لو يتقى قدر بطب\nولئن رمى رامي الردى … غرضا ، فزعزع غير سربي\nفلقد اصاب بسهمه … الغرضين من عيني وقلبي"},{"id":"diwan-radi:53","bookId":"diwan-radi","type":"poem","seq":53,"chapter":"البحر: منسرح","title":"اذهب ولا تبعدن من رجل !","page":"","text":"اذهب ولا تبعدن من رجل ! … إن كرام الرجال قد ذهبوا\nأدركت فوق الذي طلبت ندى … غمرا وفات اللئام ما طلبوا\nلا يخلف الدهر ما تجود به … ولا يعير الرجال ما تهب\nعرض نقي من الوصوم ، إذا … احك عرض المذمم الجرب\nمضى التليد الأعلى لطيبه … واستأخر المنسمان والذنب\nترعية طاعت الصعاب له … واستوسقت في زمامه العرب\nيا دهر رشقا بكل نائبة … قد انتهى العتب وانقضى العجب\nرد يدي ما استطعت عن أربي … لم يبق لي بعد موتهم أرب"},{"id":"diwan-radi:54","bookId":"diwan-radi","type":"poem","seq":54,"chapter":"البحر: طويل","title":"على اي غرس امن الدهر بعد ما","page":"","text":"على اي غرس امن الدهر بعد ما … رمى فادح الايام في الغصن الرطب\nذوى قبل أن تذوي الغصون ، وعهده … قريب بأيام الربيلة والخصب\nكفى أسفا للقلب ما عشت أنني … بكفي على غيني حثوت من الترب\nجرت خطرة مكنها وفي القلب عطشة … رفعت لها راسي عن البارد العذب\nوقلت لجفني رد دمعا على دم … وللقلب عالج قرح ندب على ندب\nومما يطيب النفس بعدك انني … على قرب من ماء وردك أو قرب\nالا لا جوى مس الفؤاد كذا الجوى … ولا ذنب عندي للزمان كذا الذنب\nخلا منك طرفي وامتلا منك خاطري … كانك من عيني نقلت الى قلبي"},{"id":"diwan-radi:55","bookId":"diwan-radi","type":"poem","seq":55,"chapter":"البحر: مجزوء الكامل","title":"ما للهموم كأنها","page":"","text":"ما للهموم كأنها … نار على قلبي تشب\nوالدمع لا يرقا له … غرب كأن العين غرب\nلوداع اخوان الشباب … ب مضت مطاياهم تخب\nفارقتهم ، والعين عي … ن بعدهم ، والقلب قلب\nما كنت احسب انني … جلد على الارزاء صعب\nاو انني ابقى وظه … ري بعد أقراني أجب\nلا الوجد منقطع الوقود … د ولا مزار الدمع غب\nما اخطأتك النائبا … ت اذا اصابت من تحب"},{"id":"diwan-radi:56","bookId":"diwan-radi","type":"poem","seq":56,"chapter":"البحر: طويل","title":"أقول ، وقد أرسلت أول نظرة","page":"","text":"أقول ، وقد أرسلت أول نظرة … ولم أر من أهوى قريبا إلى جنبي\nلئن كنت أخليت المكان الذي أرى … فهيهات أن يخلو مكانك من قلبي\nوكنت أظن الشوق للبعد وحده … ولم ادر ان الشوق للبعد والقرب\nخلا منك قلبي وامتلا منك خاطري … كانك من عيني نمقلت الى قلبي"},{"id":"diwan-radi:57","bookId":"diwan-radi","type":"poem","seq":57,"chapter":"البحر: طويل","title":"أيا شاكيا مني لذنب جنيته","page":"","text":"أيا شاكيا مني لذنب جنيته … فديتك من شاك الى حبيب\nلئن راب مني ما يريب فإنني … على عدواء الدهر غير مريب\nوإني لأرعى منك والغيب بيننا … هوى قلما يرعى بظهر مغيب\nفهب لي ذنبا واحدا ، كان قلته … فما زلل من حازم بعجيب\nفيا حسن حال الود ما دمت مذنبا … اتوب وما دامت تعد ذنوبي"},{"id":"diwan-radi:58","bookId":"diwan-radi","type":"poem","seq":58,"chapter":"البحر: كامل تام","title":"لا والذي قصد الحجيج لبيته","page":"","text":"لا والذي قصد الحجيج لبيته … ما بين ناء نازح وقريب\nوالحجر والحجر المقبل تلتقي … فيه الشفاه ، وركنه المحجوب\nلا كان موضعك الذي ملكته … بين الاصالع بعد ذا لحبيب\nإني وجدت لذاذة لك في الحشا … ليست لماكول ولا مشروب\nلي انة الشاكي اذا بعد المدى … ما بيننا وتنفس المكروب"},{"id":"diwan-radi:59","bookId":"diwan-radi","type":"poem","seq":59,"chapter":"البحر: خفيف تام","title":"إن طيف الحبيب زار طروقا","page":"","text":"إن طيف الحبيب زار طروقا … والمطايا بين القنان وشعب\nفوق اكوارهن انضاء شوق … طرقوا بالغرام دون الركب\nكلما انت المطي من الاعياء … انوا من الجوى والكرب\nزارني واصلا على غير وعد … وانثنى هاجرا على غير ذنب\nكان قلبي اليه رائد عيني … فعلى العين منة للقلب\nبت ألهو بناعم الجيد غض … وفم بارد المجاجة عذب\nبل وجدي ومن راى اليوم قبلي … ناقعا للغليل من غير شرب\nسامحا لي على البعاد بنيل … كان يلويه في زمان القرب\nكان عندي أن الغرور لطرفي … فإذا ذلك الغرور لقلبي"},{"id":"diwan-radi:60","bookId":"diwan-radi","type":"poem","seq":60,"chapter":"البحر: طويل","title":"حلفت باعلام المحصب من منى","page":"","text":"حلفت باعلام المحصب من منى … وما ضم ذاك القاع والمنزل الرحب\nوكل بجاوي يجر زمامه … إذا ما تراخت في أزمتها النجب\nوترجيع أصوات الحجيج وقد بدا … وقور النواحي تستبد به الحجب\nوروعة يوم النحر والهدى حائر … وكل دم اودى بجمته الركب\nلقد جل ما بيني وبينك عن قلى … سواء تدانى البعد أو بعد القرب\nولي دمع عين لا يرنق ساعة … ونار غرام بين جنبي لا تخبو\nوقلب يمور الطرف ان قرفى الحشا … وطرف ، إذا سكنته نفر القلب\nوجسم اذا جردته من قميصه … على الناس قالوا هكذا يفعل الحب\nفما لي على ما بي أعنف في الهوى … ويرمضني العذل المؤرق والعتب\nعلى حين أعطيك الوفاء مصرحا … وأصفيك محض الود ما عظم الخطب\nوكنت اذا فارقت دارك ساعة … صمت ، فلا جد لدي ولا لعب\nالا ليت شعري هل ابيتن ليلة … بميثاء يلطى في اباطحها الثرب\nتطرقها ماء الغمام ودرجت … بها الريح مخضرا كما نشر العصب\nوهل أذعرن قلب الظلام بفتية … تهاوى بهم قود السوالف أو قب\nوهل أردن ماء وردنا بمثله … جميعا وفي غصن الهوى ورق رطب\nوهل لي بدار انت فيها اقامة … فانشرلا ما تطوى الرسائل والكتب\nسلوت المعالي ان سلوتك ساعة … وما انا الا مغرم بالعلى صب"},{"id":"diwan-radi:61","bookId":"diwan-radi","type":"poem","seq":61,"chapter":"البحر: طويل","title":"يقر بعيني ان ارى لك منزلا","page":"","text":"يقر بعيني ان ارى لك منزلا … بنعمان يزكو تربه ويطيب\nوأرضا بنوار الأقاحي صقيلة … تردد فيها شمأل وجنوب\nواي حبيب غيب الناءي شخصه … وحال زمان دونه وخطوب\nتطاولت الاعلام بيني وبينه … واصبح نائي الدار وهو قريب\nلك الله من مطلولة القلب بالهوى … قتيلة شوق ، والحبيب غريب\nأقل سلامي إن رأيتك خيفة … وأعرض كيما لا يقال مريب\nواطرق والعينان يومض لحظها … إليك ، وما بين الضلوع وجيب\nيقولون مشغوف الفؤاد مروع … ومشغوفة تدعو به فيجيب\nوما علموا انا الى غير ريبة … بقاء الليالي نغتدي ونؤب\nعفافي من دون التقية زاجر … وصونك من دون الرقيب رقيب\nعشقت ومالي يعلم الله حاجة … سوى نظري والعاشقون ضروب\nوما لي يالمياء بالشعر طائل … سوى ان اشعاري عليك نسيب\nأحبك حبا لو جزيت ببعضه … أطاعك مني قائد وجنيب\nوفي القلب داء في يديك دواؤه … إلا رب داء لا يراه طبيب\nسرى لك من اوطانه كل عارض … تضاحك فيه البرق وهو قطوب\nولا زال خفاق النسيم مرقرقا … عليك ، وأنواء الغمام تصوب"},{"id":"diwan-radi:62","bookId":"diwan-radi","type":"poem","seq":62,"chapter":"البحر: طويل","title":"أغيب فأنسى كل شيء سوى الهوى","page":"","text":"أغيب فأنسى كل شيء سوى الهوى … وان فجعتني بالحبيب النوائب\nولا زاد يوم البين إلا صبابة … فلا الشوق منسي ولا الدمع ناضب\nاحن اذا حنت ركابي وفي الحشا … بلابل لا تعيا بهن النجائب\nفعندي اشتياق ما يحن اخو الهوى … وعندي لغوب ما تحن الركائب\nوإني لأرعى من وداد أحبتي … علي بعد ما لا تراعي الاقارب"},{"id":"diwan-radi:63","bookId":"diwan-radi","type":"poem","seq":63,"chapter":"البحر: سريع","title":"هل ناشد لي بعقيق الحمى","page":"","text":"هل ناشد لي بعقيق الحمى … غزيلا مر على الركب\nافلت من قانصه غرة … وعاد بالقلب الى السرب\nوأظمأ القلب إلى مالك … لا يحسن العدل على القلب\nيعجب من عجبي به في الهوى … واعجبي منه ومن عجبي\nأقرب بالود ، وينأى به … ويلي على بعدك من قرب\nمنعم يعطف منه الصبا … لعب الصبا بالغصن الرطب\nبلادة النعمة في طبعه … وربما ناقش في الحب\nاما اتقى الله على ضعفه … معذب القلب بلا ذنب\nيا ماطلا لي بديون الهوى … من دل عينيك على قلبي"},{"id":"diwan-radi:64","bookId":"diwan-radi","type":"poem","seq":64,"chapter":"البحر: وافر تام","title":"رماني كالعدو يريد قتلي","page":"","text":"رماني كالعدو يريد قتلي … فغالطني وقال انا الحبيب\nوانكرني فعرفني اليه … لظى الأنفاس والنظر المريب\nوقالوا لم اطعت وكيف اعصي … أميرا من رعيته القلوب"},{"id":"diwan-radi:65","bookId":"diwan-radi","type":"poem","seq":65,"chapter":"البحر: كامل تام","title":"وشممت في طفل العشية نفحة","page":"","text":"وشممت في طفل العشية نفحة … حبست برامة صحبتي وركابي\nمتململين على الرحال كأنما … مروا ببعض منازل الاحباب\nذكرت لي الارب القديم من الهوى … عهد الصبا وليالي الاطراب\nفبعثت دمعي ثم قلت لصاحبي : … ايه دموعك يا ابا الغلاب\nفي ساعة لما التفت الى الصبا … بعدت مسافته على الطلاب\nوتأرجت منها زلازل ريطتي … حتى تعهارف طيبها اصحابي\nفكانما استعقبت فارة تاجر … وبعثت فضلتها إلى أثوابي\nاشكو اليك ومن هواك شكايتي … ويهون عندك أن أبيت كما بي\nيا ماطلي بالدين وهو محبب … من لي بدائم وعدك الكذاب"},{"id":"diwan-radi:66","bookId":"diwan-radi","type":"poem","seq":66,"chapter":"البحر: خفيف تام","title":"اي عيد من الهوى عاد قلبي","page":"","text":"اي عيد من الهوى عاد قلبي … بعد ما جعجع الدجا بالركب\nلو دعاني من غير ارضك داع … لغرام لكنت غير ملبي\nاين ظبي بذي النقا يوقد النا … ر عشاءبالمندليالرطب\nكلما اخمدت زهاها بضوء الحسن … من جيده وضوء القلب\nسكن الهضب من قبا فوجدنا … اثرا للهوى بذاك الهضب\nليت أحبابنا ، وقد أشرقونا … سوغونا برد الزلال العذب\nيا لها نظرة على الشعب دلت … غرورا على غزال الشعب\nقسموا السوء بين عيني وقلبي … لم جنى ناظري فعذب قلبي"},{"id":"diwan-radi:67","bookId":"diwan-radi","type":"poem","seq":67,"chapter":"البحر: طويل","title":"ألا أيها الركب اليمانون عهدكم","page":"","text":"ألا أيها الركب اليمانون عهدكم … على ما أرى ، بالأبرقين قريب\nوان غزالا جزتم بكناسه … على النأي عندي والمطتال حبيب\nولما التقينا دل قلبي على الجوى … دليلان : حسن في العيون وطيب\nولي نظرة لا تملك العين أختها … مخافة يثنوها علي رقيب\nوهل بنفعني اليوم دعوى برائة … لقلبي ولحظي يا اميم مريب\nوأنهلني في القعب فضل غبوقه … خليطان : ريق بارد وضريب\nولو نفضت تلك الثنيات بردها … على الصبر الممرور كاد يطيب\nفيا برد ماء ذاب ما ذيق برده … بلى ان لي قلبا عليه يذوب"},{"id":"diwan-radi:68","bookId":"diwan-radi","type":"poem","seq":68,"chapter":"البحر: سريع","title":"يا ريم ذا الأجرع يرعى به","page":"","text":"يا ريم ذا الأجرع يرعى به … ثمار قلبي بدل الرطب\nهناك شرب الدمع من ناظري … يا مشرقي بالبارد العذب\nانتا على البعد همومي اذا … غبت ، وأشجاني على القرب\nلا أتبع القلب إلى غيركم … عيني لكم عين على قلبي"},{"id":"diwan-radi:69","bookId":"diwan-radi","type":"poem","seq":69,"chapter":"البحر: كامل تام","title":"لا يبعدن الله برد شبيبة","page":"","text":"لا يبعدن الله برد شبيبة … ألقيته بمنى ، ورحت سليبا\nشعر صحبت به الشباب غرانقا … والعيش مخضر الجناب رطيبا\nبعد الثلاثين انقراض شبيبة … عجبا اميم لقد رأيت عجيبا\nقد كان لي قططا يزين لمتي … شروى السنان يزين الأنبوبا\nفاليوم اطلب الهوى متكلفا … حصرا والقي الغانيات مريبا\nاما بكيت على الشباب فانه … قد كان عهدي بالشباب قريبا\nلو كان يرجع ميت بتفجع … وجوى شققت على الشباب جيوبا\nوائن حننت الى منى من بعدها … فلقد دفنت بها الغداة حبيبا"},{"id":"diwan-radi:70","bookId":"diwan-radi","type":"poem","seq":70,"chapter":"البحر: كامل تام","title":"ولقد مررت على ديارهم","page":"","text":"ولقد مررت على ديارهم … وطلولها بيد البلى نهب\nفوقفت حتى ضج من لغب … نضوي ولج بعذلي الركب\nوتلفتت عيني ، فمذ خفيت … عنها الطلول تلفت القلب"},{"id":"diwan-radi:71","bookId":"diwan-radi","type":"poem","seq":71,"chapter":"البحر: كامل تام","title":"ولق اكون من الغواني مرة","page":"","text":"ولق اكون من الغواني مرة … بأعز منزلة الحبيب الأقرب\nاقتادهن بفاحم متخايل … فيريبني ويرين لي ويزين بي\nواذا دعوت اجبن غير شوامس … زفف النياق إلى رغاء المصعب\nفاليوم يلوين الوجوه صوادفا … صد الصحاح عن الطلي الاجرب\nواذا لطفت لهن قال عواذلي … ذئب الغضاة يريغ ود الربرب\nفلئن فجعت بلمة فينانة … مات الشباب بها ولما يعقب\nفلقد فجعت بكل فرع باذخ … من عيص مدركة الأعز الأطيب\nقومي تقارعت السنون عليهم … فثلمن كل فتى كحد المقضب\nشعبا مفرقة يطير فضاضها … كالقعب منصدعا ولما يرأب\nهتف الردى بجميعهم فتتابعوا … طلق العطاس بني أب وبني أب\nوردوا واني بعدهم كظمية … تسل القوارب عن بلوغ المشرب\nطرق الزمان بكل خطب بعدهم … فإذا رأيت عجيبة لم أعجب"},{"id":"diwan-radi:72","bookId":"diwan-radi","type":"poem","seq":72,"chapter":"البحر: وافر تام","title":"غدا في الجيرة الغادين لبي","page":"","text":"غدا في الجيرة الغادين لبي … جميعا ، ثم راجعني وثابا\nلئن فارقتهم وبقيت حيا … لقد فارقت بعدهم الشبابا"},{"id":"diwan-radi:73","bookId":"diwan-radi","type":"poem","seq":73,"chapter":"البحر: وافر تام","title":"تمل من التصابي حين تمسي","page":"","text":"تمل من التصابي حين تمسي … ولا أمم صباك ، ولا قريب\nسواد الراس سلم للتصابي … وبين البيض والبيض الحروب\nوولاك الشباب على الغواني … فبادر قبل يعزلك المشيب"},{"id":"diwan-radi:74","bookId":"diwan-radi","type":"poem","seq":74,"chapter":"البحر: كامل تام","title":"الدمع مذ بعد الخليط قريب","page":"","text":"الدمع مذ بعد الخليط قريب … والشوق يدعو ، والزفير يجيب\nما كنت اعلم ان يوم فراقكم … تبقي علي نواظر وقلوب\nإن لم تكن كبدي غداة وداعكم … ذابت فاعلم انها ستذوب\nداء طلبت له الاساة فلم يكن … إلا التعلل بالدموع طبيب\nاما اقمت فان دمعي غالب … لعواذلي ، وتجلدي مغلوب\nابقوا عليلا بعدهم لا برؤه … يجى ولا الامال فيه تخيب\nكطريد يوم الورد طال هيامه … فغدا يحوم على الردى ويلوب\nبفؤاده وبصفحتيه من الصدى … ومن الرماء عن الحياض ندوب\nأسوان يفتق صبره افتاقة … أمما ، وبغمز بالجوى ، فيغيب"},{"id":"diwan-radi:75","bookId":"diwan-radi","type":"poem","seq":75,"chapter":"البحر: متقارب تام","title":"وابيض كالنصل من همه","page":"","text":"وابيض كالنصل من همه … قراع المطالب للطالب\nانيس اليدين ببذل النوال … اذا احتشمت راحة الواهب\nفتى كمل المجد أخلاقه … فسد الفجاج على العائب\nدعا فاطعت وكان الدعاء … إلى الفخر والشرف الراتب\nوكنت إلى مثلها في النهو … اثقل من كاهل الحاطب"},{"id":"diwan-radi:76","bookId":"diwan-radi","type":"poem","seq":76,"chapter":"البحر: بسيط تام","title":"ابرا الى المجد من حرصي على الطلب","page":"","text":"ابرا الى المجد من حرصي على الطلب … ومن قراعي على الارزاق والرتب\nلو أنصف الدهر دلتني غياهبه … على العلى بضياء العقل والحسب\nما ينفع المرء احساب بلا جدة … اليس ذا منتهى حظي وذاك ابي\nالآن اطلب ثاراتي بمقربة … خدعتها عن غمير النور والعشب\nيجول صدر الضحى في افق قسطلها … واليوم بين العوالي ضيق اللبب\nأنضيت ستا وعشرا ما قضيت بها … سوى المنى وطرا الا من الادب"},{"id":"diwan-radi:77","bookId":"diwan-radi","type":"poem","seq":77,"chapter":"البحر: وافر تام","title":"لعل الدهر أمضى منك غربا","page":"","text":"لعل الدهر أمضى منك غربا … وأقوى في الأمور يدا وقلبا\nومقلته اذا لحظت حسامي … تغض مهابة وتفيض رعبا\nفكيف وانت اعمى عن مقالي … ولو عاينته لرأيت شهبا\nعذرتك انت اردى الناس اصلا … واخبث منصبا واذل جنبا\nوأنت أقل في عيني من أن … اروعك أو اشن عليك حربا\nأأعجب من خصامك لي وجدي … رسول الله يوسع منك سبا\nومن رجم السماء ، فلا عجيب … يقال حثا بوجه البدر تربا\nفإنك إن هجوت هجوت ليثا … وإني إن هجوت هجوت كلبا"},{"id":"diwan-radi:78","bookId":"diwan-radi","type":"poem","seq":78,"chapter":"البحر: طويل","title":"خليلي ما بيني وبين محرق","page":"","text":"خليلي ما بيني وبين محرق … سوى وقع اطراف القنا والقواضب\nأتاني بها بزلاء تلقي جرانها … على خير بيت في لؤي بن غالب\nوفاز بكوم ذي رقاب منيفة … واسنمة ملوية بالغوارب\nارى ابلي مطروحة عن مراحها … يصيح بها الأعداء من كل جانب\nاذا هن طالعن المياه عشية … نشجن وراء الذود نشج الغرائب\nوكنا ، إذا ما أبعد المجد غاية … دفعنا اليها من صدور النجائب\nتسير أمام العاصفات كأنها … طلائع أعناق الصبا والجنائب\nخوارج من ليل كأن نجومه … بياض الحصى بالأمعز المتراكب"},{"id":"diwan-radi:79","bookId":"diwan-radi","type":"poem","seq":79,"chapter":"البحر: مجزوء الكامل","title":"إياك أن تسخو بوع","page":"","text":"إياك أن تسخو بوع … س عزمك ان تفي به\nفالصدق يحسن بالفتى … والكذب يحسب من عيوبه\nواذا قدرت على الوفا … ء ، فعد عن غدر وذيبه\nاشكوك ام اشكو الزمان … ن ، لأن مطلك من ذنوبه\nبل اشتكيه فكم دفعت … ت إلى الغرائب من خطوبه"},{"id":"diwan-radi:80","bookId":"diwan-radi","type":"poem","seq":80,"chapter":"البحر: طويل","title":"سما كبطون الأتن ريعان عارض","page":"","text":"سما كبطون الأتن ريعان عارض … تزجيه لوثاء النسيم جنوب\nرغا بين دوح الواديين برعده … رغاء مطايا مسهن لغوب\nبصير برمي القطر حتى كانه … على الرمل قارئ السهام نجيب\nتدافع اما برقة فصوارم … جلاء ، وأما عرضه فكثيب\nاذا ما اراق الماء اسفر وجهه … ويغدو بعبء الماء ، وهو قطوب\nسهرت له نابي الوسادة ، برقه … يحوم على اعناقه ويلوب\nفؤادي بنجد والفتى حيث قلبه … أسير ، وما نجد إلي حبيب\nوما لي فيه صبوة غير أنني … خلعت شبابي فيه وهو رطيب\nبلى ان قلبا ربما التاح لوحة … فهل ماؤه للواردين قريب\nألا هل ترد الريح ، يا جو ضارج … نسيمك يحلولي لنا ويطيب\nوهل تنظر العين الطليحة نظرة … إليك ، وما في الماقيين غروب\nوما وجد ادمأ الاهاب مروعة … لاحشائها تحت الظلام وجيب\nترود طلا اودت به غفلاتها … وفي كل حي للمنون نصيب\nبغوم على آثاره ، وقد اكتسى … ظلام الدياجي غائط وسهوب\nفلما أضاء الصبح لاح لعينها … دم بين ايدي الضاريات صبيب\nكوجدي وقد عرى الشباب جواده … وغير لون العارضين مشيب\nولكنها الايام اما قليبها … فمكد واما برقها فخلوب\nإذا ما بدأن الأمر أفسدن عقبه … وعفى على إحسانهن ذنوب\nفلله دري يوم أنعت قولة … لها في رؤوس السامعين دبيب\nولله دري يوم اركب همة … الى كل ارض اغتدي وأؤوب\nوكم مهمة جاذبت بالسير عرضه … وغالبته بالعزم ، وهو غلوب\nوليل رأيت الصبح في أخرياته … كما انسل من سر النجاد قضيب\nسريت به اوفي على كل ربوة … وليس سوى نجم علي رقيب\nوأزرق ماء قد سلبت جمامه … يعوم الشوى في غمره ويغيب\nوهاجرة فللت بالسير حدها … ولا ظل الا ذابل ونجيب\nوألأم مصحوب قذفت إخاءه … عن الروع والإصباح فيه مريب\nحبست به قلبا جريا على الردى … وقد رجفت تحت الصدور قلوب\nوطعنة رمح قد خرطت نجيعها … كما ماج فرغ في الإناء ذنوب\nوضربة سيف قد تركت مبينة … وحاملها عمر الزمان معيب\nوالام مصحوب قذفت اخائه … كما قذف الماء المريض شروب\nومن كان ما فوق النجوم طلابه … أمل عناء قلبه ودؤوب\nنظرت إلى الدنيا بعين مريضة … وما لي من داء الرجاء طبيب\nومن كان في شغل المنى ففراغه … منال الاماني اوردى وشعوب\nفما لي طول الدهر أمشي كأنني … لفضلي في هذا الزمان غريب\nإذا قلت قد علقت كفي بصاحب … تعود عواد بيننا وخطوب\nوما فيه شيء خالد لمكادح … وكل لغايات الامور طلوب"},{"id":"diwan-radi:81","bookId":"diwan-radi","type":"poem","seq":81,"chapter":"البحر: بسيط تام","title":"يا سعد كل فؤاد في بيوتكم","page":"","text":"يا سعد كل فؤاد في بيوتكم … مثلي تحكم فيه الظلم والشنب\nإني لأكرم نفسي أن يقال جنى … على الفتى العربي الخرد العرب\nإني على شغفي بالحب معتذر … من ان يقال شجاع فله الوصب\nإنا معاشر لا تبلى مطارفنا … إلا وهن لطلاب الندى سلب\nموقرون وأيدي الحلم طائشة … والجد ينقص من أطرافه اللعب\nفالان تغصبنا الدنيا غضارتها … ظلما وتاخذ من ايامنا النوب"},{"id":"diwan-radi:82","bookId":"diwan-radi","type":"poem","seq":82,"chapter":"البحر: وافر تام","title":"الى كم لاتلين على العتاب","page":"","text":"الى كم لاتلين على العتاب … وأنت أصم عن رد الجواب\nحذارك ان تغالبني غلابا … فإني لا أدر على الغضاب\nوإنك إن أقمت على أذاتي … فتحت الى انتصاري كل باب\nواحلم ثم يدركني ابائي … وكم يبقى القرين على الجذاب\nاذا وليتني ظفرا ونابا … فدونك فاخش من ظفري ونابي\nفان حمية القرناء تطغى … فتثلم جانب النسب القراب\nنفرالى الشراب اذا غصصنا … فكيف إذا غصصنا بالشراب\nفلا تنظر الي بعين عجز … فرب مهند لك في ثيابي\nومن لك بي يرد عليك شخصي … اذا اثبت رجلي في الركاب\nوما صبري وقد جاشت همومي … إلى أمر وعب له عبابي\nسيرمي عنك بي مرمى بعيد … وتغدو غير منتظر إيابي\nاذا الاشفاق هزك عدت منه … بعض أنامل أو قرع ناب\nوتسمع بي وقد أعلنت أمري … فتعلم ان دأبك غير دابي\nورب ركائب من نحو ارضي … تخب اليك بالعجب العجاب\nوتظهر أسرة من سر قومي … تمد الى انتظاري بالرقاب\nوتصبح لا تني عجبا وقولا : … أهذا الحد أطلق من ذبابي\nفكيف إذا رأيت الخيل شعثا … طلعن من المخارم والعقاب\nتعاظل كالجراد زفته ريح … فمر يطيعها يوم الضباب\nأمضتها الشكائم فهي خرس … تسيل لها دما بدل اللعاب\nتذكركم بذي قار طعانا … وما جر القنا يوم الكلاب\nعليها كل ابلج من قريش … لبيق بالطعان وبالضراب\nيسير ، وأرضه جرد المذاكي … وجو سمائه ظل العقاب\nوعندي للعدى لا بد يوم … يذيقهم المسمم من عقابي\nفانصب فوق هامهم قدوري … وأمزج من دمائهم شرابي\nواركز في قلوبهم رماحي … واضرب في ديارهم قبابي\nفان اهلك فعن قدر جري … وإن أملك فقد أغنى طلابي"},{"id":"diwan-radi:83","bookId":"diwan-radi","type":"poem","seq":83,"chapter":"قصائد","title":"لم يبق عندي من الإباء سوى ال","page":"","text":"لم يبق عندي من الإباء سوى ال … نظرة محمرة من الغضب\nوعض كفي على الزمان من الغي … ظ ، وشكوى وقائع النوب\nاو زفرة تحسب الضلوع لها … أطر قسي يرمين باللهب\nمضى الرجال الأولى مذ افترقوا … عني صار الزمان يلعب بي\nأقول لما عدمت نصرهم … والهف امي عليكم وابي"},{"id":"diwan-radi:84","bookId":"diwan-radi","type":"poem","seq":84,"chapter":"البحر: وافر تام","title":"أبا حسن ! أتحسب أن شوقي","page":"","text":"أبا حسن ! أتحسب أن شوقي … يقل على معارضة الخطوب\nوانك في اللقاء تهيج وجدي … وامنحك السلو على المغيب\nوكيف ، وأنت مجتمع الأماني … ومجني العيش ذي الورق الرطيب\nيهش لكم على العرفان قلبي … هشاشته الى الزور الغريب\nوألفظ غيركم ، ويسوغ عندي … ودادكم مع الماء الشروب\nويسلس في اكفكم زمامي … ويعسو عند غيركم قضيبي\nوبي شوق إليك أعل قلبي … وما لي غير قربك من طبيب\nأغار عليك من خلوات غيري … كما غار المحب على الحبيب\nوما أحظى ، إذا ما غبت عني … بحسن للزمان ولا بطيب\nأشاق ، إذا ذكرتك من بعيد … واطرب ان رأيتك من قريب\nكانك قدمة الامل المرجى … علي ، وطلعة الفرج القريب\nإذا بشرت عنك بقرب دار … نزا قلبي إليك من الوجيب\nمراح الركب بشر بعد خمس … ببارقة تصوب على قليب\nأسالم حين أبصرك الليالي … وأصفح للزمان عن الذنوب\nوانسى كلما جئت الرزايا … علي من الفوادح والندوب\nتميل بي الشكوك إليك حتى … اميل الى المقارب والنسيب\nوتقرب في قبيل الفضل مني … على بعد القبائل والشعوب\nأكاد أريب فيك ، إذا التقينا … من الانفاس والنظر المريب\nواين وجدت من قبلي شبابا … يحن من الغرام على مشيب\nإذا قرب المزار ، فأنت مني … مكان الروح من عقد الكروب\nوإن بعد اللقاء على اشتياقي … ترامقنا بألحاظ القلوب"},{"id":"diwan-radi:85","bookId":"diwan-radi","type":"poem","seq":85,"chapter":"البحر: رجز تام","title":"جاءت به من مضر مهذبا","page":"","text":"جاءت به من مضر مهذبا … مثل السنان ذلقا مذربا\nيضم برداه الجراز المقضبا … تخير الاحساب اما وابا\nابلج لا يشتم الا كذبا … "},{"id":"diwan-radi:86","bookId":"diwan-radi","type":"poem","seq":86,"chapter":"البحر: مجتث","title":"لا تنكري حسن صبري","page":"","text":"لا تنكري حسن صبري … إن أوجع الدهر ضربا\nفالعبد أصبر جسما … والحر أصبر قلبا"},{"id":"diwan-radi:87","bookId":"diwan-radi","type":"poem","seq":87,"chapter":"البحر: طويل","title":"نزوت نزاء الجندب الجون ضلة","page":"","text":"نزوت نزاء الجندب الجون ضلة … إلى باسل عبل الذراعين أغلب\nوما كنت في الأحياء إلا ضميمة … تناط بهم نوط الاباء المذبذب\nتجاور زلا ، أو تعاقد قلة … من الهون لا تدلي بام ولا اب\nفحول معد منجبون ، وأنتم … نزالة فحل منهم غير منجب\nتقنصه صرف المقادير غرة … وكم فات من ناب علوق ومخلب\nولو هيج للهيجاء طار بسرجه … جواد كذئب الردهة المتاؤب\nوكل سنان طالع فوق ضامر … كما حام زنبور على ظهر عقرب\nوفتيان غارات كأن رماحهم … بجانب ذي القرم عيدان اثأب\nبأيمانهم بيض يضيء وجوههم … قواضب قد جربن كل مجرب\nغرانق أزوال رعوا عازب الحمى … بصم العوالي ، والصفيح المقلب\nفلا تحسبوها قطرة من دمائنا … تضيع ولو في طافح النجم مطلب\nاذا اعشب الشق اليماني فابشروا … بيوم عقام ينضح الشر أجرب\nفان ترحمونا اليوم نرحمكم غدا … بعود من الجزم النزاري مصعب"},{"id":"diwan-radi:88","bookId":"diwan-radi","type":"poem","seq":88,"chapter":"البحر: متقارب تام","title":"لكم لقحة الأرض تحمونها","page":"","text":"لكم لقحة الأرض تحمونها … وفي يدكم صرها والحلب\nفمن اين نبلغ ما نشتهي … ومن أين نطمع فيما نحب\nإذا المال أصبح في الباخلين … فان مرجي الغنى في تعب"},{"id":"diwan-radi:89","bookId":"diwan-radi","type":"poem","seq":89,"chapter":"البحر: رجز تام","title":"انظر ابا قران ما تعيب","page":"","text":"انظر ابا قران ما تعيب … ماس الذرى قومها لبيب\nتصغي لها الأسماع والقلوب … مثل السهام كلها مصيب\nلطيمة نم عليها الطيب … تودعها الاردان والجيوب\nويغنم الهلباجة المعيب … يتعب ذو البراعة الاديب\nيخرج عني العاسل المذروب … قد قوم الأنبوب والأنبوب\nفلا يزال العض والتنييب … حتى يعود الذابل الصليب\nوهو بأيدي معشر كعوب … إن رزايات الفتى ضروب\nفي كل يوم هجمة تلوب … هاج عليها الكلأ الرطيب\nيطلبن ارضي والهوى طلوب … لا أمم مني ولا قريب\nعند الأعادي وسمها غريب … يرصدهن الحارب المريب\nله على مطلعها رقيب … إذا طلعن اعترض القليب\nتهوي به الأظفار والنيوب … كما هوت خائبة طلوب\nيألم قلبي ، وبها الندوب … يشكو المطى ما ألم العرقوب\nأطبعها ، وهو بها الكسوب … لي اللألي وله الثقوب\nداء على إعضاله عجيب … يضحك من أوصافه الطبيب\nهل تأمن اليوم وانت ذيب … بهم بأكناف الحمى غريب\nإن لم يدم الله والخطوب … "},{"id":"diwan-radi:90","bookId":"diwan-radi","type":"poem","seq":90,"chapter":"البحر: رمل تام","title":"كيف صبحت أبا الغمر بها","page":"","text":"كيف صبحت أبا الغمر بها … صعبة تنزوا نزاء الجندب\nمرح الشقراء في مضمارها … تتقي الصوت بمر عجب\nيركب الراكب إن جشمها … دلج الليل وتسبي المستبى\nبنت كرم ظئرها الشمس ، وما … درجت في حجر أم وأب\nغصبت ما اثرت في جسمها … قدم العلج براس العربي"},{"id":"diwan-radi:91","bookId":"diwan-radi","type":"poem","seq":91,"chapter":"البحر: متقارب تام","title":"يعاقبني ، وهو المذنب","page":"","text":"يعاقبني ، وهو المذنب … لقد ذل جارك يا جندب\nويعجب من غضبي جهلة … ومن ذا يضام فلا يغضب\nنزاد من اللوم عن وردكم … فعم نزاد ولا مشرب\nنعم اعوز الطول راجيكم … فلم أعوز الأهل والمرحب\nاذا ابلي مطلت رعيها … فهل ينفع البلد المعشب\nوهل نافعي ظاهر باسم … ومن خلفه باطن يقطب\nلقد وقف الركب من بابكم … على مطلب ماؤه مطلب\nوما كنت في النفر الشائمي … ن ، بأول من غره الخلب\nذنابى مصعن بأبعارهن … وقد يمصع الذنب الاهلب\nلقد ساءني ان يموت السماح … بموت الكرام ولا يعقب\nألا تعجبون لذي سوءة … تحكك في عرضه الاجرب\nوجعجع لي ظهر عاري الصفاح … ح عقير ، وقال : ألا تركب\nوسوف أغني بأعراضكم … غناء من الشر لا يطرب\nقواف مطلن لحز الجنوب … مطل المدى جرعها موعب\nوحسبك من سفه أنني … أجد ، وتحسبني ألعب\nوقالوا : احتلب درهم بالسؤا … ل ، إن الغوارز لا تحلب\nوكيف ولم يرغبوا في الثناء … إلى المادحين ولم يرغبوا\nلقد وسع الله ما ضيقوا … وقد عوض الله ما خيبوا"},{"id":"diwan-radi:92","bookId":"diwan-radi","type":"poem","seq":92,"chapter":"البحر: كامل تام","title":"نزل المسيل وبات يشكو سيله","page":"","text":"نزل المسيل وبات يشكو سيله … الا علوت فبت غير مراقب\nجمع المثالب ، ثم جاء تعرضا … بالمخزيات يدق باب الثالب\nوإذا اجتمعت على معايب جمة … فتنح جهدك عن طريق العايب"},{"id":"diwan-radi:93","bookId":"diwan-radi","type":"poem","seq":93,"chapter":"البحر: طويل","title":"وركب تفرى بينهم قطع الدجى","page":"","text":"وركب تفرى بينهم قطع الدجى … يسير على البيداء ينتهب التربا\nيصدون عن ورد الكرى وعيونهم … خوامس حتى تشرب المنظر العذبا\nاذا زعزتهم نبأة غادرتهم … وقد أيقظوا من بين أجفانها القضبا\nسروا وخيول الليل دهم وعرسوا … وقد غادروها في طراد الضحى شهبا\nيضوع هجير السير بين رحالهم … إذا ما نسيم الليل في ثوبه هبا"},{"id":"diwan-radi:94","bookId":"diwan-radi","type":"poem","seq":94,"chapter":"البحر: طويل","title":"أسنة هذا المجد آل المهلب","page":"","text":"أسنة هذا المجد آل المهلب … وفراطه في كل شرق ومغرب\nسلوني عن مجد المفعل واسئلوا … أبي عن أبيه ذي الجلال المهذب\nيقل ان ذاك الليث في كل معرك … وهذا الحسام العضب في كل مضرب\nوهذا الربيع الطلق رقت فروعه … نتيجة ذاك العارض المتصبب\nأخلاي من بين الملوك وإخوتي … واحلى بقلبي من بعيدي واقربي\nهم قومي الادنون من بين اسرتي … وان كان شعب القوم من غير مشعبي\nفهذا ثناي لا اريد به الغنى … أبى المجد لي أن أجعل المدح مكسبي\nولكن رجاء أن تكون لهمتي … طريقا تؤديني الى كل مطلبي\nفازحم منك الحادثات بمنكب … واقطع منك النائبات بمقضب\nوارمي الى امر اظنك بابه … ألا إن بعض الظن غير مكذب"},{"id":"diwan-radi:95","bookId":"diwan-radi","type":"poem","seq":95,"chapter":"البحر: كامل تام","title":"قل للخطوب : ضعي سلاحك قد حمى","page":"","text":"قل للخطوب : ضعي سلاحك قد حمى … سربي وآمنني أبو الخطاب\nولقد حططت بك الرجاء ولم يكن … إلا إليك تسببي وطلابي\nيا ملبسي النعم القديم لباسها … جدد علي نضارة الاثواب\nدار المعالي انت باب دخولها … فأذن فاني واقف بالباب"},{"id":"diwan-radi:96","bookId":"diwan-radi","type":"poem","seq":96,"chapter":"البحر: طويل","title":"دعوا لي اطباء العراق لينظروا","page":"","text":"دعوا لي اطباء العراق لينظروا … سقامي وما يغني الاطباء في الحب\nأشاروا بريح المندل اللدن والشذا … ورد ذماء النفس بالبارد العذب\nيطيلون جس النابضين ضلالة … ولو علموا جسوا النوابض من قلبي"},{"id":"diwan-radi:97","bookId":"diwan-radi","type":"poem","seq":97,"chapter":"البحر: مديد تام","title":"صاحب كالغر ليس ارى","page":"","text":"صاحب كالغر ليس ارى … جده مني ولا لعبه\nيتقيني بالخلاب ، وإن … جدحوا عرضي له شربه\nداعيا لي بالخلود ولو … طلبوا منه دمي وهبه\nقسما بالبيت طفت به … وبرمي جمرة العقبة"},{"id":"diwan-radi:98","bookId":"diwan-radi","type":"poem","seq":98,"chapter":"البحر: خفيف تام","title":"بين عزمي وبينهن حروب","page":"","text":"بين عزمي وبينهن حروب … إن أقواهما هو المغلوب\nعرضت رحلة فعرض بالد … مع فهان المأمول والمطلوب"},{"id":"diwan-radi:99","bookId":"diwan-radi","type":"poem","seq":99,"chapter":"قصائد","title":"إساءته شهوة ثرة","page":"","text":"إساءته شهوة ثرة … وإحسانه درة الارنب\nفقد زيد شرا إلى شره … كما استنفر الضب بالعقرب"},{"id":"diwan-radi:100","bookId":"diwan-radi","type":"poem","seq":100,"chapter":"البحر: طويل","title":"اخافك إن الخوف منك محبة","page":"","text":"اخافك إن الخوف منك محبة … وما كل مخشي العقاب محببا\nلئن كان خوفي من سطاك مبعدا … فيا ربما كان الرجاء مقربا"},{"id":"diwan-radi:101","bookId":"diwan-radi","type":"poem","seq":101,"chapter":"البحر: كامل تام","title":"ضموا قواصي كل سرح سارب","page":"","text":"ضموا قواصي كل سرح سارب … وقفوا السوائم بالندى المتقارب\nفلقد مضى حامي السروح من العدى … ومبيح اسواقها غرار القاضب"},{"id":"diwan-radi:102","bookId":"diwan-radi","type":"poem","seq":102,"chapter":"البحر: رمل تام","title":"آه من دائين عدم ومشيب","page":"","text":"آه من دائين عدم ومشيب … رب سقم لا يداوى بطبيب"},{"id":"diwan-radi:103","bookId":"diwan-radi","type":"poem","seq":103,"chapter":"البحر: طويل","title":"كان نزارا والخمول رداؤه","page":"","text":"كان نزارا والخمول رداؤه … غداة بغى جهلا علي وأجلبا\nمشبجة من خذل العين واقعت … على الماء مفتول الذراعين اغلبا"},{"id":"diwan-radi:104","bookId":"diwan-radi","type":"poem","seq":104,"chapter":"قصائد","title":"ترفق أيها المصيب","page":"","text":"ترفق أيها المصيب … ترفق أيها الرامي المصيب\nتسوء قطيعة وتشوق حبا … فما أدري عدو أم حبيب"},{"id":"diwan-radi:105","bookId":"diwan-radi","type":"poem","seq":105,"chapter":"البحر: طويل","title":"عذيري من العشرين يغمزن صعدتي","page":"","text":"عذيري من العشرين يغمزن صعدتي … ومن نوب الايام يقرعن مروتي\nومن همم أوجدنني في عشيرتي … وأكثرن ما بين الأقارب غربتي\nومن عزمات كل يوم يقفن بي … على كل باب للمقادير مصمت\nومن مهجة لا ترأم الضيم مرة … يعجل عن دار المذلة نهضتي\nومن لوعة للحب مشحوذة الظبى … إذا ضربت في جانب القوم ثنت\nومن زفرة تحت الشغاف مقيمة … إذا قلت قد ولى بها الدهر كرت\nتذكر أياما مضين ولو فدت … بنان يدي تلك الليالي لفلت\nيخالسنا الأحباب حتى تقطعت … قرائيننا ، ريب الزمان المشتت\nولم يبق لي إلا عليق مضنة … أداري الليالي عنه إما ألمت\nفياليتها قد انسأته وليتها … عليه وإن لم ينجح يوما اذمت\nسقى الله من أمسى على النأي علتي … وقد كان مع قرب المزار تعلتي\nأقلني ، أقلني نظرة ما احتسبتها … فقد انهلت قلبي غليلا وعلت\nفشوقا إلى وجه الحبيب تلهفي … وميلا إلى دار الحبيب تلفتي\nجرت خطرة منه على القلب كلما … زجرت لها العين الدموع ارشت\nومرت على لبي فقلت لعلها … تجاوزني مكظومة ، فاستمرت\nأداري شجاها كي يخلى مكانه … وهيهات ، ألقت رحلها واطمأنت\nوأعلم ما خاضت يد الدهر للفتى … أمر مذاقا من فراق الأحبة\nفكم زعزعتني النائبات فلم أزل … لها قدمي عن وطأة المتثبت\nوكم صاحب الأيام خلفي بروعة … فصرت بعين الجازع المتلفت\nتسل علي الحادثات سيوفها … فمن مغمد قد نال منى ومصلت\nزمامي بكف الدهر أتبع خطوه … وما الدهر إلا مالك للأزمة\nوقد كنت آبى أن أقاد ، وإنما … الان قيادي من الآن عريكتي\nفلا تشتموا أن يثلم الدهر جانبي … فاكثر مما مر مني بقيتي\nتحيف شوسا من عيون فاغمضت … وذلل غلبا من رقاب فذلت\nفآه على الدنيا إذ الجد صاعد … واوه من الدنيا إذا النعل زلت\nالأهل اخيض الطرف يوما بغمرة … إذا الخيل بالغر الوجوه تمطت\nولم تلق فيها غير طعن مضجج … وضرب سريع بالمنايا مسكت\nترن له هام الرجال وإن رمت … بأعينها فيه النساء أرنت\nفسوف تراني طايرا في غبارها … على سابح تهفو غدائر لمتي\nبيوم كثير بالغبار عطاسه … إذا ثوب الداعي قليل المشمت\nمعارك يخدجن المهار ، وبعدها … مناعي رجال ملقيات الأجنة\nورمحي إلى الأعداء كيدي ، وصارمي … جناني يوم الروع ، والصبر جنتي\nوكل غلام ذي جلاد ونجدة … وكل جواد ذي هبتات وميعة\nإذا ما الجياد الجرد اجرى لبانها … وشمصها وقع الظبا والأسنة\nفان عناني في يمين معود … على عقب الأيام قود الأعنة\nإذا اعترض المأمول من دونه الردى … شققت إليه الدارعين بمهجتي\nوغامست فيه لا أبالي لو أنني … تلقيت منه منيتي أو منيتي\nإذا سمحت بالموت نفسي فإنه … يقل احتفالي بالذي جر ميتتي\nوما ان أبالي ما جنى الدهر بعدما … يبل يميني قائم من صفيحتي\nفما حدثان الدهر عندي بفاتك … ولاجنة القار عندي بجنة\nألا لا أعد العيش عيشا مع الأذى … لأن قعيد الذل حي كميت\nيخيفونني بالموت ، والموت راحة … لمن بين غربي قلبه مثل همتي\nفلا تبرزوا لي بالانوف فانني … معودة جدع الموارن شفرتي\nبنينا رواق المجد تعلو سموكه … لقد عظمت تلك المباني وجلت\nأقلوا علينا لا أبا لأبيكم … ولا ترشقونا باللتيا وباللتي\nتريدون أن نوطى ، وأنتم أعزة … بأي كتاب أم باية سنة\nفإن كنتم منا فقد طال مليكم … قديما على عيدان تلك الأرومة\nفلا صلح حتى تسمعوا من أزيزها … صواعق أما صكت الأذن صكت\nولا صلح حتى ينظروا من زهائها … شواهق لا يبلغن صوت المصوت\nتفلت من أرسانها والأجلة … ثفلت من ارسانها والا جلت\nفإني زعيم للأعادي بمثلها … وذلك رهن في ذمامي وذمتي\nفيا منبتي هل أنت بالعز مورقي … حنانيك كم أبقى ، وقد طال منبتي\nأما كملت عند الخطوب تجارتي … أما خلصت عند الأمور رويتي\nأما انا موزون بكل خليفة … أرى أنفا من أن يكون خليفتي\nألست من القوم الأولى قد تسلفوا … ديون العلى قبل الورى في الأظلة\nوما خلقت أقدامهم وأكفهم … لغير العوالي والظبى والأسرة\nذوو الجبهات البيض تلمع بينها … وسوم المعالي والوجوه المضيئة\nأبوا أن يلم الذل منهم بجانب … وما العز لا للنفوس الابية\nوكم بين ذي انف حمي وحاملي … موازن قد عودن جذب الأخشة\nبلى أنني من تعلمان وإنما … أرى الدهر يعمى عن بيان فضيلتي\nفخرت بنفسي لا بأهلي موفرا … على ناقصي قومي مناقب اسرتي\nولا بد يوما أن يجيء فجاءة … فلا تنظراني عند وقت موقت\nووالله لا كديت دون منالها … وظني بربي أن يبر أليتي"},{"id":"diwan-radi:106","bookId":"diwan-radi","type":"poem","seq":106,"chapter":"البحر: طويل","title":"أبينتها أم ناكرتك شياتها","page":"","text":"أبينتها أم ناكرتك شياتها … نزائع ينقلن الردى صهواتها\nطلعن سواء ، والرماح عوابس … تعاسلها أعناقها وطلاتها\nرأوا نقعها يدنو فظنوا غمامة … فما شعروا حتى بدت جبهاتها\nوفوق قطاها غلمة غالبية … تميس على أكتافها وفراتها\nمغاوير لا ميل تثني رقابها … أفتيانها الباكون أم فتياتها\nتلثم فوق اللثم بالنقع والدجى … فلولا ظباها لم تبن صفحاتها\nمتى ترها في حيها تر فتية … ليوم الوغى مأخوذة أهباتها\nمفرغة مما تنيل عبابها … من المال أو مملوؤة جفناتها\nتخطى بها أعناق كل قبيلة … صوارمها تهتز أو قنواتها\nترى عندها الشهر الحرام محللا … إذا خفرتها للوغى عزماتها\nواحلم خلق الله حتى إذا دنا … إليها الأذى طارت بها جهلاتها\nإذا وسمت بالنار خيل فعندها … كرائم آثار الطعان سماتها\nمتى سمعت صوت الصريخ تنصتت … قياما إلى داعي الوغى سمعاتها\nرحلنا بأكباد غلاظ على الهوى … قليل إلى ما خلفها لفتاتها\nإذا ازمعت ازماعة الجد لم تبل … افتياتها الباكون أم فتياتها\nسوابقها أولى بها لانساؤها … وادراعها والبيض لا امهاتها\nوحي من الأعداء باتوا بليلة … منعمة لو لم تذم غداتها\nوخيل خششنا جوهم برماحنا … كما خش آناف القروم براتها\nفما استيقظوا حتى تداعى صهيلها … وقد سبقت ألحاظهم عبراتها\nولم ينجح إلا من تخاطت سيوفنا … وذاق الردى من عممت شفراتها\nقواضب لا يودي بشيء قتيلها … إذا امست القتلى تساق دياتها\nأنسنا بأطراف الرماح ، وإننا … لنحن محلوها ونحن سقاتها\nنبتن لأيدينا خصوصا ، وإنما … لنا يتواصى بالطعان نباتها\nبأبوابنا مركوزة ، وإلى الوغى … تزعزع في أيماننا قصباتها\nأبيت ، وكان العز مني خليقة … وهل سبة إلا وقومي اباتها\nفلا تفزعني بالوعيد سفاهة … فلي همة لا تقشعر شواتها\nتغاوت على عرضي عصائب جمة … ولو شئت ما التفت علي غواتها\nأوليهم صماء أذن سميعة … إذا ما وعت ألوت بها غفلاتها\nيطول إذا همي ، إذا كان كلما … سمعت نبيحا من كلاب خساتها\nلذلتها هانت علي ذنوبها … فلم أدر من نبذي لها من جناتها\nقوارص لم تعلق بجلدي نصالها … ولو كان غيري أنفذته شذاتها\nهم استلدغوا رقش الافاعي ونبهوا … عقارب ليل نائمات حماتها\nوهم نقلوا عني الذي لم أفه به … وما آفة الاخبار الا رواتها\nرموني بما لو أن عيني رمت به … جناني على عزي لها لفقاتها\nأريد لئن أحنو على الضغن بيننا … وتأبى قلوب أنغلتها هناتها\nدعوها ندوبا بيننا باندمالها … ولا تبلغوا مني والا نكاتها\nفإني مطول للأعادي مماحك … اذا نصفوا اوساق ضغن ملاتها\nلقد غربتني حظوة الفضل عنكم … وإن جمعت أعراقنا نبعاتها\nوما النفس في الاهلين الا غربية … إذا فقدت اشكالها ولداتها\nبني مضر خلوا نفوسا عزيزة … تنام فأولى أن يطول سناتها\nدعوها فخير للاعادي هجورها … وشر لمن يغرى بها يقظاتها\nثقوا عن قليل أن يهب شرارها … وإن قلتم قد أخمدت جمراتها\nولا تأنسوا ان الجياد بشكلها … فيا ربما أردتكم نزواتها\nولا تأمنوا صول النفوس وان غدت … مضاربها مفلولة وظباتها\nبنو هاشم عين ونحن سوادها … على رغم اقوام وانتم قذاتها\nوما زلتم داء يفري إهابها … وان كنتم منها ونحن اساتها\nواعجب ما يأتي به الدهر انكم … طلبتم على ما فيكم أدواتها\nواملتم أن تدركوها طوالعا … دعوها ستسعى للمعالي سعاتها\nوإما حرنتم عن مداها ، فإننا … سراع إذا مدت لنا حلباتها\nأبي دونكم ذاك الذي ما تعلقت … باثوابه الدنيا ولا تبعاتها\nتجنبها هوجاء لا مستقيمة … خطاها ولا مأمونة عثراتها\nغدا راضيا بالنزر منها قناعة … ولو شاء قد كانت له جفناتها\nتلافظها من بعد ما زاق طعمها … فكانت زعاقا عنده طيباتها\nتلافى قريشا حين رق اديمها … وخفت على ايدي الرجال حصاتها\nورجبها من بعد ما مال فرعها … وحين ابت الا اعوجاجا قناتها\nوكم عاد في احدى عواليه هامة … لجبار قوم قطرته شباتها\nفمن غيره لليعملات يقيمها … إذا وقعت مثنية ركباتها\nومن لعجاج الحرب يجلو ظلامه … إذا خفقت في نقعها عذباتها\nومن للمعالي القود يقرع هامها … إذا نفت الأقدام عنها صفاتها\nومن لاضاميم الجياد غدوها … لطعن حماليق العدى وبياتها\nلنا وعلينا إن لبثنا هنيهة … قطاف رؤس اينعت ثمراتها\nفيا لهفي كم من نفوس كريمة … تموت وفي اثنائها حسراتها\nيعز علينا ان تفوت وانها … قضت نحبها أو ما انقضت زفراتها\nوكان بدار اهون ملقى جنوبها … سواء عليها موتها وحياتها\nأسارى تعنيها الكبول ، مذودة … بواطشها مقصورة خطواتها\nوما برحت تبكي قتيلا عيونها … فلا دمعها يرقى ولا عبراتها\nعسى الله ان يرتاح يوما بفرحة … فتنطق أنضاء أطيل صماتها\nويؤخذ ثار مات هما ولاته … ولما تمت أضغانها وتراتها\nفكم فرجت من بعد ما أغلقت لنا … مغالقها ، واستبهمت حلقاتها\nغرست غروسا كنت أرجو لحاقها … وآمل يوما أن تطيب جناتها\nفان اثمرت لي غيرما كنت آملا … فلا ذنب لي ان حنطلت نخلاتها"},{"id":"diwan-radi:107","bookId":"diwan-radi","type":"poem","seq":107,"chapter":"البحر: خفيف تام","title":"يا ابن عبد العزيز لو بكت العي","page":"","text":"يا ابن عبد العزيز لو بكت العي … ن فتى من اميه لبكيتك\nغير اني اقول انك قد طب … ت ، وإن لم يطب ولم يزك بيتك\nانت نزهتنا عن السب والقذ … ف فلو امكن الجزاء جزيتك\nولو أني رأيت قبرك لا ستح … ييت من ان ارى وماحييتك\nوقليل ان لو بذلت دماء ال … بدن حزنا على الذرى وسقيتك\nدير سمعان لا اغبك غاد … خير ميت من آل مروان ميتك\nانت بالذكر بين عيني وقلبي … ان تدانيت منك أو قد نأيتك\nوإذا حرك الحشا خاطر من … ك توهمت أنني قد رأيتك\nوعجيب أني قليت بني مر … وان طرا ، وأنني ما قليتك\nقرب العدل منك لما نأى الجو … ر بهم فاجتويتهم واجتبيتك\nفلو أني ملكت دفعا لما نا … بك من طارق الردى لفديتك"},{"id":"diwan-radi:108","bookId":"diwan-radi","type":"poem","seq":108,"chapter":"البحر: خفيف تام","title":"من يكن زائري يجدني مقيما","page":"","text":"من يكن زائري يجدني مقيما … أتبع الغانيات بالزفرات\nفي ندامى على الهموم قعود … يدعمون الاذقان بالراحات\nكلما انزفوا من الدمع مدت … هم دواعي الهموم بالعبرات"},{"id":"diwan-radi:109","bookId":"diwan-radi","type":"poem","seq":109,"chapter":"البحر: سريع","title":"إذا مضى يوم على هدنة","page":"","text":"إذا مضى يوم على هدنة … وانت في سلم من النائبات\nفعاجل الفرصة قبل الردى … وبادر اللذات قبل البيات\nواسبق وفي حبلك انشوطة … ضغط الليالي بيد الحادثات"},{"id":"diwan-radi:110","bookId":"diwan-radi","type":"poem","seq":110,"chapter":"البحر: سريع","title":"قد آن أن يسمعك الصوت","page":"","text":"قد آن أن يسمعك الصوت … انائم قلبك ام ميت\nيا باني البيت على غرة ! … امامك المنزل والبيت\nأيجزع المرء لما فاته … وكل ما يدركه فوت\nوانما الدنيا على طولها … ثنية مطلعها الموت"},{"id":"diwan-radi:111","bookId":"diwan-radi","type":"poem","seq":111,"chapter":"البحر: مجزوء الرمل","title":"من معيد لي أيا","page":"","text":"من معيد لي أيا … مي بجزع السمرات\nوليالي بجمع … ومنى والجمرات\nوظباء حاليات … كظباء عاطلات\nرائحات في جلابي … ب الدجى مختمرات\nراميات بالعيون ال … نجل قبل الحصيات\nألعقر القلب راحوا … أم لعقر البدنات\nكيف اودعت فوادي … أعينا غير ثقات\nأيها القانص ما أح … سنت صيد الظبيات\nفاتك السرب ، وما زو … دت غير الحسرات\nيا وقوفا ما وقفن … في ظلال السلمات\nموقفا يجمع فتيا … ن الهوى والفتيات\nنتشاكى ما عنانا … بكلام العبرات\nنظر يشغل منا … كل عين بقذاة\nكم نأى ، بالنفر عنا … من غزال ومهاة\nآه من جيد إلى الدا … ر كثير اللفتات\nوغرام غير ماض … بلقاء غير آت\nفسقى بطن منى وال … خيف صوب الغاديات\nوزمانا نائم العذ … ال مامون الوشاة\nفي ليال كاللآلي … بالغواني مقمرات\nغرست عندي غرس ال … شوق ممرور الجناة\nأين راق لغرامي … وطبيب لشكاتي"},{"id":"diwan-radi:112","bookId":"diwan-radi","type":"poem","seq":112,"chapter":"البحر: وافر تام","title":"احن إلى لقائك كل يوم","page":"","text":"احن إلى لقائك كل يوم … وأسأل عن إيابك كل وقت\nواذكر ما مضى فيغيض صبري … وتنفر عبرتي ويبوح صمتي\nولي قلب ، إذا ذكر التلاقي … تظلم من يد البين المشت"},{"id":"diwan-radi:113","bookId":"diwan-radi","type":"poem","seq":113,"chapter":"البحر: خفيف تام","title":"قال لي عند ملتقى الركب عمرو","page":"","text":"قال لي عند ملتقى الركب عمرو … قوم العود بعدنا ، فانصاتا\nأين ذاك الصبا واين التصابي … سبقا الطالب المجد وفاتا\nمن قضى عقبة الثلاثين يغدو … راجعا يطلب الصبا ، هيهاتا\nلم تزل والمشيب غير قريب … ناعيا للشباب حتى ماتا\nكنت تبكي الأحياء فاستكثر اليو … م من الدمع ، واندب الأمواتا"},{"id":"diwan-radi:114","bookId":"diwan-radi","type":"poem","seq":114,"chapter":"البحر: كامل تام","title":"قد قلت للنفس الشعاع اضمها","page":"","text":"قد قلت للنفس الشعاع اضمها … كم ذا القراع لكل باب مصمت\nقد آن أن أعصي المطامع طائعا … لليأس جامع شملي المتشتت\nيقضي الحريص وليس يقضي اربه … متعللا ابدا بغير تعلة\nقل للذين بلوتهم ، فوجدتهم … آلا وغير الال ينقع غلتي\nاعددتكم لدفاع كل ملمة … عني ، فكنتم عون كل ملمة\nوتخذتكم لي جنة فكأنما … نظر العدو مقاتلي من جنتي\nسمع يبل بها الحسود غليلة … ومتى نبثن على عدو يشمت\nتابي ثمار ان تكون كريمة … وفروع دوحتها لئام المنبت\nلما رميت إليكم بمطامعي … كثر الخلاج مقلبا لرويتي\nووقفت دونكم وقوف مقسم … حذر المنية راجي الأمنية\nقد تؤمكم واخرى تنثني … عنكم وحزم الرأي للمتثبت\nلولا الحوادث ما افدت تجاربا … يعسو الرطيب ويقرح الجذع الفتي\nيأس ثنى سنن المطالب عنكم … ولوى الى الوطان عنق مطتي\nلا عذر لي الا ذهابي عنكم … فإذا ذهبت فيأسكم من رجعتي\nفلأرحلن رحيل لا متلهف … لفراقكم ، أبدا ، ولا متلفت\nولا نفضن يدي يأسا منكم … نفض الأنامل من تراب الميت\nولألمعن بكل بيت شارد … لمع المهند في يمين المصلت\nمن كل قافية تخب اليكم … بشواظها خبب الجواد المفلت\nوأقول للقلب المنازع نحوكم : … أقصر هواك لك اللتيا والتي\nأأهز من لا ينثني وأدير من … لا يرعوي والوم من لا يختتي\nيا ضيعة الامل الذي وجهته … طمعا إلى الأقوام بل يا ضيعتي\nوسرى السفائن ينثني بصدورها … موج كأسنمة الجمال الجلة\nقوم ، إذا حضروا الندي مهانة … عطست موارنهم بغير مشمت\nيا دهر ! حسبك قد أصبت مقاتلي … ما زلت تطلب بالمقادر غرتي\nما لي احيل على سواك بما جنى … قدر على قدر ، وأنت بليتي"},{"id":"diwan-radi:115","bookId":"diwan-radi","type":"poem","seq":115,"chapter":"قصائد","title":"وقفنا لهم من وراء الخطو","page":"","text":"وقفنا لهم من وراء الخطو … ب ، نطالعهم من خصاصاتها\nونرقب يوما كأيامها … وليلة نحس كليلاتها\nفإن عصا الدهر لما تدع … سياق الأمور لغاياتها\nوان الحبائفل منصوبة … فلا تستغروا بإفلاتها\nتسنمتموها طوال الذرى … فصبرا على بعد مهواتها\nومن أمطرته سماء الغنى … هوى في سيول قراراتها\nفيا لك دنيا تريش الرجا … ل وتنحي عليهم بمبراتها\nوان منائحها للفتى … لرهن له بنكاياتها\nفبيننا تقول له هاكها … إلى أن تقول له : هاتها\nألم تعلموا ان ايامكم … تعد إلى حين ميقاتها\nفكيف وثقتم باعوامها … ونحن نضن بساعاتها\nفلا تطلبن لهم عثرة … ستأتيهم هي من ذاتها\nتمر الليالي على نهجها … وتجري الخطوب لعاداتها"},{"id":"diwan-radi:116","bookId":"diwan-radi","type":"poem","seq":116,"chapter":"البحر: سريع","title":"يعبن موتاهم باحياثهم","page":"","text":"يعبن موتاهم باحياثهم … كما يعاب الحي بالميت\nقولكم زور ، وقولي لكم … يبقى بقاء الجبل المصمت"},{"id":"diwan-radi:117","bookId":"diwan-radi","type":"poem","seq":117,"chapter":"البحر: طويل","title":"رجونا أبا الهيجاء إذ مات حارث","page":"","text":"رجونا أبا الهيجاء إذ مات حارث … فمذ مضيا لم يبق للمجد وارث\nألا إن قرمي وائل ، ليلة السرى … اقاما وقد سار المطي الدلائث\nهما البازلان المقرمان تناوبا … عرى المجد لما عج بالعبء لاهث\nرفيقان ما باغاهما العز صاحب … نديمان ما ساقاهما المجد ثالث\nحسامان إن فتشت كل ضريبة … فأثرهما فيها قديم وحادث\nبقية أسياف طبعن مع الردى … فجاء وجاءت عاثيات وعائث\nاحقا بان المجد هيضت جبوره … وزال عن الحي الطوال الملاوث\nوايد على بسط السماح رقائق … وهن على قبض الرماح شرائث\nوسرب بنو حمدان كانوا حماته … رعت فيه ذؤبان الليالي العوائث\nفاين كفاة القطر في كل أزمة … وأين الملاجي منهم ، والمغاوث\nوأين الجياد المعجلات إلى الوغى … إذا غام بالنقع الملا المتواعث\nوأين الثنايا المطلعات عن الأذى … إذا ناب ضغاط من الأمر كارث\nإذا ما دعا الداعون للبأس والندى … فلا الجود منزور ولا الغوث رائث\nيرف على ناديهم الحلم والحجا … إذا ما لغا لاغ من القوم رافث\nمن المطمعين المجد بالبيض والقنا … ملاء المقاري ، والعريب غوارث\nإذا طرحوا عماتهم وضحت لهم … مفارق لم يعصب بها العار لائث\nبكتهم صدور المرهفات وبشرت … هجان المتالي والمطى الرواغث\nقروم على ما روحوا من وسوقها … ولا منهم الواني ولا المتماكث\nيخلى لهم من كل ورد جمامه … إذا وردوا والمعشبات الاثائث\nمشوا في سهول المجد حينا ووقفوا … بحيث ابتدت أوعاره والأواعث\nإذا ركبوا سال اللديدان بالقنا … وحنت مطاياها المنايا الروائث\nكأن الصقور اللامحات تلمظت … إلى الطعم وانصاعت لهن الأباغث\nمضوا لا الأيادي مخدجات نواقص … ولا مرر العلياء منهم رثائث\nولا طول النعماء فيهم مقلص … إذا علقته المعصمات الشوابث\nخلجتم لجساس بن مرة طعنة … رأى الجد فيها هجرس وهو عابث\nوغادرتم اشلاء بكر مقيمة … على العار لا تحثا عليها النبائث\nوقد كان دين في كليب وفى به … غريم مطول بالديون مماغث\nوقائع أيام كأن إكامها … بجاري دم الطعن ، الإماء الطوامث\nتعودون عنها في قناكم مباشم … وعند قنا بكر اليكم مغارث\nعقدتم بها حبلي أسار ومنة … وخانهم نقص القوى والنكائث\nتحللتم من نذر طعن ، وغيركم … كثير الألا ياغب ما قال حانث\nحروب من الأقدار طاح عراكها … بجرب ولم يسلم عليهن حارث\nوكان سنانا أوجر الخطب حده … وكان يدا أردي بها من ألاوث\nباخلاق اباء يعود بها الأذى … وعورا على الأعداء وهي دمائث\nأقول لناعيه إلى المجد والعلى : … رمى فاك مسموم الغرارين فارث\nكان سواد القلب طار بلبه … إلى الطود أقنى ينفض الطل ضابث\nورزء رمى بين القلوب شواظه … أجيج المصالي أسعرتها المحارث\nبرغمي تمسي نازلا دار هجرة … وأنت المصافي والقريب المنافث\nوان لا اجافي الترب عنك براحة … ولو نازعتنيها الرقاق الفوارث\nوان تشتمل ارض عليك فانما … على ماء عيني النقا والكثاكث\nسقى النضد النجدي ملقى ضرائح … بها منكم المستصرخون الغوايث\nفسيان فيها ، من وقار ومن على … عظامكم والراسيات اللوابث\nولا برحت بندى عقود صعيدها … نفاثة ما جاد الغمام النوافث\nلها خدشات بالموامي ، كأنها … على لقم البيداء أيد عوابث\nصبابة عز عب في مائها الردى … وعاد إليها وهو ظمأن غارث\nوافنان دوحات من المجد اشرعت … مشاظي الردى ما بينها والمشاعث\nوما كنت أخشى الدهر إلا عليهم … فهان الرزايا بعدهم والحوادث"},{"id":"diwan-radi:118","bookId":"diwan-radi","type":"poem","seq":118,"chapter":"البحر: كامل تام","title":"يا آمن الأقدار بادر صرفها","page":"","text":"يا آمن الأقدار بادر صرفها … واعلم بان الطالبين حثاث\nخذ من تراثك ما استطعت فإنما … شركاؤك الأيام والوراث\nلم يقض حق المال الا معشر … وجدوا الزمان يعيث فيه ، فعاثوا\nتحثوا على عيب الغني يد الغنى … والفقر عن عيب الفتى بحاث\nالمال مال المرء ما بلغت به الش … شهوات ، أو دفعت به الأحداث\nما كان منه فاضلا عن قوته … فليعلمن بأنه ميراث\nمالي إلى الدنيا الغرورة حاجة … فليخز ساحر كيدها النفاث\nطلقتها ألفا لأحسم داءها … وطلاق من عزم الطلاق ثلاث\nسكناتها محذورة وعهودها … منقوضة ، وحبالها أنكاث\nأم المصائب لا يزال يروعنا … منها ذكور نوائب وإناث\nإني لأعجب من رجال أمسكوا … بحبائل الدنيا ، وهن رثاث\nكنزوا الكنوز ، وأغفلوا شهواتهم … فالارض تشبع والبطون غراث\nاتراهم لم يعلموا ان التقى … أزوادنا ، وديارنا الأجداث"},{"id":"diwan-radi:119","bookId":"diwan-radi","type":"poem","seq":119,"chapter":"البحر: طويل","title":"خذوا نفثات من جوى القلب نافث","page":"","text":"خذوا نفثات من جوى القلب نافث … دفاين ضغن قد رمين بنابث\nلقد كن من قبل البواحث نزعا … فكيف بهن اليوم بعد البواحث\nعذيري من سيف رجوت قراعه … اعادي طرا من قديم وحادث\nفخان يدي ثم انثنى بغراره … فكان لعنقي اليوم أول فارث\nومن جبل اعددت شم هضابه … مردا لأيدي النائبات الكوارث\nفطوح لي من حالق ، وأزلني … زليل المطايا عن متون الأواعث\nومن مشرب انبطت ينبوع مائه … بأعلى الروابي والرياض الأثائث\nيضن علي اليوم منه بنهلة … وتبذل دوني للنقا والكثاكث\nهو الرزق مقسوما وليس تناله … ببرد التباطي أو بحر الحثاحث\nأعنتم على حربي المقادير عنوة … ورشتم إلى قلبي سهام الحوادث\nولم تدعوني والزمان فانه … لاكرم فعلا منكم في الهنابث\nكذاك من استدرى الى غير هضبة … وشد يدا بالمطمعات الرثائث\nدعائي ذئاب القاع خير مغبة … إذا ، من دعائي بعضكم للمغاوث\nفلو أنني أدعو لؤي بن غالب … لقد أنجدوني بالطوال الملاوث\nبجيش بهم وادي الظلام كانهم … صدور العوالي بالملا المتواعث\nهم اطلعوني بالنجاد وارزموا … لنصري إرزام المطي الرواعث\nوارخو خناقي بعد ما كان فتله … يغار على عنقي بأيد عوابث\nترى حلمهم تحت الظبى غير طائش … وخطوهم بين القنا غير رائث\nفلا الحلم بالنائي ، إذا ما دعوته … ولا العزم بالواني ولا المتماكث\nوكل فتى إن آد ثقل ملمة … تورك حنوي عبثها غير لاهث\nضنين بودي لا يزال بوجهه … كلام العدى عني ونفث النوافث\nشعاري من دون الشعار وتارة … قريبي من دون القريب المنافث\nتعممتموها سوأة جاهلية … لقد فاز من امسى بها غير لائث\nفجروا ذيول العار ثم تضائلوا … تضاؤل أطهار الإماء الطوامث\nتقطعت الأطماع فيكم ، ولم يدع … لكم املا لؤم الطباع الخوابث\nواصبحتم اطلال دار بقفرة … ترى الركب مجتازا بها غير لابث\nوكيف ارجيكم لدفع مغارم … وقد خاب راجيكم لدفع معارث\nقعوا وقعة الساري ، فقد طال حثكم … إلى العار ، أعناق المطي الدلائث\nفحتى متى اخفي الترات وانتم … تثيرون عن مدفونها بالمباحث\nوكم أدمل الأضغان بيني وبينكم … واغضي على نقض القوى والنكائث\nاذا رمت من سوأتكم سد هوة … تشاغلتم عن غيرها بالنبائث\nرأيت الصقور الغلب خمصى من الطوى … وما مطعم الدنيا لغير الاباغث\nفلا حظ في استنزال رزق محلق … ولا نفع في حث الحظوظ الروائث\nتركت صدوعا بيننا لانشعابها … ولم أتجشم لم تلك المشاغث\nفزيدوا ، فإني بعدها غير ناقص … وجدوا فإني بعدها غير عابث\nديون من الأضغان إن أبق أجزكم … يبهن وان اعطب يرثهن وارثي\nوإن أنس يوما ذمكم يمس فعلكم … على الذم عندي من أشد البواعث\nوان ابط يسرع بي الى ما يسؤكم … لواعج اضغان اليكم حثائث\nنحلت إذا ما فيكم من معائب … ونازعتكم طعمات تلك الخبائث\nلئن انا لم اعلق باعراض قومكم … براثن أظفار القريض الضوابث\nفوالله لا اقلعن الا دواميا … ألية بر لا ألية حانث\nلكي تعلموا غب العداوة بيننا … ويعرككم كيد المطول المماغث\nسلام على الآمال فيكم ، ولا سقى … معاهدها جود القطار الدثائث\nلعلمتموني اليأس من كل مطمع … وعودتموني الصبر في كل حادث\nوعرفتموني كيف التمس الجدا … الى غير ايدي الألأمين الشرابث\nتذللكم لقياي باليأس منكم … ولم أتذلل للمطال الملابث\nفشكرا لمن لم يجعل الرزق عندكم … فلا ري ظمآن ولا شبع غارث\nلئن ساءكم مني حزون خلائقي … فقد طال ما لم انتفع بالدمائث\nخذوها كاطواق الحمام فانها … ستبقى بقاء الراسيات اللوابث\nقوافي يقطرن النجيع كانما … طبعن على طبع الرقاق الفوارث\nإذا ما مطلناهن بقيا عليكم … خرجن خروج الخالعين النواكث\nفآليت لا أعطي اللئام مقادة … ولو تحت ضغاط من الامر كارث\nذنوبي أن استمطرت من غير ماطر … وأني طلبت الغيث من غير غائث"},{"id":"diwan-radi:120","bookId":"diwan-radi","type":"poem","seq":120,"chapter":"البحر: طويل","title":"وان لنا النار القديمة للقرى","page":"","text":"وان لنا النار القديمة للقرى … تورث من اولى الزمان وتورث\nلنا القدم الأولى إلى كل غاية … وسعيان شيء فارط وملبث\nوفي الناس أخياف جهام وماطر … وناب ، ومضاء ، وباز ، وأبغث"},{"id":"diwan-radi:121","bookId":"diwan-radi","type":"poem","seq":121,"chapter":"البحر: طويل","title":"لي الحرب معطوفا علي هياجها","page":"","text":"لي الحرب معطوفا علي هياجها … وظل جوادي قيظها وعجاجها\nويأنف عزمي ان يرد رماحها … اذا اشتبهت خرصانها وزجاجها\nفما بال بغداد اذا اشتقت رحلة … تشبث بي غيطانها وفجاجها\nكأن لها دينا علي ، وإنني … سيطلبها سيقي وديني خراجها\nابغداد مالي فيك نهلة شارب … من العيش الا والخطوب مزاجها\nولو أنني أرضى بأدنى معيشة … لأرضت منائي عند أهليك حاجها\nولكنني جار على حكم همة … كثير عن الطبع الذليل انعراجها\nيخيل لي ان الاماني غياهب … ولا تنجلي الا وعزمي سراجها"},{"id":"diwan-radi:122","bookId":"diwan-radi","type":"poem","seq":122,"chapter":"البحر: وافر تام","title":"أداري المقلتين عن ابن ليلى","page":"","text":"أداري المقلتين عن ابن ليلى … ويأبى دمعها إلا لجاجا\nلها ثبط على الايام باق … تجيش بها معينا أو اجاجا\nكأن بها ركية مستميت … يخضخضها بكورا وادلاجا\nأذود النفس عنه ، وذاك منها … عنان ما ملكت له معاجا\nكان العين بعد اليوم جرح … إذا طبوا له غلب العلاجا\nتجم على القذى وتفيض دمعا … مطل الداء وادع ثم هاجا\nواين كفارس الفرسان عمرو … اذا رزء من الحدثان فاجا\nبحق كان أولهم ولوجا … على هول وآخرهم خراجا\nاذا رسبت حصاة القلب منه … طفا قلب الجبان به انزعاجا\nبكيتك للسوابق موضعات … قماص السرب أعجز أن يعاجا\nيقرطها الاعنة مبدلات … مكان جلالها العلق المجاجا\nيدعن على الاجالد موضحات … كأن على مفارقها شجاجا\nوارقاص المطي على وجاها … يجبن إلى العلى طرقا نهاجا\nمرنقة العيون كأن فيها … دهان مواقد يصف الزجاجا\nورثت عن الابين قنا وبأسا … فأنفقت اللهاذم والزجاجا\nومنخرق اخوت السيف فيه … وحبل الليل يندمج اندماجا\nأرابك ، فاكتلأت بغير رمح … كأن على عوامله سراجا\nتوقر جاشك الاهوال فيه … اذا اعتلج الجبان به اعتلاجا\nوقد جاب الذميل عليك وهنا … من الظلماء مدرعة وساجا\nومزلقة ترش بها المنايا … وتسمع للقلوب بها رجاجا\nوفقت بشوك أخمصك العوالي … ويلقى المرء للغم انفراجا\nومظلمة من الغمرات عطشى … جعلت لها من القضب انبلاجا\nومائلة أقمت لها كعوبا … وقد شغرت على القوم اعوجاجا\nوداهية تشول بالذنابى … غدوت لباب مطلعها رتاجا\nومعضلة كفيت وذات وهي … شددت لها العراقي والعناجا\nوفاصلة كسيل الطود عجلى … قطعت بها التشادق والضجاجا\nوآنية اللحوم من القضايا … اعدت لهن كيا أو نضاجا\nوشاردة ربطت لها الحوايا … وقد مرح البطان بها وماجا\nوراي يفرق الجلى ويهدي … وراء مضيقها سبلا فجاجا\nقطعت بمطربيه على تمار … خلاج الشك ، إن له خلاجا\nكانك صبت منه بذات فرع … على البوغاء لبدت العجاجا\nكمزلقة الذباب اذا امرت … على ذي الداء بالغت الوداجا\nلئن نبحته آونة كلاب … لقد لبست به الأسد المهاجا\nفمن يزع العريب اذا تناغت … ويضرب بين غاربها سياجا\nويذكرها الحلوم على تناس … وقد بلغت حفائظها الهياجا\nيحاججها عن الأرحام ، حتى … يقر القوم ان له الحجاجا\nومن رد النقائذ بعد يأس … وقد جاوزن ضورا والولاجا\nتغلغل في النفاق قني سعد … رواغ الذئب قد ولج الحراجا\nتمادحت الرباب به وكانت … تنابز بالمعائب أو تهاجا\nبرغمي ان يكن قنا تميم … قضين على الذنائب منك حاجا\nحميت منابت الرمرام منهم … واخليت الاناعم والنباجا\nمنعتهم اللقاح وملقحات … يكاد الخوف يمنعها التناجا\nفما لقحت لهم الا اختلاسا … ولا ولدت لهم إلا خداجا\nأبى الباغون مثل مداك إلا … ضلالا عن طريقك وانعراجا\nسابعثها عليك مسقفات … طباق الأرض ، أطلعها الفجاجا\nمسالات الاغرة ملجمات … وحادا أو مقرنة زواجا\nوأجعلها سلوا بعد يأس … ومن الم الصدا ورد الاجاجا\nاقاض حق قبرك ذوا غرام … اعادج الركب عن طرب وعاجا\nيريق عليك ماء القلب صرفا … وماء العين يجعله مزاجا\nولو بلغ المنى انسان عيني … خلا منها وأسكنك الحجاجا"},{"id":"diwan-radi:123","bookId":"diwan-radi","type":"poem","seq":123,"chapter":"البحر: مجزوء الكامل","title":"لا تيأسن ، فربما","page":"","text":"لا تيأسن ، فربما … عظم البلاء وفرجا\nقد ينسخ الخوف الامان … ويغلب اليأس الرجا"},{"id":"diwan-radi:124","bookId":"diwan-radi","type":"poem","seq":124,"chapter":"البحر: كامل تام","title":"اني اذا حلب البخيل لبانها","page":"","text":"اني اذا حلب البخيل لبانها … أمسيت أحلبها دم الأوداج\nخطبتني الدنيا فقلت لها ارجعي … اني اراك كثيرة الازواج"},{"id":"diwan-radi:125","bookId":"diwan-radi","type":"poem","seq":125,"chapter":"البحر: سريع","title":"والعيس قد نشف منها السرى","page":"","text":"والعيس قد نشف منها السرى … صفو العريكات ونقى الأجاج\nلم يبق الا مضغ لاكها … طول الطوى واسترطتها الفجاج"},{"id":"diwan-radi:126","bookId":"diwan-radi","type":"poem","seq":126,"chapter":"البحر: وافر تام","title":"أغار على ثراك من الرياح","page":"","text":"أغار على ثراك من الرياح … وأسأل عن غديرك والمراح\nوأجهر بالسلام ودون صوتي … منيع لا يجاوز بالصياح\nوأهوى أن يخالطك الخزامى … ويلمع في أباطحك الأقاحي\nوكم لي نحو أرضك من مسير … دفعت به الغدو إلى الرواح\nوهذا الدهر خفض من عرامي … ورنق من غبوقي واصطباحي\nوقد كان الملام يطيف مني … بمنجذب العنان الى الجماح\nتؤول النائبات إلى مرادي … ويعطيني الزمان على اقتراحي\nوعالية السوالف والهوادي … تدافع في الاسنة والصفاح\nاذا استقصين غامضة الدياجي … فقأت بهن عاشية الصباح\nومدرع سموت له مغذا … وقد غرض المقارع بالرماح\nبنافذة تمطق عن نجيع … تمطق شارب المقر الصراح\nوأخرى في الضلوع لها هدير … هدير الفحل قرب للقاح\nفما لي تطلب الأعداء حربي … ويصبح جانبي غرض اللواح\nأبا هرم ، وأنت تريد ضيمي … بأي يد تطامن من طماحي\nلحقت ابي نزاعا في المعالي … وعرقا في الشجاعة والسماح\nوانت فما لحقت اباك الا … كما لحق الذنابى بالجناح\nنميت من العقوق إلى المخازي … كما ينمى الهرير إلى النباح\nفنحن نرى مكانك من نزار … مكان الداء في الأدم الصحاح\nبني مطر دعوا العلياء يطلع … إليها كل منذلق وقاح\nوولوا عن مقارعة المنايا : … ولقيان الملمة الرداح\nايخفى لؤم اصلكم وهذي … قروفكم تنم على الجراح\nتعيرنا القبائل أن قطعنا … قرائن عامر وبني رياح\nوعلقنا مطامعنا بحبل … تعلقه القلوب بغير راح\nوكلهم يجرون العوالي … محافظة على عشب البطاح\nفبلغ سادة الأحياء أنا … سلونا بالغنا ضرب القداح\nوعفنا القاع نسكنه وملنا … عن السمرات والنعم المراح\nوطبقت العراق لنا قباب … نظللها باطراف الرماح\nنعلل بالزلال من الغوادي … ونتحف بالنسيم من الرياح\nوجاورنا الخليفة حيث تسمو … عرانين الرجال الى الطماح\nنوجه بالثناء له مصونا … ونرتع منه في مال مباح\nوسيال اليدين من العطايا … مهيب الجد مأمون المزاح\nاذا ابتدر الملام ندى يديه … مضى طلقا على سنن المراح\nأمير المؤمنين أذال سيري … ذرى هذي المعبدة الرزاح\nفكم خاض المطي إليك بحرا … يموج على الأماعز والضواحي\nسراب كالغدير تعوم فيه … ربا كغوارب الابل القماح\nوكم لك من غرام بالمعالي … وهم في الاماني وارتياح\nوايام تشن بها المنايا … عوابس يطلعن من النواحي\nاذا ريع الشجاع بهن قلنا … لأمر غض بالماء القراح\nفلانقل المهيمن عنك ظلا … من النعماء ليس بمستباح\nوواجهك الثناء بكل أرض … معاونة لشكري وامتداحي"},{"id":"diwan-radi:127","bookId":"diwan-radi","type":"poem","seq":127,"chapter":"البحر: وافر تام","title":"تخطينا الصفوف الى رواق","page":"","text":"تخطينا الصفوف الى رواق … تحجب بالصوارم والرماح\nوحيينا عظيما من قريش … كان جبينه فلق الصباح\nعليه سيمياء الملك يبدو … وعنوان الشجاعة والسماح"},{"id":"diwan-radi:128","bookId":"diwan-radi","type":"poem","seq":128,"chapter":"البحر: بسيط تام","title":"مثال عينيك في الظبى الذي سخا","page":"","text":"مثال عينيك في الظبى الذي سخا … ولى ، وما دمل القلب الذي جرحا\nفرحت أقبض أثناء الحشا كمدا … وراح يبسط اثناء الخطى مرحا\nصفحت عن دم قلب طله هدرا … بقيا عليه ، فما أبقى ولا صفحا\nحمى له كل مرعى سهم مقتله … ومورد الماء مغبوقا ومصطبحا\nاما تح انت غرب الدمع من كمد … على الظعائن اذ جاوزن مطلحا\nأتبعتهم نظرا تدمى أواخره … وقد رملن على رمل العقيق ضحى\nفيهن أحوى غضيض الطرف رعيته … حب القلوب إذا ما راد أو سرحا\nعندي من الدمع ما لو كان وارده … مطي قومك يوم الجزع ما نزحا\nغادرن اسوان ممطورا بعبرته … ينحو مع البارق العلوي أين نحا\nيروعه الركب مجتازا ويزعجه … زجر الحداة تشل الاينق الطلحا\nهل يبلغنهم النفس التي ذهبت … فيهم شعاعا أو القلب الذي قرحا\nان هان سفح دمي بالبين عندهم … فواجب أن يهون الدمع إن سفحا\nقل للعواذل مهلا فالمشيب غدا … يغدو عقال لذي القلب الذي طمحا\nهيهات أحوج مع شيبي إلى عذل … فالشيب اعذل ممن لامني ولحا\nقف طالعا أيها الساعي ليدركني … فبعدك الجزع المغرور قد قرحا\nلا عز اخبثنا عرقا واهجننا … اما واصلدنا زندا اذا قدحا\nظن راسك قد اعياك محمله … ورب ثقل تمناه الذي طرحا\nكم المقام على جيل سواسية … نرجو الندى من إناء قل ما رشحا\nتشاغل الناس باستدفاع شرهم … عن ان يسومهم الاعطاء والمنحا\nفي كل يوم يناديني لبيعته … مشمر في عنان الغي قد جمحا\nان تمنين لمنديل اذا لكم … متى يشا ماسح منكم بها مسحا\nالام اصفيكم ودي على مضض … وكم أنير وأسدي فيكم المدحا\nيروم نصحي أقوام وروا كبدي … والعجز أن يجعل الموتور منتصحا\nارى جناني قد جاشت حلائبه … ما يمنع القلب من فيض وقد طفحا\nشمر ذويلك ، واركبها مذكرة … واطلب عن الوطن المذموم منتدحا\nوحمل الهم ، إن عناك نازله … غوارب الليل والعيرانة السرحا\nوانفض رجالا سقوك الغيظ أذنبة … وأورثوك مضيض الداء والكشحا\nان عاينوا نعمة ماتوا بها كمدا … وان رأوا غمة طاروا بها فرحا\nأوهت أكفهم بيني وبينهم … فتقا بغير العوالي قل ما نصحا\nنالوا المعالي ولم تعرق جباههم … فيها لغوبا ، وما نال الذي كدحا\nسائل عن الطود لم خفت قواعده … وكان ان مال مقدار به رجحا\nقد جربوه ، فما لانت شكيمته … وحملوه فما اعيا ولا رزحا\nرموا به الغرض الأقصى ، فشافهه … مر القطامى جلى بعد ما لمحا\nمن العراق الى اجبال خرمة … يا بعده منبذا عنا ومطرحا\nليس الملوم الذي شد اليدين به … بل الملوم المرزا من به سمحا\nهو الحسام ، فمن تعلق يداه به … يضمم على الصفقة العظمى وقد ربحا\nان اغمدوه فلم تغمد فضائله … ولا نأى ذكره الداني ، وقد نزحا\nأهدى السلام إليك الله ما حملت … غوارب الإبل الغادين والروحا\nولا اغب بلادا انت ساكنها … مسرى نسيم يميط الداء إن نفحا\nأغدو على سبل الأنواء مشترطا … سقياك في البلد النآي ومقترحا\nافردت للهم صدرا منك متسعا … على الهموم ، وقلبا منك منشرحا\nكساهم البهمة الدهماء عجزهم … والعزم البسك التحجيل والفرحا\nعل الليالي أن تثنى بعاطفة … فيستقيل زمان بعدما اجترحا\nكما رمى الداء عضوا بعد صحته … كذا اذا التاث عضور بما اصطلحا\nوكم تلاحم كرب عند معضلة … فانجاب عن قدر لله ، وانفسحا\nارى رجالا كبهم القاع عندهم … سيان من مزق الآراء أو صرحا\nيعلو على قلل الاعناق بينهم … من غش رئا ويوطا عنق من نصحا\nتظاهروا بنفاق الغي عندهم … حتى ادعاه على مكروهه الفصحا"},{"id":"diwan-radi:129","bookId":"diwan-radi","type":"poem","seq":129,"chapter":"البحر: متقارب تام","title":"برؤم السيوف وغرب الرماح","page":"","text":"برؤم السيوف وغرب الرماح … عقدنا لواء العلى والسماح\nوكل غلام حيي اللحاظ … يلقى الطعان برمح وقاح\nإذا مطل الثار جر القنا … نشاوى تقاضى صدور الصفاح\nفأغمدها في احمرار الشقي … وجردها في بياض الاقاح\nبكل فلاة تقود الجياد … تعثر فيها ببيض الأداحي\nفليلجم اعناقها بالجبال … وينعل ارساغها بالبطاح\nوأشقر يسرق صبغ المدا … انهبت جلدته للسلاح\nاذا يابس الماء بل الحزام … طارت به غلواء المراح\nتجول القرون باعطافه … مجال الفواقع في كاس راح\nيشق الظلام بسيف الضحى … ويرمي الغدو بسهم الرواح\nفيا راكب العجز مرخي العنان … للذل يخبط ، والعز ضاح\nتقاض المطالب واستنبط ال … رجاء ونبه عيون النجاح\nفلولا المطامع تحدو الطلاب … لما خفقت قادمات الجناح\nوما العيش عندي الا الاباء … وبعدي عن المنزل المستباح\nأحب الخيام وسكانها … وأحسد كل بعيد المراح\nوأغبط كل فتى لا يزال … عبئا على الزاعبات القماح\nيخاطر فيها بعقز السوام … ويشرب منها لبان اللقاح\nطروب المسامع اين استقل … صهيل الجياد وجرس النباح\nومن لي بأن أتلافى الخطوب … ان نافرتني صدور الرماح\nومن لي بتقبيل كف الزما … ن من قبل توقيعها باطراحي\nكبا الدهر بيني وبين المنى … وطال بزند الرجاء اقتداحي\nارى الحلم يطوي سباب الرجال … والجهل ينشره في التلاحي\nفيحسب عيا سكوت الحليم … ويعطى السفيه حظوظ الفصاح\nأكاشر أبناء هذا الزمان … وأهزأ من نبلهم بامتداحي\nفبين البواطن حل الطلاق … وبين الظواهر عقد النكاح\nوإني لأحفظ غيب الخليل … إن ضاع واستلبته اللواحي\nواني لاقصف بطش الفتى … ولو رد باع القضاء المتاح\nتكدر دوني نطاف الكلام … وأصقلها بالبيان الصراح\nأدافع بالجد عن غاية … ولو شئت بلغتها بالمزاح\nأراني سيخلق عمري الزمان … وكل ظلام جديد الصباح\nزجرت السرور فما يجتنى … بغير العلى طلبي وارتياحي\nفبالله يا نشوات الشمول … عودي إلى نفحات الرياح\nوصوني عن السكر من لا يزال … يندي المدام بماء القراح\nاعاف ابنة الكرم لا ابن الغمام … بين غبوقي وبين اصطباحي\nيمر الغناء فيعتاقني … وعشق الحروب ثني من جماحي\nولو لم أغن بذكر السيوف … لقل على النغمات ارتياحي\nوسمراء ترشف ظلم القلو … قذافة بالنجيع المباح\nتطارد في كل ملمومة … منطقة بالعوالي رداح\nتريق عليها كؤوس الدما … بالطعن والموت نشوان صاح\nفنخضب فيها جباه الظبى … ونرمد فيها عيون الجراح\nكأنا نرى الضرب نحر السوام … ونحتسب الطعن ضرب الصفاح\nفمن ذا أسامي ، وجدي النبي … أم من أطاول أم من ألاحي\nانا ابن الائمة والنازلين … كل منيع الربى والبراح\nوايد تصافح ايدي الكرام … وإن نفرت من أكف الشحاح\nاذا استصرخوا عصفوا بالصباح … بين الظبي والوجوه الصباح\nوسالوا الى الطعن سيل القنا … ومالوا على الضرب ميل الصفاح\nنشرنا على عذبات الرياح … ح كل لواء صقيل النواحي\nوأحسابنا ساميات الأنوف … بين المقام وبين الضراح"},{"id":"diwan-radi:130","bookId":"diwan-radi","type":"poem","seq":130,"chapter":"البحر: كامل تام","title":"بعض الملام فقد غضضت طماحي","page":"","text":"بعض الملام فقد غضضت طماحي … وكفيت من نفسي العذول اللاحي\nمن بعد ما خطر الصبا بمقادتي … وجرى الى الامد البعيد جماحي\nعشرون اوجف في البطالة خلفها … عامان غلا من يدي مراحي\nزمن يخف به الجناح إلى الصبا … لما ظفرت به خفضت جناحي\nأغضي عن المرأى الأنيق زهادة … فيه وادفع لذتي بالراح\nأمعاهد الأحباب ! هل عود إلى … مغدى نبل به الجوى ومراح\nيكفيك من انفاسنا ودموعنا … ان تمطري من بعدنا وتراحي\nفلرب عيش فيك رق نسيمه … كالماء رق على جنوب بطاح\nوتغزل كصبا الأصائل أيقظت … ريا خزامى باللوى واقاح\nكم فيك من صاح الشمائل منتش … بالذل ، أو مرضى العيون صحاح\nفسقى اللوى صوب الغمام ودره … وسقى النوازل فيه صوب الراح\nوغدا فروح ذاك عن تلك الربى … وسرى فروح ذاعن الارواح\nفلطالما اقصدنني ظبياته … وارقت فيه لبارق لماح\nوالتحت من كمد إليه ، وورده … ناء يعذب غلة الملتاح\nأيام في صبغ الشباب ذوائبي … وإلى التصابي غدوتي ورواحي\nقومي أنوف بني معد والذرى … من واضح فيهم ومن وضاح\nالسابقون الى علا ومفاخر … والغالبون على ندى وسماح\nذهبوا بشأو المجد ثم تلفتوا … هزوا الى الطلاع والطلاح\nشوس الحواجب مغضبين وفي الرضى … ما شئت من بيض الوجوه صباح\nورثوا المعالي بالجدود وبعدها … بضراب مرهفة وطعن رماح\nوقياد مخطفة الخصور كانها … العقبان تحت مجلجل دلاح\nيغبقن ليلا بالغبيق وتارة … يصبحن بالغارات كل صباح\nضربت بعرقي دوحة نبوية … في منصب واري الزناد صراح\nينمى إلى أعياص خير أرومة … ليست بعشات الفروع ضواح\nوابي الذي حصد الرقاب بسيفه … في كل يوم تصادم ونطاح\nردت إليه الشمس يحدث ضوءها … صبحا على بعد من الاصباح\nسائل به يوم الزبير مشمرا … يختال بين ذوابل وصفاح\nواسأل به صفين إن زئيره … اودي بكبش امية النطاح\nواسأل شراة النهروان ، فإنهم … ضربوا بمنذلق اليدين وقاح\nكم من طعين يوم ذاك مرمل … وحريم عز بالطعان مباح\nومناقب بيض الوجوه مضئة … أبدا ، تكاثر ألسن المداح\nمن قاس ذا شرف به فكأنما … وزن الجبال القود بالاشباح\nقد قلت للعادي علي ببغيه … مهلا فما يلحو القتادة لاحي\nفحذار إن مطرت عليك صواعقي … وحذار ان هبت عليك رياحي\nاو في الصباح فشق كل دجنة … وعلا الزئير فغض كل نباح\nأنا من علمت ، على المكاشح مرهف … نابي وشاك في الخصام سلاحي\nوابيت ان اعطي الاعادي مقودي … او ان تدر على الهوان لقاحي\nمن بعد ما أوضعت في طرق العلى … وأضر بالاعداء طول كفاحي\nوسحبت من خلع الخلائف طارفا … لحظات كل معاند طماح\nووليا في السن القريبة اسرتي … فوكلت فاسدهم الى اصلاحي\nبمهابة عمت بغير تكبر … وصرامة أدمت بغير جراح\nحلم كحاشية الرداء ، ودونه … بأس يدق عوامل الارماح\nفلئن علوتهم ، فليس بمنكر … اما علت غرر على اوضاح\nفالان امدح غير مولى نعمة … لو كنت أنصف كان من مداحي\nبعدا لدهر خاض بي أهواله … واجازني غمرا الى ضحضاح\nلادر دري ان رضيت بذلة … تلوي يدي وترد غرب طماحي\nمن دون قود الجرد تمري جريها … ربلات كل مغامر جحجاح\nعنقا على عنق الطلاب تحثها … همم ضمن عوائد الانجاح\nفظع البلاد وراء قاضية العلى … متغربا عن موطني ومراحي\nاشهى الي من النعيم يدوم لي … والذ من نعم علي مراح\nانى الى العذب النمير اصابني … بيد الهوان شربت بالأملاح\nدعني اخاطر بالحيوة وانما … طلب الرجال العز ضرب قداح\nاما لقاء الملك قسرا أو كما … لقى ابن حجر من يدي الطماح"},{"id":"diwan-radi:131","bookId":"diwan-radi","type":"poem","seq":131,"chapter":"البحر: سريع","title":"نبهتهم مثل عوالي الرماح","page":"","text":"نبهتهم مثل عوالي الرماح … إلى الوغى قبل نموم الصباح\nفوارس نالوا المنى بالقنا … وصافحوا اعراضهم بالصفاح\nلغارة سامع انبائها … يغص منها بالزلال القراح\nليس على مضرمها سبة … ولا على المجلب منها جناح\nدونكم ، فابتدروا غنمها … دمى مباحات ، ومال مباح\nفاننا في ارض اعدائنا … لا نطأ العذراء إلا سفاح\nيا نفس من هم إلى همة … فليس من عبء الأذى مستراح\nقد آن للقلب الذي كده … طول مناجاة المنى أن يراح\nلا بد أن أركبها صعبة … وقاحة تحت غلام وقاح\nيجهدها ، أو ينثني بالردى … دون الذي قدر أو بالنجاح\nالراح والراحة ذل الفتى … والعز في شرب ضريب اللقاح\nفي حيث لا حكم لغير القنا … ولا مطاع غير داعي الكفاح\nما أطيب الأمر ، ولو أنه … على رزايا نعم في مراح\nوأشعث المفرق ذي همة … طوحه الهم بعيدا فطاح\nلما رأى الصبر مضرا به … راح ، ومن لم يطق الذل راح\nدفعا بصدر السيف لما رأى … ألا يرد الضيم دفعا براح\nمتى ارى الزوراء مرتجة … تمطر بالبيض الظبي أو تراح\nيصيح فيها الموت عن ألسن … من العوالي والمواضي فصاح\nبكل روعاء عظينية … يحتثها أروع شاكي السلاح\nكانما ينظر من ظلها … نعامة زيافة بالجناح\nمتى ارى الارض وقد زلزلت … بعارض اغبر دامي النواح\nمتى ارى الناس وقد صبحوا … أوائل اليوم بطعن صراح\nيلتفت الهارب في عطفه … مروعا يرقب وقع الجراح\nمتى ارى البيض وقد امطرت … سيل دم يغلب سيل البطاح\nمتى ارى البيضة مصدوعة … عن كل نشوان طويل المراح\nمضمخ الجيد نؤوم الضحى … كأنه العذراء ذات الوشاح\nاذا رداح الروع عنت له … فرالى ضم الكعاب الرداح\nقوم رضوا بالعجز واستبدلوا … بالسيف يدمى غربه كاس راح\nتوارثوا الملك ، ولو أنجبوا … لورثوه عن طعان الرماح\nغطى رداء العز عوراتهم … فافتضحوا بالذل أي افتضاح\nإني والشاتم عرضي كمن … روع اساد الشرى بالنباح\nيطلب شأوى وهو مستيقن … ان عناني في يمين الجماح\nفارم بعينيك مليا ترى … وقع غباري في عيون الطلاح\nوارق على ظلعك هيهات ان … يزعزع الطود بمر الرياح\nلا هم قلبي بركوب العلى … يوما ولا بل يدي السماح\nإن لم أنلها باشتراط ، كما … شئت على بيض الظبى واقتراح\nافوز منها باللباب الذي … يغني الأماني نيله والصراح\nفما الذي يقعدني عن مدى … لا هو بالنسل ولا باللقاح\nطليحة مد باضباعه … وغر قبلي الناس حتى سجاح\nيطمح من لا مجد يسمو به … اني اذا اعذر عند الطماح\nوخطة يضحك منها الردى … عشراء تبري القوم بري القداح\nصبرت نفسي عند أهوالها … وقلت : من هبوتها لا براح\nاما فتى نال العلى فاشتفى … او بطل ذاق الردى فاستراح"},{"id":"diwan-radi:132","bookId":"diwan-radi","type":"poem","seq":132,"chapter":"البحر: كامل تام","title":"في كل يوم للأحبة مطرح","page":"","text":"في كل يوم للأحبة مطرح … وعلى المنازل للمدامع مسفح\nشوق على نأي الديار مغالب … وجوى على طول المطال مبرح\nنفرت بنات الصبر منك وطالما … قصرت نوازع عن ضميرك تطمح\nيا هل يمانع بعد طول قياده … قلب يطاوع في القياد ويسمح\nوعلى المطي ظباء وجرة كلما … غفل المراقب تشرئب وتسنح\nخالسننا النظر المريب كما رنت … بقر الجواء الى وميض يلمح\nيبسمن عن برد الغمام وبرده … ريان يغبق بالمدام ويصبح\nكلفت عينك نظرة مزؤودة … منعتك لذتها مدامع تسفح\nأمسوا كأن لطائما دارية … باتت تضوع من القباب وتنفخ\nملكوا ولما يحسنوا وولوا ول … يعدلوا وغنوا ولما يسمحوا\nقل لليالي قد ملكت فاسجحي … ولغيرك الخلق الكريم الأسجح\nمن اي خطب من خطوبك اشتكي … وعن أي ذنب من ذنوبك أصفح\nان اشك فعلك من فراق احبتي … فلسوء فعلك في عذاري اقبح\nضوء تشعشع في سواد ذؤابي … لا أستضيء به ولا أستصبح\nبعت الشباب به على مقة له … بيع العليم بانه لا يربح\nلا تنكرن من الزمان غريبة … ان الخطوب قليبها لا ينزح\nللذل بين الأقربين مضاضة … والذل ما بين الاباعد اروح\nواذا رمتك من الرجال قوارص … فسهام ذي القربى القريبة اجرح\nاليس نسيج الذل ان البسته … متململا ، وإناء قلبك يطفح\nما دمت تنتظر العواقب لابدا … لا تغتدي لعلى ولا تتروح\nوضجيعك العضب الذي لا ينتضى … وخليطك الزور الذي لا يبرح\nواعلم بأن البيت ، إن أوطنته … سجن وطول الهم غل يجرح\nأأخي لا تك مضغة مزرودة … تنساغ لينة القياد وتسرح\nالا ابيت وانت من جمراتها … ومن العجائب جمرة لا تلفح\nكن شوكة يعيي انتقاش شباتها … او حمضة يشجي بها المتملح\nوانفض يديك من الثراء فكم مضى … من دون ثروته البخيل المصلح\nيبقى لوارثه كرائم ماله … ولقد يرقع عيشه ويرقح\nقد ينتج المروء العشار بجده … وسواه يعتام الفحول ويلقح\nلا عذر الا ان ارى سرباتها … سوم الجراد يثور منها الابطح\nوالهام تعتصب العجاج كانه … في الجو شؤبوب الغمام الأملح\nقومي الأولى ضمنت لهم أحسابهم … تان الزمان بمثلهم لا يسمح\nعركوا أديم الأرض قبل نباتها … واستفسحوا أعطانها وتفيحوا\nفتقوا بشزر الطعن اكمام العلى … وهم جذاع قبائل لم يقرحوا\nان اخرجوا لم يجهلوا واذا قضوا … لم يقسطوا اذا علوا لم يبجحوا\nذنبي إلى البهم الكواذب أنني ال … الطرف المطهم والاغر الاقرح\nيولونني خزر العيون لانني … غلست في طلب العلى وتصبحوا\nوجذبت بالطول الذي لم يجذبوا … ومتحت بالغرب الذي لم يمتحوا\nمن كل حامل احنة لا تنجلي … غطشى دجنتها ولا تتوضح\nضب يداهنني ، ويشكل غيبه … مما يرغى قوله ويصرح\nيغدوا ومرجل ضغنه متهزم … أبدا علي ، وجرحه متقرح\nمسحت جباه الوانيات ولطمت … من دون غايتها العتاق القرح\nلو لم يكن لي في القلوب مهابة … لم يطعن الاعداء في ويقدح\nمن خيف خوف الليث خطله الربى … وعوت لتشهره الكلاب النبح\nنظروا بعين عداوة لو انها … عين الرضى لاستحسنوا ما استقبحوا\nما كان من شعث فاني منهم … لهم أود على البعاد وأسمح"},{"id":"diwan-radi:133","bookId":"diwan-radi","type":"poem","seq":133,"chapter":"البحر: طويل","title":"سليمان لو وفيت مدحي حقه","page":"","text":"سليمان لو وفيت مدحي حقه … أريتك أسباب المنى كيف تنجح\nبسطت يدي حتى ظننتك فابضا … يد الدهر عني ، وهو أزور أكلح\nفأقصدتني باليأس حتى تركتني … وظني عن نيل الغنى يتزحزح\nوأصعبت لي من بعد ما كنت مسهلا … مغالق بر شارفت تتفتح\nفمن ماله في ذمة كيف يجتدي … ومن أصله في ظلمه كيف يمدح"},{"id":"diwan-radi:134","bookId":"diwan-radi","type":"poem","seq":134,"chapter":"البحر: وافر تام","title":"أعيذك من هجاء بعد مدح","page":"","text":"أعيذك من هجاء بعد مدح … فعذني من قتال بعد صلح\nمنحتك جل أشعاري فلما … ظفرت بهن لم أظفر بمنح\nكبا زندي بحيث رجوت منه … مساعدة الضياء فخاب قدح\nوكنت مضافري فثلمت سيفي … وكنت معاضدي فقصفت رمحي\nوكنت ممنعا فاذل داري … دخولك ذل ثغر بع فتح\nفيا ليثا دعوت به ليحمي … حماي من العدى فاجتاح سرحي\nويا طبا رجوت صلاح جسمي … بكفيه ، فزاد بلاء جرحي\nويا قمرا رجوت السير فيه … فلثمه الدجى عني بجنح\nسأرمي العزم في ثغر الدياجي … واحدو العيس في سلم وطلح\nلبشر مصفق الأخلاق عذب … وجود مهذب النشوات سمح\nوقور ما استخفته الليالي … ولا خدعته عن جد بمزح\nاذا ليل النوائب مد باعا … ثناه عن عزيمته بصبح\nوان ركض السؤال الى نداه … تتبع إثر وطأته بنجح\nوأصرف همتي عن كل نكس … أمل على الضمائر كل برح\nيهددني بقبح بعد حسن … ولم أر غير قبح بعد قبح"},{"id":"diwan-radi:135","bookId":"diwan-radi","type":"poem","seq":135,"chapter":"البحر: طويل","title":"أبثك أني راغب عن معاشر","page":"","text":"أبثك أني راغب عن معاشر … يضنون بالود القليل واسمح\nإذا ما جنوا ذنبا علي احتقرته … فأعفو عن الذنب العظيم وأصفح\nويظهر لي قوم بعادا وجفوة … وما علموا أني بذلك أفرح"},{"id":"diwan-radi:136","bookId":"diwan-radi","type":"poem","seq":136,"chapter":"البحر: مجزوء الكامل","title":"صبرا على نوب الزما","page":"","text":"صبرا على نوب الزما … ن وإن أبى القلب القريح\nفلرب مبتسم ، وقد … أخذت مآخذها الجروح\nيسعى الفتى متماديا … ويد المنون له تليح\nكم آمل يغدو على الأ … مل البعيد فلا يروح\nبينا يشاد له البنا … حتى يخط له الضريح\nلا تيأسن من أن تعو … تعود عوائد وتهب ريح\nقد يسقط العود الجليد … د ، وينهض النضو الطليح\nويفرج الغماء يح … رج عندها العطن الفسيح\nولكل شيء آخر … إما جميل أو قبيح"},{"id":"diwan-radi:137","bookId":"diwan-radi","type":"poem","seq":137,"chapter":"البحر: طويل","title":"ولو كنت فيها يوم ذا الأثل لم تؤب","page":"","text":"ولو كنت فيها يوم ذا الأثل لم تؤب … وزادك إلا ذات ودقين تنضح\nغداة ذبال السمهرية يلتظى … بأيماننا ، والبيض بالبيض تقدح\nمواقف تنسي المرء ما كان قبلها … ترى الجذع العامي فيهن يقرح\nكأن سقاط البيض ثم ارتفاعها … مصاريع أبواب تجاف وتفتح\nفإن تك قد سقيت مثلي بكاسها … فما لك يا ذا الضب لا تترنح\nجعلت صحيحا مثل ضامن نقبة … له كل يوم جالب يتقرح"},{"id":"diwan-radi:138","bookId":"diwan-radi","type":"poem","seq":138,"chapter":"البحر: طويل","title":"ألا من عذيري في رجال تواعدوا","page":"","text":"ألا من عذيري في رجال تواعدوا … لحربي من رامي عقوق ورامح\nوغرهم مني اصطبار على الأذى … وقد يكظم المرء الأذى غير صافح\nفما الجارم الجاني عقوقي بسالم … ولا الماطل اللاوي ديوني برابح\nأغاروا على ذود من الشعر آمن … تقادم عندي من نتاج القرايح\nفيا ليتهم ادوه في الحي خالصا … ولم يخلطوه بالرزايا الطلايح\nوانك لو موهت كل هجينة … على ناظر ما عددت في الصرايح\nأرى كل يوم ، والأعاجيب جمة … على وبر الجربى وسوم الصحايح\nإذا طردوها خالفت برقابها … رجوعا الى اوطانها والمسارح\nوإن أوردوها غير مائي حايدت … حياد عيوف ينكر الماء قامح\nإذا انجفلت في غارة بت ناظرا … أراقب منها روحة في الروائح\nكأن بني غبراء ، إذ ينهبونها … أحالوا على مال بذي الدوح سارح\nيرجون منها والاماني ضلة … رجاء نتاج الحمل من غير لاقح\nأباغث أضرتها السفاهة ، فاغتدت … تخطف هذا القول خطف الجوارح\nهبوها اليكم من يدي منيحة … فقدان ياللقوم رد المنايح\nدعوا ورد ماء لستم من حلاله … وحلوا الروابي قبل سيل الاباطح\nولا تستهبوا العاصفات ، وأصلكم … نجيل رمت فيه الليالي بقادح\nفما انتم من مالئي ذلك الحبا … ولا فيكم أكفاء تلك المناكح\nولم تحسنوا رعي السوامخ قبلها … فكيف تعاطيتم ركوب الجوامح\nولا تطلبوها سمعة في معرة … تحدث عنكم كل غاد ورايح\nخمول الفتى خير من الذكر بالخنا … جر ذيول المندبات الفواضح\nوعندي قواف ان تلقين بالاذى … نزعن بمر القول نزع المواتح\nتعدد نبرات الأسود نباهة … وتنسى انابيح الكلاب النوابح"},{"id":"diwan-radi:139","bookId":"diwan-radi","type":"poem","seq":139,"chapter":"البحر: كامل تام","title":"قيدت أزمة كل مزن رائح","page":"","text":"قيدت أزمة كل مزن رائح … متحمل عبء المواطر دالح\nحتى يشق على العقيق مزاده … من غابق لرياضه أو صابح"},{"id":"diwan-radi:140","bookId":"diwan-radi","type":"poem","seq":140,"chapter":"البحر: متقارب تام","title":"ذكرت على فترة من مراح","page":"","text":"ذكرت على فترة من مراح … منازل بين قنا فالصفاح\nوأرضا تبدل قطانها … بمجر القنا بمجر المساحي"},{"id":"diwan-radi:141","bookId":"diwan-radi","type":"poem","seq":141,"chapter":"البحر: متقارب تام","title":"فلو كنت شاهدها في الدجى","page":"","text":"فلو كنت شاهدها في الدجى … وقد ضمها البلد الأفيح\nإذا ذكرتك على ونية … رأيت ذفاريها تنضح"},{"id":"diwan-radi:142","bookId":"diwan-radi","type":"poem","seq":142,"chapter":"البحر: خفيف تام","title":"أبلغا عني الحسين ألوكا","page":"","text":"أبلغا عني الحسين ألوكا … إن ذا الطود بعد عهدك ساخا\nوالشهاب الذي اصطليت لظاه … عكست ضوءه الخطوب فياخا\nوالفنيق الذي تدرع طول الأ … رض خوى به الرد فأناخا\nان ترد مورد القذى وهو راض … فبما يكرع الزلال النقاخا\nوالعقاب الشغواء اهبطها النيق … ق ، وقد أرعت النجوم سماخا\nاعجلتها المنون عنا ولكن … خلفت في ديارنا أفراخا\nوعلى ذلك الزمان بهم عاد … غلاما من بعد ما كان شاخا"},{"id":"diwan-radi:143","bookId":"diwan-radi","type":"poem","seq":143,"chapter":"البحر: طويل","title":"أقول لها حيث انتهى مسقط النقا :","page":"","text":"أقول لها حيث انتهى مسقط النقا : … نصلت وأيم الله من رمل مربخ\nنجوت على ما فيك من ونية السرى … وطي الموامي سربخا بعد سربخ\nبحيث الفتى لما يجب دعوة الفتى … ولا يعطف الأخ الكريم على أخ\nولم يبق إلا برزخ ، فاقذفي به … وراءك أن الدار من بعد برزخ"},{"id":"diwan-radi:144","bookId":"diwan-radi","type":"poem","seq":144,"chapter":"البحر: بسيط تام","title":"إلى كم الطرف بالبيداء معقود","page":"","text":"إلى كم الطرف بالبيداء معقود … وكم تشكى سراي الضمر القود\nتعلة لي ، بعد القرب ، تولية … عن المقام ، وبعد النوم تسهيد\nيا دار ذل لمن فارقت قعدته … والعز أولى بمن علقت يابيد\nأرمي بأيدي المطايا كل مشتبه … تنبو باخفاقها عنه الجلاميد\nوكل ليل تظل النجم ظلمته … قلب الدليل به حيران مزؤود\nوغلمة في ظهور العيس ارقهم … هم شعاع ، وآمال عباديد\nملثمين بما راخت عمائمهم … وكلهم طرب للبين غريد\nلا آخذ الطعن إلا عن رماحهم … إذا تطاعنت الشم المناجيد\nورب أمر بعيد الغاي قربني … منه السوابق والبذل المقاحيد\nأذم من أجل أشعاري فوا عجبا ! … نجاي من ضيقها سمراء قيدود\nمالي بغير العلى في الارض مضطرب … ولا لجنبي بغير العز تمهيد\nولا خطوت إلى بأس ولا كرم … إلا وموضع رجلي منه موجود\nضاع الشباب ، فقل لي أين أطلبه … وازور عن نظري البيض الرعاديد\nوجرد الشيب في فودي أبيضه … يا ليته في سواد الشعر مغمود\nبيض وسود براسي لا يسلطها … على الذوائب إلا البيض والسود\nيؤمل الناس أن يبقوا وما علموا … أن الفتى ليد الأقدار مولود\nشغلت بالهم حتى ما يفرحني … لولا الخليفة نور وز ولا عيد\n … وإن طغى بيننا نأي وتبعيد\nمحسد المجد مغبوط مناقبه … متيم القلب بالعلياء معمود\nكريم ما ضم برداه وعمته … عفيف ما ضمنت منه المراقيد\nمطهر القلب لا انهلت مدامعه … وجدا وما حقر الانفاس تصعيد\nما راق عينيه الا ما اقرهما … من المكارم لا عين ولا جيد\nالمورد الرمح ما نالت عوامله … والمطعم العضب ما عزاه تجريد\nوالقائد الخيل يمطو في اعنتها … مطو النعام اضلتها القراديد\nفي كل يوم له نعمى يجددها … تملا يدي ، ولقولي فيه تجديد\nوما اسر بمال لا اعز به … ولا ألذ برأي فيه تفنيد\nليس السراء بغير المجد فائدة … وما البقاء بغير العز محمود\nجرح الحمام ولا جرح الأذى أبدا … والموت عند طروق الضيم مورود\nصارت اليك امير المؤمنين على … غراء احرزها اباؤك الصيد\nمن هاشم أنت في صماء شاهقة … لها رواق بباع المجد معمود\nنهاية العز ان تبقى له ابدا … وغاية الجود ان تبقى لك الجود\nلاي حال يداري القلب غلثه … رجاء ورد ووردي منك تصريد\nقد كنت عن عدد الايام في شغل … فاليوم عامي لوعد منك معدود\nالام فيك واذني غير سامعة … فاللؤم مطرح والعذل مردود\nيروم ملكك من لا رأي ينجده … ولا فخار ولا بأس ولا جود\nوكيف يطلب شأوا منك ذو ظلع … باقي غبارك في عينيه موجود\nما كل بارقة تحدو السحاب ولا … \nيستفزه الخيل والاقدار تحصره … ويستطيل العوالي وهو رعديد\nلا تحفلن بوعيد زل عن فمه … فما يضر من المغرور توعيد\nولا يؤمل أن يلقاك في عدد … ان اصحر الليث اخفى شخصه السيد\nولو بسطت يمينا بالعراق اذا … نالته ، وهو بعيد الدار مطرود\nأعيذ مجدك أن أبقى على طمع … وان تكون عطاياي المواعيد\nوان اعيش بعيدا من لقائكم … \nما لي احب حبيبا لا اشاهده … ولا رجاي الى لقياه ممدود\nوأتعب القلب فيمن لا وصال له … ياللرجال اقل الخرد الغيد\nاكثرت شعري ولم اظفر بحاجته … فسقني قبل أن تفنى الأغاريد\nقد جاء عيد وعيد المرء لذته … وانت فيهم عظيم القدر محمود\nعيش الفتى كله وقت يسر به … من الدنا وجميع العيش مفقود\nفاسعد به ، وبأيام طرفن به … إن العزيز على العلات مسعود\nقليل مدحك في شعري يزينه … حتى كأن مقالي فيك تغريد\nكم خوض الناس في قولي وقائله … وكم غلا بي إغراق وتجويد\nاذم من اجل اشعاري فوا عجنا … تذم إن جنت الخمر العناقيد\nوما شكوت لان العز يقعدني … وانت سيفي ويوم الروع مشهود"},{"id":"diwan-radi:145","bookId":"diwan-radi","type":"poem","seq":145,"chapter":"البحر: رمل تام","title":"من رأى البرق بغوري السند","page":"","text":"من رأى البرق بغوري السند … في أديم الليل يفري ويقد\nحيرة المصباح تزهوه الصبا … خلل الظلماء يخبو ويقد\nكلما أنجد علوي السنا … قام بالقلب اشتياق وقعد\nتقصر الآجال من أعدائكم … ذاب دمع العين فيه وجمد\nومغان أنبت الحسن بها … هيفا ترعاه عيني ، وغيد\nكلما عاود قلبي ذكرها … لعب الدمع بجفني وجد\nإن ريم السرب أدنى لي الجوى … ونأى بالصبر عني والجلد\nبندى غضين غصن ونقا … وجنى عذبين شهد وبرد\nقل لزور الشيب اهلا انه … أخذ الغي وأعطاني الرشد\nطارق قوم عودي بالنهى … بعد ما استغمز من طول الاود\nوقر اليوم جموحا رأسه … جار ما جار طويلا وقصد\nظل لماع جلاه بارح … بعدما ابرق حينا ورعد\nلا تعد العيش شيئا ، إنه … نفس يقضي وأيام تعد\nإنما الأيام يوم واحد … وغرور اسمه اليوم وغد\nيا قوام الدين مليت بها … دولة تجري إلى غير أمد\nكسقاط النار أورى قدحه … كلما فرعن النار وقد\nأصلها يطلب أعماق الثرى … وذراها يطلب النجم صعد\nكلما زاد علوا فرعها … زاد مسراها قرارا ووطد\nكلما توهي طنبا من بيتها … نوب الايام والجد وتد\nانت اسيها إذا لج بها … من اعاديها رداع وضمد\nقائد الحيل تساقى بالردى … تحت اساد لها النقع لبد\nتحسب الشوس على اكتادها … فلق الجندل في ماء الزرد\nوعلى أربق قد أرسلها … كالقطا الجون يبادرن الثمد\nوبيم ودجوها بالقنا … ربما داويت من غير عمد\nيوم أمسى من قناها ماطرا … سال واديه من الطعن ومد\nفص جمع الغي عن شدتها … زأر الضيغم فانصاع النقد\nونجا المغرور من جامحها … مفلت الشحمة حلق المزدرد\nغاويا يحلم بالملك وهل … يغلب العير على بيت الاسد\nاذكرونا يوم ذي قار وقد … اقبلوه عارض الطعن برد\nرحض الأغلف في تياره … ورد العلج ، وما كاد يرد\nيصطلي نار طعان مضة … اوقدت فيها نزار بن معد\nسل صفيح الهند عن موقفه … وبعين الشمس للنقع رمد\nجر في دار الاعادي فيلقا … كرغاء\nفعلى الجو سقوف من قنا … وعلى الأرض قطوع من جسد\nأصعق الأعداء حتى خلته … زفيان الريح يرمي بالعضد\nركدة عن جولة تحسبها … مرجل القين غلا ثم برد\nما أضل الرمح فيها منهم … عثر السيف به فيما وجد\nمن بني ساسان أقنى ضربت … حجر الملك عليه والسدد\nطلعت في كل افق شمسه … هل ترى يختص بالشمس بلد\nما رأينا كأبيه ناجلا … ولد الناس جميعا بولد\nإن يكن تاجا وعضدا فابنه … دره التاج ودملوج العضد\nلاضحا ظلكم يوما ولا … مطل الاقبال فيكم ماوعد\nوتفارطتم على رفه السرى … مورد النعماء والعيش الرغد\nوغدا الجد جموحا بكم … ماله عن غاية الايام رد\nتقصر الاجال من اعداءكم … ويطال العيش فيكم ويمد\nتنفد الغدران احيانا وما … لعباب اليم ذي اللج نفد\nجعجع المجد بكم مبركه … راضيا بالدار فيكم والبلد\nوقباب الملك في اعطانها … رفعت منكم بعادي العمد\nمعشر فات المساعي سعيهم … ضل من كاثر رملا بعدد\nافسدوا الدهر على اولاده … لا يرى مثلهم فيمن ولد\nيا معيد الماء في عودي ، ويا … مثبتي بعد اضطراب واود\nثمري اليوم لمن أورقني … واذا ما اورق الفرع عقد\nكل يوم لك نعمي غضة … تعقد الفخر باطواق جدد\nرب من بعد من منكم … جاء عفوا ، ويدا من بعد يد\nفاعتقدها ناظمات للعلى … جامعات المجد ، والمجد بدد\nمن مطايا الذكر لا يحسرها … أبدا وعث بلاد وجدد\nعقد للمجد باق عينها … أبد الدهر ، وللمجد عقد\nخارجيات بيادون المدى … ولها فيك بواق وقعد"},{"id":"diwan-radi:146","bookId":"diwan-radi","type":"poem","seq":146,"chapter":"البحر: طويل","title":"أبى الله إلا أن يسوء بك العدى","page":"","text":"أبى الله إلا أن يسوء بك العدى … ويصبح مستثنى البقاء على الردى\nوما كان هذا الدهر يوما بنازع … نجاد حسام مثله ما تقلدا\nلعا ولعا لا عثر من بعد هذه … تلقى العلى واستأنف العز أغيدا\nخفيت خفاء البدر يرجى ظهوره … وما غاب بدر الليل إلا ليشهدا\nغروب الدراري ضامن لطلوعها … فيا فرقدا باق على الليل فرقدا\nمعاذا لهذا … معاذ الشمل المجد ان يتبددا\nسلمت لنا والله ارأف بالعلى … من ان ينطوي عنا وارحم للندى\nفقل للعدى شموا الهوان بأجدع … وعضوا على الأيدي القصار بأدردا\nافيقوا لها من سكرة الغي وابتغوا … زماما إلى ما تكرهون ومقودا\nحسبتم بأن الملك هيضت جبوره … وان سوام المجد اصبحن شردا\nلها اليوم راع لا يراع سوامه … اذل لها نهج الطريق وعبدا\nإذا طمع الأعداء فيها أجارها … وارتعها بين العوالي واوردا\nوإن قوام الدين قد عب بحره … وعيدا أقام الخالعين وأقعدا\nتقوه فبينا تنظر … إلى ان تراه شائل اللج مزبدا\nأأطمعكم أن الحسام قضى المنى … ولم يبق عند الدهر ثأرا ، فأغمدا\nوإني ضمين ان تجرد مازق … لغاو من الايام ان يتجردا\nاما يرهب القطاع الا مجردا … اما يتقى العسال الا مسددا\nليهن لليالي والمعالي انها … اثابة برء عدها المجد مولدا\nعلى حين طارت بالقلوب مخافة … اطير فريص الملك منها وارعدا\nواصبحت الامال غرثى ظمية … يواعدن من نعماك مرعى وموردا\nفلو يستطيع الدهر من بعد هذه … لألبسك اليوم التميم المعقدا\nبأي منال أم بأية أذرع … تعاطيتم اليوم البناء العطودا\nبناء أقام المجد فيه عماده … وقرره تحت العوالي ، ووطدا\nكد أبكم منه غداة حداكم … تشاغله الآذان عن طرب الحدا\nوكبكم كب الحجيج هدية … تحثحثها نخس النصال الى المدى\nكأيام حنوي دارزين وأربق … مواقف أخبى الطعن فيها وأوقدا\nاطيل اختراط البيض فيها فلو خفى … بها لمعان البرق ظن المهندا\nوتخفى بها الامطار من طول ماجرى … عليها نجيع الطعن والضرب سرمدا\nشللتم بها شل الطرائد بالقنا … تبرأ من ولى وضل الذي هدى\nوما زادكم منهن غير جوايف … هوادر يرددن المسابر واليدا\nدعوا لقم العلياء للمهتدي به … وخلوا طريقا غار فيه وأنجدا\nلأطولكم طولا ، إذا المزن أصبحت … غوارز لا يعدمن خلفا مجددا\nنهيتكم عن ذي هماهم مشبل … حمى بجنوب السيء ضالا وعرقدا\nفضافض غيل في الدماء عييه … كأن على ليتيه سبا موردا\nيفرق بين الجحفلين زثيره … كما اط نجدي الغمام وارعدا\nيجر سآبي الدماء وراءه … مجر الخليع الشرعبي المعضدا\nوحذرتكم مغلولبا ذا غطامط … اذا كب بوصي السفين وازبدا\nله زجل كالفحل يقرع شوله … الظ بقرقار الهدير ورددا\nالا اخرس الغاوي ولا فاه قائل … بامثالها ما بلل القطر جلمدا\nولاوجد الراجون افقك مظلما … وزند الندى يوما بكفك مصلدا\nولاسمع الاعداء الا باصلم … ولا نظر الحساد الا بارمدا\nفليس المنى ما عشت قالصة الجنى … علينا ولا النعمى بناقصة الجدا\nبقيت بقاء القول فيك فانه … إذا بلغ الباقي المدى جاوز المدى\nولابعد المأمول من ان تناله … فان فات في ذا اليوم ادركته غدا\nومليت حتى تسأم العيش ملة … فلو خلد الاقوام كنت المخلدا"},{"id":"diwan-radi:147","bookId":"diwan-radi","type":"poem","seq":147,"chapter":"البحر: طويل","title":"إباء أقام الدهر عني وأقعدا","page":"","text":"إباء أقام الدهر عني وأقعدا … وصبر على الأيام أنأى وأبعدا\nوقلب تقاضاه الجوانح انة … إذا راح ملآنا من الهم ، أو غدا\nأخوذ على أيدي المطامع بالنوى … نزاعا ، وما يزداد إلا تبعدا\nإذا ركبت اماله ظهر نية … رأيت غلاما غائر الشوق متجدا\nغذي زماع لا يمل كأنما … يرى الليل كورا والمجرة مقودا\nيلثم عرنين الحسام بهمة … تكلفه خوض الليالي مجردا\nأيا خاطبا ودي على النأي ، إنني … صديقك إن كنت الحسام المهندا\nفإني رأيت السيف أنصر للفتى … إذا قال قولا ماضيا أو توعدا\nأرى بين نيل العز والذل ساعة … من الطعن تقتاد الوشيج المقصدا\nفمن أخرته نفسه مات عاجزا … ومن قدمته نفسه مات سيدا\nإذا كان إقدام الفتى ضائرا له … فما المجد مطلوبا ، ولا العز مفتدى\nفدى لابن عباد ضنين بنفسه … إذا نقض الروع الطراف الممددا\nودبر أطراف الرماح ، وإنما … يدبر قبل الطعن رأيا مسددا\nبه طال من خطوي وكنت كانني … مشيت الى نيل المعالي مقيدا\nومن مات في حبس المذلة قلبه … رأى العز في دار المذلة مولدا\nيسر الفتى حمل النجاد ، وربما … رأى حتفه في صفحتي ما تقلدا\nلنال المعالي من يدل بنفسه … ولا يذخر الآباء مجدا موطدا\nوما يستفاد العز من شيمة الفتى … اذا كان في دين المعالي مقلدا\nأبا قاسم هذا الذي كنت راجيا … لا رغم اعداء واكبت حسدا\nلئن كنت في مدح العلى فاغرا فما … وان ظمئت امالنا كنت موردا\nفيا ليت رعيان القضيمة خيروا … لبست إليك الشرعبي المعضدا\nولو كان لا يجني على المرء بأسه … لدرعني العزم الدلاص المسردا\nوليل دفعناه إليك ، كأنما … دفعنا به لجا من اليم مزبدا\nوشمس خلعناها عليك مريضة … وكنا لبسناها رداء موردا\nوملك أنفنا أن نقيم ببابه … فزودنا زاد امرىء ما تزودا\nوأمرد حي ملتح بلثامه … يطول جوادا قادح السن أجردا\nرأى أرجل الخوص الخماص كأنما … تسالب أيديها النجاء العمردا\nتركنا لا يد العيس ما خلف ظهرها … ومن ذل في دار رأى البعد أحمدا\nوسرنا على رغم الظلام كأننا … بدور تلاقي من جنابك اسعدا\nتركت اليك الناس طرا كانني … أرى كل محجوب بعيرا معبدا\n … باني رعيت العز غضا مجددا\nفلله نور في محياك انه … يمزق جلبابا من الليل اربدا\nولله ما ضمت ثناياك ، إنها … ثنايا جبال تطلع البأس والندى\nأغر ضوءها ، يا قبلة المجد ، إنني … ارى غرر الامال نحوك سجدا\nوأنت الذي ما احتل في الأرض مقعدا … من الجد الا شتق في الجومصعدا\nإذا ظمئت عيس إليك ، فإنما … حقائبها تروي لجينا وعسجدا\nتكتمك الأسرار حزما وفطنة … وتفضحك الآراء عزا وسؤددا\nوما كنت إلا السيف يعرف منتضى … وينكر في بعض المواطن مغمدا\nوحي جلال قد صبحت بغارة … من الخيل يستاق النعام المشردا\nويوم من الأيام شوهت وجهه … بأغبر كد الطير حتى تبلدا\nرمت بك أقصى المجد نفس شريفة … وقلب جريء لا يخاف من الردى\nوهمة مقدام على كل فتكة … يفارق فيها طبعه ما تعودا\nمقيم بصحراء الضغائن مصحرا … اذا اخمدت من نارها اوقدا\nلك القلم الماضي الذي لو قرنته … بجري العوالي كان أجرى وأجودا\nإذا انسل من عقد البنان حسبته … يحوك على القرطاس بردا معمدا\nيغازل منه الخط عينا كحيلة … إذا عاد يوما ناظر الرمح أرمدا\nوان مج نصل من دم الصرب احمرا … أراق دما من مقتل الخطب أسودا\nاذا استرعفته همة منك غادرت … قوادمه تجري وعيدا وموعدا\nساثني باشعاري عليك فانني … رأيت مسود القوم يطري المسودا\nفما عرفتني الارض غيرك مطلبا … ولا بلغتني العيس إلاك مقصدا\nألا إن ترك الحمد تبخيل محسن … وما بذل المعطاء الا ليحمدا\n … فإني إلى غير الندى باسط يدا\nخطبت اليك الود لاشيء غيره … وود الفتى كالبر يعطى ويجتدى\nدعاني اليك العز حتى اجبته … ومن طلبته جمة الماء أوردا\nوإني لأرجو من جوارك فعلة … أغيظ بها الحساد مثنى وموحدا\nومدحك هذا بكر مدح مدحته … وكنت أروض القول حتى تسددا\nولو علقت مني بغيرك مدحة … لكنت كمن يعتاض بالماء جلمدا\nولست براض هذه لك تحفة … أضمنها فيك الثناء المخلدا\nفإن كان شعري فاتك اليوم آبيا … علي ، فإني سوف أعطيكه عدا\nولولاك ما أومى إلى المدح شاعر … يعد عليا للعلى ومحمدا\nأبوه أبوه المستطيل بنفسه … على العز مصروفا به ومقلدا\nفتى سنه عن خمسه عشرة حجة … تربى له فضلا ومجدا ومحتدا\nفتي الصبا كهل الفضائل ما مشى … إلى العمر إلا احتل في الفضل مقعدا\n … حديثا ولا يدعو من الناس منجدا\nولا طالبا من دهره فوق قوته … كفاني من الغدران ما نقع الصدا\nسأحمد عيشا صان وجهي بمائه … وان كان ما اعطى قليلا مصردا\nوقالوا لقاء الناس انس وراحة … ولو كنت ارضى الناس ماكنت مفردا\nطربت إلى الفضل الذي فيك وانتشى … لذكرك شعري راقدا ومسهدا\nوما كنت إلا عاشقا ضاع شجوه … فأصبح يستملي الحمام المغردا\nوليس عجيبا ان طغى فيك مقول … رآك حقيقا في المعالي ، فجودا\nبعدت عن الاتشاد من غير رغبة … ولكنني استخلفت نعماك منشدا\nفمرني بأمر قبل موتي فانني … ارى المرء لا يبقى وان بعد المدى\nوما الميت إلا راحل كره النوى … وأعجله المقدار أن يتزودا"},{"id":"diwan-radi:148","bookId":"diwan-radi","type":"poem","seq":148,"chapter":"البحر: كامل تام","title":"أثر الهوادج في عراص البيد","page":"","text":"أثر الهوادج في عراص البيد … مثل الجبال على الجمال القود\nيطلعبن من رمل الشقيق لواغبا … زحف الجنوب بعارض ممدود\nكم بان في المتحملين عشية … من ذي لمى خضر الرضاب برود\nوقضيب اسحله لو انعطف الصبا … يوما لنا بقوامه الأملود\nمروا على رملي زرود فهل ترى … الصاقة لحشى برمل ذرود\nمتلفتين من القباب كانما … انتقبوا باعين ربرب وخدود\nغرسوا الغصون على النقا وترنحوا … من كل مائلة الغدائر رود\nإن اللآلي بين أصداف اللمى … غلبت مراشفها على مجلودي\nولووا بوعدي يوم خف قطينهم … ومن الصدود اللي بالموعود\nلم ترضني تلك الليالي عنهم … بنوالهم ، فأقول يوما : عودي\nسيان قربهم علي ، وبعدهم … لولا الجوى وعلاقة المعمود\nربعت على آثاركم نجدية … غراء ذات بوارق ورعود\nتسقي معالم منكم لولا النوى … لم أرمها بقلى ، ولا بصدود\nولعجت فيها طارحا عن ناظري … ثقل الدموع ، وثانيا من جيدي\nهل تبردون حرارة من حائم … حران عن ذاك الغدير مذود\nفلقد تمعك في مواطئ عيسكم … يوم الوداع ، تمعك الموؤود\nوأما وذياك الغزيل إنه … عرض الزلال وحال دون ورودي\nأغدو إلى طرد الظباء ، وأنثني … وانا الطريدة للظباء الغيد\nحتام تعتلق البطالة مقودي … ويعودني لهوى الظعائن عيدي\nعشرون اردفها الزمان باربع … ارهفنني ومنعن من تجريدي\nأعلقت في سرب الخطوب حبائلي … وقدحت في ظلم الأمور زنودي\nوكرعت في حلو الزملان ومره … ما شئت واعتقب العواجم عودي\nوفرعت رابية العلى متمهلا … كفاه أخمطة العلى ، والجود\nوخبطت في المتعرضين بقولة … جداء من بدع الزمان شرود\nفضربت أوجههم بغير مناصل … وهزمت جمعهم بغير جنود\nما ضرني ، لما فللت غروبهم … أني كثرت لهم وقل عديدي\nوأبي الذي حسد الرجال قديمه … إن المناقب آية المحسود\nذو السن والشرف الذي جمعت به … كفاه اخمطه العلى والجود\nاحدى اخامصه رقاب عداته … من سيد بلغ العلى ومسود\nفالان اذ نبذ المشيب شبيبتي … نبذ القذى ، وأقام من تأويدي\nوفررت من سن القروح تجاربا … وعسا على قعس السنين عمودي\nولبست في الصغر العلى مستبدلا … اطواقها بتمائم المولود\nوصفقت فيث ايدي الخلائف راهنا … لهم يدي بوثائق وعقود\nوحللت عندهم محل المجتبى … ونزلت منهم منزل المودود\nفغر العدو يريد ذم فضائلي … هيهات ألجم فوك بالجلمود\nهمسا ، فكم أسكت قبلك كاشحا … بمناقبي ، وعلي فضل مزيد\nمالي اريغ النصف من متحامل … أو أطلب الإجمال عند حسود\nأم كيف يرأمني ، وليس بمنجبي … اترى الرؤوم تكون غير ولود\nفلأنهضن إلى المعالي نهضة … ملء الزمان تفي بطول قعودي\nإجمح أمامك إن هممت بفعلة … وتغاب عن عذل وعن تفنيد\nوإذا التفت إلى العواقب بدلت … قلب الجري بمهجة الرعديد\nقد قلت للابل الطلاح حدوتها … غلس الظلام بسائق غريد\nمن كل مضطرب الزمام كانه … في الليل زم بأرقم مطرود\nفتل الطوى أجوافها بظهورها … واحل اكل لحومها للبيد\nإن لم تري كافي الكفاة ، فلم يزل … منكن مسقط ظالع أو مود\nبهداه يستضوي الورى وبهديه … قرب الطريق لهم الى المعبود\nاسد إذا جر القبائل خلفه … حل الطلى بلوائه المعقود\nومقصر في الطول غير مقصر … في الضرب يقطع كل حبل وريد\nومزعزع مثل الجرير ، إذا انحنى … للطعن شيع بالطوال الميد\nما مر يسحب منه إلا رده … ريان يقطر من دماء الصيد\nوالجيش يرفع عمة من قسطل … فوق القنا ويجر ذيل حديد\nسلف لكل كتيبة يطأ العدى … فيها مفاجأة بغير وعيد\nفي غلمة حملوا القنا وتحملوا … اعباء يوم المأزق المشهود\nقوم ، إذا ركبوا الجياد تجلببوا … بقساطل وتعمموا ببنود\nواذا سروا كمنوا كمون اراقم … واذا لقوا برزوا بروز اسود\nواذا هتفت بهم ليوم كريهة … تدمى غوارب نحرها المورود\nكثروا الحصى بجموعهم وتلاحقوا … بك من قيام في السروج قعود\nكم من عدو قد ابات كانما … يطوي الضلوع على قنا مقصود\nلوعيد محتضر العدى بحسامه … قبل احتمال ضغائن وحقود\nوموللات كالرماح تلمظت … فيها المنون تلمظ المزؤود\nسود المخاطم ينتظمن محاسنا … بيضا ، يضئن على الليالي السود\nكتفتح النوار فتقه الحيا … او كالصباح فرى الدجى بعمود\nما زال قدر من عقيرة سيفه … علما أمام رواقه الممدود\nوجفان جود كالركايا تستقى … أبدا بأيدي نزل ووفود\nكم حجة لك في النوافل نوهت … بدعاء دين العدل والتوحيد\nومجادل ادمى جدالك قلبه … وأعضه بجوانب الصيخود\nوشفيت ممترض الهدى من معشر … سدوا من الآراء غير سديد\nقارعتهم بالقول حتى أذعنوا … وأطلت نوم الصارم المغمود\nجمر بمسهكة الرياح نسفته … كان الضلال يمده بوقود\nفي كل معضلة أضب رتاجها … يلقي إليك الدين بالإقليد\nفالله يشكر والنبي محمد … وقفات مبد في النضال معيد\nرأي يغب ، إذا الرجال تلهوجوا … الآراء ، أو عجلوا عن التسديد\nلو كان يمكنني التقلب لم يكن … إلا إليك تهائمي ونجودي\nوطويت ما بعدت مسافة بيننا … ان البعيد اليك غير بعيد\nوأنخت عيسي في جنابك طارحا … بفناء دارك انسعى وقتودي\nوتركت اسوقها نكوس عقيرة … متبدلات صوارم بقيود\nبيني وبينك حرمتان تلاقتا … نثري الذي بك يقتدي وقصيدي\nووصايل الادب الذي تصل الفتى … لا باتصال قبائل وجدود\nقد كنت اعقل عن سواك عقائلي … وأصون در قلائدي وعقودي\nواحوك افواف القريض فلا ارى … ان ادنس باللئام برودي\nولقد ذممت الناس قبلك كلهم … فالان طرق لي الى المحمود\nإن أهد أشعاري إليك ، فإنه … كالسرد أعرضه على داود\nلكنني أعطيت صفو خواطري … وسقيت ما صبت علي رعودي\nوسمحت بالموجود عند بلاغتي … إني كذاك أجود بالموجود"},{"id":"diwan-radi:149","bookId":"diwan-radi","type":"poem","seq":149,"chapter":"البحر: طويل","title":"اعاتب لومي وما الذنب واحد","page":"","text":"اعاتب لومي وما الذنب واحد … وهن الليالي الباديات العوائد\nوأهون شيء في الزمان خطوبه … اذا لم يعاونها العدو المعاند\nوكيف تلذ العيش عين ثقيلة … على الخلق أو قلب على الدهر واجد\nوناضب مال ، وهو في الجود فائض … وناقص حظ وهو في المجد زائد\nتضوت شبابا لم انل فيه سبة … على ان شيطان البطالة مارد\nوكل فتى لم يرض عن عزمة القنا … ومن عددي قلب جري وساعد\nوعندي إباء لا يلين لغامز … ولو نازعتنيه الرقاق البوارد\n … ذليلا ولو ناجى علاه الفراقد\nولولا الوزير الازدشيري وحده … لغاض المعالي والندى والمحامد\nوسد طريق المجد عن كل سالك … وضاقت على الآمال هذي الموارد\nفتى نفحتني منه ريح بليلة … تغادر عودي وهو ريان مائد\nومد بضبعي يوم لا العزم ناصر … ولا الرمح مناع ، ولا العضب ذائد\nوساعد جدي في بلوغي إلى العلى … وما بلغ الآمال إلا المساعد\nعلى حين ولاني المقارب صده … وزاد على الصد العدو المباعد\nتود العلى طلابها وهو وادع … ويبلغ ما لم يبلغوا وهو قاعد\nيخلى له عن كل عز وسؤدد … ويلقى اليه في الامور المقالد\nانيس سروج الخيل في كل ظلمة … وبين الغواني مضجع منه بارد\nهموم تناجي بالعلاء وهمة … لها فارط في كل مجد ورائد\nيعلمه بهرام كل شجاعة … ويقطعه اقصى المعالي عطارد\nوكيف يغص الاقربون بورده … وقد نهلت منه الرجال الاباعد\nلك الله ما الآمال الا ركائب … وانت لها هاد وحاد وقايد\nأبى لك إلا الفضل نفس كريمة … ورأي إلى فعل الجميل معاود\nوطود من العلياء مدت سموكه … فطالت ذراه واطمأن القواعد\nوإني لأرجو من علائك دولة … تنذلل لي فيها الرقاب العواند\nويوما يظل الخافقين بمزنة … رذاذ ، غواديها الرؤوس الشوارد\nلا عقد مجدا يعجز الناس حله … وتنحل من هام الاعادي معاقد\nفمن ذا يراميني ولي منك جنة … ومن ذا يدانيني ولي منك عاضد\nعلي رداء من جمالك واسع … وعندي عز من جلالك خالد\nولو كنت ممن يملك المال رقه … لقلت بعنقي من نداك قلائد\nفلا تتركني عرضة لمضاغن … يطارد في اضغانه واطارد\nولولا صدود منك هانت عظائم … تشق على غيري وذلت شدائد\nولكنك المرء الذي تحت سخطه … أسود ترامى بالردى وأساود\nكانك للارض العريضة مالك … وحيدا ، وللدنيا العظيمة والد\nفعودا إلى الحلم الذي أنت أهله … فمثلك بالإحسان باد وعائد\nوحام على ما بيننا من قرابة … فان الذي بيني وبينك شاهد\nوأرع مقالي منك أذنا سميعة … لها بلقاء السائلين عوائد\nومر بجواب يشبه البدء عوده … ليردي عدوا ، أو ليكبت حاسد"},{"id":"diwan-radi:150","bookId":"diwan-radi","type":"poem","seq":150,"chapter":"البحر: مجزوء الوافر","title":"أكافينا النصيح بقي","page":"","text":"أكافينا النصيح بقي … فينا دائما ابدا\nقمت الى العلى قدما … وتبسط بالنوال يد\nلئن حرقتني عذلا … لقد نوهت بي صعدا\nفطلت الاطولين علا … وفت الابعدين مدى\nعلي طروق وردكم … وليس علي ان اردا"},{"id":"diwan-radi:151","bookId":"diwan-radi","type":"poem","seq":151,"chapter":"البحر: سريع","title":"اذا احتبى بالعشب الوادي","page":"","text":"اذا احتبى بالعشب الوادي … وانحل فيه الواكف الغادي\nوفوفت ريح الصبا متنه … تفويف اعلام وابرادي\nفلا سقاك الله من صفوة … او تنجزي في السير ميعادي\nرب طلاب أتلع رمته … وحاجة عالية الهادي\nمعتجرا بالليل أحدو به … بزلاء تستولي على الحادي\nلا أرد الماء ، ولو أنني … ضجيع اسدام واعداد\nكانني روعاء مطرودة … يزور عنها جانب الوادي\nهذا ، وكم فيض ترشفته … والماء لا يلوي على الصادي\nتؤم بي الخرقاء مخطومة … امام وراد ورواد\nاشرف بيت من بني هاشم … وخير اطناب واعماد\nالقت اليه ناقتي في السرى … وما له من حتفه فاد\nتركت من ليست له همة … ملتفتا في الماء والزاد\nتلوث موسى بابنه في العلى … بفضل اجداد واجداد\nنعم حمى الدرع ليوم الوغى … انت وراع الحلم للنادي\nإذا القنا مد مدى باعه … عانقته في ثوب فرصاد\nأدعوك ، والدهر له وقفة … ما بين اصداري وايرادي\nلمثلها ادعو بنات السرى … تخلط أعناقا بأعضاد\nنفسي كما تعرق صبارة … لو لم يفض الخطب من آدي\nولو أمنت الدهر أحداثه … صافحت كف الضيغم العادي\nمالي لا ارغب عن بلدة … ترغب في كثرة حسادي\nما الرزق بالكرخ مقيم ، ولا … طوق العلى في جيد بغداد\nبكل أرض ، إن توردتها … ديار أشكال وأضداد\nانحلني فيها طلاب العلى … وذاك فخري عند أندادي\nلو كان دائي من غرام الهوى … جزعت من ابصار عوادي\nأين الغواني من طلابي وما … أطلب إلا الرائح الغادي\nاكثر ما يلقينني ساهرا … ما بين اعراف واكتاد\nوقل ما يلقينني راقدا … ما بين احشاء واجيادي\nان مسنى ناب الردى لم اقل … يا ليت موتي كان ميلادي\nسيان ما سيري على سابح … او شرجع تخفق ابرادي\n … لها المقادير بمرصاد\nتفدي الفتى في عيشه السن … وما له من حنفه فاد\nقالوا ، وما أنكرها قولة … من مائق في الغي منقاد\nالظلم والانصاف من فعل من … يحكم في الحاضر والبادي\nفقلت اني وجميع الورى … منه على وعد وإيعاد\nإن كان إسلامي على هذه … فكل غي عند إرشادي\nهيهات لا احسد ذا قدرة … ولو حوى عاقر اغمادي\nولو حسدت الفضل في اهله … "},{"id":"diwan-radi:152","bookId":"diwan-radi","type":"poem","seq":152,"chapter":"البحر: خفيف تام","title":"شقيت منك بالعلاء الاعادي","page":"","text":"شقيت منك بالعلاء الاعادي … والمعالي ضرائر الحساد\nواستقاد الزمان بعد التداني … من رجال تفاءلوا بالبعاد\nورعيت الإياب غضا جديدا … وتبدلت مطمحا بالقياد\nواذا ما الشجاع شمر برديه … ه ، فلله أي يوم جلاد\nأمرعت أرضنا بكل مكان … واستجابت لنا بروق الغوادي\nوحبانا بوبله كل أفق … واتانا بسيله كل واد\nاترى آن للمنى ان تقاضى … حاجة طال مطلها في الفؤاد\nبين هم تحت المناسم مطرو … ح وعزم على ظهور الجياد\nومهار يكدها كل يوم … طرد ، أو قوارح في الطراد\nمن قلوب لها التقلب في العز … م وايد طليقة بالايادي\nما يبالي الهمام اين ترقى … وخباء العلى امين العباد\nيا حياة يشجى بها كل حي … والتوالي شجية بالهوادي\nإن سما بالنفاق غيرك ، فالأو … عال ملوية على الأطواد\nاو تعاطى مداك فالمرء مسبو … ق اذا كف من عنان الجواد\nحركت عزمة المعالي ، ولكن … يحدث السيل خفة في الجماد\nكيف يستعمل السماح وبذل ال … المال غير المعلم المستفاد\nنحن في عصبة ترى الجور عدلا … وتسمي الضلال دار رشاد\nلو أجيزت له العيادة يوما … وديار تسطو على الوراد\nإنما أنت نعمة الله في الأر … ض ، إذا كان نقمة للعباد\nلك طبع تعرفته الليالي … وامترى فيه كل قار وبادي\nجاعل قسوة الوعيد على الايام … عبدا لرقة النيعاد\nايكون البخيل غير بخيل … أم يكون الجواد غير جواد\nلأجار الزمان من كل بؤس … ظاهر الجد طاهر الأجداد\nفرحات به العيون كما تف … رح بالعشب اعين الرواد\nواضح العزم متلئب المطايا … سمحت كفه به للمنايا\nأخذت كفه بصخرة عزم … دوخت بالطلاب هام البلاد\nوجبان لويت عنه ، فأمسى … وجل العين من قراع الرقاد\nمستطيرا كأن هداب جفني … يه على الناظرين شوك القتاد\nلا أقال الإله من خانك العه … د ، وجازاك بغضة بالوداد\nظن بالعجز ان حسبك ذل … والمواضي تصان بالأغماد\nقصر الدهر من ذراه ، وقد كا … ن بتلك الظبى طويل النجاد\nوأذل الزمان بعدك عطفي … ه ، وقد كان من أعز العباد\nكنت ليثا وكان ذئبا ولكن … لا تلذ الأشكال بالأضداد\nوتمادى بما جناه على الأيام … يام حتى جنى عليه التمادي\nسمحت كفه به المنايا … بعد ان لم يكن من الاجواد\nظن ان المدى يطول وفي الآ … مال ما لا يعان بالأجداد\nكل حي يغالط العيش بالد … هر وكل تعدو عليه العوادي\nلو رجعنا إلى العقول يقينا … لرأينا الممات في الميلاد\nكيف لا يطلب الحمام عليل … حكم الدهر فيه رأي المعاد\nلو اجتزت له العيادة يوما … لقضى من فظاظة العواد\nاو تصدى لمجمع جرحته … ألسن القوم بالعيون الحداد\nهكذا تدرك النفوس من الأع … داء برد القلوب والأكباد\nكل حبس يهون عند الليالي … بعد حبس الارواح في الاجساد\n … حشاء مزرورة على الاحقاد\nنلت بعضا وسوف تدرك كلا … إنما السيل بعد قطر العهاد\nمثل ما مر لا تعيد الليالي … والحديث السفيه غير معاد\nرب يوم شهدته ، والمنايا … تطرح الطعن من رؤوس الصعاد\nخلق الخيل بالنخيع وكانت … غرر الخيل معقلا للجساد\nيا قريع الزمان ، دعوة صب … بالاماني متيم بالمراد\nلك إن ذمت المحاضر يوما … عنفوان الثناء في كل ناد\nنظر العيد منك بدرا تخفى … برهة عن نواظر الاعياد\nفتهن السرور فاليوم مص … قول الحواشي مجرر الابراد\nمن مرام بعاده لتدان … ومراد نقصانه لازدياد\nلو قدرنا على المنى لفدينا … ذي الاضاحي من الظبي بالاعادي\nإنما نحن مشبهوك وما الأش … شبال الا طبائع الاساد\nنحن ذاك الغرار من هذه البي … ض وذاك الشرار من ذا الزناد\nهذه تحفتي اليك وخير الش … شعر ما كان تحفة الإنشاد\nوضميري إذا طرحتك فيه … جاش لي بحره بخير العتاد\nأنا من صفوة النبي ، وغيري … ولد لا يعد في الأولاد"},{"id":"diwan-radi:153","bookId":"diwan-radi","type":"poem","seq":153,"chapter":"البحر: منسرح","title":"خير الهوى ما نجا من الكمد","page":"","text":"خير الهوى ما نجا من الكمد … وعاشق العز ماجد الكبد\nما حمل الذل ظهر مارنة … ولا انزوى عن طبيعة الصيد\nكيف يربي الحياة مقتبل … يرى المنى عاقرا بلا ولد\nيعذلني في الزماع كل فتى … والسيف إن قر في الغمود صدي\nانا النضار الذي يضن به … لو قلبتني يمين منتقد\nاني اظن الظنون صادقة … كأن يومي طليعة لغدي\nما وتر الدهر لمتي ، ويدي … تاخذ قبل المشيب بالقود\nتغدر بي وفرتي وكنت اذا … طلبت غير الوفاء لم اجد\nبعدكم حنت الركاب ، وسا … ل الركب بالصحصحان والجدد\nوالليل بين النجوم تحسبه … يحظر في نثرة من الزرد\nليلي ببغداذ لا اقر به … كانني فيه ناظر الرمد\nينفر نومي كان مقلته … تشرج اجفانها على ضمد\nافكر في حالة اطوالها … وفعلة تخصب القنا بيدي\nللنفس أن تبعث العزائم والرأ … ي وكل الفعال للجسد\nها انها نومة بسورتها … اقالت العين عثرة السهد\nلا اطردت بي إليك سابحة … حتى ارى النقع عالي الكتد\nمالي لا اركب البعاد ولا … أدعى على القرب بيضة البلد\nأصحب من لا ألوم صحبته … غير نزور الندى ولا جحد\nفتى رأى الدهر غير مؤتمن … فما فشا سره إلى أحد\nوأتهم الخيل ، فهو يمتحن ال … رة قبل الطراد بالطرد\nفي كل فج يقود راحلة … تجذبها الأرض جذبة المسد\nلا يبعد الله غلمة ركبوا … أغراضهم واستفوا من البعد\nرموا بعهد النعيم ، واصطنعوا … كل بخيل الذباب مطرد\nقلوا على كثرة العدو لهم … كم عدد لا يعد في العدد\nلي فيهم أشرف الحظوظ ، إذ ال … روع أعان الحسام بالعضد\nواين مثل الحسين ان احسنت … صنائع البيض والقنا القصد\nابلج ان صاحت المطي به … فدى التنائي بعيشة الرغد\nما خلع الدهر عنه سابغة … والليث لا ينتضى من اللبد\nلو أمطرته السماء أنجمها … عزا لما قال للسماء قدي\nلا يسال الضيف عن منازله … ومنزل البدر غير مفتقد\nرأى الظبى في الغمود آجنة … والخيل ملطومة عن الأمد\nفاسئل اسيافه واوردها … غمر المنايا بمائها الثمد\nتخلق أجفانها ويعرضها … دم الطلى في غلائل جدد\nيا قائد الخيل في سنابكها … ما يشمت السهل منه بالجلد\nيفديك يوم الخصام ممتهن … كأنه مضغة لمزدرد\nوصارخ رافع عقيرته … فككت عنه جوامع الزرد\nإذا المنى قابلتك أوجهها … صفدت باع المطال بالصفد\nرب مخوف كأن طلعته … تلقى المطايا بطلعة الأسد\nحططت فيه الرحال محتزما … وأنت ثاني المهند الفرد\nتسحب برديك في ملاعبه … وما اقتفته براثن الأسد\nزادك في كل ما خصصت به … في كل امن ويوم محتشد\nكل اصم الكعوب معتدل … خلت أنابيبه من الأود\nوكل طاغي الغرار تلحظه … من غمده في طرائق قدد\nولامة سال فوقها زرد … كالماء في قطعة من الزبد\nحكمك بالسيف غير منهجم … وأنت بالضرب غير متثد\nلله بيت رفعت عمته … أغناه سلطانه عن العمد\nخلائق طلقة معبسة … كالصاب يجري بصورة الشهد\nفأنت يوم النوال في حلل … منها ويوم النوال في زرد\nعلامة العز ان حسدت به … أن المعالي قرائن الحسد\nكم لك من وقفة صقلت بها … رسائلا دبجت على البرد\nتنوب عن كنهها معارفها … وفضل بدر ينوب عن أحد\nناجاك شعري وكنت اخرسه … عن الورى قانعا بمقتصدي\nكان نزاعي اليك يسمح بي … فالان مذ عدت ضن بي بلدي"},{"id":"diwan-radi:154","bookId":"diwan-radi","type":"poem","seq":154,"chapter":"البحر: طويل","title":"نصافي المعالي ، والزمان معاند","page":"","text":"نصافي المعالي ، والزمان معاند … وننهض بالآمال ، والجد قاعد\nتمر بنا الأيام غير رواجع … كما صافحت مر السيول الجلامد\nوتمكننا من مائها كل مزنة … وتمنعنا فضل السحاب المزاود\nوما مرضت لي في المطالب همة … واحداثه في كل يوم عوائد\nعوائد هم لا يحيين غبطة … بهن ولا تلقى لهن الوسائد\nولله ليل يملأ القلب هوله … وقد قلقت بالنائمين المراقد\nيقر بعيني ان ارى ارض بابل … تخوض مغانيها الجياد المذاود\nوأسحب فيها برد جذلان شامت … اذا شاء غنته الرقاق البوارد\nسللنا رقاب العيس من خلل الدجى … تلاعبها اشطانها والمقاود\nوقد حف بالبدر النجوم كأنه … هدي تهاداه الاماء الولائد\nوفي اعين القوم انضمام من الكرى … وطرفا لسرى بين الأزمة شاهد\nفمضطرب في غرزة مترنح … وآخر مكبوب على الرحل ساجد\nوغائرة قد وقر النوم لحظها … تسفه جفنيها الهموم العوائد\nتقود جيادا ما اتهمن على مدى … بلى ربما ارتابت بهن الاوابد\nإذا جال في أشداقها الظمء قلصت … لها الارض وانقادت اليها الموارد\nأبحنا لها تقتض من عذر الربى … فكرت عليها بالعجاج الفدافد\nطرائق بيد يعسل الآل بينها … كما اضطرب السرحان والليل بارد\nهجمنا على غول الطريق وبعده … وما ركضت فيه الرياح الصوارد\nأأرسل خيل اللحظ في طلب الهوى … ومن ظنها أن الخدود طرائد\nولي شغل في طالب ضل قصده … أسائل عنه ما يقول المقاصد\nأقول لدهر تاه إذ صيد ليثه : … كذاك يصاد الليث والليث راقد\nاثلم هذا النصل بالضرب ضارب … وزعزع هذا الطود بالوطء صاعد\nتعز فما كل المصائب قادم … عليك ، ولا كل النوائب عائد\nينال الفتى من دهره قدر نفسه … وتأتي على قدر الرجال المكايد\nفدى لك يا مجد المعالي وبأسها … فعال جبان شجعته الحقائد\nفما تركت منك الصوارم والقنا … ولا أخذت منك الحسان الخرائد\nعزلت ولكن ما عزلت عن الندى … وجودك في جيد العلى لك شاهد\nبوجهك ماء العز في العزل ذائب … ووجه الذي ولي من الماء جامد\nفانت ترجي الملك وهو زواله … بغير جلاد فيه وهو مجالد\nفلا يفرح الأعداء فالغزل معرض … اذا راح عنه صادر جاء وارد\nوما كنت إلا السيف يمضي ذبابه … ولا ينصر العلياء من لا يجالد\nنضي فقصى حق الضرائب في الوغى … وأثنت عليه حين رد المغامد\nفأعطوا عنان الضر غيرك إذ رأوا … يمينك تستولي عليها الفوائد\nوما كنت يوما في الزمان بممسك … عرى المال ان ضجت اليك المواعد\nولا كنت ترضى أن تصح ببلدة … اذا قيل عضو من زمانك فاسد\nأيا غدوة ساء الحسين صباحها … وسر العدى فيها الزمان المعاند\nلحققت عندي ان كل صبيحة … مجاجة سم والليالي اساود\nيعرفك الإخوان كل بنفسه … وخير اخ من عرفتك الشدايد\nوطاغ يعير البغي غرب لسانه … وليس له عن جانب الدين ذائد\nشننت عليه الحق حتى رددته … صموتا ، وفي أنيابه القول راقد\nيدل بغير الله عضدا وناصرا … وناصرك الرحمن ، والمجد عاضد\nتعير رب الخير بالي عظامه … الا نزهت تلك العظام البوائد\nولكن رأى سب النبي غنيمة … وما حوله إلا مريب وجاحد\nولو كان بين الفاطميين رفرفت … عليه العوالي والظبي السواعد\nألا إن جدب الحلم عندك مخصب … وان لئيم المجد عندك رافد\nضجرت من العلياء فاخترت عزلها … كانك قد افنت نداك المحامد\nتركت قلوصا بالفلاة ووحشها … تجاذبه عن نفسه وتراود\nستذكرك الارماح وهي قوارب … وليس لها إلا القلوب موارد\nحوى المجد يا قيس بن عيلان ماجد … وجل ، فما يلقى له فيه حاسد\nفتى يحتوي أرماحكم ، وهو صارم … ويسري جيوشا نحوكم ، وهو واحد\nويوم عويث والسيوف بوارق … تظل المنايا والقسي رواعد\nرددتهم ، والسمر بين ظهورهم … تعقل فيه الموت والموت شارد\nوقد خلقت فيها عيونا قريحة … ينامون عمر الليل ، وهي سواهد\nأسنة فهر في صدور جيادهم … كان قناها للجياد مقاود\nهم ذخروا اعمارهم لسيوفه … فأولى لها والحرب عذراء ناهد\nرأيت فيافي تقتضي هبواته … وترغب أرساغ الجياد القوادد\nمدى يمخض الاشواط حتى يعيدها … ولا زبدة الا الجواد المجاود\nلنعم حريم العزم أنت وثغره … اذا رجح الرأي الالد المجالد\nالست من القوم الذين اذا سطوا … تبرى من التاج العظيم المعاقد\nسياطهم بيض الظبى وسجونهم … إذا غضبوا دون العلاء الملاحد\nرقاب العدى والعيس فيهم ذليلة … وللبيض ما نيطت عليه القلائد\nيعشش طير الخضب في حجراتهم … وتعقل منهن البيوت الشوارد\nوما والد مثل ابن موسى لمولد … قريب تجافاه الرجال الأباعد\nحمى الحج واحتل المظالم رتبة … على ان ريعان النقابة زائد\nفاقبل والدنيا مشوق وشايق … وأعرض ، والدنيا طريد وطارد\nوساعده ، يوم استقل ركابه … أخوه ، وقال البين : نعم المساعد\nهما صبرا والحق يركب راسه … عشية زالت بالفروع القواعد\nتفرد بالعلياء عن أهل بيته … وكل يهاديه إلى المجد والد\nوتختلف الآمال في ثمراتها … اذا اشرقت بالري والماء واحد\nومد على الجوزاء اطناب منزل … يلوذ بحقويه السها والفراقد\nفقر لنيران البوارق مصطل … وظمء لاحواض الغمائم وارد\nاحق بلاد الله بالمزن ارضه … اذا شام اقصى خطره البرق رائد\nكاني به والعز ينضو همومه … وقد خضعت تلك الخطوب النواكد\nاعاد اليه الله ماضي سروره … ورد الليالي وهي بيض أماجد\nمنيت بشوق ينحر الدمع سيفه … اذا حادثته بالصقال المعاهد\nأآل هذيم هل تقر قلوبكم … وقلب بن عدنان على الدهر واجد\nإذا جحدوا نعماك لوت رقابهم … لمنك اطواق بها وقلائد\nولا زالت الأسياف تسبي حريمهم … وتسبي حريم المال منك القصائد"},{"id":"diwan-radi:155","bookId":"diwan-radi","type":"poem","seq":155,"chapter":"قصائد","title":"انظر الى الايام كيف تعود","page":"","text":"انظر الى الايام كيف تعود … وإلى المعالي الغر كيف تزيد\nوإلى الزمان نبا ، وعاود عطفه … فارتاح ظمآن واورق عود\nنعم طلعن على العدو بغيظه … فتركنه حمر الجنان يميد\nقد عاود الايام ماء شبابها … فالعيش غض والليالي غيد\nاقبال عز كالاسنة مقبل … يمضي وجد في العلاء جديد\nوعلى لأبلج من ذؤابة هاشم … يثني عليه السؤدد المعقود\nقد فات مطلوبا وادرك طالبا … ومقارعوه على الامور قعود\nخسأت عيونهم وقد طمحت له … عدد عراض في العلى وعديد\nما صال إلا انجاب غي مظلم … واندق من عمد الضلال عمود\nيأسو ويجرح ، فالجراحة عزمة … تصمى وآسيها الندى والجود\nسطو وصفح يطرقان عدوه … أبدا ، ووعد صادق ووعيد\nعن اي باع في العلاء رميتم … ليثا تقيه مقادر وجدود\nطاشت سهامكم وفارق نزعه … سهم الى قلب العدو سديد\nحسدوك لما فات سعيك سعيهم … صعدا فما نقع الغليل حسود\nورأوا بوايجها تلوح ، وريحها … تسري ، وعارضها الغزير يجود\nعجل الزمان بها اليك وحطمت … بين الضلوع ضغائن وحقود\nقد كنت اخشى ان يقول مخبر … كادوا وما أعطوا المراد فكيدوا\nاو ان يقال اقارب نزعت بهم … ظنن ، فكل بالعقوق بعيد\nسئلوا العواد فجانبوه فعاودوا … والان اذ ملك الزمان وقيدوا\nلولا الالية منك الا تنتضي … عضبا يقوم مقامه التفنيد\nلسننت في الأقوام ، غير ملوم … ما سن يوم ابن الزبير يزيد\nاليوم أصحرت الضغائن ، وانجلت … تلك الموارن والجباه السود\nوتراجعوا عصبا إليك ، وخلفهم … عنف السباق وللقلوب وئيد\nفاصفح فسوف ينال صفحك منهم … ما لا ينال العضب ، وهو حديد\nوحذار من ويل العقاب وقد بدت … ملء العيون بوارق ورعود\nوتغنموا عفوا يفيض وفيئة … تدنو وحلما لا يزال يعود\nفلسطوة الضرغام اجمل بالفتى … من ان يرى عال عليه السيد\nما السؤدد المطلوب إلا دون ما … يرمى اليه السؤدد المولود\nفإذا هما اتفقا تكسرت القنا … ان غالبا وتضعضع الجلمود\nوأجل ما ضرب الرجال بحدة ا … لأعداء مجد طارف وتليد\nالان اطلقت النصول ورشحت … \nوتبلج البيت الحرام طلاقة … مذ قيل ان جماله مردود\nوعلى المظالم والنقابة همة … يقظى ، وظل أمانة ممدود\nحمدا لانعمك الجسام فلم يزل … أبدا يزيد لها علي مزيد\nعليتني حتى تحققت العدى … اني حميم للعلى وعقيد\nوتركت حسادي على زفراتهم … عوج الضلوع فواجد وعميد\nفلاشكرنك ما تجاذب مقولي … نثر يشق على العدى وقصيد\nوالشكر أنفس ما وجدت ، وإنما … أمل الفتى أن يقبل الموجود"},{"id":"diwan-radi:156","bookId":"diwan-radi","type":"poem","seq":156,"chapter":"البحر: بسيط تام","title":"جري النسيم على ماء العناقيد","page":"","text":"جري النسيم على ماء العناقيد … وعللي بالأماني كل معمود\nيا نفحة هزت الأحشاء شائقة … وذكرت نفحات الخرد الغيد\nيضمها الليل في اثناء غيهبه … والقطر يلمس أطراف الجلاميد\nكأنها عن طريق المزن طائشة … لحظ تردده أجفان مزؤود\nليت الأحبة أغرين الرياح بنا … وان نأين على شحط وتبعيد\nوليتهن على يأس اللقاء لنا … عللن بالوعدسير الضمر القود\nأبيت ، والليل مبثوث حبائله … والوجد يقنص مني كل مجلود\nشوقا إليك ، وإشفاقا عليك ، ولي … دمعان ما بين محلول ومعقود\nليس الغريب الذي تنأى الديار به … إن الغريب قريب غير مودود\nيا طائر البان ما غربت عن سكن … يوما ولا كنت عن مأوى بمطرود\nوانت في ظل افنان مهدلة … تحنو عليك بقنوان العناقيد\nملأت عشيك طعما غير محتلس … بلا رقيب ، وورد غير تصريد\nتبكي ومالك من الف فجعت به … ولا لويت ، على بعد ، بموعود\nظلمت ما انت من همي ولا كمدي … إن العليل لقلب عاده عيدي\nانا الذي ان بكى وجدا فحق له … كم بين باك من البلوى وغريد\nوخلة جذبت تثني مودتها … عني ، وأمسكت عنها بالمواعيد\nمني الى الدهر شكوى غير غافلة … عن موثق بحبال العجز مصفود\nيحارب الهم إن مال الرقاد به … حتى تجلى غيابات المراقيد\nبيني وبين المنى اني اقول لها … بيني وبينك قطع البيد والبيد\nوساهمين على الأكوار دأبهم … قرع السياط باعناق المقاحيد\nعاطيتهم من علالات الكرى نطفا … والسير يرجم جلمودا بجلمود\nوللحداة على آثارنا زجل … يغزي المطايا بأجواز القراديد\nيقطعون حبى الأيام عن طبع … وتحتبي بالمعالي والمحاميد\nويهجرون اذا جدت عزائمهم … دنيا تلاعب بالغر المجاويد\nما الفقر عار وإن كشفت عورته … وانما العار مال غير محمود\nتلقى أكفهم في كل نائبة … ملوية بحبال البأس والجود\nإن صاح صائحهم يوم الوغى هجموا … على السوابق بالبيض المذاويد\nوكم عدو مشت فيه رماحهم … فاستنصر الركض من جرداء قيدود\nمن كل أبلج إن خبت عزائمه … القت اليه الاماني بالمقاليد\nإذا تحرق ، أحشاء الفلا ملئت … من رعيه خاطر الريبال والسيد\nوإن جرى شرقت بالخصل راحته … أخذا وبدد أنفاس المجاهيد\nيابن الحسين وما دعواي كاذبة … اذا نسبتك في الشم المناجيد\nالطاعنين من الاعداء ما لحقوا … والخيل تلطم هامات الصياخيد\nمعودون من الايام مرتبة … لا يستطيل اليها كل صنديد\nيأبون يلبس الاظلام ربعهم … ليلا وما عذبوا طرفا بتسهيد\nويغضبون اذا عاطيتهم همما … مرفهات ، وهما غير مكدود\nهم الضيوف لأرض غير آهلة … من الانيس وورد غير مورود\nفانمت ابسطهم باعا اذا بسطوا … ايديهم لوعيد أو لموعود\nالان جاءت خيول السعد راكضة … تجري بيوم مضيء الوجه مجدود\nبمولد صقل الاباء حليته … فطوق المجد أعناق المواليد\nمولودة نهب الراؤون بهجتها … لثماوعانقها في ثوب محسود\nكانت شهابا كسا ظلماءه وضحا … والليل يدخل في أثوابه السود\nجاءت بها ليلة تثنى سوالفها … في صدر يوم رشيق القد املود\nلله شمس علي جاءت بجوهرة … غراء ، عن قمر بالمجد مسعود\nما عددت منك الا نطفة سلكت … الى الاماني طريق الماء في العود\nنشرت منها خمارا في الفخار طوى … مع النوائب تيجان الصناديد\nشريفة رشحت منها مناسبها … لحلية العز مجرى الليث والجيد\nما كنت تقبل بذل الدهر تكرمة … حتى حباك ببذل غير مردود\nأعطاك كنز فخار كان يصرفه … من نسل غيرك في شتى عباديد\nشجى لنفس شجاع الحرب معترضا … وفرحة لفؤاد العاتق الرود\nفرقت عنك العدى تدمى ضمائرها … بباع عز على الأيام ممدود\nلا زلت تملك ، والأحداث راغمة … عناق غصن الأماني غير مخضود\nوتستنير لك الأيام ملهية … ينمى بها كل إصباح إلى عيد\nيا مطلق السمع والاسماع ما برحت … أسيرة في يدي عذل وتفنيد\nورب رزء من الايام منهجهم … عزاك منه النهى عن خير مفقود\nما زلت ترقب إحسان الزمان له … حتى تبدلت مولودا بمولود"},{"id":"diwan-radi:157","bookId":"diwan-radi","type":"poem","seq":157,"chapter":"البحر: طويل","title":"عجبت من الايام انجازها وعدي","page":"","text":"عجبت من الايام انجازها وعدي … وتقريبها ما كان مني على بعد\nوإن الليالي ، مذ لبست رداءها … تحاذر من حدي فتزري على جدي\nولي ان يطل عمري مع الدهر وقفة … تذلل احداث الزمان لمن بعدي\nواني لمر البأس مسترعف الظبى … واني لحلو الجود مستمطر الرفد\nإذا بزني مالي عطاء تركته … حميدا ، وطالبت القواضب بالرد\nوقد عجمت مني الليالي مذربا … تخلل أنياب الأساود والأسد\nاذا خب فيه ملء حيزومه الجوى … توقر يخفى منه غير الذي يبدي\nوكنت اذا الايام جلن بساحتي … رجعن ولم يبلغن اخر ما عندي\nولكنها نفس ، كما شئت ، حرة … تصول ولو في ماضغ الاسد الورد\nواعظم ما القيت شجوا ولوعة … عتاب اخ فل الزمان به حدى\nأقيك الردى ما كان ما كان عن قلى … ولكن هنات كدن يلعبن بالجلد\nولا تحسبن القلب جازت كلومه … إلى القلب ، إلا بعدما حز في الجلد\nمنحتك ما عندي من الصد معلنا … وعقد ضميري أن أدوم على الود\nولم اغد محلول اللحاظ طلاقة … وقلبي معقود الجنان على الحقد\nسجايا رعين المجد في تلعاته … وناقلن في العلياء غورا الى نجد\nوقد كنت ابغي رتبة بعد رتبة … فآنف لي من أن أفوز بها وحدي\nحفاظا على القربى الرؤوم ، وغيرة … على الحسب الداني وبقيا على المجد\nولم لا ؟ ونحن الراجعان من العلى … إلى المغرس الريان والسؤدد الرغد\nمن القوم أشباه المكارم فيهم … وعرق المعالي الغر والحسب العد\nحسدت عليك الأجنبين محبة … ونافست فيك الابعدين على الود\nوقد كان لذع ، فاتقيت شباته … بقلب على الضراء كالحجر الصلد\nتجلدت حتى لم يجد في مغمزا … وعدت كما عاد الجراز الى الغمد\nوها انا عريان الجنان من التي … تسوء ومنفوض الضلوع من الوجد\nوكم سخط أمسى دليلا إلى رضى … وكم خطأ اضحى طريقا الى عمد\nأقلب عينا في الإخاء صحيحة … اذا ارتمت الاعداء بالاعين الرمد\nواني مذ عاد التودد بيننا … تجلى الدجى عن ناظري وورى زندي\nوعاد زماني بعدما غاض حسنه … أنيقا كبرد العصب أو زمن الورد\nوكنت سليب الكف من كل ثروة … فأصبحت من نيل الأماني على وعد\nوفارقت ضيق الصدر عنك إلى الرضى … كما نشط المأسور من حلق القد\nوقد ضمني محض الصفاء وصدقه … اليك كما ضمت ذراع الى عضد\nوكنت على ما بيننا من عيابه … اعدك جدي حين اسطو على ضدي"},{"id":"diwan-radi:158","bookId":"diwan-radi","type":"poem","seq":158,"chapter":"البحر: طويل","title":"تكشف ظل العتب عن غرة العهد","page":"","text":"تكشف ظل العتب عن غرة العهد … وأعدى اقتراب الوصل منا على البعد\nتجنبني من لست عن بعض هجره … صفوحا ولا في قسوة عنه بالجلد\nنضته يد الإعتاب عما سخطته … كما ينتضى العضب الجراز من الغمد\nوكنت على ما جره الهجر ممسكا … بحبل وفاء غير منفصم العقد\nامين نواحي السر لم تسر غدرة … ببالي ولم أحفل بداعية الصد\nتلين على مس الاخاء مضاربي … وان كنت في الاقوام مستحسن الجد\nولما استمر الببين في عدوائه … تغول عفوي أو ترقى الى جهدي\nاصاحب حسن الظن والشك مقبل … بوجهي إلى حيث استرثت عرا الود\nاذا اتسعت في خطة الصد فكرتي … تجللني هم يضيق به جلدي\nوان ناكرتني خلة من خلاله … تعرض قلبي يفتديها من الحقد\nيخال رجال ما رأوا لضلالة … ولن تستشف الشمس بالاعين الرمد\nوكم مظهر سيما الوداد يرونه … حميدا وما يخفي بعيد من الحمد\nوحوشيت ان القاك سبطا تظاهري … وان كنت مطويا على باطن جعد\nإذا تركت يمنى يديك تعلقي … فيا ليت شعري من تمسك من بعدي ؟\nإيابا فلم نشرف على غاية النوى … ولم تنأ كل النأي عن سنن القصد\nفللدر نثر ليس يدفع حسنه … وليس كما ضمته ناحية العقد\nولو لم يلاق القدح زندا بمثله … لما انبعث شهب الشرار من الزند\nوقد غاض سخطانا فهل من صبابة … برأيك اني قد تصرم ما عندي\nهلم نعد صفو الوداد كما بدا … اعادة من لم يلف عن ذاك من بد\nونغتنم الأيام وهي طوائش … تؤاتي بلا قصد وتأبى بلا عمد\nومثلك أهدى أن يعاد إلى الهدى … وأرشد أن ينحاز عن جهة القصد"},{"id":"diwan-radi:159","bookId":"diwan-radi","type":"poem","seq":159,"chapter":"البحر: كامل تام","title":"يا دار من قتل الهوى بعدي","page":"","text":"يا دار من قتل الهوى بعدي … وجدوا ولا مثل الذي عندي\nلا تعجبي ، يا دار ، أنهم … ابدوا ومن يك واجدا يبدي\nربع قريب العهد أحسبه … بالظاعنين وقد مضى عهدي\nلو حركت ذاك الرماد يد … لرأت بقايا الجمر والوقد\nإني ليعجبني حماك ، إذا … نشر النسيم ذوائب الرند\nوالماء تصقله الرياح كما … ابدى العياب مضاعف السرد\nحيا مريض ثراك غادية … تعطيه ريح العنبر الورد\nاو ذات نهد بين سارية … يتلويان تلوي القد\nيتشقق البرق اللموع بها … وتروعه بتهزم الرعد\nلي مقلة ما تستفيق جوى … تدمى ويقرع ماؤها خدي\nوالعيس ما وجدت تحن ، ولا … تخفى واكتم دائما وجدي\nوملام ايام وليس لها … عطف وبعض اللوم لا يجدي\nلا خير في دنيا نوائبها … تدوي ، وداء منونها يعدي\nلا تحسبن الرزق مطرحا … فالرزق بين مواضع الاسد\nولرب مصحوب غرضت به … غرض الخوامس من قذى الورد\nداني يدي فنفضتها حذرا … من ان يدنس هزله جدي\nومبخل إن جاد بعد مدى … فالمتاء يطلع من صفا صلد\nكيف السبيل إلى بلهنية … في ذا الزمان وعيشة رغد\nفي كل ليل لي وقود منى … ومطامع وسدتها عضدي\nوالمرء ما أرضى أمانيه … ينقاد من لعب الى جد\nوجهي مجال للطعان ، فما … خوفي لقاء الحر والبرد\nفلاشربن مناقبا بدمي … ولانقبن على العلى جهدي\nولارحلن العيس مرحلة … عوجاء بين القور والوهد\nعلي ألاقي من أسر به … ويفل عند لقائه كدي\nوأتوب من ذم الزمان ، إذا … علقت يداي يدي ابي سعدي\nخلي ، وإن بعد الزمان به … يوما ، وماطلني به وعدي\nومطالعي في الأنس إن لويت … عني الرقاب ولج في صدي\nلا تحسبوا ذا البعد غيرني … فالبعد غير مغير ودي\nوإذا الفتى حسنت رعايته … في القرب ضاعفها على البعد\nلو تسألون دمي سمحت به … من غير معصية ، ولا رد\nاو كان جلد يستعار اذا … يوم الطعان ، لعرتكم جلدي\nاو ان خطوا يستراب به … منكم سحبت ورائكم بردي\nكانت غيابة حادث فجلا … ديجورها قمر من السعد\nونهصت منها غير مكترث … مثل الحسام نزا من الغمد\nالله جارك ما رمتك نوى … تذري الركائب أو قطا الجرد\nوانا الذي ان تدج نائبة … يصبح أمامك موريا زندي"},{"id":"diwan-radi:160","bookId":"diwan-radi","type":"poem","seq":160,"chapter":"البحر: طويل","title":"أسائل سيفي : أي بارقة تجدي","page":"","text":"أسائل سيفي : أي بارقة تجدي … ولي رغبة عمن يعلل بالوعد\nوأطلب في الدنيا العلى ، وركائبي … مقلقلة ما بين غور إلى نجد\nيشتت ترب القاع وسم اكفها … واخفافها في حيز النص والوخد\nوخطة ضيم خادعتني ، ففتها … الى مطلع بين المذمة والحمد\nويوم من الشعرى خرقت وشمسه … تساقط من هام الإكام إلى الوهد\nوليل دجوجي كأن ظلامه … سماوة ملوي الذراعين بالقد\nخطوت ، وفي كفي خطام نجيبة … مدفعة من كل قرب إلى بعد\nاذا لحظت ماء جذبت زمامها … وقلت : ارغبي بالعز عن مورد ثمد\nتؤمين خير الأرض أهلا وتربة … يحط بها رحل المكارم والمجد\nوفي الارض قوم يلطمون جباههم … اذا هجمت اعلى المنازل بالوفد\nوتنبو أكف العيس عن عرصاتهم … من البخل حتى تستغيث الى الطرد\nفما خدعتها روضة عن مسيرها … ولا لمع معسول تطلع من ورد\nاكف بني عدنان تستمطر الظبى … وتأنف من جود الغمائم بالعهد\nوتلقى الوغى ، واليوم ينصر بيضه … على البيض في مجرى من الجد والجد\nمنازلهم عقر المطايا ، وإنما … تعقلها بالبشر والنائل الجعد\nجذبتم بضبع المجد يا آل غالب … وغادرتم الاعدام منعقر الخد\nعلى حين سدت ثلمة العار عنكم … صدور العوالي والمطهمة الجرد\nوكم غارة أقبلتموها مواقرا … من الاسل الذيال والبيض والسرد\nكما قاد علوي السحاب غمامة … وجلجلها ملء من البرق والرعد\nكفى أملي في ذا الزمان وأهله … علي مجيرا من يد الدهر أو معدي\nفتى ما مشى في سمعه شدو قينة … ولا جذبت أحشاءه سورة الوجد\nولا هجر السمر العوالي للذة … ولا عاتب البيض الغواني على الصد\nاذا اظلمت آمال قوم بردها … أضاء سنا معروفه ظلمة الرد\nوان شام يوما ناره خلت انها … تطلع نحو الواردين من الزند\nوكم بين كفيه اذا احتدم الردى … وبين العوالي من زمام ومن عقد\nليهنك يا بن الاكرمين بن حرة … تمزق عنه النحس عن غرة السعد\nفرب له خيل الوغى ، فلمثله … تربي اللليالي كاهل الفرس النهد\nوبشر به البيض الصوارم والقنا … وبشره عن قول النوائب بالجلد\nستذكره والحرب ينكحها الردى … وقد طلقت أغمادها قضب الهند\nكاني به جار على حكم سيفه … يعاهده ان لا يبيت على حقد\nإذا أنهضته للنزال حفيظة … وأنهض مستن الحسام من الغمد\nوارخي بعطفيه حواشي نجاده … وجر على اعقابه فاضل البرد\nوعطف خرصان الرماح كأنها … من الدم في أطرافها شجر الورد\nوزعزع نظم الرمح حتى برده … نثارا على الأعداء بالحطم والقصد\nوشايح عن احسابه بحسامه … وذب عن العرض الممنع بالرفد\nرأيت فتى في كفه سمة الندى … وفي وجهه شبه من الاب والجد\nاذا ما اجتبى في الحي وامتد باعه … رأيت اباه حين يحكم أو يجدي\nإلى جده تنمى شمائل مجده … وهل ترجع الاشبال الا الى الاسد\nوليد همى ماء العلى في جبينه … وقد شمت منه بارق الحسب العد\nفلو قيل يوما اين صفوة يعرب … رأيت العلى تومي إلى ذلك المهد\nإلى ربعك المألوف مني تطلعت … رقاب القوافي تحت أدعج مزبد\nولما بعثت الشعر نحوك قال لي : … الان فعق الا الى بابه قصدي\nسقيت الندى شعري ، فأنبت حمده … ولو صاب في جسمي لأنبته جلدي\nوإني لأستحيي العلى فيك أن أرى … ضنينا من الشعر المصون بما عندي\nكبت الحسود الندب حتى كببته … فمن عاذري يوما من الحاسد الوغد\nاذا الشمس غاضت كل عين صحيحة … فكيف بها في هذه المقل الرمد"},{"id":"diwan-radi:161","bookId":"diwan-radi","type":"poem","seq":161,"chapter":"البحر: كامل تام","title":"هو سيف دولتنا الذي يوم الوغى","page":"","text":"هو سيف دولتنا الذي يوم الوغى … يفرى قلوب عداته بفرنده\nيعدو بطرف ان جرى سبق الردى … وبصارم يسم الطلى في غمده\nجار ، ولكن رأيه في جريه … ماض ولكن عزمه في حده"},{"id":"diwan-radi:162","bookId":"diwan-radi","type":"poem","seq":162,"chapter":"البحر: رجز تام","title":"أبارق طالعنا من نجد","page":"","text":"أبارق طالعنا من نجد … يضيء في عارضه المربد\nمستعبرا عن زفرات الرعد … ماء كما ارتجت شعاب العد\nيقرن أعناق الربى بالوهد … ومنهل مبرقع بالثمد\nهتكته باليعملات الجرد … ملثمات باللغام الجعد\nيفقأن بالمصدر عين الورد … وليلة صدية الفرند\nبيض النجوم واحمرار الوقد … مثل سماطي نرجس وورد\nأو مقل صحائح ورمد … تنازع اللحظ وليس تعدي\nيقول لي الدهر الا تستجدي … اين ضياء المطلب المسود\nارى الليالي يشتهين بعدي … ولا يقربن يدا من زندي\nيلجن بين صارمي وغمدي … كأن صمصامي بغير حد\nوحاجتي تصلى بنار لرد … ألاحظ الغي بعين الرشد\nولا أبالي من تمادي بعدي … أعوذ من رزق بغير كد\nفي ذا الورى قلب بغير حقد … من ذا الذي على الزمان يعدي\nكل جواد كاذب في الوعد … وكل خل خائن في الود\nيحل بالعذر نطاق العهد … لا عانقت هوج الرياح بردي\nإلا على ظهر أقب نهد … يخطو على ململمات ملذ\nكأنه في سرعان الوخذ … يلعب في ارساغه بالنرد\nيا أيها المخوفي بسعد … طرحتني بين النيوب الدرد\nولو أتاك النصر من معد … جلجلت من لحمى زئير الاسد\nأها لنفس حبست في جلدي … ان الاسير غرض بالقد\nاشرف ذخري صارم في الغمد … إن العلى نشو سيوف الهند\nلا بد أن أطرق باب الجد … واجعل الخلة عرس الرفد\nويطرد الليل لسان زندي … حتى أقاس بأبي وجدي\nهنئت يا مالك رق المجد … ومتعبي دون الورى بالحمد\nمنك العطايا والمنى من عندي … "},{"id":"diwan-radi:163","bookId":"diwan-radi","type":"poem","seq":163,"chapter":"البحر: وافر تام","title":"لحيا عهدهن حيا العهاد","page":"","text":"لحيا عهدهن حيا العهاد … ندى يغتص منه كل ناد\nواطلالا يطل الدمع فيها … إذا بدت الحواضر والبوادي\nرواء لا تريح الريح فيها … من الادلاج انتاج الغوادي\nإذا مات الحيا بين السواري … أتاها بالغوادي في معاد\nمجاهل منزل كانت زمانا … معالم كل مكرمة وآد\nتكف ربوعها ايدي الاماني … وقد عانقن أعناق الأيادي\nإذا حل الحبى أمل طريف … حبته مهجة المال التلاد\nفما لي واللقاء وكل يوم … تهددني الركائب بالبعاد\nدعى عذلي فليس العذل يجني … به ما أثمرت شيمي وعادي\nولي عزم تعوذ به العوالي … إذا فزعت إلى مهج الاعادي\nيضم شعاعه قلب ولكن … تضيق به حيازيم البلاد\nوكم قلب أسر علي حقدا … فأفشى سره سر النجاد\nويوم تعثر الخرصان عمدا … به في كل نحر أو فؤاده\nيشق الروع عن ضاحي بدور … برزن من العجاجة في دآد\nتريهم فيه مرآة المنايا … بصدق يقينهم وجه المعاد\nوحشو أكفهم سمر رواء … بورد الموت من مهج صواد\nتهديها إلى الطعن المنايا … بحيث تضل في طرق الهوادي\nوقد نشأت سحاب من عجاج … تعط صدورها أيدي الجياد\nبارماح خلقن من المنايا … واسياف طبعن على الجلاد\nزرعت اسنتي في كل قلب … بها والهام تزرع بالحصاد\nوبحر دم تعوم الطير فيه … وترقى بين امواج الطراد\nتراها في فروج النقع حمرا … كما طار الشرار عن الزناد\nوليل بات يصلت لي هموما … يطل بغربهن دم الرقاد\nوكيف يحب اغمار الليالي … أسير الطرف في أيدي السهاد\nفلو حل المؤمل عقد همي … شددت بمقلتي عرى الرقاد\nواني وهو في خيشوم مجد … تنفس عن نسيم من وداد\nكأن عهودنا كانت قلوبا … تربي بين احشاء العهاد\nاينسبني له ظن غوي … وكان الغي يمكر بالرشاد\nإذا فثكلت سابحثي وسيفي … غداة وغى ، وراحلتي وزادي\nاتخلع حليك الاشعار عنها … اذا كسيت من المعنى المعاد\nومن هذا يقوم مقام فضل … قعدن له ذرى الصم الصلاد\nأأترك ضيغما في ظهر طود … وآخذ تتفلا في بطن واد\nوألفظ صفو أحشاء الغوادي … واجرع رنق احشاء الثماد\nوقد علمت ربيعة أن بيتي … لغير الغدر ، مرفوع العماد\nأتتك قلادة لم يخل منها … صليف الجود أو جيد الجواد\nفمن لم يجر دمعته عليها … فخاطره افظ من الجماد\nوما أجني بها عذرا ولكن … محافظة على ثمر الوداد"},{"id":"diwan-radi:164","bookId":"diwan-radi","type":"poem","seq":164,"chapter":"البحر: خفيف تام","title":"مرضت بعدكم صدور الصعاد","page":"","text":"مرضت بعدكم صدور الصعاد … لا دواء الا قلوب الاعادي\nان خير الرماح ما شرقت با … طعن منها معاقد الأكباد\nاي خطب ارخى ذؤابة ليل … لم أجبه من عزمتي بزناد\nحكم الدهر أن صاحب ذا العي … عيش قتيل المنى بغير مراد\nوقصير الغنى طويل يد الجو … د ثقيل الحجى خفيف العتاد\nكلما قلت روحتني الليالي … ضربت بي آفاق هذي البلاد\nوتلقت بي الظلام ، رديف ال … جم بين الاتهام والانجاد\nوعتاب الزمان مثل عتاب العين … عين تنهى ، ودمعها بازدياد\nضجت الخيل من سراياي حتى … لحسدن البطاء قب الجياد\nكل يوم اقودها شائمات … بارق الموت من سماء الجلاد\nبليوث تقري الهجير وجوها … تقطر المجد بين قار وباد\nشرقت غرة القريض بندب … اشرقت عنده وجوه الايادي"},{"id":"diwan-radi:165","bookId":"diwan-radi","type":"poem","seq":165,"chapter":"البحر: طويل","title":"لاي حبيب يحسن الرأي والود","page":"","text":"لاي حبيب يحسن الرأي والود … وأكثر هذا الناس ليس له عهد\nارى ذمي الايام ما لا يضرها … فهل دافع عني نوائبها الحمد\nوما هذه الدنيا لنا بمطيعة … وليس لخلق من مداراتها بد\nتحوز المعالي والعبيد لعاجز … ويخدم فيها نفسه البطل الفرد\nاكل قريب لي بعيد بوده … وكل صديق بين اضلعه حقد\nولله قلب لا يبل غليله … وصال ، ولا يلهيه عن خله وعد\nيكلفني أن أطلب العز بالمنى … واين العلى ان لم يساعدني الجد\nاحن وما اهواه رمح وصارم … وسابغة زغف ، وذو ميعة نهد\nفيا لي من قلب معنى به الحشا … ويا لي من دمع قريح به الخد\nأريد من الأيام كل عظيمة … ومابين اضلاعي لها اسد ورد\nوليس فتى من عاق عن حمل سيفه … إسار ، وحلاه عن الطلب القد\nاذا كان لا يمضي الحسام بنفسه … فللضارب الماضي بقائمة الحد\nوحولي من هذا الأنام عصابة … توددها يخفى واضغانها تبدو\nي سر الفتى دهر ، وقد كان ساءه … وتخدمه الأيام ، وهو لها عبد\nولا مال إلا ما كسبت بنيله … ثناء ولا مال لمن لا له مجد\nوما العيش الا تصاحب فتية … طواعن لا يعنيهم النحس والسعد\nإذا طربوا يوما إلى العز شمروا … وان ندبوا يوما الى غارة جدوا\nوكم لي في يوم الثوية رقدة … يضاجعني فيها المهند والغمد\nإذا طلب الأعداء إثري ببلدة … نجوت وقد غطى على أثري البرد\nولو شاء رمحي سد كل ثنية … تطالعني فيها المغاوير والجرد\nنصلنا على الاكوار من عجز ليلة … ترامى بنا في صدرها القور والوهد\nطردنا إليها خف كل نجيبة … عليها غلام لا يمارسه الوجد\nودسنا بأيدي العيس ليلا ، كأنما … تشابه في ظلمائه الشيب والمرد\nالا ليت شعري هل تبلغني المنى … وتلقى بي الاعداء احصنة جرد\nجواد وقد سد الغبار فروجها … تروح الى طعن القبائل أو تغدوا\nخفاف على إثر الطريدة في الفلا … إذا ماجت الرمضاء واختلط الطرد\nكأن نجوم الليل ، تحت سروجها … تهاوى على الظلماء والليل مسود\nيعيد عليها الطعن كل بن همة … كأن دم الاعداء في فمه شهد\nيضارب حتى ما لصارمه قوى … ويطعن حتى ما لذابله جهد\nتغرب لا مستحقبا غير قوته … ولا قائلا إلا لما يهب المجد\nولا خائفا إلا جريرة رمحه … ولا طالبا إلا الذي تطلب الأسد\nإذا عربي لم يكن مثل سيفه … مضاء على الأعداء أنكره الجد\nوما ضاق عنه كل شرق ومغرب … من الارض الا ضاق عن نفسه الجلد\nإذا قل مال المرء قل صديقه … وفارقه ذاك التحنن والود\nواصبح يغضي الطرف عن كل منظر … أنيق وبلهيه التغرب والبعد\nفمالي وللايام ارضى بجورها … وتعلم اني لا جبان ولا وغد\nتغاضى عيون الناس عني مهابة … كما تتقي شمس الضحى الاعين الرمد\nتخطت بي الكثبان جرداء شطبة … فلا الرعي دان من خطاها ولا الورد\nتدافع رجلاها يديها عن الفلا … إلى حيث ينمى العز والجد والجد\nفجاءتك ورهاء العنان بفارس … تلفت حتى غاب عن عينه نجد\nومثلك من لا توحش الركب داره … ولا نازل عنها إذا نزل الوفد\nفيا لآخذا من مجده ما استحقه … نصيبك هذا العز والحسب العد\nأب أنت أعلى منه في الفضل والعلى … وامضى يدا والنار والدها زند\nوما عارض عنوانه البيض والقنا … أخو عارض عنوانه البرق والرعد\nوكم لك في صدر العدو مرشة … يخضب منه الرمح منبعق ورد\nوفوق شواة الذمر ضربة ثائر … يكاد له السيف اليماني ينقد\nيود رجال انني كنت مفحما … ولولا خصامي لم يودوا الذي ودوا\nمدحتهم فاستقبح القول فيهم … ألا رب عنق لا يليق به عقد\nزهدت وزهدي في الحياة لعلة … وحجة من لا يبلغ الامل الزهد\nوهان على قلبي الزمان واهله … ووجداننا ، والموت يطلبنا ، فقد\nوأرضى من الأيام أن لا تميتني … وبي دون أقراني نوائبها النكد"},{"id":"diwan-radi:166","bookId":"diwan-radi","type":"poem","seq":166,"chapter":"البحر: كامل تام","title":"ليت الخيال فريسة لرقادي","page":"","text":"ليت الخيال فريسة لرقادي … يدنو بطيفك عن نوى وبعاد\nولقد اطلت الى سلوك شقتي … وجعلت هجرك والتجنب زادي\nأهون بما حملتنيه من الضنى … لو أن طيفك كان من عوادي\nولقلما نزل الخيال بمقلة … روعاء نافرة بغير رقاد\nما تلتقي الأجفان منها ساعة … وإذا التقت فلغض دمع باد\nلا يبعدن قلبي الذي خلفته … وقفا على الإتهام والإنجاد\nإن الذي عمر الرقاد وسادة … لم يدر كيف بنا علي وساد\nلا زال جيب الليل منفصم العرى … عن كل اوطف مبرق مرعاد\nيسقى منازل عاث فيهن البلى … من أن يراق على يدي بأباد\nوإذا الرياح تبوعت ، فصدورها … لعناق حاضر ارضكم والبادي\nولقد بعثت من الدموع اليكم … بركائب ومن الزفير بحاد\nإني متى استنجدت سرب مدامع … خذلته اسراب الفراق العادي\nلولا هواك لما ذللت وانما … عزي يعيرني بذل فؤادي\nما للزمان يذودني عن مطلبي … ويريغني عن طارفي وتلادي\nيحنو علي اذا اقمت كانني … الاسرار في احشاء كل بلاد\nعادات هذا الناس ذم مفضل … وملام مقدام وعذل جواد\nولقد عجبت ، ولا عجيب أنه … كل الورى للفاضلين اعادي\nوارى زماني يستلين عريكتي … وارى عدوي يستحر عنادي\nاتظنني القي اليك يدا وما … بيني وبينك غير ضرب الهادي\nاسعى لكل عظيمة فانالها … عزما يفوت هواجس الحساد\nعزما قويا لا يشاور رقبة … للخطب في الاصدار والايراد\nما زال يشهد لي إذا استنطقته … بالجود في ليلي ، لسان زنادي\nإني لتحقن ماء وجهي همتي … من ان يراق على يدي باياد\nمما يقلل رغبتي أني أرى … صفدي ببذل المال مثل صفادي\nوالمال اهون مطلبا من ان ارى … ضرعا أرامي دونه وأرادي\nومناضل عثرت به احسابه … في مسلك وعر من الاجداد\nخلقت عرف جواده بنجيعه … والسبق في طلق الردى لجوادي\nولرب يوم غضة أطرافه … صقلت بخطو روائح وغوادي\nيوم اراق دم الغمام على السرى … بظبى من الإيماض غير حداد\nولغرة الجو الرقيق أسرة … يلمعن من قطع السحاب الغادي\nجاذبته صافي اديم هجيره … واليعملات شواحب الأعضاد\nفي فتية سلبوا النهار ضياءه … ورموا بياض جبينه بسواد\nوحشوا حشا الظلماء ملء جنانها … حتى تصدع بالصديع البادي\nوكانما بيض النجوم فواقع … في زاخر متتابع الإزباد\nنالوا على قدر الرجاء وانما … يروى على قدر الاوام الصادي\nقوم إذا قرعوا زنودا للقرى … ستروا فروج النار بالوراد\nما ضل في قلب امرء امل سرى … إلا وجودهم الهدى والهادي\nطنب يعثرن الخطوب ، وباحة … ممنوعة إلا من الرواد\nسحبوا أنابيب القنا ، فكأنما … سحبوا بهن حواشي الأبراد\nيزجرن جردا لا تقر على الثرى … مرحا كان الترب شوك قتاد\nمن كل تلعاء المناكب جيدها … \nضربوا قباب البيض فوق مفارق … اطنابها شرع القنا المياد\nذبل يهذ بها الطعان وانها … تزداد جهلا كل يوم جلاد\nيحملن عبء الموت وهي خفايف … في الطعن بين جناجن وهواد\nهم أنشبوا قصد القنا من وائل … من حيث نار الحقد في ايقاد\nولغوا بوقع حوافر في مأزق … ملأوا بهن مسامع الأصلاد\nنجب نفضن له الفرائص خيفة … تحت العرين ، براثن الآساد\nلبست له الحرب المشوبة قبلة … وتعودت منه صدور صعاد\nولدت وجوههم العجاجة طلعة … وظبى السيوف ثواكل الاغماد\nمن كل نصل أضمرت أحشاؤه ال … أرواح وهو حشى بغير فؤاد\nالخيل ترتشف الصعيد بسورها … طردا ، وتلفظه على الأكتاد\nاقبلن مثل السيل صوب عنقه … نشز العقاب الى قرار الوادي\nوتكاد تمسح من دماء جراحها … اثار ما نقشت على الاطواد\nترجيع قعقعة الشكيم اذا سرت … لعداتها ، بدل من الإيعاد\nيوم كأن الأرض فيه عانقت … صدر السماء بعارض منقاد\nويكاد جامحه يثقف في الطلى … بالطعن اطراف القنا المنآد\nوكأنهن ، إذا انحنين ، رواكع … صلت الى قبل من الاكباد\nوشققن اردية الضغائن بالردى … من بعد ما شملت قلوب إياد\nان يسلبوا ضافي الدروع فانهم … كاسون من علق دروع جساد\nرجع الضراب رجالهم بعمائم … محمرة ونساهم بحداد\nلا ينقضون بنى الحقود كأنما … شيدت طلوعهم على الاحقاد\nمهج كأنبوب اليراع ، إذا عدا … روع وعند المطمعات عوادي\nكادت تطير مخافة لو لم تكن … من شرع الأرماح في أسداد\nبلغت لنا الأرماح كل طماعة … وحوت لنا الاسياف كل مراد\nانا خل كل فتى اذا ايقظته … ايقظت كالنضاض أو كالعادي\nألف الحسام ، فلو دعاه لغارة … عجلان صاحبه بغير نجاد\nكفاه تصديها الدماء من القنا … طورا ، ويصقلها الندى في النادي\nان جاد اقنى المعسرين وان سطى … افنى القنى بمواير الفرصاد\nمن مبلغ الشعراء عني ان لي … قول الفحول ونجدة الانجاد\nقد كان هذا الشعر ينزع في الدنا … عنهم فكان عقالة ميلادي"},{"id":"diwan-radi:167","bookId":"diwan-radi","type":"poem","seq":167,"chapter":"البحر: متقارب تام","title":"أراك ستحدث للقلب وجدا","page":"","text":"أراك ستحدث للقلب وجدا … اذا ما الظعائن ودعن نجدا\nبواكر يطلعن نقب الغوير … شأون النواظر نأبا وبعدا\nتتبعهم نظرات الصقور … ن هفهفة الطير جدا\nعلى قنوين ، ألا من رأى … ظعائن بالطعن والضرب نجدا\nنخالسها من خلال القنا … سلاما ، ونعلم أن لا تردا\nكأن هوادجها والقباب … يثنين منهن بانا ورندا\nفما شئت تنسم بالقلب نشرا … وما شئت تقطف بالعين وردا\nكان قواني انماطها … قطوع رياض من الطل تندى\nيصدون عنا بلمع الخدود … ويمنعنا وجدنا أن نصدا\nكأنا بنجد غداة الوداع … نصادي عيونا من الدمع رمدا\nوايسر ما نال منا الغليل ان … لا نحس من الماء بردا\nاثاروا زفيرا يلف الضلوع … لف الرياح انابيب ملدا\nفكل حرارة انفاسه … تدل على أن في القلب وقدا\nواني للشوق من بعدهم … أراعي الجنوب رواحا ومغدى\nوأفرح من نحو أوطانهم … بغيث يجلجل برقا ورعدا\nإذا طلع الركب يممته … احيي الوجوه كهولا ومردا\nوأسألهم عن جنوب الحمى … وعن أرض نجد ومن حل نجدا\nنشدتكم الله ، فليخبرن … من كان أقرب بالرمل عهدا\nهل الدار بالجزع مأهولة … انار الربيع عليها واسدى\nوهل حلب الغيث أخلافه … أأحصيتم رمل يبرين عدا\nوهل أهله عن تنائي الديار … يراعون عهدا ويرعون ودا ؟\nلئن اقرض الله ذاك النعيم … فيهم ، لقد كان فرضا مؤدى\nاعار الزمان ولكنه … تعقب اعطاؤه فاستردا\nانا ابن العرانين من هاشم … ارق القبائل راحا واندى\nاكنهم للمراميل ظلا … وأثقبهم للمطاريق زندا\nسراع الى نزوات الخطوب … يهزون سمرا ويمرون جردا\nكان الصريخ يهاهي بهم … أسودا تهب من الغيل ربدا\nاذا اغرقوا بيضهم في الطلى … وساموا القنا من دم الطعن وردا\nعلى القب تشغلهن السياط … امام الرعيل عنيفا وشدا\nرمين السخال ، وقين النفوس … حتى بلغن لغوبا وجهدا\nفما اومؤا بصدور الرماح … يوما إلى القرن إلا تردى\nسيوف تطيل قراعا وقرعا … وخيل تعيد طرادا وطردا\n … قتلا بيوم طعان وصفدا\nوكم صاف من دارهم سيد … وقاظ يعالج في الجيد قدا\nكان الفتى منهم في النزال … يرى اكبر الغنم ان قيل اودى\nولا يحمد العيش في يومه … اذا لم يلاق من السيف هدا\nيبيت على ظبتي همة … يجاثي خصوما من النوم لدا\nإذا غل أيدي الرجال النعاس … شد على العضب باعا اشدا\nواصبح تزفيه ريح العجاج … غضبان اعجل ان يستعدا\nوسيان من جر عزماته … وحيدا إلى الروع أو جر جندا\nيرى مهربا فيلاقي الردى … لقاء امرىء لا يرى منه بدا\nمضيء المحيا كأن الجمال … اذا هب منه جبينا وخدا\nترى وجهه في حضور الندى … كالعضب رقرقت فيه الفرندا\nينير ويلحم في خفية … إلى أن يحوك من الرأي بردا\nبني عمنا أين قحطانكم … إذا عب بحر نزار ومدا\nمضغناكم اذا عددنا قريشا … ونلهمكم إذ بلغنا معدا\nهم ألدغوكم حماة الرماح … ولدوكم بظبى البيض لدا\nحموكم منابت عشب البلاد … تحلوا من النور سبطا وجعدا\nوساموا بنجد مطاياكم … لما نشطت منه بالغور ردا\nلنا من تعج الورى باسمه … إلى الله ندعوه في المجد جدا\nوبيت تهاوى إليه المطي … تهز الدلاء ذميلا ووخدا\nبنا أنقذ الله هذا العريب … حتى استقام الى الدين قصدا\nوذل غواشيه من بعد ما … سعى في الذلالة سعيا مجدا\nواخفت زمجرة المشركين … يفري الجماجم قطا وقدا\nفاكثر بما طل تلك الدماء … واعظم بما جر بدرا واحدا\nوان لنابض تلك العروق … إذا عدن ينبضن كيا معدا\nفلا تشمخن يابن ام الضلال … بجدي وجدت من النار بردا\nأجار على عجل أخمصيك … زلق الغي اذ كدت تردا\nواعتق عنقك من سيفه … فأصبح رأسك حرا وعبدا\nيزيد على مشتهى الجود جودا … ويبني على غاية المجد مجدا\nنلين عطائفنا للقريب … ونولي المجانب قربا اجدا\nوليس لنا شبخ الراحتين … إذا جاد أعطى قليلا وأكدى\nلقد زجر المجد حتى اصاب … بنا مطلع النجم لا بل تعدى\nكذاك مناقبنا فانظروا … \nسبقنا الى المجد من كان قبلا … فكيف نقاس بمن جاء بعدا"},{"id":"diwan-radi:168","bookId":"diwan-radi","type":"poem","seq":168,"chapter":"البحر: سريع","title":"لو علمت اي فتى ماجد","page":"","text":"لو علمت اي فتى ماجد … ذات اللمى والشنب البارد\nلما وفى لي موعدي بالنوى … من غير ذنب ووفى واعدي\nكالغصن مهزوزا ، ولكنه … يفعل فعل الخطل المائد\nأضللت قلبي فيك عمدا وقد … تعين الثأر على العامد\nفهل لما اضللت من ناشد … وهل لما ضيعت من واجد\nقلوبنا عندك معقودة … بطرف ذاك الشادن العاقد\nافلتنا ثم ثنى طرفه … تلفت الظبي إلى الصائد\nما انصف الفاسق في لحظه … لما أرانا عفة العابد\nتعزز الحب له ذلة … وناقص الحب الى زائد\nوالمرء محسود بلذاته … والحب ملذوذ بلا حاسد\nيا عذبة المبسم بلي الجوى … بنهلة من ريقك الصارد\nارى غديرا شبما ماؤه … فهل لذاك الماء من وارد\nمن لي به من عسل ذائب … يجري خلال البرد الجامد\nانا ابن من ليس بجد له … من لم يكن بالماجد الجائد\nولم يكن في سلك آبائه … غير طويل الباع والساعد\nقد حلب الدهر أفاويقه … واتبع الشارد بالطارد\nلنا الجبال القود مرفوعة … تزل عنها قدم الصاعد\nلنا الجياد القب أخاذة … على العدى بالامد الزائد\nلنا القنا والبيض مطواعة … في الضرب يعصين يد الغامد\nلنا الأسود الغلب في غيلها … من ثائر باسا ومن لابد\nمن أسد طال به عمره … ومن قريب العمر مستاسد\nيا أيها العائب لي جهلة … حذار من ارقمي الراصد\nأقدم النذر ، ولي سطوة … تنفر النوم عن الراقد\nكلمعة البارق مجتازة … تقضي على زمجرة الراعد\nإن كنت ما جربتني ضاربا … فاصبر لما جاءك من ساعدي\nوهاك من كفي مفروجة … فرج القبا موسية العائد\nرب نعيم زال ريعانة … بلسعة من عقرب الحاسد\nانا الذي ابذل من طارفي … مثل الذي ابذل من تالدي\nما مروتي للناحت المنتحي … يوما ولا غصني للعاضد\nاسعى لقوم قعدوا في العلى … ما أكثر الساعي إلى القاعد\nانا الذي يوطيء اكتافها … ما رن رمح بيدي مارد\nانا الذي يضرم افاقها … كأنها معمعة الواقد\nانا الذي يوجر ابطالها … ضربا كخبط الجمل الوارد\nما انا للعلياء ان لم يكن … من ولدي ما كان من والدي\nولا مشت بي الخيل إن لم أطأ … سرير هذا الأغلب الماجد\nفان انلها فكما رمته … أولا ، فقد يكذبني رائدي\nوالغاية الموت فما فكرتي … أسائقي أصبح أم قائدي"},{"id":"diwan-radi:169","bookId":"diwan-radi","type":"poem","seq":169,"chapter":"البحر: كامل تام","title":"هل ريع قلبك للخليط المنجد","page":"","text":"هل ريع قلبك للخليط المنجد … بلوى البراق تزايلوا عن موعدي\nقالوا غدا يوم النوى فتسلفوا … عضا لأطراف البنان على غد\nرفعوا القباب ، وبينهن لبانة … لم تقضها عدة الغزال الاغيد\nوغدوا غدو الروض ألبسه الحيا … نسجين بين مسرد ومعضد\nووراهم قلب يشاق ومهجة … بردت ردى وغليلها لم يبرد\nلاثوا خدودهم على عين النقا … ودمى النمارق والغصون الميد\nوأهلة بتنا نضل بضوئها … ولقد ترانا بالأهلة نهتدي\nفسقى ثرى تلك الغصون نباته … ما شاء من سبل الغمام المزبد\nولقد مررت على الديار فعزني … جلدي وكان اعز منه تجلدي\nلولا مكاثرة الدموع عشية … لعرفت رسم المنزل المتابد\nلهفي لأيام الشباب على ندى … أطرافهن وظلهن الأبرد\nأيام أنفض للمراح ذوائبي … واروح بين معذل ومفند\nومرجلين من الحمام غرانق … مثل الغصون ثيابها الورق الندي\nمتمليين من الشباب كأنهم … أقمار غاشية الظلام الأربد\nصقلت نصول خدودهم بيد الصبا … مرد العوارض في زمان أمرد\nتستنبط الألحاظ ماء وجوههم … فيكاد ينقع من غضارتها الصدي\nلا تنفر الحسناء من مسي ، ولا … تثنى إذا مدت إلى أرب يدي\nوبياض ما بيني وبين احبتي … يوم اللقاء من الغراب الاسود\nفالان اذ قرع النوائب مروتي … وألن معجم عودي المتشدد\nوقصرن خطوي عن مراهنة الصبا … فخطوت للذات خطو مقيد\nالبستني برد الوقار ضرورة … وارينني جدد الطريق الاقصد\nفاليوم اسلس في القياد وطالما … منعت فضول عزامتي من مقودي\nمالي اذل وصارمي لم ينثلم … بطلى العدى وقناي لم يتقصد\nقد طال في ثوب الهموم تزملي … فلآخذن لنهضتي من مقعدي\nولا ظعنن دجى الظلام بجسرة … هوجاء تسئل موردا عن موارد\nفي غلمة هدموا ذرى عبدية … أنضاء خمس للنجاء عمرد\nتصل الدؤوب كأن طالي أنيق … نضح الذفارى بالكحيل المعقد\nمشق الهجير لحومها وتناضلت … أخفافها بالأمعز المتوقد\nلو عيد من داء الفهاهة واحد … صاحت بها الاعراق دونك فازدد\nحتى اذا ركبوا الروس من الكرى … وتصوب العيون بعد تصعد\nجعلوا الخدود على أزمة ضمر … فتل الكلال قيودهن بلا يد\nمثل الصوارم والدجى أغمادها … حتى تسل إلى المغار الابعد\nانافي الضحى سرج الحصان وفي الدجى … كور على ظهر الأمون الجلعد\nبيدي من الهندي فضل عمامة … لا بد أعصبها برأس مسود\nإني لأغلط آنفا بمواسي … وأقيم من عنق الأبي الأصيد\nقل للعدى ان بت اوقد نارها … ما بيننا أبدا ، إذا لم تخمد\nفدعوا مصاولة الضراغم وانبحوا … نبح الكلاب على نجوم الأسعد\nلا يغررنكم تناوم ضيغم … وتناذروا وثبات أغلب ملبد\nالصارم المشهور ينذر نفسه … فخذوا الحذار من الحسام المغمد\nوأقارب جعلوا العقوق سجية … يتوارثون سفاهة عن قعدد\nلبسوا لنا زرد النفاق فاصبحوا … في ذمة الخلق اللئيم الأوغد\nوكانما تلك الضلوع قساوة … تثنى على قطع الصفاء الجلمد\nقالوا : الصفاح ! فقلت : إن ألية … أن لا أمد يدي بغير مهند\nمن كل منجوب الجنان كانه … في الروع مطرود وان لم يطرد\nان عاين النقعين انكر قلبه … ونجا بناصية الطمر الأجرد\n … عادوه من عي إذا حضر الندي\nمتقدم في لؤمه ميلاده … ومن الخمول كانه لم يولد\nقل للذي بالغي سوى بيننا : … اين الغبار من الجبال الركد\nلا تدنين مواربين دعوتهم … يوم الطعان فسوفوك إلى الغد\nتركوا القنا تهفو إليك صدوره … والقوم بين مهلل ومغرد\nحتى اتقوا بك ثم فاغرة الردى … فنجوا وانت على طريق المزرد\nقذفوك في غمائها وتباعدوا … عنها ، وقالوا : قم لنفسك واقعد\nقطع الزمان قبال نعلك ، فانتعل … أخرى تقيك من العثار وجدد\nيصل الذليل الى العزيز بكيده … والشمس تظلم من دخان الموقد\nواشدد يديك إلى الوغى بمغامر … ندب ، لعادات الطعان معود\nلم ينقتش شوك القنا من جلده … في الروع الا بالقنا المتقصد\nمن كل مربدة النجيع إذا علت … نغراتها قطعت حضور العود\nإن سوموه إلى الرهان ، فإنما … مسحوا جبين مقلد لمقلد\nما عذر من ضربت به اعراقه … حتى بلغن إلى النبي محمد\nأن لا يمد إلى المكارم باعه … وينال منقطع العلا والسؤدد\nمتحلقا حتى تكون ذيوله … أبد الزمان عمائما للفرقد\nأعن المقادر لا تكن هبابة … وتأزر اليوم العصبصب وارتد\nلا تغبطن على البقاء معمرا … فلقرب يوم منية من مولد"},{"id":"diwan-radi:170","bookId":"diwan-radi","type":"poem","seq":170,"chapter":"البحر: مجزوء الرجز","title":"يا قلب جدد كمدا","page":"","text":"يا قلب جدد كمدا … فموعد البين غدا\nلم أر فرقا بعدهم … بين الفراق والردى\nيا زفرة هيجها … حاد من الغور حدا\nأغنى زفير العاشقي … عيسه عن الحدا\nارعى الحمول ناظرا … مزاحم يقذف في\nواطرد الطرف على … اثارهم ما انطردا\nومذ أذابوا ماء عي … جمر الغضا ما خمدا\n … بالاسى ما جمدا\nيا هل ارى من حاجة … حقف النقا والجمدا\nأنا الغلام القرشي … جرعائه وانعقدا\nوهل أعيد ناظرا … يتبع سربا منجدا\nيمشين هزات القنا … مال وما تحصدا\nهل ناشد ينشد لي … ذاك الغزال الاغيدا\nما ضل عني انما … ضل بقلبي كمدا\nرهنته قلبي ، ومن … يرهن قلبا أبدا\nيا منجزا وعيده … وماطلا ما وعدا\nأراك مني أقربا … وان غدوت ابعدا\nعذبت قلبي عنتا … والطرف لا القلب بدا\nرب ثنايا بردت … لذي جوى ما بردا\nيا حر قلبي ! من سقي … رضابهن الابردا\nلم يدر هل ذاق بها … جمر غضا أو بردا\nيا كبدي تجلدا … فما اطيق الجلدا\nعسى فؤاد يرعوي … رب مضل وجدا\nوحمل الحاج الرما … ح لا الأمون الجلعدا\nاني اذا ما لم اجد … إلا الهوان موردا\nكنت اداوي كبدي … لو غادروا لي كبدا\nدع للمشيب ذمة … إن له عندي يدا\nاعتق من رق الهوى … مذللا معبدا\nلكن هوى لي أن أرى … لون عذاري اسودا\n … شائبا وامردا\nما اخلق البرد فلم … بدل لي وجددا\nلولا تكاليفك لم … أعط الزمان مقودا\nولا ثنيت عنقي … إلى الليالي صيدا\nسجية من بطل … لازم ما تعودا\nبايع اطراف القنا … وعاقد المهندا\nشاورت قلبا آبيا … فقال لي لاتردا\nإني لقوم بعدوا … في المجد والجود مدى\nشوس اذا الباغي بغى … سمح ، إذا الجادي جدا\nتفرعوا طود العلى … والجبل العطودا\nمجدهم أقدم من … هضب القنان مولدا\nاصادق في الخطب … للسيف وللمال عدا\nإذا اهتدى بنارهم … طارق ليل ما اهتدى\nتقارعوا على القرى … واقترعوا على الجدا\nوغارة في سدفة … توقظ حيا رقدا\nبضمر أسقطها … عليهم مع الندا\nتلهب نضا زعزعا … او قربا عمردا\nكانني ابعثها … فيهم ثنى وموحدا\n … يوم الحصاب جلمدا\nمن كل محبوك كما … أمر لاو مسدا\nيغني الفتى عنانه … عن سوطه اذا عدا\nكأنما فارسه … يقدع ذئبا أصردا\nأنزع عن صفحته … شوك القنا مقصدا\nلو شمته ببارق … ماء الكلاب اوردا\nوكل صل لامظ … يطلب ريا للصدى\nأقدم من سنانه … اذا الجبان عردا\nماض ، فإن شم طرو … ق الضيم زاغ حيدا\nيلقى الطراد جذلا … كما يلاقي الطردا\nانا الغلام تالقرشي … منجبا ما ولدا\nأنزعت دلوي قبلكم … إلى العراق سؤددا\nما زال عزمي لي عن … دار الهوان مبعدا\nمرحلي عن بلد … وراجما بي بلدا\nإن لم يكن نيل منى … فابغ اذا ورد ردا"},{"id":"diwan-radi:171","bookId":"diwan-radi","type":"poem","seq":171,"chapter":"البحر: طويل","title":"ابر على الانواء فضلي ونائلي","page":"","text":"ابر على الانواء فضلي ونائلي … وطال على الجوزاء قدري ومحتدي\nيدي ألفت بذل النوال فلو نبت … عن الجود يوما قلت ما هذه يدي"},{"id":"diwan-radi:172","bookId":"diwan-radi","type":"poem","seq":172,"chapter":"البحر: مجزوء الكامل","title":"قل للعدى موتوا بغيظكم","page":"","text":"قل للعدى موتوا بغيظكم … الغيظ مردي\nودعوا على أحرزتها … يا وادعين بطول جهد\nكم بين ايديكم وبي … ن النجم من قرب وبعد\nولي النقابة خال امي … قبل ثم ابي وجدي\nوليتها طفلا ، فهل … مجد يعدد مثل مجدي\nوأظن نفسي سوف تح … ني على الامر الاشد\nحتى ارى متملكا … شرق العلى والغرب وحدي"},{"id":"diwan-radi:173","bookId":"diwan-radi","type":"poem","seq":173,"chapter":"البحر: طويل","title":"يفاخرنا قوم بمن لم يلدهم","page":"","text":"يفاخرنا قوم بمن لم يلدهم … بتيم اذا عد السوابق اوعدي\nوينسون من لو قدموه لقدموا … عذار جواد في الجياد مقلد\nفتى هاشم بعد النبي وباعها … لمرمى على أو نيل مجد وسؤدد\nولولا علي ما علوا سرواتها … ولا جعجعوا منها بمرعى ومورد\nأخذنا عليهم بالنبي وفاطم … طلاع المساعي من مقام ومقعد\nوطلنا بسبطي احمد ووصيه … رقاب الورى من متهمين ومنجد\nوحزنا عتيقا وهو غاية فخركم … بمولد بنت القاسم بن محمد\nفجد نبي ثم جد خليفة … فما بعد جدينا علي وأحمد\nوما افتخرت بعد النبي بغيره … يد صفقت يوم البياع على يد"},{"id":"diwan-radi:174","bookId":"diwan-radi","type":"poem","seq":174,"chapter":"البحر: طويل","title":"نزلنا بمستن المكارم والعلى","page":"","text":"نزلنا بمستن المكارم والعلى … فلم نبق فضلا للرجال ولا مجدا\nوليس نرى للفضل والمجد دوننا … على حالة قصدا ولا خلفنا مغدى\nنماني قروم من ذوائب غالب … يمدون بي في كل طود على مدا\nلئن جحدوا اني ابن خير الورى ابا … فلن يجحدوا أني ابن خير الورى جدا"},{"id":"diwan-radi:175","bookId":"diwan-radi","type":"poem","seq":175,"chapter":"البحر: كامل تام","title":"هذي المنازل بالغميم فنادها","page":"","text":"هذي المنازل بالغميم فنادها … واسكب سخي العين بعد جمادها\nإن كان دين للمعالم ، فاقضه … أو مهجة عند الطلول ففادها\nيا هل تبل من الغليل اليهم … اشرافة للركب فوق نجادها\nنؤي كمنعطف الحنية دونه … سحم الخدود لهن ارث رمادها\nومناط اطناب ومقعد فتية … تخبو زناد الحي غير زنادها\nومجر أرسان الجياد لغلمة … سجفوا البيوت بشقرها وورادها\nولقد حبست على الديار عصابة … مضمومة الايدي الى اكبادها\nحسرى تجاوب بالبكاء عيونها … وتعط بالزفرات في أبرادها\nوقفوا بها حتى كان مطيهم … كانت قوائمهن من اوتادها\nثم انثنت والدمع ماء مزادها … ولواعج الأشجان من أزوادها\nمن كل مشتمل حمايل رنة … قطر المدامع من حلي نجادها\nحيتك بل حيت طلولك ديمة … يشفي سقيم الربع نفث عهادها\nوغدت عليك من الخمايل يمنة … تستام نافقة على روادها\nهل تطلبون من النواظر بعدكم … شيئا سوى عبراتها وسهادها\nلم يبق ذخر للمدامع عنكم … كلا ولا عين جرى لرقادها\nشغل الدموع عن الديار بكاؤنا … لبكاء فاطمة على أولادها\nلم يخلفوها في الشهيد وقد رأى … دفع الفرات يذاد عن أورادها\nاترى درت ان الحسين طريدة … لقنا بني الطرداء عند ولادها\nكانت مآتم بالعراق تعدها … أموية بالشام من أعيادها\nما راقبت غضب النبي وقد غدا … زرع النبي مظنة لحصادها\nباعت بصائر دينها بضلالها … وشرت معاطب غيها برشادها\nجعلت رسول الله من خصمائها … فلبئس ما ذخرت ليوم معادها\nنسل النبي على صعاب مطيها … ودم النبي على رؤوس صعادها\nوالهفتاه لعصبة علوية … تبعت امية بعد عز قيادها\nجعلت عران الذل في آنافها … وعلاط وسم الضيم في اجيادها\nزعمت بان الدين سوغ قتلها … أوليس هذا الدين عن أجدادها\nطلبت تراث الجاهلية عندها … وشفت قديم الغل من أحقادها\nواستأثرت بالامر عن غيابها … وقضت بما شاءت علي شهادها\nالله سابقكم إلى أرواحها … وكسبتم الآثام في أجسادها\nإن قوضت تلك القباب ، فإنما … خرت عماد الدين قبل عمادها\nان الخلافة اصبحت مزوية … عن شعبها ببياضها وسوادها\nطمست منابرها علوج أمية … تنزو ذئابهم على اعوادها\nهي صفوة الله التي اوحى لها … وقضى اوامره الى امجادها\nأخذت بأطراف الفخار ، فعاذر … ان يصبح الثقلان من حسادها\nالزهد والأحلام في فتاكها … والفتك لولا الله في زهادها\nعصب يقمط بالنجاد وليدها … ومهود صبيتها ظهور جيادها\nتروي مناقب فضلها أعداؤها … أبدا ، وتسنده إلى أضدادها\nيا غيرة الله اغضبي لنبيه … وتزحزحي بالبيض عن اغمادها\nمن عصبة ضاعت دماء محمد … وبنيه بين يزيدها وزيادها\nصفدات مال الله ملء أكفها … وأكف آل الله في أصفادها\nصربوا بسيف محمد أبناءه … ضرب الغرائب عدن بعد ذيادها\nقد قلت للركب الطلاح كانهم … ربد النسور على ذرى اطوادها\nيحدو بعوج كالحني اطاعه … معتاصها ، فطغى على منقادها\nحتى تخيل من هباب رقابها … أعناقها في السير من أعدادها\nقف بي ولو لوث الزرار فانما … هي مهجة علق الجوى بفؤادها\nبالطف حيث غدا مراق دمائها … ومناخ اينقها ليوم جلادها\nالقفر من أرواقها ، والطير من … طراقها ، والوحش من عوادها\nتجري لها حبب الدموع ، وإنما … حب القلوب يكن من أمدادها\nيا يوم عاشوراء كم لك لوعة … تترقص الاحشاء من ايقادها\nما عدت الا عاد قلبي غلة … حرى ، ولو بالغت في إبرادها\nمثل السليم مضيضة آناؤه … خزر العيون تعوده بعدادها\nيا جد لا زالت كتائب حسرة … إن لم يراوحها البكاء يغادها\nهذا الثناء ، وما بلغت ، وإنما … هي حلبة خلعوا عذار جوادها\nأأقول : جادكم الربيع ، وأنتم … في كل منزلة ربيع بلادها\nام استزيد لكم علا بمدائحي … اين الجبال من الربى ووهادها\nكيف الثناء على النجوم ، إذا سمت … فوق العيون الى مدى ابعادها\nأغنى طلوع الشمس عن أوصافها … بجلالها وضيائها وبعادها"},{"id":"diwan-radi:176","bookId":"diwan-radi","type":"poem","seq":176,"chapter":"البحر: طويل","title":"وراءك عن شاك قليل العوائد","page":"","text":"وراءك عن شاك قليل العوائد … تقلبه بالرمل ايدي الاباعد\nيراعي نجوم الليل والهم كلما … مضى صادر عني باخر وارد\nتوزع بين النجم والدمع طرفه … بمطروفة انسانها غير راقد\nوما يطبيها الغمض الا لانه … طريق الى طيف الخيال المعاود\nذكرتكم ذكر الصبا بعد عهده … قضى وطرا مني وليس بعائد\nإذا جانبوني جانبا من وصالهم … علقت باطراف المنى والمواعد\nفيا نظرة لا تنظر العين اختها … إلى الدار من رمل اللوى المتقاود\nهي الدار لا شوقي القديم بناقص … إليها ، ولا دمعي عليها بجامد\nولي كبد مقروحة لو اضاعها … من السقم غيري ما بغاها بناشد\nاما فارق الاحباب قبلي مفارق … ولا شيع الاظعان مثلي بواجد\nتأوبني داء من الهم لم يزل … بقلبي حتى عادني منه عائدي\nتذكرت يوم السبط من آل هاشم … وما يومنا من آل حرب بواحد\nوظام يريغ الماء قد حيل دونه … سقوه ذبابات الرقاق البوارد\nأتاحوا له مر الموارد بالقنا … على ما أباحوا من عذاب الموارد\nبنى لهم الماضون آساس هذه … فعلوا على آساس تلك القواعد\nرمونا كما يرمى الظماء عن الروا … يذودوننا عن ارث جد ووالد\nويا رب ساع في الليالي لقاعد … على ما رأى ، بل كل ساع لقاعد\nأضاعوا نفوسا بالرماح ضياعها … يعز على الباغين منا النواشد\nأألله ! ما تنفك في صفحاتها … خموش لكلب من امية عاقد\nلئن رقد النصار عما أصابنا … فما الله عما نيل منا براقد\nلقد علقوها بالنبي خصومة … إلى الله تغني عن يمين وشاهد\nويا رب أدنى من أمية لحمة … رمونا على الشنآن رمي الجلامد\nطبعنا لهم سيفا فكنا لحده … ضرائب عن ايمانهم والسواعد\nالا ليس فعل الاولين وان علا … على قبح فعل الاخرين بزائد\nيريدون أن نرضى وقد منعوا الرضى … لسير بني اعمامنا غير قاصد\nكذبتك ، إن نازعتني الحق ظالما … إذا قلت يوما إنني غير واجد"},{"id":"diwan-radi:177","bookId":"diwan-radi","type":"poem","seq":177,"chapter":"البحر: وافر تام","title":"تفوز بنا المنون وتستبد","page":"","text":"تفوز بنا المنون وتستبد … وياخذنا الزمان ولا يرد\nوانظر ماضيا في عقب ماض … لقد أيقنت أن الأمر جد\nرويدا بالفرار من المنايا … فليس يفوتها الساري المجد\nفاين ملوكنا الماضون قدما … اعدوا للنوائب واستعدوا\nواين معاقدوا الدنيا قديما … نبت بهم ، فلا إل وعقد\nوكل فتى تحف بجانبيه … خواطر بالقنا قب وجرد\nفما دفع المنايا عنه وفر … ولا هزم النوائب عنه جند\nولا اسل لها قرع ووخز … ولا قضب لها قط وقد\nاعارهم الزمان نعيم عيش … فيا سرعان ما نزعوا وردوا\nهم فرط لنا في كل يوم … نمدهم ، وإن لم يستمدوا\nفلا الغادي يروح فنرتجيه … ولا المتروح العجلان يغدو\nوللإنسان من هذي الليالي … وهوب لا يدوم ومسترد\nتجد لنا ملابسها ، فيبقى … جديداها ، ويبلى المستجد\nأإبراهيم ! أما دمع عيني … عليك فما يعد ولا يحد\nيغصص بالاوائل منه طرف … ويدمى بالأواخر منه خد\nبكيتك للوداد ، ورب باك … عليك من الأقارب لا يود\nوإن بكاء من تبكيه قربى … لدون بكاء من يبكيه ودج\nإذا غضنا الدموع أبت علينا … مناقب منك ليس لهن ند\nفمنهن اشتطاطك في المساعي … وفضل العزم ، والباع الأشد\nفاين مسابق الاجال طعنا … يعود ورمحه ريان ورد\nواين الآسر الفكاك يسري … إليه من العدى ذم وحمد\nفاعناق احاط بهن من … وأعناق أحاط بهن قد\nأيا سهما رمى غرضا ، فأخطا … وذي الاقدار اسهمها اسد\nولو غير الردى جاثاك اقعى … به من بأسك الخصم الألد\nقتيل فله ناب كهام … وكان العضب ضوأه الفرند\nوذل بذل قاتله ، فأضحى … لقاتله به عز ومجد\nفيا اسدا يصول عليه ذئب … ويا مولى يطول عليه عبد\nوكيف رجوت ان يبقى سليما … وما شرب القرون له معد\nوهل بقيت قبائله ، فيبقى … ربيعة أو نزار أو معد\nمن القوم الألى طلبوا ونالوا … وجد بهم إلى العلياء جد\nإذا ندبوا إلى البأساء عاجوا … وان ادنو الى العوراء صدوا\nتصدع مجد أولهم ، فشدوا … جوانبه بأنفسهم وسدوا\nإذا عد الأماجد جاء منهم … عديد كالرمال ، فلم يعدوا\nسقاه أحم نجدي التوالي … يعم بودقه غور ونجد\nإذا مخضت حوافله جنوب … مرى لقحاته برق ورعد\nتدافع منه ملأن الحوايا … سياق النيب أصدرهن ورد\nولا عرى ثراه من الغوادي … ومن نوارها سبط وجعد\nاذا ماالراكب مر عليه قالوا … أيا حالي الصعيد سقاك عهد\nلقد كرمت يمينك قبل حيا … وقد كرم الغمام عليك بعد"},{"id":"diwan-radi:178","bookId":"diwan-radi","type":"poem","seq":178,"chapter":"البحر: طويل","title":"اعامر لا لليوم انت ولا الغد","page":"","text":"اعامر لا لليوم انت ولا الغد … تقلدت ذل الدهر بعد المقلد\nواصبحت كالمخطوم من بعد عزة … متى قيد مشاء على الضيم ينقد\nفان سار للاعداء غيرك فاربعي … وإن قام للعلياء غيرك فاقعد\nوقل للحمى لا حامي اليوم بعده … ولا قائم من دون مجد وسؤدد\nوللبيض لا كف لماض مهند … وللسمر لا باع لعال مسدد\nوقل للعدى امنا على كل جانب … من الارض أو نوما على كل مرقد\nفقد زال من كانت طلائع خوفه … تعارضكم في كل مرعى ومورد\nفاين الجياد الملجمات على الوحى … سراعا الى نقع الصريخ المندد\nواين الظبى ما زال منها بكفه … رداء عظيم أو عمامة سيد\nواين المطايا تذرع البيد والدجى … الى اقرب من نيل عز وابعد\nواين الجفان الغر من قمع الذرى … هجان الاعالي بالسديف المسرهد\nواين القدور الراسيات كانها … سماوات ربلان النعام المطرد\nواين الوفود الماتحون ببابه … بسجلين من بحري وعيد وموعد\nمرمون من قبل اللقاء مهابة … اذا رمقوا باب الطراف الممدد\nيشيرون بالتسليم من خلل القنا … الى واضح من عامر غير قعدد\nيحيون مرهوبا كأن رواقه … وليجة مفتول الذراعين ملبد\nاذا هم امضى الراي غير ملوم … وإن قال أجرى القول غير مفند\nحسام نكا فيه كهام بغرة … واولى له لو هزه غير مغمد\nلئن فلل الذلان منه فربما … تحيف من ماضي الظبى شق مبرد\nفلا نعم الباغون يوما بعيشة … ولا حضروا إلا بألأم مشهد\nولاصادفوا في الدهر منجى لخائف … ولاوجدوا في الارض ماوى لمطرد\nولا شربوا إلا دما بعده ، ولا … تحابوا بغير الزاعبي المقصد\nولا نظروا الا بعمياء بعده … ولا ارتضعوا إلا بخلف مجدد\nابعد الطوال الشم من آل عامر … الى البيض والادراع والخيل والند\nوأهل القباب الحمر يرخى سدولها … على سؤدد عود ومجد موطد\nإذا فزعوا للأمر ألجوا ظهورهم … الى كل طود من نزار عطود\nلهم جامل داجي المراح كأنما … تراغين عن قطع من الليل أسود\nتروح لهم حمر العوادي كانها … قواني عروق العندم المتورد\nكان الرياض الغر حول بيوتهم … ذئاب الغضا يمرحن في كل مرود\nإذا ما انتشوا هزوا رؤوسا كريمة … لها طرب بالجود قبل التغرد\nتراموا بها حمراء تحسب شربها … ذوي قرة حفوا جوانب موقد\nلهم سامر تحت الظلام وراكد … على النار يذكيها بضال وغرقد\nيقول الفتى منهم لراعي عشاره : … الا لا تقيدها بغير المهند\nمضى النجباء الاطولون كانهم … صدور القنا في الشرعبي المعضد\nرمت فيهم بعد التئام وألفة … يد الاربى صدع البلاط الممرد\nتشظوا تشظي العود تجري فروعه … على ثغرها خرقاء مجنونة اليد\nتكبهم الايام عم جمحاتها … كما كب اعجاز الهدي المقلد\nخلت بهم الاجداث عنا واطبقت … على المجد منهم كل بيداء قردد\nفمن يعدل الميلاء أو يرأب الثأي … وياخذ من ريب الزمان على يد\nتفانوا على كسب العلى ، وتجرعوا … بايديهم كاس الردى جرع الصدي\nكما رض في مر السيول عشية … ذرى جلمد صعب الذرى قرع جلمد\nالا في سبيل المجد ثاوون لم نكن … قبورهم غير الدلاص المسرد\nوكانوا أحاديث الرفاق ، فأصبحوا … أغاني للغوري والمتنجد\nلعا لكم من عاثرين تتابعوا … على زلل الأقدام عثر المقيد\nأفي كل يوم قطرة من دمائكم … تمسحها من ظفر شنعاء موئد\nملوك وإخوان كأني بعدهم … على قرب من خمس يوم عمرد\nعراعر ينزو القلب عند ادكارهم … نزاء الدبى بالامعز المتوقد\nسقاكم ولولا عادة عربية … لقل لكم قطر الحبي المنضد\nمن المزن رجراح العباب ، كأنه … من البطء ترجاف الكسير المقود\nتخال على هام الربى من ربابه … عناصي هامات الحجيج الملبد\nترادف يزجي كلكلا بعد كلكل … تطلع ركب من أبانين منجد\nخفى برقه ثم استطار كأنه … يشقق هداب الملاء المعمد\nلجأنا من الدنيا الى مستقرة … تنولنا عذب الجنا وكان قد\nعلقنا جماد النيل ناقصة الجدا … تروح علينا بالغرور وتغتدي\nأمن بعدهم أرجو الخلود وهذه … سبيلي ومن تلك الشرائع موردي\nفان انج من ذا اليوم قاطع ربقة … فقصري من ريب المنون على غد\nسواء مخلى للمنايا اكيلة … ومن راح منا في التميم المعقد\nفقل لليالي بعدهم : هاك مقودي … تقضى ايابي فاصدري بي أو وردي\nودونك من ظهري وقد غال أسرتي … طريق الردى ظهر الذلول المعبد\nبأي يد ارمى الزمان وساعد … وكانوا يدي أعطيتها الخطب عن يدي\nوما كان صبري عنهم من جلادة … أبى الوجد لي بل عادة من تجلدي"},{"id":"diwan-radi:179","bookId":"diwan-radi","type":"poem","seq":179,"chapter":"البحر: وافر تام","title":"الا من يمطر السنة الجمادا","page":"","text":"الا من يمطر السنة الجمادا … ومن للجمع يطلعه النجادا\nومن للخيل يقبلهن شعثا … ويركبهن شقرا ، أو ورادا\nغداة الروع ينعلها الهوادي … من الاعداء واللمم الجعادا\nمجلجة كأن بها اواما … إلى وقع الصوارم أو جوادا\nيسامحها القياد إلى المعالي … وعند الضيم يمطلها القيادا\nومن للحرب ينضح ذفرييها … ويعركها جلادا أو طرادا\nيبدل من دم الاعداء فيها … لصارمه الحمائل والعمادا\nهوى قمر اللانام وكان اوفى … على قمر التمام على وزادا\nفقل للقلب : لبك والتعزي … وثقل للعين جفنك والرقادا\nمصائب لا أنادي الصبر فيها … ولا أدعى اليه ولا انادي\nاللعينين قد قذيا بكاء … ام الجنبين قد قلقا وسادا\nكأن الوسم شعشع فيه قين … بجذوته علطت به الفوادا\nمن القوم الأولى ملأوا الليالي … إلى أصبارها كرما وآدا\nورسوا في فواغر كل خطب … صدور البيض والزرق الحدادا\nاذا صاب الحيا ببلاد ضيم … جلوا عنهن ، وانتجعوا بلادا\nهم الجبل المطل على الأعادي … إذا رجم الزمان به ، ورادا\nلهم حسب اذا نقبت عنه … تضرم جمرة وورى زنادا\nلهم أنف يذب الضيم عنهم … ورأي يفرج الكرب الشدادا\nوايمان اذا مطرت عطاء … حسبت الناس كلهم جوادا\nترى رأي الفتى فيهم مطاعا … وقول المرء منهم مستعادا\nوقد بلغوا من العلياء اقصى … ذوائبها وما بلغوا المرادا\nاشت جميعهم صرف الليالي … \nمصابك لم يدع قلبا ضنينا … بلغته ولا عينا جمادا\nكأن الناس بعدك في ظلام … أو الأيام ألبست الحدادا\nوكنت أفدت خلته ، ولكن … افادني الزمان وما افادا\nفإن لم أبكه قربى تلاقت … مغارسها بكيت له ودادا\nيعز علي ان اطويه صفحا … وأذهب عنه نأيا أو بعادا\nتعز ابا علي ان خطبا … على العلاة يبلغ ما ارادا\nهو القدر الذي خبطت يداه … \nوضعضع كل من حمل العوالي … وارجل كل من ركب الجيادا\nيعرى ظهر اكثرنا عديدا … ويهجم بيت اطولنا عمادا\nكذاك الدهر إن أبقى قليلا … أحال على بقيته ، وعادا\nوبينا المرء يجنيه ثمارا … إلى ان عاد يخرطه قتادا\nواقرب ما ترى فيه انتقاصا … إذا ما قيل قد كمل ازديادا\nونعلم ان سيوجرنا مرارا … باية ان يلمظنا شهادا\nوما تجدي الدموع على فقيد … ولو غسلت من العين السوادا\nوكنت مقلدا منها حساما … على الأعداء داهية نآدى\nفنافسك الردى في مضربيه … فبز النصل ، واختلع النجادا\nفناد اليوم غير ابي شجاع … وصم ابا شجاع ان ينادى\nحدى غير الغمام اليه كوما … تعز على المقاد أن تقادا\nنزائع من رياح الغور شبت … على القلل البوارق والرعادا\nمخضن بهن مخض الوطب حتى … اذا جلجلن اطلقن المزادا\nتلامحت البروق بجانبيها … كأن لها انحلالا وانعقادا\nكأن بهن راعي مرزمات … ابس فحرك الخور الجلادا\nفيا للناس اوقره ترابا … واستسقي لاعظمه العهادا\nوما السقيا لتبلغه ، ولكن … وجدت لها على قلبي برادا"},{"id":"diwan-radi:180","bookId":"diwan-radi","type":"poem","seq":180,"chapter":"البحر: طويل","title":"سلا ظاهر الأنفاس عن باطن الوجد","page":"","text":"سلا ظاهر الأنفاس عن باطن الوجد … فان الذي اخفي نظير الذي ابدي\nزفيرا ، تهاداه الجوانح كلما … تمطي بقلبي ضاق عن مره جلدي\nوكيف يرد الدمع ، يا عين ، بعدما … تعسف اجفاني وجار على خدي\nوإني إن أنضح جواي بعبرة … يكن كخبي النار يقدح بالزند\nفهذي جفوني من دموعي في حيا … وهذا جناني من غليلي في وقد\nحلفت بما وارى الستار ، وما هوت … إليه رقاب العيس ترقل أو تخدي\nلقد ذهب العيش الرقيق بذاهب … هو الغارب المجزول من ذروة المجد\nوإني ، إذا قالوا مضى لسبيله … وهيل عليه الترب من جانب اللحد\nكساقطة إحدى يديه إزاءه … وقد جبها صرف الزمان من الزند\nوقد رمت الأيام من حيث لا أرى … صميمي بالداء العنيف على عمد\nفلا تعجبا أني نحلت من الجوى … فايسر ما لاقيت ما حز في الجلد\nولو أن رزءا غاض ماء لكانه … وجفت له خضر الغصون من الرند\nسقى قبره مستمطر ذو غفارة … يجر عليه عرف ملآن مربد\nإذا قلت : قد خفت متاليه أرزمت … وأجلب بالبرق المشقق والرعد\nحسام جلا عنه الزمان ، فصممت … مضاربه حينا ، وعاد إلى الغمد\nسنان تحدته الدروع بزغفها … فبدد اعيان المضاعف والسرد\nجواد جرى حتى استبد بغاية … تقطع أنفاس الجياد من الجهد\nسحاب علا حتى تصوب مزنه … وأقلع لما عم بالعيشة الرغد\nربيع تجلى ، وانجلى ، ووراءه … ثناء كما يثني على زمن الورد\nنعض على الموت الأنامل حسرة … وان كان لا يغني غناء ولا يجدي\nوهل ينفع المكلوم عض بنانه … ولو مات من غيظ على الاسد الورد\nعوار من الدنيا يهون فقدها … تيقننا ان العواري للرد\nينال الردى من يعرض الهضب دونه … ولو كان في غور من الأرض أو نجد\nويسلم من تسقى الاسنة حوله … بيدي الكماة المعلمين على الجرد\nفما ذاك ان لم يلق حتفا بخالد … ولا ذا من الحتف المطل على بعد\nلئن ثلمت مني الليالي عشائري … فما ثلموا الا من الحسب العد\nشجوني ولم يبقوا لعيني بلة … من الدمع الا استفرغوها من الوجد\nعزاءك ، فالأيام أسد مذلة … تعط الفتى عط المقاريض للبرد\nإذا أوردته نهلة من نعيمها … اعادته حران الضلوع من الورد\nأغل إلى القلب المنيع من القنا … واجري الى الآجال من قضب الهند\nأراد بك الحساد أمرا ، فرده … عليهم سفاه الراي والراي قد يردي\nفلا يغمدن السطو والحلم ضائر … وقد نزع الاعداء آصرة الود\nهم قعقعوا بغيا عليك واجلبوا … فآبوا وما قاموا بحل ولا عقد\nوقد ركبوه مرة بعد مرة … فيا لذلول البغي من مركب مردي\nفحتى متى تغضى مرارا على القذى … وتلحظك الاضغان من مقل رمد\nفإن لا تصل تصبح عداك كثيرة … عليك ، وداء الطعن إن هبته يعدي\nوهل كان ذاك البعد إلا تنزها … على المضمر البغضاء والحاسد الوغد\nوجئت مجيء البدر أخلق ضوءه … فعاد جديد النور بالطالع السعد\nوكم من عدو قد سرى فيك كيده … سرى السم من رقطاء ذات قرا جعد\nفأغفلته ثم انتضيت عزيمة … نزعت بها من قلبه حمة الحقد\nوذي خطل أوجرته منك غصة … فأطرق منها لا يعيد ولا يبدي"},{"id":"diwan-radi:181","bookId":"diwan-radi","type":"poem","seq":181,"chapter":"البحر: طويل","title":"أتاني ، ورحلي بالعذيب ، عشية","page":"","text":"أتاني ، ورحلي بالعذيب ، عشية … وايدي المطايا قد قطعن بنا نجدا\nنعي أطار القلب عن مستقره … وكنت على قصد فاغلطني القصدا\nفليت نعى الركب العراقي غيره … فما كل مفقود وجعت له فقدا\nويا ناعييه اليوم غضا على قذى … فقد زدتما قلبي على وجده وجدا\nفبئس ، على بعد اللقاء ، تحية … احيي بها تذكى على كبدي وقدا\nبرغمي ان اوردت قبلي بمورد … تبرضت منه لا زلالا ولا بردا\nجزتك الجوازي عن عماد اقمتها … وعن عقد للدين أحكمتها شدا\nوذي جدل ألجمت فاه بغصة … تلجلج فيه لا مساغا ولا ردا\nقعست له حتى التقيت سهامه … وأثبت في تاموره الحجج اللدا\nومزلقة للقول ما شئت دحضها … وقد زل عنها من اعاد ومن ابدى\nوإني لأستسقي لك الله عفوه … ويالك غيثا ما اعم وما اندى\nواخلق بمن كان النبي ورهطه … محامين عنه ان يفوز ولا يردى\nبكيتك حتى استنفد الدمع ناظري … ولو مدني دمعي عليك لما اجدى"},{"id":"diwan-radi:182","bookId":"diwan-radi","type":"poem","seq":182,"chapter":"البحر: كامل تام","title":"أعلمت من حملوا على الأعواد","page":"","text":"أعلمت من حملوا على الأعواد … أرأيت كيف خبا ضياء النادي\nجبل هوى لو خر في … من وقعه متتابع الإزباد\nما كنت اعلم قبل حظك في الثرى … ان الثرى بعلو على الاطواد\nبعدا ليومك في الزمان فانه … أقذى العيون وفت في الأعضاد\nلا ينفد الدمع الذي يبكى به … إن القلوب له من الأمداد\nكيف انمحى ذاك الجناب وعطلت … تلك الفجاج وضل ذاك الهادي\nطاحت بتلك المكرمات طوائح … وعدت على ذاك الجواد عوادي\nقالوا : أطاع وقيد في شطن الردى … ايدي المنون ملكت اي قياد\nمن مصعب لو لم يقده الاهه … بقضائه ما كان بالمنقاد\nهذا أبو إسحق يغلق رهنه … هل ذا يد أو مانع أو فاد\nلو كنت تفدى لافتدتك فوارس … مطروا بعارض كل يوم طراد\nواذا تألق بارق لوقيعة … والخيل تفحص بالرجال بداد\nسلوا الدروع من العباب ، وأقبلوا … من جانبيك مقاود العواد\nلكن رماك مجبن الشجعان عن … إقدامهم ، ومضعضع الأنجاد\nكالليث يوهن بالتراب ، ويمتلي … نوما على الأضغان والأحقاد\nوالدهر تدخل نافذات سهامه … مأوى الصلال ومربض الاساد\nألقى الجران على عنطنط حمير … فمضى ، ومد يدا لأحمر عاد\nاعزز علي بان يفارق ناظري … لمعان ذاك الكوكب الوقاد\nاعزز علي بان نزلت بمنزل … متشابه الأمجاد والأوغاد\nفي عصبة جنبوا إلى آجالهم … والدهر يعجلهم عن الإرواد\nضربوا بمدرجة الفناء قبابهم … من غير أطناب ، ولا أوتاد\nركب اناخوا لا يرجى منهم … قصد لاتهام ولا انجاد\nكرهوا النزول فانزلتهم وقعة … للدهر باركة بكل مقاد\nفتهافتوا عن رحل كل مذلل … وتطاوحوا عن سرج كل جواد\nبادون في صور الجميع ، وإنهم … متفردون تفرد الآحاد\nمما يطيل الهم أن أمامنا … طول الطريق وقلة الازواد\nعمري ! لقد أغمدت منك مهندا … في الترب كان ممزق الاغماد\nقد كنت اهوى ان اشاطرك الردى … ولكن اراد الله غير مراد\nولقد كبا طرف الرقاد بناظري … اسفا عليك فلا لعا لرقاد\nثكلتك ارض لم تلد لك ثانيا … أنى ، ومثلك معوذ الميلاد\nمن للبلاغة والفصاحة إن همى … ذاك الغمام وعب ذاك الوادي\nمن للملوك يجز في اعدائها … بظبى من القول البليغ حداد\nمن للممالك لا يزال يلمها … بسداد امر ضائع وسداد\nمن للجحافل يستزل رماحها … ويرد رعلتها بغير جلاد\nمن للموارق يسترد قلوبها … بزلازل الإبراق والإرعاد\nوصحايف فيها الأراقم كمن … مرهوبة الاصدار والايراد\nتدمى طوائعها اذا استعرضتها … من شدة التحذير والإيعاد\nحمر على نظر العدو كأنما … بدم يخط بهن لا بمداد\nيقدمن إقدام الجيوش ، وباطل … أن ينهزمن هزائم الأجناد\nفقر بها تمسى الملوك فقيرة … أبدا إلى مبدى لها ومعاد\nوتكون صوتا للحرون اذا ونى … وعنان عنق الجامح المتمادي\nترقي ، وتلذع في القلوب ، وإن يشا … حط النجوم بها من الأبعاد\nان الدموع عليك غير بخيلة … والقلب بالسلوان غير جواد\nسودت ما بين الفضاء وناظري … وغسلت من عيني كل سواد\nري الخدود من المدامع شاهد … أن القلوب من الغليل صواد\nما كنت اخشى ان نضن بلفظة … لتقوم بعدك لي مقام الزاد\nماذا الذي منع الفنيق هديره … من بعد صولته على الاذواد\nماذا الذي حبس الجواد عن المدى … من بعد سبقته الى الآماد\nماذا الذي فجع الهمام بوثبة … وعدا على دمه ، وكان العادي\nقل للنوائب عددي ايامه … يغنى عن التعديد بالتعداد\nحمال ألوية العلاء بنجدة … كالسيف يغني عن مناط نجاد\nقلصت اظلة كل فضل بعده … وأمر مشربها على الوراد\nلقضى لسانك مذ ذوت ثمراته … أن لا دوام لنضرة الأعواد\nوقضى جنابك مذ قضت وقداته … أن لا بقاء لقدح كل زناد\nبقيت اعيجاز يضل تبيعها … ومضت هواد للرجال هواد\nيا ليت أني ما اقتنيتك صاحبا … كم قنينة جلبت اسى لفؤادي\nإن لم تسف إلى التناسل نفسه … كفي الأسى بتفاقد الأوداد\nبرد القلوب لمن تحب بقاءه … مما يجر حرارة الاكباد\nليس الفجائع بالذخائر مثلها … باماجد الاعيان والافراد\nويقول من لم يدركنهك انهم … نقصوا به عددا من الاعداد\nهيهات ! أدرج بين برديك الردى … رجل الرجال وأوحد الآحاد\nلا تطلبي يا نفس خلا بعد … فلمثله اعيي على المرتاد\nفقدت ملائمة الشكول بفقده … وبقيت بين تباين الأضداد\nما مطعم الدنيا بحلو بعده … أبدا ، ولا ماء الحيا ببراد\nالفضل ناسب بيننا ان لم يكن … شرفي مناسبه ولا ميلادي\nإن لم تكن من أسرتي وعشيرتي … فلا انت اعلقهم يدا بوداد\nلو لم يكن عالي الاصول فقد وفى … شرف الجدود بسؤدد الاجداد\nلا در دري ان مطلتك ذمة … في باطن متغيب ، أو باد\nإن الوفاء ، كما اقترحت ، فلو يكن … حيا اذا ما كنت بالمزداد\nليس التنافث بيننا بمعاود … أبدا ، وليس زماننا بمعاد\nضاقت علي الارض بعدك كلها … وتركت اضيقها علي بلادي\nلك في الحشى قبر وان لم تأوه … ومن الدموع روائح وغوادي\nسلوا من الابراد جسمك وانثنى … جسمي يسل عليك في الأبراد\nكم من طويل العمر بعد وفاته … بالذكر يصحب حاضرا ، أو بادي\nما مات من جعل الزمان لسانه … يتلو مناقب عودا وبوادي\nفاذهب كما ذهب الربيع واثره … باق بكل خمايل ونجاد\nلا تبعدن وأين قربك بعدها … إن المنايا غاية الأبعاد\nصفح الثرى عن حر وجهك انه … مغرى بطي محاسن الامجاد\nوتماسكت تلك البنان فطالما … عبث البلى بانامل الاجواد\nوسقاك فضلك إنه أروى حيا … من رائح متعرس ، أو غاد\nحدث على أن لا نبات بأرضه … وقفت عليه مطالب الرواد"},{"id":"diwan-radi:183","bookId":"diwan-radi","type":"poem","seq":183,"chapter":"البحر: مديد تام","title":"ترك الدنيا لطالبها","page":"","text":"ترك الدنيا لطالبها … ورضى بالدون مقتصدا\nنافرا منها فليس يرى … بالاماني آنسا ابدا\nبعد ان نال العلا وما … زال ينمي جده صعدا\nنفض الأطماع عن يده … واستخار الواحد الأحدا\nورأى أن لا نجاة له … فمضى يبغي النجاة غدا"},{"id":"diwan-radi:184","bookId":"diwan-radi","type":"poem","seq":184,"chapter":"البحر: مجزوء الكامل","title":"يا غائبا نقض الودادا","page":"","text":"يا غائبا نقض الودادا … اشمت بالقرب البعادا\nوتركتني ، والشوق يأ … بى ان يروح لي فوادا\nتأبى سوابق عبرتي … ان تخدع المقل الرقادا\nلو أن طرفي سار نح … وك لاتخذت النوم زادا\nفارجع إلى رسم الصفا … ء ، فإنه إن عدت عادا\nودع العدى فوحرمة … العلياء لا بلغوا المرادا\nبسطوا لنا أيدي النوا … ل ، وما نرى منهم جوادا\nقلبي أسير في حبا … لك لا أؤمل أن يقادا\nاعجلت قلبي ان يمس الهجر … فاستلب الودادا\nيا بائعي بالنزر مخ … تارا ليبلغ ما أرادا\nان جدت بي فليند من … من كان بي يوما جوادا\nمن ضاع مثلي من يدي … ه ، فليت شعري ما استفادا\nلا يلبس الود الطريف … ف مجامل خلع التلادا"},{"id":"diwan-radi:185","bookId":"diwan-radi","type":"poem","seq":185,"chapter":"البحر: مديد تام","title":"مثال ودي لا يغيره","page":"","text":"مثال ودي لا يغيره … لك هجران ولا بعد\nوجفوني لا يزال بها … طيف حلم منك يطرد\nوضميري أنت تعلمه … لك لا يلوي به احد\nيا مقيد الشوق من كبدي ! … آه لا صبر ، ولا جلد\nجرحتني منك جارحة … كل اعضائي لها عدد"},{"id":"diwan-radi:186","bookId":"diwan-radi","type":"poem","seq":186,"chapter":"البحر: مديد تام","title":"اترى الاحباب مذ ظعنوا","page":"","text":"اترى الاحباب مذ ظعنوا … وجدوا للبين ما أجد\nلا يبت ذاك الحبيب كما … بات هذا القلب والكبد\nكان زورا بعد بينهم … وغرورا ذلك الجلد\nومتى تدن الديار بهم … يجدوا قلبي كما عهدوا"},{"id":"diwan-radi:187","bookId":"diwan-radi","type":"poem","seq":187,"chapter":"البحر: طويل","title":"خذي نفسي ياريح من جانب الحمى","page":"","text":"خذي نفسي ياريح من جانب الحمى … فلاقي بها ليلا نسيم ربى نجد\nفان بذاك الحي الفا عهدته … وبالرغم مني أن يطول به عهدي\nولولا تداوي القلب من ألم الجوى … بذكر تلاقينا قضيت من الوجد\nويا صاحبي اليوم عوجا لتسئلا … ركيبا من الغورين أنضاؤهم تخدي\nعن الحي بالجرعاء جرعاء مالك … هل ارتبعوا واخضر واديهم بعدي\nكأن بعيني بعدهم غائر القذى … إذا أنا لم أنظر إلى العلم الفرد\nشممت بنجد شيحة حاجرية … فأمطرتها دمعي ، وأفرشتها خدي\nذكرت بهاريا الحبيب على النوى … وهيهات ذا يا بعد بينهما عندي\nواني لمجلوب لي الشوق كلما … تنفس شاك ، أو تألم ذو وجد\nتعرض رسل الشوق والركب هاجد … فتوقظني من بين نوامهم وحدي\nفقلت لاصحابي الا تتزافروا … رويدكم ! إن الهوى داؤه يعدي\nوما شرب العشاق الا بقيتي … ولا وردوا في الحب الا على وردي"},{"id":"diwan-radi:188","bookId":"diwan-radi","type":"poem","seq":188,"chapter":"البحر: طويل","title":"أقول وقد جاز الرفاق بذي النقا","page":"","text":"أقول وقد جاز الرفاق بذي النقا … ودون المطايا مربخ وزرود\nاتطلب يا قلبي العراق من الحمى … ليهنك من مرمى عليك بعيد\nوإن حديث النفس بالشيء دونه … رمال النقا من عالج لشديد\nترى اليوم في بغداد اندية الهوى … لها مبدي من بعدنا ومعيد\nفمن واصف شوقا ومن مشتك حشا … رمته المرامي أعين وخدود\nتلفت حتى لم يبن من بلادكم … دخان ولا من نارهن وقود\nوان التفات القلب من بعد طرفه … طوال الليالي نحوكم ليزيد\nولما تدانى البين قال لي الهوى : … رويدا وقال القلب اين تريد\nاتطمع ان تسلوا على البعد والنوى … وانت على قرب المزار عميد\nولو قال لي الغادون ما انت مشته … غداة جزعنا الرمل قلت اعود\nأأصبر ، والوعساء بيني وبينكم … واعلام خبت انني لجليد"},{"id":"diwan-radi:189","bookId":"diwan-radi","type":"poem","seq":189,"chapter":"البحر: منسرح","title":"يا طيب نجد ، وحسن ساكنه","page":"","text":"يا طيب نجد ، وحسن ساكنه … لو انهم انجزوا الذي وعدوا\nقالوا ، وقد قربت ركائبنا … والقلب يظما بهم ولا يرد\nأتارك أرضنا ، فقلت لهم : … انجد قلبي واعرق الجسد"},{"id":"diwan-radi:190","bookId":"diwan-radi","type":"poem","seq":190,"chapter":"البحر: رجز تام","title":"صدت وما كان لها الصدود","page":"","text":"صدت وما كان لها الصدود … وازور عني طرفها والجيد\nيقول لما اخلق الجديد … اذا البجال ذلك الوليد\nيا ابن ذاك الخضل الاملود … ريان من ماء الصبا يميد\nتصحبه اللحظ العذارى الغيد … غدا الغزال اليوم ، وهو سيد\nقلت : نعم ! ذاك الذي أريد … مضى حبيب قلما يعود\nلشد ما اوجعني الفقيد … أيامنا بعد البياض سود"},{"id":"diwan-radi:191","bookId":"diwan-radi","type":"poem","seq":191,"chapter":"البحر: كامل تام","title":"أأميم ! إن أخاك غض جماحه","page":"","text":"أأميم ! إن أخاك غض جماحه … بيض طردن عن الذوائب سودا\nعقب الجديد إذا مررن على الفتى … مر الفوادح لم يدعن جديدا\nقد كان قبلك للحسان طريدة … فاليوم راح عن الحسان طريدا\nحولن عنه نواظرا مزورة … نظر القلى ولوين عنه خدودا\nنشد التصابي ، بعد ما ضاع الصبا … غرضا ، لعمرك يا أميم ، بعيدا"},{"id":"diwan-radi:192","bookId":"diwan-radi","type":"poem","seq":192,"chapter":"البحر: متقارب تام","title":"تحنل جيراننا عن منى","page":"","text":"تحنل جيراننا عن منى … وقالوا : النقا بيننا موعد\nوهل ناقع قول ذي غلة … وقد بعد الركب لا يبعدوا\nتنادوا بان التناءي غدا … لك السوء من طالع ، يا غد\nفلله ما جمع المازمان … وجمع لقلبي والمسجد\nيضاع فينشد قعب الغبوق … وقلبي يضاع ولا ينشد\nوغيداء من ماطلات الديون … لها بالحمى زمن أغيد\nتريع كما التفتت ظبية … بذي البان عن لها المورد\nنظرت وهيهات من ناظريك … ظباء تهامة يا منجد\nويا ربما ، والهوى ضلة … ترى العين ما لا تنال اليد"},{"id":"diwan-radi:193","bookId":"diwan-radi","type":"poem","seq":193,"chapter":"البحر: طويل","title":"سقى الله يوما ساعدتنا كؤوسه","page":"","text":"سقى الله يوما ساعدتنا كؤوسه … على خحين ماجاد الزمان بمسعد\nجلونا عليه الخمر حتى تكشفت … فواقعها عن لونها المتورد\nنفض لنا عنها حبابا كأنه … قذى يتمشى بين أجفان أرمد\nوندمان صدق تسلب الراح عقله … وتسلبها خداه حسن التورد\nفلا زالت الأيام تجري صروفها … علينا بمغبوط من العيش سرمد"},{"id":"diwan-radi:194","bookId":"diwan-radi","type":"poem","seq":194,"chapter":"البحر: متقارب تام","title":"حططت المكارم عن عاتقي","page":"","text":"حططت المكارم عن عاتقي … وجردني الذل عن محتدي\nوالا فلا امني النازلون … ولا جاءني الطارق المجتدي\nولا قلت اني عند الفخ … ر ، إلا لغير أبي أحمد\nمتى حلت عن ودك المصطفى … واخلف ما رمته مولدي\nسألقاك بالعهد عند المشيب … وها أنا في حلية الامرد\nوإني ، إذا لم أجد ناصرا … وجدتك انصر لي من يدي\nخذ الوقت واعلم بان اللبي … ب يأخذ من يومه للغد\nفما ينفع المرء بعد المنون … قول النوادب لا تبعد\nعلى انني تحفة للصديق … يروح بنجواي ، أو يغتدي\nواني ليأنس بي الزائر … أنيس النواظر بالأثمد\nتغمض لي أعين الحاسدين … كالشمس في ناظر الأرمد\nفلا دخل البعد ما بيننا … ولا فك منا يدا عن يد\nوطول ايامنا بالمقام … في ظل عيش رقيق ندي"},{"id":"diwan-radi:195","bookId":"diwan-radi","type":"poem","seq":195,"chapter":"البحر: كامل تام","title":"هب للديار بقية الجلد","page":"","text":"هب للديار بقية الجلد … ودع الدموع وباعث الكمد\nواذهب بنفسك أن يقال سلا … وصفا لداعي العذل والفند\nاتصد عن طلل رغيت به … ما شئت من هيف ومن غيد\nطوت الليالي من معارفه … ما كان من علم ومن نضد\nأمسى الهوى فيه بلا أثر … وجرى البلى فيه بلا امد\nولقد عهدت رباه جامعة … بين الظباء الغيد والاسد\nأيام من فتك الغرام به … يمشي بلا عقل ولا قود\nان الاولى بعثوا ببينهم … ما زودوا في القرب للبعد\nما ضرهم ، والبين يحفزهم … لو عللونا بانتظار غد\nوجدوا وما جادوا ، ومحتقب … للوم من اثري ولم يجد\nليت الذي علق الرجاء به … اذ لم يجد للصب لم يجد\nولقد رأيتهم ، وحيهم … متقعقع الأطناب والعمد\nفكانما اقنى براثنه … ينشبن بين القلب والكبد\nوغريرة خلف السجوف لها … نسب إلى أومانة العقد\nخرجت خروج الريم عاطلة … ولجيدها حلي من الجيد\nتجري الاراك على مفلجة … يجرين من شهد على برد\nعني اليك فلست من اربي … ما انت من غيبي ومن رشدي\nقضت الليالي منك مأربتي … ونفضت من علق الغرام يدي\nوحدا النهى والشيب راحلتي … على استقاماتي على الجدد\nفاليوم اتبع الزمام وهل … يغني اباي اليوم أو صيدي\nلا تقر يا ضيف الهموم قرى … الا قرى العيرانة الأجد\nوانهض ، فإن لم تحظ في بلد … بالرزق فاقطعه اللا بلد\nوابغ العلى أبدا ، فكم طلب … قد بات من نيل على صدد\nاما يقال سعى فاحرزها … أو أن يقال ، مضى ، ولم يعد\nقولا لهذا الدهر معتبة … اسرفت بي يا دهر فاقتصد\nكم لوعة تهدي الى كبدي … وغرائب ما درن في خلدي\nايصاح بي عن كل صافية … طردا إلى الأقذاء والثمد\nوأسام في أكلاء موبئة … محتشها دون السوام ردي\nهل نافعي ، والجد في صبب … مري مع الآمال في صعد\nأمسى علي مع الزمان أخ … قد كنت آمل يومه لغد\nمن كان احنى عند نائبة … من والدي وابر من ولدي\nلم يثمر الظن الجميل به … فقدي من الظن الجميل قدي\nلو كان ما بيني وبينكم … بيني وبين الذئب والاسد\nلأويت من هذا إلى حرم … ولجأت من هذا على عضد\nولاصبحا في الروع من عددي … كرما وفي اللأواء من عددي\nولمانعا عني ، إذا جعلت … نوب الزمان تهيض من جلدي\nأو كان ما قدمت من مقة … سببا الى البغضاء لم يزد\nبل لو قذفت بمدحتي لكم … في\nلرمي الي اشف جوهرة … وسقى باعذب مائه بلدي\nكم من مطالب قد عقدت بها … طمعي ، فحل مرائر العقد\nوأعادني منها على أسف … واباتني فيها على ضمد\nالفعل مهزأة لكل فم … والعرض منديل لكل يد\nفليثبتن الان ان ثبتت … قدم على جمر لمعتمد\nوليصبرن لوقع صاعقتي … ويوطنن حشا على الزؤد\nفلتدخلن عليه قبته … ولاجة تخفى على الرصد\nوهواجم يدفعن كل يد … ونوافذ يهزأن بالزرد\nكالبيض لا يصقلن عن طبع … والسمر لا يغمزن عن اود\nحتى يذوق لحد انصلها … طعنا ، ولا طعن القنا القصد\nومتى يوقع فل مقنبها … لم اخلها ابدا من المدد\nأخطأت في طلبي ، وأخطأ في … يأسي ، ورد يدي بغير يد\nفلأجعلن عقوبتي أبدا … أن لا أمد يدا إلى أحد\nفتكون أول زلة سبقت … مني ، وآخرها إلى الأبد"},{"id":"diwan-radi:196","bookId":"diwan-radi","type":"poem","seq":196,"chapter":"البحر: طويل","title":"تزود من الماء النقاخ ، فلن ترى","page":"","text":"تزود من الماء النقاخ ، فلن ترى … بوادي الغضا ماء نقاخا ولا بردا\nونل من نسيم الرند والبان نفحة … فهيهات واد ينبت البان والرندا\nوعج بالحمى عينا فلست برامق … طوال الليالي ذلك العلم الفردا\nوكر الى نجد بطرفك انه … متى يعد لا ينظر عقيقا ولا نجدا\nتلفت دون الركب والعين غمرة … وقد مدها سيل الدموع بما مدا\nلعلي أرى دارا بأسنمة النقا … فأطربنا للدار أقربنا عهدا\nتلاعب بي بين المعالم لوعة … فتذهب بي يأسا وترجع بي وجدا\nمنازل ناشدت السحاب فما قضى … فريضتها عني السحاب ولا ادى\nوهل بالغ ما يبلغ الدمع عندها … حقائب غيث تحمل البرق والرعدا\nأمنك الخيال الطارقي بعد هجعة … يعاطي جوى الظمآن مبتسما بردا\nدنا من اعالي الرقمتين وما دنا … وصد وقد ولى الظلام ، وما صدا\nومن عجب ريي وما نقع الصدى … وعدى له منا علي وما اعتدا\nأساء ليالي الفرب نأيا وهجرة … واسدى على بعد من الدار ما اسدى\nأفي كل يوم للمطامع جاذب … يجشمني ما يعجز الأسد الوردا\nكاني اذا جادلت دون مطالبي … أجادل للأيام ألسنة لدا\nاحل عقود النائبات وانثنى … وخلفي يد للدهر تحكمها عقدا\nإذا ما نفذت السد من كل حادث … رأيت أمامي دون ما أبتغي سدا\nأأترك أملاكا رزانا حلومهم … حلولا على الزوراء أيمانهم تندى\nكانك تلقى منهم آجمية … مؤللة الأنياب أو قللا صلدا\nولا يأنف الجبار أن يعتفيهم … ولا الحر يأبى أن يكون لهم عبدا\nإذا ما عدمنا الجود منهم لعلة … فلن نعدم العلياء منهم ولا المجدا\nوان كريم القوم من خدم العلا … وان لئيم القوم من خدم الرفدا\nإذا ما طرقت المرء منهم وجدته … على النار لا كابي الزناد ولا وغدا\nلهم كل موقوذ من التاج راسه … غنى بالعلا ان ينسب الاب والجدا\nنحاسن اقمار الدجى بوجوههم … فنبهرها نورا ونغلبها سعدا\nتخالهم غيدا اذا بذلوا الندى … وتحسبهم جنا ، إذا ركبوا الجردا\nإذا طربوا للجود أمطرتهم حيا … وان غضبوا للمجد هيجتهم اسدا\nوأنقل بيتي في البلاد مجاورا … بيوت المخازي قد ضللت اذا جدا\nخياما قصيرات العماد تخالها … كلابا على الأذناب مقعية ربدا\nإذا عز ماء بينهم وردوا القذى … وإن قل زاد عندهم مضغوا القدا\nترى الوفد عن أعطانهم وقبابهم … من اللوم انأى من نهامهم طردا\nأأترك أمطاء السوابق ضلة … وأستحمل الحاجات أحمرة قفدا\nلرأي لعمري غير دان من النهى … ولا واسط في الحزم قبلا ولا بعدا\nفلا طرب أن زدت قربا إليهم … ولا اسف ان زاد ما بيننا بعدا\nكعمت لساني أن يقول ، وإن يقل … فقل في الجراز العضب ان فارق الغمدا\nوإن برودا للمخازي معدة … فمن شاء في ذا الحي اسحبته بردا\nقلائد في الاعناق بالعار لا تهي … على مر أيام الزمان ، ولا تصدا\nاذا صلصلت بين القنا قضت القنا … وان زفرت بالسرد قطعت السردا\nلها بين اعراض الرجال قعاقع … مدارجها أسعى من الغر أو أعدى\nأآل بويه ما نرى الناس غيركم … ولا نشتكي للخلق اولاكم فقدا\nنرى منعكم جودا ومطلكم جدا … وإذلالكم عزا وإمراركم شهدا\nوعيش الليالي عند غيركم ردى … وبرد الأماني عند غيركم وقدا\nاذا لم تكونوا نازلي الارض لم نجد … بها الوادي الممطور والكلأ الجعدا\nوينبط محفاري بارضكم الغنى … إذا ما نبا عن جانب اللؤم أو أكدى\nوكنت أرى أني متى شئت دونكم … وجدت مجازا للمطالب أو معدى\nفلم ار لي من مطلع عن بلادكم … ولا من مراح للاماني ولا مغدا\nخذوا بزمامي قد رجعت إليكم … رجوع نزيل لا يرى منكم بدا\nأريد ذهابا عنكم ، فيردني … إليكم تجاريب الرجال ، ولا حمدا"},{"id":"diwan-radi:197","bookId":"diwan-radi","type":"poem","seq":197,"chapter":"البحر: بسيط تام","title":"أرى وجوها وأيمانا مقفلة","page":"","text":"أرى وجوها وأيمانا مقفلة … فمغلق البشر منها مغلق الجود\nمعبسين لئلا يحدثوا طمعا … للسائلين ولا يوفوا بموعود\nنوالهم بين صعب النيل ممتنع … بالمطل أو مستخس القدر مردود"},{"id":"diwan-radi:198","bookId":"diwan-radi","type":"poem","seq":198,"chapter":"البحر: طويل","title":"هوى لكما ان الشباب يعاد","page":"","text":"هوى لكما ان الشباب يعاد … وإن بياض العارضين سواد\nوإن الليالي عدن ، والحي جيرة … كما كن ام لا مالهن معاد\nحننت اليكم حنة النيب اصبحت … ثلوب على الماء الروى وتذاد\nتوان بأعناق الغليل ، وقد حوى … مشارعه عذب الجمام يراد\nدع الوجد يبلغ ما ارادا فما الهوى … بدان ، ولا عهد الديار معاد\nوإن بذاك الجزع وحشا غريرة … تصيد ، وأعيا الناس كيف تصاد\nضلالا ، أبين الزاهدين أزاد … فظل ، ولم يملك لهن قياد\nغداة وقفنا ، والدموع مرشة … كأن عيون الواقفين مزاد\nأبا طول هم أن تكون مضاجع … وغزر دموع ان يكن رقاد\nفتموا على عنف السياق وزادوا … وبين جفوني والمنام طراد\nلهم كل يوم والنوى مطمثنة … سليم له يوم الفراق عداد\nفيا بين لم تنفع اليك وسيلة … ويا وجد لم يسلم عليك فؤاد\nحلفت بايديهن في كل مهمه … عليهن من باقي الظلام سواد\nكأيدي العذارى الفاقدات تدارعت … للدم الطلا اطمارهن حداد\nخوانف ، مهبوط بهن عشية … قرار ، ومطلوع بهن نجاد\nتقص بآثار الدماء ، كأنها … مساحب جرحى يوم طال طراد\nيطيرن بالوقع الشرار كانما … مناسمها تحت الظلام زناد\nكأن الدجى والفجر يركب عقبه … نزائع دهم خلفهن وراد\nأزير سرى ما فيه للغمض مطمع … كان قتود اليعملات قتاد\nروام إلى جمع كأن رؤوسها … قباب بنتها بالمراقب عاد\nيجعجعن أجلادا وهاما رواجفا … وهن على ما نابهن جلاد\nلحي على الجرعاء الام رحلة … إذا ظعنوا ساقوا العيوب وقادوا\nاذا رحلوا عن خطة اللوم خالفوا … إليها بأعناق المطي وعادوا\nلهم مجلس ما فيه للمجد مقعد … ومربط عار ما عليه جياد\nبيوتهم سود الذرى ، ولنارهم … مواقد بيض ما بهن رماد\nلهم حسب اعمى اضل دليله … قلم يدر في الاحساب اين يقاد\nتحير في الأحياء ذلا متى يرم … سبيل العلى يضرب عليه سداد\nله عن بيوت الأكرمين دوافع … وعن هضبات الماجدين ذياد\nقباب يطاطي اللؤم منها كأنها … ولو رفعت فوق الجبال وهاد\nوايد جفوف لا تلين وانها … ولو مطرت فيها الغيوم جماد\nلهن على طرد الضيوف تعاقد … هراش كلاب بينهن عقاد\nتصان النصول النابيات وعندهم … نصول مواض ما لهن غماد\nاما كان فيكم مجمل أو مجامل … إذا لم يكن فيكم اغر جواد\nفلامر حبا بالبيت لا فيه مفزع … للاج ولا للمستجن عماد\nفلا ترهبوني بالرماح سفاهة … فعيدان أوطاني قنا وصعاد\nولا توعدوني بالصوارم ضلة … فبيني وبين المشرفي ولاد\nسامضغ بالاقوال اعراض قومكم … وللقول انياب لدي حداد\nترى للقوافي ، والسماء جلية … عليكم بروق جمة ورعاد\nفحمد الآل الغوث إن أكفهم … سباط الحواشي ، واللمام جعاد\nإذا وقفوا في المجد خافوا نقيضه … فثموا على عنف السياق وزاد\nأقاموا بأقطار العلى وتناقلوا … عليها وأبدوا في العلى ، وأعادوا\nإلى حسب منه على البدر عمة … وفي عاتق الجوزاء منه نجاد\nبما تنزل الحاجات يا أم مالك … وأين رجال تعتفى وبلاد\nحبست مقالي محبس البدن أبتغى … به عوضا جما ، وليس يراد\nارى زهد مستام وارجو زيادة … \nفلا اخضر واد أنتم من حلاله … ولا جيد ما جاد البلاد عهاد\nولا رفعت نار لكم مسي ليلة … ولا راج مال طارف وتلاد\nفما للندى فيكم نصيب وسهمه … ولا للاماني مسرح ومراد\nألا إن مرعى الطالبين هشائم … لديكم ، وورد الآملين ثماد\nلكم عقدة قبل النوال مريرة … وداهية بعد النوال نآد\nوزرعتم ولكن حال من دون زرعكم … جنود اذى منها دبى وجراد"},{"id":"diwan-radi:199","bookId":"diwan-radi","type":"poem","seq":199,"chapter":"البحر: وافر تام","title":"أرى بغداد قد أخنى عليها","page":"","text":"أرى بغداد قد أخنى عليها … وصبحها بغارته الجليد\nكان ذرى معالمها قلاص … نواء كشطت عنها الجلود\nكأن به لغام العيس باتت … تساقطه عجال الرجع قود\nغطى قمم النجاد ، فكل واد … على نشراته سب جديد\nكما تعرى به الغيطان محلا … وتغبر التهايم والنجود\nفمهما شئت تنظر من رباها … إلى بيض عواقبهن سود\nأقول له وقد أمسى مكبا … على الأقطار يضعف ، أو يزيد :\nوراءك فالخواطر باردات … على الإحسان والأيدي جمود\nوانك لو تروم مزيد برد … إلى برد لاعوزك المزيد"},{"id":"diwan-radi:200","bookId":"diwan-radi","type":"poem","seq":200,"chapter":"البحر: كامل تام","title":"ردوا تراث محمد ردوا","page":"","text":"ردوا تراث محمد ردوا … ليس القضيب لكم ، ولا البرد\nهل عرقت فيكم كفاطمة … أم هل لكم كمحمد جد\nجل افتخارهم بأنهم … عند الخصام مصاقع لد\nإن الخلائف والأولى فخروا … بهم علينا قبل أو بعد\nشرفوا بنا ولجدنا خلقوا … وهم صنائعنا ، إذا عدوا"},{"id":"diwan-radi:201","bookId":"diwan-radi","type":"poem","seq":201,"chapter":"البحر: خفيف تام","title":"بان عهد الشباب منكم حميدا","page":"","text":"بان عهد الشباب منكم حميدا … وجديدا لو كان دام جديدا\nفترى الظاعن المقوض بيتي … ه يرجى من قلعة أن يعودا\nلا يرى ناقلا إلى الحي رجلا … لا ولا ثانيا إلى الدار جيدا\nفإذا شئت أن تبكي ليالي … فملآن قل لعينيك جودا"},{"id":"diwan-radi:202","bookId":"diwan-radi","type":"poem","seq":202,"chapter":"البحر: طويل","title":"أحاجي رجالا : ما ملابس سود","page":"","text":"أحاجي رجالا : ما ملابس سود … جدائد لا يبقى لهن جديد\nسحائب تمضي بالفتى فصواعق … وغيث وهيف زعزع وبرود\nكذلك ، والأيام نعمى وأبؤس … لكل هبوب ، يا أميم ، ركود"},{"id":"diwan-radi:203","bookId":"diwan-radi","type":"poem","seq":203,"chapter":"البحر: مجتث","title":"يا قادحا بالزناد","page":"","text":"يا قادحا بالزناد … مر فاقتدح بفؤادي"},{"id":"diwan-radi:204","bookId":"diwan-radi","type":"poem","seq":204,"chapter":"البحر: كامل تام","title":"هذا أمير المؤمنين محمد","page":"","text":"هذا أمير المؤمنين محمد … كرمت مغارسه وطاب المولد\nأوما كفاك بأن أمك فاطم … وأبوك حيدرة وجدك أحمد\nيمسي ، ومنزل ضيفه لا يحتوى … كرما ، وبيت نضاره لا يقلد"},{"id":"diwan-radi:205","bookId":"diwan-radi","type":"poem","seq":205,"chapter":"البحر: كامل تام","title":"غيري أضلكم ، فلم أنا ناشد","page":"","text":"غيري أضلكم ، فلم أنا ناشد … وسواي أفقدكم فلم أنا واجد\nعجبا لكم يأبى البكاء أقارب … منكم وتشرق بالدموع أباعد"},{"id":"diwan-radi:206","bookId":"diwan-radi","type":"poem","seq":206,"chapter":"البحر: وافر تام","title":"أتوا بمخالب الآساد سلت","page":"","text":"أتوا بمخالب الآساد سلت … براثنها ، وأشلاء الجلود\nوأي ممنع يأبى عليهم … إذا آبوا بأسلاب الأسود"},{"id":"diwan-radi:207","bookId":"diwan-radi","type":"poem","seq":207,"chapter":"البحر: كامل تام","title":"من كل سارية كأن رشاشها","page":"","text":"من كل سارية كأن رشاشها … ابر تخيط للرياض برودا\nنثرت فرائدها فنظمت الربى … من درهن قلائدا وعقودا"},{"id":"diwan-radi:208","bookId":"diwan-radi","type":"poem","seq":208,"chapter":"البحر: طويل","title":"ولاحت لنا أبيات آل محرق","page":"","text":"ولاحت لنا أبيات آل محرق … بها اللؤم ثاو لا يروح ولا يغدو\nخيام قصيرات العماد كأنها … كلاب على الأذناب مقعية ربد"},{"id":"diwan-radi:209","bookId":"diwan-radi","type":"poem","seq":209,"chapter":"البحر: طويل","title":"جعلت لك الفرخين يا نصر طعمة","page":"","text":"جعلت لك الفرخين يا نصر طعمة … فقم غير رعديد لنفسك واقعد\nفإني مشغول عن الرأي بالهوى … وبابن شريح والغريض ومعبد"},{"id":"diwan-radi:210","bookId":"diwan-radi","type":"poem","seq":210,"chapter":"البحر: رجز تام","title":"أقول لبيك ، ولم تناد","page":"","text":"أقول لبيك ، ولم تناد … ما أوقع الموت على الجواد\nما كنت الا حية بواد … واسدا على العدو عاد\nورب جار لي من الأعادي … اقام بعد ذلة عمادي\nكأنه في الكرب الشداد … جار الحذاقي ابي دواد"},{"id":"diwan-radi:211","bookId":"diwan-radi","type":"poem","seq":211,"chapter":"البحر: متقارب تام","title":"ترى النازلين بارض العراق","page":"","text":"ترى النازلين بارض العراق … ق ، قد علموا أن وجدي كذا\nفلا حبذا بلد بعدهم … وإن أوطنوه ، فيا حبذا\nدنا طرب والهوى نازح … فيما بعد ذاك ويا قرب ذا\nهوى لي اطعت به العاذلين … وما طاعة العذل الا اذى\nوكنت أقذي به ناظري … فمذ غاب صار لعيني قذى"},{"id":"diwan-radi:212","bookId":"diwan-radi","type":"poem","seq":212,"chapter":"البحر: مجزوء الرجز","title":"ما للبياض والشعر","page":"","text":"ما للبياض والشعر … ما كل بيض بغرر\nصفقة غبن في الهوى … بيع بهيم بأغر\nصغره في أعين الغي … د بياض وكبر\nلولا الشباب ما نهى … على المها ولا امر\nما كان اغنى ليل … ذا المفرق عن ضوء القمر\nقد كان صبح ليله … أمر صبح ينتظر\nواها وهل يغنى الفتى … بكاء عين لأثر\nيا حبذا ضيفك من … مفارق ، وإن عذر\nاين غزال داجن … رأى البياض ، فنفر\nهيهات ريم السرب لا … يدنو الى ذيب الخمر\nيا دهر ما ذنبك في … ما رابني بمغتفر\nرب ذنوب للفتى … ليس لها اليوم عذر\nأقصر فقد جزت المدى … مجاملا ، أو فاقتصر\nالان اذ لف النهى … مرة حزم بمرر\nوعاد منصاتي على … ايدي الليالي ينأطر\nوسالمت شمائلي … جن العرام والاشر\nنان في اليوم المطر … يوم ، وظلا فانحسر\nأقسمت بالأطلاح قد … أدمج منهن الضمر\nيمطلن بالعشب ، فلا … رعي لها إلا الجرر\nكل علاة تتقى ال … ط بمجدول ممر\nكأنها حنية … إلا اللياط والوتر\nمخفض الجأش ، إذا … طوى الليالي ونشر\nملبدا يرمى الى … مكة حصباء الوبر\nاذا رأى اعلامها … عج اليها وجأر\nام اللوى ثم نحا … الخيف ولبى وجمر\nفي محرمين بدلوا ال … نخاطر البزل ، وقد\nإن قوام الدين أو … لى بالعلى من البشر\nوبالجياد والقنا … وبالعديد والنفر\nوبالمقاويم العلا … وبالمعاظيم الكبر\nمهذب الاعياص في … باء مختار الشجر\nمفترش للملك احلى … في المعالي وامر\nفي صبية تفوقوا … من حلب العز درر\nملاعب بين قباب … الملك منهم والحجر\nمن معشر لم يخلقوا … الا لنفع أو ضرر\nلسد ثغر فاغر … بالبيض ، أو طعن ثغر\nكانوا ثمال الناس وال … اذا ما الامر هر\nأيام لا نلقى لنا … معتصما ولا وزر\nجروا إلى طعن العدى … ارعن هداد المجر\nجحافلا كالسيل اب … قى غمرا بعد غمر\nقد لبست جيادها … براقعا من الغرر\nضمر كامثال القنا … لولا السبيب والعذر\nمعجلة فرسانها … حتى عن الدرع تزر\nيقرع فيهن القنا … وقع المداري في الشعر\nلأم اكن انهى العدى … عن ناب نضناض ذكر\nله اليهم مسحب … يهدي المنايا ومجر\nمجاليا بكيده … ان عاجز القوم اسر\nيمسى بطينا من دم … الاعداء وهو مضطمر\nينام لا عن غفلة … عينا وبالقلب سهر\nما ضره من سمعه … أن لا يعان بالبصر\nبقية من قدم ال … ضلال وقاد النظر\nومؤجد المتنين إن … صمم للعقر عقر\nكأن في ساعده … وعيا وعى ثم جبر\nكالقاتل اعتام القوى … بعد القوى ثم شزر\nمخقض الجاش اذا … صاح به الجمع وقر\nاخبر خافي الشخص … لا بالمقام المشتهر\nيقعي بنجد والحمى … من وثبة على غرر\nمبترك الصالي على … النار ، ليالي القرر\nكم قلت منه للعدى … حذار ان اغنى الحذر\nوعوذوا منه النحو … ر والرقاب والقصر\nإياكم منه ، إذا … اوعد نابا وظفر\nوقام نفض الحلس يج … لو ناظرا ثم زأر\nملتفعا بشملة … فيها البجارى والبجر\nتوقعوا طلاعها … كناغر العرق نغر\nإن العدى لينضها … \nكأنها حائمة العق … بان في اليوم المطر\nيمشين من صبغ الد … ء في رياط وأزر\nتخاطر البزل وقد … مار عليهن القطر\nفي كل يوم تحتها … منجدل ومنعفر\nتجر في شوك القنا … حر القديد المصطهر\nتخبروا اليوم ، فما … بعد الطعان من خبر\nآل بويه انتم الا … مطار والناس الحضر\nما في الليالي غيركم … شيء به العين تقر\nان نهض الجاش بكم … فما نبالي من عثر\nلولاكم لم يبق في … عود الرجاء معتصر\nقد غنى الملك بكم … وهو إليكم مفتقر\nفدم على الأيام أر … سي في العلى من الحجر\nترفع ذيلا لمراقي المج … د أو ذيلا تجر\nوانعم بذا النيروز زو … را نازلا ومنتظر\nيفاوح النعمى كما … فاوحت الروض المطر\nقضيت فيه وطرا … وما قضى منك وطر\nما جزعي لمن مضى … وانت لي فيمن غبر\nانت المراد والمراد … د ، والمعاذ والعصر\nردمن جمام العزلا … مطرقا ، ولا كدر\nوازدد بقاء وعلا … ما بعد ورديك صدر\nمقدما إلى العلى … مؤخرا عن القدر"},{"id":"diwan-radi:213","bookId":"diwan-radi","type":"poem","seq":213,"chapter":"البحر: طويل","title":"أيا مرحبا بالغيث تسري بروقه","page":"","text":"أيا مرحبا بالغيث تسري بروقه … تروح يندي لا بكيا ولا نزرا\nطلعت على بغداد والخطب فاغر … فعاد ذميما ينزع الناب والظفرا\nاذاءت وعزت بعد ذل وروضت … كانك كنت الغيث والليث والبدرا\nتغاير اقطار البلاد محبة … عليك فهذا القطر يحسد ذا القطرا\nوقلمت أظفار الخطوب فما اشتكى … نزيلك كلما للخطوب ولا عقرا\nومن ذا الذي تمسي من الدهر جاره … فيقبل للمقدار ، إن رابه ، عذرا\nفيا واقفا دون الذي تستحقه … لو أنك جزت الشمس لم تجز القدرا\nفعثرا لأعداء رموك ، ولا لعا … ونهضا على رغم العدو ، ولا عثرا"},{"id":"diwan-radi:214","bookId":"diwan-radi","type":"poem","seq":214,"chapter":"البحر: خفيف تام","title":"لن تشقوا لذا الجواد غبارا","page":"","text":"لن تشقوا لذا الجواد غبارا … فاربحوا خلفه الوحى والعثارا\nوقفوا في مصارع العجز عنه … فات فوت الوميض من لا يجارى\nسابق عضت الاكف عليه … انج اليوم في العلاء وغارا\nقام يجني العلى وانتم قعود … وصحا للندى ، وأنتم سكارى\nطلبوا شأوك المبرز ، هيها … طريقا على الجياد خبارا\nليس منهم من ساق تلك المصاعي … ب غلابا ، وقاد ذاك القطارا\nشمري ايها الركاب وخلي … عطن اللوم والعماد القصارا\nوانزلي بي مجاورا في اناس … لا يذم النزيل فيهم جوارا\nخلطوا الضيف بالنفوس على العس … ر ، وباتوا على السماح غيارى\nعند أقنى من البزاة عتيق … ترك الطير واقعات وطارا\nمن اذا عرضوا تعرض جودا … واذا جارت الليالي اجارا\nما مقامي على الجداول ارجوها … ها لنيل ، وقد رأيت البحارا\nكالذي شاور الدجى في سراه … واستغش النجوم والأقمارا\nيا أبا غالب دعوتك للخط … ب ، ومن يظم يستدر القطارا\nلم أجاوزك بالدعاء ، فلبي … ت جهارا ، وقد دعوت سرارا\nلم تقل لا ولم تشد على خلف … الندى بين راحتيك صرارا\nوسبقت العلات ، لم تنتظرها … ولو شئتها لكانت كثارا\nقد هززناك للندى فوجدنا … ورقا ناضرا وعودا نضارا\nورأينا النوال عينا بلا مط … اذا ما النوال كان ضمارا\nلم تزل كاملا ولم تسم بالكا … مل من قبل ان تشد الازارا\nصبية من معاشر حذقوهم … أدب الجود والعلاء صغارا\nاليق الناس بالسماح اكفا … والمعالي شمائلا ونجارا\nفي صيال الأسود إن نزل الخط … ب عليهم وفي حياء العذارى\nكلقاح تأبى على العصب درا … وعلى المسح تستهل غزارا\nاطلقونا من الخطوب فبتنا … في يد المن مطلقين اسارى\nما نرى عند غيركم من جميل … ليس الا من عندكم مستعارا\nقد رأينا الإحسان منكم عيانا … وسمعناه عنكم اخبارا\nمن رأى قبلكم شموسا مضيا … ت جمعن الانوار والامطارا\nنظر الخلة الخفية عندي … نظر الغيث صاب يبغى قرارا\nلم يغالط عنها اللحاظ ، ولا أص … فح عنها فعل اللئيم ازورارا\nبادر الحادث المعد اليها … ورأى الغنم أن يكون بدارا\nيوقد النار للقرى ، وعليها … حسب لو خبا الوقود أنارا\nولو اسطاع ، والمطي تسامى … شب فوق الرجال بالليل نارا\nهمم همها العلى علمته … بالندى كيف يملك الاحرارا\nلا كقوم لم يطلعوا شرف الجود … د ، ولم يرفعوا لمجد منارا\nيقف الحق عندهم فيلاقي … طرق الجود بينهم اوعارا\nعرفوا محكم التجارب في البخ … ل ، وكانوا عن الندى أغمارا\nعند جول الاراء بله عن الحزم … وفي الخطب عاجزون حيارى\nيا كمال العلى ويا وزر الملك … اذا لم يجد معانا ودار\nمعملا في الخميس أقلامك الغ … اذا اعملوا القنا الخطارا\nكلما اشرعوا الذوابل اشرعت … ت غريما صدقا ، ورايا مغارا\nبك سدوا فوار جائشة القع … ر ، لها عائد يرد السبارا\nوجدوا طبها لديك ، فولو … على البعد عرقها النغارا\nلو أقاموا لها سواك لشبت … صعبة تمنع المطا والعذارا\nضربوا اوجه البكار وقادوا … للاعادي قباقبا هدارا\nورأوا في مناكب الملك وهنا … فدعوا باسمه فكان جبارا\nقائدا للقراع كل حصان … تتراءى به عقابا مطارا\nمثل لون العقار تحسبه نارا … يطير الطعان منها شرارا\nدافعا بالرماح في كل ثغر … لججا تركب العدو غمارا\nيتلاغطن باصطكاك العوالي … لغط الحج يرجمون الجمارا\nعجبا للذي أجرت من الأ … لم لا يحارب الاقدارا\nأيخاف الخطوب من كان للي … ث نزيلا ، وكان للنجم جارا\nلو قدرنا وساعفتنا الليالي … لوصلنا بعمرك الأعمارا"},{"id":"diwan-radi:215","bookId":"diwan-radi","type":"poem","seq":215,"chapter":"البحر: رجز تام","title":"يا ناشد النعماء يقفو إثرها !","page":"","text":"يا ناشد النعماء يقفو إثرها ! … قف المطايا قد بلغت بحرها\nمسيلها فينا ، ومستقرها … طود العلى وشمسها وبدرها\nفوضت الدنيا إليه أمرها … وقلدته نفعها وضرها\nعدت مساعيها ، فكان فخرها … لم تقذ عين المجد مذ اقرها\nذو شيمة تعطي العيون خبرها … لا تحوج الناظر ان يقرها\nنرجو ونخشى حلوها ومرها … كجمة الماء نرجي غمرها\nيوم الورود ، ونهاب قعرها … يبعثها بعث السحاب قطرها\nمحجلات نعم وغرها … شغلتنا حتى نسينا شكرها\nيهدي إلينا شفعها ووترها … عياب دارين حملن عطرها\nإن المعالي ولدتك بكرها … ما ضمنت مثلك يوما حجرها\nاما رؤما ارضعتك درها … لو ألفت على النظام نثرها\nقلائد المجد لكنت درها … نرى الاعادي ان عزمت ثغرها\nأباغث الطير تراءت صقرها … فحل وغى يئسي الفحول هدرها\nلاصبحتنا ووقينا شرها … ظلماء أمر لا تكون فجرها"},{"id":"diwan-radi:216","bookId":"diwan-radi","type":"poem","seq":216,"chapter":"البحر: سريع","title":"قرت عيون المجد والفخر","page":"","text":"قرت عيون المجد والفخر … بخلعة الشمس على البدر\nصبت على عطفيه اطرافها … مغلمة بالعز والنصر\nكأنها خلعة ثوب الدجى … في عاتق العيوق والنسر\nزر عليه الملك فضفاضها … وانما زر على\nخطوت فيها غير مستكبر … خطو السها في خلع الفجر\nجاءت عوانا من تحياته … وانت منها في على بكر\nفكل يوم أنت في صدره … فارس طرف الحمد والاجر\nتغدو بك الايام نهاضة … تطلع من مجد إلى فخر\nفانهض فلو رمت لحاق العلى … صافحت أيدي الأنجم الزهر\nولو زجرت المزن عن صوبه … لضنت الاقطار بالقطر\nوضمت الانواء اخلافها … كما استمر الماء في الغدر\nفانت سر في ضمير العلى … كالعقد بين الجيد والنحر\nتبرجت منك وجوه المنى … مرتجة في النائل الغمر\nإنك من قوم ، إذا استلأموا … تقبلوا في البيض والسمر\nوقطروا الخيل بفرسانها … خارجة عن حلقة الحضر\nوجاذبوا الايام اثوابها … عنها ، بأيدي النهي والأمر\nمن كل طلق الوجه سهل الحيا … يبسم عن اخلاقه الغر\nمقدم في القوم ما قدمت … عن ريشها قادمة النسر\nريان والايام ظمآنة … من الندى ، نشوان بالبشر\nلا يمسك العذل يديه ولا … تاخذ منه سورة الخمر\nاليك سيرت بها شامة … واضحة في غرة الدهر\nشدا بها العترف في جوه … وارتاح طير الصبح في الوكر\nأبياتها مثل عيون المها … مطروفة الألحاظ بالسحر\nجاءت تهنيك بطوق العلى … ولفظها يفتر عن در\nفاسعد ، أبا سعد ، بإقباله … فالهدي مجنوب الى النحر\nما هو إنعام ، ولكنه … ما خلع الغيث على الزهر\nجاءتك من قبلي ، وإحسانها … يقوم لي عندك بالعذر\nولو اجبت الشوق لما دعى … جاءك بي من قبل أن تسري"},{"id":"diwan-radi:217","bookId":"diwan-radi","type":"poem","seq":217,"chapter":"البحر: مجزوء الكامل","title":"نطق اللسان عن الضمير","page":"","text":"نطق اللسان عن الضمير … والشر عنوان البشير\nالان اعفيت القلو … ب من التقلقل والنفور\nوانجابت الظلماء عن … وضح الصباح المستنير\nما طال يوم ملثم … إلا استراح إلى السفور\nخبر تشبث بالمسامع … عن فم الملك الخطير\nوأذل أعناق العدى … ذل المطية للجرير\nيسمو به قول الخطيب … ب وتستطيل يد المشير\nوضمائر الاعداء تقذف … بالحنين على الزفير\nوسوابق العبرات تر … كض في السوالف والنحور\nوضحت به الأيام في … ئب غير فضفاض الضمير\nمتحير عند النوائب … مستريب بالامور\nغرض بنعمته ، وبع … ض القوم يشرق بالنمير\nيغتر بالدنيا وحبلك … لا يدلى بالغرور\nحسب المضخ بالدماء … ء كمن تغلف بالعبير\nولأنت مثل القر يعصف … منه بالشعرى العبور\nكنت النسيم جرى علي … فغض من نار الحرور\nعجلان يحمل مغرم … الدنيا على ظهر حسير\nيسطو بلا سبب ، وتل … ك طبيعة الكلب العقور\nانت المكلل بالمناقب … عند ايماض الثغور\nفي رفقة البيداء او … بين المنازل والقصور\nغيرت الوان الرماح … ح ، ورونق البيض الذكور\nورددت أعطاف الظبى … تختال في العلق الغزير\nبضوامر مثل النسو … وغلمة مثل الصقور\nوبأسرة من هاشم … غدروا بربات الخدور\nسمر الترائب والطلى … بيض العوارض لا الشعور\nمستنجدون على البعا … ومنجدون على الحضور\nالمانعون من الاذى … والمنقذون من الدهور\nلهم الكلام ، وإنما … للاسد صولات الزئير\nالنجر مختلف وان … كان النبال من الجفير\nفي الناس غير مطهر … والحر معدوم النظير\nوالنسل يخبث بعضه … ما كل ماء للطهور\nلك دون أعراض الرجا … حمية الرجل الغيور\nولماء كفك في المحول … ل طلاقة العام المطير\nما بين نعمة طالب … فينا ، ودعوة مستجير\nالعز من شيع الغنى … والذل اولى بالفقير\nولربما رزق الغنى … رب الشويهة والبعير\nعصفت بمبغضك النوائب … من امير أو وزير\nلما أراد بك المن … صار من تحف القبور\nجذبته في شطن المنون … ن يد النآد العنقفير\nوضمحت به الايام في … ظل النعيم إلى الهجير\nمتأوها تحت الخطوب … تأوه الجمل العقير\nلعبت بك الدنيا ، وسع … في فم الجد العثور\nوالريح تلعب بالذوا … بل وهي تطعن في الصدور\nما التذ لبس الصوف الا … لا من تعمم بالقتير\nمتخدد الخدين مغ … الذوائب والضفور\nسام بفضل حيائه … والطرف يوصف بالفتور\nاسر الوقار طماحه … والقد املك بالاسير\nمن بعد ما صحب الركا … ئب لا يعف عن المسير\nجذلان ينظر وجهه … في عارض العضب الشهير\nمتغطرفا كالسيل يب … بالجنادل والصخور\nانا بني الدنيا نعلل … بالليالي والشهور\nكفلت بانفسنا وهل … طفل يعيش بغير ظير\nنحن الشبول من الضراغم … والنطاف من البحور\nواذا عزانا ناسب … نسب الشموس إلى البدور\nغدر السرور بنا وكان … ن وفاؤه يوم الغدير\nيوم اطاف به الوصي … وقد تلقب بالامير\nفتسل فيه ورد عارية … رية الغرام إلى المعير\nوابتز اعمار الهموم … بطول اعمار السرور\nفلغير قلبك من يعل … ل همه نطف الخمور\nلا تقنعن عند المطالب … لب بالقليل من الكثير\nفتبرض الأطماع مثل … تبرض الثمد الجرور\nهذا أوان تطاول الحا … جات والأمل القصير\nفانفح لنا من راحتيك … بلا القليل ولا النزور\nلا تحوجن إلى العصا … وانت في الضرع الدرور\nاثار شكرك في فمي … وسمات ودك في ضميري\nوقصيدة عذراء مث … ل تألق الروض النضير\nفرحت بمالك رقها … فرح الخميلة بالغدير\nوكأنه في رصفها … جار الفرزدق أو جرير\nوكأنه في حسنها … بين الخورنق والسدير"},{"id":"diwan-radi:218","bookId":"diwan-radi","type":"poem","seq":218,"chapter":"البحر: متقارب تام","title":"رأيت المنى نهزة الثائر","page":"","text":"رأيت المنى نهزة الثائر … وسهم العلى في يد القامر\nوما عدم المجد مستأسد … يبل القنا بالدم المائر\nولو ضمن العز بعض الوكور … أغارت يداه على الطائر\nوإن ولج الضغن أثوابه … نضا لبدة الأسد الخادر\nيسفه في الروع فعل القنا … ويرضى عن المقضب الباتر\nفشمر لمظلمة ما تزا … تقبض من بطشه الناظر\nورد غمرة العز بين الرماح … واحجر على الماء في الحاجر\nرأيتك تصلى بحر الطعا … ن ، كما صليت شحمة الصاهر\nأبثك أني قطعت الزما … ن أطلب عزي ، أو ناصري\nفما ارتاح همي الى صاحب … ولا نام عزمي على سامر\nإذا قيد الليل خطو المنى … مشى النوم في مقلة الساهر\nوإني أخف إلى المسمعا … ت عن خطرة الشغف الخاطر\nوما ذاك جهلا ، ولكنه … نزاع الجواد إلى الصافر\nولولا القريض واشغاله … شغلت بغير المنى خاطري\nوما الشعر فخري ، ولكنه … اطول به همة الفاخر\nأنزهه عن لقاء الرجا … ل وأجعله تحفة الزائر\nفما يتهدى اليه الملوك … الا من المثل السائر\nواني وان كنت من اهله … لتنكرني حرفة الشاعر\nوطوقني الدهر ثني الزمام … فالان اهزأ بالزاجر\nواني لالقى من النائبات … ملقى الاشاء من الآبر\nاو انس وحشي هذا البروق … ق في موطن النعم النافر\nواصحب فيها رفاق السحاب … تنبو عن البلد العامر\nلعلي ألقى عصي النوى … تأوب ذي اللبد الصادر\nوكنت اذا منحتني الملوك … نزازا من النائل الغامر\nأبيت القليل ، ولكنني … رددت الرذاذ على الماطر\nوماالفخر في ادب ناتج … يضاف الى مطلب عاقر\nوكم قمت في مشهد للخطوب … قياما بغيضا إلى الحاضر\nأرد النوائب بالموسوي … وأعطي الرغائب بالناصري\nولولا الحسين عصبت الرجاء … واغضيت عن برقه النائر\nواشمت بالقرب ايدي النوى … وخاطرت بالطمع العائر\nاذا هم باع الطلا بالظبي … وكف المعاقر بالثائر\nكأن الظلام إذا خاضه … تلثم بالقمر السافر\nرأى المجد اعظم ما يقتنى … اذا السيف عق يد الشاهر\nفطاعن حتى استباح ال … ح ، إن الغنيمة للظافر\nرمى بالجياد صدور الركاب … ب عن قدرة الآمل القادر\nفقاد الجديل الى لاحق … وأهدى الوجيه إلى داعر\nواصبح وهو وراء المطي … يلعب بالاجرد الضامر\nإذا مشق الخف فوق البطا … ح وقع فيهن بالحافر\nيوقع ألحاظه ، والشجا … ع يلحظ عن ناظر فاتر\nإذا عز عن حلمه أول … فان الحمية في الاخر\nفما انفرج الدهر عن مثله … إذا عصف الروع بالصابر\nاحد على الطعن من صارم … وأصفح عن زعلة العاثر\nواجدر ان نابه نائب … برد الامور الى الآمر\nأبا أحمد ! ثمرات المدي … ح تحرز عن فرعك الناضر\nاذا العجز حط المعالي هجمت … ت على هالة القمر الباهر\nوما زلت تعدل في الغادرين … حتى انتصفت من الجائر\nأتتك تشبب لب الفتى … كما مزقت نفثة الساحر"},{"id":"diwan-radi:219","bookId":"diwan-radi","type":"poem","seq":219,"chapter":"البحر: كامل تام","title":"وقف على العبرات هذا الناظر","page":"","text":"وقف على العبرات هذا الناظر … وكفاه سقما أنه بك ساهر\nردي عليه ما نضا من لحظه … خداك والغصن الوريق الناضر\nفلأنت آمن ان يلومك عاذل … في فرط حب ، أو يغرك عاذر\nهذا الفراق ، وأنت أعلم بالهوى … فارعى فايام المحب غوادر\nوانا الفداء لمن اباح حمى الهوى … فغدت تطاه مناسم ، وحوافر\nحوشيت ان القاك سارق لحظة … تلد الوفاء وام عهدك عاقر\nوابى الهوى ما كدت اسلو في الكرى … إلا ارتقى طرفي الخيال الزائر\nاليوم جار البين في أحكامه … فكأن اسباب الوفاء جرائر\nهذي الديار لها بمنعرج اللوى … قفرا ، تجنبها الغمام الباكر\nأرض أقول بها لسانحة المها : … انا ان عثرن لعا وقلبي العاثر\nقالت وقد غمرت دموعي وجنتي : … لله ما فعل المحل الداثر\nأغضيت عن وجه الحبيب تكرما … واريته ان الجفون كواسر\nهب لي وحسبي نظرة أرنو بها … فمقرها وجه الحسين الزاهر\nفلثم أبلج إن أهل جبينه … جمحت اليه خواطر ونواظر\nقرب الغمام فعن قريب ينثني … فيبل مربعك العريض الماطر\nان حل بيدا فالخلاء محافل … او قاد خيلا فالسروج منابر\nيا ابن الأكابر لا أقمت بمشهد … إلا وذكرك في المكارم سائر\nما سرت حتى سار نعتك أولا … فسريت تتبعه وهمك آخر\nنفثت لك الأمطار في عقد الربى … فقصدتها ان الغمام لساحر\nذلل ركابك اين سرت كأنما … وصى المطي بك الجديل وداعر\nما ضر من شرب الحمام تكرها … بظباك في روع ، وأنت تعاقر\nقضب الأعادي لا ترومي ضربه … أبدا ، فأنت لما يخد مسابر\nسايرت أزماني ، فلم أبلغ مدى … حتى استقل بي الثناء السائر\nوصحبت أيام الهوى فرأيتها … سرحا حمته عواذل وعواذر\nورأيت اكبر ما رأيت متيما … متنازعاه آمر ، أو زاجر\nفندمت بعد الحب كيف أطيعه … وعصيت عزماتي ، وهن أوامر\nابكي على الايام وهي ضواحك … في وجه غيري وهو فيها حائر\nلو شاب طرف شاب أسود ناظري … من طول ما أنا في الحوادث ناظر\nاو ان هذي الشمس تصبغ لمة … صبغت شواتي طول ما انا حاسر\nاو كان يأنس بالانيس اوابد … يوما ، لزم لي النعام النافر\nما المجد إلا في السرى ، والحمد إ … الا في القرى والمستغر الخاسر\nوغدا أمشي العيس بين حطيطة … ووديقة لم يغن فيها ماطر\nتندى مناسمها دمى وشفاهها … تندى لغاما والخفاف مشافر\nيخبطن أجواز الصفيح على الوجى … والليل منتشر القوادم طائر\nبينا يوسدنا الكرى اعضادها … حتى قذفن النوم ، وهي نوافر\nخوص كان عيونها في هامها … قلب بعدن عن الورود غوائر\nواذا عبرن بماء واد جزنه … عجلاى يخدن كانهن صوادر\nوإليك أنحلت الفلا أخفافها … تطوى بهن قبائل وعمائر\nيحملن ركبا مغرمين ، إذا سروا … رفعت لهم تحت الظلام عقائر\nنحلوا من البلوى نحول مطيهم … فضوامر من فوقهن ضوامر\nفأتتك لو كلفت ما كلفتها … نوب الزمان اتتك وهي زوافر\nلله صبرك حيث تفترق الظبى … بين الهوادي والقنا متشاجر\nواليوم اسود لمة من ليله … سترتك منه ذوائب وغدائر\nفي حيث سد على الطيور مجالها … حتى رعى ما في الوكور الطائر\nلثمت خد الشمس منه بأسود … والنور يشهد أن وجهك سافر\nيوم تود السمر ان صدورها … لتعد ما كسبت يداك ، خناصر\nوالسبي تعصف بالجيوب أكفها … في جنب ما عصفت قنا وبواتر\nفعلى النساء من الخروق يلامق … وعلى الرجال من النجيع مغافر\nولوا وايديهم على هاماتهم … فكانما تلك الاكف معاجر\nوبذلت أجساد الكماة لوحشة … فعلمن أنك أنت فيه الظافر\nانى تعرس فالرياض مطافل … لسوام إبلك ، والوحوش جآذر\nواذا تسالم فالسموم صوارد … واذا تحارب فالنسيم هواجر\nوكأن رمحك حالب لدم الطلى … وكأن سيفك في الجماجم جازر\nلو تعلم الافلاك انك والدي … لم ترض أني للسماء مصاهر\nوبحسب جودك أنني لك مادح … وبحسب مجدي أنني بك فاخر\nإن الذي حلته غر مدائحي … ندب كساه مفاخر ومآثر\nكثرت نعوت صفاته في مدحه … فكان مادحه المفوه سامر\nكفل البقاء بنفسه فلو انقضى … ذا الدهر عاوده الزمان الغابر\nواليوم كمن في صدره لك آمل … يعطى وكم في عجزه لك شاكر\nأمعثر الأحداث في أذيالها … ناجاك مدحي والجدود عواثر\nاني رضيتك في الزمان ممدحا … وعلاك لا ترضى بأني شاعر"},{"id":"diwan-radi:220","bookId":"diwan-radi","type":"poem","seq":220,"chapter":"البحر: متقارب تام","title":"من الظلم ان نتعاطى الخمارا","page":"","text":"من الظلم ان نتعاطى الخمارا … وقد سلبتنا الهموم العقارا\nوفينا شآبيب صرف الزمان … تروى مرارا وتظما مرارا\nتخيرني عفتي والغنى … ومن لي أني ملكت الخيارا\nولو أن لي رغبة في النوا … ل أجممته ، واجتديت البحارا\nوهون صولته انني … ارى العيش ثوب بلى مستعارا\nفما اركب الخطب الا جليلا … ولا أجذب الأمر إلا اقتسارا\nوكنت اذا ما استطال العدو … نثلت عليه القنا والشفارا\nوكم لي الى الدهر من حاجة … ابل بها ذابلا أو غرارا\nتجر إليها ذيول المنى … ويخلع فيها الزمان العذارا\nويوم تخرقت فيه السيوف … وخضت إليه الدماء الغزارا\nاثرت العجاج عليه دخانا … واضرمت من مائر الطعن نارا\nوعانقت من بيضه في النجيع … شقيقا ومن سمره جلنارا\nولية خوف شعار الفتى … يصافح بالسمع فيها السرارا\nأبحنا حماها أكف المطي … حتى انتهبنا الربى والجرارا\nوأرض مقنعة بالهجي … تنضو من الآل عنها خمارا\nهجمت على جوها بالرماح … تبني من الطل فيها منارا\nفما ارتعت من شعبات الحمام … ولا خفت فيه لأمر خطارا\nوفللت من جنبات الخطوب … بعزم اذا جار دهر اجارا\nومما يحلل ذم الزمان … ن إقصاؤه الماجدين الخيارا\nأسمعي ذؤابة هذا الأنام … دعاء يجر علي الجهارا\nثقا بالاله فان الزما … ن يعطي امانا ويمطي جذارا\nولا عجب أن يعير الثراء … فالمجد اكرم من ان يعارا\nاذا سالم الموت نفسيكما … فبعثر للذل فيه وجارا\nاصابتكما نكبة فانجلت … \nودهر يرد علينا العلاء … ء ، أجدر به أن يرد الغفارا\nألم تر يا من رمته الخطوب … يمينا تنازعه أو يسارا\nومن خوض الدهر من ماله … قوارح أحداثه والمهارى\nوما أكل الخطب من عزنا … وكنا له سلعا أو مرارا\nبنينا مصاد العلا مصمتا … \nعقدنا بباع الردى ذمة … فحل الذمام وفض الذمارا\nونحن نؤمل أن الزمان … يرد الذي من علانا استعارا\nونملك اعناق احداثه … فنلبسها مسحلا أو عذارا\nوتجلو غمايمها عنكما … هموما تظل القلوب الحرارا\nويعطيكما الله نفس الحسو … رقا مسلمة اواسارى\nويرجع شانيكما شاحبا … ينفض عن منكبيه الغبارا\nومن قمر الدهر امواله … قضى جده ان يرد القمارا\nوحسبك كيدا يميت العدو … أن يطلب الذل منك الفرارا\nلئن جلتما فيمكر الزمان … فبواكما من مداه العثارا\nفما يقرع الجهل إلا الحليم … ولا ينكث الخرق الا الوقارا\nتفرق مالكما في العدى … وشخصكما واحدلا يمارا\nولم ألق منفردا في الزمان … يسائل عن إلفه : أين سارا\nسأنتظر الدهر ما دام لي … بوعد وأسأر عندي انتظارا\nلحى الله دهرا كثير العدو … حتى الظلام يعادي النهارا\nتصفحت أوجه أبنائه … فلم يجد اللحظ فيهم قرارا\nرأيت الصباح يذم المسا … ء ذمي ، ويكره منه الجوارا\nويشحب فيه على أنه … يبدل في كل يوم صدارا\nفكونوا كما انا في النائبات … آبى مع القدح إلا استعارا\nفما غرني جوده بالثراء … وما زادني منه الا نفارا"},{"id":"diwan-radi:221","bookId":"diwan-radi","type":"poem","seq":221,"chapter":"البحر: وافر تام","title":"اما ذعرت بنا بقر الخدور","page":"","text":"اما ذعرت بنا بقر الخدور … وغزلان المنازل والقصور\nعشية ما التفتن على رقيب … ولا استحيين من نظر الغيور\nاما والله لو اطلقت شوقي … لفاض على الترائب والنحور\nاكنت معنفي لما التقينا … على وطر من الدمن الدثور\nنبل من الدموع على زفير … مراتع ذلك الظبي الغرير\nوقد أظما الهوى منا قلوبا … كرعن من الصبابة في غدير\nوللسير التدام في المطايا … وللبين احتدام في الصدور\nاحين جذبتم الاوطان عنا … بأعناق المخطمة النفور\nوجدن الشجو في نغم الأغاني … ونشو الشوق في نطف الخمور\nبواقينا تتيم بالمواضي … وزئرنا يتيه على المزور\nسقى الله البطاح وما تصدى … لنا بين الخورنق والسدير\nوآراما برامة ، كل غيث … تملس من سحائبه مطير\nففيها هزني أرج الخزامى … وأعداني على نار الهجير\nقبضت يد السحاب بفيض دمعي … وأسكت الحمايم بالزفير\nركبت اليك اعجاز الليالي … أخوض من المساء إلى البكور\nوفتيان تهزهم المذاكي … بأطراف الحمايل والسيور\nفجئتك راكبا صهوات دهر … كثير وقائع الجد العثور\nلحى الله امرأ ينضو حساما … فيجبن وهو ملآن الضمير\nاما في هذه الدنيا نجيب … يساعدني على حرب الدهور\nفنشرب آجن الغدران فيها … اذا ماالذل حام على النمير\nونلقى أشهب الأمواه ترمي … برغبتنا الى شبه البحور\nأبيت ، إذا المطامع أيقظتني … ألاحظهن عن طرف كسير\nواملأ مقلتي من العوالي … إذا امتلأت من العلق الغزير\nويعجبني اطيط الرحل ترمي … أزمته السهول إلى الوعور\nولا أرضى مصاحبة الهوينا … الى طرق المطالب والشقور\nويصحبني ذؤالة مستريبا … يبشخصي في الاماعز كالخفير\nلأني ما تحيفني زمان … فاحوجني الحسام الى نصير\nولا اقتضت الهواجر لثم خدي … فماطلها لثامي عن سفوري\nوكنت اذا توعدني قبيل … وربى الطعن في البيض الذكور\nرميتهم بمحتبل الأعادي … وقاطع حبوة الملك الخطير\nكأني لم أشق على الليالي … بحرب أو خصام أو مسير\nولا اضحكت سيفي في جهاد … يمزق عنه تعبيس الثغور\nعذيري من بلاد ليس تخلو … سوائي من مليك أو امير\nتضن وقد ضننت فما ارى … مثلمة الأشاعر والنسور\nاذا ادنيت رجلي من ثراها … فزعت بها الى قتد البعير\nارى تلك الصلوة بها حلالا … فما امتاحها ماء الطهور\nوكيف تتم في بلد صلاة … وجل بقاعه قبل الفجور\n … فأعرف من أرى غير النظير\nتغمض عن وجوههم الدراري … وتسحب فيهم غرر البدور\nعلت أصواتهم صوتي ، ولكن … صهيل الخيل يطرق للهرير\nمضوا الا بقايا سوف تمضي … وشر القوم شذ عن القبور\nومازالت جمام الماء تفنى … وتختم مدة الثمد الجرور\nونكس شاطرته من الليالي … يدعن شيمتي كرم وخير\nفأصبح لا يرى للمال عتقا … وتملك كفه رق البدور\n … مضاجع هامة القمر المنير\nصحبنا الدهر والايام بيض … ونحن نواضر سود الشعور\nفلما اسودت الدنيا برزنا … لها بيض الذوائب بالقتير\nتميل على مناكبنا الليالي … بألوان الغدائر والضفور\nونرسب في مصائبها ، ونطفو … لغير بني أبينا بالسرور\nاذا لحظت عزائمنا التقينا … الى مقل من الايام حور\nترينا في جباه الاسد ذلا … وفي حدق الأراقم كالفتور\nأقول لناقتي ، واليوم يملا … اناء البيد من ماء الحرور\nوقد سحبت ذوائبها ذكاء … على قمم الجنادل والصخور\n … كما قطن العذارى في الخدور\nتعاتبها المراتع في الفيافي … ويشكرها الكباث الى البرير\nإذا باب الحسين أضاف رحلي … اذم على المطي من المسير\nفثم الغيث معقود النواصي … وليث الغاب محلول الزئير\nأطال العشب من سرر الروابي … وحط الماء في قطع الصبير\nسماح في جوانبه أباء … كحسن الماء في السيف الشهير\nفتى يصلى بأطراف المواضي … ونار الحرب طائشة السعير\nويمشق بالعوالي في الهوادي … وطرس اليوم مختلط السطور\nيرد الشمس مطروفا سناها … وقد حجبت بأجنحة النسور\nهمام جر ارسان المعالي … إليه ، وطاس أطناب الأمور\nيشاور ، وهو أعلم بالقضايا … فيسبق رأيه قول المشير\nويفرغ صائبات الرأي فيها … كافراغ النبال من الجفير\nرمى بالنار في ثغر الدياجي … وادب شيمة الكلب العقور\nلمزؤود تقاذفه المطايا … ويسنده الى ظهر حسير\nعلى ظلماء قابضة إليه … بلحظ المجتلي ويد المشير\nتناعس نجمها عن كل سار … فيقظ بين راحلة وكور\nمتى القاك قائدها عرابا … \nتهادى كالعذارى حاليات … معاقد حزمها بدل الخصور\nفاسبح من دمائك في خلوق … وارفل من عجاجك في عبير\nاذا ركضت بساحتك الليالي … فلا زالت تقاعس في الشهور\nوإن طالت بها أيدي الأماني … فلا امتدت يد الوعد القصير\nولا زالت رماحك مطلقات … ترددها إلى الأجل الأسير"},{"id":"diwan-radi:222","bookId":"diwan-radi","type":"poem","seq":222,"chapter":"البحر: طويل","title":"بغير شفيع نال عفو المقادر","page":"","text":"بغير شفيع نال عفو المقادر … أخو الجد لا مستنصرا بالمعاذر\nواعجب فعلا من قعودي على العلى … سراي بأعقاب الجدود العواثر\nأؤمل ما أبقى الزمان ، وإنما … سوالفه معقودة بالغوابر\nفخل رقاب العيس يجذبها السرى … بامال قوم محصدات المرائر\nفما التذ طعم السير الا بمنية … وان الاماني نعم زاد المسافر\nودون مدارات المطي على الوحي … مشاغبة الاشجان دون الضمائر\nفليت قلوب العاشقين إذا ونى … بها السير كانت في صدور الاباعر\nولله قلبي ما ارق على الهوى … واصبى الى لثم الخدود النواضر\nيحن إلى ما تضمن الخمر والحلى … ويصدق عما في ضمان المآزر\nولما غدونا للوداع ونقرت … صروف النوى دون الخليط المجاور\nعنيت من القلب العفيف بعاذل … ومن خدع الشوق السفيه بعاذر\nعشية لاعراس الوفاء بمرمل … لدينا ، ولا أم الصفاء بعاقر\nومن لم ينل اطماعه من حبيبه … رضي غير راض بالخيال المزاور\nوكنت أذود الدمع إلا أقله … لسقيا حمى من بعد بينك داثر\nوإني لا أرضى ، إذا ما تحملت … إليه مرابيع السحاب المواطر\nكليني الى ليل كان نجومه … تغازل طرفي عن عيون الجآذر\nأمر بدار منك مشجوجة الثرى … بمجرى نسيم الآنسات الغرائر\nتمر عليها الريح ، وهي كأنها … تلفت في أعطاف تلك المقاصر\nويشهق فيها بالاصايل والضحى … حيا كل عراض الشآبيب ماطر\nويستن فيها البرق حتى تخاله … يفيض بفيض القطر في كل حاجر\nولما رأيت الليل مسترق الخطى … واطرافه تجلو وجوه التباشر\nارقت لاجفان الركائب هبة … بألحاظ جوال العزائم ساهر\nرسيما به يعتل بالاعين الكرى … وينشق عن مكنونه كل ناظر\nببهماء يستغوي الحداة سرابها … على ظمإ بين الجوانح ثائر\nويحبو بها الاعياس حتى كانها … تنص على أخفافها بالكراكر\nومولى ادانيه على السخط والرضى … ويبعط عني والقنا في الحناجر\nيهز علي السوط والرمح دونه … وهز العوالي غير هز المخاصر\nعطفت له صدر الاصم وتحته … عواطف أسباب الحقود النوافر\nفخر وفيه للطعان مناظر … يطالعها طير الفلا بالمناسر\nفما ظفرت من نفسه أم قشعم … بما ظفرت من جسمه ام عامر\nوركب تفادى النوم أن يستخفه … اذا ما الكرى القى يدا في المحاجر\nوردت به بحبوحة الورد فانثنى … يقلص صافي مائه في المشافر\nوغادر احشاء الغدير ضوامرا … من الماء في ظميء النواحي الضوامر\nورود خفيف الورد اول وارد … طروقا الى ماء واول صادر\nاذا هز اطراف الخليج رمت به ال … موارد خفا في وجوه المصادر\nوكان إذا ما عاقه بعد مطلب … يضعضع أعضاد المطي الزوافر\nتمرس بالأيام حتى ألفنه … وكر على احداثها والدوائر\nواخطأ سهم القطر مقتل محله … فزم قسي العاديات الهوامر\nفتى حين اكدت ارضه هجمت به … على لابن من آل عدنان تامر\nعلى ماجد لا يسرح اللؤم عنده … ولا تدرى أفعاله بالمناكر\nاذا راوح الرعيان ليلا سوامه … فقد لفها جنح الظلام بعاقر\nتفرعت حتى عودتني رماحه … فعودت من سوء الظنون سرائري\nتشابه ايامي به فكأنما … أوائلها ممزوجة بالأواخر\nهو الواهب الألف التي لو تسومها … قبيلا ، فداها بالجديل وداعر\nيطول إذا مد الرديني باعه … وعانق اعناق الرجال المساعر\nفيفري طريقا للسبار كانما … لها ذمة في الطعن ، رسل المسابر\nتعلق في ثني العرين بعزمة … تذلل امطاء الليوث الخوادر\nفطردها حتى استباح شبولها … وما ضعضعته اسدها بالزماجر\nيخف اليه الجيش حتى كأنه … يمد باعناق النعام النوافر\nجزى الله عنه الخيل ما تستحقه … اذا رقصت بالدراعين المغاور\nوخبت على بيداء تشرق ماءها … عن الركب في طي العيون الغوائر\nتمر على المعزاء خفاقة الحصى … وتحثو بوجه الشمس ترب القراقر\nوتسترعف الآفاق لمع صفائها … بمغبرة تمحو سطور الهواجر\nحمى بيضة الاسلام بالحق فاحتمت … وقرت بأعشاش الرماح الشواجر\nومن قبل ما كانت تقلقل خيفة … وترقب في الايام وهصة كاسر\nإذا عبقت أخلاقه أرج العلى … تضوع في الحيين كعب وعامر\nولما انجلت من جوزة الشرك فرصة … تقنصها والدين دامي الأظافر\nتداركها والرمح يركب رأسه … فيرعف من قطر الدماء القواطر\nبطعن كولغ الذئب ان زعزع القنا … سقاها شآبيب الدماء الموائر\nافاض على عدنان فضل وقاره … وقد مسها طيش السهام الغوائر\nفبوأ أوفاهم يدا قلة العلى … ومد بأضباع الرجال البحاتر\nاذا جنبوه للرهان اتوا به … جوادا يفدى شاؤه باليعافر\nيغطي على اوضاحها بغباره … ويخرج سهلا من جنوب الاواعر\nاذا ذكروه للخلافة لم تزل … تطلع من شوق رقاب المنابر\nلعل زمانا يرتفي درجاتها … باروع من آل النبي عراعر\nومن لي بيوم أبطحي سروره … يجول ما بين الصفا والمشاعر\nفها ان طوق الملك في عنق ماجد … وإن حسام الحق في كف شاهر\nويا رب قوم ما استعاضوا لذلة … شهيق العوالي من حنين المزامر\nكؤوسهم أسيافهم وخضابها … إذا جردوها من دماء المعاصر\nرضوا بخيال المجد والشخص عنده … وما قيمة الأعراض عند الجواهر\nهم تبعوه مقصرين ، وربما … توسدت الأظلاف وقع الحوافر\nإذا عددوا المجدالتليد تنحلوا … على تتبرى من عقود الخناصر\nحريون إلا أن تهز رماحهم … ضنينون الا بالعلى والمفاخر\nهم انتحلوا إرث النبي محمد … ودبوا الى اولاده بالفواقر\nوما زالت الشحناء بين ضلوعهم … تربي الاماني في حجور الاعاصر\nإلى أن ثنوها دعوة أموية … زوتها عن الاظهار ايدي المقادر\nولو أن من آل النبي مقيمها … لعاجوا عليه بالعهود الغوادر\nفما هرقوا في جمعها ري عامل … ولا قطعوا في عقدها شبع طائر\nوقد ملأوا منها الأكف ، وأهلها … فما ملئوا منها لحاظ النواظر\nفراشوا لهم نبل العداوة بعدما … بروها وكانت قبل غير طوائر\nشهدت لقد أدى الخلافة سيفه … إلى جانب من عقوة الدين عامر\nيفرق ما بين الكؤوس وشربها … ويجمع ما بين الطلى والبواتر\nفيرفع صدر السيف ان حط كاسه … ويمري دماء الهام ان لم يعاقر\nوينهض مشتاقا إلى مصرخ القنا … فيسحب بردي فاسق السيف مع\nظم حي ما رمته هجيرة … فقعقع في اعراضها بالهواجر\nولما طغت غيلان في عشق غيها … رماها من الكيد الوحي بساحر\nرماهم من الرمح الطويل بحالب … ومن شفرة العضب الحسام بجازر\nواضرم نارا فاسترابوا بضؤها … وما هي إلا للضيوف السوائر\nفلما تراخت في الضلال ظنونهم … تراخى فطارت ناره في العشائر\nولما اروه نفرة العار خافها … ولو نفرت أرماحهم لم تحاذر\nفارسلها شعواء تقدح نارها … على جنبات الأمعز المتزاور\nشماطيط يجرون الحديد كانها … مشين على موج من اليم زاخر\nعليها من البيض العوارض فتية … خضاب قناها من دماء المناحر\nمفارق لا يعلو عليها مطاول … غداة وغى ، إلا قباب المغافر\nفجاؤوك والخيل العتاق طلائح … تضاءل من عبء الرماح العواثر\nوما حركوها للطعان ، كأنما … زجاج قناها علقت بالاشاعر\nوجارت سهام الموت فيها وانما … دليل المنايا في السهام الجوائر\nوطأتهم بالاحقيات وطئة … تذلل خد الجانب المتصاغر\nفازعجت دارا منهم مطمئنة … واخليتها من كل عاف وسامر\nشننت بها الغارات حتى ترابها … يثور على العادات من غير حافر\nوكل فتاة من نزار تركتها … تريع إلى ظل الربوع الدوائر\nتحشش في أذيالها مستكينة … وتحطب ذلا في حبال الغدائر\nوكل غلام منهم شام سيفه … رأى فيه وجه الحق طلق المناظر\nولما امتطى ظهرا من الغي كاسيا … تندم أن أعرى ظهور البصائر\nجفته العلى فانسل من عقداتها … وما علقت اعطافه بالمآثر\nولو لم تمسح بالأمان رؤوسهم … بما انست هاماتهم بالغفائر\nتفرت قلوب القوم حتى تهتكت … بما استترت فيه بنات السرائر\nأبا أحمد ثق بالمعالي ، فإنها … اذا لم ترع بالبخل غير غوادر\nفما مالك المدخور الا لطالب … ولا ربعك المعمور الا لزائر\nولا تطلبا ثار الرماح ، وإنما … دماء المعالي في رقاب الجرائر\nجلوت القذى عن مقلتي فباشرت … صنيعك أجفاني بألحاظ شاكر\nفان هز يوما فرع ملكك حاسد … فان المعالي محكمات الاواصر\nهو العود سهل للسماح جناته … ولكن على الاعداء وعر المكاسر\nاذم على الايام من كل حادث … وحاط جناب الدين من كل ذاعر\nوضم شفاه الوحش حتى ظننته … سيصدى صقالا في نيوب القساور\nوما زال يسمو بالمعالي كانها … تجر إليه بالنجوم الزواهر\nله سابقات القبل في كل أول … مضى ، وبقاء البعد في كل آخر\nترفع في العلياء عن وصف مادح … ورفعت عن مدح الملوك خواطري\nفما هو لولا ما اقول بسامع … ولا أنا لولا ما يمن بشاعر"},{"id":"diwan-radi:223","bookId":"diwan-radi","type":"poem","seq":223,"chapter":"البحر: بسيط تام","title":"شيمي لحاظك عنا ظبية الخمر","page":"","text":"شيمي لحاظك عنا ظبية الخمر … ليس الصبا اليوم من شأني ولا وطري\nمات الغرام فما اصغى إلى طرب … ولا أربي دموع العين للسهر\nمن يعشق العز لا يعنو لغانية … في روتق الصفو ما يغني عن الكدر\nشغلت بالمجد عما يستلذ به … وقائم الليل لا يلوي على السمر\nطويت حبل زمان كنت انديه … إذا جذبت به باعا من العمر\nلا يبعد الله من غارت ركائبهم … وأنجد الشوق بين القلب والبصر\nيا وقفة بوراء الليل اعهدها … كانت نتيجة صبر عاقر الوطر\nوالوجد يغصبني قلبا أضن به … والدمع يمنع عيني لذة النظر\nطرقتهم والمطايا يستراب بها … والليل يرمقني بالأنجم الزهر\nاصانع الكلب ان يبدي عقيرته … والحي مني ، إذا أغفوا على غرر\nوفي الخباء الذي هام الفؤاد به … نجلاء من اعين الغزلان والبقر\nابرزتها فتحاضرنا مباعدة … عن الخيام نعفي الخطو بالازر\nثم انثنيت ولم ادنس سوى عبق … على جنوبي لريا بردها العطر\nلا أغفل المزن أرضا يعقلون بها … ولاطوى عنهم مستعذب المطر\nجر النسيم على أعطاف دارهم … ذيلا ، وألبسها من رقة السحر\nوما بكائي على إلف فجعت به … الا لكل فتى كالصارم الذكر\nما حاربوا الدهر إلا لان جانبه … إن المشيع أولى الناس بالظفر\nيا للرجال دعاء لا يشار به … الا إلى غرض بالذل والحذر\nردوا الرحيل فان القلب مرتحل … وسافروا إن دمع العين في سفر\nويوم ضجت ثنايا بابل ومشت … بالخيل في خلع الاوضاح والغرر\nقمنا نجلي وراء اللثم كل فتى … كأن حليته في صفحة القمر\nإني لأمنح قوما لا أزورهم … مج القنا من دم الأوداج والثغر\nطعنا كما صبح الغدران ممتحن … رمى فشتت شمل الماء بالحجر\nوجاهل نال من عرضي بلا سبب … أمسكت عنه بلا عي ولا حصر\nحمته عني المخازي ان اعاقبه … كذاك تحمى لحوم الذود بالدبر\nومهمته كشفار البيض مطرد … بالآل ، عار من الأعلام والخمر\nإذا تدلت عليه الشمس أوحشها … تولع المور بالانهار والغدر\nغصصت تربته بالعيس مالكة … على النجاء رقاب الورد والصدر\nاطوي البلاد إلى ما لا اذل به … من البلاد ، وما أطوي على خطر\nمجاهلا ما أظن الذئب يعرفها … ولا مشى قائف فيها على أثر\nينسى بها اليقظ المقدام حاجته … ويصبح المرء فيها ميت الخبر\nلا تبعدن أماني التي نشزت … على الزمان بايدي الا ينق الصعر\nاليك لولاك ما لج البعاد بها … ترى المنازل بالادلاج والبكر\nيا ابن النبي مقالا لا خفاء به … وأحسن القول فينا قول مختصر\nرأيت كفك مأوى كل مكرمة … إذا تواصت أكف القوم بالعسر\nلطاب فرعك ، واهتزت أراكته … في المجد ، إن المعالي أطيب الشجر\nما كل نسل الفتى تزكو مغارسه … قد يفجع العود بالاوراق والثمر\nإن الرماح ، وإن طالت ذوائبها … من العدى تتواصى عنك بالقصر\nتسل منك الليالي سيف ملحمة … يستنهض الموت بين البيض والسمر\nمشيع الرأي إن كرت أسنته … جر القنا بين منآد ومنأطر\nفاسلم اذا نكب المركوب راكبه … واستأسد الدهر بالاقدار والغير"},{"id":"diwan-radi:224","bookId":"diwan-radi","type":"poem","seq":224,"chapter":"البحر: بسيط تام","title":"لك السوابق والأوضاح والغرر","page":"","text":"لك السوابق والأوضاح والغرر … وناظر ما انطوى عن لحظه اثر\nوعاطفات من البقيا ، إذا جعلت … محقرات من الاضغان تبثدر\nإطراقة كقبوع الصل يتبعها … عزم يسور فلا يبقي ولا يذر\nوالليث لا ترهب الاقران طلعته … حتى يصمم منه الناب والظفر\nانت المؤدب اخلاق السحاب اذا … ضنت بدرتها العراصة الهمر\nمن بعد ما اصطفقت فيها صواعقها … وشاغب البرق في أطرافها المطر\nوالبالغ الأمر جالت دون مبلغه … سمر القنا وامرت دونه المرر\nوالقازف النفس في حمراء ان خفيت … بالنقع نم على ضوضائها الشرر\nفي جحفل لم تزل يهدي اوائله … مطالع من نجاد الارض منتظر\nان نال منك زمان في تصرفه … ملا لا يملكه من غيرك القدر\nفالبيض تعلق إن سارت مهجرة … من الشحوب بما لا تعلق السمر\nما ناهض الرحلة الخرقاء معتقلا … بالحزم من فل من آرائه السفر\nفاسلب مراح المطايا من مناسمها … مزامل النجم والاظلام معتكر\nوجب بين فروج الليل أسنمة … ما استاف اخفافها اين ولا ضجر\nخرس البغام ترد الصوت كاظمة … وقد تصاعد من اعناقها الجرر\nكم حاجة بمكان النجم قربها … طول التعرض والروحات والبكر\nأسال في الليل إفرند الصباح بنا … سير تساقد من ادمانه الازر\nومشهد مثل حد السيف منصلت … تزل عن غربة الالباب والفكر\nطعنت بالحجة الغراء ثغرته … ورمح غيرك فيه العي والحصر\nوقسطل شرقت شمس النهار به … فاسفر النقع والآفاق تعتجر\nتسلطت فيه اطراف الظبي ودنت … عوامل السمر فارتابت بها الثغر\nفوقت فيه سهاما غير طائشة … في حيث يرمح صدر المعجس الوتر\nفما استخفك من حمل النهى خرق … ولا استكفك عن طعن العدى خفر\nوما نظرت الى الايام معتبرا … إلا وأعطاك كنز العبرة النظر\nونعم قادح زند انت في ظلم … لا يوقد النار فيها المرخ والعشر\nبذكر جودك يستسقى المحول إذا … لم يله فيها نساء الحلة السمر\nلما جريت جرت خيل سواسية … ولت وخاف على أنفاسها البهر\nان البهيم اذا مسحت جبهته … فالحكم أن تلطم الأوضاح والغرر\nقارعت دهرك حتى لاح مقتله … ما استقبح الروع حتى استحسن الظفر\nالان نعم مقيل التاج لمته … ونعم مغنى العلى أيامه الزهر\nتطيش أمواله والبذل يطلبها … ما وفر المال عن اعراضه وقر\nمشيع هذب الأرماح مذ فطنت … الى طعان الاعادي والردى غمر\nيسري من الكيد جيشا لا غبار له … ولا طلائع تهديه ولا نذر\nكم بات في لهوات الليل تعركه … ما بين اكوارها المهرية الصعر\nوالخيل تقدح من ارساغها شررا … أمسى يعثن منه الترب والمدر\nرد السيوف فمغلول ومنثلم … على الرماح ومنآد ومنأطر\nاذا اشاح بنصل في انامله … قامت تعانقه الهامات والقصر\nنصل تمطى المنايا في مضاربه … إذا المعزر أثنى نصله الخور\nعار ، يصافح أعناق الرجال به … يوم النزال ، وما في باعه قصر\nإذا الوفود دعت للضرب شفرته … أطاع فاحتشمت من ضيقه العكر\nسئلت عن وجهه الظلماء مقمرة … عنه ، وهل يتمارى أنه القمر\nنفسي فداء اخ لم يقذ صحبته … اذ كل صافية في مائها كدر\nما حان منا لغير العز مضطرب … ولا اطبانا الى غير العلى وطر\nأأعذر الدهر إذ جارت حكومته … إذا ففسق عذري حين أعتذر\nعند ابن خير أب حامت أنامله … على القنا ومشت في كفه البتر\nورب قول مريض قد سهرت له … افضى الي به عن لفظك الخبر\nمالي تسفه اشعاري الذي شهدت … اني ببعض فخار منك افتخر\nيا ابن الذين تبارى في ندائهم … أصواتنا ، إن عرت أوطاننا الغير\nاذا كررنا حديثا منهم اعترضت … تجلو قديمهم الآيات والسور\nوكم عدو ، إذا شاغبت دولته … يزور عن طاعتيه السمع والبصر\nقد كان ملكك خلف العز يرضعه … حتى عصاك فخانت رشفه الدرر\nكم حاطب خانه حبل ، فأقعصه … ذلا ، وشر الحبال الحية الذكر\nومجلس ما أظن الهم يعرفه … \n … تراكضت في حواشي روضه الغدر\nماء كجيد الفتاة الرود قابضة … من الحلي على اثنائه الزهر\nضمخت بالراح اثواب الكؤوس كما … فض النسيم على اعطافه السحر\nمتيم بالعلى والمجد يألفه … وما مشى في نواحي خده الشعر\n … والماء يخبرنا عن ورده الصدر\n … اعدى على الشهد فيه الصاب والصبر\nحياك بالعذر في عذراء قد خرقت … عنها الحجاب وما اقتضت لها عذر\n … ومع قبولك لا يغلو لها مهر"},{"id":"diwan-radi:225","bookId":"diwan-radi","type":"poem","seq":225,"chapter":"البحر: متقارب تام","title":"لبست الوغى قبل ثوب الغبار","page":"","text":"لبست الوغى قبل ثوب الغبار … وقارعت بالنصل قبل الغرار\nواسد اذا شعرت بالحمام … رأت عيشها خلف ذاك الشعار\nطوال الخدود قصار الحقود … رواء الشفاء ظماء المهار\nومنتجعين ديار العدو … في كل مصطرم ذي اوار\nبسمر مثقفة للطعان … وجرد مسومة للغوار\nويوم ختمنا عليه الردى … وقد فض عنه ختام الذمار\nتصيد قلوب الأعادي به … صدور القنا وهي هيم ضوار\nاذا ستر النقع اثارها … هتكن الضمائر عن كل ثار\nقلوبهم بذيول الحمام … وقع اطرافها في عثار\nوتجهر بالموت أرواحهم … وسمر القنا معها في سرار\nوقد وردوا بصدور الرماح … كما صدروا بصدور الشفار\nكسونا قنانا ثياب الدما … ونحن من العار فيها عوار\nلقد كنت اسحب برد الشماس … لا يرفع العذل مرخى ازاري\nفأصبحت قبل نزول العذار … معترفا ، صابرا للعذار\nألا رب صب بحب العلى … وليد المطايا رضيع السفار\nبعيد المعالي ، قريب العوالي … صديق الأيادي ، عدو النضار\n … غرار التصابي بايدي العقار\nيمزق بالعيس جيب الدجى … ويهتك بالخيل صدر النهار\nإذا غاض ماء الندى أسبلت … يداه بماء من الجود جار\nإذا ما رعت في ربى جوده … هزال الاماني غدت كالشبار\nوكم نديت من نداه المنى … ندا سمره بالنجيع الممار\nومن كن يهوين خلف الرجاء … فأمسين من جوده في قرار\nكما قد قلبك يا ابن الحسين … من شوقه وعيون الفخار\nبمولد غراء اعطيتها … بدو الاهلة بعد السرار\nأغارت على الحسن أسبابها … فاسبابه عندها في اسار\nولا عجب أن ترى مثلها … وزندك في كرم العرق وارى\nنثرن عليها سواد القلوب … وكان الهنا في خلال النثار\nولو أنصف الدهر لم نقتنع … بغير قلوب النجوم الدراري\nهناك بها الله ما غردت … صدور القنا في اعالي نزار\nواحيا بها لك ميت العلى … وأردى بها كل عاب وعار\nوذلت عمائم قوم بها … كما أنها شرف للخمار\nفحسبك فخر بهذا المديح … وان غاض في المدح ماء افتخاري\nيزورك بين قلوب العداة … فيقطعها في اتصال المزار\nغدت كف مجدك من مدحتي … تجول معاصمها في سوار"},{"id":"diwan-radi:226","bookId":"diwan-radi","type":"poem","seq":226,"chapter":"البحر: كامل تام","title":"جربت آل الغوث ثم تركتهم","page":"","text":"جربت آل الغوث ثم تركتهم … متخيرا والجار قبل الدار\nالسابقين الى مناخ مطيتي … لما تدافعت العريب جواري\nوالضاربين علي بيت زمامة … خسأ العدو فما يطيق ضراري\nأعظمتم حسبي ، ولما تحفلوا … مارث من سلبي ولا اطماري\nوعرفتموا مني مخيلة سؤدد … خفيت وراء ملابس الاقتار\nكيف اعترافي للزمان وريبه … فعل الذليل ، وأنتم أنصاري\nأجممتم في الصبح راعي هجمتي … وكفيتم بالليل موقد ناري"},{"id":"diwan-radi:227","bookId":"diwan-radi","type":"poem","seq":227,"chapter":"البحر: طويل","title":"عقيد العلى لا زلت تستعبد العلى","page":"","text":"عقيد العلى لا زلت تستعبد العلى … وتعتق منها رق كل اسير\nلئن خف من ضافي ردائك عاتقي … فودك يخطو في رداء قتيري\nستعلم ان الثوب يدثر رسمه … ورسم الهوى في القلب غير دثور\nفلا تشمتن الحاسدين فسرهم … يشف لظني من وراء أمور"},{"id":"diwan-radi:228","bookId":"diwan-radi","type":"poem","seq":228,"chapter":"البحر: متقارب تام","title":"لاي صنائعه اشكر","page":"","text":"لاي صنائعه اشكر … وفي اي اخلاقه انظر\nفتى طانب المجد في بيته … هو السيف والعارض الممطر\nفتى ، كالحسام وصوب الغمام … ذا يستهل وذا يمطر\nاذا ازدحمت فيه الحاظنا … وقد ضم اعطافه المحضر\nترى ان جلبابه لامة … من البأس أو تاجه مغفر\nواجريت شكري الى شاؤه … فجاء ، وأنفاسه تزفر"},{"id":"diwan-radi:229","bookId":"diwan-radi","type":"poem","seq":229,"chapter":"البحر: طويل","title":"سانزل حاجاتي اذا طال حبسها","page":"","text":"سانزل حاجاتي اذا طال حبسها … بأبواب نوام عن الحمد والأجر\nباروع مصبوب على قالب الحيا … وابيض مطبوع على سكة البدر"},{"id":"diwan-radi:230","bookId":"diwan-radi","type":"poem","seq":230,"chapter":"البحر: كامل تام","title":"يا حبذا فوق الكثيب الاعفر","page":"","text":"يا حبذا فوق الكثيب الاعفر … ركز الذوابل في ظلال الضمر\nومناخ كل مطية معقولة … ومجال كل مناقل متمطر\nوتطرح الركب الطلاح على النقا … يهفون بين مزمل ومعفر\nرفعت لعين الناظر المتنور … والليل مثل الواقف المتحير\nنار كأطراف البزوق تشبها … بمطالع البيداء ايدي معشر\nكم نفرت من شجو قلب نافر … واستمطرت من دمع عين ممطر\nلله اية ساعة حضر الاسى … فيها فغيب في القلوب الحضر\nأجنت بها غدر الوفاء فلم تغض … والغدر طامي الماء غير مكدر\nوفوارس ركبوا النجاء ، وأدلجوا … من موغل خلف المنى ومغرر\nمروا يجرون الرماح لغارة … والطالعات عن الدجى لم تجرر\nفكأنما الجرباء لمة احلس … ولها المجرة مفرق لم يستر\nافشي حنين ركابهم سر السرى … لغبا فاضمر في نزائع ضمر\nنحروا بها نحر الفلاة ، وقلبوا … قلب الظلام على ذميل مسعر\nوالعيس تلطم خد كل مفازة … وتريق ما ابقى المزاد وتمتري\nولرب منذلق تمنطق سيفه … بنجيع كل ممنطق ومسور\nومسود بالغدر وجه وفائه … عصفرته بشبا الوشيج الاسمر\nفشفيت غل النفس من حوبائه … نهلا يعل من الدم المتمنجر\nخلع الحياة جناته وصوارمي … خلعت عليه يلمقا لم يزرر\nولقد رميت ضميره من خشيتي … باحد من طرف السنان واعقر\nولرب روع رعته بفوارس … قلبوا صدور رماحهم للأظهر\nفكدرت تحت النقع ، من جبهاتهم … مثل النجوم على العجاج الأكدر\nوهم الألى ربت لهم أحسابهم … ولد المعالي في حجور الأعصر\nمن كل أبلج مذ تلثم وجهه … بالنفع في طلب العلى لم يسفر\nما زال يخطر في غمامة قسطل … بين العوالي ، أو قميص سنور\nلا يتقي الشمس ، الظهائر ، إن سرى … إلا بظل قنا وعارض عثير\nفي معرك سحب العجاج ذوائبا … سودا به ، فوق النجيع الأحمر\nافل السنان عن الطعان كأنه … فكأن كل حشى ربابة ميسر\nعثرت بارياش القشاعم شمسه … والطعن في هبواته لم يعثر\nنثرت على بيض الكماة دراها … فنثرن ضربا ، وهي لم تتنثر\nلم تشعر الهامات عند نثارها … بقرارها فكأنها لم تنثر\nيجرون وهي مقيمة لكنها … خطارة من مغفر في مغفر\nمن مبلغ عني القبائل انني … متوطن عنق العلاء بمفخر\nاشرعت ضم الجود مشرع تالدي … فامتاحهم ، وطلاحهم لم تصدر\nجاءت كما جاء الشهاب مضيئة … تجلو الاسى عن قلب كل مفكر\nمن خاطر خطرت به همم العلى … والشعر بعد بقلبه لم يخطر\nنائي الخنا ، داني النهى ، صافي السدى … ضافي العطايا ، والعلى والمفخر"},{"id":"diwan-radi:231","bookId":"diwan-radi","type":"poem","seq":231,"chapter":"البحر: وافر تام","title":"أما لو لم تعاقره العقار","page":"","text":"أما لو لم تعاقره العقار … عقار الشوق مازجه الوقار\nوقفنا نغصب الأجفان ماء … له من نار أضلعنا انتصار\nفكم من نشوة للشوق تهفو … بصبر مسه منها خمار\nسقى دور السحاب صدى ربوع … بما يظمى اليهن المزار\nوجاذبها فضول المحل عنها … بأيمان من الخصب القطار\nليالي يوقظ التذكار شوقي … وهجعة سلوتي فيها غرار\nألا إن الزمان قضى علينا … باحداث لنا فيها اعتبار\nاذا ما الخطب ضللنا دجاه … انارت من تحاربنا منار\nنصد عن الحيا ، والجو ماء … ونستلم الثرى ، والأرض نار\nسرينا في ضمير البيد حتى … تركناها ، ونحن لها شعار\nأيا للمجد من قوم لئام … ألا حر على عرض يغار\nفاشجعهم اذا فزعوا جبان … واذكاهم اذا نطقوا حمار\nلبونكم تدر لأبعديكم … وعندي الذين منها والنفار\nلغيري ضوء ناركم وعندي … دواخنها السواطع والاوار\nوجرد قد لبسن ثياب ليل … ضوامر في اياطلها اقورار\nبركب ترعد الظلماء منهم … فيسترها من الجزع النهار\nيهلل نسج ثوب من عجاج … تشف وراء طرته الشفار\nسترن الجو بالقسطال حتى … كأن البدر أضمره السرار\nويوم سلطت فيه العوالي … على الارواح واخترم الذمار\nنعانق فيه ابكار المنايا … وهن لغير انفسنا ظوار\nوقد حجز العجاج ، فلا نجاء … وقد ضاق المجلل فلا قرار\nوملنا بالجياد على وجاها … وقد دمي الشكائم والعذار\nوقد وسمت حوافرها كؤوسا … ومن علق الدماء لها عقار\nواجرى الضرب في الاحشاء غدرا … تبرض مائها الاسل الحرار\nضربن لنا النسور رواق ظل … تلوذ بحقوة القب المهار\nتحل الهام فيه بالمواضي … وفي الاعناق حبل ردى مغار\nتخوض ترائكا منها لجينا … وتصدر وهي من علق نضار\nبضرب ينثر الشفرات ، حتى … لها في كل جانحة غرار\nبكل فتى يزل العار عنه … إذا ما هز ضبعيه الفخار\nحسام لا يضب عليه غمد … وليث لا يطل عليه زار\nتألف حد صارمه المنايا … وفيها عن حشاشته ازورار\nيجرد معصما من صدر رمح … ويرجع ، والفؤاد له سوار\nوسمر الخط تعثر بالهوادي … فيجذبها الى المهج العثار\nوكم من طعنة في رحب صدر … يجوز بها الى القلب الصدار\nفلولا أنها فهقت نجيعا … تخرقها لوسعتها الغبار\nوقد جثم الردى في كل سهم … له في كل حيزوم مطار\nاذا اختارت بنو قيس نزالي … رجعت وللردى فيها الخيار\nبرمح طرفه يزداد لحظا … إذا ما غض منه دم ممار\nصموت بين أطراف العوالي … وفي طعن القلوب له خوار\nاذا سالت عواليه بحتف … فليس لها سوى قبلب قرار\nيصد حسامهم عن ماء قلبي … واعلم ان غربيه حرار\nوينكص رمحهم في الطعن حتى … كأن كعوبه عني قصار\nعقاب النصر تحتهم مهيض … ونسر الموت فوقهم مطار\nلقد أضحكت عني آل فهر … بارماح بكت فيها نزار\nهم شهب ، إذا اتقدوا لحرب … فخرصان الرماح لها شرار\nاذا وقفت قناهم عن طعان … فليس لها سوى الموت انتظار\nإذا اطردت أكفهم بجود … اسرت مائها السحب الغزار\nبهم ألف الضرائب حد سيفي … وشجعني على الطلب الخطار"},{"id":"diwan-radi:232","bookId":"diwan-radi","type":"poem","seq":232,"chapter":"البحر: رجز تام","title":"قد زيلت عظيمة ، فشمري","page":"","text":"قد زيلت عظيمة ، فشمري … وارضي بما جر القضاء واصبري\nيا نفس قد عن المراد ، فخذي … إن كنت يوما تأخذين أو ذري\nنهزة مجد كنت في طلابها … لمثلها ينصف ساقي مئزري\nعشرون اعجزن الصبا وجزن بي … غاياته وما قضين وطري\nفكيف بالعيش الرطيب بعدما … حط المشيب رحله في شعري\nسواد رأس ام سواد ناظر … فانه مذ زال اقذى بصري\nما كان اضوى ذلك الليل على … سواد عطفيه ولما يقمر\nعمر الفتى شبابه وانما … آونة الشيب انقضاء العمر\nالا صديق في الزمان ماجد … اشكو اليه عجزي ويجري\nبعتق من رق الهوان عاتقا … عج من الضيم عجيج الموقر\nحسبي من رعي الهشيم المجتوى … حسبي من ورد الاجاج الكدر\nفما ارى الا سواما هملا … او صورا مذمومة مالصور\nما انا الا النصل مغمودا ولو … جردني الروع لبان جوهري\nلا بد أن يظهر معروفي فقد … طال على مر الزمان منكري\nلا بد أن أصدر بعد موردي … فرب قوم يرقبون صدري\nلا بد أن أشعر وجهي جرأة … حواملا إلى العدى خطية\nلا بد أن أحمل أبناء الوغى … على خفاف في الطراد ضمر\nيطلع للناظر هادي نقعها … طلوع قيدوم السحاب الاغبر\nحواملا الى العدجى خطية … تعير طرف البطل المقطر\nمن كل أظمى ناهل سنانه … او حسن الاثر قبيح الاثر\nينطحن بالأقران بين معلم … بالدم ، أو معلم بالعثير\nكل جري القلب في مقتحم … للروع ، مغرور به مغرر\nعمائم من التريك وضح … على جلابيب من السنور\nكأنما فوق قطا جيادها … أسود خفان وجن عبقر\nمن كل ممشوق يجاري ظله … كالطائر الزائف في التمطر\nمروع من حوله وكأنه … صال يقي البرد نوازي الشرر\nدونك فانظرني ، فإن جهلتني … فربما دل علي منظري\nكيف وقد طابت أصول دوحتي … تمر للجانين يوما ثمري\nأوائلي من قد علمت في العلى … ومعشري على القديم معشري\nذوائب المجد المنيفات على … جماجم منيفة في مضر\nذوو البطاح الفيح والبيت الذي … يعلو الورى والعدد المجمهر\nكل عذيق في العلى مرجب … عزا وعود في العلى مجرجر\nكم يوم مجد ظاهر فخاره … عنهم ظهور الابلق المشهر\nيا قدمي دونك مسعاة العلى … قد ضمن الاقبال ان لا تعثري\nليكثرن خطوك ، أو تنتعلي … سرير ملك ، أو مراقي منبر\nلابد من يوم اعز نصره … يقر عينم الواجد المستعبر\nفان نصرت فالنعيم مدة … والمضجع العاذر إن لم تنصري\nكم مطلب منتظر خدمته … ومطلب جاء ولم أنتظر\nعلة مثل السيف لا ممرضة … أضج منها كضجيج الأدبر\nلابد من تعفيره في تربها … بالداء ، أو بالقاطع المذكر\nفبالسقام ذلة لمن قضى … وبالظبي اعز للمغفر\nفان امت من دونها يمضى الردى … بمعذر في السعي لا بمعذر\nوان اعش هنيهة فربما … شق على اذن العدو خبري"},{"id":"diwan-radi:233","bookId":"diwan-radi","type":"poem","seq":233,"chapter":"البحر: كامل تام","title":"ولقد شهدت الخيل دامية","page":"","text":"ولقد شهدت الخيل دامية … تختال في أعطافها السمر\nفي ظلمة من ليل غيهبها … ما ان لها إلى الردى فجر\nفكأن مج دم النحور بها … إثر الطعان مقاود حمر"},{"id":"diwan-radi:234","bookId":"diwan-radi","type":"poem","seq":234,"chapter":"البحر: كامل تام","title":"ما عند عينك في الخيال الزائر","page":"","text":"ما عند عينك في الخيال الزائر … أطروق زور أم طماعة خاطر\nبات الكرى عندي يزور زورة … من قاطع نايء الديار مهاجر\nأحذاك حر الوجد غير مساهم … وسقاك كأس الهم غير معاقر\nإن الظعائن يوم جو سويقة … عاودن قلبي عند يوم الحاجر\nسارت بهم ذلل الركاب فلا روى … للظاميات ولا لعا للعاثر\nكم في سراها من سروب مدامع … تقفو سروب ربارب وجآذر\nحلبت ذخائرها المدامع بعدكم … في أربع قبل العقيق دواثر\nيبكين حيا خف غير مقايض … بهوى وحيا قر غير مزاور\nلو تحفلون بزفرة من واجد … او تسمعون لانة من ذاكر\nلا تحسبوا اني اقمت فانما … قلب المقيم زميل ذاك السائر\nقالوا : المشيب ! فعم صباحا بالنهى … واعقر مراحك للطروق الزائر\nلو دام لي ود الا وانس لم ابل … بطلوع شيب وابيضاض غدائر\nلكن شيب الرأس إن يك طالعا … عندي فوصل البيض اول غائر\nواها على عهد الشباب وطيبه … والغض من ورق الشباب الناضر\nواها له ماكان غير دجنة … قلصت صبابتها كظل الطائر\nسبع وعشرون اهتصرن شبيبتي … والن عودي للزمان الكاسر\nكان المشيب وراء ظل قالص … لأخ الصبا واما عمر قاصر\nوأرى المنايا ان رأت بك شيبة … جعلتك مرمى نبلها المتواتر\nتعشو إلى ضوء المشيب فتهتدي … وتضل في ليل الشباب الغابر\nلو يفتدى ذاك السواد فديته … بسواد عيني بل سواد ضمائري\nأبياض رأس واسوداد مطالب ؟ … صبرا على حكم الزمان الجائر\nان اصفحت عنه الخدود فطالما … عطفت له بلواجظ ونواظر\nولقد يكون وما له من عاذل … فاليوم عاد وماله من عاذر\nكان السواد سواد عين حبيبه … فغدا البياض بياض طرف الناظر\nلو لم يكن في الشيب الا انه … عذر الملول وحجة للهاجر\nسالم تصاريف الزمان فمن يرم … حرب الزمان يعد قليل الناصر\nمن يكان يشكو من رشاش خطوبه … فلقد سقاني بالذنوب الوافر\nابلغ ظباء الحي ان فؤاده … قطع العلاقة ، وارعوى للزاجر\nاوردنني فعلمت ان مواردي … لولا النهى ، لم أدر أين مصادري\nنالت لبا من علائق صبوة … ونشطت قلبا من جوى متخامر\nأنا من علمتن ، الغداة ، نقية … أزري ، وضامنة العفاف مآزري\nفاعرفن كيف شمائلي وضرائبي … وانظرن كيف مناقبي ومآثري\nكمعاقد الجبل الاشم معاقدي … ومجاور البيت الحرام مجاوري\nلم يشتمل قلبي الرجاء ولم يكن … طرفي جنيبة كل برق نائر\nوابيت ان ترد المطالب همتي … او ان يسف الى المطامع طائري\nاسعى على اثر النوائب منصفا … منها ، وآسي كل عرق ناغر\nقل للاعادي جنبوا عن ساحلي … لا يغرقنكم التطام زواخري\nلولا خمولكم لقد قلدتم … عارا بنظم غرائبي وسوائري\nأخزيتم ذا كبرة وتكاوس … وفضلتم ذا ودعة وقراقر\nفتناذروا ناب الشجاع مشى به … جنح الدجى ، ويد العقور الخادر\nيا ساعيا لينال مطمح غايتي … اين الذوائب من مدق الحافر\nإذهب بسبي إن سببتك فاخرا … قد نوهت بك ضربة من باتر\nمن عار هذا الدهر نيلك للعلى … وجنون هذا المنجنون الدائر\nقومي الأولى لحبوا إلى نيل العلى … وضح الطريق لمنجد أو غائر\nأخذوا المعالي عن متون قواضب … ترد الغوار وعن ظهور ضوامر\nوعن الرماح يشيط في أطرافها … بالطعن كل معامر ومغاور\nقوم إذا اشتجرت عليهم خطة … زعموا النوائب بالقنا المتشاجر\nوإذا التقت أيديهم في أزمة … ساجلن اذنبة السحاب الماطر\nلا نارهم نار مغمضة ولا … \nوتسوف أفواه الملوك أكفهم … سوف السوام ربيع روض باكر\nشجعاء افئدة بغير صوارم … خطباء السنة بغير منابر\nذمروا قلوب المادحين وانما … مدح الملوك شجاعة للشاعر\nيتغايرون على السماح كأنما … يتغايرون عل وصال ضرائر\nأهدي إلى قومي نصيحة حازم … طب بأدواء الضغائن خابر\nلا تنظروا الجاني لمحو ذنوبه … بملفقات تنصل ومعاذر\nلن تظفروا بالعز حتى تصبغوا … ثوب المعالي بالنجيع المائر\nلا تعتبوا الا بالسنة القنا … فلهن إطآر البعيد النافر\nودعوا التظاهر بالحلوم ، فإنها … سبب انبعاث جرائم وجرائر\nلا تخدعن ، فما عقوبة قادر … إلا بأحسن من تجاوز قادر"},{"id":"diwan-radi:235","bookId":"diwan-radi","type":"poem","seq":235,"chapter":"البحر: رمل تام","title":"قربوهن ليبعدن المغارا","page":"","text":"قربوهن ليبعدن المغارا … ويبدلن بدار الهون دارا\nواصطفوهن لينتجن العلى … بالعوالي ، لا لينتجن المهارا\nفي بيوت الحي أدنى منزلا … ومقامات من البيض العذارى\nاخدموهن الغواني غيرة … انهم كانوا على المجد غيارا\nغرر تقنص من لاطمها … يوم تمسي لطمة الدمر جبارا\nجللوها الرقم من عزتها … وادروا لمقاريها العشارا\nأقضموها بدل الرطب الجنى … وسقوها بدل الماء العقارا\nكل محبوك القرى تحسبه … طائرا اوفى على النيق وطارا\nتخرج النبأة منه وثبة … مضرب الريح على الطود الازارا\nيلحق الرمح ، ولو كن القنا … كسياط الاعوجيات قصارا\nوأغر الخلق ، والخلق له … نسب ردد في السيف مرارا\nوبياض الخلق اعلى رتبة … من بياض زان وجها وعذارا\nسل بقوم نزل الدهر بهم … فاساء اللبث فيهم والجوارا\nلم تكن علياؤهم منحولة … أبد الدهر ، ولا المجد معارا\nطيبوا الاردان ان جالستهم … قلت داريون قد فضوا العطارا\nكان نثر المسك باقي عهدهم … وعهود الناس دمنا وذئارا\nناب عرف الطيب عن نار القرة ى … ضوأ الليل ، وما أوقد نارا\nضرب المجد عليهم بيته … وغدوا دون حمى المجد إطارا\nشذبت ايدي الليالي منهم … عددا لا يرأم الضيم كثارا\nعانقوا الهضب وكانوا هضبة … لا يلاقي عندها السيل قرارا\nصدع المقدار فيهم صدعة … منبذ القعب أبى إلا انكسارا\nلم تكن ختلا ولكن غارة … آمن الشلة من لاقى العوارا\nقد نزلنا دار كسرى بعده … أربعا ما كن للذل ظؤارا\nاسفرت اعطانها عن معشر … شغلوا المجد بهم عن ان يعارا\nتصف الدار لنا قطانها : … المعالي والمساعي والنجارا\nواذا لم تدر ما قوم مضوا … فسل الاثار واستنب الديارا\nآل ساسان حدا الخطب بهم … واسترد الدهر منهم ما اعارا\nبعد ما شادوا البنى ترفعها … عمد المجد قبابا ومنارا\nكل ملموم القرى صعب الذرى … يزلق العقبانم عنه والنسارا\nجعجعوا الإيوان في مبركه … مبرك البازل قد قضى السفارا\nحمل الدهر الى ان رده … ضاغط العبء ضلوعا وفقارا\nمطرقا إطراق مأمون الشذا … غمر النادي حلما ووقارا\nأو مليك وقع الدهر به … فأماط الطوق عنه والسوارا\nأوهنت منه الليالي فقرة … لا يلاقي وهنها اليوم جبارا\nاين لا اين المعالي جمة … والحمى افيح والراي مغارا\nورجال شدخت أوضاحهم … غلوا الاعناق منا واسارا\nيهملون المال إهمالهم … غارب السرح ويرعون الذمارا\nكل موقوذ من التاج له … نهر يسقي يلنجوجا وغارا\nذي ضياء إن جلا عرنينه … ضوء الليل وما اوقد نارا\nتسكن الضوضاء عنه هيبة … مثل ما لبدت المزن الغبارا\nكزئير الليث ينفي صوته … عن خفا فيه ، ثؤاجا ويعارا\nعمروا لم يعلموا أن لنا … جائز الأمر عليهم والإمارا\nقدروا جد نزار واقفا … ومشى الجد فما عزوا نزارا\nلاوذوا لما رأوا من دونهم … واديا يلقي به السيل غمارا\nعاينوا الضرب دراكا في الطلى … يعجل الفارس ، والطعن بدارا\nأصحر الليث العفرنى ، فانثنى … يطلب اليربوع في الارض وجارا\nقهقروا الشرك على أعقابه … بعد ما استقدم غيا وضرارا\nوأثاروا الدين من مربضه … واطاروا عن مجاليه الخمارا\nداينوا المجد باطراف القنا … فغدا عينا ، وقد كان ضمارا\nعلموا لما اذيقوا بأسنا … ان عقب الجري قد بذ الحضارا\nلا أغب الدار من بعدهم … شول يحملن وبلا وقطارا\nفي غمام بهل اخلافها … اطلق الراعد عنهن الصرارا\nمثقلات ترجم الودق بها … كاكف الحج يرمون الجمارا\n … نغر العرق إذا ما العرق فارا\nكل دهماء ترى القطر بها … من لجين وترى البرق نضارا\nجهمة تضرب غاريها الصبا … رجة الركب يكدون البئارا\nكالمطايا اقبلت مرحولة … شلها حاد اذا انجد غارا\nأو نعام الدو بادرن الدجى … يتجاوبن عرارا وزمارا\nطاولوا الدهر ولم يبقوا ، ومن … يأمن الليل عليه والنهارا"},{"id":"diwan-radi:236","bookId":"diwan-radi","type":"poem","seq":236,"chapter":"البحر: بسيط تام","title":"صاحت بذودبي بغدار فانسني","page":"","text":"صاحت بذودبي بغدار فانسني … تقلبي في ظهور الخيل والعير\nوكلما هجهجت بي عن منازلها … عارضتها بجنان غير مذعور\nأطغى على قاطنيها غير مكترث … وأفعل الفعل فيها غير مأمور\nخطب يهددني بالبعد عن وطني … وما خلقت لغير السرج والكور\nبني أمية ! ما الأسياف نائمة … فقد نجوت وقدحي غير مقمور\nعجلان البس وجهي كل داجية … والبر عريان من ظبي ويعفور\nورب قايلة والهم يتحفني … بناظر من نطاف الدمع ممطور :\nخفض عليك فللاحزان آونة … وما المقيم على حزن بمعذور\nفقلت : هيهات ! فات السمع لائمه … لا يفهم الحزن إلا يوم عاشور\nيوم حدى الظعن فيه بابن فاطمة … سنان مطرد الكعبين مطرور\nوخر للموت لا كف تقلبه … إلا بوطء من الجرد المحاضير\nظمآن سلى نجيع الطعن غلته … عن بارد من عباب الماء مقرور\nكأن بيض المواضي ، وهي تنهبه … نار تحكم في جسم من النور\nلله ملقى على الرمضاء عض به … فم الردى بين اقدام وتشمير\nتحنو عليه الربى ظلا وتستره … عن النواظر أذيال الأعاصير\nتهلابه اللوحش ان تدنوا لمصرعه … وقد أقام ثلاثا غير مقبور\nومورد غمرات الضرب غرته … جرت اليه المنايا بالمصادير\nومستطيل على الازمان يقدرها … جنى الزمان عليها بالمقادسير\nأغرى به ابن زياد لؤم عنصره … وسعيه ليزيد غير مشكور\nوود ان يتلاقى ما جنت يده … وكان ذلك كسرا غير مجبور\nتسبى بنات رسول الله بينهم … والدين غض المبادي غير مستور\nان يظفر الموت منا بابن منجية … فطالما عاد ريان الأظافير\nيلقى القنا بجبين شان صفحته … وقع اللقنا بين تضميخ وتعفير\nمن بعد ما رد أطراف الرماح به … قلب فسيح ورأي غير محصور\nوالنقع يسحب من أذياله ، وله … على الغزالة جيب غير مزرور\nفي فيلق شرق بالبيض تحسبه … برقا تدلى على الآكام والقور\nبني انمية ما الاسياف نائمة … عن شاهر في أقاصي الأرض موتور\nوالبارقات تلوى في مغامدها … والسابقات تمطى في المضامير\n … عريان يقلق منه كل مغرور\nوللصوارم ما شاءت مضاربها … من الرقاب شراب غير منزور\nاكل يوم لآل المصطفى قمر … يهوى بوقع العوالي والمباتير\nوكل يوم لهم بيضاء صافية … يشوبها الدهر من رنق وتكدير\nمغوار قوم ، يروع الموت من يده … أمسى وأصبح نهبا للمغاوير\nوابيض الوجه مشهور تغطرفه … مضى بيوم من الايام مشهور\nما لي تعجبت من همي ونفرته … والحزن جرح بقلبي غير مسبور\nباي طرف ارى العلياء ان نضبت … عيني ولجلجت عنها بالمعاذير\nألقى الزمان بكلم غير مندمل … عمر الزمان وقلب غير مسرور\nيا جدلا زال لي هم يحرضني … على الدموع ووجد غير مقهور\nوالدمع تخفره عين مؤرقة … خفر الحنية عن نزع وتوتير\nإن السلو لمحظور على كبدي … وما السلو على قلب بمحظور"},{"id":"diwan-radi:237","bookId":"diwan-radi","type":"poem","seq":237,"chapter":"البحر: كامل تام","title":"ألقي السلاح ربيعة بن نزار","page":"","text":"ألقي السلاح ربيعة بن نزار … اودى الردى بقريعك المغوار\nوترجلي عن كل اجردسابح … ميل الرقاب نواكس الابصار\nودعي الأعنة من أكفك إنها … فقدت مصرفها ليوم مغار\nوتجنبي جر القنا فلقد مضى … عنهن كبش الفيلق الجرار\nوليغد كل مغرض من بعده … مغرى بحل معاقد الاكوار\nقطع الزمان لسانك العضب الشبا … وهدى تخمط فحلك الهدار\nواجتاح ذاك … وطوى غوارب ذلك التيار\nاليوم صرحت النوائب كيدها … فينا وبان تحامل الاقدار\nمستنزل الأسد الهزبر برمحه … ولى ، وفالق هامة الجبار\nوتعطلت وقفات كل كريهة … أبدا ، وحط رواق كل غبار\nهيهات لا علق النجيع بعامل … يوما ولا علق السرى بعذار\nيا تغلب ابنة وائل ! ما لي أرى … نجميك قد افلا عن النظار\nغربا ، فذاك غروبه لمنية … عجلى وذاك غروبه لاسار\nما لي رأيت فناء دارك عاطلا … من كل أبلج كالشهاب الواري\nمتخبلي الاقطار الا من جوى … ونشيج كل خريدة معطار\nوحنين ملقاة الرجال مناخه … وصهيل واضعة السروج عوار\nفجعت سماؤك بالشموس وحولت … عنها وعنك مطالع الأقمار\nفي كل يوم نوء مجد ساقط … منها ونجم مناقب متوار\nعضت بنازلها المنون ولم تزل … تقرو طريق الناب بالأظفار\nيا طالا بالثار اعجلك الردى … عن ان ينام على وجود الثار\nيعتادج ذكرك ما تهزم مرجل … وطغى تغيض برمة أعشار\nهجرت ركاب الركب بعدك قطعها … هول الدجى ومهاول الأوعار\nوعدمن كل مفازة مرهوبة … وامن كل مخاطر عقار\nفالان يجررن الازمة بدنا … بين المياه تفيض والانوار\nاين القباب الحمر تفهق بالقرى … مهتوكة الأستار للزوار\nاين الفناء تموج في جناته … بصهيل جرد أو رغاء عشار\nاين القنا مركوزة تهفو بها … عذب البنود يطرن كل مطار\nاين الجياد مللن من طول السرى … يقذفن بالمهرات والأمهار\nمن معشر غلب الرقاب جحاجح … غلبوا على الاقدار والاخطار\nمن كل أروع طاعن أو ضارب … أو واهب ، أو خالع ، أو قار\nوفوارس كالشهب تطرح ضوءها … يوم الوغى وأوار حر النار\nركبوا رماحهم إلى أغراضهم … أمم العلى ، وجروا بغير عثار\nواستنزلوا ارزاقهم لسيوفهم … فغنوا بغير مذلة وصغار\nكانوا هم الحي اللقاح وغيرهم … ضرع على حكم المقاول جار\nلا ينبذون إلى الخلائف طاعة … بقعاقع الإيعاد والإنذار\nعقدوا لوائهم ببيض اكفهم … كبرا على العقاد والامار\nواستفظعوا خلع الملوك وأيقنوا … أن اللباس لها ادراع العاري\nكثر النصير لهم ، فلما جاءهم … أمر الردى وجدوا بلا أنصار\nهم اعجلوا داعي المنون تعرضا … للطعن بين ذوابل وشفار\nأوليس يكفينا تسلط بأسها … حتى تسلطها على الاعمار\nنزلوا بقارعة تشابه عندها … ذل العبيد وعزة الاحرار\nسد البلى ، وأنار فوق جسومهم … من كل منهال النقا موار\nخرس قد اعتنقوا الصفيح وطالما … اعتنقوا الصفائح والدماء جوار\nنقضت مرائرهم ، وكن أكفهم … مبلولة بالنقض والإمرار\nصاروا قرارا للمنون ، وإنما … كانوا لسيل الذل غير قرار\nكنا نرى أعيانهم ممدوحة … فاليوم يمتدحون بالاثار\nشرفا بني حمدان ان نفوسكم … من خير عرق ضارب ونجار\nانفت من الموت الذليل فاشعرت … جلدا على وقع القنا الخطار\nبكرت عليك سحابة نفاخة … تلقي زلازلها على الأقطار\nشهاقة أسفا عليك برعدها … طورا وباكية بعذب قطار\nوسقتك أوعية الدموع فجاوزت … قطرات ذاك العارض المدرار\nوإذا الصبا حدت النسيم مريضة … تفلي جميم الروض والنوار\nممطورة الانفاس فاه بطيبها … سحريبين بها من الاسحار\nفجرت على ذاك التراب سليمة … من غير اضرار لها بجوار\nتجري وذاك القبر غير مروع … منها ، وذاك الترب غير مثار\nاني ذكرتك خاليا فكأنما … أخذت علي الأرض بالأطرار\nوكأنما مالت علي بحدها … نزوات قانية الاديم عقار\nلازال زائر قبره في عبرة … تنعى البقاء اليه واستعبار\nوالروض من حال عليه وعاطل … والمزن من غاد عليه وسار"},{"id":"diwan-radi:238","bookId":"diwan-radi","type":"poem","seq":238,"chapter":"البحر: كامل تام","title":"أوما رأيت وقائع الدهر","page":"","text":"أوما رأيت وقائع الدهر … أفلا تسيء الظن بالعمر\nبينا الفتى كالطود تكنفه … هضباته والعضب ذي الاثر\nيأبى الدنية في عشيرته … ويجاذب الايدي على الفخر\nوإذا أشار إلى قبائله … حشدت إليه بأوجه غر\nيترادفون على الرماح كأنهم … سيل يعب وعارض يسري\nان نهنهوا زادوا مقاربة … فكأنما يدعون بالزجر\nعدد النجوم ، إذا دعي بهم … يتزاحمون تزاحم الشعر\nعقدوا على الجلى مآذرهم … سبط الانامل طيب الزر\nزل الزمان بوطئ اخمصه … ومواطئ الازمان للعثر\nنزع الإباء ، وكان شملته … واقر اقرار على صغر\nصدع الردى أعيا تلاحمه … من ألحم الصدفين بالقطر ؟\nحر الجيادعلى الوجى ومضى … أمما يدق السهل بالوعر\nحتى التقى بالشمس مغمده … في قعر منقطع من\nثم انثنت كف المنون به … كالضغث بين الناب والظفر\nلم تستجر عنه الرماح ولا … رد القضاء بما له الدثر\nلحمامه كان الذي يبري … لاقته وهو مضيع الظهر\nوبنى الحصون تمتعا فكأنما … أمسى بمضيعة ، ولا يدري\nوبرى المعابل للعدى فكأنما … \nهذا عبيد الله حين رمى … عرض العلى وابى على الدهر\nورمت به العيوق همته … فوطي رقاب الأنجم الزهر\nغلبت مآثره النجوم على … عرصاتها ، وبدأن بالبدر\nوتناذر الأعداء صولته … فأبات أشجعهم على ذعر\nقادت حزامته المنون فلم … تمنع مضارب بيضة البتر\nنكصت اسنته وأحجم جنده … جزعا لمطلع ذلك الامر\nقد كان مشهورا إذا ذكرت … خطط الوغى ومواقف الصبر\nمتهللا في كل نائبة … تضع القلوب مواضع البشر\nيرقى إلى أمد المكارم والعلى … لم تختزله موانع الكبر\nلو لم يعارضه الحمام اذا … لمضى على غلوائه يجري\nاودى وما اوزدت مناقبه … ومن الرجال معمر الذكر\nطوت الليالي بعد مصرعه … نار القرى ومعرس السفر\nخلي وترب أبي لقد سلبت … مني النوائب انفس الذخر\nقد كان من عددي إذا طرقت … بزلاء ضاق بها حمى الصدر\nوهو الزمان على تقلبه … ينوي العقوق بنية البر\nكم زفرة خرساء اكظمها … متمسكا بعلائق الأجر\nضمرت بجرتها عليك وفي … احشائها كلواعج الجمر\nلو أن ما أنحى عليك يد … راعتك بالانباض عن عقر\nلوقفت بينكما لاعكس سهمهما … عن نحرك البادي الى نحري\nولو أنها سمراء مشرعة … أعطيت حد سنانها صدري\nوسمحت دونك بالحياة على … ضنى بها وكرائم الوفر\nاو بالغا بالنفس معذرة … والسعي بين النجح والعذر\nلكن رمتك اشد رامية … سهما واهداها الى العقر\nبلغتك من خلف الدروع ومن … خلل القنا ، والعسكر المجر\nحمل الغمام جديد ريقه … فسقى مغيب ذلك القبر\nلولا مشاركة المدامع في … سقياه قل له ندى القطر\nلو أنبتت ترب الرجال على … قدر العلى ونباهة القدر\nنبتت عليه من شجاعته … تلك الجنادل بالقنا السمر\nان التوقي فرط معجزة … فدع القضاء يقد أو يفري\nلو مال بالقرنين خوفهما … للموت ما اضغنا على الوتر\nاوعد داما في الخطال اذا … لتوادعا أبدا على غمر\nنحمي المطاعم للبقاء وذي … الاآجال ملء فروجها تجري\nلو كان حفظ النفس ينفعنا … كان الطبيب احق بالعمر\nالموت داء لا دواء له … سيان ما يوبي وما يمري"},{"id":"diwan-radi:239","bookId":"diwan-radi","type":"poem","seq":239,"chapter":"البحر: طويل","title":"لعمري لقد ماطلت لو دفع الردى","page":"","text":"لعمري لقد ماطلت لو دفع الردى … مطال وقد عاتبت لو سمع الدهر\nأفي كل يوم انت غاد مشيع … حبيبا إلى دار يقال لها القبر\nلئن كان لي في كل ما أنا تارك … وراء الثرى اجر لقد عظم الاجر\nسقيت أبا بكر على البعد والنوى … ولا بل هام الشامتين بك القطر\nأخي ما أقل التابعيك إلى الثرى … واخوانك الادنون من قبلها كثر\nلقد كانت النكراء منك خليقة … ولاعرف حتى يتقى قبله النكر\nألا إنما الماضون منا هم الأولى … أراحوا وحطوا والبواقي هم السفر\nنتبعه ابصارنا وهو ذاهب … كما مال قرن الشمس أو وجب البدر\nعليك سلام الله فات بك الردى … ولم يبق عين للقاء ولا أثر"},{"id":"diwan-radi:240","bookId":"diwan-radi","type":"poem","seq":240,"chapter":"البحر: خفيف تام","title":"لو رأيت الغرام يبلغ عذرا","page":"","text":"لو رأيت الغرام يبلغ عذرا … قلت حزنا ولم اقل لك صبرا\nواستزدنا ريح الزفير هبوبا … وسحاب الدموع وبلا وقطرا\nورأينا معرس الحزن سهلا … في الرزايا وجانب الصبر عرا\nلكن الأمر ما علمت ، وهل … تنظر من وقعة الزمان مبرا\nواقعا بالاضداد اروى واظمى … وقضى ، واقتضى ، وساء وسرا\nكل يوم يغدو بقاطعة الآ … مال غضبان قد تابط شرا\nمذنبا كلما شكا شاك كيدا … واذا قيل قد اناب اصرا\nضيغما يخبط السروب طروبا … كلما مر بالعقيرة كرا\nوارى الناس وافرا وملقى … بالرزايا والارض دارا وقبرا\nمنزلي قلعة ولبث ، فهذا … مجازا لنا وهذا مقرا\nكل يوم نذم للدهر عهدا … خان فيه ونشتكي منه غدرا\nقد انيخت لنا الركائب فالاحازم … زم عبى زادا ، ووطأ ظهرا\nعجبا سمتك السلو ، وعندي … كب زماعا الى المنون ونفرا\nكم فقيدلنا طوته الليالي … ذقن منه حلوا وذوقن مرا\nوكأن الايام يدركن ثارا … عندنا فيه ، أو يقضين نذرا\nإنما المرء كالقضيب ، تراه … يكتسي الاخضر الرطيب ليعرى\nمعكس السهم ذا يراش ليمضى … في المرامي وذا يراش ليبرى\nمن مؤد إلى علي ألوكا … أبجد عصيت للصبر امرا\nاي خطب راخى قواك وقد … ت جديلا على الخطوب ممرا\nأعل من عثرة الأسى إن للأن … نداد نهضا وللاعاجز عثرا\nأي باق يبقي عليك ، ولو كن … كنت موقى من الخطوب معرا\nافقد الاصل بالغا منتهى النبت … المرجى من افقد الفرع نضرا\nكن كعود الطريق طال سراه … يشتكي قفرة ويألم عقرا\nوالجليد لالذي اذا الدهر ابكى … منه قلبا جل على الناس ثغرا\nمستميتا يزر بالصبر درعا … ويراه في ظلمة الهم فجرا\nوقرته روائع الدهر ، حتى … لم يرع غير مرة ، واستمرا\nكلما زيد غمة ، زاد صبرا … ضرم الزند كلما لز أورى\nارمضته هواجر الخطب فانقا … د حمول الأذى ، وما قال هجرا\nهاب ضحضاحها ومر به الدهر … ر على سبلها ، فخاض الغمرا\nكلما غاب من بني خلف بدر … يضيء الظلام اخلف بدرا\nواذا قلت ينزع العوزاذل سمعي … في التسلي عن معشر زاد وقرا\nأجد القلب بعد لومي أسخى … فكأن اللاحي بما قال اغرى\nزاد عذلا فزاد قلبي ولوعا … رب آس اراد نفعا فضرا\nفسقى الدمع معشرا نزلوا القل … واخلوا باقي المنازل طرا\nكلما قصر الحيا كان ماء العي … ن ابقى صوبا واعظم غزرا\nكم حشوت الثرى حساما طريرا … وطويلا لدنا وطرفا اغرا\nوخدودا مثل الذوابل ملسا … وجباها مثل الدنانير غرا\nوكأن القبور منهم بذي الجز … عياب حملن درا وعطرا\nاوجه صانها الجلال فأمسين … ترابا تحتالجنادل غبرا\nعطل الدهر من حلاهن فينا … وتحلى الثرى بهن واثرى\nقطع الموت بيننا ، فتباي … نا لقاء ، إلا نزاعا وذكرا\nفبعدنا ، وما اعتمدنا بعادا … وهجرنا ، وما أردنا الهجرا\nروعة ان جزعت منها فعذر … لجزوع ، وإن صبرت ، فأحرى\nوقعت موقع العوان من الدهر … وانم كانت الرزية بكرا"},{"id":"diwan-radi:241","bookId":"diwan-radi","type":"poem","seq":241,"chapter":"البحر: طويل","title":"تناسيت ، إلا باقيات من الذكر","page":"","text":"تناسيت ، إلا باقيات من الذكر … ليالينا بين القرينة والغمر\nوكم زادني فيها الهوى عن جمامه … وقارعني الغيران عن بيضة الخدر\nوذي دعج لا نابل الحي رايشا … ولا باريا يبري من الشر ما يبري\nيقلب لي في محجري ام شادن … تجفل أو يدنو على ذعر\nتلقيت من طرفيه سهما وجدته … يلذ على عيني ويؤلم في صدري\nفيالك من رام اضم سهامه … وإن نلن مني باليدين إلى النحر\nأقول لغيداق ، وأذكرني الهوى … على النأي ما للقلب ويبك الذكر\nتذكرني ما حالت الارض دونه … ألا إنما سولت للدمع أن يجري\nوطي الليالي والجديد الى بلى … وليس لما يطوي الجديدان من نشر\nوشر الرفيقين الذي إن أمرته … عصاك وإن ما حطته الدهر لم يدر\nيقارعني ، حتى إذا كل غربه … نسينا التصافي واندملنا على غمر\nأفي كل يوم أنت ماتح عبرة … على طلل بالود أو منزل قفر\nومنتزح جمات عينيك راجعا … الى غزر ماء لا بكئ ولا نزر\nأقول : عزاء ، والجوى يستفزه … وأعيا الأواسي عي عظم على وقر\nفلما ابى الا البكاء رفدته … بعينين كانا للدموع على قدر\nوقلت له رد الجفون على القذى … وخل الجوى يمري من الدمع ما يمري\nقسمن زفير الوجد بيني وبينه … دواليك أقريه اللواعج أو يقري\nعشية تغشاني من الدمع كنة … كأني مرهوم الإزارين بالقطر\nفزعت الى فضل الرداء مبادرا … تلقي دمعي أن ينم على سري\nكأني وغيداقا طريدا مخافة … اصابا دما في مالك وبنى النضر\nنحلأ عن ماء الحلول وننثني … على رصف اكباد احر من الجمر\nفاين بنو ام المكارم والندى … وال الجياد الغر والجامل الدثر\nواين الطوال الغلب كانت سيوفهم … فرادى عن الأجفان للضرب والعقر\nكانك تلقى هجمة الخطب منهم … بزيد القنى أو بالتلمس أو عمرو\nإذا عدموا أثروا طعانا ، وغيرهم … لئيم الغنى يوم الغنى عاجز الفقر\nلهم كل شهقى بالنجيع كما رغى … قراسية رد العجيج على الهدر\nلها رقصات بالدماء ، كأنما … تشقق عن أعراف أحصنة شقر\nتلمظ تلماظ المروع ، وتنكفي … جواشنها من مظلم الجال ذي قعر\nرموا بجباه الخيل مأسدة الردى … وسدوا بمربوع القنا طلع الثغر\nولم تدر أيمان القوابل منهم … أسلت رجالا أم ظبى قضب بتر ؟\nهم استفرغوا ما كان في البيض والقنا … فلم يبق الا ذوا اعوجاج والخطر\nبنوها بايام الطعان وما بنت … لتغلب أيام الطعان على بكر\nيعودون قد ردوا العظيمة عن يد … وقد أغلقوا باب الطلاطلة البكر\nوغير الوان القنا طول طعنهم … فبالحمر تدعى اليوم لا بالقنا السمر\nغدوا سهكى الايمان من صدأ الظبى … وراحوا كراما طيبي عقد الازر\nهم الحاجبون العرض عن كل سبة … إذا طرقوا والآذنون على القدر\nوهم ينفدون المال في أول الغنى … ويستأنفون الصبر في اول الصبر\nمليؤن ان يبدوا بذي التاج ذلة … اذا كرموا في طاعة الجود ذا الطمر\nاذا سئلوا لم يتبعوا المال وجمة … ولم يدفعوا في صفحة الحق بالعذر\nمن البيض يستامون ، والعام كالح … جدوبا وطمطكارون في الحجج الغبر\nكأن عفاة المرء ذي الطول منهم … يمدون أوذام الدلاء من\nمغاوير في الجلى ، مغابير للحمى … مفاريخ للغمى ، مداريك للوتر\nسراع الى الورد الذي ماؤه الردى … اذا ارعد النكس الجبان بلا قر\nوتأخذهم في ساعة الجود هزة … فحول الوغى بين الزماجر والخطر\nفتحسبهم فيها نشاة وى من الغنى … وهم في جلابيب الخصاصة والفقر\nعظيم عليهم ان يبيتوا بلا يد … وهين عليهم أن يفيئوا بلا وفر\nإذا نزل الحي الغريب تقارعوا … عليه ، فلم يدر المقل من المثري\nيميلون في شق الوفاء مع الردى … اذا كان محبوب البقاء مع الغعدر\nحواقلة مثل الصقور وفتية … إذا ما حناني طارق دعموا ظهري\nوما لطموا عن غاية المجد جبهتي … بلى خلعوا عنمي لادراكها عذري\nتوراك لي في حال يسري فان رأوا … \nهم أنهضوني بعدما قيل لا لعا … وهم أغرموا الأيام لي ما جنى عثري\nكفوني ، وما استكفيتهم من ضراعة … ترافد أيدي الأبعدين على نصري\nترى كل ذيال العطاف ، كأنما … تفرج منه الليل عن قمر بدر\nله رائد يلقاك من قبل شخصه … جلالا كما دل الضياء على الفجر\nيصدع عنه الناظرون كانما … يرون به ذا لبدتين أبا أجر\nله عبق يغنينه عن طيب عرضه … سطوعا من البان المديني والعطرا\nلقد أولع الموت الزؤام بجمعهم … كأن الردى فيهم تحلل من نذر\nوروا كبدي في آخر الدهر لوعة … بما بردوا قلبي على اول الدهر\nمضوا ، فكأن الحي فرع أراكة … على اثرهم عري من الورق النضر\nواصبح ورد الدمع للعين بعدهم … على الغب إذ ورد الفراء على العشر\nوما تركوا عند الرماح بقية … لهز إلى يوم العماس ولا جر\nنبذتهم نبذ الإداوة لم تدع … من الماء ما يعدى على غلة الصدر\nبقيت معنى بالبقاء خلافهم … وما بيننا الا قديد يمة السفر\nوأغدوا على آثارهم وودادتي … لو انهم الغادون بعدي على اثري\nوفي الحي بيتي خالفا وكأنني … من الوجد يورى بين اقبرهم قبري\nكأني مغلوب على نصل سيفه … اقام بلا ناب يروع ولا ظفر\nفما أتلافى الغمض إلا على قذى … ولا أتناسى الوجد إلا على ذكر\nوقالوا اصطبر للخطب ، هيهات إذ مضى … مقوم درئي ، والمعين على دهري"},{"id":"diwan-radi:242","bookId":"diwan-radi","type":"poem","seq":242,"chapter":"البحر: طويل","title":"وذي نضد لا يقطع الطرف عرضه","page":"","text":"وذي نضد لا يقطع الطرف عرضه … اذا قيل نجدي المباح تغورا\nتخال به ركني أبان وشابة … أطلا ورجراجا من الرمل أعفرا\nإذا مد بالأعناق قعقع رعده … كعود الملا ان عضه العبء جرجرا\nكما اصطرعت رايات قيس وخندف … عجالى يجرون العديد المجمهرا\nاذا اج بالايماض قلت ابن كفة … يضرم بالغاب الأباء المسعرا\nتشول تشوال البروق ببرقة … ورجع قرقار الفنيق بقرقرا\nكأن به النوتي من سيف جدة … على عجل يزجي السفين الموقرا\nله نعرات بين قو ورامة … ولا نعرات الشيخ اوس ابن معيرا\nابست به ريح النعامى منيحة … كما جعجع الوهم الثقال ليعقرا\nوهو جاء في اشواطها عجرفية … تسوق من الغور الغمام الكنهورا\nتبعق بالاطباء من كل فيقة … كمخض الغريري المزاد الموكرا\nوأقلع إقلاع الظلام ، وقد وزى … قلال الروابي والركي المغورا\nقضى بك لا ضنا عليك بمدمعي … ولكن رسيل الدمع جاد وأمطرا\nلقد ساءني ان البلابل روحت … وان مطال الداء بعدك اقصرا\nتضرعت في اعقاب وجد عليكم … ومن فاته الاعذار بالامر عذرا\nوأهجركم هجر الخلي ، وأنتم … اعز على عيني من طارق الكرى\nولم أزجر العين الدموع لتنتهي … ولم اعذل القلب اللجوج ليصبرا\nوقالوا : أرح قرح الفؤاد ، وإنما … أحب فؤادي انطوى دونه البرى\nكفى جانب القبر الذي انت ضمنه … زفيري ودمعي أن يراح ويمطرا\nوما ضر قلبي إذ غدا منك آهلا … تأمل عيني منزلا منك مقفرا\nذكرتك والارض العريضة بيننا … وشر على ذي الوجد أن يتذكرا\nفإن لم يزل قلبي إليك فقد هفا … وان لم يزد دمعي عليك فقد جرى"},{"id":"diwan-radi:243","bookId":"diwan-radi","type":"poem","seq":243,"chapter":"البحر: خفيف تام","title":"اين بانوك ايها الحيرة البيضاء","page":"","text":"اين بانوك ايها الحيرة البيضاء … ضاء ، والموطئون منك الديارا\nوالاولى شققوا ثراك من العش … ب ، وأجروا خلالك الأنهارا\nالمهيبون بالضيوف اذا … هبت شمالا والموقدون النارا\nكلما باخ ضؤها اقضموها … بالقبيبات مندليا وغارا\nربطوا حولك الجياد وخطوا … لك من مركز العوالي عذارا\nوحموا ارضك الحوافر حتى … لقبوا ارضها خدود العذارا\nلم يدع منك حادث الدهر الا … عبرا للعيون واستعبارا\nوبقايا من دارسات طلول … خبرتنا عن اهلها الاخبارا\nعبقات الثرى كأن عليها … لطميين ينفضون العطارا\nوقباب كانما رفعوا منها … لمسترشد الظلام منارا\nعقدوا بينها وبين نجوم الا … فق من سالف الليالي جوارا\nاين عقبانك الخواطف حلقن … وابقين عندك الاوكارا\nورجال مثل الأسود مشوا في … ك ، تداعوا قوائما وشفارا\nحبذا أهلك المحلون أهلا … يوم بانوا ، وحبذا الدار دارا\nلم يكونوا الا كركب تاني … برهة في مناخه ثم سارا"},{"id":"diwan-radi:244","bookId":"diwan-radi","type":"poem","seq":244,"chapter":"البحر: رمل تام","title":"طلعت ، والليل مشتمل","page":"","text":"طلعت ، والليل مشتمل … سابغ الاذيال والازر\nمن خصاصات الغبيط ، وقد … غرد الحادي على اقر\nورقاب القوم مايلة … من بقايا نشوة السهر\nفاستقاموا في رحالهم … يتبعون الضوء بالنظر\nفامترينا ، ثم قلت لهم : … ليس هذا مطلع القمر"},{"id":"diwan-radi:245","bookId":"diwan-radi","type":"poem","seq":245,"chapter":"البحر: طويل","title":"ألا يا ليالي الخيف ! هل يرجع الهوى","page":"","text":"ألا يا ليالي الخيف ! هل يرجع الهوى … إليكن لي ؟ لا جازكن ندى القطر\nفيا دين قلبي من ثلاث على منى … مضين ولم يبقين غير جوى الذكر\nورامين وهنا بالجمار وانما … رموا بين أحشاء المحبين بالجمر\nرموا لا يبالون الحشى ، وتروحوا … خليين ، والرامي يصيب ، ولا يدري\nوقالوا غدا ميعادنا النفر من منى … وما سرني ان اللقاء مع النفر\nويا بؤس للقرب الذي لا نذوقه … سوى ساعة ثم البعاد مدى الدهر\nفيا صاحبي ان تعط صبرا فانني … نزعت يدي اليوم من طاعة الصبر\nوان كنت لم تدر البكا قبل هذه … فميعاد دمع العين منقلب السفر"},{"id":"diwan-radi:246","bookId":"diwan-radi","type":"poem","seq":246,"chapter":"البحر: بسيط تام","title":"أرتاح إن أخذ الصفصاف زينته","page":"","text":"أرتاح إن أخذ الصفصاف زينته … من الربيع وقال الركب قد مطرا\nمسائلا ، كلما هبت يمانية … وفد القرينة هل احسستم خبرا\nإن لم أرق فيك ماء الناظرين أسى … على الزمان الذي ولى فلا نظرا"},{"id":"diwan-radi:247","bookId":"diwan-radi","type":"poem","seq":247,"chapter":"البحر: كامل تام","title":"نأت القلوب وسوف تنأى الدار","page":"","text":"نأت القلوب وسوف تنأى الدار … وتغيرت بمذاعها الاسرار\nولقد شققت حشى الزمان فلم يكن … فيه سوى سر النوى اضمار\nما للخطوب تبزني ثوب الهوى … وعلي من احداثها اطمار\nألفت ضميري النائبات كأنها … لعتاق أفراس الجوى مضمار\nما لي ارقرق فيك دمعا ترتوي … منه الخطوب وما له مشتار\nايها مؤمل طئ لا تنقضن … ودا له من ذمة امرار\nفلقد حللت من الفؤاد محلة … في حيث ليس من الورى لك جار\nفلئن وفيت فما الوفاء ببدعة … إن الوفاء لذي الصفاء شعار\nوائن غدرت ولا عجيب انه … بعض الزمان ببعضه غدار\nنفسي فداء الغادرين تباعدوا … او قاربوا أو انصفوا أو جاروا"},{"id":"diwan-radi:248","bookId":"diwan-radi","type":"poem","seq":248,"chapter":"البحر: مخلع البسيط","title":"ورب ليل طربت فيه","page":"","text":"ورب ليل طربت فيه … وما استرقتني العقار\nصحوت من سكره ولكن … بي من بقايا الهوى خمار\nنجهل فيه مع الأغاني … والجهل في مثله وقار\nلما استضاء الظلام منا … تعانق الليل والنهار\nزار حبيب الفؤاد فيه … من بعد ما استبعد المزار\nإذا تناءت بنا قلوب … فلا تدانت بنا ديار"},{"id":"diwan-radi:249","bookId":"diwan-radi","type":"poem","seq":249,"chapter":"البحر: بسيط تام","title":"لاموا ولو وجدوا وجدي لقد عذروا","page":"","text":"لاموا ولو وجدوا وجدي لقد عذروا … وذنب من لام ظلما غير مغتفر\nلما تمالوا على عذلي اجبتهم … يعز معترف لا ذل معتذر\nأهوى السواد برأسي ثم أمقته … فكيف يختلف اللونان في نظري\nتأبى طلائع بيض ذر شارقها … في عارضي ان تكون البيض من وطري\nاني علقت سواد اللون بعدكم … علاقة تشمت الظلماء بالقمر\nلو لم يكن فوق لون البيض ما رقمت … صبغ الليالي على الأجياد والعذر\nجعلته لسواد الرأس تذكرة … ان تفقد العين يرضى القلب بالاثر\nوالليل استر للخالي بلذته … والصبح افضح للساري على غرر\nوللفتى في ظلام الليل معذرة … وما له في الضحى إن ضل من عذر\nلا أجمع الحب للبيض الحسان إلى … ما بيض الدهر والايام من شعري\nوكيف يذهب عن قلبي وعن بصري … من كان مثل سواد القلب والبصر"},{"id":"diwan-radi:250","bookId":"diwan-radi","type":"poem","seq":250,"chapter":"البحر: مخلع البسيط","title":"ليس على الشيب للغواني","page":"","text":"ليس على الشيب للغواني … وإن تجملن ، من قرار\nكأنما البيض من لداتي … ضرائر البيض من عذاري\nان خيمت هذه بارضي … تحملت تلك عن دياري\nأرين في رأسي الليالي … شر ضياء لشر نار\nيبدي الخفيات من عيوبي … ويظهر السر من عواري\nاعدوا به اليوم للغواني … اعدى من الذئب للضواري\nوكن طربى إلى طروقي … اذ ليل رأسي بلا دراري\nفمذ أضاء المشيب فودي … تورع الزور عن مزاري\nمثل الخيالات زرن ليلا … وزلن مع طالع النهار"},{"id":"diwan-radi:251","bookId":"diwan-radi","type":"poem","seq":251,"chapter":"البحر: بسيط تام","title":"انا الفداء لظبي ما اعترضت له","page":"","text":"انا الفداء لظبي ما اعترضت له … إلا وهتك شوقا لي أستره\nلاحظته والنوى تدمى ملاحظه … بعارض من رشاش الدمع يمطره\nما انفك من نفس للوجد يكتمه … تحت الضلوع ومن دمع يوفره\nأهوى إلي يدا عقد العناق بها … والبين يعذله ، والحب يعذره\nوقال تذكر هذا بعد فرقتنا … فقلت ما كنت انساه فاذكره"},{"id":"diwan-radi:252","bookId":"diwan-radi","type":"poem","seq":252,"chapter":"البحر: متقارب تام","title":"أقول ، وقد عاد عيد الغرام","page":"","text":"أقول ، وقد عاد عيد الغرام … لما هبطن بنا الاجفرا\nأيا صاحبي ! أترى نارهم ؟ … فقال : تريني ما لا أرى\nدعاني الغرام ولم يدعه … فابصرت ما لم يكن مبصرا\nفما زلت أطربه بالحنين … وأذكره المنزل المقفرا\nإلى أن تنفس عن زفرة … وان من الوجد مستعبرا"},{"id":"diwan-radi:253","bookId":"diwan-radi","type":"poem","seq":253,"chapter":"البحر: بسيط تام","title":"يا قلب ما انت من نجد وساكنه","page":"","text":"يا قلب ما انت من نجد وساكنه … خلفت نجدا وراء المدلج الساري\nراحت نوازع من قلبي تتبعه … على بقايا لبانات وأوطار\nأهفو إلى الركب تعلو لي ركابهم … من الحمى في أسيحاق وأطمار\nتضوع ارواح نجد من ثيابهم … عند النزول لقرب العهد بالدار\nيا راكبان ! قفا لي واقضيا وطري … وخبراني عن نجد بأخبار\nهل روضت قاعة الوعساء ام مطرت … خميلة الطلح ذات البان والغار\nأم هل أبيت ودار عند كاظمة … داري وسمار ذاك الحي سماري\nأيام أودع سري في الهوى فرسي … وأكتم الحي إدلاجي وأخطاري\nفلم يزالا الى ان نم بي نفسي … وحدث الركب عني دمعي الجاري"},{"id":"diwan-radi:254","bookId":"diwan-radi","type":"poem","seq":254,"chapter":"البحر: منسرح","title":"اشكو ليالي غير معتبة","page":"","text":"اشكو ليالي غير معتبة … اما من الطول أو من القصر\nتطول في هجركم وتقصر في … الوصل فما نلتقسي على قدر\nيا لليلة كاد من تقاربها … يعثر فيها العشاء بالسحر"},{"id":"diwan-radi:255","bookId":"diwan-radi","type":"poem","seq":255,"chapter":"البحر: طويل","title":"أتحسب سوء الظن يجرح في فكري","page":"","text":"أتحسب سوء الظن يجرح في فكري … إذا فاحتوي بي العجز من كنف الصبر\nوعاقت يدي عند النزال عوائق … عن السيف لا تدني يدي من النصر\nفلا تقربا ظني بظن مسفه … يظن بزقع الاثر في غرة البدر\nفقلبي يأبى ان يدنس سره … بريب وودي ان يعنف من غدري\nوقد جدت بالنعمى عليك لانني … حللت عرى ضغني وكفكفت من وتري\nولو أنني جازيت قوما بفعلهم … لألبستهم حليا من البيض والسمر\nواخلاقنا ماء زلال تنطوي … حفاظا ويرمي الأفق بالأنجم الزهر\nوما نحن الا عارض ان قصدته … لجود حباك النائل الغمر بالقطر\nوإن هز للأضغان عادت بروقه … حريقا على الأعداء مضطرم السعر\nغفرت ذنوبا منك أذكت عزايمي … وكاد شهاب السخط يطلع من صدري\nصفحت وقد كان التغصص ذادني … عن الصفح لكن أنت من كرم\nومن قيد الالفاظ عند نزاعها … بقيد النهى أغنته عن طلب العذر\nفرح غانما بالعفو ممن لو انطوى … على حنق مات الحمام من الذعر\nبكفي اني شئت ناصية العلى … أهز ، وأعناق المكارم في أسري"},{"id":"diwan-radi:256","bookId":"diwan-radi","type":"poem","seq":256,"chapter":"البحر: طويل","title":"ألا إنها غمر السخائم والغمر","page":"","text":"ألا إنها غمر السخائم والغمر … جناية من يجني لها ثمر الدهر\nتحن الربى للقطر لا لغمامة … وما تنفع السحب السواري بلا قطر\nسأهجر أبكار القوافي ، فإنني … أراها على الأيام تقتص بالغدر"},{"id":"diwan-radi:257","bookId":"diwan-radi","type":"poem","seq":257,"chapter":"البحر: متقارب تام","title":"ألا رب دوية خضتها","page":"","text":"ألا رب دوية خضتها … وقد قيد العين ديجورها\nوحاجة رمحي ذيالها … وهم جوادي يعفورها\nربأت بها في ذرى قلة … قريب من النجم ديجورها\nكان السماء بها لامة … وزهر النجوم مساميرها"},{"id":"diwan-radi:258","bookId":"diwan-radi","type":"poem","seq":258,"chapter":"البحر: بسيط تام","title":"لما رأيت جنود الجهل غالبة","page":"","text":"لما رأيت جنود الجهل غالبة … والناس في مثل شدق الضيغم الضاري\nنهضت تكتم في برديك سابغة … لفيلق كنجوم الليل جرار\nوالحر تنهضه إما شجاعته … إلى الملم ، وإما خشية العار"},{"id":"diwan-radi:259","bookId":"diwan-radi","type":"poem","seq":259,"chapter":"البحر: رجز تام","title":"صبرا فما الفايز الا من صبر","page":"","text":"صبرا فما الفايز الا من صبر … إن الليالي واعدات بالظفر\nلا بد أن يمضي بما فيه القدر … يلقى الفتى من دهره خيرا وشر\nلا بد أن ينهض جد من عثر … قد ينضب الخلف الغزير ويدر\nورب عظم هيض حينا وانجبر … أخوك من كان مآلا ووزر\nإذا نحا الدهر بناب وعقر … ليس الذي إن جانب الخوف انحسر\nاقبل في الامن وولى في الحذر … ابلغ مقالي العضب الذكر\nذا العنق الاغلب والوجه الاغر … لولاه ما لاقوا بعودي من خور\nولو تعاطاني العدو ما قدر … وكان للخصوم عني مزدجر\nحرمت حظي منه من دون البشر … خصصت بالغلة من ذاك المطر\nوقد سقى البدو وطبق الحضر … عسى الذي ساء قريبا ان يسر\nفليس ظني فيه كاذب الخبر … ولا رجائي ببعيد المنتظر\nقد زاده الله على عظم الخطر … مكارما ذات حجول وغرر\nفات بها كل جواد وطمر … سبقا الى غاية كل مفتخر\nفالله يعشي عنه ناظر الغير … ما طلع النجم ، وأورق الشجر"},{"id":"diwan-radi:260","bookId":"diwan-radi","type":"poem","seq":260,"chapter":"البحر: متقارب تام","title":"ارى ركدة ريحها يرتجى","page":"","text":"ارى ركدة ريحها يرتجى … ومظلمة صبحها ينتظر\nلعل همومك هذي الطوال … سيكشفها فرج مختصر\nفتأمن من حيث يخشى الاذى … كما خبت من حيث يقضى الوطر\nإذا عاد جد كأن لم يزل … وان سر دهر كان لم يضر\nوقالوا انتظرها على بطئها … ومن ضامن العمر للمنتظر\nوهل نافعي يوم أقضي صدى … اذا صاب وادي قومي المطر\nفإن لم يكن فرج في الحياة … فكم فرج في انقضاء العمر"},{"id":"diwan-radi:261","bookId":"diwan-radi","type":"poem","seq":261,"chapter":"البحر: طويل","title":"اذا ضافني هم امل طروقه","page":"","text":"اذا ضافني هم امل طروقه … ببعض الليالي ، أو أضيق به صدرا\nولم أر لي ما يطرد الهم مثله … سماعا يجلي عن ضمير ولا خمرا\nأقول لندماني كرا إلى المنى … وذكر التصابي واندبا ذلك العصرا\nفقد طال ما احدثت عهدا بطيبة … فردا علي القول أحدث به ذكرا\nفما كان الا خلسة ثم انني … رأيت يدي مما علقت به صفرا"},{"id":"diwan-radi:262","bookId":"diwan-radi","type":"poem","seq":262,"chapter":"البحر: رجز تام","title":"ناديته بالرمل والامر ذكر","page":"","text":"ناديته بالرمل والامر ذكر … وقد مضى الورد وأعجز الصدر\nيا عمرو ، ذا الجمة والوجه الأغر … قم اضطرارا جاوز الأمر الخبر\nفقام مشزور القوى على مرر … كانما ناط على الجيد القمر\nمضطرب الازرة وقاد النظر … كانما ينظر من وقبي حجر\nقدح لحاظ كمطارات الشرر … يلهب في ازاره اذا نظر\nكالصل ان جر ذناباه زفر … او الغريري اذا عج هدر\nجرجر لما سيم ضيما وزأر … جرجرة العود بلا طول السفر\nفردها بعد العراك والبهر … واليوم ذو مزادة تنضح شر\nحتى رماني بهواديها ومر … مبتسما كانما قضى وطر"},{"id":"diwan-radi:263","bookId":"diwan-radi","type":"poem","seq":263,"chapter":"البحر: بسيط تام","title":"خذ من صديقك مرأى دون مستمع","page":"","text":"خذ من صديقك مرأى دون مستمع … يا بعد بن عيان المرء والخبر\nوقد يورق العود يوما وهو ذو يبس … وتقبس النار من ذي نعمة حصر\nكذب عليه ، إذا أرضاك ظاهره … شهادة الصادقين السمع والبصر\nوان سمعت فقل ما كان عن اذن … وإن نظرت فقل ما كان عن نظر\nإن كنت لا تصطفي إلا أخا ثقة … فاخلق لنفسك إخوانا على قدر"},{"id":"diwan-radi:264","bookId":"diwan-radi","type":"poem","seq":264,"chapter":"البحر: كامل تام","title":"ياذا المعارج كم سألتك نعمة","page":"","text":"ياذا المعارج كم سألتك نعمة … فمنحتنيها بالذنوب الأوفر\nأي العوارف منك أشكر فضله … عجز المقل وزاد طول المكثر\nاكفأتني ما قد حذرت وقوعه … أم ما كفيت من الذي لم أحذر ؟"},{"id":"diwan-radi:265","bookId":"diwan-radi","type":"poem","seq":265,"chapter":"البحر: بسيط تام","title":"في كل يوم مودات مطلقة","page":"","text":"في كل يوم مودات مطلقة … قد كان أنكحنيها الدهر مغرورا\nيطيب النفس عن قطعي علائقها … اني افارق من فارقت معذورا\nكن في الانام بلا عين ولا اذن … أو لا فعش أبد الأيام مصدورا\nغيب الرجال ظنون قبل مبحثه … فما طلابك أن تلقاه موفورا\nفما نلائم إلا عاد منصدعا … ولا نثقف إلا عاد مأطورا\nمحل البلاد ولا جار تغص به … يضوي الفتى ويكون العام ممطورا\nوالناس اسد تحامي عن فرائسها … اما عقرت واما كنت معقورا\nكم وحدة هي خير من مصاحبة … ينسي الجميع ويغدو الفذ مذكورا\nمن كشف الناس لم يسلم له أحد … الناس داء فخل الداء مستورا"},{"id":"diwan-radi:266","bookId":"diwan-radi","type":"poem","seq":266,"chapter":"البحر: بسيط تام","title":"من شافعي ، وذنوبي عندها الكبر","page":"","text":"من شافعي ، وذنوبي عندها الكبر … إن المشيب لذنب ليس يغتفر\nراحت تزيح عليك الهم صاحية … وعند قلبك من غي الهوى سكر\nرأت بياضك مسودا مطالعه … ما فيه للحب لا عين ولا أثر\nواي ذنب للون راق منظره … اذا اراك خلاف الصبغة الاثر\nوما علليك ونفسي فيك واحدة … إذا تلون في ألوانه الشعر\nأنساك طول نهار الشيب آخره … وكل ليل شباب عيبه القصر\nإن السواد على لذاته لعمى … كما الباض على علاته بصر\nالبيض اوفى وابقى لي مصاحبة … والسود مستوفزات للنوى غدر\nكنت البهيم واعلاق الهوى جدد … واخلقتك حجول الشيب والغرر\nوليس كل ظلام دام غيهبه … يسر خابطه ان يطلع القمر\nأما تريني كصل تحت هضبته … بالرمل اطرق لا ناب ولا ظفر\nمسالما يأمن \\ الاقران عدوته … ملقى الحنية عرى متنها الوتر\nكالفرع ساقط ما يعلوه من ورق … والجفن افرد عنه الصارم الذكر\nان اشهد القوم لا اعلم نجيهم … ماذا قضوا ، ويجمجم دوني الخبر\nكان الشباب الذي انضيت مندله … عقب الخميلة لما صوح الزهر\nمن بعد ما كنت أستسبي المها شغفا … أمست تروع بي الغزلان والبقر\nلم ادر ان الصبا تبلى خميصته … وان منصات ذاك العود ينأطر\nوقد أروع سوام الحي راتعة … ولائد الحي ، مملولا لي العمر\nفقد ارد العفرني عن اكيلته … وازجر الضيغم الغادي فينزجر\nما للزمان رمى قومي فذعذعهم … تطاير القعب لما صكه الحجر\nينفض جماعهم عن كل نائبة … كما تهالك تحت الميسم الوبر\nما كان ضر الليالي لو نفسن بهم … على النوائب ، واستثناهم القدر\nأصبحت بعدهم في شر خالفة … مثل السلى حوله الذؤبان والنمر\nفي كل يوم لرحلي عن نواقرهم … إلى المعاطب مهواة ومحتفر\nأرد نبل الأداني ما رميت بها … فهل إلى الرحم البلهاء لي عذر\n … بمقرب لا يواري عنقه الخمر\nإذا توجس كان القلب ناظره … والقلب ينظر ما لا ينظر البصر\nأجفو له الولد ، مذخورا له شفقي … عليه دونهم الروعات والحذر\nيمسون شعثا وتمسى في بلهنية … كأنما جده عدنان أو مضر\nففي القلوب على حوبائه حنق … وبالعيون الى مضماره شرر\nمن عاطيات تعالى في اعنتها … صك القداح رماها القامر اليسر\nواليوم عريان مشهور بفرجته … يعتم بالنقع أطوارا ، ويأتزر\nكأنهن ذئاب القاع مجفلة … لولا السبيب على الأعناق والعذر\nيطلعن نزو الدبى العامي اونة … أو مطرق القين ينزو تحته الشرر\nتخالهن مزاد الماء اغفلها … بالدو ربط العزالي فهي تبتدر\nسواهما كصوالي النار ألجأها … الى مواقها الشفان والقرر\nتكاد تسبق أيديها نواظرها … إلى الطريدة لولا اللجم والعذر\nاني حلفت بايدي الراقصات ضحى … وبالحجيج وما لبوا وما جمروا\nوالرائحات الى جمع محزمة … مر اليمام دعى اورادها الصدر\nتنوس ركبانها نوس القراط اذا … مالت من السهر الأجياد والعذر\nوما اريق باعلى الخيف من علق … توجى له البدن الملقاة والجزر\nوالبيت قالصة عنه ذلاذله … سوم المخيض جلى عن ركنه الحجر\nلأمطرن بني الديان دامية … هطلى ، تذم بها الأنواء والمطر\nقلو عناء ولان ثرى عديدهم … وربما قل أقوام ، وإن كثروا\n … بالقارعات ولا يأسون من عقروا\nتمسكوا بوصايا اللوم تحسبهم … تتلى عليهم بها الآيات والزبر\nيا أعثر الله أيدي أينق حملت … رحلي الى حيث لا ماء ولا شجر\nمنازل لا يرجى عندها أمل … على الليالي ولا يقضي بها وطر\nمنابت سار فيها قادح عمل … يرمي العروق وعيدان بها خور\nمن كل وجه نقاب العار نقبته … كالعر مر عليه القار والقطر\nيصدى من اللؤم حتى لو تعاوده … ايدي العيون زمانا لانجلى الاثر\nابقوا مخازي لا تعفى مواطنها … على البلاد فضول الريط والازر\nيا طلح رامة لا سقيت من شجر … مذمم الأرض لا ظل ولا ثمر\nكأنني يوم أستدريك من حذر … جاني دم طاح لا منجى ولا وزر\nسيان عندي وأيدي الحي جامدة … ان اخطأ القطر زاديهم وان مطروا\nما كل مثمرة تحلو لذايقها … إن السياط لها من مثلها ثمر\nالوم من لا يعد اللؤم منقصة … وضاع عتب مسئ ليس يعتذر\nيا نفس لا تهلكي يأسا ، ولا تدعي … لوك الشكائم حتى ينجلي العمر\nقالوا انتظرها وان عزت مطالبها … هل ينظر القدر الجاني فانتظر\nألقى المطامع مبتوتا حبائلها … للرزق والرزق لا الداني ولا القفر\nطأ من رجائك لا الاطواد مورقة … يوما ولا جندل البقعاء معتصر\nليل من الهم لا يدعى السمير له … أعمى المطالع لا نجم ولا سحر\nأنقل النفس من صبر إلى جزع … والصبر أعود إلا أنه صبر"},{"id":"diwan-radi:267","bookId":"diwan-radi","type":"poem","seq":267,"chapter":"البحر: طويل","title":"أرى ماء وجه المرء من ماء عرضه","page":"","text":"أرى ماء وجه المرء من ماء عرضه … فحذرك لا يقطر على العار قاطره\nفان انت لم تستبق بالصون بعضه … تتابع مطلولا على الذل سائره\nتنكر هذا الناس بعدك للندى … وأقلع من نوء المكارم ماطره\nفاولاهم بالحمد من لان رده … ومن حسنت علاته ومعاذره"},{"id":"diwan-radi:268","bookId":"diwan-radi","type":"poem","seq":268,"chapter":"البحر: طويل","title":"تجاف عن الاعداء بقيا فربما","page":"","text":"تجاف عن الاعداء بقيا فربما … كفيت فلم تجرح بناب ولاظفر\nولا تبر منهم كل عود تخافه … فان الاعادي ينبتون مع الدهر"},{"id":"diwan-radi:269","bookId":"diwan-radi","type":"poem","seq":269,"chapter":"البحر: طويل","title":"ولولا هناة والهناة معاذر","page":"","text":"ولولا هناة والهناة معاذر … لطارت برحلي عنك بزلاء ضامر\nوشيعت اظعانا كأن زهاؤها … بجانب ذي القلام نخل مواقر\nمفارق دار طأطأ الذل أهلها … وما عز دار ليس فيها معاشر\nأقمت على ما ساء أذنا ومقلة … عماعم يبنون العلى وكراكر\nأبيت رميضا صاليا حر زفرة … لليلي من زور الملمات سامر\nارقت ولم يأرق معي من رجوته … ليومي ، إذا دارت علي الدوائر\nاقام على دار القطيعة والقلى … يشاور فيما ساءني ويؤامر\nرماني عن قوس العدو وقال لي … امامك اني من ورائك ثائر\nوعندي لتبديل الديار مناخة … توقع ما تملي علي المقادر\nأقول : غدا ، والشر أقرب من غد … أبى الضيم أن يبقى بعشك طائر\nفما انت نظار وغيرك رائح … ونضوك موموم ورحلك قاتر\nاذا لم يكن لي ناصر من عشيرتي … فلي من يد المولى وان ذل ناصر\nواني وان قلوا لمستمسك بهم … وقد تمسك الساق المهيض الجبائر\nوبعض موالي المرء يغمز عوده … كما غمز القدح الخليع المقامر\nوقد كان مولى الزبرقان هراسة … لها واخذ في الأخمصين وناقر\n … وجار الايادي الحذافى واقر\nوقد كان فيها للسموأل عذرة … ومن رام عذرا أمكنته المعاذر\nولكنه اصغى لما قال لائم … فاوفى ولم يحفل بما قال عاذر\nفلا يغررنك ثغرا بن حرة … تبسم للأعداء والصدر واغر\nشكا الناس يبكي قلبه ولسانه … وان كتمت عنك الدموع النواظر\nتواكله الخلان حتى حسامه … وأعوانه ، حتى الجنان الموازر\nوما كنت إلا كالموارب نفسه … بغى ولدا ، والعرس جداء عاقر\nوهل ينفعن الطارقين على الطوى … إذا غاب جود المرء والزاد حاضر\nيفوز الفتى بالحمد والمال ناقص … وتتبع موفور الرجال المعائر\nولو كنت في فهر لقام بنصرتي … غضوب اذا لم يغضب الحي غائر\nوسدد من دوني سنانا كأنه … إلى الطعن ناب يقلس السم قاطر\n … أدر عليها لقحة الطعن عامر\n … من الطعم يوما ، أدركته الأظافر\nويأبى الفتى ، والسيف يحطم أنفه … وفي الناس مصبور على السيف صابر\nولو يأبى العوام كان مناخها … لغامر عنها اللوذعي المغامر\nوراحت طرابا لم تشمس رحالها … ولا نعرت منها القدور النواغر\nسوارح لم يدفع عن الرعي دافع … لئيم ولم ينهر عن الماء زاجر\nفتلتم على ضلعاء منقوضة القوى … اذا ما استمرت بالرجال المرائر\nسهامكم في كل عار سديدة … وسهمكم في مرشق المجد عائر\nوما كنتم لجم الجوامح قبلها … فتثنونني إن أعجلتني البوادر\nإذا ما دعوا لليوم ذي الخطب أصفحوا … صدور الحرابى ارمضتها الهواجر\nكأن بكورا من نطاة وخيبر … لها ناحط منهم رميض وناعر\nوما انا الا اكلة في رحالهم … \nولولا ابو العوام لم يملكوا العلى … على الناس الا ان تشب النوائر\nولم يرفعوا بين الغوير وحاجر … قبابهم ما دام للبدن ناحر\nأرد على قومي فضول تغمدي … وإني على ما ساء قومي لقادر\nوإني لأستأني حلوم عشيرتي … ليعدل منآد ، ويرجع نافر\nوأطلس مناني الكذاب ، وقال لي : … ليهنك احدى الليلتين لباكر\nينافط فيها هجرس وهو نائم … وجرر فيها هجرس وهو فاتر\nتشبه بالمجرين في حلبة الندى … أقم وادعا ، يا عمرو ، إنك عاثر\nوأهملها مرعية في ضمانه … زمان ادعى نسيانها ، وهو ذاكر\nرآها على علاتها ظهر صعبة … تحادر من ارقاصها وتحادر\nفأحجم عنها هائبا نزواتها … وطار عليها الشحشحان المخاطر\nرأى سيفه فيها فعض بنانه … فالا ابا الغلاق كنت تبادر\n … عليه برمان القروم الخواطر\nتطاوح والاوراد تركب عنقه … خواطر ما دون الردى وكواسر\nواني مليء ان بقيت لعرضكم … بشوه المجالي تحتهن النواقر\nعلالة ركبان الظلام ، إذا ونوا … من السير مرفوع بهن العقائر\nقوارع من تخبط يعد وهو موضح … اميم ومن تخطيء يبت وهو ساهر\nبواق باعراض الرجال خدوشها … كما رقشت رق الأبيل المزائر\nحقيبة شر بئس ما اختار ريها … اذا نفضت عند الاياب المآزر\nنلمكم ، والله يصدع شعبكم … ولا يجبر الاقوام ما الله كاسر\nاحن الى قومي كما حن نازع … إلى الماء قد دانى له القيد قاصر\nتذكر جونا بالبطاح تلفه … بمنتضد الدوح الغمام المواطر\nوجنت عليه ليلة عقربية … لها سائل في كل واد وقاطر\nيا بطح معشاب كان نطافه … دموع العذارى أسلمتها المحاجر\nيبيت على الماء الذي في ظلاله … كنانة والحيان كعب وعامر\nلهم في كفاف الأرض شرقا ومغربا … عماعم ينبون العلى وكراكر\nأداروا رحى بالأعوجيات قمحها … صدور المواضي والرؤوس النوادر\nهم نشطوني منشط السجل بعدما … تطاوحه الجولان والقعر غاير\nومدوا يدي من بعد ما كان مطرحي … من الأرض مجرورا عليه الجرائر\nوقواشرها واليوم مستوجف الحشا … له أبجل من عائذ الطعن فائر\nوما غير دار المرء الا مذلة … ولا غير قوم المرء الا فواقر\nواخليت من قلبي مكانا لذكرهم … وقد يذكر البادي وتنسى الحواضر"},{"id":"diwan-radi:270","bookId":"diwan-radi","type":"poem","seq":270,"chapter":"البحر: طويل","title":"فيا عجبا مما يظن محمد","page":"","text":"فيا عجبا مما يظن محمد … وللظن في بعض المواطن غرار\nيقدر أن الملك طوع يمينه … ومن دون ما يرجو المقدر أقدار\nله كل يوم منية وطماعة … ونبذ قريض بالاماني سيار\nلئن هو اعفى للخلافة لمة … لها طرر فوق الجبين وأطرار\nوأبدى لها وجها نقيا كأنه … وقد نقشت فيه العوارض ، دينار\nورام العلى بالشعر والشعر دائبا … ففي الناس شعر خاملون وشعار\nوإني أرى زندا تواتر قدحه … ويوشك يوما ان تشب لنا النار"},{"id":"diwan-radi:271","bookId":"diwan-radi","type":"poem","seq":271,"chapter":"البحر: طويل","title":"رموا بمرامي بغيهم ، فاتقيتها","page":"","text":"رموا بمرامي بغيهم ، فاتقيتها … وقلت لهم بيني وبينكم الدهر\nكاني بكم لا تستطيعون حيلة … وليس لكم نهي يطاع ولا امر"},{"id":"diwan-radi:272","bookId":"diwan-radi","type":"poem","seq":272,"chapter":"البحر: وافر تام","title":"بغى الذلان غايتنا ، وأنى","page":"","text":"بغى الذلان غايتنا ، وأنى … يقام المجد بالعمد القصار\nوأهتكهم لكل خباء نقع … إذا ما مد أطناب الغبار\nكأن الدمع فوق الخد منها … حباب يستدير على عقار"},{"id":"diwan-radi:273","bookId":"diwan-radi","type":"poem","seq":273,"chapter":"البحر: متقارب تام","title":"لا مثالها يسخر الساخر","page":"","text":"لا مثالها يسخر الساخر … لقد ذل جارك يا عامر\nتراه لقى بين أيدي الخطو … ب ، لا أنت ناه ولا آمر"},{"id":"diwan-radi:274","bookId":"diwan-radi","type":"poem","seq":274,"chapter":"البحر: رجز تام","title":"اما تراها كالجراز البتار","page":"","text":"اما تراها كالجراز البتار … تحتلق القوم احتلاق الأشعار\nحي على السير ، وحي قد سار … "},{"id":"diwan-radi:275","bookId":"diwan-radi","type":"poem","seq":275,"chapter":"البحر: طويل","title":"وعين عوان بالدموع وغيرها","page":"","text":"وعين عوان بالدموع وغيرها … من الدمع يعرورى جوانبها بكر\nتمطت بي العشرون حتى رمين بي … الى غاية من دونها يقطع العمر"},{"id":"diwan-radi:276","bookId":"diwan-radi","type":"poem","seq":276,"chapter":"البحر: طويل","title":"يقولون نم في هدنة الدهر آمنا","page":"","text":"يقولون نم في هدنة الدهر آمنا … فقلت : ومن لي أن يهادنني الدهر\nهل الحرب الا ماترون نقيصة … من العمر ، أو عدم من المال أو عسر\nفلا صلح حتى لا يكون لواجد … ثراء ، ولا يبقى على وافر وفر"},{"id":"diwan-radi:277","bookId":"diwan-radi","type":"poem","seq":277,"chapter":"البحر: طويل","title":"تطاير في مر العجاج كأنها","page":"","text":"تطاير في مر العجاج كأنها … أجادل حطتها سغابا وكورها\nلها بين جنبي ضرغد قضربة … غريرية يهدي الضيوف زفيرها"},{"id":"diwan-radi:278","bookId":"diwan-radi","type":"poem","seq":278,"chapter":"البحر: طويل","title":"أيا ربة الخدر الممنع بالقنا","page":"","text":"أيا ربة الخدر الممنع بالقنا … اتنأين لم تنظر بك العين منظرا\nومن عجب اصفيتك الود بعدما … تعاطى القنا قومي وقومك أعصرا"},{"id":"diwan-radi:279","bookId":"diwan-radi","type":"poem","seq":279,"chapter":"البحر: بسيط تام","title":"اناشد انت اطلالا بذي القور","page":"","text":"اناشد انت اطلالا بذي القور … أضلها جولان القطر والمور\nفما أحيل عليهم عند نازلة … لكن احيل على ذنب المقادير\nان تقتطعه الاعادي عن مذاهبه … فرب ابيض مغمود لمنشور"},{"id":"diwan-radi:280","bookId":"diwan-radi","type":"poem","seq":280,"chapter":"البحر: متقارب تام","title":"ومن عامر غلمة كالسيوف","page":"","text":"ومن عامر غلمة كالسيوف … جريال اوجههم يقطر\nاذا صدئ القوم لا يصدأون … كأنهم الذهب الأحمر"},{"id":"diwan-radi:281","bookId":"diwan-radi","type":"poem","seq":281,"chapter":"البحر: طويل","title":"رأيت شباب المرء ليلا يجنه","page":"","text":"رأيت شباب المرء ليلا يجنه … يغطي على بادي العيوب ويستر\nوشيب الفتى صبح يبين عواره … ويرمق فيه بالعيون فينظر\nفإن ضلالي في النهار لهجنة … وإن ضلالي في دجى الليل أعذر"},{"id":"diwan-radi:282","bookId":"diwan-radi","type":"poem","seq":282,"chapter":"البحر: طويل","title":"صبرت على عرك النوائب فيكم","page":"","text":"صبرت على عرك النوائب فيكم … وقد بلغ المجلود أو غلب الصبر\nوقيدني مر الحفاظ بداركم … وأطلق غيري من حبالكم العذر\nفما كان لولاكم يمر لي الغنى … ويحلو إلى قلبي الخصاصة والفقر"},{"id":"diwan-radi:283","bookId":"diwan-radi","type":"poem","seq":283,"chapter":"البحر: متقارب تام","title":"وافلتهن ابو عامر","page":"","text":"وافلتهن ابو عامر … يقبل ناصية الاشقر\nيقول اذا ارهقته الرماح ا … إن لم تزد عنقا تعذر\nسليبا يخفف حتى رمى … من الرعب بالدرع والمغفر"},{"id":"diwan-radi:284","bookId":"diwan-radi","type":"poem","seq":284,"chapter":"البحر: رجز تام","title":"لهذه كان الزمان ينتظر","page":"","text":"لهذه كان الزمان ينتظر … لم يبق من بعدك للمجد وطر\nتامرني بالصبر هيهات لقد … هان على الاملس ما لاقى الدبر\nلولا ظبى سيفك في صدورها … لما نهي فيها الردى ولا امر"},{"id":"diwan-radi:285","bookId":"diwan-radi","type":"poem","seq":285,"chapter":"البحر: بسيط تام","title":"لا يغررنك سلم جاء يطلبه","page":"","text":"لا يغررنك سلم جاء يطلبه … لم يخطب السلم إلا بعدما عقرا\nأعطى يدا بعدما شلت أناملها … وأسلم النفس لما لم يجد وزرا"},{"id":"diwan-radi:286","bookId":"diwan-radi","type":"poem","seq":286,"chapter":"البحر: خفيف تام","title":"رب ناء الملاط يحسب جيدا","page":"","text":"رب ناء الملاط يحسب جيدا … حائلا بين غرضه وصداره\nان ثناه الزمام جرجر كال … عد بالليل لج في قرقاره\nوكأن اللعام يسقط من في … ه هوافي ما طم من أوباره"},{"id":"diwan-radi:287","bookId":"diwan-radi","type":"poem","seq":287,"chapter":"البحر: رجز تام","title":"أغلب لا يخشى وعيد السفر","page":"","text":"أغلب لا يخشى وعيد السفر … كانما يدعونه بالرجز"},{"id":"diwan-radi:288","bookId":"diwan-radi","type":"poem","seq":288,"chapter":"البحر: رجز تام","title":"كم قابس عاد بغير نار","page":"","text":"كم قابس عاد بغير نار … لابد للمسرع من عثار"},{"id":"diwan-radi:289","bookId":"diwan-radi","type":"poem","seq":289,"chapter":"البحر: مجزوء الكامل","title":"اطمح بطرفك هل ترى","page":"","text":"اطمح بطرفك هل ترى … الا مصابا أو معزا\nنأبى التعزي ، ثم يل … حقنا الزمان بمن تعزى\nأغدو وراء الذاهبي … ن تهزني الزفرات هزا\nلا ناظرا اثرا ولا … متوجسا للقوم رزا\nابكي ظبي فجعت يدي … منها باصدقها مهزا\nقد كنت صلب العود لا … يجني الزمان علي غمزا\nحتى مضى بكم يؤز … ركم القضاء الجدازا\nلم أستطع منعا ، فيا … لله عزما عاد عجزا\nهل غادروا إلا حشا … قلقا وقلبا مستفزا\nأمسي كأن من القنا … بأضالعي قرعا ووخزا\nيا ثانيا للنفس ، بل … يا ثالث العينين عزا\nعضو عثت فيه المنية … ما اجل وما اعزا\nعز الحمام عليك ان … ن القرن إن ما عز بزا"},{"id":"diwan-radi:290","bookId":"diwan-radi","type":"poem","seq":290,"chapter":"البحر: كامل تام","title":"شرف الخلافة يا بني العباس","page":"","text":"شرف الخلافة يا بني العباس … اليبوم جدده ابو العباس\nوافى لحفظ فروعها وكنيه … كان المشير مواضع الأغراس\nهذا الذي رفعت يداه بنا … ئها العالي وذاك موطد الاساس\nذا الطود بقاه الزمان ذخيرة … من ذلك الجبل العظيم الراسي\nملك تطاوح مالكوه وأصبحوا … منه وراء معالم أدراس\nغاب أبن به ضراغم هاشم … من كل أغلب للعدى فراس\nحتى نبا بهم الزمان فازعجوا … عن تلكم الأغيال والأخياس\nفاليوم لم العز بعد تشعت … وأعيد ذكر الدين بعد تناس\nقد كان زعزك الزمان فراعه … عود على عجم النوائب عاس\nما كان غير مجرب لك في العلى … لتكون راعي الامر دون الناس\nفبلاك عيب البأس يوم كريهة … ورآك طود الحلم يوم مراس\nفلأنت قائم سيفها الذرب الشبا … مجدا ووابل نؤها الرجاس\nمن معشر وسموا الزمان مناقبا … تبقى بقاء الوحي في الأطراس\nمترادفين على المكارم والعلى … متسابقين إلى الندى والباس\nطلعوا على مروان يوم لقائه … من كل أروع بالقنا دعاس\nسدوا النجاء عليه دون جمامه … بقراع لا عزل ولا نكاس\nبالزاب والآمال واقفة الخطى … بين الرجاء لنيلها والياس\nحتى رأى الجعدي ذل قياده … ليد المنون تمد بالأمراس\nوهوت به أيد أناملها القنا … مهوى كليب عن يدي جساس\nضربوه في بطن الصعيد بنومة … \nوتسلموها غضة ، فمضى بها … الأبرار ناشزة عن الأرجاس\nفالان قر العز في سكناته … ثلج الضمائر بارد الأنفاس\nوقفت أخامص طالبيه ، ورفهت … ايد نفضن معاقد الاجلاس\nواحتل غاربه ولي خلافه … ما كان يلبسها على ألباس\nسبق الرجال إلى ذراها ناجيا … من ناب كل مجاذب نهاس\nيقطان يخرج في الخطوب وينثني … ولهاه للكلم الرغيب أواس\nويرق أحيانا ، وبين ضلوعه … قلب على المال المثمر قاس\nتغدوا ظبا البيض الرقاق بقلبه … احلى واعذب من ظباء كناس\nوكأن حمل السيف يقطر غربه … أنسى يمين يديه حمل الكاس\nاحسود ذي الثغر الشوادخ انها … حرم على الاغيار للافراس\nلا تحسدن قوما اذا فاضلتهم … فضلوك في الأخلاق والأجناس\nواذا رميت الطرف راعك منهم … أطلال أجبال عليك رواس\nكانوا نجوما ثم شعشع نورهم … والنار أولها من الأقباس\nمجد امير المؤمنين اعدته … غضا كنور المورق المياس\nوبعثت في قلب الخلافة فرحة … دخلت على الخلفاء في الأرماس\nومكيدة أشلى عليك نيوبها … غضبان للقربى القريبة ناس\nفغرت اليك ففتها وتراجعت … ففرته بالأنياب والأضراس\nحمراء من جمر الخطوب وطئتها … فلبست فيها الصبر اي لباس\nفردا سلكت بها المضيق وإنما … طرق العلاء قليلة الإيناس\nاورق امين الله عودي انما … أغراس أصلك في العلى أغراسي\nواملك على من كان قبلك شاؤه … في فرط تقريبي ، وفي إيناسي\nإني لأجتنب السؤال متاركا … خلفا يدر علي بالإبساس\nولقد اطعتك طاعة مارامها … مني امرؤ الا عصاه شماسي\nفرت إليك ، بغير داع ، همتي … وصغا إليك ، بلا قياد ، راسي"},{"id":"diwan-radi:291","bookId":"diwan-radi","type":"poem","seq":291,"chapter":"البحر: طويل","title":"تمنى رجال نيلها ، وهي شامس","page":"","text":"تمنى رجال نيلها ، وهي شامس … واين من النجم الاكف اللوامس\nوإن المعالي عن رجال طلائق … وهن على بعض الرجال حبائس\nولم أر كالعلياء ترضى على الأذى … وتهوى على علاتها ، وهي عانس\nفقل للحسود اليوم أغض على القذى … فما كل نار أوقدت أنت قابس\nوما لك والاقدام بالخيل والقنا … وحظك عن نيل العلى متقاعس\nوهل نافع يوما وجدك راجل … اذا قيل يوم الروع انك فارس\nفطب عن بلوغ العز نفسا لئيمة … فمتا للعلى الا النفوس النفائس\nوإن قوام الدين من دون ثغرها … له ناظر يقظان والنجم ناعس\nرعاها بهم لا يمل وهمة … إذا نام عنها حارس قام حارس\nأخو الحرب ذاق الرائعات وذقنه … ونال ، ونالته القنا والفوارس\nيغاديك يوم السلم طلقا ، وفكره … يمارس حد الروع فيما يمارس\nكان ملوك الارض حول سريره … بغاث وقوف والقطامي جالس\nاذا رمقوه والجفون كواسر … على غير داء والرقاب نواكس\nيحيون وضاحا ، كأن جبينه … سنا قمر ما غيرته الحنادس\nتصرف اعناق الملوك لامره … وتستخدم الأعضاء والرأس رائس\nمن القوم حلوا بالربى وأمدهم … قديم المساعي ، والعلاء القدامس\nتحلهم دار العدو شفارهم … وترعيهم الأرض القني المداعس\nبهاليل ازوال بكل قبيلة … ملاذع من نيرانهم ومقابس\nوما جلسوا الا السيوف معدة … ليوم الوغى ، والمرء ممن يجالس\nاذا اخطئوا مرمى من المجد اجهشوا … زئير الضواري افلتتها الفرائس\nفمن خائض غمر الردى غير ناكص … ومن صافق يوم الندى لا يماكس\nاذا ما اجتداه المجتدون على الطوى … يبيت رطيب الكف والبطن يابس\nله في الاعادي كل شوهاء يهتدي … بتهدارها طلس الذئاب اللغاوس\nونشاجة تحت الضلوع مرشة … كما هاع مملوء من الخمر قالس\nمطرقة الجالين هطلى كأنما … \nألا رب حي من رجال أعزة … أسالت بهم منك الغمام الرواجس\nأرادوك بالأمر الجليل فردهم … على عوج الاعقاب جد ممارس\nتطاعنهم عنك السعود بجدها … ولا يتقي طعن المقادير تارس\nاذا افلتوا طعن الرماح رمتهم … بطعن عواليها النجوم الاناحس\nسلبتهم عز الثراء ، فلم تدع … لهم ما يرى منه العدو المنافس\nفما لهم ، غير الشعور ، عمائم … ولا لهم ، غير الجلود ، ملابس\nوعمتهم من حد بأسك سطوة … بها اجتدعت اعناقهم لا المعاطس\nفما جازها في ذروة النيق صاعد … ولا فاتها في لجة الماء قامس\nولا ناطق للخوف إلا مخافت … ولا ناظر للذل إلا مخالس\nترى الاب ينبو عن بنيه ويتقي … اخاه الفتى وهو القريب الموانس\nوليس يحيا منهم اليوم طالع … هوانا ولا يجدي اذا اعتام بائس\nتملس أعواد القنا من أكفهم … وينفضهم من عن قطاها العوانس\nيكون مزر المرء غلا لعنقه … من الخوف ، حتى ينزع الثوب لابس\nإذا ضربوا في الأرض فهي مهالك … وإن أوطنوا الأبيات فهي محابس\nوعاطسهم في الحفل غير مشمت … فكالنابح العاوي من القوم عاطس\nواطرق شيطان الغواية منهم … فلم يبق من نعابة الغي نابس\nوعند طبيب المعضلات شفاؤهم … إذا عاد من داء العداوة ناكس\nفيوماه يوم بالمواهب غائم … علينا ويوم بالقواضب شامس\nسجية بسام يقول عدوه … أهذا الذي يلقى الوغى وهو عابس\nنزاد ، ويروى الأبعدون بمائكم … ونحن على الورد الظماء الخوامس\nوتندى لقوم آخرين سحابكم … ونحن مناشي ارضكم والغرائس\nرجوتك والعشرون ما تم عقدها … فلم انا من بعد الثلاثين آيس\nولي خدمة قدمتها لتعزني … ولولا الجنى ما رجب الفرع غارس\nوما همتي الا المعالي وانني … على المرء بالعلياء لا المال نافس\nوقد غار حظ أنت ثاني جماحه … وتقدع من بعد الجماح الشوامس\nعسى ملك الأملاك ينتاش أعظما … برتهن ذؤبان الليالي النواهس\nوقد كنت شمت العز منك وجادني … بغيظ الأعادي ماطر منه راجس\nفباعدني من صوب مزنك حاسد … يضاحك ثغري والجنان معابس\nيريني حنانا وهو يضمر بغضه … كلا ناظرينا من قلى متشاوس\nفجدد يدا عندي يرف لباسها … فقد اخلقت تلك الايادي اللبائس\nوبابك اولى بي من الارض كلها … فحتام لي عن قرع بابك حابس\nواقسم لولا ان دارك فارس … لما انتصفت من ارض بغداد فارس"},{"id":"diwan-radi:292","bookId":"diwan-radi","type":"poem","seq":292,"chapter":"البحر: طويل","title":"أقول لركب خابطين إلى الندى","page":"","text":"أقول لركب خابطين إلى الندى … رموا غرضا والليل داجي الحنادس\nأقيموا رقاب اليعملات ، فإنني … سأستمطر النعماء نوءا بفارس\nبنانا إذا سيم الحيا غير باخل … ووجها اذا سيل الندى غير عابس\nأحب ثرى أرض أقمت بجوها … وان كان في ارض سواها مغارسي\nوكم رفعت لي نار حي فجزتها … وما نار ممنون القرى من مقابسي\nنزعت فخاري يوم البس نعمة … لغيرك ، ما زرت علي ملابسي\nاذا كنت لي غيثا فانت غرستني … ومورق عودي بالندى مثل غارسي\nتركت رجالا لم يهشوا لمنة … ولم ينقعوا غل الظماء الخوامس\nعلى القرب إني فيهم غير طامع … ومنك على بعد المدى غير آيس\nغياث الندى ضمت اكف واغلقت … على اللؤم ابواب النفوس الخسائس\nولولاك أمسى الناس في كل مذهب … على اثر من معلم الجود طامس\nعضلت ثنائي عنهم وذخرته … لأبلج ممنون النقيبة رائس\nوما كنت إلا الطرف يمنع ظهره … جبانا ويعطي ظهره كل فارس"},{"id":"diwan-radi:293","bookId":"diwan-radi","type":"poem","seq":293,"chapter":"البحر: مجزوء الكامل","title":"لا ترقدن على الأذى","page":"","text":"لا ترقدن على الأذى … واعزم كما عزم ابن موسى\nلما ألظ به العدى … عنتا ، وأضرارا وبوسا\nورموا إليه نواظرا … كاسنة اليزني شوسا\nأغضى لهم ، وأثار لي … الغاب يقتنص النفوسا\nغضبان يغلي بالزماجر … جر كلما نظر الفريسا\nيتنكب اللحم الذلي … ل ويطلب العضو الرئيسا\nاظننتموه على الاذى … في داركم أبدا حبيسا\nإن الذلول على القوا … عاد بعدكم شموسا\nوارم مثل الصل ينتظر … تظر التي تشفي النسيسا\nحتى أحد لكم حسا … ما قاطعا نغض الرؤوسا\nاما عقرن ظباه اعجلن … ظباه أع\nان تفجئوا بدخانها … فيعقب ما شجر الوطيسا\nكيدا سرى لكم ، ولم … تسمع له أذن حسيسا\nقد ينزع اللين الكريم … ويلبس الخلق الشريسا\nوتكون طلقا ثم يؤنس … نس ذلة فيرى عبوسا\nويعود مر الطعم لا … عذب المذاق ولا مسوسا\nجلن العقاير أن تكوسا … كن طرقت لكم ببوسى\nوغمطتم تلك السعود … فابدلت بكم نحوسا\nوأهنتم ثوب العلى … فغدى الهوان لكم لبوسا\nمن بعد ما حلتكم ال … علياء جوهرها النفيسا\nحتى ظننا الله ليس … س برازق إلا خسيسا\nيا حسنكم في الدهر أذ … نابا واقبحكم رؤوسا\nخلوا الطريق لمن تع … ان تجربه خميسا\nودعوا السياسة في العلى … لأغر يحسن أن يسوسا\nهذا خمار فتى ادار م … ر من البلاء لكم كؤوسا"},{"id":"diwan-radi:294","bookId":"diwan-radi","type":"poem","seq":294,"chapter":"البحر: كامل تام","title":"يا ذاكر النعماء إن نسيت","page":"","text":"يا ذاكر النعماء إن نسيت … ومجدد المعروف ان درسا\nومنبه الآمال ان رقدت … بالطول لا اغفى ولا نعسا\nنصل اذا وقف النصول مضى … جبل إذا اضطرب الجبال رسا\nلله بحر ما هتفت به … حتى استهل على وانبجسا\nأجممت جمته ، ففاض بها … يطأ الربى ويبلل اليبسا\nزخرت غواربه إلي ، ولم … يقل الرجاء لعلما وعسا\nوأغر مختلس مكارمه … إن الكريم يرى الندى خلسا\nغرس الصنائع ثم عاد به … عود الندى فسقى الذي غرسا\nكالعضب فيه صاقل عمل … ينفي القذى ويباعد الدنسا\nمن معشر ركبوا المكارم في … أولى الزمان مصاعبا شمسا\nشغلوا ملابسها فلم يدعوا … للناس الا الدنس اللبسا\nالعاطفون ، إذا الصديق نبا … والمحسنون اذا الزمان اسا\nواذا خناق الكرب ضاق بنا … ردوا النفوس ورددوا النفسا\nما ضر من مطروا ببلدته … إن كان ماء المزن محتبسا\nلا أزلق اليوم العبوس لكم … قدما ، ولا أطفى لكم قبسا\nلا تفترن على الزمان ، وإن … عثر الزمان بعزكم تعسا"},{"id":"diwan-radi:295","bookId":"diwan-radi","type":"poem","seq":295,"chapter":"البحر: بسيط تام","title":"خذي حديثك من نفسي عن النفس","page":"","text":"خذي حديثك من نفسي عن النفس … وجد المشوق المعنى غير ملتبس\nالماء في ناظري والنار في كبدي … إن شئت فاعترفي ، أو شئت فاقتبسي\nكم نظرة منك تشفي النفس عن عرض … وترجع القلب مني جد منثكس\nتلذ عيني وقلبي منك في الم … فالقلب في مأتم والعين في عرس\nكم الفؤاد ، حبيسا ، غير منطلق … ودمع عيني ، طليقا ، غير منحبس\nعلى الزمان على الخلصاء يسمح لي … يوما بذاك اللمى الممنوع واللعس\nيقول مني كأن الحب اوله … فكيف أذكرني هذا الضنا ونسي\nقل لليالي فري نحضي على بدني … او فاعرقيني بالانياب وانتهسي\nخذي سلاحك لي ان كنت اخذة … قد امكن الناشط الذيال وافترسي\nفكم اريغ العلى والحظ في صبب … وكم أقول : لعا ، والجد في تعس\nنذبذب الرزق لا فقر ولا جدة … حظ لعمرك لم يحمق ولم يكس\nفي كل يوم بسربي منك غادية … إحالة الذئب باد غير مختلس\nفوهاء تفغر نحوي ، وهي ساغبة … شجو الوليد اذا ماعب في النفس\nيا يؤس الدهر ألقاني بمسبعة … وقال لي عند غيل الضيغم احترس\nمضر الرجال الاولى كانت نقائبهم … لا بالرجاع ، ولا المبذولة اللبس\nوصرت أهون عند الحي بعدهم … مما على الابل الجربا من العبس\nاستنزل الرزق من قوم خلائقهم … شمس الاعنة عند الزجر والمرس\nيستبدلون بي الأبدال معجزة … من يرضى بالعير يهجر كامل الفرس\nالعرض يترك للرامي بمضيعة … والمال يحفظ بالأعوان والحرس\nيحصنون على الراجي مطالعه … خوفا من السلة الحذاء والخلس\nاصبحت حين اريغ النفع عندهم … كناشد الغفل بين العمي والخرس\nلقد زللت وكانت هفوة امما … أيام أرجو الندى الجاري من اليبس\nوان اعجز من لاقيت ذو امل … يرجو الصلا عند زند ضن بالقبس\nأيا الذوائب من قومي أوازنهم … لقد وزنت الصفا العادي بالدهس\nيا صاحبي اشددا النضوين ، وانطلقا … إن سلم الله أفجرنا من الغلس\nلا تنظرا غير وعد السيف آونة … من لم يرس بذباب السيف لم يرس\nسيرا عن الوطن المذموم واتبعا … الى الاباء قياد الانفس الشمس\nولا تقيما على صعب مغالقه … بعرضه ما بثوبيه من الدنس"},{"id":"diwan-radi:296","bookId":"diwan-radi","type":"poem","seq":296,"chapter":"البحر: سريع","title":"قربت بالبعد من الناس","page":"","text":"قربت بالبعد من الناس … وفضت الأطماع بالياس\nإلا بقايا من جميع الهوى … تهفو بلب الجبل الراسي\nدمعي كجودي عند بذل الندى … وحر بأسي مثل انفاسي\nوجهي رقيق يستشف الحيا … منه ، وقلبي دونه قاس\nلاحظ في المجد لمن لم يزل … في حيز الإبريق والكاس\nكل غلام رام خدع العلى … يلطف في بري وايناسي"},{"id":"diwan-radi:297","bookId":"diwan-radi","type":"poem","seq":297,"chapter":"البحر: طويل","title":"بقاء الفتى مستأنف من فنائه","page":"","text":"بقاء الفتى مستأنف من فنائه … وما الحي الا كالمغيب في الرمس\nارى الناس ورادين حوضا من الردى … فمن فارط أو بالغ الورد عن خمس\nويجري على من مات دمعي وما له … بكيت ولكني بكيت على نفسي\nوكل فتى باق سيتبع من مضى … وكل غد جاء سيلحق بالأمس\nفلا يبعدنك الله من متفرد … رأى الموت انسا فاستراح الى الانس\nأقول وقد قالوا مضى لسبيله … مضى غير رعديد الجنان ولا نكس\nكان حداد الليل زاد سواده … عليك ورد الضوء من مطلع الشمس\nأرى كل رزء دون رزئك قدره … فليس يلاقيني ليومك ما ينسي"},{"id":"diwan-radi:298","bookId":"diwan-radi","type":"poem","seq":298,"chapter":"البحر: وافر تام","title":"بقلبي للنوئب جانحات","page":"","text":"بقلبي للنوئب جانحات … عماق القعر موئسة الاواسي\nاقارع شغبها لو كان يغني … قراعي للنوائب أو مراسي\nوتعذمني فتخطي صفحتيها … عذامي يوم اعذم أو ضراسي\nكأني بين قادمتي نزور … تراوح بين ولغي وانتهاسي\nولم يلبثن غربان الليالي … نغيقا ان اطرن غراب راسي\nوما زال الزمان يحيف حتى … نزعت له على مضض لباسي\nنضى عني السواد بلا مرادي … وأعطاني البياض بلا التماسي\nاروع به الظباء وقد اراني … زميلا للغزال إلى الكناس\nلمسقط حامل الشعرات عني … بحد السيف في اليوم الغماس\nأحب إلي من نزعي رداء … كسانيه الشباب واي كاس\nواخلق وهو يذكرني التصابي … وعود النبع يغمز وهو عاس\nوددت بان ما تخبى المواضي … بدال لي بما جنت المواسي\nوبغضني المشيب الى لداتي … وهونني البقاء على أناسي\nخذوا بأزمتي فلقد أراني … قليلا ما يلين لكم شماسي\nاليس الى الثلاثين انتسابي … ولم أبلغ إلى القلل الرواسي\nفمن دل المشيب على عذاري … وما جر الذيول على غراسي\nسابكي للشباب بشاردات … كصاردة السهام عن القياس\nيعلل شدوها الطلح المعنى … اذا سقط العصي من النعاس\nفمن يك ناسيا عهدا فاني … لعهدك يا شبابي غير ناس\nوكنت عليك مع طمعي جزوعا … فكيف يكون وجدي بعد ياسي\nلضاع بكاء من يبكيك شجوا … ضياع الدمع بالطلل الطماس\nولو اجدى البكاء على نوار … لاعيي الدمع عين ابي فراس\nفان العيش بعدك غير عيش … وإن الناس بعدك غير ناس"},{"id":"diwan-radi:299","bookId":"diwan-radi","type":"poem","seq":299,"chapter":"البحر: كامل تام","title":"أمضرة بالبدر طالعة","page":"","text":"أمضرة بالبدر طالعة … عند العيون ، وضرة الشمس\nأنا منك في كمد على كمد … يومي علي امر من امسي\nجنية وقبيلها بشر … عظم البلاء بها على الإنس\nوتقول لما جئت اسئلها … كيف الشفاء لداء ذي النكس\nعجبا له اذ جاء يسئل من … مس الفؤاد رقي من المس\nلا تنكري هذا النحول اما … نفسي تذوب عليك من نفسي"},{"id":"diwan-radi:300","bookId":"diwan-radi","type":"poem","seq":300,"chapter":"البحر: طويل","title":"هم خلفوا دمعي طليقا وغادروا","page":"","text":"هم خلفوا دمعي طليقا وغادروا … فؤادي على داء الغرام حبيسا\nطلاع الحشى لم يتركوا فيه فضلة … تضم جوى من بعدهم ورسيسا\nيخافكم قلبي وانتم احبة … كأن الأعادي ينظروني شوسا\nلقد خفت عيني أن تكون طليعة … لكم وفؤادي ان يكون دسيسا"},{"id":"diwan-radi:301","bookId":"diwan-radi","type":"poem","seq":301,"chapter":"البحر: مجزوء الخفيف","title":"باح بالمضمر الدفين لس","page":"","text":"باح بالمضمر الدفين لس … ان من النفس\nعن مبل من الجوى … راجع الداء فانتكس\nما لقلبي عن السلو … رأى النار فاقتبس\nجددت نظرة المهاة … من الوجد ما درس\nطلبت غرة الفؤاد … د المعنى ، وما احترس\nركبت صبغة الهلال … ل على صبغة الغلس\nفي خمار من اللمى … وقميص من اللغس"},{"id":"diwan-radi:302","bookId":"diwan-radi","type":"poem","seq":302,"chapter":"البحر: بسيط تام","title":"كنا نعظم بالآمال بعضكم","page":"","text":"كنا نعظم بالآمال بعضكم … ثم انقضت فتساوى عندنا الناس\nلم تفضلونا بشيء غير واحدة … هي الرجاء ، فسوى بيننا الياس"},{"id":"diwan-radi:303","bookId":"diwan-radi","type":"poem","seq":303,"chapter":"البحر: بسيط تام","title":"كم عرضوا لي بالدنيا وزخرفها","page":"","text":"كم عرضوا لي بالدنيا وزخرفها … مع الهلوك فلم ارفع بها رأسا\nوكيف يقبل رفد الناس محتملا … ذل المطالب من لا يمدح الناسا"},{"id":"diwan-radi:304","bookId":"diwan-radi","type":"poem","seq":304,"chapter":"البحر: طويل","title":"ومعتادة للطيب ليست تغبه","page":"","text":"ومعتادة للطيب ليست تغبه … منغمة الاطراف تدمى من اللمس\nإذا ما دخان الند من ثوبها علا … على وجهها ابصرت غيما على شمس"},{"id":"diwan-radi:305","bookId":"diwan-radi","type":"poem","seq":305,"chapter":"البحر: وافر تام","title":"لتبدي اليوم نسوة آل كعب","page":"","text":"لتبدي اليوم نسوة آل كعب … بأجياد مدماة الخدوش\nعلى الفرسان من سلفي تميم … يثلهم الردى ثل العروش\nمضوا وبقيت بعدهم مهيضا … كما نهض الجناح بغير ريش\nومن نهشت اسنة آل كعب … فلا درياق للرجل النهيش\nفيا نفس اذهبي اسفا عليهم … فبعدهم كموتك ان تعيشي"},{"id":"diwan-radi:306","bookId":"diwan-radi","type":"poem","seq":306,"chapter":"قصائد","title":"ما هاج ذي طرب مخماص","page":"","text":"ما هاج ذي طرب مخماص … ليل ابي العوام والقلاص\nأرسلها خمصاء في خماص … زوراء من رعي الجميم الواصي\nبعد مطال القرب البصاص … رام الى غايتها الاقاصي\nقذى المآقي لبد العناصي … في مطلق انجمه شواصي\nلمع المداري جلن في العقاص … كان خفق الكوكب الوباص\nزرقاء من زرق بني ملاص … حتى اتقين الشمس بالنواصي\nمفتقة من جانب النشاص … تطلع الرود من الخصاص\nمالي وما للقدر المعاصي … كالعير مضروبا على القماص\nاين ابو العوام للعواصي … يروضها والخيل والدلاص\nورعيها بين القنا العراص … من آمن القلام والقراص\nوللقرى والطرق الخراص … وللقنا يلدغن بالاخراص\nهيهات لا حامي الى العراص … شيم الظبي وضمت القواصي\nسم المطايا ليلة الارقاص … يرجعن ارماقا بلا اشخاص\nزاد الفتى والقوم في انتقاص … وبعدوا عن جامح فحاص\nبعد اللغاديد من القصاص … قام المجاري وكبى المناصي\nمن معشر مطيب الأعياص … بين لباب المجد والمصاص\nلهم بآداب الندى تواصي … من كل سباق المدى نواص\nقوم لا عناق العدى قواص … قرن لقاء عجل الاقعاص\nيا قبر بين القور والدعاص … ضم على لؤلؤ الغواص\nضم الوعا وبز بالعقاص … سقيت من داني الحيا والقاصي\nقاد ابن ليلى قائد المعتاص … كان سياغي فغدا اغتصاصي\nما اثقل اليأس على الحراص … هل لجروح الدهر من قصاص\nجد الردى والناس في حياص … حيد الأقاطيع عن القناص\nقد ينزل العالي من الصياصي … وقد يطيع الرأس وهو عاصي\nأمر لجام القدر القراص … ما شاء من حكم فلا مناص"},{"id":"diwan-radi:307","bookId":"diwan-radi","type":"poem","seq":307,"chapter":"البحر: كامل تام","title":"يا بؤس مقتنص الغزال طماعة","page":"","text":"يا بؤس مقتنص الغزال طماعة … ذهب الغزال بلب ذاك القانص\nكالدرة البيضاء حان ضياعها … من بعد ما ملأت يمين الغائص\nما كان قربك غير برق لامع … ولى الغمام به وظل قالص\nأغدو على أمل كحبك زائد … واروح عن حظ كوصلك ناقص"},{"id":"diwan-radi:308","bookId":"diwan-radi","type":"poem","seq":308,"chapter":"البحر: كامل تام","title":"لمن الديار طلولها وقص","page":"","text":"لمن الديار طلولها وقص … ما للقطين بعقرها شخص\nابقى الخليط بها معاهدة … اثر لعمرك ما له قص\nولقد تحل بها مرببة … ظمأى الوشاح وللبرى غص\nغنيت بحلي الحسن عاطلة … ما للنضار بجيدها وبص\nفرعاء ان نهضت لحاجتها … عجل القضيب وابطيء الدعص\nومرجل جعد ينوء به … جيد الغزال وناعم رخص\nسرقت بطرف الريم مهجته … ومن النواظر قاطع لص\nقسما بشعث جعجعت لهم … بالمأزمين ظوالع خص\nطعنوا الظلام بكل ناجية … في موق كل دجى لها بحص\nترمي الإكام بمنسم عمم … دامي الأظل كأنه قرص\nوالراجمين جمارها بمنى … غدوا وما حلقوا وما قصوا\nمتجردين من الرياض ضحى … حل النطاق واطلق العقص\nلاسقينك كاس لاذعة … لا العب ينفذها ولا المص\nبقوارع يمسي الرمي بها … من غير ما طرب ، له رقص\nتنسي جرائحها قوارصها … والطلق ينسى عنده المغص\nأإلى معد جئت مرتقيا … يا عير ! أين رمى بك القمص\nأمن الوهاد الى الربى عجلا … سرعان ذا الذملان والنص\nالحقت ريشك في قوادمهم … عجلان تلصقه وينحص\nإن زدتهم ، فلقد نقصتهم … إن الزيادة بالشغا نقص\nغادرتها شنعاء ضاحية … لا النقس يصبغها ولا الحص\nومن المخازي عند لابسها … ما لا تواري الازر والقمص\nيا موعدي بذناب مخلبه … ان البعوض اذاته القرص\nلا تحسدن المرء ثروته … ان البطان الى غد خمص\nوخف السقاط على الذين علوا … ومن العلو يحاذر الوقص\nواعقد يديك بمجتنى كرم … لاقدح في حسب ولا غمص\nاسد اذا بصر الرجال به … خفض الكلام وطومن الشخص\nمن معشر ركبت اوائلهم … أولى العلى ، وجيادها شمص\nان احسنوا عموا بنائلهم … واذا رموا بجزيرة خصوا\nعدد المكارم في بيوتهم … والجامل القبقاب والقبص\nرفعوا المساعي من قواعدها … يعلو بهن الرضم والرص\nحتى انثموا في رأس اشرفها … وعلى الكعوب يوقع الخرص\nافنى العدو وليس ينقصهم … من رمل منقطع اللوى القبص"},{"id":"diwan-radi:309","bookId":"diwan-radi","type":"poem","seq":309,"chapter":"البحر: خفيف تام","title":"رب مستغمز إبائي وفي النا","page":"","text":"رب مستغمز إبائي وفي النا … اس ذلول على الاذى وقموص\nناصب لي حبائل الطمع المز … ري ، وغيري للمطمعات قنيص\nبذل المال لي يساوم عرضي … ان عرضي اذا علي رخيص\nلا يعاب المقل ، وهو قنوع … ويعاب الغني ، وهو حريص\nلبستي علها تجلى ولم يدنس … رداء من العلى وقميص\nوانظرنها تجر زعازعها النك … ب وبطني من النوال خميص\nوارقبي ععطفة الزمان بجد … ربما حلق الجناح الحصيص\nبقدم الباسل الابي على الحت … ف وفيه عن الهوان نكوص\nكلما عضه الاذى غض بالصبر … ر يزجي الأيام وهي غصيص\nقسما بالأشاعث الخمص أدت … هم إلى المأزمين قود وخوص\nترتعي جرة البطون من الجه … د ، إذا عز أجرد وقصيص\nاكلت نيها الموامي فلم يب … ق عليها إلا الذما والشخوص\nلا جعلت الهوان دار مقام … وعن الضيم معدل ومحيص\nخف عن عاتقي الرجاء وكم با … بات بمن الرجال وهو وقيص\nإن يكن في ندى الملوك سبوغ … للمرجى ، ففي رجاي قلوص"},{"id":"diwan-radi:310","bookId":"diwan-radi","type":"poem","seq":310,"chapter":"البحر: سريع","title":"كيف أضاء البرق ، إذ أومضا","page":"","text":"كيف أضاء البرق ، إذ أومضا … منابت الرمث بوادي الغضا\nعهد الحمى لا اين عهد الحمى … قضى على الصب جوى وانقضى\nونازل بالقلب أوطانه … بين حمى الرمل وبين الأضا\nلا ناله الداء الذي نالني … منه وان شف وان امرضا\nولا يكابد ليل ذي غلة … لو طلع البدر به ما اضا\nهان على الواجد طعم الكرى … إن الفتى الساهر ما غمضا\nما آن للممطول ان يقتضي … ولا لذا الماطل ان يقتضى\nان غريمي بديون الهوى … أدان قلبي وأساء القضا\nيا راكبا تحمله جسرة … كالهقل ناش البلد الأعرضا\nانحله الخوف وخوف الفتى … سيف على مفرقه منتضى\nقل لبهاء الملك ان جئته … سود دهري بك ما بيضا\nسخط لو أن الطود يرمى به … ساخ عن الأطواد ، أو خفضا\nومر قول ذل عزي له … لو مزج الماء به عرمضا\nأعوذ بالعفو ، وهل آمن … نذيرة الصل إذا نضنضا\nأيا غياث الخلق إن أجدبوا … ويا قوام الدين ان قوضا\nويا ضياء ان نأى نوره … لم نر يوما بعده أبيضا\nمالي مطويا على غلة … ارمضني وجدك ما ارمضا\nقد قلق الجنب وطال الكرى … وأظلم الجو وضاق الفضا\nلا تعطش الزهر الذي نبته … بصوب إنعامك قد روضا\nإن كان لي ذنب ، ولا ذنب لي … فاستأنف العفو وهب ما مضى\nلا تبر عودا أنت ريشته … حاشا لباني المجد ان ينقضا\nوارع لغرس أنت أنهضته … لولاك ما قارب ان ينهضا\nلو عرض الدنيا على عزها … منك ، لما سر بما عوضا\nولا يكن عهدك ، بعد الهوى … غيما تجلى وخضايا نضا\nيا راميا لا درع من سهمه … أقصدني من قبل أن ينتضى\nقضى على قلبي بإقلاقه … ما انا بالجلد على ما قضى\nوكيف لا ابكي لاعراض من … يعرض عني الدهر أن أعرضا\nقد كنت ارجوه لنيل المنى … فاليوم لا اطلب غير الرضا"},{"id":"diwan-radi:311","bookId":"diwan-radi","type":"poem","seq":311,"chapter":"البحر: خفيف تام","title":"عند قلبي علاقة ما تقضى","page":"","text":"عند قلبي علاقة ما تقضى … وجوى كلما ذوى عاد غضا\nوبكاء على المنازل ابلتهن … ايدي الأيام بسطا وقبضا\nوالتفات إلى التصابي ، وقد أس … رع بي جامح الثلاثين ركضا\nمن معيد أيام ذي الأثل ، أو ما … منع الدل دينها أن يقضى\nسامحا بالقليل من عهد نجد … ربما أقنع القليل وأرضى\nإن عيدا من الغواني ، إذا رم … ت التسلي أشجى لقلبي وأنضى\nوإذا ما عزمت صبرا ارتني … مقلا تفسخ الدل دينها أن يقضى\nوإذا ما أمتن بالبعد بعضا … برد عز ، أو حر نصل ، فإني\nفسقى الرمل منزلا ومعانا … هزجات ينبضن بالبرق نبضا\nومشت فيه بالنسيم عليلا … قطع المزن في الرياض المرضى\nما لذا الزور ما يغب من الرم … طروقا في مضجع قد اقضا\nمهديا لي من طيب أرواح نجد … ما يداوي نكس العليلى المنضا\nلم يكن غير خطرة البرق ما … ما زود عين المشوق الا ومضا\nقادة الغمض من زرود فلما … زار أنبى عن مقلتي الغمضا\nقد لبست الخطوب سودا وبيضا … وقطعت الزمان طولا وعرضا\nووردت الأمور صفوا ورنقا … ورعيت الآمال رطبا وحمضا\nوتلفعت ريطة من بياض … إنا راض منها بما ليس يرضى\nابرمت لي من صنعة الدهر لا … يسرع فيها إلا المنايا نفضا\nمخبر فاحم ولون مضيء … من أرى اليوم فاحما مبيضا\nكم مقامي تلقي علي الليالي … نوبا لا اطيق منهن نهضا\nوخطوبا إذا نحتن من العظم … فلا بدع أن عرقن النحضا\nقاعدا مطرح السقاء انتحته … بصروف الاقدار جرا ومنخضا\nركبتني وهما جلالا فما زال … جدابي حتى رمى بي نقضا\nكل يوم على مزلة خطب … اتوقى مرمى إلى الذل دحضا\nومسقى على القذى يرد الور … \nكلما سار طالبا خفض عيش … \nأين لا اين من يجير على الدهر إذا … ر ، إذا الدهر هر يوما وعضا\n … لم يدعنا حتى وهبنا العرضا\nوتركنا نفل الزمان قنوعا … \nفذماما على الندى ان يرجى … وعياب البخيل من أن يفضى\nوأمانا مني عليه ، فما أذ … عر سربا ، ولا أنازل أرضا\nلا حملت الحسام إن لم أحمل … رؤوس العدى قراعا وعضا\nفعل مستثقل الحياة يعد ال … بعثا على المنون وحضا\nمستميتا يرى التحية بالضي … م لطاما ، والعار جرحا ممضا\nطارحا نفسه على كل هول … قد تعامى عنه الجبان وأغضى\nحيث يلقى ضرب السيوف اخاديد … تمج الدماء والطعن وخضا\nوفتور مثل الأسود أعدوا … لقنيص العلياء وثبا وربضا\nفوق اكوار ضمر اقلق النسع … ع قديم اضطمارها والغرضا\nكلما اجلوذ الظلام استلذوا … لعب الليل بالطلاح الانضا\nكل مستعسف اليدين بقوس … مجد يرمي عن المكارم عرضا\nسوطه نسعة العنان ، إذا ح … رك جلى إلى المراد وأفضى\nفلعلي ألقى المنى أو خلاجا … من حمام قضى علي وأمضى\nراكبا صهوة الخطار عقيدا … لبنات الفلا يجبن الارضا\n … ولهام الاعداء وقما وغضا\nبرد عز أو حر تصل فاني … أجد اليوم في ضلوعي رمضا"},{"id":"diwan-radi:312","bookId":"diwan-radi","type":"poem","seq":312,"chapter":"البحر: متقارب تام","title":"مواقد نيرانهم قرة","page":"","text":"مواقد نيرانهم قرة … وسربال طاهيهم ابيض\nإذا حركوا للمساعي ابوا … وإن أنزلوا دار ضيم رضوا"},{"id":"diwan-radi:313","bookId":"diwan-radi","type":"poem","seq":313,"chapter":"البحر: طويل","title":"حذار فان الليث قد فر نابه","page":"","text":"حذار فان الليث قد فر نابه … وقد أوتر الرامي المصيب وأنبضا\nاسر بمن ارجى إلى اليوم يومه … فأدرك ما يهوى ، وآسى لمن مضى\nوقد كنت ادعو ان تؤخر مدتي … لعلي أرى يوما من العدل أبيضا"},{"id":"diwan-radi:314","bookId":"diwan-radi","type":"poem","seq":314,"chapter":"البحر: كامل تام","title":"أهلا به من رائح متصعد","page":"","text":"أهلا به من رائح متصعد … بخوالج من برقه ونوابض\nهزج البروق ، كأنه متمطق … بأراقم قلن الرمال نضانض\nحتى يقول الساهرون لومضه … نضر العراق بقطر هذا العارض"},{"id":"diwan-radi:315","bookId":"diwan-radi","type":"poem","seq":315,"chapter":"البحر: مجزوء الخفيف","title":"ضوأ حين اومضا","page":"","text":"ضوأ حين اومضا … منبت الرمل والغضا\nبارقا مزنة اطال … استنانا واعرضا"},{"id":"diwan-radi:316","bookId":"diwan-radi","type":"poem","seq":316,"chapter":"البحر: رجز تام","title":"لغير تقدير ذرعن الأرضا","page":"","text":"لغير تقدير ذرعن الأرضا … حتى علمن طولها والعرضا"},{"id":"diwan-radi:317","bookId":"diwan-radi","type":"poem","seq":317,"chapter":"البحر: وافر تام","title":"لجام للمشيب ثنى جماحي","page":"","text":"لجام للمشيب ثنى جماحي … وذللني لا يام وراضا\nأقر بلبسه ، ولقد أراني … أجاحده إباء وامتعاضا\nتعوضت الوقار من التصابي … لشد على المعوض ما استعاضا\nلوى عني الخدود من الغواني … وقطع دوني الحدق المراضا\nفصار بياضه عندي سوادا … وكان سواده عندي بياضا"},{"id":"diwan-radi:318","bookId":"diwan-radi","type":"poem","seq":318,"chapter":"البحر: طويل","title":"رضيت من الاحباب دون الذي يرضي","page":"","text":"رضيت من الاحباب دون الذي يرضي … وداينت من تقضى الديون ولا يقضي\nوقد أنهرت في الليالي جراحها … مرارا ، وأنضاني من الهم ما ينضي\nطوى الدهر أسباب الهوى عن جوانحي … وحل الصبا عقد الرحايل عن نقضي\nولم يبق لي في الأعين النجل طربة … ولا أرب عند الشباب الذي يمضي\nأضحى اليوم عن ظل الشبيبة مفرقي … وأبدل مسود العذار بمبيض\nتاني ، وممطول من النأي بيننا … قوارص تنبو بالجفون عن الغمض\nومولى ورى قلبي بلذعة ميسم … من الكلم العوراء مضا على مض\nفعذرا لاعدائي إذا كان اقربى … يشذب من عودي ويعرق من نحضي\nإذا ما رمى عرضي القريب بسهمه … عذرت بعيد القوم اما رمى عرضي\nالم يأته اني تفردت بعده … روابي للعلياء جاش لها نهضي\nوأني جعلت الأنف من كل حاسد … قبالي وخدي كل مضطغن أرضي\nوكم من مقام دون مجدك قمته … على زلق بين النوائب أو دحض\nوقارعت من أعياك قبل قراعه … فدامجني بعد التشاور والبغض\nلقد أمست الأرحام منا على شفا … فأخلق بمشف لا يعلل أن يقضي\nرأيت مخيلات العقوق مليحة … فلا تجعلن برق الأذى صادق الومض\nولا تشمتن من ود لوا اننا معا … شحيحان تلطينا الجنادل بالأرض\nاذا كنت اغضي والقواذع جمة … فمثلك أولى أن يرم وأن يغضي\nعلى غصص لو كن في البدر لم ينر … وفي العود لم يورق وفي السهم لم يمض\nرزئتك حيا بالقطيعة والفلى … وبعض الرزايا قبل يوم الفتى المقضي\nاناديك فارجع من قريب فانني … اذا ضاق بي ذرعي مضيت كما تمضي\nلقد كان في حكم الوشائج لو رأى … عن المجد بطئي أن يبالغ في حضي\nفكيف ولم تخرج مناديح همتي … ولا ذمت العلياء بسطي ولا قبضي\nاذا هو اغضى ناظري على القذى … وكان لمثلي مسخطا فلمن يرضي\nخليلي ما عودي لأول غامز … ولا زبد وطبي للمقيم على مخض\nفقل للعدى عضوا الأخامص إنكم … تعرقتم الأيدي علي من العض\nهم نقضوا ما قد بنى أولوهم … وشدنا وهيهات البناء من النقض\nوفي كل يوم يضبغ العار منهم … رداء امرء والعار باق على الرحض\nيريدون أن يخفوا النواقر بيننا … وقد صاحت الأضغان في الحدق المرض\nذكرت حفاظي والحفيظة في الحشا … لها نغضان العرق يحفز بالنبض\nدعوتكم قبل التي لا شوى لها … وقلت لهم فيؤا إلى الخلق المرضي\nردوني نميرا قبل أن أحمل القذى … ولا تردوا إلا على الثمد البرض\nولسوا جميمي قبل أن يمنع الحمى … إبائي أو يوبى على رعيكم حمضي\nومن قبل أن يسدي المعادون بيننا … برود الخنا ما شئت في الطول والعرض\nتقوا عار حرب لا يعود مثيرها … وان غلب الاقران إلا على رمض\nولا تولجوا زور العقوق بيوتكم … اناشدكم بالله في الحسب المحض\nأراها بعين الظن حمراء جهمة … ستجري إلأى العار العواقب أو تفضي\nتهضمني من لا يكون لغيره … من الناس اطراقي على الهون أو غضي\nافوق نبل القول بيني وبينه … فيؤلمني من قبل نزعي بها عرضي\nوارجع لم اولغ لساني في دمي … ولم ادم اعضائي بنهشي ولا عضي\nاذا اضطرمت ما بين جنبي غضبة … وكاد فمي يمضي من القول ما يمضي\nشفعت على نفسي بنفسي فكفكفت … من الغيظ واستعطفت بعضي على بعضي"},{"id":"diwan-radi:319","bookId":"diwan-radi","type":"poem","seq":319,"chapter":"البحر: طويل","title":"أرى موضع المعروف لو أستطيعه","page":"","text":"أرى موضع المعروف لو أستطيعه … واغضي ولو شاء الغني لي لم اغض\nألاحظ خلات الكرام بغصة … ويقصر مالي عن بلوع الذي يرضي\nوأقبض كفي عن عطاي وقد يرى … ذهابي بها عند الفضول عن القبض\nتقتلنا هذي الليالي ولا تدي … وتستقرض الأيام منا ولا تقضي\nولولا الندى ما طأطأ العدم هامتي … ولا كان ينقضيني من الهم ما ينضي\nوكيف وفور العرض والمال وافر … ومن يخزن الاموال ينفق من العرض\nومن عدم أقري النوازل عذرة … ولو حل لي لحمي قريتهم بعضي"},{"id":"diwan-radi:320","bookId":"diwan-radi","type":"poem","seq":320,"chapter":"البحر: مجزوء الكامل","title":"قالوا تزاور عطفه","page":"","text":"قالوا تزاور عطفه … وأرابنا إيماضه\nوابى اباء الصعب لا … يسطيعه رواضه\nغضبان سل خطامه … عنه وحل إباضه\nعطلت رباه من الصفا … ء ، وعريت أنقاضه\nان يستعض مني فلا … مغبوطة اعواضه\nقد عز من يعتاض من … وذل من يعتاضه\nهيهات لا احبابه … مني ولا ابغاضه\nما سرني إقباله … فيسؤني اعراضه"},{"id":"diwan-radi:321","bookId":"diwan-radi","type":"poem","seq":321,"chapter":"البحر: رجز تام","title":"أبا علي للألد إن سطا","page":"","text":"أبا علي للألد إن سطا … وللخصوم ان اطالوا اللغطا\nتصيب عمدا ان اصابوا غلطا … ولمع تكشف عنهن الغطا\nكشفك عن بيض العذري الغطا … ومصعب للقول صعب الممتطى\nعسفت حتى عاد مجزول المطا … دامي الملاط رحله قد أغبطا\nوسائرات بالخطى لا بالخطا … شوارد عنك قطعن الربطا\nكما رأيت الخيل تعدو المرطى … البست فيها كل اذن قرطا\nقد وردت أفهامنا ورد القطا … ومشكلات ما نشطن منشطا\nعطالها بمقول ، إذا عطا … ميز من ديجورها ما اختلطا\nغلل مابين العقاص المشطا … ضل المجارون وما تورطا\nملوا مجاراة فنيق قد مطا … قرم يهد الأرض إن تخمطا\nمل المطي اودى ولا مغتبطا … كانوا العقابيل ، وكنت الفرطا\nعند السراع يعرف القوم البطا … أرضى زمان بك ثم أسخطا\nما أطلب الأيام منا شططا … "},{"id":"diwan-radi:322","bookId":"diwan-radi","type":"poem","seq":322,"chapter":"البحر: وافر تام","title":"كانت لم تقد بعويرضات","page":"","text":"كانت لم تقد بعويرضات … أبا العوام ، فتيانا قطاطا\nولم تحمل على الأعداء منهم … قنا لدنا وايمانا سباطا\nإذا المنجود نبههم طروقا … رأى زعل الشبيبة والنشاطا\nقيام السمهري تبادروها … وقد لبسوا المخيلة والشطاطا\nولم تسق الجياد مسومات … تجشمها المغاور والوراطا\nوترسلها العرضنة صاديات … مبادرة إلى الماء الغطاطا\nتصيب بها فواغر كل ثغر … كانك ترسل النبل المراطا\nفلين مفارق المعزاء وخدا … كفلي الانمل اللمم الشماطا\nومن جعل الدليل له ابن ليلى … فلن يخشى الضلال ولا الغلاطا\nوناجية تساقطها حسيرا … سقاط حسامك البدن العباطا\nوتطلق رحلها والفجر طفل … وقد أكل البواني والملاطا\nوشاذبة طويت بها اعتسافا … بساط الدو ، إن له بساطا\nدوارع للبلاد بغير حاد … تخال فضول أنسعها سياطا\nوعدت بها تساوك من وجاها … دبيب النمل يتعل البلاطا\nومنخرق كان على رباه … من الظلم الاكنة واللياطا\nتعلقت النجوم بجانبيه … كأن الليل البسها القراطا\nطعنت ظلامه بالركب حتى … رأيت له انجيابا وانعطاطا\nوكل فتى تبطن بيت نبع … وصير غمد قاطعه إباطا\nأغيلمة زحمت بها الأعادي … تعاطى بالذوابل ما تعاطى\nتخال على عواملها ، إذا ما … وردن الطعن السنها السلاطا\nويوم للوقيعة ذي اوار … ككبر القين اوقد فاستشاطا\nفرقت جموعه فرق العناصي … وقد مرج الطعان به اختلاطا\nتعاطي كأسه فتعب فيها … ويحتقر الجبان فلا يعاطا\nجعلت طلى العدى فيه اقتراحا … على بيض القواضب واشترطا\nتغلغل في جماجمها العوالي … كما غلغلت في اللمم المشاطا\nتترى بعد يومك كل خطب … كانك كنت للجلى رباطا\nألا أين السريع إلى المنايا … إذا المعزال عرد ، أو تباطا\nاذا ولج الرواق رأيت منه … طويل الباع قد غمز السماطا\nوكنت اذا اخذت بمنكبيه … غداة الضيق ، فرج لي الضغاطا\nوكم بزلاء صيح بها اليه … تطاطا لها تجزك ، فما تطاطا\nفقولا للمنفض مذرويه : … خض الامر انغماسا وانعطاطا\nمراس الحرب أسحبه العوالي … وطول الامن اسحبك الرباطا\nهم حملوا لك الاحسان عفوا … فدونكهن ولغا واستراطا\nحموكم ، والأسنة في الهوادي … وقوع الطير تبتدر اللقاطا\nغداة خلا بداركم الاعادي … فلم يدعوا لحوضكم لياطا\nتشقق في جلودكم العوالي … كان الطعن يلبسها الرهاطا\nبكل قرارة منكم لحيم … يقضي الليل زفرا وانتحاطا\nأجمكم ، ولاقى عن علاكم … عضاض الطعن والضرب الخلاطا\nومد ببوعكم حتى غدوتم … وعالي النجم اقربكم مناطا\nوحلق مضرحي كان فيكم … وان لكل طائرة سقاطا\nفلا تبعد رجال من قريش … وسمت بهم فلم أعد العلاطا\nرعوا تلعات هذا المجد لسا … بانياب العوامل وانتشاطا\nتخيرهم حمام الموت منا … خيار الزائد اعتراض النماطا\nتداعوا كالسلوك وهت قواها … مروقا بالنوائب وانخراطا\nمضوا من كل أغلب مستميت … اذا ما العار جلله اماطا\nنأوا عني فضعضعني نواهم … وما كانوا فقد قطعوا النياطا"},{"id":"diwan-radi:323","bookId":"diwan-radi","type":"poem","seq":323,"chapter":"البحر: كامل تام","title":"سنحت لنا بلوى العقيق وربما","page":"","text":"سنحت لنا بلوى العقيق وربما … عرض الزلال وزيد عنه الفارط\nقلبي وطرفي ، يوم حم لقاؤها … ضدان ذا راض وهذا ساخط\nنظرت بلا قصد فأقصدت الحشا … ويذيق طعم الموت سهم غالط\nقل للغزال اذا مررت بذي النقا … فلعل جأشك للبلابل رابط\nلم انت في هبة القليل مناقش … أبدا ، وفي عدة الوصال مغالط"},{"id":"diwan-radi:324","bookId":"diwan-radi","type":"poem","seq":324,"chapter":"البحر: رمل تام","title":"ما لذا الداني إلى القلب شحط","page":"","text":"ما لذا الداني إلى القلب شحط … وغريم الحب بالدين ألط\nظالم قلد أحكام الهوى … طالما جار علينا وقسط\nنسخط الشيء ونرضاه ، إذا … لم تر العتبى على طول السخط\nكل يوم لي خصيم ضالع … والمقادير لها حكم شطط\nعجبت ان عاد شغبا منطقي … كل ذي حلم اذا ضيم لغط\nورأت وخط بياض طارق … وخط التهمام قلبي ، فوخط\nمالها تنكر مع هذا الشجى … وقعات الشيب بالجعد القطط\nوارى عودي على صمائه … أن من غمز الليالي ونحط\nموقرا يحبسني عن غايتي … لا المدى يطوي ولا العبء يحط\nإن قومي صدعتهم نوبة … شقق البرد اليماني يعط\nخلتهم والخطب يعتامهم … شجر الوادي رماه المختبط\nوكما خايل يوما عاقر … كلما ثارت له البدن عبط\nتبعوا امر المقادير فهم … فاطن يطعن أو دان يشط\nفل أحداث رمى الدهر بهم … فهم في رقع الدهر نقط\nذاقهم مستحليا أرواحهم … ورأى المضغ طويلا ، فاسترط\nيصطفي كل كريم منهم … وإذا استكرم ذو العقب ربط\nوبواق غير باقين وكم … يلبث القارب من بعد الفرط\nكم طوى الموت لهم من بهمة … خائض الغمرة فراج الضغط\nوجواد متعب مضماره … كلما لزت به الخيل معط\nسلهم ، أو فسل الروع بهم … يوم خدر الشمس بالنقع يلط\nيبصر الناس على ايديهم … قصب الاعناق بالبيض يقط\nاقبلوا الاعداء ملتف القنا … بين معروض ومجرور يحط\nتحسب الارماح من قعقاعها … شجرا للطير فيهن لغط\nومواض تنثر الهمام لهم … هبة العاصف ترمي بالخبط\nفارقونا ، فبقينا بعدهم … كالرذايا ، وضعت عنها الغبط\nفي ذنابى معشر جيرانهم … مضغ للخطب يغدو أو لقط\nليس بالراضي اذا نبهم … طارق الليل ولا بالمغتبط\nصور رائعة لا يرتجي … نفعها ، مثل تهاويل النمط\nشمخوا أن حلق الجد بهم … غلط الدهر وكم يبقى الغلط\nكسل الايام عنهم غرهم … ربما جاء زمان قد نشط\nكل مخنوق علي جرته … خلط العجز بشوك ، فاختلط\nإن رأى المغرم طاطا ، وله … حاجب من حافر اللؤم يمط\nأهمل العرض على علم به … ورعى ، لما رعى ، المال فقط\nطمع ورطني في حبلهم … ويصاد الطير من حيث لقط\nكنت ارجواهم ثمارا تجتني … فهم اليوم قتاد يخترط\nمن عذيري من رصيد كيده … راش ما راش طويلا ومرط\nجامع لي بين فخر وأذى … ربما برح بالأذن القرط\nحمل الثقل على ذي غارب … كلما عج من الحمل ضغط\nأتقى الرمي ولو شئت مضى … كل مطرور اذا صمم عط\nواذا كشفت ما يرمضني … من مضيض الداء قال الحلم غط\nكل يوم رحم منبوذة … كرؤوم البو عضباء تئط\nمطرح الشنة قد أيبسها … قدم العهد بعامي الاقط\nيسأل البقيا ، وقد أحميته … ميسما لو مر بالطود غلط\nصدق الواشين ، فيما زعموا … فنأى بالود عني وشحط\nلا أرى الجن وأفاكا به … في دجى الليل ، ولا الوحي هبط\nنفثة من واغر جمجمها … فيك ، لولا الله والحلم قنط"},{"id":"diwan-radi:325","bookId":"diwan-radi","type":"poem","seq":325,"chapter":"البحر: كامل تام","title":"قل للهوامل في الدنا ما بالكم","page":"","text":"قل للهوامل في الدنا ما بالكم … كالنائمين ، وأنتم أيقاظ\nاين المقاول والجبابر قبلكم … فاضوا على علل الزمان وفاظوا\nمتنافسين على المقام ، وإنما … خلف الركائب سائق ملظاظ\nاللبث لمح والمناخ محفز … والرعي خطف ، والورود لماظ\nانظر إلى هذا الزمان بعينه … ترجع إليك بمقته الألحاظ"},{"id":"diwan-radi:326","bookId":"diwan-radi","type":"poem","seq":326,"chapter":"البحر: رجز تام","title":"يا عمرو ! لا أعرف ثقلا بهظك","page":"","text":"يا عمرو ! لا أعرف ثقلا بهظك … خلة حر ، فأعرها ملحظك\nمن قائم على العلا ما احفظك … ما نام عن حاجته من أيقظك"},{"id":"diwan-radi:327","bookId":"diwan-radi","type":"poem","seq":327,"chapter":"البحر: وافر تام","title":"أسيغ الغيظ من نوب الليالي","page":"","text":"أسيغ الغيظ من نوب الليالي … وما يشعرن بالحنق المغيظ\nأرجي الرزق من خرت دقيق … يسد بسلك حرمان غليظ\nوارجع ليس في كفي منه … سوى عض اليدين على الحظوظ"},{"id":"diwan-radi:328","bookId":"diwan-radi","type":"poem","seq":328,"chapter":"البحر: سريع","title":"ألهاك عنا ، ربة البرقع","page":"","text":"ألهاك عنا ، ربة البرقع … مر الثلاثين إلى الأربع\nانت اعنتني الشيب في مفرقي … مع الليالي ، فصلي ، أو دعي\nيا حاجة القلب ألم ترحمي … جنانة الدمع على مدمعي\nلولا ضلالات الهوى لم يكن … عنان قلبي لك بالاطوع\nكيف طوى دارك ذو صبوة … عهدي به يطرب للمربع\nكان يرى ناظره سبة … ان مر بالدار ولم يدمع\nيا حبذا منك خيال سرى … فدله الشوق على مضجعي\nاني تسرى من عقيق الحمى … منازل الحي على لعلع\nبات يعاطيني جنى ظلمه … وبت ظمآن ، ولم أنقع\nمعانقا كان عناقي له … وراء احشائي والاضلع\nعاقرني يشرب من مهجتي … ريا ، ويسقيني من أدمعي\nهل تبلغني الدار من بعدهم … على الطوى جائلة الانسع\nكأن مجرى النسع في ذفها … مضطرب الايم على الاجرع\nتحملني والشوق في كورها … اني دعاني طرب اسمع\nان بهاء الملك ان ادعه … والخطب قد نازلني ، يمنع\nرب زمام لي في ضمنه … لم اتقوله ولم ادع\nمصطنعي والسن في روقها … اصاب مني غرض المصنع\nلم أرض إلاه ، ومن قبله … أقنعني الدهر ، ولم أقنع\nأغر ، إن روع جيرانه … لم يذق الغمض ولم يهجع\nكأنما الضيم إليه سرى … وهو على المطلع الامنع\nفي حسب أصبح وضاحه … قد غلب الشمس على المطلع\nلئن نأى عنا ، فإحسانه … ادنى من الناظر والمسمع\nسوم الحيا اقلع عن ارضنا … ونحن في آثاره نرتعي\nكم نفخة منه على فاقة … تنبت عشب البلد البلقع\nونظرة تجبر وهن الفتى … وعظمه منصدع ما وعي\nإذا قضى مر على نهجه … واستوقف الحق على المقطع\nكم طار في ملك ذو نخوة … قالت له ريح المنايا قع\nأما نهى الأعداء ما جربوا … فهو غدا يعطس عن اجدع\nلم يلقك المغرور الاغدا … يقوم الجنب على المصرع\nينتظر الحي بهم هتفه … من النواعي وكأن قد نعي\nمن جاهد خاب ، ومن طالب … اوفي على الفج ولم يطلع\nومسرع أقلع من عثرة … روعاء والعثرة للمسرع\nونادم أطرق عن حزبه … قد نادم الناجذ بالإصبع\n … ولا ربوا والعز في موضع\nشابهت السوأة ما بينهم … ما اسبه الحالق بالانزع\nارتضعوا والعار من فيقة … ونزعوا واللؤم من منزع\nمن عاقد اغدر من مومس … وواعد اكذب من يلمع\nراموك بالأيدي وكان السهى … أعلى من أن يدرك بالأذرع\nقد علموا عند قراع الصفا … وليمة الذؤبان والأضبع\nقل لبهام نشرت في الربا … هذا قوام الدين ، فاستجمعي\nقد أصحر الضيغم من غيله … اظفوره منك على مطمع\nغضبان قد غرك همهامه … \nكم فيك من خرق لاظفاره … كملغم الأشدق ، لم يرقع\nليس كغزو الذئب بهم الحمى … ان مر بالسخلة لم يرجع\nإن لم تشاور حلمه تصبحي … أي جنيب لك لم يوضع\nيستمع الرأي وعنه غنى … قد يصقل السيف ولم يطيع\nلا بد أن ترمض روعاته … وان عفا اليوم ولم يوقع\nوالسيف إن مر على هامة … روعها ان هو لم يقطع\nقل لحسود النجم في فوته … عشت بداء الكمد الموجع\nلابد للبطنة من خمصة … فجع على غيظك أو فاشبع\nمواقف تفسخ فيها الظبى … عقدة رأي البطل الأروع\nأيامك الغر تسربلتها … مثل متون القضب اللمع\nافاقت البصرة من دائها … وقد رقى الناس ولم ينجع\nعادات اسيافك في غيرها … والسيف مدلول على المقطع\nفلست بالخامل من غاربي … على سنام النقب الاظلع\nقد خاب من اصبح من غيركم … علي ، والإقبال منكم معي\nيا أيها … فهل لنا عندك من مكرع"},{"id":"diwan-radi:329","bookId":"diwan-radi","type":"poem","seq":329,"chapter":"البحر: كامل تام","title":"تمضى العلى وإلى ذراكم ترجع","page":"","text":"تمضى العلى وإلى ذراكم ترجع … شمس تغيب لكم وأخرى تطلع\nإن الصفا العادي يقرع بالأذى … من غيركم ، وصفاكم لا يقرع\nمتداولين لباس اثواب العلى … هذا يجاب له وهذا ينزع\nفي كل يوم للنواظر منكم … أعلام علياء تحط وترفع\nلا مثل من ملك العى مستقبل … فينا ، ومن طوت المنون مودع\nعينان عين للمزيد قريرة … منا وعين للنقيصة تدمع\nوإذا اطمأن من العطية مضجع … يوما أقض من الرزية مضجع\nفلئن فرحنا إن ذلك مفرح … ولئن جزعنا إن ذلك مجزع\nللمجد من علياكم ومصابكم … انف به شمم وآخر اجدع\nبؤسى ونعمى أعقبت ، فكأنما … ردت على أعقابهن الأدمع\nلولا الاعز ابو شجاع لم يكن … وهي النوائب عن قليل يرقع\nلولاه ما انجبر الكسير ولا سيما … طرف الحسير ، ولا سلا المتفجع\nما كانت العلياء بعد مصلبها … لولاه بالبدل المجدد تقنع\nنثلوا كنائن مجدهم فتخيروا … منهن اقوم نصلة لا ينزع\nسهما رمى غرض العلى من بعدما … لم يبق في قوس المعالي منزع\nلا يطمع الأعداء مطلع نجده … قد ضاق الاعنه ذاك المطلع\nطلبتك قد قلقت اليك نصولها … حتى استقر بها النصاب الامنع\nظمأى إليك وأين عنك محيدها … والرعي عندك والروا والمرتع\nيوما ، وطينتها بغيرك تطبع … يوما وطينتها بغيرك تطيع\nسبقت ببيعتك القلوب أكفها … ايد اطعنك والضمائر اطوع\nمن مضمر يخشى الهوى لا ينثني … او صافق بيد الرضى لا يرجع\nأعطت تخايلها الصدور ، وربما … تعطى يد ولها ضمير يمنع\nالله أيد ملككم وسما به … مجد القواعد والبناء الارفع\nبيت يسقف بالسماء رواقه … وتهاب ذرته الحمام الوقع\nاطناب قبته انابيب القنا … وسجوف ظلته المواضي اللمع\nإن ساخت الأركان أشرف ركنه … او ضعضع البنيان لا يتضعضع\nكم مصعب منع الخطام تركته … تحت الرحالة يستقيم ويطلع\nاو خالع قصرت يداه عن العلى … بوع لكم تقص الرقاب وأذرع\nفسبقتم وكبا به من جده … دون المنى قصف الفقار موقع\nتخفى مكانده ويظهر سطوكم … الذر يقرص والاراقم تلسع\nلا ثل عرش بني بويه أنهم … غدر المكارم والجناب الامرع\nفعلى روائهم يحوم المعتفي … وإلى روائهم تشير الإصبع\nان قاربوا فهم الشهاد المجتنى … وإذا أبوا فهم السمام المنقع\nايديهم طرق الندى وجباههم … أبهى من التيجان لا بل ألمع\nفهم لا يام الحفائظ مفزع … وهم لا يام المكارم مظمع\nهتف العلاء بهم إلى غاياته … فتضرع القوم اللئام وأسرعوا\nانا غرسكم والغصن لدن والصبا … غض وللعيس القياد الأطوع\nرشتم سهامي للعدى ، وتركتم … قدمي إلأى امد المعالي تتبع\nوحثثتم حظي ليلحق شاؤكم … حتى استمر وحظ غيري يقدع\nوصنعتم فعرفت قدر صنيعكم … ولربما غلط الطريق المصنع\nوحفظت ما استودعت من نعمائكم … إن الوفاء أمانة تستودع\nيا باني الشرف الموطد حيث لا … تصل العيون ولا تنال الأذرع\nوسليل محصنة العلى في حجرها … مستودع وبدرها مسترضع\nتحنو الملوك من جنباته … كالقلب حانية عليه الاضلع\nارنق لها فتق النوائب بالندى … او بالقنا ولكل خرق مرقع\nواسلك سبيل أبيك ، إن سبيله … لقم يجيز إلى المناقب مهيع\nواطلب على ايامه وجياده … حسرى يردن على الطعان وظلع\nتدق الغوار على الغوار كأنها … وطفاء تحفزها بليل زعزع\nوالصبح منقد القميص كما جلا … عن حر مفرقه البجال الانزع\nواستقبل الأيام غير جوامح … يثني إليك بها عنان طيع\nتعنو لأخمصك الخطوب ذليلة … بعد العراك وخدهن الاضرع\nإن سر أمسك كان يومك فوقه … ويقل عند غد لما يتوقع"},{"id":"diwan-radi:330","bookId":"diwan-radi","type":"poem","seq":330,"chapter":"البحر: وافر تام","title":"طلاب العز من شيم الشجاع","page":"","text":"طلاب العز من شيم الشجاع … وسعي المرء تحرزه المساعي\nودون المجد قلب مستطيل … وباع غير مجبوب الذراع\nأخوف بالزماع ، ولست أدري … بأين اجر ناصية الزماع\nولست أضل في طرق المعالي … ونار العز عالية الشعاع\nويعجبني البعاد كان قلبي … يحدث عن عدي بن الرقاع\nلقيت من المقام على الأماني … كما لقي الطموح من الصقاع\nولو اني ملكت عنان طرفي … أخذت على الوسيقة بالكراع\nوكنت اذا تلون لي خليل … تلون بي له خلو النزاع\nبخيل بالسلام اذا التقينا … ولكني جواد بالوداع\nايصرعني الزمان ولست آوي … إلأى جنب ذليل للصراع\nوأرضع بالخداع عن المعالي … وكان الطفل أولى بالرضاع\nألا لله طينتنا بأرض … مشوهة المعالم والبقاع\nإذا مرق الدجى منا أخذنا … عليها بالمذانب والتلاع\nوأولى بالضيافة ، لو علمنا … خصيب الرحل مطروق الرباع\nإلى امل الحسين بسطت ظني … بزين الملة اشتفت الأماني\nإذا بخل الغمام على محل … تدارك غلة الإبل الزماع\nمجيري إن تناكرت الليالي … وعوني ان تكاثرت الدواعي\nوقد جعل الزمان يضئ وجهي … ويرفع ناظري ويمد باعي\nرفعت اليك دعوة مستجير … وانت مدى عقيرة كل داع\nليهنك ما تجدده الليالي … وحسبك من فراق واجتماع\nفذاك الصخر خر من اليفاع … من الاملاك والمال المضاع\nتمارى الناس قبلك وهي غضب … اديوان الضياع ام الضياع\nوعادت في يديك مروضات … وكانت فقع قرقرة بقاع\nظفرت بما اشتهيت وانت وان … ونال الغض غيرك وهو ساع\nيبشر والقلوب مفجعات … كأن بشيره في الخلق ناع\nوما كل المواهب بالاماني … ولا كل الاحاظي بالقراع\nلكل في بلوغ العز طيع … تقلب بين أضلاع السباع\nبزين الملة اشتقت الاماني … من المطل الممانع والدفاع\nواصبحت الشفاه مقلقلات … \nفاعلن بشره في كل وحه … وبين طوله في كل باع\nرآك لكل ما يأتيه أهلا … وأنت أحق ذودا بالمراع\nصنيعا لا يجر عليك منا … وحمل المن غير المستطاع\nأجار أبو الفوارس منك سيفا … تحامته يمين أبي شجاع\nفدى لك من ينازعك الرزايا … ويقرضك الأذى صاعا بصاع\nيعض أنامل الأسد الضواري … عليك بغيظ انياب الافاعي\nرعاك بلحظ طرف غير ران … وعاج عليك سمعا غير واع\nفكنت السيف اغمده جبان … فسل وقد تصدى للمصاع\nالان رد العلا بلا رقيب … وشمر في الأمور ولا تراع\nولا يغررك قعقعة الاعادي … \nرجونا منك يوما مستطيلا … على الاعداء وضاح القناع\nتغيظ الحاسدين به وترضي … قلوبا لا تعلل بالخداع\nاتقنع ان تضام وانت حام … وتهملنا البقاع ، وأنت راع\nوما في الأرض أحسن من يسارا … اذا استولى على مطاع\nالان تراجعت تلك الرعايا … وجهزت الرعية للمراعي\nوعاد السرب امنع من قلوب … تقلب بين اضلاع السماع\nوصار الدهر أمرح من طروب … تصافح سمعه نغم السماع\nتسمح عطفه بعد اجتناب … وتخطم انفه بعد امتناع\nتفاخرنا رجال ليس تدري … بما علم الجبان من الشجاع\nولو خليت عنا في رهان … تبينت البطاء من السراع\nونحن أحق بالدنيا ، ولكن … تخيرت القطوف على الوساع\nاروم بحسن رأيك كل امر … يؤلف فرقة الأمل الشعاع\nوأطلب منك ما لا عيب فيه … واين المجد الا في اصطناعي"},{"id":"diwan-radi:331","bookId":"diwan-radi","type":"poem","seq":331,"chapter":"البحر: طويل","title":"لأغنتك عن وصلي الهموم القواطع","page":"","text":"لأغنتك عن وصلي الهموم القواطع … وعن مشرع الذل الرماح الشوارع\nواي طلاب فاتني وطلائعي … منى قبل اعناق المطي طوالع\nدعيني أقم أرضا ، وأطلب غيرها … فبينهما ان واصل الهم قاطع\nفما كل ممنوح من العز شاكر … ولا كل محظوظ من المال قانع\nوما عاقني ربع ، فبت ولم تبت … يوقعني من غير ذاك المطامع\nقطوع لا قران الرجال كانني … الى كل فج ثائر الرحل نازع\nأفي كل يوم الدهر جانبي … وباع الثناء الحر بالذم بائع\nفلم ألق إلا ماذق الود كاذبا … يسف به من طائر الغدر واقع\nورايعة للبين من عامرية … تتزعزع منها بالسلام الاصابع\nفلو لم تزودنا السلام عشية … لسرنا واعناق المطي خواضع\nتصد حداء حين تبعث وعدها … كذوبا ، وإني بالرجاء لقانع\nأفي كل يوم يعدم الدهر جانبي … ورجع زفيري للحمائم خادع\nحنين المطايا علم الشوق مهجتي … فكيف تسليها الحمام السواجع\nبذلتك قلبا كنت ادخر صوته … اذا لاح لي برق من العزم لامع\nسبقت إلى يأسي رجاي ، فحزته … ولم تنتظر رأي فها انا طامع\nوما عند أملاك الطوائف حاجتي … اذا ما ابت ان تقتضيها القواطع\nوما لي شغل في القريض ، وإنما … أبين فيه ما تقول المطامع\nولو هز أسماع الملوك نشيده … دروان كل المجد ما انا صانع\nتقول لي الأيام ، وهي بخيلة : … ألا أسأل ، فإما ذو عطاء ومانع\nرأيت كريما ما خلا قط من حمى … يزار ولو ان الديار بلاقع\nولا مرضت نار القرى في خيامه … بليل ولو ان الرياح زعارع\nاذا صارعته الريح خلنا شعاعها … يشير إلى الوراد والركب هاجع\nفضنا ، بني فهر ، بما في أكفكم … من المجد ، فالأيام عود وراجع\nوردوا اكف الحرب حلما عن العدى … إذا أمكنت حد السيوف المقاطع\nفكم غارة تسترجف الليل أيقظت … صدور القنا والغادرون هواجع\nعيون العوالي والنجوم روامق … ونقع المذاكى بينهن براقع\nولا بد من شعواء تظما نفوسها … وليس لها إلا السيوف مشارع\nهو اليوم أخفت خيله لمع آله … فاشباحه فوق العجاج لوامع\nترى النقع مسود الذيول وفوقه … رداء الردى تحمر منه الوشائع\nوركب كان الترب ينهض نحوه … يعانقه في سيره ويصارع\nفلو أن ثغر الليل لاح ابتسامه … عن الصبح منه لم تسمه البلاقع\nإذا ما سروا تحت الدجى فوجوههم … لضوء الضحى قبل الصباح طلائع\nوان ادلجوا لم يسئل الليل عنهم … كأنهم فيه النجوم الطوالع\nويبدأ فيها للسراب زخارف … تلاعب لحظ المجتلي وتخادع\nفلا تعجبوا من سيرهم في هجيرها … فجر وغاهم للهجير طبائع\nوأرض يضل الليل بين فروجها … ويجزعه أجزاعها والأجارع\nتخطيتها والصبح يخرق في الدجى … نوافد لا يلقى بها الجو راقع\nتطاول اسر الليل فيها كأنما … دجاه لاعناق النجوم جوامع\nوقد مد من باع المجرة فانثنى … كأن الثريا فيه كف تقارع\nوهبت لضوء الفرقدين نواظري … إلى أن بدا فتق من الفجر ساطع\nكأنهما إلفان قال كلاهما … لشخص اخيه قل فاني سامع\nإذا أنا لم أقبض عن الخل هفوة … فلا بسطت كفي إليه الصنائع\nوإن أنا لم يستنزل المجد حبوتي … فلا اهلت مني الربى والمرابع\nأبا قاسم ! حلاك بالشعر ماجد … عليك له حتى الممات رصائع\nأخ لا يرى الأيام أهلا لمدحه … ولو ضمنت ان لا تراه الفجائع\nشجاع لأعناق النوائب راكب … همام لأطواد الحوادث فارع\nستشرع ماء الفخر في كأس مدحتي … وما انا في ماء الندى منك شارع\nليهنك مولود يولد فخره … أب ، بشره للسائلين ذرائع\nوليد لوان الليل ردي بوجهه … لما جاورته بالجنوب المضاجع\nومبتسم ، يرتج في ماء حسنه … له من عيون الناظرين فواقع\nرمى الدهر منه كل قلب من العدى … بسهم نضا أحقادهم وهو وادع\nيرامونه باللحظ كي يعصفوا به … وأبصارهم صور لديه خواشع\n … لارواحهم في مقلتيه مصارع\nيودون ان لو كا بين قلوبهم … مع الحقد حتى لا تراه المجامع\nمتى ابتسموا فاعلم ثغورهم … دموع ، لها تلك الشفاه مدامع"},{"id":"diwan-radi:332","bookId":"diwan-radi","type":"poem","seq":332,"chapter":"البحر: متقارب تام","title":"تخيرته اطول القوم باعا","page":"","text":"تخيرته اطول القوم باعا … وارحبهم في المعالي ذراعا\nوأخذهم بعنان الخطوب … يجير على الدهر أمرا مطاعا\nبعزم كبارقة المشرفي … يأبى على الهز الا قراعا\nيهاب ويرجى لريب الزمان … كالمنصل راق عيونا وراعا\nوصدر وسيع على النائيات … يبجل اذا غب رأيا وساعا\nترى كل يوم مع الحادثات … عراكا له دوننا أو قراعا\nله قلم إن جرى غربه … أمنا القنا ، وخشينا اليراعا\nومدره قول بيد الخصوم … إذا بلغوا بالخصام القذاعا\nكعالية الرمج ان طاولوه … طال الى المجد نفسا وباعا\nإذا نزعوا عن هوى المكرمات … من اللوم زاد اليها نزاعا\nبحمزة امسيت القى الخطوب … وارمى العدو وارقى اليفاعا\nيدافع ركني حتى انال … ويدفع عني الأعادي دفاعا\nأطال يدي ففرعت الهضاب … وأطلعني بالندى ما استطاعا\nحقوق علي رأى انها … حقوق عليه فوالي وراعى\nفلا الوعد كان مطالا ضمارا … يغر ولا القول زورا خداعا\nصنعت فتممت حسن الصنيع … وكم صانع لا يرب اصطناعا\nتعاطوا صنيعك ، فاستثقلوه … ان التطبع يعي الطباعا\nوغيرك يمطل فعل الجميل … فإن فعل الفعل يوما أضاعا\nتلقاك نيروزك المستجد … يسر عيانا ويرضي سماعا\nولا زال دهرك طوع الجنيب … إذا ما أمرت بأمر أطاعا\nتلاقى الخطوب ثقالا بطاء … وغر الاماني عجالا سراعا\nهمام رميت قيادي اليه … مآلا إلى شعبه وانقطاعا\nمددت يميني فاعلقتها … يدا باصطناع الأيادي صناعا\nإذا قرحت عندنا نعمة … اعاد اياديه فينا جذاعا\nفلو رام قسمة عمري له … لم أرض له العمر إلا مشاعا\nوإن هو ساومني مهجتي … صفقت على راحته بياعا"},{"id":"diwan-radi:333","bookId":"diwan-radi","type":"poem","seq":333,"chapter":"البحر: رجز تام","title":"غالى بها الزائد حتى ابتاعها","page":"","text":"غالى بها الزائد حتى ابتاعها … بادنة قد ملأت أنساعها\nسوغها الراعي ربيع ضارج … والارض قد عم الندى بقاعها\nيوردها بين نطاع فالنقا … زرق جمام لبست يراعها\nطاع لها حمض اللوى ونشرت … لها ربى قباقب أقطاعها\nرعت حلي رامة وشاطرت … جوازي الرمل بها لعاعها\nتلس اثار درور جونة … ألقت على ذي بقر بعاعها\nمسيلة بين العقيق والحمى … أضواج بطن الأرض أو أجزاعها\nتطلق عقل النبت إما رجعت … جلجالها بالرغد أو قتعاعها\nيستفيض العشب لها رؤسه … اذا البروق اعتصرت دفاعها\nحتى بنى الني على سنامها … مبانيا ما بطنت سياعها\nشاغبه الهم فارضاه بها … تشرع عن دار الاذى نزاعها\nإن قطع الراعي عليها لم تبل … أشبعها الخذراف أم أجاعها\nمخيلة مبركها من شخصها … إذا المطايا عمرت رباعها\nتضيع عن غب الونى كانها … عائمة قد رفعت شراعها\nتحسبها الورهاء ريعت فنجت … من الذى طارحة قناعها\nوقرها السير وكانت حقبة … لو سمعت حس القراد راعها\nكأنها طاوي المصير هاجه … عض ضراع قد بلا مصاعها\nاذا رأى افتراقها زاولها … ثم يني اذا رأى اجتماعها\n … مشاورات النفس اوازماعها\nفي عانة تطيعه محاميا … فان رآها شردا اطاعها\nتنتصب انتصابه لنبأة … ذعرا ، وينصاع لها انصياعها\nيحفظها عن سربها … فان رأى جد الردى اضاعها\nأقضى عليها أربا من همة … لو عدل الدهر ثنى زماعها\nمطبوعة على العلى لو رضيت … بالذل يوما أنكرت طباعها\nيا حفظها ان بلغت مرامها … وان ابى الدهر فياضياعها\nأستعجل الأمر وحظي رايث … نفس ارجى ابدا خداعها\nولو قنعت بالحظوظ لم أبل … ابطائها بالرزق ام اسراعها\nاصارع الاقدار عن وقوعها … بمنكب معود صراعها\nتصادف الخرقاء من زمانها … سجال رزق أخطأت صناعها\nقومي الأولى إما جروا لغاية … بذوا بطاء الغاي أو سراعها\nهم الملاجي والمناجي والحمى … إذا المنايا وقعت وقاعها\nهم المعاذ والملاذ والذرى … اذ السيول ركبت تلاعها\nهم المقيلون المنيلون اذا … ما اللزبة اللزباء ألقت باعها\nأزوال أيام الطعان إن طغت … يد الزمان أحسنوا دفاعها\nفي حيث لا تنظر تحت نقعها … الا عصي الموت أو قراعها\nلم يغنموا الاموال الا اخذوا … صفيها ، وقبضوا مرباعها\nتلقى بهم مرسى الوقار والحجى … وضئضئ العلياء أو جماعها\nان نزلوا الجو اماتوا شمسه … والارض كانوا ابدا طلاعها\nبيوتهم مرهوبة تخالها … أولاج غيل رشحت سباعها\nالمانعون الضيم باللدن ترى … هبابها للطعن أو زعزاعها\nكأن في الأيمان حيات النقا … ارقمها التضناض أو شجاعها\nمن كل سوار ، إذا رام العلى … حاز عقاب الجو أو ملاعها\nمحلقا يبلغ منها غاية … لو رامها العيوق ما استطاعها\nحاصوا خصاصات قريش بالقنا … شوارعا ، وجمعوا شعاعها\nردوا على ساداتها احضارها … وضمنوا بيض الطلى ارتجاعها\nوتوجوا بمجدهم مفرقها … عن عطل وسوروا ذراعها\nكانوا صياصيها وكانوا دونها … فراطها في المجد أو نزاعها\nوالزاحمين بالقنا أعداءها … على الثنايا ، منعوا طلاعها\nأيام حطوا بالظبى أغمادها … عن العلى وغمزوا نباعها\nبالخيل لا تعلف الا شدها … أو ملقها بالبيد ، واندراعها\nمثل الرماح هز هزت كعوبها … او كالذباب اتبعت اطماعها\nكأن عقبان الشريف فوقها … تعلو قنان الارض أو جزاعها\nثلمح ما عارضها باعين … مثل الجذى طارحة شعاعها\nهم رفعوا بمجدهم قبابها … وضؤوا من نارهم يفاعها\nحموا بأطراف القنا سوامها … من العدى وامنوا رتاعها\nوالصقوا بالرغم دون نيلها … موارنا قد أوعبوا اجتداعها\nإن كان روع عاقدوا شجاعها … على الردى وامنوا مجزاعها\nكبوا على أذقانها أصنامها … لا ودها ابقوا ولا سواعها\nتدارك الله بجدي عزها … وقد شراها ذلها وباعها\nجازت به حد العلى وقد رأت … تقارع الجدود واصطراعها\nبمجده والعز من ايامه … مدت إلى نيل العلى أضباعها\nواعجبا لعصبة مغرورة … تريد أن تلصق بي قذاعها\nأذهلني استواؤها في غيها … مطيعها أعذل ، أو مطاعها\nتقودني إلى الهوان ضلة … وقد أبى العز لي اتباعها\nتسومني ورد القذى وقد رأت … عزة هذي النفس وامتناعها\nتريد أن ألقى الخنا لقاءها … وأن أنيخ للأذى جعجاعها\nوألبس العار الطويل لبسها … وأرضع الذل لها رضاعها\nقبيلة اغلطها نهج العلى … لؤم عروق جرت انضاعها\nقوم هوت أنفسهم من دلة … وأشرفت حظوظهم أيفاعها\nيا ليتهم حطوا انحطاط قدرهم … او رفعتني همتي ارتفاعها\nاما المعالي فاخذنا اولا … طول سنيها ، وأخذتم ساعها\nأسمحت الدنيا لكم وأعرضت … صنائع لم تحسنوا اصطناعها\nردت عليكم نعم مظلومة … لم تشكورها فانظروا انقطاعها\nيا بئس ما جرت عليك عامدا … من رائعات تكثر ارتياعها\nنفحة عار لذعت أعراضها … لذع اللظى ووقرت اسماعها\nوغادرت صفاحها دامية … عقر المطايا المت ايضاعها\nوامنت منها نزار انها … سؤة قول كفيت سماعها"},{"id":"diwan-radi:334","bookId":"diwan-radi","type":"poem","seq":334,"chapter":"البحر: طويل","title":"خصيم من الايام لي وشفيع","page":"","text":"خصيم من الايام لي وشفيع … كذا الدهر يعصي مرة ويطيع\nوبى ظمأ لولا العلى ما بللته … وفي كل قلب غلة ونزوع\nوما انا ممن يطلب الماء للصدى … ويجمعني والواردين شروع\nرضاعي من الدنيا الممات فطامه … وما نزح الثقدي الغزير رضيع\nأبينا ، ولا ضيم أصاب أنوفنا … وفي الارض مصطاف لنا وربيع\nإذا غدرت نفس الجبان بصبره … حمتنا ذروع طلقة وردوع\nوأقنعنا بالبيد أن ليس منزل … وما بين ايدي اليعملات وسيع\nأبثك أن المال عار على الفتى … وما المال إلا عفة وقنوع\nايطلع لي عزم إلى ما اريده … وصاحب سري في الرجال مذيع\nوتشتاق نفسي حالة بعد حالة … وازجرها اني اذا لقنوع\nواني لاغرى بالنسيم اذا سرى … ويعجبني بالابرقين ربوع\nويحيني علي الشوق نجدي مزنة … وبرق باطراف الحجاز لموع\nولا اعرف الاشجان حتى يشوقني … حمام ببطن الواديين سجوع\nولولا الهوى ما كنت إلا مشمرا … أطاع على رغم الهوى وأطيع\nاذا راق صبح فالحصان مصاحب … وان عاق ليل فالحسام ضجيع\nتركت الليالي خلف ظهري رذية … وصاحبني طاغي الذباب قطوع\nوخاطرت مشغوفا بما أنا طالب … أجوب الدجى والطالبون هجوع\nألا إن رمحا لا يصول لنبعة … وإن حساما لا يقد قطيع\nوفارقت من أبناء قيس وخندف … رجالا ولم تنفر علي ضلوع\nتركتهم يدعون والدمع ناشز … وما ملكت طرفي علي دموع\nوحذرهم مني فؤاد مشيع … وعزم لاقران الرجال قطوع\nونفس على كر النوائب حرة … وقلب على حرب الزمان مطيع\nوقلت : قبول الضيم أعظم خطة … وما الحرفي رحب البلاد مضيع\nفلما رأيت الذل في القوم سبة … ذهبت ، فلم يقدر علي رجوع\nألا إن ليلي بالعراق كأنه … طليح تجافاه الرجال ظليع\nمقيم يعاطيني الهموم وناظري … معنى بأعجاز النجوم ولوع\nوخيل أبحناها السماوة والوجى … تنفر ايديها الحصى وتروع\nإلى ان تسامى الصبح والليل لافظ … حشاشته ، والطالعات تريع\nولله يوم بالعراق نجوته … وايدي المنايا بالنجاء وقوع\nتملست منه أملس الجيب وانثنى … له في جيوب الناكثين ردوع\nتنازعه الأفواه في كل مشهد … وكل حديث كنت فيه بديع\nطعمنا وأطعمنا القنا من دمائه … وسارت بأمال الرجال صدوع\nوتحفظ أيدينا كعوب رماحنا … واطرافها بين القلوب تضيع\nطماعيتي ان املك المجد كله … وكل غلام في العلاء طموع\nومولى يعاطيني الكؤوس تجملا … وقد ود لو ان العقار نجيع\nخبأت له ما بين جنبي فتكة … دهته ، ويوم الغادرين شنيع\nفلا كان يوم لا يدوم وفائه … فإن وفاء في الزمان بديع\nوبعض مقال القائلين مكذب … وبعض وراد الاقربين خدوع\nارى رشادا يصغى ولبس مكلم … ومسترشد يدعو وليس سميع\nوما الناس إلا ماجد متلثم … وآخر مجرور العطاف خليع\nوما الدهر الا نعمة ومصيبة … وما الخلق الا آمن وجزوع\nويوم رقيق الطرتين مصفق … وخطب جراز المضربين قطيع\nعجبت له يسري بنا وهو واقف … ويا كل من اعمارنا ويجوع\nواي فتى من فرع سعد صحبته … وما هجنت تلك الأصول فروع\nخفيف على ظهر النجيب تهزه … عروض على اعطافه وقطوع\nإذا غاب يوم أطلع العز وجهه … وللبدر فينا مغرب وطلوع\nسانقض من ليل الثوبة وفرتي … إلى منزل للدهر فيه خضوع\nارى العيس قد خاط اللغام شفاهها … ومن دونها صعب الضراب منيع\nاذا اخذت منها الازمة حثها … نجاء واعضاد المطي تبوع\nونحن ، إذا طار السياط بشأوها … سجود على اكوارها وركوع\nوإني لا أرضى من الدهر بالرضا … وعزمي اخوذ والزمان منوع\nوفي العيش مشمول النطاف مرقرق … وفي الارض مخنصر الجناب مريع"},{"id":"diwan-radi:335","bookId":"diwan-radi","type":"poem","seq":335,"chapter":"البحر: طويل","title":"اظن الليالي بعدكم سنريع","page":"","text":"اظن الليالي بعدكم سنريع … فمن يبق لي من رائع فتروع\nخذي عدة الصبر الجميل فانه … \nوقد كنت ابكي للاحبة قد أنى … لقلبي سلو واطمأن ولوع\nولكنما أبكي المكارم أخليت … منازل منها للندى وربوع\nوهل أنا جاز ذلك العهد بالبكا … ولو أن كحل الماقيين نجيع\nأبيت وطراق الهموم كأنها … محافل حي تنتجى وجموع\nاقارع اولى الليل عن اخرياته … كاني اقود وهو ظليع\nوعيني لرقراق الدموع وقيعة … لها اليوم من عاصي الشؤون مطيع\nبمن تدفع الجلي بمن ترفع العلى … بمن تحفظ الآمال وهي تضيع\nبمن ينقع الظمآن ، وهو محلأ … بمن يؤمن المطرود ، وهو مروع\nهو الرزء لا يعدو المكارم والعلى … \nواين قوام الدين للبيض والقنا … اذا لم يكن الا اليقين دروع\nواين قوام الدين للنيل والقرى … اذا الجذب معط والسحاب منوع\nالا من لاضياف الشتاء يلفهم … سقيط ظلام قطقط وصقيع\nتجاذبهم ايدي الشمال رباطهم … فيسقط سب أو يضل قطيع\nاذا كان بين البيت والزفزف الصبا … أحاديث تخفى مرة ، وتذيع\nومن للعفاة المرملين يشلهم … من الدهر قرن لا يرام منيع\nفيا راعي الذود الظماء تركتها … وأحفظ راع مذ نأيت مضيع\nوليس لها في الدار دين شريعة … ولا في ثنايا الطالعين طلوع\nولا للغوادي مذ فقدت مزايد … ولا للمعالي مذ عدمت قريع\nأقول لناعيه عقرت ، وجربت … بشلوك فدعاء اليدين خموع\nوغلغل ما بين الحجابين والحشا … كأني أقود النجم ، وهو ظليع\nنعيت الندى غضا يرف نباته … وشمل العلى والمجد وهو جميع\nببدر معم في الكواكب مخول … \nمن القوم طالوا كل طول إلى العلى … اذا اذرع يوما قصرن وبوع\nبنوا في يفاع المجد وهو ممنع … بنى طيرها بين النجوم وقوع\nفلا حملت أم المكارم بعده … صلوم لأشراف العلاء جدوع\nولا أدت الركب الخماص ، على الوجى … سفائن بر ، والسياط قلوع\nإلى أن يزاد المستنيلين بعده … من الحي قر في الظلام وجوع\nأضم عليه الراحتين تعلقا … وقد نزعته من يدى نزوع\nغصبتك علقا لم ابعه ولم اكن … كباغي رباح يشتري ويبيع\nطويتك طي البرد لم ينض من بلى … وقد يغمد المطرور ، وهو صنيع\nاناديك من تحت الخطوب غدي لها … بظهري رحل ضاغط وقطوع\nوما كانت الايام يفرعن هضبتي … لو أنك واع للدعاء سميع\nرمتني سهام البأس بعدك جهرة … وأنبض ، نحوي عاجز وجزوع\nوزال مجن مانع كنت اتقي … به الخطب ، والخطب الجليل قطوع\nوما كنت أدري أن فوقك آمرا … من الدهر يدعو بغتة فتطيع\nفغالب اطماعي عليك مغالب … وقارع آمالي عليك قروع\nعصبت ، فلم أسمح لغير أكفكم … بدري وبعض الحالبين طموع\nإباء ، ولو طارت بكفي مليحة … فأين قوام الدين للخطب يعتري\nلقد لسبتني من عقارب كيدهم … دبوب ، إذا جن الظلام لسوع\nيسومني حسن الثناء وضامن … لسوء مقال أن يسوء صنيع\nوحسبك من ذم الفتى ترك مدحه … لأمر يضيق القول وهو وسيع\nسقاك على نأي الديار وشحطها … ربيع ، وهل يسقي الربيع ربيع\nوحياك عنا كل نجم وشارق … اذا جن ليل أو اضاء صديع\nذكرتك ذكر العاطشات ورودها … تحرق أكباد لها وضلوع\nتقاذفن يطلبن الرواء عشية … نزائع ادنى وردهن نزيع\nضربن طريقا بالمناسم اربعا … إلى الماء لا تدنى إليه شروع\nفهجرا لدار الحي بعد رحيلكم … وما كل اظغان لهن رجوع\nولا مرحبا بالأرض لستم حلولها … وان كان مرعى للقطين مريع\nلقد جل قدر الرزء أن يبلغ البكا … مداه ولو ان القلوب دموع\nولو أن قلبي بعد يومك صخرة … لبان بها وجدا عليك صدوع"},{"id":"diwan-radi:336","bookId":"diwan-radi","type":"poem","seq":336,"chapter":"البحر: بسيط تام","title":"منابت العشب لا حام ولا راع","page":"","text":"منابت العشب لا حام ولا راع … مضى الردى بطويل الرمح والباع\nالقائد الخيل يرعيها شكائمها … والمطعم البزل للديمومة القاع\nمن يستفز سيوفا من مغامدها … ومن يجلل نوقا بين أنساع\nيسقى أسنته حتى تقيء دما … ويهدم العيس من شد وايضاع\nما بات إلا على هم ولا اغتمضت … عيناه الا على عزم وازماع\nخطيب مجمعة تغلي شقاشقه … اذا رموه بابصار واسماع\nلما اتاني نعي من بلادكم … عضضت كفي من غيظ على الناعي\nابدي التصامم عنه حين اسمعه … عمدا وقد ابلغ الناعون اسماعي\nعمت عقيلا وإن خضت بني شبث … بزلاء تملأ أذن السامع الواعي\nليس الشجاع الذي من دون رؤيته … باب يلاحك مصراعا بمصراع\nولا الذي إن مضى أبقى لوارثه … سوائما بين اضواح واجزاع\nلكنه من إذا أودى فليس له … الا عقائل ارماح وادراع\nيعتسه الذئب في الظلماء مرتفقا … على رحابل ملقااة واقطاع\nيذوق العين طمع النوم مضمضة … اذا الجبان ملا عينا بتهجاع\nأشيعث الرأس لا يجري الدهان به … وإن فلي فبماضي الغرب قطاع\nلا يخلف المال إلا ريث يتلفه … ولا يذم على ما روح الراعي\nكم فجعتني الليالي قبله بفتى … مشمر بغروب المجد نزاع\nيمر صوتي ، فلا يلوي بجانبه … وكان يكفيه ايمائي والماعي\nمن كان انسي اضحى وحشتي وغدا … من كان برئي اسبابا لا وجاع\nأنزلته حيث لا يظما إلى نهل … ولا يبالي بإخصاب وإمراع\nوأرتعت حتى إذا لم يبق لي طمع … أملت نهج دموعي غير مرتاع\nفي كل يوم أكر الطرف ملتفتا … وراء نجم من الاقران منصاع\nامانع الدمع عينا حد دامعة … وألزم اليد قلبا جد ملتاع\nهل دمعة حذفتها العين شافية … داء حنوت عليه بين اضلاعي\nأم هل يرد زمان في ثنيته … لنا أوائل سلاف وطلاع\nيحدو على العنف اخرانا ليلحقنا … عجلان ابرك اولانا بجعجاع\nجر الزمان على قومي سنابكه … وأوقع الموت فيهم أي إيقاع\nواستطعمتني المنايا من اضن به … فكان بالرغم اطعامي واشباعي\nقلد جناجنها الانساع وارم بها … مناكب الليل ندبا غير مجزاع\nفلا نجاء من الأقدار طالبة … فاطلب علالة آمال وأطماع\nبينا بسير الفتى حتى دعون به … فرد عارضه ليا الى الداعي\nيسعى مجدا فان الوى به قدر … ضل الدليل وزلت اخمص الساعي\nيا مصعبا بخست ايدي المنون به … فقيد قود ذلول الظهر مطواع\nكم فرجة للاعادي بت تكلؤها … لولاك فاهت بذي ودقين منباع\nالحمتها بصدور الخيل معلمة … إلى الوغى وطوال ذات زعزاع\nأرش فوقك نجدي يمد له … نيل السماء بآذي ودفاع\nيبدو مع الليل رجافا تكركره … ريح النعامى بواني الخطو مظلاع\nوكل هافتة الاعناق ينحرها … لمع البروق على ميث وأجراع\nبرق كخفق جناح المضرحي إذا … جلى الطرائد من ومض وتلماع\nتجير ودقا وترغو من جوانبها … رعدا اذا قيل قد همت باقلاع\nاستودع الارض خلاني لتحفظهم … لقد وثقت إلى هوجاء مضياع\nلو كان يرتدع القضاء بمردع … أو ينثني بمدجج ومقنع\nلغدت مشمرة تقيك من الردى … عصب تجر قنا الطعان وتدعي\nومسددون أسنة يزنية … فتلوا بأكعبها حبال الأذرع\nقوم ذيولهم الرماح اذا خطوا … رفعوا بمسحبها غبار الأجرع\nخيل توقح بالنجيع من الوجى … وقني تثقف بالظلى والاضلع\nمتعلقين عنان كل مسوم … يشأى عجاجته بوقع الأربع\nذي غرة سبغت عليه كأنه … فيها يمد لحاظه من برقع\nقعد عن الغنم القريب المجتبى … سرع إلى الطلب البعيد المنزع\nيا ناشدا همل المساعي نافضا … في إثرها لقم الطريق المهيع\nهيهات لا مسعاة تنشد بعدها … بظبى القواضب والقنا المتزعزع\nان ابن يوسف عريت انقاضه … وثوى بمنزلة المكل المظلع\nمتطامنا من بعد ما وضعت له … أيامه خد الذليل الأضرع\nألقى بطاعته ، ولما يمتنع … ومضى لطيته ولما يرجع\nقذيت له مقل السماح وقد شكا … وهوت له قلل العلاء وقد نعي\nابنته تحت الصفائح لو يرى … ودعوته خلف الجنادل لو يعي\nما لبث من يمسي مجازا للردى … ومعرج القدر المغد المسرع\nيغدو لا قدام الخطوب بمعثر … ويرى بمرئ للمنون ومسمع\nما للزمان يلذ طعم مصائبي … فكانه يظمى ليشرب ادمعي\nمغرى بنزع قوادمي مستعذبا … لتالمي من صرفه وتوجعي\nارعى الذين جنوا ورق الغنى … دوني واعلكني شكيمة مطمعي\nومضى باخوان الصفاء فلم يدع … منهم اخا ثقة ولا عضدا معي\nابكيك يا عبد العزيز بخطة … تعمي مطالعها وخطب مضلع\nومقاوم ما زلت تعجز ليلها … بلسان قوال وقلب سميدع\nاني ارى في المجد بعدك ثلمة … تبقى وخرقا ما له من مرقع\nمن يشرق الخصم الألد بريقه … عيا ويقدع منه ما لم يقدع\nأم من يبلغ بالبلاغة غاية … تلوي بحسرى طالبين وظلع\nأم من يرد من المغيرة غربها … والخيل تنهض كالقطا بالدرع\nبنوافذ للقول يبلغ وقعها … ما ليس يبلغ بالرماح الشرع\nشهب تشعشع في النوائب ضؤها … كالشمس تنغض رأسها للمطلع\nحتى يقول الغابطون وقد رأوا … فعلاته : زاحم بجد أودع\nويود من حمل الثنا لو أصبحت … تلك الاداة على الكمي الاروع\nإن لا تكن في الجمع أمضى طعنة … فلا انت امضى خطبة في المجمع\nإن الفصاحة ذللت لك عنقها … فاخذت منها بالعنان الاطواع\nأمست ظهور المجد عندك ترتقي … منها الى قمع السنام الامنع\nنهاز أذنبة الكلام ، إذا هفا … بشر كبارقة النصول اللمع\nنهاز اذنية الكلام اذا هفا … قلب الجري وعي قول المصقع\nقد قلت للمتعرضين لسطوه … خلوا وجار الارقم المتطلع\nإياكم أن يستضيفكم الدجى … ومقيله ومقيلكم في موضع\nلا تتبعوا شبه الأمور فانه … شبه يتيح الحق عند المقطع\nنثني عليك ثناء راي هجمة … مثل القذاة ملظة بالدمع\nواذا تغيطلت المطالع حيرة … صدع العماية بالقضاء المقنع\nبأبى من استودعته بطن الثرى … وعلمت كيف خيانة المستودع\nياليت شعري من اعد لدهره … ماذا اعد لضيق هذا المضجع\nلم يخل من ترمي الخطوب سواده … من واقع ابدا ومن متوقع\nنجد الضراعة والنقيصة نزرة … إن القلامة شكة للإصبع\nان اقض مفروض البكاء عليكم … متحرجا يجري الدموع تبرعي\nهل تعلمون على بعاد دياركم … أن الغليل عليكم لم ينقع\nلا تعدموا مني وإن بعد المدى … نفس العميد وانة المتفجع\nما شئت من دمع لكم متحدر … وزفير وجد بعدكم مترفع\nأمسى أخ لك لم يجارك في الصبا … طلقا ولا ساقاك در المرضع\nفي صدره ارة عليك من الجوى … تذكى بانفاس المعنى الموجع\nرزء تخضخض سهمه في مقتلي … يمضى الزمان ونصله لم ينزع\nنضح الثرى ذو أنت فيه مجلجل … يستخلف الأكلاء بعد المقلع\nهزج الرعود له بكل ثنية … زجل كشقشقة الفنيق الموضع\nلثق المناخ ثقيلة أوراكه … حضر المجر مروض بالبلقع\nحتى ترى نزع الربى من نوره … غمما يرف على خصيب ممرع\nومتى يكن فيه سقاك نقيصة … أبد الزمان تممتها بالأدمع\n … بعد الجدوب على الغمام المقلع\nونقول فيك ولو سكننا قالت … لت الأيام أكثر ما نقول وندعي\nولقد تجافى المجد عن ثفناته … قلقا عليك فما يقر بمريع\nنقصت اداة الفضل بعدك كلها … فوعى بمصطلم وشم بأجدع\nفاذهب رعاك الله غير مضيع … وسقى ثراك المزن غير مروع\nفالقلب للشانين إن لم يكتئب … والجفن للاعداء ان لم يدمع"},{"id":"diwan-radi:337","bookId":"diwan-radi","type":"poem","seq":337,"chapter":"البحر: طويل","title":"الا ناشدا ذاك الجناب الممنعا","page":"","text":"الا ناشدا ذاك الجناب الممنعا … وجردا يناقلن الوشيج المزعزعا\nومن يملأ الايام بأسا ونائلا … وتثنى له الأعناق خوفا ومطمعا\nأجلي إليه ذلك الخطب مقدما … وقد كان لا يلقاه إلا مروعا\nوجاز أضاميم البلاد مغيرة … وحي نزارا حاسرين ودرعا\nوسمر عقيل تحمل الموت أحمرا … وبيض عقيل تقطر السم منقعا\nولم تخش من حد الصوارم مضربا … ولم تلق من ايدي القبائل مدفعا\nرأى ورق البيض الخفاف هشائما … وشوك العوالي ناصلا أو منزعا\nهو القدر الاقوى الذي يقصف لقنا … ويلوي من الجبار جيدا وأخدعا\nويستهزم الجرد الجياد تخالها … بجافلة الابطال سربا مذعذعا\nترى الظفر الماضي الشباة قلامة … إذا غالب الأقدار ، والباع إصبعا\nأتاني ، وغول الأرض بيني وبينه … فيا لك رزءا ما أمض وأوجعا\nجوانب أنباء وددت بأنني … صممت لها ما أورق العود مسمعا\nتصاممت حتى ابلغ النفس عذرة … وما نطق الناعون الا لا سمعا\nبان ابا حسان كبت جفانه … واخمد نيران القرى يوم ودعا\nاعز على عيني من العين موضعا … والطف في قلبي من القلب موقعا\nاكن غليلي بالضلوع ولم اجد … لقلبي وراء الهم مذ غاب مطلعا\nوفارقني مثل النعيم مفارقا … وودعني مثل الشباب مودعا\nعلا الوجد بي حتى كأن لم أر الردى … يخط لجنب قبل جنبك مصرعا\nلقد صغر الارزاء رزؤك قبلها … وهون عندي النازل المتوقعا\nفإن لم تزل نفسي عليك ، فإنها … ستنفد انفاسا حرارا وادمعا\nفيا لائمي اليوم لا صبر بعده … فطيرا بأعباء الملامة أو قعا\nبرغمك اجممت الصوارم والقنا … واخليت يوم الروع بيضا وادرعا\nومنتجع أرض العدو تخاله … جبال شرورى طلن ميثا واجرعا\nاذا وردت أنقاع ماء وقيعة … أنشت على اخراه بالماء اجمعا\nإذا انقاد علويا حسبت جياده … اكاما عليهن الاجادل وقعا\nمطوت به استراث جماحه … وجعجع بالبيداء حسرى وظلعا\nمن القوم طاروا في الفلاكل طيرة … ومدوا الى الاحساب بوعا واذرعا\nاذا لبسوا الريط اليماني واقبلوا … يجرون منها الشرعبي المضلعا\nحسبت اسود الغاب رحن عشية … تخال بهن البابلي المشعشعا\nصفاح خدود كالذوابل طلقة … يبادون بالظلماء لحما مبضعا\nوابيض من عليا معد سما به … إلى السورة العليا أب غير أضرعا\nكانك تلقى وجهه البدر طالعا … اذا ابتدر القوم المرفعا\nفان الهبت فيه الحفيظة خلته … وراء اللثام الارقم المتطلعا\nيقوم اهتزاز الرمح خبت كعوبه … ويقعد اقعاء ابن عيل تسمعا\nضموم على الهم الذي بات ضيفه … على الامر الذي كان ازمعا\nصليب على قرع الخطوب كانما … يرادين طودا من عماية أفرعا\nوكم مثله يستفرغ الدمع رزؤه … ويوهي صفاة القلب حتى تصدعا\nاذا احجم الاقوام دون ثنية … تجبز الى بحبوحة المجد اطلعا\nتراه الثفال العود في حجراته … وفي الروع الغلام السرعرعا\nفيا بانيا للعز ثلم ما بنى … وباراعيا للمجد اهمل ما رعى\nفقدتك فقد الناظرين تخرما … جميعا عن العينين ، واختلجا معا\nتهافت ثوب المجد بعدك عن بلى … كانك لم ترقع من الارض مرقعا\nلئن بز هذا الحي منك عماده … فغير عجيب أن يعز ، ويمنعا\nفقد تسمع الأذنان أوعب صلمها … ويدرك انف فغمة الطيب اجدعا\nوان يمض نصل من عقيل نجد له … مناصل في ايدي الصيافل قطعا\nفما غيض ذاك الماء حتى علا الربى … ولا اجتث ذاك الأصل حتى تفرعا\nوإن يختلسنا ذلك العضب حادث … فمن بعد ما ابقى الغماد المرصعا\nمجاور قوم أنزلوا دار غربة … إذا ظعنوا لا يظعنون المشيعا\nولا يستجدون اللباس من البلى … ولا يعمرون المنزل المتضعضعا\nبطيئون عن داعي اللقاء تخالهم … إذا ما دعوا يوما مرمين ، هجعا\nحفائر ألقى الجود أفلاذ كبده … بهن وخط المجد فيهن مضجعا\nوحط بهن الرحل تدمى صفاحه … كما افرد الحي الاجب الموقعا\nأجدك لا تلقى لذا المجد جامعا … ولا للمعالي الغر بعدك مجمعا\nوكان طريق الجود عندك مأمنا … فأذأب بالقوم اللئام وأسبعا\nأسيت على آل المسيب أنهم … بدور المعالي غاربات وطلعا\nتفروا تفري السجل دق اديمه … ولما يدع فيه الخوارز مرقعا\nمضوا بعدما أبقوا إلى المجد منهجا … ركوبا باعلى غارب الارض مهبعا\nاذا وضعوا فيه اجازوا الى العلى … وان سار فيه الناس ارذى واظلعا\nولم يتركوا في نصل شنعاء مضربا … ولم يدعوا في قوس علياء منزعا\nتغالتهم ايدي المنون علائقا … من العز قد زايلن عادا وتبعا\nأخلاي ما أبقوا لعيني قرة … ولا زودوا إلا الحنين المرجعا\nوكانوا على الأيام ملهى ومطربا … فقد اصبحوا للقلب مبكى ومجزعا\nكأن عقارا بعدهم بابلية … تخال بها في الرأس نكباء زعزعا\nلها رقصات في الذوائب والشوى … ترد جبان القوم ندبا مشيعا\nشربت بها شرب الظمية صادفت … قرار عبابي من الماء مترعا\nسقاكم وما سقى السحائب غمرة … من الجود أمرى من نداكم وأمرعا\nنشاص الثريا كلما هب بردته … تذبذب يزجي عارضا مترفعا\nحدته من الغورين هوجاء كلما … ونى عجرفت فيه فخب وأوضعا\nتلف به لف الحداة جمائلا … يزاد عن البيداء طردا مدفعا\nكأن بقعقاع الرعود عشية … عشارا يراغين الجلال الجلنفعا\nكأن اليماني حاك في أخرياته … فأعرض أبراد الرباب وأوسعا\nإلى أن تفرى من جلابيبه الصبا … كأن على الجرباء ريطا مقطعا\nفشق على ذاك التراب مزاده … وخوى على تلك القبور وجعجعا\nفبعدا لطيب العيش بعد فراقكم … فلا أسمع الداعي إليه ولا دعا\nولا اسقا للدهر ان صد مؤيسا … ولا مرحبا بالدهر إن عاد مطمعا\nوان عثر الاحياء من بعد موتكم … فلا دعدعا للعاثرين ولا لعا"},{"id":"diwan-radi:338","bookId":"diwan-radi","type":"poem","seq":338,"chapter":"البحر: طويل","title":"عظيم الأسى في هذه غير مقنع","page":"","text":"عظيم الأسى في هذه غير مقنع … ولوم الردى فيما جنى غير منجع\nولا عين إلا الدمع تجري غروبه … فلاق به المقدور إن شئت أو دع\nفليس القنا فيما أصاب بشرع … وليس الظبا فيما الم بقطع\nولا مانع مما رمى الله سهمه … دفاع المحامي وادراع المدرع\nوإن المنايا إن طرفن بفادح … فسيان لقيا حاسر أو مقنع\nإذا انتصر المحزون كان انتصاره … بدمع يزيد الوجد أو عض إصبع\nوان غبين القوم من طاعن الردى … إذا جاء في جيش الرزايا بأدمع\nاترضى عن الدنيا وما زال بركها … على مقصد منا وشلو مبضع\nاذا سمحت يوما بسجواء سجسج … تلتها على عمد بنكباء زعزع\nعلى كل حال من مصيف ومربع … جليد على طول المدى لم يروع\nوكم جف دمع فيك قد كان غربه … بطيئا اذا ما ريم لم يتسرع\nتوقع أمر زاد هما وقوعه … وإن وقوع الأمر دون التوقع\nأيا جدثا وارى من العز هضبة … تمد الى العليا ببوع واذرع\nسقاك ولولا ما تجن من التقى … لقلت شآبيب القعار المشعشع\nوقل لقبر انت سر ضميره … بكاء الغوادي كل يوم بأربع\nوقفت عليه عاطفا فضل عبرة … تفيض على فضل الحنين المرجع\nأقول له ، والعين فيها زجاجة … من الدمع قدوارى بها الجول مدمعي\nوما هي إلا ساعة ، وهو لاحق … بعاد إلى يوم المعاد وتبع :\nهل أنت مجيبي إن دعوت بأنة … وهل أنت غاد بعد طول مدى معي\nوهيهات حالت بيننا مستطيلة … ضموم على الأجرام من كل مطلع\nلنا كل يوم فرحة من مبشر … بمقتبل أو رنة من مفجع\nوطاري رجاء في ملم مسلم … وعارض يأس من خليط مودع\nوما بعد ما بيني وبينك سامعا … وأنت بمرأى من مقامي ومسمع\nلحا الله هذا الدهر ماذا جرت به … نوائبه من مؤلم الوقع مظلع\nلقد جب منا ذروة أي ذروة … فأبنا بأضلاع الأجب الموقع\nأليس عبيد الله خلى مكانه … فلا عطس الاسلام الا باجدع\nتعز امير المؤمنين صريمة … من العزم عن ماضي الصرائم أروع\nلمينك لم يذخرك نصحا اذا حنا … رجال على الغش القديم باضلع\nهو السابق الهادي الى عقد بيعة … رأى الناس فيها بين حسرى وظلع\nغرست به غرسا برى الدهر عوده … وكان متى تغرس على الرغم ينزع\nبقيت امين الله عودا لمفزع … ومرعى لإخفاق ووردا لمطمع\nاذا صفحت عنك الليالي واغريت … بحفظك فيناهان كل مضيع\nفلا فجعت بالعز دارك ساعة … ولا غض من باب الرواق المرفع\nولا برحت تلك الرباع مجودة … على كل حال من مصيف ومريع\nلقد هاج هذا الرزء ريعان زفرة … تلقيتها عن قلب موجع\nولا سبب إلا المودة إنه … تقطع مني ، والقوى لم تقطع\nوليس مقال حركته حفيظة … وعهد كقول القائل المتصنع"},{"id":"diwan-radi:339","bookId":"diwan-radi","type":"poem","seq":339,"chapter":"البحر: منسرح","title":"آب الرديني والحسام معا","page":"","text":"آب الرديني والحسام معا … وام يوب حامل الحسام معه\nان الخفيف الحاذين جدله … معير بالقعود والرتعه\nغدا عليه من كان خيفته … برقا على الهون لازما ظلعه\nلو أنصف الحي من ربيعته … ما صاف محتله ولا ربعه\nوانتزع الثار من مظنته … معاجلا بالدم الذي انتزعه\nبالسمر تهتز في أسنتها … والخيل تعدو العنيق والربعه\nفي جحفل قعقعت حوافزه … قعاقع الرعد حاديا بأقزعه\nتملؤه عين رآه وتر … من الرعب اذن من سمعه\nكان سنانا يزين صعدتهم … شل بذاك السنان من نزعه\nومارنا لم يزل له ظبة … يجدع اعناق حي من جدعه\nيطلعه فوق كل مرقبة … قلب جري وعزمة طلعه\nإذا جرى والحسود في صعد … مع للمعتفين أم ورعه ؟\nخلى غبار المدى له ومضى … يطلب قوت العيون منقطعه\nابكى نداه العريض ام بشره … اللامع للمعفين ام ورعه\nايها عقيل واي منقصة … إيها عقيل الملوك وأي منقصة\nصار طراد الملوك عادتكم … بعد طراد البعوض والقمعه\nألام أني رثيت زافرة … كانوا نجوم الفخار أو لمعه\nإن لا تكن ذي الأصول تجمعنا … يوما فان القلوب مجتمعه\nكم رحم بالعقوق نقطعها … ورحم الود غير منقطعه\nلا تيأسوا من ثقوب زندهم … كانني بالزمان قد قرعه\nلا بد من ان يثوب حالهم … لكل ضيق من الامور سعه"},{"id":"diwan-radi:340","bookId":"diwan-radi","type":"poem","seq":340,"chapter":"البحر: كامل تام","title":"يا يوسف ابن ابي سعيد دعوة","page":"","text":"يا يوسف ابن ابي سعيد دعوة … اوحى اليك بها ضمير موجع\nإن الفجائع بالرجال كثيرة … ولقل من يرعى ومن يتفجع\nلما رأيت الناس بعدك نكبوا … سننن الحفاظ فغادر ومضيع\nقرطست في غرض الوفاء بقولة … لأكون بعدك حافظا ما ضيعوا\nمن كان اسرع عند امرك نهضة … قد بات ، وهو إلى سلوك أسرع\nكم من أخ لك لم يدم لك عهده … قد كان منك بحيث تثنى الإصبع\nلم ينسنا كافي الكفاة مصابه … حتى رمانا فيك خطب مظلع\nقرف على قرح تقارب عهده … إن القروف على القروح لأوجع\nوتلاحق الفضلاء اعضم شاهد … ان الحمام بغير علق مولع\nواها له لو كان اسر يفتدى … برغيبة أو كان خرق يرقع\nفي كل يوم للنعوش مشيع … منا يرف وراجع يسترجع\nكيف الغرور وللفناء ثنية … ويد المنون تشير ثم المطلع\nولرب أصغر عاقد عرنينه … أمسى له في الأرض خد أضرع\nما كنت ابخل ان اطيل لو انه … يجدي المطيل إذا أطال وينفع\nلكنه سيان من تجرى له … عند الفجائع دمعة أو أدمع"},{"id":"diwan-radi:341","bookId":"diwan-radi","type":"poem","seq":341,"chapter":"البحر: بسيط تام","title":"قف موقف الشك لا يأس ولا طمع","page":"","text":"قف موقف الشك لا يأس ولا طمع … وغالط العيش لا صبر ولا جزع\nوخادع القلب لا يود الغليل به … إن كان قلب على الماضين ينخدع\nوكاذب النفس يمتد الرجاء لها … إن الرجاء بصدق النفس ينقطع\nسائل بصحبي أنى وجهة سلكوا … عنا واي الثنايا بعدنا طلعوا\nحدا باظعانهم حتى استمر بها … حادي المقادير لا يلوى بهم ظلع\nغابوا فغاب عن الدنيا وساكنها … مرأ انيق عن الدنيا ومستمع\nبني أبي قد نكى فيكم بشكته … ونال ما شاء هذا الأزلم الجذع\nكنتم نجوما لذي الدهماء زاهرة … تضيء منها الليالي السود والدرع\nان تخب انواركم من بعدما صدعت … ثوب الدجا فلضوء الشمس منقطع\nفي غرة المجد مذ غيبتم كلف … على الزمان وفي خد العلى ضرع\nوبالمواضي حران في الوغى وباعناق … ناق الضوامر مذ أرحلتم خضع\nمصاعب ذعذعت ايدي المنور بها … فطاع معتصم وانقاذ ممتنع\nلم يعدموا يوم حرب تحت قسطلها … طير الرخام على لباتهم تقع\nلم ينزعوا البيض مذ لاثوا عمائمهم … إلا وقد غاض منها الشيب والنزع\nنسابق الموت تطويحا بأنفسنا … حتى كأنا على الآجال نقترع\nابكيهم ويد الايام دائبة … تدوف لي فضلة الكأس التي جرعوا\nلا امتري انني مجر الى امد … جروا إليه قبيل اليوم أو نزعوا\nوأنني وارد العد الذي وردوا … بالكره أو قارع الباب الذي قرعوا\nسدت فواغر افواه القبور بهم … وليس للارض لا ري ولا شبع\nاعتادهم لا ارجى ان يعود لهم … إلي ماض ، ولا لي فيهم طمع\nفما توهج احشاي على نفر … كانوا عوادي للايام فارتجعوا\nنليح ان ترتعي الاقدار انفسنا … وكلنا للمنايا السود مزدرع\nنلهوا وما نحن الا للردى اكل … \nكانوا حوامي جبال العز فانقرضوا … وصدعوا قلل العليا مذ انصدعوا\nفوارس قوضوا عن سابقاتهم … فاستنزلوا بطعان الدهر واقتلعوا\nقوم فكاهتهم ضرب الطلى ولهم … تحت العجاج بأطراف القنا ولع\nإما تؤود من الأيام نائبة … قاموا بها واطاقوا الحمل واضطلعوا\nلا تستلينهم الضراء نازلة … \nكم خمصة كان فيها العز آونة … وشيعة كان فيها العار والضرع\nمن كل أغلب نظار على شوس … له لواء على العلياء متبع\nيخفى به التاج من لألأ غرته … على جبين بضوء المجد يلتمع\nذو عزمة تلهم الدنيا وساكنها … وهمة تسع الدنيا وما تسع\nيلقى الظبى حاسرا تبدو مقاتله … ويرهب الذم يوما ، وهو مدرع\nإن المصائب تنسي المرء مقبلة … قصد الطريق لما يسلي وما يزع\nحتى إذا انكشفت عنه غياطلها … تبين المرؤ ما يأتي وما يدع\nأرسى النسيم بواديكم ولا برحت … حوامل المزن في اجداثكم تضع\nولا يزال جنين النبت ترضعه … على قبوركم العراضة الهمع\nهل تعلمون على نأي الديار بكم … أن الضمير إليكم شيق ولع ؟\nلكم على الدهر من اكبادنا شعل … من الغليل ، ومن آماقنا دفع\nلواعج افصحت عنها الدموع وقد … كادت تجمجمها الأحشاء والضلع\nأنزفت دمعي حتى ما تركت له … غربا يفيض على رزء ، إذا يقع\nثم اضطررت الى صبري فعدت به … وأعرب الصبر لما أعجم الجزع"},{"id":"diwan-radi:342","bookId":"diwan-radi","type":"poem","seq":342,"chapter":"البحر: بسيط تام","title":"صبرت عنك فلم ألفظك من شبع","page":"","text":"صبرت عنك فلم ألفظك من شبع … لكن ارى الصبر اولى بي من الجزع\nوان لي عادة في كل نازلة … أن لا تذل لها عنقي من الضرع\nلذاك شجعت قلبي وهو ذو كمد … وملت بالدمع عني وهو ذو دوع\nماض على وقعات الدهر إن طرقت … غدا بحمل اذاها جد مضطلع\nوحاسر يتلقى كل نائبة … تدمى فيصرفيها صبر مدرع\nلولا اندفاع دموع العين غالبة … لم يعقب الصبر دمعا غير مندفع\nفي اليأس منك سلو عنك يضمره … وقبل يومك يقوى الحزن بالطمع\nما كان ذيلك مسدولا على دنس … ولا نطاقك معقودا على طمع\nما شئت من لين اخلاق ومكرمة … ومن عفاف ومن فضل ومن ورع\nلله نفرة وجد لست أملكها … إذا تذكرت إخوان الصفاء معي\nيواصل الحزن قلبي كلما فجعت … يدي بحبل من الأقران منقطع\nألقى الغمام حواياه على جدث … نزلت منه بملقى غير متسع\nفي حيث لا طمع يوما لذي طمع … في ان يعود ولا رجعى لمرتجع\nلا عين تنظران ارسى بعقوتها … زور ولا اذن عند النداء تعي\nوهون الوجدان الموت مشترك … فينا وانا لذا الماضي من التبع\nهي الثنايا إلى الآجال نطلعها … فمن حثيث ومن راق على ظلع\nكالشاء يعذل منا غير مكترث … عيا ، ويوعظ منا غير مستمع\nالآن يعلم أن العيش مختلس … واننا نقطع الايام بالخدع\nهيهات لا قارج يبقى ولا جذع … على نوائب كر الأزلم الجذع\nإن المنايا لشتى بين طارقة … هونا ، ونافرة عن هول مطلع\nاما فناء عن الدنيا على مهل … أو اعتباطا يغادي غدوة السبع\nما لليالي يرنقن المجاجة من … شربي وبوبين مصطافي ومرتبعي\nعدت عوادي الردى بيني وبينكم … وانزلتك النوى عني بمنقطع\nوشتتت شملك الأيام ظالمة … فشمل دمعي ولبي غير مجتمع\nأخي لا رغبت عيني ولا أذني … من بعد يومك في مرأى ومستمع\nولا أراك بقلب غير مصطبر … إذا أهاب به السلوان لم يطع"},{"id":"diwan-radi:343","bookId":"diwan-radi","type":"poem","seq":343,"chapter":"البحر: طويل","title":"ذكرتك لما طبق الافق عارض","page":"","text":"ذكرتك لما طبق الافق عارض … وأعرض برق كالضرام لموع\nوانت مقيم حيث لا البرق يجتلى … بعين ، ولا روح النسيم يضوع\nغريب عن الأوطان لا لك هبة … إليها ، ولا بعد المضي رجوع\nخلا منك ربع قد تبدلت بعده … ربوع بلى ما مثلهن ربوع\nوعاود قلبي الذكر إذ نحن جيرة … زمانا وإذ شمل الجميع جميع\nواذ عيشنا الرقراق يسبغ خفضه … علينا واذ طير النعيم وقوع\nإلى أن مشى بيني وبينكم الردى … وقطع أقران الصفاء قطوع\nوفي كل يوم صاحب استجده … نيوب ردى في السمام نقيع\nسلام على تلك القبور ، وجادها … باروى واسنى ما يجود ربيع\nفلا تغبطونا إذ أقمنا ، وأنتم … على ظعن ، إن اللقاء سريع"},{"id":"diwan-radi:344","bookId":"diwan-radi","type":"poem","seq":344,"chapter":"البحر: مخلع البسيط","title":"أأترك الغر من لداتي","page":"","text":"أأترك الغر من لداتي … خوالي البيض والدروع\nتحدو الليالي بهم رفاقا … ماضيهم معوز الرجوع\nتفرقوا لا عن اختيار … وانتقلوا لا الى ربوع\nرجعت في اثرهم برغمي … بعد نزاع إلى نزوع\nابقى الجوى جرحة بقلبي … ما عشت مكتومة النجيع\nكم غبن الموت عن كريم … وقارع الخطب عن قريع\nبانوا فلم انتزح عليهم … دمعي ولم استذب ضلوع\nواسفح الدمع للاعادي … اني اذا فارغ الدموع"},{"id":"diwan-radi:345","bookId":"diwan-radi","type":"poem","seq":345,"chapter":"قصائد","title":"يا صاحب القلب الصحيح أما اشتفى","page":"","text":"يا صاحب القلب الصحيح أما اشتفى … ألم الجوى من قلبي المصدوع ؟\nأأسأت بالمشتاق حين ملكته … وجزيت فرط نزاعه بنزوع\nهيهات لا تتكلفن لي الهوى … فضح التطبع شيمة المطبوع\nكم قد نصبت لك الحبائل طمائعا … فنجوت بعد تعرض لوقوع\nوتركتني ظمآن أشرب غلتي … اسفا على ذاك اللمى الممنوع\nقلبي وطرفي منك : هذا في حمى … قيظ وهذا في رياض ربيع\nكم ليلة جرعته في طولها … غصص الملام ومؤلم التقريع\nابكي ويبسم والدجى ما بيننا … حتى أضاء بثغره ودموعي\nتفلي أنامله التراب تعللا … وأناملي في سني المقروع\nقمر اذا استخجلتهبعتابه … لبس الغروب ، ولم يعد لطلوع\nلو حيث يستمع السرار وقفتما … لعجبتما من عزه وخضوعي\nابغي هواه بشافع من غيره … شر الهوى ما نلته بشفيع\nما كان الا قبلة التسليم اردفها … الفراق بضمة التوديع\nكمدي قديم في هواك وانما … تاريخ وصلك كان مذ أسبوع\nأهون عليك إذا امتلأت من الكرى … اني ابيت بليلة الملسوع\nقد كنت اجزيك الصدود بمثله … لو أن قلبك كان بين ضلوعي"},{"id":"diwan-radi:346","bookId":"diwan-radi","type":"poem","seq":346,"chapter":"البحر: طويل","title":"أقول وما حنت بذي الأثل ناقتي :","page":"","text":"أقول وما حنت بذي الأثل ناقتي : … قوي لا ينل منك الحنين الموجع\nتحنين الا ان بي لابك الهوى … ولي لا لك الخليط المودع\nوباتت تشكى تحت رحلى ضمانة … كلانا ، إذا ، يا ناق نضو مفجع\nاحست بنار في ضلوع فاصبحت … يخب بها حر العرام ويوضع\nاروح بفتيان خماص من الجوى … لهم أنة في كل دار وأدمع\nإذا غرد الركب الخفي تأوهوا … لما وجدوا بعد النوى وتوجعوا\nعلى ابرق الحنان كان حنينا … وبالجزع مبكى ان مررنا ومجزع\nتزافر صحبي يوم ذي الائل ذفرة … تذوب قلوب من لظاها وأدمع\nمنازل لم تسلم عليهن مقلة … ولا جف بعد البين فيهن مدمع\nفدمع على بالي الديار مفرق … وقلب على أهل الديار موزع\nارى اليأس حتى تعزم النفس سلوة … ويرجع بي داعي الغرام ، فأطمع\nذكرت الحمى ذكر الطريد محله … يذاد مذاد العاطشات ويرجع\nواين الحمى لا الدار بالدار بعدهم … ولا مربع بعد الحنين مربع\nسلام على الأطلال لا عن جناية … وان كن يأسا حين لم يبق مطمع\nنشدتكم هل زال من بعد أهله … زرود ، ورامته طلول وأربع\nوهل أنبت الوادي العقيقي بعدهم … وبدل بالجيران شعب ولعلع\nفيا قلب ان يفن العزاء فطالما … عهدتك بعد الظاعنين تصدع\nوقد كان من قلبي الى الصبر جانب … فقلبي بعد اليوم للصبر اجمع\nنعم عادني عيد الغرام ونبهت … علي الجوى دار بميثاء بلقع\nوطارت بقلبي نفحة غضوية … ينفسها حال من الروض ممرع\nأصد حياء للرفاق ، وإنما … زمامي منقاد مع الشوق طيع\nنظرت الكثيب الأيمن اليوم نظرة … ترد إلي الطرف يدمى ويدمع\nورب غزال داجن في كناسه … على رقبة الواشين يعطي ويمنع\nوأحسن في الود التقاضي إذا لوى … ويبذل منزور النوال ، فأقنع\nوايقظت للبرق اليماني صاحبا … بذات النقا يخفى مرارا ويلمع\nتعرض نجديا ، وأذكى وميضه … عقيق الحمى منه معان وأجرع\nأأنت معيني للغليل بنظرة … فنبكي على تلك الليالي ونجزع\nمعاذ الهوى لو كنت مثلي في الهوى … اذا لدعاك الشوق من حيث تسمع\nهناك الكرى ، إني من الوجد ساهر … وبرء الحشى ، إني من البين موجع\nفلا لب لي الا تماسك ساعة … ولا نوم لي إلا النعاس المروع\nتصامم عني لائثا فضل برده … ولا يحفل الشوق النؤم المقنع\nطوتك الليالي من رفيق كانه … من العجز يربوع الملا المتقصع\nينام على هد الصفاة بلادة … ألا موطن يدنو بشمل ويجمع\nالا سلوة تنهي الدموع فتنتهي … الا مورد يروى الغليل فينقع\nفصبرا على قرع الزمان وغمزه … وهل ينكر الحمل الذلول الموقع\nوهبت له ظهري على عقر غاربي … فكل زمام قادني منه اتبع\nوكم ظهر صعب عاد بالذل يمتطى … وعرنين آب بات بالضيم يقرع\nوقل لليالي حاملي ، أو تحاملي … فلم يبق في قوس المقادير منزع"},{"id":"diwan-radi:347","bookId":"diwan-radi","type":"poem","seq":347,"chapter":"البحر: طويل","title":"ألا يا غزال الرمل من بطن وجرة","page":"","text":"ألا يا غزال الرمل من بطن وجرة … إللواجد الظمآن منك شروع\nخلا لك في الاحشاء مرعى تروده … وصابك من ماء الدموع ربيع\nألا هل إلى ظل الأثيل تخلص … وهل لثنيات الغوير طلوع\nوهل بليت خيم على ايمن الحمى … وزالت لنا بالابرقين ربوع\nوهل لليالينا الطوال تصرم … وهل لليالينا القصار رجوع\nولم أنس يوم الجزع حسنا خلسته … بعيني ، على أن الزيال سريع\nولما توافقنا ذهلت ولم يحن … لطير قلوب العاشقين وقوع\nعلى حين أعدت حيرتي قلب صاحبي … فرحنا وسوط العامري مضيع\nحديث يضل القلب عند استماعه … فليس عجيبا أن يضل قطيع\nعشية لي من رقبة الحي زاجر … عن الدمع الأ ان تشذ دموع\nوقد أمرت عيناك عيني بالبكا … فقل لي اي الامرين اطيع"},{"id":"diwan-radi:348","bookId":"diwan-radi","type":"poem","seq":348,"chapter":"البحر: طويل","title":"تشاهقن لما أن رأين بمفرقي","page":"","text":"تشاهقن لما أن رأين بمفرقي … بياضا كأن الشيب عندي من البدع\nوقلن عهدنا فوق عاتق ذا الفتى … رداء من الحوك الرقيق فما صنع\nولم أر عضبا عيب منه صقاله … وكان حبيبا للقلوب على الطبع\nوقالوال غلام زين الشيب رأسه … فبعدا لرأس زانه الشيب والنزع\nتسلى الغواني عنه من بعد صبوة … وما أبعد النبت الهشيم من النجع\nوكن يخرقن السجوف اذا بدا … فصرن يرقعن الخروق اذا طلع"},{"id":"diwan-radi:349","bookId":"diwan-radi","type":"poem","seq":349,"chapter":"البحر: خفيف تام","title":"عارضا بي ركب الحجاز من سكن أسائله","page":"","text":"عارضا بي ركب الحجاز من سكن أسائله … متى عهده بسكان سلع\nواستملا حديث من سكن الخفيف … ولا تكتباه الا بدمعي\nفاتني ان ارى الديار بطرفي … فلعلي أرى الديار بسمعي\nيا غزالا بين النقا والمصلي … ليس تبقى على نبالك درعي\nكلما سل من فؤادي سهم … عاد سهم لكم مضيض الوقع\nوتحرجت يوم حراما … من عطائي ، فمن أباحك منعي\nمن معيد أيام سلع على ما … ما كان منها واين ايام سلع\nطالب بالعراق ينشد هيهات … ت ، زمانا أضله بالجزع"},{"id":"diwan-radi:350","bookId":"diwan-radi","type":"poem","seq":350,"chapter":"البحر: طويل","title":"وقفت بربع العامرية وقفة","page":"","text":"وقفت بربع العامرية وقفة … فعز اشتياقي ، والطلول خواضع\nوكم ليلة بتنا على غير ريبة … علينا عيون للنهى ومسامع\nنفض حديثا عن ختام مودة … معاقلها أحشاؤنا والأضالع\nيكاد غراب الليل عند حديثنا … يطير ارتياحا وهو في واقع\nخلونا فكانت عفة لا تعفف … وقد رفعت في الحي عنا الموانع\nسلوا مضجعي عني وعنها فاننا … رضينا بما يخبرن عنا المضاجع"},{"id":"diwan-radi:351","bookId":"diwan-radi","type":"poem","seq":351,"chapter":"البحر: طويل","title":"لقلبي بغوري البلاد لبابة","page":"","text":"لقلبي بغوري البلاد لبابة … وان كنت مسدودا علي المطالع\nلعلي أعطى ، والأماني ضلة … وإن الليالي معطيات موانع\nمبيتي في أثواب ظمياء ، ليلة … بوادي الغضا والعاذلون هواجع\nوما نطفة مشمولة بمنجمة … وعاها صفا من آمن الطود فارع\nمن البيض لولا بردها قلت : دمعة … مرنقة ما اسلمتها المدامع\nيا عذب مما نولتنيه موهنا … وقد شيم بالغور النجوم الطوالع\nارى بعد ورد الماء في القلب غلة … اليك على اني من الماء ناقع\nواني لا قوى ما اكون طماعة … اذا كذبت فيك المنى والمطامع"},{"id":"diwan-radi:352","bookId":"diwan-radi","type":"poem","seq":352,"chapter":"البحر: طويل","title":"تجمجم بالأشعار كل قبيلة","page":"","text":"تجمجم بالأشعار كل قبيلة … وفي القول محفوظ عليها وضائع\nوكل فتى بالشعر تجلو همومه … ويكتب ما تملي عليه المطامع\nوشعري تختص القلوب بحفظه … وتخظى به دون العيون المسامع\nواولى به من كان مثلك حازما … يذبب عن اطرافه ويقارع\nستظفر من نظمي بكل قصيدة … كما حلت الليل النجوم الطوالع\nتضيء قوافيها وراء بيوتها … طراقا ، كما يتلو النصول القبائع\nاذا هزها السمار طار لها الكرى … وهزت جنوب النائمين المضاجع\nوغيرك يعمى عن معان مضيئة … كما تقبض اللحظا لبروق اللوامع\nوما كل ممدوح يلذ بمدحه … ألا بعض أطواق الرقاب جوامع"},{"id":"diwan-radi:353","bookId":"diwan-radi","type":"poem","seq":353,"chapter":"البحر: طويل","title":"وعاري الشوى والمنكبين من الطوى","page":"","text":"وعاري الشوى والمنكبين من الطوى … اتيح له باليل عادي الا شاجع\nأغيبر مقطوع من الليل ثوبه … انيس باطراف البلاد البلانع\nقليل نعاس العين إلا غيابة … تمر بعيني جاثم القلب جائع\nاذا جن ليل طارد النوم طرفه … ونص هدى االحاظه بالمطامع\nيراوح بين الناظرين إذا التقت … على النوم أطباق العيون الهواجع\nله خطفة حذاء من كل ثلة … كنشطة أقنى ينفض الطل واقع\nالم وقد كاد الظلام تقضيا … يشرد فراط النجوم بالطوالع\nطوى نفسه وانساب في شملة الدجى … وكل امرء ينقاد طوع المطامع\nإذا فات شيء سمعه دل أنفه … وان فات عينيه رأى بالمسامع\nتظالع حتى حك بالأرض زوره … وراغ ، وقد روعته ، غير ظالع\nيخادعه مستهزئا بلحاظه … تداركها مستنجدا بالأكارع\nجري يسوم النفس كل عظيمة … وبمضى اذا لم يمض من لم يدافع\nاذا حافظ الراعي على الضان غره … \n … خداع ابن ظلماء كثير الرقائع\nولما عوى والرمل بيني وبينه … تيقن صحبي انه غير راجع\nتأوب ، والظلماء تضرب وجهه … إلينا ، بأذيال الرياح الزعازع\nله الويل من مستطعم عاد طعمه … لقوم عجال بالقسي النوازع"},{"id":"diwan-radi:354","bookId":"diwan-radi","type":"poem","seq":354,"chapter":"البحر: طويل","title":"ولا قرن الا دامع الطعن نحره","page":"","text":"ولا قرن الا دامع الطعن نحره … وما غسلته بالدموع مدامعه\nويوم كان السمهري عيونه … إلى الموت ، والنقع المثار براقعه\nيخرق منه كل جلباب مهجة … على انه في منظر العين راقعه"},{"id":"diwan-radi:355","bookId":"diwan-radi","type":"poem","seq":355,"chapter":"البحر: طويل","title":"وليل كجلجاب الشباب رقعته","page":"","text":"وليل كجلجاب الشباب رقعته … بصبح كجلباب المشيب طلائعه\nكان سماء اليوم ماء اثاره … من الليل سيل فالنجوم فواقعه"},{"id":"diwan-radi:356","bookId":"diwan-radi","type":"poem","seq":356,"chapter":"البحر: كامل تام","title":"ومروع لي بالسلام كانما","page":"","text":"ومروع لي بالسلام كانما … تسليمه فيما يمض وداع\nتغفى بمنظره العيون كانما … وتقيئ عند غنائه الاسماع\nابذاك نستشفى ومن نغماته … تتولد الالام والاوجاع\nأم كيف يطربنا غناء مشوه … أبدا نهال بوجهه ونراع\nنزوي الوجوه تفاديا من صوته … حتى كان سماعه إسماع\nوكأن ضرب بنانه ضرب الطلى … وكانما ايقاعه ايقاع\nاشهى الينا من غنائك مسمعا … زجل الضراغم بينهن قراع"},{"id":"diwan-radi:357","bookId":"diwan-radi","type":"poem","seq":357,"chapter":"البحر: طويل","title":"اروم انتصافي من رجال اباعد","page":"","text":"اروم انتصافي من رجال اباعد … ونفسي أعدى لي من الناس أجمعا\nاذا لم تكن نفس لفتى من صديقه … فلا يحدثن في خلة الغير مطمعا"},{"id":"diwan-radi:358","bookId":"diwan-radi","type":"poem","seq":358,"chapter":"البحر: طويل","title":"سيسكتني يأسي وفي الصدر حاجة","page":"","text":"سيسكتني يأسي وفي الصدر حاجة … كما أنطقتني والرجال المطامع\nبضائع قول عند غيري ربحها … وعندي خسراناتها والوضائع\nغرائب لو هدت على الطود ذي الصفا … اصاخ اليها يذبل والقعاقع\nتضاع كما ضاعت خلاة بقفرة … زفتها النعامى والرياح الزعازع\nكان لساني نسعة حضرمية … طواها ، ولم تبلغ لها السوم ، بائع\nلقد كان لي عن باحة الذل مذهب … ومضطرب عن جانب الضيم واسع\nوما مد ما بيني وبين مذاهبي … حجاز ولا سدت علي المطالع\nاكن ثناي وابن فعلاء معرض … لئن انت لم تسمع فعرضك سامع\nولو ما جزيت القرض بالعرض لم يضع … فان الندى عند الكرام ودائع\nسيدرى من المغبون منا ومنكم … اذا افترقت عما تقول المجامع\nوهل تدعي حفظ المكارم عصبة … لئام ، ومثلي بينها اليوم ضائع\nنعم لستم الأيدي الطوال فعاونوا … على قدركم ، قد تستعان الأصابع\nارى بارقا لم يروني وهو حاضر … فكيف أرجي ربه ، وهو شاسع\nإذا لم يكن وصلي إليكم ذريعة … فيا ليت شعري ما تكون الذرائع\nواخلف شيمي كل برق اشيمه … فلا النؤ مرجو ولا الغيث واقع\nسأذهب عنكم غير باك عليكم … وما لي عذر أن تفيض المدامع\nوأهجركم هجر المفيق من الهوى … خلا القلب منه واطمأن المضاجع\nوأعتد فجا أنتم من حلاله … ثنية خوف ، ما لها اليوم طالع\nوما موقفي والركب يرجو على الصدى … موارد قد نشت بهن الوقائع\nافارقكم لا النفس ولهى عليكم … ولا اللب مخلوس ولا القلب جازع\nولا عاظفا جيدي اليكم بلفتة … من الشوق ما سار النجوم الطوالع\nولا ذاكرا ما كان بيني وبينكم … مراجعة ان المحب المراجع\nنبذتكم نبذ المخفف ثقله … واني لحبل منة الغدر قاطع"},{"id":"diwan-radi:359","bookId":"diwan-radi","type":"poem","seq":359,"chapter":"البحر: بسيط تام","title":"ما اخطاتك سهام الدهر رامية","page":"","text":"ما اخطاتك سهام الدهر رامية … فما أبالي من الدنيا بمن تقع\nالناس خولك غربان على جيف … بله عن المجد إن طاروا وإن وقعوا\nفما لنا فيهم ان اقبلوا طمع … ولا عليهم اذا ما ادبروا جزع"},{"id":"diwan-radi:360","bookId":"diwan-radi","type":"poem","seq":360,"chapter":"البحر: طويل","title":"يقولون ماش الدهر من حيث مامشى","page":"","text":"يقولون ماش الدهر من حيث مامشى … فكيف بماش يستقيم واظلع\nوما واثق بالدهر الا كراقد … على فضل ثوب الظل والظل يسرع\nوقالوا : تعلل ! إنما العيش نومة … يقضى ويمضى طارق الهم اجمع\nولو كان نوما ساكنا لحمدته … ولكنه نوم مروع مفزع"},{"id":"diwan-radi:361","bookId":"diwan-radi","type":"poem","seq":361,"chapter":"البحر: كامل تام","title":"ولرب يوم هاج من طربي","page":"","text":"ولرب يوم هاج من طربي … ولقد يضيق بغيره ذرعي\nمن منظر حسن ومن نغم … ندعوه قيد العين والسمع\nلما أظل الليل مجلسنا … طعن الدجى بأسنة الشمع"},{"id":"diwan-radi:362","bookId":"diwan-radi","type":"poem","seq":362,"chapter":"البحر: كامل تام","title":"خلطوا الصوارم بالقنا ، وتعمموا","page":"","text":"خلطوا الصوارم بالقنا ، وتعمموا … بالبيض ، واجتابوا العجاج دروعا\nقوم إذا هتف الصريخ بنصرهم … فجروا عليه من الظبة ينبوعا"},{"id":"diwan-radi:363","bookId":"diwan-radi","type":"poem","seq":363,"chapter":"البحر: كامل تام","title":"شرس تيقظه تيقظ خائف","page":"","text":"شرس تيقظه تيقظ خائف … وفعال نجدته فعال شجاع\nومدربين على اللقاء كانهم … لم يخلقوا إلا ليوم قراع"},{"id":"diwan-radi:364","bookId":"diwan-radi","type":"poem","seq":364,"chapter":"البحر: طويل","title":"تضيق صدور العتب ، والعذر أوسع","page":"","text":"تضيق صدور العتب ، والعذر أوسع … ويجمح طرف الهجر والود أطوع\nلك الله من قلب ملاه وفاؤه … فليس لعذر في نواحيه مرتع\nولي خاطر ما ان سلكت مضاءه … على الهم إلا كاد في الدهر يقطع\nاليك فما تظمى الى الغدر همتي … إذا ما سقاني من ودادك مشرع\nولكنني في معشر حلي ودهم … اذا ما اجتلته النائبات التصنع\nاذا ركضت اقوالهم في مسامعي … على العذر جاءت خاطري وهي ظلع\nلحا الله هذا الدهر سيفا على المنى … اوصل ارابي بها ويقطع\nاذا شمت منه بارق العزم ردني … كليل لحاظ الناس والخطب يهمع\nصحبت الرجال الخابطين الى العلى … فثبطني لؤم الزمان وأسرع\nامالي من حظ المكارم ان ارى … سريعا إلى داعي العلى حين يسمع\nترد سهامي الحادثات طوائشا … وفي قوس عزمي لو تبوع منزع\nأصرف فهمي ، والمقاول سرع … واملك حلمي والعوامل شرع"},{"id":"diwan-radi:365","bookId":"diwan-radi","type":"poem","seq":365,"chapter":"البحر: طويل","title":"ومهتزة العرنين رقراقة السنا","page":"","text":"ومهتزة العرنين رقراقة السنا … تناسب مستن البروق اللوامع\nافاض على اعطافها القين حلة … تفضفضن في مثل النجوم الطوالع\nفجاءت بجسم يملأ العين بهجة … اذا ما اجتلاها حاسر مثل دارع\nيحيا بها من لم تحي يمينه … بغير العوالي والسيوف الققواطع\nاحد من العذل المطل على الهوى … وارهف من غرب النوى في المقاطع"},{"id":"diwan-radi:366","bookId":"diwan-radi","type":"poem","seq":366,"chapter":"البحر: متقارب تام","title":"مقيم من الهم لا يقلع","page":"","text":"مقيم من الهم لا يقلع … وماض من العيش لا يرجع\nويوم اشم باقباله … ويوم بإدباره أجدع\nلأخفق من علقت بالمنى … يداه واثرى الذي يقنع\nوما الذل الا خداع اللئيم … والحر بالذل لا يخدع\nرأينا الرجاء على نأيه … رشاء ، وكل يد تنزع\nبليت وغيري لا يبتلى … بامرين ما فيهما مطمع\nبدهر الوم ولا يرعوي … ومولى اقول ولا يسمع\nوإني ، إذا ما استطال الزمان … انجدني صاحب اروع\nونفس على صبرها مرة … وقلب على رأيه مجمع\nأخوض به كل دوية … يزل بها الخف أو يظلع\nبكل مقلدة بالنسوع … وكان على غيره يدمع\nيصيح الحصى تحت أخفافها … فنونا ، ويصطخب اليرمع\nواني لاوعب في جلدها … وللركب هملجة زعزع\nأقيم وخد الضحى أبيض … واسري ورجه الدجى اسفع\nوامضى اذا بلد المستغير … وهاب الثنية من يطلع\nواشلي على المقربات السياط … إذا ضمها البلد البلقع\nوأوردها الخمس في لجمها … تبرض ما الفت تكرع\nتعجب منها وحوش الفلاة … ة تسري واسرابها رتع\nارى النوم ينبو به ناظري … وكل العيون له مربع\nومن ضاقت الأرض عن همه … حر أن يضيق به مضجع\nلئن كان احزن بي منزل … فمن قبل امرع لي مرتع\nعلى انني عند عض الزمان … صفاة يضن بها المقطع\nلقد عاف امواله من يجود … وقد طلق النفس من يشجع\nوابيض يوم الوغى حاسر … تردى بقائمه الدرع\nتحف مضاربه ماءه … كما حف واديه الأجرع\n … كما هزت القلم الإصبع\nوزغف تحدر عن بيضة … كأن الأغم بها أنزع\nيذلل لي سطوات الزمان … سيفي ومثلي لا يخضع\nتطاولت للبرق لما سرى … وعنقي إلى مثله أتلع\nفما لي لا استعيد الجوى … وقد لاح لي بارق يلمع\nوأبذل قلبا بأمثاله … تضن الجوانح والأضلع\nألا إن قلب الفتى مضغة … تضر ولكنها تتفع\nوابلج اعددته للخطوب … طودا الى ظله ارجع\nكريم الوفاء امين الاخاء … باق على العهد لا يقلع\nسريع إلى دعوتي في الأمور … انى الى صوته اسرع\nجلوت به الدمع عن ناظري … وكان على غيره بدمع\nوكفكفت عمن سواه يدي … وكنت أرى الماء لا يشبع\nدعوتك يا ناصري في الهوى … وكان الى ودك المفزع\nأتاني أنك طوحت بال … زيارة عن عارض يقطع\nلقد نال شكواك من مهجتي … كما نال من عرقك المبضع\nدم جاش شؤبوبه عن يد … يقلبها البطل الأروع\nمفيض ولكنه غايض … وخرق ولكنه يرقع\nولو أن لي فسحة في الزمان … جاءك بي القدر الأسرع\nوان غبت عنك فان الفؤاد … عندك ما فاته موضع\nيعوج عليك فلا ينثني … ويشرب منك فلا ينقع\nواني لتعطفني المطعمات … عليك كما عطف الاخدع\nولولاك لم أعترف بالغرام … ولا قيل إن الفتى موجع\nوما فضل شوقي لولا البكاءخ … ء والشوق عنوانه الادمع"},{"id":"diwan-radi:367","bookId":"diwan-radi","type":"poem","seq":367,"chapter":"البحر: طويل","title":"لئن قرب الله النوى بعد هذه","page":"","text":"لئن قرب الله النوى بعد هذه … وكان لروحات المطي بلاغ\nشغلت بكن النفس عن كل حاجة … وهيهات من شغل بكن فراغ\nوليس لبرد الماء لم تشربي به … إلى القلب مني ، يا أميم ، مساغ"},{"id":"diwan-radi:368","bookId":"diwan-radi","type":"poem","seq":368,"chapter":"البحر: بسيط تام","title":"بالجد لا بالمساعي يبلغ الشرف","page":"","text":"بالجد لا بالمساعي يبلغ الشرف … تمشي الجدود بأقوام ، وإن وقفوا\nأعيا من الدهر خلق لا دوام له … البذل والمنع والإنجاز والخلف\nواط بجفونه أعقاب خلته … يوما ودود ويوما ملة طرف\nراحت تعجب من شيب ألم به … وعاذر شيبه التهمام والأسف\nولا تزال هموم النفس طارقة … رسل البياض إلى الفودين تختلف\nإن الثلاثين والسبع التوين به … عن الصبا ، فهو مزور ومنعطف\nفما له صبوة يبكى بها طلل … ولا له طربة يعلى بها شرف\nأين الذين رموا قلبي بسهمهم … ولم يداووا لي القرف الذي قرفوا\nيشكو فراقهم القلب الذي جرحوا … مني ، وتبكيهم العين التي طرفوا\nكم جاءني الخوف مما كنت آمنه … وكم أمنت التي قلبي بها يجف\nقد يأمن المرء سهما فيه موقعه … وقد يخاف الذي ينأى وينحرف\nلما رأيت مرامي الظن خاطئة … ودون ما ارتجى منكم نوى قذف\nصرفت نفسي عنكم ، وهي غانية … والنفس تصرف أحيانا فتنصرف\nما هز فرعكم يأس ولا طمع … ولا مرى دركم لين ، ولا عنف\nولا لكم في ثنايا الجود مطلع … ولا لكم في ظهور المجد مرتدف\nيأبى لي العز والغراء من شيمي … إمساك حبل غرور ما له طرف\nهبها ضبابة ليل أنت خابطها … إن الظلام ، وإن عناك ، منكشف\nتنظر الصبح أن الصبح منتظر … والفجر يعرب عما أعجم السدف\nكأنني يوم استعطى نوالكم … دان من الصخرة الصماء يغترف\nويوم أدعوكم للخطب احذره … داع يبلغ من قد ضمه الجدف\nما كنتم من سيوفي ، إذ هزرتكم … هز النوابي إذا أمضيتها تقف\nيا راعي الذود لا أصبحت في نفر … تروى البكار وتظما الجلة الشرف\nما أعجب القسمة العوجاء يقسمها … الدار واحدة والورد مختلف\nلئن حرمت من العلياء ما رزقوا … لقد جهلت من الفحشاء ما عرفوا\nلأرحلن المطايا ثم أبركها … حيث اطمأن الندى واستوطن الشرف\nكأنما في رجال الركب خاطرة … تعانق الدو ، والنأجية العصف\nبدار أغلب ما في وعده خلف … للراغبين ، ولا في حكمه جنف\nحيث الحقوق قيام في مقاطعها … وكل من حاكم الأيام منتصف\nراض الأمور أولى شبيبته … فالرأي محتنك والعمر موتنف\nيحي المكارم أبناء له وردوا … كما بنى المجد آباء له سلفوا\nيا ابن الأولى نزلوا العلياء خالية … منازل الدر يرمى دونه الصدف\nالمقدمين ، فلا ميل ، ولا عزل … والحاملون فلا جوز ولا ضعف\nلي فيهم خلف من كل مفتقد … وربما جاز قدر الذاهب الخلف\nفي كل يوم عدو أنت قائده … قود الجنيب ، لما عسفت معتسف\nفي السلم دافقة ، شؤبوبها خضل … والروع بارقة ذو رعدها قصف\nفمن شعاب ندى أمواهه دفع … ومن طعان قنا آباره خسف\nتغدو كأنك ، والهامات طائرة … جان من الحنظل العامي ينتقف\nكأن سيفك ضيف الشيب ليس له … عن الرؤوس ، إذا ما جاء ، منصرف\nفاستأنفوا العز مخضرا زمانكم … كأنما الدهر فيكم روضة أنف\nوابقوا بقاء الدراري في مطالعها … إلا البدور ، فإن البدر ينكسف"},{"id":"diwan-radi:369","bookId":"diwan-radi","type":"poem","seq":369,"chapter":"البحر: بسيط تام","title":"تسعى البكار معناة ، وقد ملكت","page":"","text":"تسعى البكار معناة ، وقد ملكت … أولى الجمام عليها الجلة الشرف\nإذا رأينا قوام الدين راكبها … فليس في ظهرها للقوم مرتدف\nفقل لمعتسف يرجو لحاقهم : … لبث فقد بلغوا العليا وما اعتسفوا\nلو أن عين أبيك اليوم ناظرة … تعجب الأصل مما أثمر الطرف\nونى عن السعي ، فاسترعى مساعيه … مدربا بطريق المجد لا يقف\nقد يسبق الخيل تاليها وإن كثرت … منها الفوارط يوم الجري والسلف"},{"id":"diwan-radi:370","bookId":"diwan-radi","type":"poem","seq":370,"chapter":"البحر: خفيف تام","title":"قل لأقنى يرمي إلى المجد طرفا","page":"","text":"قل لأقنى يرمي إلى المجد طرفا … ضرم يعجل الطرائد خطفا\nطار يستشرف المواقع حتى … وجد العز موقعا فأسفا\nومجاري الزمان خطبا فخطبا … سابقا خطوه صرفا فصرفا\nلاث أبطاله عمائم بيضا … لبسوا تحتها قتيرا وزغفا\nطود يمنى ب … ها لذل وخفا\nقد كفيت السعي الطويل ، وتأبى … أن يرى المجد منك حلسا وقفا\nبين جد بذ الجدود فأوفى … وأب ضمن العلاء ، فوفى\nقام فيه يلف خطبا بخطب … لا نؤوما ، ولا سؤوما ألفا\nعقدوا بينكم وبين المعالي … قبل يعلو الرجال عقدا وحلفا\nركبوا صعبة العلى أول النا … س ، فمن جاء بعدهم جاء ردفا\nبيت جود تكفي النوائب فيه … وجفان القرى به ليس تكفا\nعنده النار أوقدت باليلنجو … جي تذكى عرفا ، وتجزل عرفا\nقد بلاك الأعداء حلوا ومرا … وبلوا شيمتيك لينا وعنفا\nفراؤك الحسام قدا وقطا … إذا ما ضفا عليك ورفا\nحسبوها تصنعا فرأوها … كل يوم تزداد ضعفا وضعفا\nكهلال السحاب ما غاب حتى … رق عن وجهه الغمام فشفا\nخلق ثابت إذا غير الدهر … رجالا أخلاقهم تتكفا\nإن تناسوا تذكر الجود طبعا … أو تولوا ثنى إلى المجد عطفا\nفي رواق من القنا لا ترى في … هلقد جاذب الزمام الأكفا\nرسبوا في غمارها ، ولو أن ال … بعد ما غض ناظريه وأغفى\nإن من ضوئها لذي التاج تاجا … ولرب الأطواق طوقا وشنفا\nفابق للخطب مقذيا منه عينا … كل يوم ، ومرغما منه أنفا\nصل بفخر الملك الأغر حساما … تجمع الماضيين عضبا وكفا\nداعم الملك يوم مال ولاقى … موجانا من الخطوب ورجفا"},{"id":"diwan-radi:371","bookId":"diwan-radi","type":"poem","seq":371,"chapter":"البحر: كامل تام","title":"ردوا الغليل لقلبي المشغوف","page":"","text":"ردوا الغليل لقلبي المشغوف … وخذوا الكرى عن ناظري المطروف\nودعوا الهوى يقوى علي مضاعفا … أني على الأشجان غير ضعيف\nولقد رتقت على العذول مسامعي … وصممت عن عذل وعن تعنيف\nأرضى البطالة أن تكون قلائدي … أبدا ولوم اللائمين شنوفي\nهل دارنا بالرمل غير نزيعة … أم حينا بالجزع غير مخلوف\nفلقد عهدت بها كنافرة المها … من كل ممشوق القوام قضيف\nسرب ، إذا استوقفت في ظبياته … عيني رحت على جوى موقوف\nيرعين أثمار القلوب تواركا … مرعى ربيع بلالوى وخريف\nكم بين أثناء الضلوع لهن من … قرف بأظفار النوى مقروف\nلا تأخذيني بالمشيب فإنه … تفويف ذي الأيام لا تفويفي\nلو أستطيع نضوت عني برده … ورميت شمس نهاره بكسوف\nكان الشباب دجنة فتمزقت … عن ضوء لا حسن ، ولا مألوف\nولئن تعجل بالنصول ، فخلفه … روحات سوف للمنون عنيف\nوإذا نظرت إلى الزمان رأيته … تعب الشريف وراحة المشروف\nأوفيت معتليا عليكم واضعا … ومجال كل موضع مضعوف\nأعلي يستل الدني لسانه … سيذوق موبى مربعي ومصيفي\nفيمن تعيرني بفيك رغامها … أبتالدي في المجد أم بطريفي\nابمعشري وهم الأولى عاداتهم … في الروع ضرب طلا وخرق صفوف\nمن كل وضاح الجبين مغامر … عند العظائم ، باسمه مهتوف\nوإذا قرعت ، فهم صدور ذوابلي … ومن العدو معاقلي وكهوفي\nفاذهب بنفسك حاسما اطماعها … عن صل واد أو هزبر غريف\nفلقد جررت على الزمان عوائدي … إني أدق زحوفه بزحوفي\nهذا ، وقومك بين قاذف معشر … كذبا ، وبين ملعن مقذوف\nلا المجد في أبياتهم بمعرق … يوما ولا لهم الندى بحليف\nقبلي سقاك أبي كؤوس مذلة … ولتشربن بيدي كؤوس حتوف\nذاك الثقاف يقيم كل مميل … وأنا الجراز أقد كل صليف\nفحذار إن شب الفنيق لحاظه … وتقاربت أنيابه لصريف\nخل الطريق لمجمر أخفافه … ماض على سنن الطريق منيف\nولضيغم يطأ الرجال ، غلبة … بقنا من الأنياب أو بسيوف\nواشدد حشاك فلست تطمح خاليا … إلا بدا لك موقفي ووقوفي\nوإذا رميت من الحذار بمقلة … في الجو راعك في السماء حفيفي\nأهوى إلى فرص يسوءك غبها … متسرعا كالأجدل الغطريف\nكيدا يري أن لا دعي أمية … قدمي على قمر السماء الموفي\nووليتكم فحززت في عيدانكم … حتى أقام مميلها تثقيفي\nوفطمتكم بالزجر عن عاداتكم … ورددت منكركم إلى المعروف\nعف السريرة لم تلط لريبة … يوما علي مغالقي وسجوفي\nفلئن صرفت فلست عن شرف العلى … ومقاعد العظماء بالمصروف\nولئن بقيت لكم ، فإني واحد … أبدا أقوم منكم بألوف"},{"id":"diwan-radi:372","bookId":"diwan-radi","type":"poem","seq":372,"chapter":"البحر: وافر تام","title":"ردي مر الورود ولا تعافي","page":"","text":"ردي مر الورود ولا تعافي … فما ينأى بيومك أن تخافي\nفطورا تعرضين على زلال … وطورا تعرضين على ذعاف\nومن يشرب بصاف غير رنق … يرد يوما برنق غير صافي\nغمست يدي في أمر فمن لي … وأين بنزع كفي وانكفافي\nكفاني أنني حرب لقومي … وذلك لي من الضراء كاف\nحطمت صعادهم حتى استقاموا … مجاوزة بهم حد الثقاف\nفصرت لذمهم غرضا رجيما … يراموني بمثل حصى القذاف\nوأكذب بالتصون مدعيهم … والجم فائليهم بالعفاف\nولو أني أطعت الرشد يوما … لابدلت التحامل بالتجافي\nوأغضيت اللواحظ عن ذنوب … وموضعها لعيني غير خاف\nولكن الحمية في تأبى … قراري للرجال على التكافي\nوانظر سبة وعظيم عار … رضاي من المنازع بالكفاف\nولو أني رميت أصاب سهمي … ولكني أنقب عن شغافي\nفما سهمي السديد من النوابي … ولا باعي الطويل من الضعاف\nولي أنف كأنف الليث يأبى … شميمي للمذلة واستيافي\nوقد عرف العدى وبلوا قديما … خطاي إلى المنايا وازدلافي\nلي العزم الذي قد جربوه … يقد مضارب البيض الخفاف\nوربط الجأش والاقدام ذل … يزلزلها الردى يوم الوقاف\nوقد كلت صوارمها وملت … عرانين القنى من الرعاف\nفعال أغر ريان العوالي … من الأعداء ملآن الصحاف\nيضيف ، فلا يميز من يراه … أمارات المضيف من المضاف\nإذا عد المناقب جاء بيتي … يجر ذيول أحساب ضوافي\nأقلوا ، لا أبا لكم ، وخلوا … مطاعنة الأسنة بالأشافي\nفقد مدت غيابات المخازي … على عرصاتكم مد الطراف\nصفوت لكم فرنقتم غديري … وأي مضاغن رجع المصافي\nويوشك أن يقام على التقالي … أنابيب رجعن إلى التصافي\nمضى زمن التمازح والتداني … وذا زمن التزايل والتنافي\nلئن أعلى بنائكم اصطناعي … فسوف يثل عرشكم انحرافي\nأداوي دائهم فيزيد خبثا … وليس لداء ذي البغضاء شاف\nحنوت عليهم ولرب حان … على جان وإن بعد التلافي\nفما قلبي وإن جهلوا بقاس … ولا حلمي وإن قطعوا بهاف\nفما تغني القوادم من جناح … تحامل ، إن قعدن به الخوافي\nوعندي للزمان مسومات … من الأشعار تخترق الفيافي\nقصائد أنست الشعراء طرا … عوائهم على أثر القوافي\nبوارد للغليل كان قلبي … يعب بهن في برد النطاف\nأسر بهن أقواما ، وأرمي … أقيواما ، بثالثة الأثافي"},{"id":"diwan-radi:373","bookId":"diwan-radi","type":"poem","seq":373,"chapter":"البحر: طويل","title":"وفى بمواعيد الخليط وأخلفوا","page":"","text":"وفى بمواعيد الخليط وأخلفوا … وكم وعدوا القلب المعنى ولم يفوا\nوما ضرهم أن لم يجودوا بمقنع … من النيل اذمنوا قليلا وسوفوا\nأفي كل يوم لفتة ثم عبرة … على رسم دار أو مطي موقف\nوركب على الأكوار يثني رقابهم … لداعي الصبا ، عهد قديم ومألف\nفمن واجد قد ألزم القلب كفه … ومن طرب يعلو اليفاع ويشرف\nومستعبر قد اتبع الدمع زفرة … تكاد لها عوج الضلوع تثقف\nقضى ما قضى من أنة الشوق وانثنى … بدار الجوى والقلب يهفو ويرجف\nولم تغن حتى زايل البعد بيننا … وحتى رمانا الأزلم المتغطرف\nكأن الليالي كن آلين حلفة … بأن لا يرى فيهن شمل مؤلف\nألم خيال العامرية بعدما … تبطننا جفن من الليل أوطف\nيحيي طلاحا حين هموا بوقعة … تهاووا على الأذقان مما تعسفوا\nوقيدين قد مال النعاس بهامهم … كما أرعشت أيدي المعاطين قرقف\nأعاريب لا يدرون ما الريف بالفلا … ولا يغبطون القوم أما تريفوا\nرذايا هوى إن عن برق تطاولوا … وإن عارضوا الطير الغوادي تعيفوا\nتوارك للشق الذي هو آمن … نوازل بالأرض التي هي أخوف\nأيا وقفة التوديع هل فيك راجع … إشارته ذاك البنان المطرف\nوهل مطمعي ذاك الغزال بلفتة … وإن ثور الركب العجال وأوجفوا\nعشية لا ينفك لحظة مبهت … مراقبة منا ، ودمع مكفكف\nفلله من غنى الحداة ورائه … ولله ما ورى العبيط المسجف\nوسائلة عني كأني لم ألج … حمى قومها واليوم بالنقع مسدف\nلئن كنت مجهولا بذلي في الهوى … فإني بعزي عند غيرك أعرف\nفلا تعجبي أني تعرقني الضنى … فإن الهوى يقوى علي وأضعف\nيقرع باسمي الجيش ثم يردني … إلى طاعة الحسناء قلب مكلف\nسلي بي ألم أنغل في لهواتها … وفحل المردى دوني بنابيه يصرف\nسلي بي ألم أحمل على الضيم ساعدي … وقد ثلم الماضي ، ورض المثقف\nسلي بي ألم أثن الأعنة ظافرا … تحدث عن يومي نزار وخندف\nوحي تخطت بي أعز بيوته … صدور المواضي والوشيج المرعف\nسلي بي ألم أصبر على الظمء بعدما … هوى بالمهارى نفنف ثم نفنف\nوكل غلام ملء درعيه نجدة … ولوثة أعرابية وتغطرف\nعلى كل طاو فيه جد وميعة … وطاوية فيها هباب وعجرف\nوقد أتبعت سمر العوالي زجاجها … وحن من الأنباض جزع معطف\nفإن تسمعوا صوت المرنات تعلموا … بمن جعلت تدعو النواعي وتهتف\nلنا الدولة الغراء ، ما زال عندها … من الجور واق أو من الظلم منصف\nبعيدة صوت في العلى ، غير رافع … بها صوته المظلوم والمتحيف\nونحن أعز الناس شرقا ومغربا … وأكرم أبصار على الأرض تطرف\nبنواكل فياض اليدين من الندى … إذا جاد ألغى ما يقول المعنف\nوكل محيا بالسلام معظم … كثير إليه الناظر المتشوف\nوأبيض بسام كأن جبينه … سنا قمر أو بارق متكشف\nحيي ، فإن سيم الهوان رأيته … يشد ولا ماضي الغرارين مرهف\nلنا الجبهات المستنيرات في العلى … إذا التثم الأقوام زلا وأغدفوا\nأبونا الذي أبدى بصفين سيفه … ضغاء ابن هند ، والقنا يتقصف\nومن قبل ما أبلى ببدر وغيرها … ولا موقف إلا له فيه موقف\nورثنا رسول الله علوي مجده … ومعظم ما ضم الصفا والمعرف\nوعند رجال أن جل تراثه … قضيب محلى ، أو رداء مفوف\nيريدون أن نلقي إليهم أكفنا … وهن دمنا أيديهم ، الدهر ، تنطف\nفلله ما أقسى ضمائر قومنا … لقد جاوزوا حد العقوق وأسرفوا\nيضنون أن نعطي نصيبنا من العلا … وقد عالجوا دين العلى وتسلفوا\nوهذا أبي الأدنى الذي تعرفونه … مقدم مجد أول ومخلف\nمؤلف ما بين الملوك إذا هفوا … وأشفوا على حز الرقاب وأشرفوا\nإذا قال : ردوا غارب الحلم راجعوا … وإن قال : مهلا بعض ذا الجد وقفوا\nوبالأمس لما صال قادر ملكهم … وأعرض منه الجانب المتخوف\nتلافاه حتى سامح الضغن قلبه … وأسمح لما قيل لا يتألف\nوكان ولي العقد والعهد بينه … وبين بهاء الملك يسعى ويلطف\nولما التقى نجوى عقيل لنبوة … ومد لهم حبل من الغدر محصف\nلوى عطفه لي القني رقابهم … ولو لسواه استعطفوا ما تعطفوا\nوسل مضرا لما سما لديارها … فهب ونام العاجز المتضعف\nتولجها كالسيل صلحا وعنوة … فأبقى ورد البيض ظمأى تلهف\nله وقفات بالحجيج شهودها … إلى عقب الدنيا منى والمخيف\nومن مأثرات غير هاتيك لم تزل … لها عنق عال على الناس مشرف\nحمى فاه عن بسط الملوك وقد كبت … عليها جباه من رجال وآنف\nزمام علا لو غيره رام جره … لساق به حاد من الذل معنف\nجرى ما جرى قبلي وها أنا خلفه … إلى الأمد الأقصى أغذ وأوجف\nولولا مراعاة الأبوة جزته … ولكن لغير العجز ما أتوقف\nحذفت فضول العيش حتى رددتها … إلى دون ما يرضى به المتعفف\nوأملت أن أجري خفيفا إلى العلى … إذا شئتم أن تلحقوا فتخففوا\nحلفت برب البدن تدمى نحورها … وبالنفر الأطوار لبوا وعرفوا\nلأبتذلن النفس حتى أصونها … وغيري في قيد من الذل يرسف\nفقد طالما ضيعت في العيش فرصة … وهل ينفع الملهوف ما يتلهف\nوإن قوافي الشعر ما لم أكن لها … مسفسفة ، فيها عتيق ومقرف\nأنا الفارس الوثاب في صهواتها … وكل مجيد جاء بعدي مردف"},{"id":"diwan-radi:374","bookId":"diwan-radi","type":"poem","seq":374,"chapter":"البحر: كامل تام","title":"أشكو إليك مدامعا تكف","page":"","text":"أشكو إليك مدامعا تكف … بعد النوى ، وجوانحا تجف\nوحشا ، إذا ذكر الفراق هفا … في جانبيه الشوق والأسف\nفجعت بعلق مضنة يده … فأقام لا عوض ، ولا خلف\nكالناشط امتنعت موارده … ونأت عليه الروضة الأنف\nأنس تناقص مع تكامله … لا بدع إن البدر ينكسف\nلا يبعد الله الذين نأوا … وقفوا الغرام بنا وما وقفوا\nأي القوى قطعوا ، وأي دم … سفكوا ، وأي جراحة قرفوا\nلم أنس موقفنا ووقفتهم … بعد النوى ، ودموعنا تكف\nمتساكتين من الوجوم ، وقد … نطقت علينا الأدمع الذرف\nيا راكب الكوماء ، غاربها … كالطود أوفى فوقه الشعف\nيطأ الظلام على مفارقه … والليل في أجفانه وطف\nذرع الدجا وطوى خميصته … ولها على قمم الربى كفف\nحتى نضا الإظلام صيغته … وطواه جون الليل منكشف\nماض إذا أهوى به كنف … من جنح ليل ضمه كنف\nأبلغ فتى حمد مذكرة … تنقد منها البيض والزغف\nنفثات مكروب ألظ به … حر الجوى وعلا به الكلف\nما كان أسرع ما نبا زمن … وتكدرت من ودنا نطف\nحبل غدا بأكفنا طرف … منه ، وفي أيدي النوى طرف\nهل حسن ذاك الدهر مرتجع … أم طيب ذاك العيش مؤتنف\nأم هل يباح الورد ثانية … ويلذ برد الماء مرتشف\nلهفي على ذاك الزمان وهل … يثني زمانا ماضيا لهف\nانبت بعدك حبلنا ، وحدت … كلا لطيته نوى قذف\nوانفك سلك نظامنا ، بددا … ولقد عنينا وهو مؤتلف\nوتجنب البتي جانبنا … ونبا فلا ود ولا شعف\nوقلى مجالسنا ومال به … عطف إلى البغضاء منعطف\nوأزيح ذاك الأنس أجمعه … وأميط ذاك البر واللطف\nجعل الوصية تحت أخمصه … وأتى الإساءة وهو معترف\nإنا نذم إليك خلته … فهو الملول الغادر الطرف\nفلعلنا ، ولعل مطمعة … يوما بقربك منه ننتصف\nفسقى ليالينا التي سلفت … فرط من الأنواء أو سلف\nيحدى بسوط الريح تحفزه … هفافة في سوقها عنف\nنتج الصباح عشاره سبلا … جوادا وألقح شوله السدف\nندعوك حين الشمل منشعب … فتلافنا ، والرأي مختلف\nإن لم تقم تلك الغصون غدا … منهن منآد ومنقصف\nلا تحسبن قولي مماذقة … وجدي ببعدك فوق ما أصف"},{"id":"diwan-radi:375","bookId":"diwan-radi","type":"poem","seq":375,"chapter":"البحر: كامل تام","title":"جرعتني غصصا ورحت مسلما","page":"","text":"جرعتني غصصا ورحت مسلما … فلأسقينك مثلها أضعافا\nإن نجتمع يوما أكن لك جذوة … حمراء ، توسع جانبيك ثقافا\nأنسى التفاتي لا أراك ورجعتي … أبكي الديار ، وأندب الألافا\nأنسى ارتفاقي ، والعيون هواجع … وجوانبي عن مضجعي تتجافى\nأنسى اشتمالي بالسقام مقيمة … عندي عقائله وأنت معافى\nكم قد أردت على التبدل خاطري … فإني وازغ عن البديل وعافى\nورقبته فرأيته متمنعا … وبعثته فوجدته وقافا\nوعذرته بعد الإباء لأنه … ظن الذي يطرى كأنت فخافا\nولقد جنيت علي عمدا لا كمن … عرف الجناية مخطئا فتلافى\nما هكذا من كان يزعم أنه … عين الصديق ولا كذا من صافى\nهب لم يكن لك بالوفاء عوائد … أتراك ما أحسنت أن تتوافى\nومن العجائب أن وفيت لغادر … نقض العهود وضيع الأحلافا\nلا كنت من ريب الزمان بسالم … إن كنت تسلم من يدي كفافا\nبل لا التذذت من الزمان بشربة … إن لم أعضك من الزلال ذعافا\nإن حاف لي دهر عليك ، فطالما … مال الزمان علي فيك وحافا"},{"id":"diwan-radi:376","bookId":"diwan-radi","type":"poem","seq":376,"chapter":"البحر: خفيف تام","title":"كل شيء من الزمان طريف","page":"","text":"كل شيء من الزمان طريف … والليالي مغانم وحتوف\nلا يبذ الهموم إلا غلام … يركب الهول ، والحسام رديف\nكلما حزت النوائب فينا … اطلعتنا على الكلوم القروف\nيا أبا الفضل ، والأمور فنون … تبعث الهم والخطوب صروف\nوحفاظي كما علمت ، ولكن … أنكر الغدر ودي المعروف\nإنما الغدر في الرجال أذب … إن تأملت ، والوفاء ألوف\nما يذل الزمان بالفقر حرا … كيف ما كان فالشريف شريف\nإن تكرمت ، فالخليل كريم … أو تمنعت فالملول عنيف\nأو يكن أنكر الإخاء قديما … منك قلب فإن قلبي عروف\nك ، فأين التكرم المألوف … إنما البر منزل مألوف"},{"id":"diwan-radi:377","bookId":"diwan-radi","type":"poem","seq":377,"chapter":"البحر: خفيف تام","title":"أقعدتنا زمانة وزمان","page":"","text":"أقعدتنا زمانة وزمان … جائر عن قضاء حق الشريف"},{"id":"diwan-radi:378","bookId":"diwan-radi","type":"poem","seq":378,"chapter":"البحر: خفيف تام","title":"كم ذميل إليكم ووجيف","page":"","text":"كم ذميل إليكم ووجيف … وصدود عنا لكم وصدوف\nوغرام بكم لو أن غراما … جر نفعا للواجد المشغوف\nكل يوم وداع ركب عجال … بالنوى أو عناء ركب وقوف\nت وأخليت لي مكان الرديف … وطويل على الديار وقوفي\nلم يثقف عودي الزمان ، ولكن … ضج عود الزمان من تثقيفي\nقلت للدهر يوم رام اختداعي … عن جناني الماضي ونفسي العزوف\nونزاع يهفو إليه يلبي … هفوات المصرصر الغطريف\nإن شكواك للزمان مبين … لي على قدر عقله المضعوف\nوالحظوظ البلهاء من ذي الليالي … أنكحت بنت عامر من ثقيف\nإن حرمت الرزق الذي نال منه … فدواء العيي داء الحصيف\nعمل فاضح وأجمل من بعض … الولايات عطلة المصروف\nفاصطبر للخطوب رب اصطبار … شق فجرا من ليلهن المخوف\nإنما نلبس الدروع ثقالا … لرجوع إلى خفاف الشفوف\nإن أولى بالصبر إن حرجته … من حشاه منها كثير القروف\nقر عينا بطارقات الشكايا … ما تجافت مطرقات الحتوف\nكلما كان زائد العقل أمسى … ناقصا من تليده والطريف"},{"id":"diwan-radi:379","bookId":"diwan-radi","type":"poem","seq":379,"chapter":"البحر: كامل تام","title":"قضت المنازل يوم كاظمة","page":"","text":"قضت المنازل يوم كاظمة … أن المطي يطول موقفها\nلمع من الأطلال يحزننا … محتلها البالي ومألفها\nسبقت مدامعها برشتها … من قبل أن يومي مكفكفها\nوتكلفت من صوب ماطرها … فوق الذي يرجو مكلفها\nإن كنت انفدت الدموع بها … فالوجد بعد اليوم يخلفها\nلا منة مني على طلل … ديم طلاع العين أذرفها\nولواعج نفسي ينفسها … وبلابل دمعي يخففها\nظعنوا فللأحشاء مذ طعنوا … حرق تعسفها وتعسفها\nلا تنشدن الدار بعدهم … إني على الإقواء أعرفها\nوعلامة للشوق أضمره … طربي إلي الإيقاع أشرفها\nفي كل يوم لي غريم هوى … يلوي الديون ولا يسوفها\nرفقا بقلبي يا أبا حسن … العين منك وأنت تطرفها\nفكأنني بعلائق شعب … قد زال عن أمم تألفها\nومقومات من غصون هوى … يعوج أطوارا مثقفها\nفي القلب منك جراحة أبدا … ما زلت أدملها وتفرقها\nكم من معاقد بت تفسخها … ومواعد بالقرب تخلفها\nأما الحفاظ فأنت تمطله … والمحفظات فأنت تسلفها\nسأروم عصف النفس عنك وإن … كان الغرام إليك يعطفها\nولطالما استصرفتها مللا … ولئن صحوت فسوف أصرفها\nوإذا طلبت بها السلو أبى … إلا النزاع إليك مدنفها\nفكأن منسيها يذكرها … أو ما يؤسيها يسوفها\nتمضي ونحوكم تلفتها … وإلى لقائكم تشوفها\nفهواكم والشوق يعذرها … وذميم فعلكم يعنفها\nهل يعطفنكم توجعها … أو يقبلن بكم تلهفها\nفاستبق منها ما يضن به … تلك الصبابة أنت ترشفها\nلا تأمننها إن أسأت بها … هي ما علمت وأنت تعرفها\nإن كان يطمعكم تذللها … فلسوف يفزعكم تغطرفها\nولئن غلا فيكم تهالكها … فليكثرن عنكم تعففها\nسأروغ عن ورد الهوان به … هي غرفة لا بد أغرفها\nإن الهضيمة إن أقاد لها … قدر لعمرك لا أؤثفها\nيدنو بنفسي لينها كرما … ويبين عند الضيم عجرفها\nقسما برب الراقصات هوى … أمم البناء العود موجفها\nيطلبن رابدة الظليم إذا … طرق الظلام أضل مسدفها\nبلغت على علل السرى ، وغدت … وملاؤها بالبدن نصفها\nيغدو على الأرقال مؤتدما … من نيها العامي نفنفها\nينجو على رمق مقدمها … ويقيم معذورا مخلفها\nوبحيث جعجعت العريب ضحى … مثل الحني بلى معطفها\nوبفضل ما أوعى محصبها … وأقر من قدم معرفها\nإني على طول الصدود لكم … كالنفس مأمون تحيفها\nأرضى وأغضب في حبابكم … ورقاب ودي لا أصرفها\nجاءتكم أسلا مشرعة … متوقعا فيكم تقصفها\nقد بات فيها قائل صنع … يهمي لهاذمها ويرهفها\nأعزز علي بأن يكون لكم … بالأمس ثقفها مثقفها\nوبراقعا للعار ضافية … يبقى على الأيام مغدفها\nيجلى لأعينكم مشوهها … ولقد يكون لكم مفوفها\nإن تستعيذوا من توسطها … أعراضكم ، فكفى تطرفها\nفتزاجروا من قبل أن تردوا … بموارد . . . . . . ترشفها\nوتغنموا بطاء عارضها … من قبل أن يمريه حرجفها\nفلترجعوا أمما تلومها … ولتقلعوا ندما توقفها"},{"id":"diwan-radi:380","bookId":"diwan-radi","type":"poem","seq":380,"chapter":"البحر: طويل","title":"أقول لها بين الغديرين والنقا","page":"","text":"أقول لها بين الغديرين والنقا … سواد الدجى بيني وبين المناصف\nخذي الجانب الوحشي لا تتعرضي … لحي حلال باللوى والأصالف\nأمامك ! إن الخوف حاد مشمر … وما للمطايا مثل حادي المخاوف\nفمرت تظن النسع صوتا أجيله … فلا عذر إلا تتقي بالعجارف\nوقعت بها في أول الفجر وقعة … غشاشا ، كما أقضي ألية حالف\nوأشممتها رمل الأنيعم غدوة … فسافت بأنف منكر غير عارف\nأحملها الشوق القديم فتنبري … باجلا دعاني القلب جم المشاغف\nكثير التفات الطرف في كل مذهب … بأنة مصدور على البين لاهف\nإذا ما دعاه الشوق راوح كفه … على لاعج في مضمر القلب لاطف\nأعاد له البرق الحجازي موهنا … عقابيل أيام اللقاء السوالف\nكأن به من خطب ظمياء غصة … يسيغ شجاها بالدموع الذوارف\nكان أثيوابي على ذئب ردهة … دني الليل فاستثنى رياح التنائف\nأقومها ، حتى إذا قيل راكب … تظالعت مر المائل المتجانف\nعسفنا بأرقال المطي وطالما … صبرنا على ضيم العدى والمخاسف\nوما سرني أني أقيم على الأذى … وأني بدار الهون بعض الخلائف\nفجوبي الملا أو جاوري بي ربيعة … وأسرة عيلان الطوال الغطارف\nمن البيض ، غران المجالي ، إذا انتدوا … بدا لك بسامون شم المراعف\nهناك إذا استلبست ألبست فيهم … جناحي عتيق آمن الظل واجف\nبحيث إذا أعطى الذمام حبالة … علقت بها غير البوالي الضعائف\nإذا ما طلعت النقب ، والليل دونه … أمنت العدى إلا تلفت خائف\nنجوت فكم من عضة في أنامل … عليك ولهف من قلوب لواهف\nأتوعدني بالقارعات بجيلة … لقد ذل من عرضتم للمتالف\nإذا غضبوا للأمر كان وعيدهم … حبيق الألايا وارتعاد الروانف\nلهم نبعات الشر ينتبلونها … ضروبا ، فمن بادي عقوق وراصف\nمجاهيل أغفال ، إذا ما تعرضوا … بأحسابهم أنكرتهم بالمعارف\nوكم أسرة من غيركم ذات شوكة … دبينا إلى عيدانهم بالقواصف\nعطفنا إليها بالعوالي أسنة … شروعا كأذناب الغظاء الدوالف\nوعدنا بها حمرا تقيء صدورها … دماء العدى قطر الأنوف الرواعف\nوكنا ، إذا داع دعا لوقيعة … سحبنا لها الأرماح سحب المطارف\nعجبت لذي لونين خالط شيمتي … فكشفت منه مخزيات المكاشف\nضممت يدي منه وكانت غباوة … على ضرب مردود من الورق زائف\nيخاوص عين النار خوفا من القرى … إذا نار قوم أوقدت بالمشارف\nوإن آنس الأضياف صمت كلبه … وطأطأ أعناق المطي الصوارف\nنبذتك نبذ السن بعد انفصامها … وإني لمجذام القرين المخالف\nإذا المروء مضته قذاة بطرفه … فغير ملوم إن رماها بحاذف\nوما أنت من جدي فيرجع راجع … من الرحم البلهاء بعض العواطف\nحلفت بمن عج الملبون باسمه … عجيج المطايا من منى والمواقف\nعجافا كأوتار الحنايا من الطوى … على مثل أعجاس القسي العطائف\nطوى الضمر من أجوافها بعدما انتهت … ثمائلها ، طي البرود اللطائف\nترى كل مجهود ، إذا منه السرى … أكب على السرجين إكباب راعف\nورب الهدايا المشعرات نكبها … عجالا ورب الراقصات الخوانف\nوما بالصفا من حالق ومقصر … ومن ماسح ركن العتيق وطائف\nوساع إلى أعلام جمع ، ودافع … وماش على جنبي الآل وواقف\nلأعراضكم عندي أشد مهانة … من الحنظل العامي عند النواقف\nفلا تستهبوا الشر من رقداته … فيسحتكم سحت السنين الخوالف\nقوافي يقطرن السمام كأنها … ملاغم حيات الرمال الزواحف\nفكم حمضة منكم لنا بقرارة … يعود إليها ناشط بعد قاطف\nوإياكم أن تحملوا من قوارضي … على ظهر زعراء الملاطين شارف\nتخب بجانيكم وفي كل ساعة … يتاح لها منكم براق ورادف\nدعوا السلف القمقام تسري رفاقه … لنيل المعالي ، واقعدوا في الخوالف\nوذاك أديم لم تكونوا سراته … بلى ربما استأثرتم بالزعانف\nتغطوا ولا تستكشفوني عواركم … فما جلبة إلا لها ظهر قارف\nوإن مدت الأيام بيني وبينكم … أطلت بكاء العاجز المتهاتف"},{"id":"diwan-radi:381","bookId":"diwan-radi","type":"poem","seq":381,"chapter":"البحر: بسيط تام","title":"الله يعلم ميلي عن جنابكم","page":"","text":"الله يعلم ميلي عن جنابكم … ولو تناهيت لي في البر واللطف\nفكيف بي وعلى عينيك ترجمة … من الحقود وعنوان من الشنف\nأطيف منك بوجه غير ملتفت … إلى المناجي وعطف غير منعطف\nفما أغبك من عذر ولا شغل … ولا أزورك من وجد ولا شغف\nقد كان قبلك مرجو فواضله … راق إلى المجد طلاع إلى الشرف\nتمر نفحة نعماه ، إذا خطرت … من القبول بجنبي روضة أنف\nإن تستعضك المعالي بعد ذاك فقد … أفحشن في بدل منه وفي خلف\nيهتن للمرء تفريه أظافره … كما تهش سباع الطير للجيف\nإذا نجا من يديه غير منعقر … أفنى أنامله عضا من الأسف\nيظن أني وصال به سببي … إني إذا من أمير المؤمنين نفي\nإذا لبست جمالا أنت ملبسه … فإنني قد طرحت المجد عن كتفي\nلا قدس الله نفسا منك جامعة … كيد البغال إلى ذي الجلة الشرف\nولا سقي الغيث دارا أنت ساكنها … إلا بأغبر ناري الذرى قصف"},{"id":"diwan-radi:382","bookId":"diwan-radi","type":"poem","seq":382,"chapter":"البحر: كامل تام","title":"لمن الحدوج تهزهن الأنيق","page":"","text":"لمن الحدوج تهزهن الأنيق … والركب يطفو في السراب ويغرق\nيقطعن أعراض العقيق ، فمشئم … يحدو ركائبه الغرام ومعرق\nأبقوا سيرا بعدهم لا يفتدى … مما يجن وطالبا لا يلحق\nيهفو الولوع به فيطرف طرفه … ويزيد جولان الدموع ، فيطرق\nووراء ذاك الخدر عارض مزنة … لا ناقع ظمأ ولا متألق\nومحجب ، فإذا بدا من نوره … للركب ملتهب المطالع مونق\nخروا على شعب الرحال وأسندوا … أيدي الطعان إلى قلوب تخفق\nهل عهدنا بعد التفرق راجع … أو غصننا بعد التسلب مورق\nشوق أقام وأنت غير مقيمة … والشوق بالكلف المعنى أعلق\nما كنت أحظى في الدنو فكيف بي … واليوم نحن مغرب ومشرق\nمن أجل حبك قلت عاود أنسه … ذاك الحمى وسقي اللوى والأبرق\nطرق الخيال ببطن وجرة بعدما … زعم العواذل أنه لا يطرق\nأتحننا بعد الرقاد وقسوة … أيام أصفيك الوداد وأمذق\nإني اهتديت وما اهتديت وبيننا … سور علي من الطعان وخندق\nومطلحين لهم بكل ثنية … ملقى وسادته الثرى والمرفق\nأو قابضين على الأزمة ، والكرى … يغشى أكفهم النعاس ، فتمرق\nأوموا إلى الغرض البعيد فكلهم … ماض يخب مع الرجاء ويعنق\nوإلى أمير المؤمنين نجت بهم … ميل الجماجم سيرهن تدفق\nكنقانق الظلمان أعجلها الدجى … وحدا بها زجل الرواعد مبرق\nيطلبن زائدة المكارم والندى … حيث استقر بها العلاء المعرق\nالزاخر الغدق الذي يروى به … ظمأ المنى ، والوابل المتبعق\nأبغاة هذا المجد إن مرامه … دحض يزل الصاعدين ويزلق\nهيهات ظنكم تمرد مارد … من دون نيلكم ، وعز الأبلق\nلا حرجوا هذي البحار فربما … كان الذي يروي المعاطش يغرق\nودعوا مجاذبة الخلافة ، إنها … أرج بغير ثنائهم لا يعبق\nغنيت بهم تحتز دون منالها … قمم العدى ويرد عنها الفيلق\nكعقائل الأبطال تجلب دونها … بيض القواضب والقنا المتدقق\nفهم لذروتها التي لا ترتقي … أبدا وبيضتها التي لا تفلق\nأشفت فكنت شفائها ولقد ترى … شلوا بأظفار العدو يمزق\nكنت الصباح رمى إليها ضوءه … ومضى بهبوته الظلام الأورق\nفسنامها لا يمتطى ونباتها … لا يختلى ، وفناؤها لا يطرق\nووزنت بالقسطاس غير مراقب … والعدل مهجور الطريق مطلق\nفي كل يوم للعدو ، إذا التوى … بظباك يوم أوارة ومحرق\nأنتم موادع كل خطب يتقى … \nوأبوكم العباس ما استسقى به … بعد القنوط قبائل إلا سقوا\nبعج الغمام بدعوة مسموعة … فأجابه شرق البوارق مغدق\nما منكم إلا ابن أم للندى … أو مصبح بدم مصبح بدم الأعادي مغبق\nلله يوم أطلعتك به العلى … علما يزاول بالعيون ويرشق\nلما سمت بك غرة موموقة … كالشمس تبهر بالضياء وتومق\nوبرزت في برد النبي وللهدى … نور على اطرار وجهك مشرق\nوعلى السحاب الجود ليث معظما … ذاك الرداء وزر ذاك اليلمق\nفي موقف تغضي العيون جلالة … فيه ، ويعثر بالكلام المنطق\nوكأنما فوق السرير ، وقد سما … أسد على نشزات غاب مطرق\nوالناس إما راجع متهيب … مما رأى أو طالع متشوق\nمالوا إليك محبة ، فتجمعوا … ورأوا عليك مهابة ، فتفرقوا\nوطعنت من غرر الكلام بفيصل … لا يستقل به السنان الأزرق\nوغرست في حب القلوب مودة … تزكو على مر الزمان وتورق\nوأنا القريب إليك فيه ودونه … ليدي عدوك طود عز أعنق\nعطفا ، أمير المؤمنين ، فإننا … في دوحة العلياء لا نتفرق\nما بيننا ، يوم الفخار ، تفاوت … \nإلا الخلافة ميزتك ، فإنني … أنا عاطل منها ، وأنت مطوق"},{"id":"diwan-radi:383","bookId":"diwan-radi","type":"poem","seq":383,"chapter":"البحر: رجز تام","title":"رأى على الغور وميضا فاشتاق","page":"","text":"رأى على الغور وميضا فاشتاق … ما أجلب البرق لماء الآماق\nما للوميض ، والفؤاد الخفاق … قد ذاق من بين الخليط ما ذاق\nداء غرام ما له من إفراق … قد كل آسيه ، وقد مل الراق\nلآل ليلى في الفؤاد أعلاق … تزيد من حيث تقضى الأشواق\nقامت ترآئيك بقلب مقلاق … وللوداع عجل وإرهاق\nمن ثقب الدر النقي براق … يرمي القلوب وأسيلا رقراق\nيقوم لليل مقام الإشراق … حي إذا قام الوغي على ساق\nردوا القنا وطاعنوا بالأحداق … أحبهم على الضنا والإيراق\nحب الضنين المال بعد الإملاق … أن مودات القلوب أرزاق\nمن منصفي من الملول المذاق … قلبي وطرفي من جوى وإقلاق\nفي غرق ما ينقضي وإحراق … يضن حتى بالخيال الطراق\nرمى الإله بالرميض الذلاق … كل غراب بالزيال نعاق\nيا ناق أداك المؤدى يا ناق … ماذا المقام والفؤاد قد تاق\nهل حاجة المأسور إلا الاطلاق … ألهاك عن ليل السرى والإعناق\nمناشط الشيح ورعي الطباق … سيري إلى ورد الجموم الفهاق\nحمل المساعي غير حمل الأوساق … بحيث تسري للعلاء أعراق\nنور الغواشي ومساك الأرماق … من مشعر باتوا بليل العشاق\nإلى المعالي والندى بالأشواق … كانوا إذا أظلم ليل الطراق\nشهب الدياجي ونجوم الآفاق … بيض وجوه كالظبى وأعناق\nأطوع من تيجانها والأطواق … سيان منهم سابق ولحاق\nمن قاد غير المجد منهم أو ساق … مهلا إلى أين الصعود يا راق\nضل المجارون وقام السباق … لم يلحقوا يوما غبار الاطلاق\nإلا قذى لناظر ، أو حملاق … قد رجعوا عنك بلي الأعناق\nهيهات فات الأعوجي المعناق … سهم من الله بعيد الأغراق\nأعطى ديون القوم خصل الأسباق … مسعاة مجد عاق عنها ما عاق\nخطبتها على النجيع المهراق … غراء ما ناكحها بمطلاق\nليس لها إلا الجراز الذلاق … يضرحها ضرح القذى من الماق\nضربا أخاديد وطعنا شهاق … نائي القرارات بعيد الأعماق\nيذكرنا وابل طعن دفاق … \nجماجما من العريب اقلاق … أنذرتهم وثب هريت الاشداق\nطوى من الدماج طي المخراق … صل على حتف العدو مطراق\nمحاذر اللحظ مرجى الإطلاق … سحائب تشئم بعد أعراق\nلنا حياها والزلال الغيداق … وللعدى إرعادها والإبراق\nفي كل يوم ذو الجلال الخلاق … يبري لقوس المجد منكم أفواق\nارقني طولك بعد الاعتاق … أساغ ريقي والخناق قد ضاق\nفأنعم بنيروز إليك مشتاق … والق به من خير ما يلقى اللاق\nفما وقيت ، فالعدى بلا واق … عهد على الأيام باقي الميثاق\nأن لا يرى غصنك ذاوي الأوراق … ضوا من الأثمار بعد الإيراق\nما أهون الفاني إذا كنت الباق … "},{"id":"diwan-radi:384","bookId":"diwan-radi","type":"poem","seq":384,"chapter":"البحر: مجزوء الرمل","title":"خل دمعي وطريقه","page":"","text":"خل دمعي وطريقه … أحرام أن أريقه\nكم خليط بأن عني … ما قضى الدمع حقوقه\nمن لبرق هب وهنا … من أبانين وسوقه\nمن غمام كالمتالي … وخيال دلس القل\nلاح فاقتاد فؤادا … قي على النأي وريقه\nومغاوير الحفيظا … مك أعياد الخليقه\nوملوك في ثراهم … رج للدين مضيقه\nبوجوه واضحات … ه ، إذا ضل طريقه\nوأكف منفقات … ب على العين طروقه\nوبأخلاق رقاق … دون أعراض صفيقه\nطعن فوار الوديقه … عز قدما وفريقه\nاحذر الشمس بجون … يعجل الليل غسوقه\nجلب الخيل ليوم … ض أراب مستذيقه\nمطلت بالرعد حتى … نسي القود عليقه\nكل صدر بالعوالي … يسمع الطعن شهيقه\nفي هجير من أوار ال … بالأسابي عميقه\nيا قوام الدين والفا … هامهم غير مفيقه\nسبق السيل فأعيا … كل باغ أن يعوقه\nلا تعاط اليوم عبأ … ب يدمى ، ودقيقه\nحسب الأوشال جهلا … كالعياليم العميقه\nومدى الجازر تدمى … كالمباتير الرقيقه\nفي معال باقيات … للعدا غير مذيقه\nواثقا بالدهر تعطى … من رزاياه وثيقه\nآمن المرتع ترعى … فيلق جر على أر\nإن نعاق الأعادي … ي ، وإن كنت سحيقه\nم إلى الظئر الشفيقه … ف ، وأطوادا زليقه"},{"id":"diwan-radi:385","bookId":"diwan-radi","type":"poem","seq":385,"chapter":"البحر: كامل تام","title":"يا دار ما طربت إليك النوق","page":"","text":"يا دار ما طربت إليك النوق … إلا وربعك شائق ومشوق\nجاءتك تمرح في الأزمة والبرى … والزجر ورد والسياط عليق\nوتحن ما جد المسير كأنما … كل البلاد محجر وعقيق\nدار تملكها الفراق فرقها … بالمحل من أسر الغمام طليق\nشرقت بأدمعها المطي كأنما … فيها حنين اليعملات شهيق\nخفقت يمانية على أرجائها … وطغت عليها زعزع وخربق\nفي كل أصباح وكل عشية … يسري عليها للدموع فريق\nسخط الغراب على المساقط بينها … فله بأنجاز الفراق نعيق\nفتوزعت تلك القذاة نواظر … وتقسمت تلك الشجاة حلوق\nالآن أقبل بي الوقار عن الصبا … فغضضت طرفي والظباء تروق\nولو أنني لم أعط مجدي حقه … أنكرت طعم العز حين أذوق\nرمت المعالي فامتنعن ولم يزل … أبدا يمانع عاشقا معشوق\nوصبرت حتى نلتهن ولم أقل … ضجرا دواء الفارك التطليق\nما كنت أول من جثا بقميصه … عبق الفخار وجيبه مخروق\nكثرت أماني الرجال ، ولم تزل … متوسعات ، والزمان يضيق\nمن كل جسم تقتضيه حفرة … فكأنه من طينها مخلوق\nومفازة تلد الهجير خرقتها … والأرض من لمع السراب بروق\nبنجاء صامتة البغام كأنها … والآل يركض في الفلاة فنيق\nسبقت إليك العزم طائشة الخطى … فنجت وأعناق المطي تفوق\nجذبت بضبعي من تهامة قاصدا … والنجم في بحر الظلام غريق\nمستشريا برقا تقطع خيطه … فله عن طرر البلاد شروق\nهز المجرة أفقه وكأنها … غصن بأحدق النجوم وريق\nوالليل محلول النطاق عن الضحى … عار ، وعقد الصبح فيه وثيق\nما كان الأهجعة حتى انثنى … والطرف من سكر النعاس مفيق\nوتماسكت تلك العمائم بعد ما … أرخى جوانبها كرى وخفوق\nما رفهت ركباتها إلا وفي … جلد الظلام من الضياء خروق\nيا ناق عاصي من يماطلك السرى … فلحيق غيرك بالعقال خليق\nوردي حياض فتى معد كلها … فالحبل اتلع والقليب عميق\nوإذا تراخت حبوتي أوثقتها … بفناء بيت تربه العيوق\nفي بلدة حرم على أعدائه … وعلى النوائب ربوة إزليق\nتتزاحم الأضياف في أبياته … فرقا تحن إلى القرى وتتوق\nوإذا رآهم لم يقل متمثلا … أبنى الزمان لكل رحب ضيق\nعجبا لربعك كيف تخصب أرضه … وجنابه بدم السوام شريق\nوالخيل تعلم أن حشو ظهورها … منه نهى ينجاب عنها الموق\nما زال يجنبها إلى أعدائه … والشمس تسحب والفلاة تضيق\nمن كل رقاص كأن صهيله … نغم وما مج الطعان رحيق\nطرف تعود أن يخلق وجهه … في حيث ينضو النقع وهو سبوق\nذو جلدة حمراء تحسب أنها … من طول تخليق الرهان خلوق\nواليوم ملطوم السوالف بالظبا … والليل مرتعد النجوم خفوق\nلقطت نفوسهم شفاه صوارم … فرغت وأسياف العوامل روق\nفي كل يوم يندبون مصارعا … للوحش فيها والنسور طروق\nنشوانة الأعطاف من دم فتية … فيهم صبوح للردى وغبوق\nتبكي عليها غير راحمة لها … بالهاطلات رواعد وبروق\nطلعت وفي سجف … الغيوب فتوق\nويكر والفرس الجواد مبلد … ويقد والعضب الحسام معوق\nكرات من شدت قوائم عزمه … فلها رسيم في العلى وعنيق\nكفاه ادبتا السهام فما لها … في النبض عن خطإ البنان مروق\nلولا احتذاء السهم طاعة قوسه … ما شيع النصل المصمم فوق\nيدني الحمام بكفه مترسل … لقضائه نائي السنان رشيق\nنفضت على الأيام منه شمائل … ابرزن وجه الدهر وهو طليق\nوأقام أسواق الضراب فللردى … فيهن من سبي النفوس رقيق\nنفسي فداؤك أي يوم لم تقم … لك فيه من جلب القواضب سوق\nقمر يهاب الموت ضوء جبينه … واليوم خوار العجاج غسوق\nوالسيف ليس يهاب قبل قراعه … حتى يمس العين منه بريق\nعشق السماح وكل سحر للمنى … فيه بأنفاث السؤال يحيق\nطهرت قلبي مذ علمت بأنه … لترى مدائحه العظام طريق\nكم كاهل للشعر أثقل نعته … عطفيه وهو لما يؤد مطيق\nطأطأت فرع المجد ثم جنيته … فارتد وهو على عداك سحوق\nفرع أشار إلى السماء فجازها … حتى كأن له النجوم عروق\nومبخل شهدت عليه يمينه … في حيث يمنعها الندى ويعوق\nيبكي إذا بكت السحاب كأنه … أبدا على طرف الغمام شفيق\nوإذا تعرض عارض أغضى له … ألا يرى الأنواء كيف تريق\nلو أبدت الأيام جانب وجهه … لتشبثته مظالم وحقوق\nإن سار سار إلى النزال بخفية … حتى كأن سلاحه مسروق\nبيت أقام البخل فيه فاستوى … بفنائه المحروم والمرزوق\nيرجو بلوغ نداك وهو محقق … مع حرصه أن الجواد عتيق\nفي الطينة البيضاء غرسك أنه … غرس تداوله البقاع عريق\nفإذا التثمت فكل وجه باسل … وإذا حسرت فكل خد روق\nالله جارك ، والمطي جوائر … والنصر درعك ، والحسام ذليق\nلا زلت تجنب من سيوفك في العدى … نحرا يخب وراءه التشريق\nوإذا جهرت بصوت عزمك مسمعا … أصغى إليك اليمن والتوفيق\nشرفت مدحي فاعتلى بك طوده … ومن المدائح فائق ومفوق\nشهدت له خيل الخواطر أنه … خير الصهيل ، وما سواه نهيق"},{"id":"diwan-radi:386","bookId":"diwan-radi","type":"poem","seq":386,"chapter":"البحر: كامل تام","title":"لو صح أن البين يعشقه","page":"","text":"لو صح أن البين يعشقه … ما استعبرت في السير أينقه\nقمر على غصن يرنحه … مر اللحاظ وليس يرشقه\nطأطأت لحظ العين حين خطا … والبين يرمقني ويرمقه\nواذبت دمعي يوم ودعني … في صحن خد ذاب رونقه\nودعته والبدر تحسبه … متقاعسا في الفجر أعنقه\nوالليل يكبو فيه أدهمه … والصبح ينهض منه أبلقه\nواللثم يركض في سوالفه … وتكاد خيل الدمع تسبقه\nما غرني يوم اللقاء ولا … خدع ارتياح هواي ريقه\nوعلمت حين نشرت مطرفه … إن الفراق غدا يمزقه\nبكت الجفون ، وأنت طارفها … وشكا الفؤاد وأنت محرقه\nودي لخير الناس أذخره … ما كل ود فيك أنفقه\nود تقادم عهده فصفا … وجديد ود المرء أخلقه\nلمشمر الأطراف منزعج … الاعطاف يهجعه تأرقه\nلأغر تعشي الشمس غرته … ويشق جيب الليل مشرقه\nيسري فتحجبه خلائقه … ويضيء أوجهها تخلقه\nأبدت خبي المجد طلعته … وأذاع سر المجد منطقه\nولقلما شرقت أسنته … إلا وصفو الحمد يشرقه\nوإذا استرق المحل مرتبعا … أمر السحاب الجون يعتقه\nوإذا تأمل شخصه ملك … أوما إلى قدميه مفرقه\nفي كفه عارى الذباب له … لمع يدلك كيف ترمقه\nأطغاه رونق غربه ، فطغى … والماء يطغيه ترقرقه\nجذلان يرقص في الرؤوس إذا … غنته بالصهلات سبقه\nصلى الردى لو يستطيع إلى … نصل براحته مخلقه\nيؤوي الضيوف ودون حجرته … باب على الأحداث يغلقه\nوإذا النوائب زعزعت يده … في الطعن جاءته تملقه\nعريان خيل الغدر من دنس … لا يستطيع الغدر يعلقه\nالجود ينهاه ويأمره … والدهر يرجوه ويفرقه\nهو قادر لكن صولته … في البطش يصرعها ترفقه\nولرب مجهول ركائبه … خلف الرياح الهوج تخرقه\nقلقلت بالأجفاف تربته … والقيظ عن أمم يحرقه\nذمتك ربوته ووهدته … وشكاك فدفده وسملقه\nولرب ورد بت قاربه … لا يطمئن به تدفقه\nوالماء يرعد في جوانبه … جزعا وظمء العيس يشرقه\nلما لحظت الدهر زايله … أظلامه وافتر ضيقه\nساورته ، ففضضت سورته … وارتاح في نعماك مملقه\nوكذاك هم الريح في غصن … تثنيه ، أو ماء تصفقه\nلما رآك الملك منصلتا … بالسيف ترعده وتبرقه\nاستنكف التعديل مايله … واسترجع التحكيم أخرقه\nأفل السماح وأنت شارقه … ودجا العلاء وأنت مشرقه\nولرب يوم شمت بارقه … والموت يهطله ويودقه\nوالسيف قائمه يفارقه … والرمح عامله يطلقه\nوالشمس تجري وهي مهملة … في ثوب نقع لا تخرقه\nوالخيل تطبع في حوافرها … وشما تداوله ، وتخلقه\nمن كل ذيال السبيب رمى … بيديه أولى النقع أولقه\nأشليت عزمك في كتائبه … والسهم يشليه مفوقه\nفاسلم على الأيام تلبسها … فالدهر ثوب أنت مخلقه"},{"id":"diwan-radi:387","bookId":"diwan-radi","type":"poem","seq":387,"chapter":"البحر: طويل","title":"بود الرذايا أنها في السوابق","page":"","text":"بود الرذايا أنها في السوابق … وكم للعلى من طالب غير لاحق\nوفي شدة الدهر اعتبار لعاقل … وفي لذة الدنيا غرور لواثق\nأرى العيش أياما تمر وليثنا … نباعد من أحداثها والبوائق\nشهي إلى الناس النجاء من الردى … ولا عنق إلا وهي في فتر خانق\nمستريح من الجوى … كاذب الود ماذق\nوأكثر من شاورته غير حازم … وأكثر من صاحبت غير الموافق\nإذا أنت فتشت القلوب وجدتها … قلوب الأعادي في جسوم الأصادق\nل غير الموافق … من جميع الخلائق\nوعندي من الود الذي لا يشوبه … لحاظ المرائي أو كلام المنافق\nأغالط نفسي بعد مرأى ومسمع … ولا أنظر الدنيا بعين الحقائق\nعلى أنني أدري ، إذا كان قائدي … بقائي ، فإن الموت لا شك سائقي\nوما جمعي الأموال إلا غنيمة … لمن عاش بعدي واتهاما لرازقي\nتنفس في رأسي بياض كأنه … صقال تراق في النصول الروانق\nوما جزعي إن حال لون وإنما … أرى الشيب عضبا قاطعا حبل عاتقي\nفما لي أذم الغادرين ، وإنما … شبابي أدنى غادر بي وماذق\n … ومن لي أن يبقى بياض المفارق\nوإن وراء الشيب ما لا أجوزه … بعائقة تنسي جميع العوائق\nوليس نهار الشيب عندي بمزمع … رجوعا إلى ليل الشباب الغرانق\nوما العز إلا غزوك الحي بالقنا … وربط المذاكي في خدور العواتق\nوإغمادك الأسياف في كل هامة … وركزك أطراف القنا في الحمالق\nولا ترتضي أن تدنس العرض ساعة … ومشيك في ثوب من الزين رائق\nفللعز ما أدنى لياني من القنا … وأكره رمحي في صدور الفيالق\nسقى الله نفسا ما أضر بقاؤها … بجسمي ، وأغراها بما كان عارقي\nتكلفني سيرا إلى غير غاية … مضرا بأبناء الجديل ولاحق\nوليل كعين الظبى إلا نجومه … \nجريا على الظلماء حتى كأنني … أراها بألحاظ الرزايا الطوارق\nوركب أناخوا ساعة ، فتناهبوا … ثرى البيد في أعضادهم والمرافق\nوساروا بأيدي العيس عجلى كأنها … خراطم أقلام جرت في المهارق\nوما أنا ممن يضجر السير قلبه … وتذكره الأمواه حر الودائق\nولكن شريك الوحش في كل مهمة … وردف الليالي في الربى والأبارق\nرعى الله من فارقت من غير رغبة … على الوجد مني والسقام المطابق\nيباعد عني من غرامي لأجله … ويقرب من قلبي له غير وامق\nإذا شئت أن لا تهجر الهم فاغترب … وإن شئت أن يأتي الحمام ففارق\nفكل غريب يألف الهم قلبه … ولا سيما قلب الغريب المفارق\nفكيف بطرف لحظه لحظ مدنف … سقيم وجسم قلبه قلب عاشق\nإذا كنت ممن يجحد الشوق في النوى … فكم فاض دمعي من حنين الأيانق\nوكم أنا وقاف على كل منزل … وكم أنا مرتاح إلى كل بارق\nأحن إلى من لا يحن صبابة … وما واجد قلبا مشوق وشائق\nوعندي من الأحباب كل عظيمة … تزهد في قرب الضجيع المعانق\nتعطلت الأحشاء من كل أنة … فلا القرب يضنيني ولا البعد شائقي\nوما في الغواني من سرور لناظر … ولا في الخزامى من نسيم لناشق\nرمى الله بي من هذه الأرض غيرها … وقطع من هذا الأنام علائقي\nفكم فيهم من واعد غير منجز … وكم فيهم من قائل غير صادق\nيظنون أن المجد فيمن له الغنى … وأن جميع العلم فضل التشادق\nوفاء كأنبوب اليراع لصاحب … وغدر كأطراف الرماح الزوالق\nولولا ابن موسى لم يكن في زماننا … معاذ لجان أو محل لطارق\nولا دبرت سمر القنا كف فارس … ولا مد في رزق المنى باع رازق\nتغمدنا من كل أرض بنفحة … وأمطرنا من كل جو بوادق\nإذا هم لم يبعد به زجر زاجر … وإن ثار لم يعطف به نعق ناعق\nوإن رام أملاك البلاد بفتكة … مشى الذل في تيجانها والمناطق\nله العز والمجد التليد وراثة … وأخذا عن البيض الظبى والسوابق\nوما زال يلقى كل غبراء فخمة … تغالى بأطراف القنا والعقائق\nوما برحت في عصر سيوفه … مواضع تيجان الرجال البطارق\nيجردها مثل الأقاحي على الطلى … ويغمدها محمرة كالشقائق\nتبلغه أقصى الأماني رماحه … وآراؤه ، والرأي أمضى مرافق\nوخيل كأطراف العوالي جريئة … على الطعن مسقاة دماء الموارق\nإذا عن طرد أو طراد تبادرت … طراد الأعادي قبل طرد الوسائق\nتدير عيونا بدد الروع لحظها … وغطى مآقيها غبار السمالق\nنواصب آذان إلى كل نبأة … طوامح ألحاظ إلى كل مارق\nذواكر للنجوى بيوم طعانه … ينسي رؤوس الخيل جذب العلائق\nتروع جنان الليث إن لم تذمه … وتطعن في الأقران إن لم تعانق\nهنيئا لك العيد المضاعف سعده … كما ضاعف الوسمي نبت الحدائق\nوكم مثل هذا العيد قضيت فرضه … بمكة في ظل البنود الخوافق\nوقدت إليه العيس عجلى مروعة … تناهز في أنماطها والنمارق\nمدفعة تحت السياط كأنها … إذا جنت الظلماء ، أيدي النقانق\nويعنتها الحادون أو توسع الخطا … إلى قرب دار الموقف المتضائق\nوأي مقام للورى تحت ظله … مهيب يطاطي من عيون الحدائق\nوأكثر ما تلقى به العين أو ترى … إفاضة مخلوق إلى قرب خالق\nثمانين أعطيت المنى في مرورها … ولم ترم عن مسراك فيها بعائق\nوأكبر ظني أن أرى منك عارضا … يؤممها في مثل تلك البوارق\nأبا أحمد هذا طلابي ، وهذه … مناي التي أمتك دون الخلائق\nوإني لأرجو منك ما لا أذيعه … مخافة واش أو عدو مماذق\nولا بد من يوم حميد ، كأنه … من النقع في أثناء برد شبارق\nعظيم دوي الصوت في سمع سامع … بعيد سماع الصوت من نطق ناطق\nأعد عناي فيه روحا وراحة … وكم سعة للمرء غب المضائق\nوهذا مقالي فيك غيث ، وربما … رميت العدا من وقعه بالصواعق\nإذا أنت يوما سمتنيه ، فإنما … تكلفني قطع الذرى والشواهق\nوحسبك منه ما رضيت استماعه … وأكثر ما في الناس لغو المناطق"},{"id":"diwan-radi:388","bookId":"diwan-radi","type":"poem","seq":388,"chapter":"البحر: طويل","title":"ألا يا لقومي للخطوب الطوارق","page":"","text":"ألا يا لقومي للخطوب الطوارق … وللعظم يرمى كل يوم بعارق\nوللدهر يعري جانبي من أقاربي … ويقطع ما بيني وبين الأصادق\nويوري بقلبي نار وجد شواظها … تريني الليالي ضوءه في مفارقي\nوللنائبات استهدفتني نصالها … على شرف يرميننا بالفلائق\nوللنفس قد طارت شعاعا من الجوى … لفقد الصفايا وانقطاع العلائق\nلها كل يوم موقف مع مودع … وملتفت في عقب ماض مفارق\nنجوم من الإخوان يرمي بها الردى … مقاربها فوت العيون الروامق\nكأني ، إذا تبعت آثار غارب … بعيني ، لم أنظر إلى ضوء شارق\nولا دار إلا سوف يجلى قطينها … على نعق غربان الخطوب النواعق\nويخرج منها بالكرائم حادث … ويدخلها صرف الردى بالبوائق\nكأنا قذى يرمي به السيل كلما … تطاوح ما بين الربى والأبارق\nأعض بناني إصبعا ثم إصبعا … على ثامر من فرع مجد ووارق\nوعقد من الأخدان أوهى نظامه … كرور الرزايا واعتقاب الطوارق\nأرد الشجا قبل الزفير تجلدا … وأغلب دمعي قبل بل الحمالق\nكأني بعد الذاهبين رذية … تزجى وراء الماضيات السوابق\nولا ريب أني مبرك في مناخهم … وأني بالماضين أول لاحق\nفأين الملوك الأقدمون تساندوا … إلى جذم أحساب كرام المعارق\nبهاليل مناعون للضيم أحسنوا … بلائهم عند النصول الذوالق\nعواصب بالتيجان فوق جماجم … وضاء المجالي واضحات المفارق\nإذا رثموا المسك العرانين خلتهم … أسود الشرى سافت دما بالمناشق\nفحول أطلن الهدر والخطر بالقنا … ضوارب للأذقان ميل الشقائق\nهم انتعلوا العلياء قيل نعالهم … وداسوا طلى الأعداء قبل النمارق\nترى كل حر الملطمين كأنه … عتيق المهارى من جياد عتائق\nإذا قام ساوى الرمح حتى يمسه … بغارب ممطوط النجاد وعاتق\nوراء الدجى يعشو إلى ضوء وجهه … كأن على عرنينه ضوء بارق\nوأين الملاجي العاصمات من الردى … إذا طرقت إحدى الليالي بطارق\nمصاعب لم تعط الرؤوس لقائد … ولا استوسقت قبل المنايا لسائق\nفشن عليه الأزلم العود غارة … بلا قرع أرماح ولا نقع مازق\nوشل بها شل الطرائد بالقنا … وكعكعها من جلة ودرادق\nلتبكي أبا الفتح العيون بدمعها … وألسننا من بعدها بالمناطق\nإذا هب من تلك الغليل بدامع … تسرع من هذا الغرام بناطق\nشقيقي إذا التاث الشقيق وأعرضت … خلائق قومي جانبا عن خلائقي\nكأن جناني يوم وافي نعيه … فري أديم بين أيدي الخوالق\nفمن لأوابي القول يبلو عراكها … ويحذفها حذف النبال الموارق\nإذا صاح في أعقابها أطردت له … ثواني بالأعناق طرد الوسايق\nوسومها ملس المتون كأنها … نزائع من آل الوجيه ولاحق\nتغلغل في أعقابهن وسومه … بأبقى بقاء من وسوم الأيانق\nففي الناس منها ذائق غير آكل … وقد كان منها آكلا غير ذائق\nومن للمعاني في الأكمة ألقيت … إلى باقر غيب المعاني وفاتق\nيطوح في أثنائها بضميره … مرير القوى ولاج تلك المضايق\nتسنم أعلا طودها غير عاثر … وجاوز أقصى دحضها غير زالق\nطوى منه بطن الأرض ما تستعيده … على الدهر منشورا بطون المهارق\nمضى طيب الأردان يأرج ذكره … أريج الصبا تندى لعرنين ناشق\nكان جميع الناس أثنوا عشية … على بعض أمطار الربيع المغادق\nأمدوه من طيب لغير كرامة … وضموه في ثوب جديد البنائق\nوما احتاج بردا غير برد عفافه … ولا عرف طيب غير تلك الخلائق\nمرافق شعب كالهشائهم وسدوا … بمنقطع البيداء غير المرافق\nقد اعتنقوا الأجداث لا من صبابة … ويا رب زهد في الضجيع المعانق\nوما الميت إن واراه ستر من الثرى … بأقرب مما دون رمل الشقائق\nوفارقني عن خلة غير طرقة … تضمنها صدر امرىء غير ماذق\nتروق ماء الود بيني وبينه … وطاح القذى عن سلسل الطعم رائق\nسقاك وهل يسقيك إلا تعلة … لغير الردى قطر الغمام الدوافق\nمن المزن حمحام ، إذا التج لجة … أضاءت تواليه زناد البوارق\nسلافة غيث شلشلتها همية … نتيجة أنواء السحاب الرقارق\nومستنبت روضا عليك منورا … على صابح من ماء مزن وغابق\nوما فرحي إن جاورتك حديقه … وقبرك مملوء بغر الحدائق\nسخا لك من ريح الزفير بحاصب … مقيم ومن ماء الشؤون بوادق\nفما العهد مني إن لهوت بثابت … ولا الود مني إن سلوت بصادق"},{"id":"diwan-radi:389","bookId":"diwan-radi","type":"poem","seq":389,"chapter":"البحر: سريع","title":"تعيف الطير ، فأنبأنه","page":"","text":"تعيف الطير ، فأنبأنه … أن ابن ليلى علقته علوق\nوإن سجلا من دم آمن … أفرغه الطعن بوادي العقيق\nيا ناعي الفارس قد أصبحت … ضباع ذي العرعر منه نغوق\nتعلم من تنعى إلى قومه … طار ذراعاك بعضب ذلوق\nبعدا لأرماح تميم لقد … هددن عادي بناء عتيق\nقرعن في أصل كريم الثرى … وجلن في فرع عزيز العروق\nحدوا له من حيث لا يتقي … عيرا من الطعن ملاء الوسوق\nكان ذا المطلع أمسى الردى … رصيده وأزور عنه الفريق\nقالت لها النفس على عارها … ما لك لا تنقض هذا الطريق\nما كان بالراجع عن نهجه … لو وقف السيف له في المضيق\nلا يدع الذابل من طعمه … على صبوح بدم ، أو غبوق\nكان أعلاه لسان فما … يغبه الدهر بلال بريق\nكم بات رباء لسيارة … طارقة غير أوان الطروق\nفي قنة عيطاء ممطولة … كأنها قلة رأس حليق\nيزايل الليل على رحله … ويؤثر القوم بطعم الخفوق\nويغتدي بعد عراك السرى … يعارض الركب بوجه طليق\nأوفى ، كما جلى على رهوة … أزرق وإلى نظرات بنيق\nيسل عينيه على مرية … عن زجل الطير قبيل الشروق\nيعترق اللحم على بارق … وينتقي العظم برمل الشقيق\nأو حية الرعن ذوى رأسه … مشترق الشمس بطود زليق\nيعقد أولاه بأخراته … لفاف بنت الرقم الخنفقيق\nكعمة الألوث مالت به … بين الندامى نزوات الرحيق\nجامع لين وصيال معا … أطراق ذي حلم وصول الحنيق\nيدير في فيه ذليق الشبا … مثل لماظ الرجل المستذيق\nتخال ما تطرح أشداقه … ما لطخ المحض بقعب الغبوق\nمستجمع فرق عن وثبة … نشطك حبل العربي الربيق\nنعم كعام الثغر يشجو به … فم المنايا ونصاح الفتوق\nتضمه في الروع من درعه … أم لها منه أذى أو عقوق\nزال وأبقى ، عند أعقابه … خديم مال عرفته الحقوق\nمضى ووصاهم بأن يقبلوا … دعوى العدا فيهم وحكم الصديق\nكان هوى للنفس ، لو أنني … في حلق القد وأنت الطليق\nما كنت بالهائب طرق الردى … ما سلم العضب ، وأنت الرفيق\nما أنا باللاقي بذات النقا … خيل وغى مشعلة بالعنيق\nماطلها الماء ، فلما سلت … عن الروى ماطلها بالعليق\nولابن ليلى عارضا رمحه … يحدو بخفان جمالا ونوق\nيأبى إذا الضيم غدا مضغة … سلسالة سائغة في الحلوق\nيروح من يرجو له غرة … قد خضخض السجل بجال عميق\nيحدث النفس بما فاته … تطاول الغمر لمجنى السحوق\nاستبدل الحي بعقبانه … أغربة بعدك حمق النغيق\nخاطرت الشول بأذنابها … لما انطوى قرقار ذاك الفنيق\nقد نطق الصامت من بعده … واصرد النابل بعد المروق\nمخيلة لا مطر خلفها … تلمع منها شولان البروق\nما الحي بالضاحك عن مثله … ولا وجوه الحي مذ غاب روق\nولا أغب الأرض تمسي بها … ظل صفيق ونسيم رقيق\nلا أغفلت قبرك حنانة … خرقاء بالقطر صناع البروق\nما أبدع المقدار فيما جنى … لكنه حمل غير المطيق"},{"id":"diwan-radi:390","bookId":"diwan-radi","type":"poem","seq":390,"chapter":"البحر: طويل","title":"الوي حيازيمي عليك تحرقا","page":"","text":"الوي حيازيمي عليك تحرقا … وأشكو قصور الدمع فيك وما رقا\nفيا شمل لبي لا تزال مبددا … ويا جفن عيني لا تزال مؤرقا\nفقد كنت أستسقي الدموع لمثلها … وما جم دمع العين إلا ليهرقا\nأعاينت هذا الدهر إن سر مرة … أساء ، وإن صفى لنا الود رنقا\nكأني أنادي منه صماء صلدة … وصل فلاة لا يلين على الرقا\nإذا غفل الحادون ثار مساورا … وإن روجع النجوى أرم وأطرقا\nطلوع الثنايا ينفذ الليل لحظه … إذا ما رنا ، جواب أرض ، وحملقا\nله المنظر العاري وكل هنيئة … تغاور بالأنقاء بردا مشرقا\nكان زماما ضاع من أرحبية … تلوى بأقواز النقا ، وتعلقا\nتلمظ شيئا كالجباب ، وغامرت … به وثبة أمضى من الليث مصدقا\nرشاء الردى لو عض بالطود هاضه … ولو شم ما لاقى على الأرض أحرقا\nدويهية يحمي الطريق مجره … إذا نفخ الركبان نام وأرقا\nوما العيش إلا غمة وارتياحة … ومفترق بعد الدنو وملتقى\nهو الدهر يبلي جدة بعد جدة … فيا لابسا أبلى طويلا وأخلقا\nفكم من علي فيك حلق وانهوى … وكم من غني نال منك وأملقا\nومن قبل ما أردى جذاما وحميرا … وأطرق زور الموت عوجا وعملقا\nوأبقى على دار السمؤل بركه … وقاد إلى ورد المنون محرقا\nففارق هذا الأبلق الفرد بغتة … وودع ذا بعد النعيم الخورنقا\nفما البأس والإقدام نجى عتيبة … ولا الجود والإعطاء أبقى المحلقا\nأراه سنانا للقريب مسددا … وسهما إلى النأي البعيد مفوقا\nإذا ما عدا لم تبصر البيض قطعا … ولا الزغف مناعا ولا الجرد سبقا\nولا في مهاوي الأرض إن رمت مهبطا … ولا في مراقي الجو إن رمت مرتقى\nولا الحوت إن شق البحار بفائت … ولا الطيران مد الجناح وحلقا\nوللعمر نهج إن تسنمه الفتى … إلى الغاية القصوى أزل وأزلقا\nألا قاتل الله الذي جاء غازيا … فقارعنا عن مخة الساق وانتقى\nوكم من عليل قد شرقت بيومه … جوى ، بعد ما قالوا أبل وأفرقا\nوآخر طلقت السرور لفقده … وقد راح للدنيا النشوز مطلقا\nبنفسي من أفقدت دارا أنيقة … من العيش واستودعت بيداء سملقا\nوأبدلته من ظل فينان ناضر … ظلال صفيح كالغمام مطبقا\nوخففت عن أيدي الأقارب ثقله … وحملته ثقل الجنادل والنقا\nجلست عليه طامعا ثم جاءني … من اليأس أمر أن أخب وأعنقا\nوما من هوان خطأ الترب فوقه … وخطى له بيتا من الأمر ضيقا\nوقد كان فوق الأرض يسحق نأيه … فصار وراء الأرض أنأى وأسحقا\nخليلي زما لي من العيس جسرة … مضبرة الأضلاع أدماء سهوقا\nتمر كما مرت أوائل بارق … يشق الدجى والعارض المتألقا\nكأن يد القسطار بين فروجها … يقلب في الكف اللجين المطرقا\nوحطا لجامي في قذال طمرة … كأن بها من ميعة الشد أولقا\nتعير الفتى ظهرا قصيرا ، كأنه … قرا النقنق الطاوي وعنقا عشنقا\nلعلي أفوت الموت إن جد جده … وأعظم ظني أن ينال ويلحقا\nوهل يأمن الإنسان من فجآته … وإن حث بالبيداء خيلا وأينقا\nلقد سل هذا الرزء من عيني الكرى … وغصص بالماء الزلال وأشرقا\nومما يعزى المرء ما شاء أنه … يرى نفسه في الميتين معرقا\nولو غير هذا الموت نالك ظفره … وولاك غربا للمنايا مذلقا\nلكان وراء الثار منا . . . . . … عصائب تختار المنون على البقا\nإذا ضربوا ردوا الحديد مثلما … وإن طعنوا ردوا الوشيج مدققا\nبكل قصير يفلق الهام أبيض … وكل طويل يهتك السرد أورقا\nإذا اهتز من خلف السنان حسبته … بأعلى النجاد الأرقم المتشدقا\nولكنه القرن الذي لا نرده … وهل لامرىء رد إذا الليث حققا\nيقود الفتى ما زم بالضيم أنفه … وقد قاد أبطالا وقد جر فيلقا\nمشقق أعراف الخطابة صامت … ولاقي صدور الخيل يوم الوغى لقا\nولم تغن عنه الخط قوم درؤها … ولا البيض أجرى القين فيهن رونقا\nسقاه ، وإن لم ترو للقلب غلة … وما كان ظني أن أقول له سقا\nولا زالت الأنواء تحبوه مرعدا … من المزن ملآن الحيازيم مبرقا\nإذا قيل ولى عاد يحدو عشاره … وإن قيل أرقا دمعة القطر أغدقا\nوأعلم أن لا ينفع الغيث هالكا … ولا يشعر المندوب بالهام إن زقا\nولو كان بالسقيا يعود أنا له … كما لو سقي عاري القضيب لأورقا\nولكن أداري خاطرا متلهفا … وقلبا بما خلف التراب معلقا"},{"id":"diwan-radi:391","bookId":"diwan-radi","type":"poem","seq":391,"chapter":"البحر: بسيط تام","title":"لا يبعد الله فتيانا رزئتهم","page":"","text":"لا يبعد الله فتيانا رزئتهم … رزء الغصون ، وفيها الماء والورق\nإن يرحلوا اليوم عن داري فإنهم … جيران قلبي أقاموا بعد ما انطلقوا\nبانوا فكل نعيم بعدهم كمد … باق وكل مساغ بعدهم شرق\nأراك تجزع للقوم الذين مضوا … فهل آمنت على القوم الذين بقوا\nلا يلبث المرء يبلى شرخ جدته … من الزمان جديد ما له خلق\nهدى الغرام دموعي في مسالكه … عليهم ، وأضلت صبري الطرق\nوكيف ينعم بالتغميض بعدهم … عين أعان عليها الدمع والأرق\nإني لأعجب بعد اليوم من كبد … تدمى لهم كيف تندي وهي تحترق"},{"id":"diwan-radi:392","bookId":"diwan-radi","type":"poem","seq":392,"chapter":"البحر: كامل تام","title":"لولا يذم الركب عندك موقفي","page":"","text":"لولا يذم الركب عندك موقفي … حييت قبرك ، يا أبا إسحق\nكيف اشتياقك مذ نأيت إلى أخ … قلق الضمير إليك بالأشواق\nهل تذكر الزمن الأنيق وعيشنا … يحلو على متأمل ومذاق\nلا بد للقرباء أن يتزايلوا … يوما ، بعذر قلى وعذر فراق\nأمضي وتعطفني إليك نوازع … بتنفس كتنفس العشاق\nوأذود عن عيني الدموع ولو خلت … لجرت عليك بوابل غيداق\nولو أن في طرفي قذاة من ثرى … وأراك ما قذيتها من ماقي\nإن تمض فالمجد المرجب خالد … أو تفن فالكلم العظام بواقي\nمشحوذة تدمى بغير مضارب … كالسيف أطلق في طلى الأعناق\nيقبلن كالجيش المغير يؤمه … كمش الإزار مقلص عن ساق\nقرطات أذان الملوك خليقة … بمواضع التيجان والأطواق\nعقدوا بها المجد الشرود وأثلوا … درجا إلى شرف العلى ومراقي\nأوترتها أيام باعك صلب … وكددتها بالنزع والإغراق\nحتى إذا مرحت قواك شددتها … باسم على عقب الليالي باقي\nكنجائب قعدت بها أرماقها … محسورة ، فمشين بالأعراق"},{"id":"diwan-radi:393","bookId":"diwan-radi","type":"poem","seq":393,"chapter":"البحر: طويل","title":"أمن ذكر دار بالمصلى إلى منى","page":"","text":"أمن ذكر دار بالمصلى إلى منى … تعاد كما عيد السليم المؤرق\nحنينا إليها والتواء من الجوى … كأنك في الحي الولود المطرق\nأألله ، إني إن مررت بأرضها … فؤادي مأسور ودمعي مطلق\nأكر إليها الطرف ثم أرده … بإنسان عين في صرى الدمع يغرق\nهواي يمان كيف لا كيف نلتقي … وركبي منقاد القرينة معرق\nفواها من الربع الذي غير البلى … وآها على القوم الذين تفرقوا\nأصون تراب الأرض كانوا حلولها … وأحذر من مري عليها وأشفق\nولم يبق عندي للهوى غير أنني … إذا الركب مروا بي على الدار أشهق"},{"id":"diwan-radi:394","bookId":"diwan-radi","type":"poem","seq":394,"chapter":"البحر: رجز تام","title":"يا حسن الخلق قبيح الأخلاق !","page":"","text":"يا حسن الخلق قبيح الأخلاق ! … إني على ذاك إليك مشتاق\nرب مصاف علق بمذاق … إن مودات القلوب أرزاق\nيا هل لدائي من هواك أفراق … هيهات ما أعضل داء العشاق"},{"id":"diwan-radi:395","bookId":"diwan-radi","type":"poem","seq":395,"chapter":"قصائد","title":"يا ليلة كرم الزمان بها لو أن الليل باق","page":"","text":"يا ليلة كرم الزمان بها لو أن الليل باق … لو أن الليل باق\nكان اتفاق بيننا … جار على غير اتفاق\nواستروح المهجور من … زفرات هم واشتياق"},{"id":"diwan-radi:396","bookId":"diwan-radi","type":"poem","seq":396,"chapter":"البحر: كامل تام","title":"ولقد أقول لصاحب نبهته","page":"","text":"ولقد أقول لصاحب نبهته … فوق الرحالة والمطي رواقي\nأو ما شممت بذي الأبارق نفحة … خلصت إلى كبد الفتى المشتاق\nفجنى نسيم الشيح من نجد له … حرق الحشى وتحلب الآماق\nآها على نفحات نجد ! إنها … رسل الهوى وأدلة الأشواق\nأسقيت بالكأس التي سقيتها … أم هل خطتك إلي كف الساقي\nفأوى وقال : أرى بقلبك لسعة … للحب ليس لدائها من راق\nفصف الغرام لمفرق من دائه … إني لأقدم منك في العشاق\nأبثثته كمدي وطول تجلدي … وأليم ما بي من نوى وفراق\nأشكو إليه بياض سود مفارقي … ويظل يعجب من سواد الباقي"},{"id":"diwan-radi:397","bookId":"diwan-radi","type":"poem","seq":397,"chapter":"البحر: خفيف تام","title":"أيها الرائح المغذ تحمل","page":"","text":"أيها الرائح المغذ تحمل … حاجة للمعذب المشتاق\nأقرعني السلام أهل المصلى … وبلاغ السلام بعد التلاقي\nوإذا ما مررت بالخيف فاشهد … أن قلبي إليه بالأشواق\nوإذا ما سئلت عني فقل نضو هوى ما أظنه اليوم باق … وهوى ما أظنه اليوم باق\nضاع قلبي فانشده لي بين جمع … ومنى عند بعض تلك الحداق"},{"id":"diwan-radi:398","bookId":"diwan-radi","type":"poem","seq":398,"chapter":"البحر: طويل","title":"كفى حزنا إني صديق وصادق","page":"","text":"كفى حزنا إني صديق وصادق … وما لي من بين الأنام صديق\nفكيف أريغ الأبعدين لخلة … وهذا قريب غادر ، وشقيق"},{"id":"diwan-radi:399","bookId":"diwan-radi","type":"poem","seq":399,"chapter":"البحر: طويل","title":"إذا قلت أن القرب يشفي من الجوى","page":"","text":"إذا قلت أن القرب يشفي من الجوى … أبي القلب أن يزداد إلا تشوقا\nوإن أنا أضمرت السلو تراجعت … من الشوق أخلاق يزلن التخلقا\nوكم لي من ليل يجدد لي الهوى … إذا أشأم البرق اليماني وأعرقا\nأصانع لحظي أن يطول ذبابه … إليك ، وأنهى الدمع أن يترقرقا\nمخافة واش يثلم الحب قوله … وهيهات طال الحب منا وأورقا\nغدونا على الأعداء نحمي مودة … ونمنع عن أطرافها أن تمزقا\nفما أنت إلا السهم صافح ثغره … وما أنا إلا العضب صادم مفرقا\nإذا كنت لي خلا فحسبي من الورى … بقاؤك ، لولا أنت ما طال لي بقا\nجمعنا فلا نحفل بما صنع الهوى … وخفنا على الأيام أن نتفرقا"},{"id":"diwan-radi:400","bookId":"diwan-radi","type":"poem","seq":400,"chapter":"البحر: سريع","title":"لو كان ما تطلبه غاية","page":"","text":"لو كان ما تطلبه غاية … كنت المصلي وأنا السابق\nتظنني أرغب عن موقف … يحضر فيه الشوق والشائق\nفكرت حتى لم أجد فكرة … تقدح إلا ولها عائق\nلو كنت في أثناء سري إذا … علمت أني قائل صادق\nقلبي جنيب لك لا يرعوى … وودك القائد والسائق\nولحظ عينيك رمى مقلتي … كان نومي تحتها عاشق\nفاصبر ، فإن الصبر أحرى إذا … ضاق عليك المسلك الضايق\nفالنطق الطاهر ما بيننا … مترجم والنظر الفاسق"},{"id":"diwan-radi:401","bookId":"diwan-radi","type":"poem","seq":401,"chapter":"البحر: متقارب تام","title":"وليل تمزق عنه النسي","page":"","text":"وليل تمزق عنه النسي … م واستلب الجو غربا وشرقا\nونيلوفر فتحته الرياح … وعانقه الماء صفوا ورنقا"},{"id":"diwan-radi:402","bookId":"diwan-radi","type":"poem","seq":402,"chapter":"البحر: كامل تام","title":"ما وقع الواشوان في ولفقوا","page":"","text":"ما وقع الواشوان في ولفقوا … قل لي ، فإما حاسد أو مشفق\nفي كل يوم ظهر داري مغرب … لكلامهم وجبين دارك مشرق\nوإلى متى عودي على أيديهم … ملقى ينيب دائبا ويحرق\nكم يسبك الذهب المصفى مرة … قد لاح جوهره وبان الرونق\nيحلو لهم عرضي فيستطرونه … ويصل عرضهم الذليل فيبصق\nنفضوا عيوبهم علي ، وإنما … وجدوا مصحا في الأديم فمزقوا\nمن لي بمن أن بان عيب خليله … غطاه عن شانيه ، أو من يصدق\nوإذا الحليم رمى بسر صديقه … عمدا ، فأولى بالوداد الأحمق\nمن كان يغتاب الرجال وهم أن … يبلو الأصادق فالصديق المطرق\nوإذا تألقت الثغور لسبة … لم يدر ثغرا أو سنا يتألق\nلا تملك الفحشاء جانب سمعه … ويزل قول الهجر عنه ويزلق\nجار الزمان فلا جواد يرتجى … للنائبات ولا صديق يشفق\nوطغى علي فكل رحب ضيق … إن قلت فيه ، وكل حبل يخنق\nأمر شحي للعزم غير مرشح … واليوم من ليل العجاجة أبلق\nدعني فإن الدهر يقصف همتي … ويجد من أملي الذي أتعلق\nالموت يركض في نواحي دهرنا … وكأن صرف النائبات مطرق"},{"id":"diwan-radi:403","bookId":"diwan-radi","type":"poem","seq":403,"chapter":"البحر: منسرح","title":"برقت بالوعد في دجى أملي","page":"","text":"برقت بالوعد في دجى أملي … والغيث لا يقتضى إذا برقا\nحاشاك أن أقتضيك منقبة … تسلك منها إلى العلى طرقا\nفانهض لها أنها الغلام تجد … حبلا ضنينا بكف من علقا\nوكم صريخ نهضت تنصره … والطعن يسترعف القنا علقا\nدع العدا عن جوانبي بيد … يروع فيها النضار والورقا"},{"id":"diwan-radi:404","bookId":"diwan-radi","type":"poem","seq":404,"chapter":"البحر: بسيط تام","title":"أهز عاسية العيدان آبية","page":"","text":"أهز عاسية العيدان آبية … على الخوابط لا لينا ولا ورقا\nوما مدحتهم أني رجوتهم … لكنه عوذ من شرهم ورقا\nقالوا : نعدك للجلى ، فقلت لهم : … حسبي من الري ما لا يبلغ الشرقا\nناموا خليين عما بي ، فلم تركوا … وهنا علي مطال الهم والأرقا\nكفى بقوم هجاء أن مادحهم … يهدي الثناء إلى أعراضهم فرقا\nمن لم يبال بأعقاب الحديث غدا … فما يبالي أمان القول أم صدقا"},{"id":"diwan-radi:405","bookId":"diwan-radi","type":"poem","seq":405,"chapter":"البحر: خفيف تام","title":"قمر غاض ضوءه في المحاق","page":"","text":"قمر غاض ضوءه في المحاق … يوم جد انطلاقه وانطلاقي\nجامد اللحظ حيرة البين إلا … أن منه ذوب المهراق\nصار در الدموع يخلف ثغري … في حواشي تلك الخدود الرقاق\nعز صبري يوم اللقاء ، ولكن … فضحته الأشجان يوم الفراق\nيا عريق الهوى ستقضي إذا ما … طلع البين من ثنايا العراق\nيوم لا غير زفرة من فؤاد … ذي قروح ورشة من مآق\nنسرق الدمع في الجيوب حياء … وبنا ما بنا من الإشفاق\nكاد طل الدموع يلتذ لولا … هز سير الرسيم والإعناق\nبيننا ، يا بني المغيرة ، يوم … لو رآنا العدو أضمرنا ما\nشهقة الضرب في الطلى والهوادي … رنة الطعن في الكلى والصفاق\nحمرت نجدة وليس بذمر … وجميعا والليل ملقي الرواق\nونجوم تنوب عنها العوالي … من سماء العجاج في الآفاق\nحرم حشوه القنا وفناء … ذو طراز من الجياد العتاق\nأمعيني على بلوغ الأماني … وشفائي من علتي واشتياقي\nوخليلي لما جفاني خليل … صدحتي غصصته بفراق\nحين وافقت نيتي في التصافي … ذقت مني الوفاء عذب المذاق\nأينعت بيننا المودة حتى … جللتنا والدهر بالأوراق\nوسوامي اللحاظ في الروع تلقا … خارجا من ثيابه الأخلاق\nقم نبادر مرمى الزمان ببين … فسهام الخطوب في الأفواق\nكلما كرت الليالي علينا … شق فيها الوفاء جيب الشقاق\nفي جبين الزمان منك ومني … غرة كوكبية الائتلاق\nلا تزال الأيام تضدر منا … عن إخاء لم نقذه بفراق"},{"id":"diwan-radi:406","bookId":"diwan-radi","type":"poem","seq":406,"chapter":"البحر: متقارب تام","title":"لقاؤك جر علي الفراقا","page":"","text":"لقاؤك جر علي الفراقا … وما زادني القرب إلا اشتياقا\nجلوت علي هدي الوداد … فأسلفتها بالقبول الصداقا\nوأسرفت بالبشر حتى ظننت أنك أصجعت فيه النفاقا … ت أنك أضجعت فيه النفاقا\nوحاشاك من تهمة في المغيب … فكيف حضور يضم الرفاقا\nوكان الزعيم بهذا الإخا … ء يوما حسوناه كأسا دهاقا\nنحرنا الدنان على صدره … فلله أي دماء أراقا\nشرقنا بلذاته والسرور … يلوي إزارا ويرخي نطاقا\nيشقق والليل رطب الذيو … غلائل تندى نسيما رقاقا\nسقى الله دهرا حبانا الوداد مبتدها فشكرنا العراقا … د مبتدها ، فشكرنا العراقا\nوما زلت أعجب من حفظه … لنا القرب حتى نسينا الفراقا\nاتقتص من جسدي بالبعاد … وما زود البلع منك العناقا"},{"id":"diwan-radi:407","bookId":"diwan-radi","type":"poem","seq":407,"chapter":"البحر: طويل","title":"أبا حسن لي في الرجال فراسة","page":"","text":"أبا حسن لي في الرجال فراسة … تعودت منها أن تقول فتصدقا\nوقد خبرتني عنك أنك ماجد … سترقى من العلياء أبعد مرتقى\nفوفيتك التعظيم قبل أوانه … وقلت أطال الله للسيد البقا\nوأضمرت منه لفظة لم أبح بها … إلى أن أرى اطلاقها لي مطلقا\nفإن عشت أو إن مت فاذكر بشارتي … وأوجب بها حقا عليك محققا\nوكن لي في الأولاد والأهل حافظا … إذا ما اطمأن الجنب في موضع البقا"},{"id":"diwan-radi:408","bookId":"diwan-radi","type":"poem","seq":408,"chapter":"البحر: طويل","title":"سننت لهذا الرمح غربا مذلقا","page":"","text":"سننت لهذا الرمح غربا مذلقا … وأجريت في ذا الهندواني رونقا\nوسومت ذا الطرف الجواد وإنما … شرعت له نهجا فخب وأعنقا\nلئن برقت مني مخايل عارض … لعينيك يقضي أن يجود ويغدقا\nفليس بساق قبل ربعك مربعا … وليس براق قبل جوك مرتقى\nوإن صدقت منه الليالي مخيلة … تكن بجديد الماء أول من سقى\nويغدو لمن يروي جنابك مرويا … زلالا وللأعداء دونك مصعقا\nوإن تر ليثا لائذا لفريسة … يراصد غرات المقادير مطرقا\nفما ذاك إلا أن يوفر طعمها … عليك ، إذا جلى إليها وحققا\nوإن يرق يوما في المعالي فإنه … سما ليوقى وطء رجلك مزلقا\nوإن يسع في الأمر العظيم فإنما … سعى لك في ذاك الطريق مطرقا\nوإن يصب السهم الذي راش نصله … فما كان إلا في هواك مفوقا\nوإن ينهض الغرس الذي هو غارس … يكن لك مجنى في الخطوب ومعلقا\nلتجنيه دون الناس ما كان مثمرا … وتلبس طلا منه ما كان مورقا\nفنم وادعا واستسقني فستنتضي … حساما إذا ما مر بالعظم طبقا\nوجر ذيول العز أنى أجره … لهاما إذا ما أظلم الليل أبرقا\nوجيشا جناحاه يزمان بالردى … خفوقان ما نالا من الأرض مخفقا\nبه كل طعان يلوث برأسه … عنيق المذاكي ما يثير من النقا\nلدن غدوة حتى ترى الشمس ورسة … كأن على الغيطان ثوبا مزبرقا\nوركب أغذوا بالركاب ، فنشفوا … ثمائلها بالجوب غربا ومشرقا\nوكل معراة الضلوع كأنما … أقاموا عليها جازرا متعرقا\nفإن راشني دهري أكن لك بازيا … يسرك محصورا ويرضيك مطلقا\nأشاطرك العز الذي أستفيده … بصفقة راض إن غنيت وأملقا\nفتذهب بالشطر الذي كله غنى … وأذهب بالشطر الذي كله شقا\nوتأخذ منه ما أنام وما حلا … وأخذ منه ما أمر وأرقا\nفغيري إما طار غادر صحبه … دوين المعالي واقعين وحلقا\nفإن تسلف التبجيل قبل أوانه … أعضك به وجها من الود مونقا\nوإن تعطني الإعظام قولا فإنني … سأعطيك فعلا منه أذكى وأعبقا\nلعل الليالي أن يبلغن منية … ويقرعن لي بابا من الحظ مغلقا\nنظار ولا تستبط عزمي فلن ترى … علوقا ، إذا ما لم تجد متعلقا\nوليس ينال الأمر إلا بحازم … من القوم أحمى ميسما ثم ألصقا\nفإن قعدت بي السن يوما فإنه … سينهض بي مجدي إليها محققا\nفوالله لا كذبت ظنك إنه … لعار إذا ما عاد ظنك مخفقا\nفإن الذي ظن الظنون صوادقا … نظير الذي قوى الظنون وحققا"},{"id":"diwan-radi:409","bookId":"diwan-radi","type":"poem","seq":409,"chapter":"البحر: رجز تام","title":"جاء بها قالصة عن ساق","page":"","text":"جاء بها قالصة عن ساق … روعاء من إرث أبي الغيداق\nتحن والحنة للمشتاق … ما أولع الحنين بالنياق\nتمشي على نعل دم مراق … ليست بذي هلب ولا طراق\nتذكري رمل النقا واشتياقي … وبرد ماء ألعس وساقي\nينزع من أثعوب جم باقي … حمضها في قلص عتاق\nمناشط العشب على الملاق … أشعث بادي جنجن التراقي\nكأنه في السمل الأخلاق … من تيهه ذو التاج والأطواق\nنحارة للإبل المناقي … فواقها أدنى من الفواق\nأسفع إلا موضع النطاق … ينزل حد الصارم الذلاق\nمنازل العقال والرباق … موطن المنزل للرفاق\nمرت على الأقوار والبراق … مر جرور لعارض الشهاق\nطائرة بالقرب الخفاق … منفلت الدلو من العراقي\nتحثو على نجد ثرى العراق … كأنها بعض الهباب الباقي\nوالليل أعمى شارق الرواق … نذير قوم جد في اللحاق\nينذر جيشا عجل الإرهاق … أقبل لا يحفل ما يلاقي"},{"id":"diwan-radi:410","bookId":"diwan-radi","type":"poem","seq":410,"chapter":"البحر: رجز تام","title":"نبهت مني ، يا أبا الغيداق","page":"","text":"نبهت مني ، يا أبا الغيداق … أصم لا يسمع صوت الراقي\nصل صفا ملعن البصاق … ريقته تهزأ بالدرياق\nكأنه أم من الاطراق … تلقى الرجال عنده الملاقي\nينظر من عين بلا حملاق … إن نام لا يكلؤها بماق\nآثاره في القور والبراق … تستوقف الركب عن الإعناق\nيشم منك موضع النطاق … بوخزة من ذرب حذاق\nيكتمه في هرت الأشداق … ليك من حديدة الحلاق\nترى على اللبات والتراقي … أهالة من سمه المراق\nمثل القذى لجلج في المآقي … ينحب بالماضي جنان الباقي\nرزقك أدته يد الخلاق … لكنه مر من الأرزاق\nقد حان ألا أن يقيه الواقي … من ابتغى جهلا بما يلاقي\nتجربة السيف على الأعناق … ألم يعقك اليوم عني عاق\nحتى لقيت أذني عناق … سوف أغني بك في الرفاق\nحدوا كحدو البدن بالقياقي … محملا غوارب النياق\nمن لاذعات الكلم البواقي … نهزا سيجليها إلى العراق\nإني ارتقيت بعد ضعف الساق … روابيا مزلقة المراقي\nأهدفت للإرعاد والإبراق … نصب مسيل العارض البعاق\nترقع عرضا منك ذا انخراق … كما رفدت النعل بالطراق\nحذار من مذروبة ذلاق … ترفع عنك جانب الرواق\nهواجما مقطوعة الرباق … حتى على الأذان والأحداق\nتنتزع الأصول بالأعراق … يلجا بها الحر إلى الإباق\nأعقدها مواضع الأطواق … لها على الأعناق وسم باق\nمثل وسوم الإبل المناق … نزيعة من جلب العراق\nتقنى لغير الشم والعناق … تميطها ، وهي إلى التصاق\nلا تقلع القوباء بالأرياق … عجت لأعراضكم الأخلاق\nأفلق في جماجم أفلاق … وأجهز اليوم على أرماق\nلا تأمن النار على الأحراق … هذا ونبلي لك في الإيفاق\nفكيف بعد النزع والأغراق … "},{"id":"diwan-radi:411","bookId":"diwan-radi","type":"poem","seq":411,"chapter":"قصائد","title":"ما لخيال الحبيب قد طرقا","page":"","text":"ما لخيال الحبيب قد طرقا … وما لهذا المحب قد قلقا\nسألت بإنسان عينه لجج … ولو لم يكن سابحا لقد غرقا"},{"id":"diwan-radi:412","bookId":"diwan-radi","type":"poem","seq":412,"chapter":"البحر: بسيط تام","title":"ضاعت ديونك عند الغيد أعناقا","page":"","text":"ضاعت ديونك عند الغيد أعناقا … وما قضينك لما جئت مشتاقا\nتحملوا ، وعيون الحي ناظرة … وعاق طرفك يوم الجزع ما عاقا"},{"id":"diwan-radi:413","bookId":"diwan-radi","type":"poem","seq":413,"chapter":"البحر: بسيط تام","title":"خلوا عليك مطال السفر وانطلقوا","page":"","text":"خلوا عليك مطال السفر وانطلقوا … وأسلفوك سلوا قبل أن عشقوا\nلو ينصفوني الهوى ما كان عندهم … برد القلوب وعندي الشوق والأرق"},{"id":"diwan-radi:414","bookId":"diwan-radi","type":"poem","seq":414,"chapter":"البحر: طويل","title":"وردنا بها بين العذيب وضارج","page":"","text":"وردنا بها بين العذيب وضارج … تريكة جون أسأرتها البوارق\nوقد ذعذع الليل النجوم لغورها … كبيض الأداخي بعثرته النقانق"},{"id":"diwan-radi:415","bookId":"diwan-radi","type":"poem","seq":415,"chapter":"البحر: مجزوء الخفيف","title":"دولة تطلب الفرا","page":"","text":"دولة تطلب الفرا … ر ، ومجد محلق\nهو يأس مكذب … ورجاء مصدق\nقد بنيتم فشيدوا … وغرستم ، فأورقوا"},{"id":"diwan-radi:416","bookId":"diwan-radi","type":"poem","seq":416,"chapter":"البحر: مجزوء الكامل","title":"أترى نراح من الفراق","page":"","text":"أترى نراح من الفراق … يوما ، ونأخذ في التلاقي\nفأغض من جزعي وامحو الدمع من بين المآقي … حو الدمع من بين المآقي\nوأروح في ظفر القوى … وقد انتصفت من الفراق"},{"id":"diwan-radi:417","bookId":"diwan-radi","type":"poem","seq":417,"chapter":"البحر: خفيف تام","title":"يا أراك الحمى تراني أراكا","page":"","text":"يا أراك الحمى تراني أراكا … أي قلب جنى عليه جناكا\nأعطش الله كل فرع بنعمان من الماطر الروى وسقاكا … الروى وسقاكا\nأي نور لناظري ، إذا ما … مر يوم ، وناظري لا يراكا\nلم تدع فيك نائبات الليالي … أثرا للهوى سوى مغناكا\nوأثاف كأنهن رذايا … وأسارى لا ينظرون فكاكا\nوشجيج طم الزمان نواصيه كما شعث الوليد السواكا … ه ، كما شعث الوليد السواكا\nالذميل الذميل يا ركب أني … لضمين أن لا يخيب سراكا\nجئيهم مخمس الركاب فنادوا … جنب الورد لا نقعت صداكا\nورأيت العدو حيث تراه … ورآك العدو حيث يراكا\nزدت سبقا على أبيك ، وكانت … غاية المجد لو لحقت أباكا\nمن إذا غالنا الضلال رأينا … هقواما لديننا أو مساكا\nمن طموح خطمته وجموح … بك أعضضته الشكيم فلاكا\nلم تزل تطعن المولين حتى … حسبت من قنا الظهور قناكا\nورجال تحككوا ، فأفاقوا … بجذيل قد عودوه الحكاكا\nضربوا في جوانب الطود فانظر … حمق العاجزين كيف أحاكا\nطاح في حد مخلبيك وخست … أكلة الذئب أن تقارب فاكا\nطلب الأمر فانثنى بغرور … كان فوتا ، فخاله إدراكا\nكيف تقذى عين ويألم طرف … نظر اليوم وجهك الضحاكا\nكل يوم فضل علي جديد … وعلاء أنا له من علاكا\nيا ديار الأحباب كيف تغير … كلما قيل قد بلغت مناكا\nوإذا ما طويت عنك التقاضي … عني الطول منك بي فاقتضاكا"},{"id":"diwan-radi:418","bookId":"diwan-radi","type":"poem","seq":418,"chapter":"البحر: طويل","title":"لقد جثمت تعبيسة في المضاحك","page":"","text":"لقد جثمت تعبيسة في المضاحك … تمد بأضباع الدموع السوافك\nفكفكف صدور السمهري بعزمة … على كل ملآن من الضغن فاتك\nإذا ما أضل النقع طرق سنانه … تسرع من حجب الكلى في مسالك\nوليل مريض النجم من صحة الدجى … خطته بنا أيدي الهجان الأوارك\nبركب فروا برد الظلام وقلصوا … حواشيه في أيدي القلاص الرواتك"},{"id":"diwan-radi:419","bookId":"diwan-radi","type":"poem","seq":419,"chapter":"البحر: طويل","title":"يصافحه نشر الخزامى ، كأنما","page":"","text":"يصافحه نشر الخزامى ، كأنما … يمسح أعطاف الرماح السواهك\nفجاءت باسد الحديد ترقرقت … عليها بماء الشمس غدر الترائك\nبدت تزلق الأبصار في لمعانها … على أنها في ثوب اقتم حالك\nتلف بأعراف الجياد رماحها … وتنشر من أطمار بيض بواتك\nوتنكح أوتار الحنايا نبالها … فتشرد عنها في نصال فوارك\nألف بلألاء السماح فروجها … تبيض أعجاس القسي العواتك\nبيوم طراد قنع الشمس نقعه … تردوا بموار الدماء الصوائك\nولا يألمون الطعن حتى كأنهم … أسروا ضلوعا من كعوب النيازك"},{"id":"diwan-radi:420","bookId":"diwan-radi","type":"poem","seq":420,"chapter":"البحر: طويل","title":"ولا يوم إلا أن ترامي رماحه","page":"","text":"ولا يوم إلا أن ترامي رماحه … قلوب تميم في صدور المهالك\nوقد شرت ذود العوالي أنامل … ولكنها بين الطلى في مبارك\nتطل دماء من نحور أعزة … كحقن أفاويق الضروع الحواشك\nالكني فتى فهر إلى البيض والقنا … فإني قذاة في عيون المآلك\nولي أمل من دون مبرك نضوه … يقلقل أثباج المطي البوارك\nسقى الله ظمأن المنى كل عارض … من الدم ملآن الملاطين حاشك\nيزمجر من وقع الصفيح على الطلى … ويرعد من وقع القنا بالحوارك\nبطعن إذا بادت عواليه قومت … من القوم منآد الضلوع الشوابك"},{"id":"diwan-radi:421","bookId":"diwan-radi","type":"poem","seq":421,"chapter":"البحر: بسيط تام","title":"دع الذميل إلى الغايات والرتكا","page":"","text":"دع الذميل إلى الغايات والرتكا … ماذا الطلاب أترجو بعدها دركا\nما لي أكلفها التهجير دائبة … على الوجى وقوام الدين قد هلكا\nحل الغروض فلا دار ملائمة … ولا مزور إذا لاقيته ضحكا\nأمسى يقوض عنا العز خلفه … وثور المجد عنا بعد ما بركا\nاليوم صرحت الجلى ، وقد تركت … بين الرجاء وبين اليأس معتركا\nتمثل الخطب مظنونا لتالفه … فسوف نلقاه موجودا ومدركا\nرزيئة لم تدع شمسا ولا قمرا … ولا غماما ولا نجما ولا فلكا\nلو كان يقبل من مفقودها عوض … لأنفق المجد فيها كلما ملكا\nقد أدهش الملك قبل اليوم من حذر … وإنما اليوم أذرى دمعه وبكى\nأمسى بها عاطلا من بعد حليته … وهادما من بناء المجد ما سمكا\nمن للجياد مراعيها شكائمها … يحملن شوك القنا اللذاع والشككا\nيطا بها تحت أطراف القنا زلقا … من الدماء ومن هام العدا نبكا\nمن للظبى يختلي زرع الرقاب بها … حكم القصاقص لا عقل لما سفكا\nمن للقنا جعلت أيدي فوارسه … من القلوب لها الأطواق والمسكا\nمن للأسود نهاها عن مطاعمها … فكم رددن فريسا بعد ما انتهكا\nمن للعزائم والآراء يطلعها … مطالع البيض يجلو ضؤها الحالكا\nمن للرقاق إذا أشفت على عطب … يغدو لها بلغا بالطول أو مسكا\nمن للخطوب ينجي من مخالبها … وينزع الظفر منها كلما سدكا\nومن معشر أخذوا الفضلى فما تركوا … منها لمن يطلب العلياء متركا\nقدوا من البيض خلقا والحيما خلقا … عيصا ألف بعيص المجد فاشتبكا\nلو أنهم طبعوا لم ترض أوجههم … دراري الليل لو كانت لها سلكا\nهم أبدعوا المجد لا إن كان أولهم … رأى من الجد فعلا قبله فحكى\nالراكبين ظهورا قلما ركبت … والمالكين عنانا قلما ملكا\nهيهات لا ألبس الأعداء بعدهم … يوم الجراء ، لجاما يقرع الحنكا\nولا أريحت على العلياء حافلة … لها سنام من الأجمام قد تمكا\nيا صفقة من بياع كلها غرر … من ضامن للعلى من بعدها الدركا\nخلالها كل ذئب مع أكيلته … من واقع طاروا من عاجز فتكا\nالموت أخبث من أن يرتضي أبدا … لا سوقة بدلا منه ولا ملكا\nكالعلق والعلق لو خيرت بينهما … لم ترض بالدون يوما أن يكون لكا\nراق تفرد بالإحسان يفرعها … وزايد النجم في العلياء واشتركا\nاللين يمطيك من أخلاقه ذللا … والضيم يخرج منه الآبي المعكا\nغمر العطية لا يبقي على نشب … وإن رأى قلبي الرأي محتنكا\nلا تتبعوا في المساعي غير أخمصه … فأخصر الطرق في العلياء ما سلكا\nما مثل قبرك يستسقى الغمام له … وكيف يسقي القطار النازل الفلكا\nلا يبعد الله أقواما رزئتهم … لو ثلموا من جنوب الطود لا أنهتكا\nفقدتهم مثل فقد العين ناظرها … يبكي عليها بها يا طول ذاك بكا\nإذا رجا القلب أن ينسيه غصته … ما يحدث الدهر أدمى قرحه ونكا\nإن يأخذ الموت منا من نضن به … فما نبالي بمن بقى ومن تركا\nإني أرى القلب ينزو لأدكارهم … نزو القطاطة مدوا فوقها الشركا\nلا تبصر الدهر بعد اليوم مبتسما … إن الليالي أنست بعده الضحكا"},{"id":"diwan-radi:422","bookId":"diwan-radi","type":"poem","seq":422,"chapter":"البحر: بسيط تام","title":"يا ظبية البان ترعى في خمائله","page":"","text":"يا ظبية البان ترعى في خمائله … ليهنك اليوم أن القلب مرعاك\nالماء عندك مبذول لشاربه … وليس يرويك الأمد معي الباكي\nهبت لنا من رياح الغور رائحة … بعد الرقاد عرفناها برياك\nانثنينا إذا ما هزنا طرب … على الرحال تعللنا بذكراك\nسهم أصاب وراميه بذي سلم … من بالعراق ، لقد أبعدت مرماك\nوعد لعينيك عندي ما وفيت به … يا قرب ما كذبت عيني عيناك\nحكت لحاظك ما في الريم من ملح … يوم اللقاء فكان الفضل للحاكي\nكأن طرفك يوم الجزع يخبرنا … بما طوى عنك من أسماء قتلاك\nأنت النعيم لقلبي والعذاب له … فما أمرك في قلبي وأحلاك\nعندي رسائل شوق لست أذكرها … لولا الرقيب لقد بلغتها فاك\nسقى منى وليالي الخيف ما شربت … من الغمام وحياها وحياك\nإذ يلتقي كل ذي دين وماطله … منا ويجتمع المشكو والشاكي\nلما غدا السرب يعطو بين أرحلنا … ما كان فيه غريم القلب إلاك\nهامت بك العين لم تتبع سواك هوى … من علم البين أن القلب يهواك\nحتى دنا السرب ، ما أحييت من كمد … قتلى هواك ولا فاديت أسراك\nيا حبذا نفحة مرت بفيك لنا … ونطفة غمست فيها ثناياك\nوحبذا وقفة ، والركب مغتفل … على ثرى وخدت فيه مطاياك\nلو كانت اللمة السوداء من عددي … يوم الغميم لما أفلت إشراكي"},{"id":"diwan-radi:423","bookId":"diwan-radi","type":"poem","seq":423,"chapter":"البحر: كامل تام","title":"يا قلب ليتك حين لم تدع الهوى","page":"","text":"يا قلب ليتك حين لم تدع الهوى … علقت من يهواك مثل هواكا\nلو كان حر الوجد يعقب بعده … برد الوصال غفرت ذاك لذاكا\nلا بل شجيت بمن يبيت مسلما … خالي الضلوع ولا يحس شجاكا\nإن يصبحوا صاحين من خمر الهوى … فلقد سقوك من الغرام دراكا\nيا ليت شغلك بالأسى أعداهم … أولا فليت فراغهم أعداكا\nأهوى وذلا في الهوى وطماعة … أبدا ، تعالى الله ما أشقاكا\nيا قلب كيف علقت في أشراكهم … ولقد عهدتك تفلت الإشراكا\nأكثبت حتى أقصدتك سهامهم … قد كنت عن أمثالها إنهاكا\nإن ذبت من كمد ، فقد جر الهوى … هذا السقام علي من مجركا\nلا تشكون إلي وجدا بعدها … هذا الذي جرت علي يداكا\nلأعاقبنك بالغليل ، فإنني … لولاك لم أذق الهوى لولاكا\nيا عاذل المشتاق دعه فإنه … يطوي على الزفرات غير حشاكا\nلو كان قلبك قلبه ما لمته … حاشاكا مما عنده حاشاك"},{"id":"diwan-radi:424","bookId":"diwan-radi","type":"poem","seq":424,"chapter":"البحر: بسيط تام","title":"أما تحرك للأقدار نابضة","page":"","text":"أما تحرك للأقدار نابضة … أما يغير سلطان ولا ملك\nقد هادن الدهر حتى لأقراع له … وأطرق الخطب حتى ما به حرك\nكل يفوت الرزايا أن يقعن به … أما لأيدي المنايا فيهم درك ؟\nقد قصر الدهر عجزا عن لحاقهم … فأين أين ذميل الدهر والرتك\nأخلت السبعة العليا طرايقها … أم أخطأت نهجها أم سمر الفلك ؟"},{"id":"diwan-radi:425","bookId":"diwan-radi","type":"poem","seq":425,"chapter":"البحر: طويل","title":"أفي كل يوم أنت رام بهمة","page":"","text":"أفي كل يوم أنت رام بهمة … إلى حيث لا ترمي النجوم الشوابك\nوما كل ما منيت نفسك خاليا … تنال ولا تفضي إليه المسالك\nيقولون رم تلق الذي أنت طالب … فأين العواقي دونها والمهالك\nوكم سعي ساع جر حتفا لنفسه … ولولا الخطى ما شاك ذا الرجل شائك\nألا ربما حياك رزقك طالعا … ورحلك محطوط ونضوك بارك"},{"id":"diwan-radi:426","bookId":"diwan-radi","type":"poem","seq":426,"chapter":"قصائد","title":"ورب غاو منطقه","page":"","text":"ورب غاو منطقه … بسكتة ، والحلوم تعترك\nوللفتى من وقاره جنن … إن كثرت من عدو الشكك\nثار به الجهل فابتسمت له … ورب جان عقابه الضحك"},{"id":"diwan-radi:427","bookId":"diwan-radi","type":"poem","seq":427,"chapter":"البحر: طويل","title":"أيا راكبا ترمي به الليل جسرة","page":"","text":"أيا راكبا ترمي به الليل جسرة … لها نمرق من نيها ووراك\nقراها ربيع الواديين وأتمكت … قراها عهاد باللوى وركاك\nلها هاديا عين وأذن سميعة … إذا غار أو غر العيون سماك\nتحمل ألوكا ربما حملت به … رذايا المطايا ، مشيهن سواك\nوأبلغ عماد الدين أما بلغته … بأن سلاح اللوم عندي شاك\nأفي الرأي أن تسترعي الذئب ثلة … وغوثك بطء والخطوب وشاك ؟\nأردت وقاء الرجل والنعل عقرب … مراصدة ، والأفعوان شراك\nوكان أبوك القرم هادم عرشه … فلم أنت أعماد له وسماك\nيكون سماما للمعادين ناقعا … وأنت لأرماق العداة مساك\nألا فاحذروها ، أول السيل دفعة … ورب ضئيل عاد وهو ضناك\nنذار لكم من وثبة ضيغنية … لها بعد غرار السكون حراك\nولا تزرعوا شوك القتاد فإنكم … جديرون أن تدموا به وتشاكوا\nطبعتم نصولا للعدو قواطعا … وليس عليكم للضراب شكاك\nوكان فنيصا أفلتته حبالة … وأين حبال بعدها وشراك\nيكاد من الأضغان يعدم بعضكم … على ان في فيه الشكيم يلاك\nفكيف إذا ألقى العذارين خالعا … وزال لجام الجاذبين ركاك\nدماء نيام في الأباجل أوقظت … وظني يوما أن يطول سفاك\nأليس أبوه من له في مجنكم … ضراب على مر الزمان دراك\nوكان سنانا في قناة ابن واصل … أليكم وللأجداد ثم عراك\nفأمست له بين الغماد وأربق … رهون منايا ما لهن فكاك\nتلافت عليه العاسلات كأنها … أنامل أيد ، بينهن شباك\nوإن ملاك الرأي نزع حماتها … وبالجزع حمض عازب وأراك\nفما أتبعته نشطة من حميمه … ولا من أراك الجهلتين سواك\nيطاولكم وهو الحضيض إلى العلى … فكيف إذا ما عاد وهو سكاك\nأحيلوا عليها بالمحافر أنها … معاثر في طرق العلا ونباك\nوما الحزم للأقوام أن يطأ والربى … وبين نعال الواطئين شياك\nولو عضد الملك اجتلاها مخيلة … لقطعها بالعضب وهي تحاك\nفليت لنا ذاك الجذيل يطبنا … إذا لج بالداء العضال حكاك\nفإن تطفئوها اليوم فهي شرارة … وغدوا أوار ، والأوار هلاك"},{"id":"diwan-radi:428","bookId":"diwan-radi","type":"poem","seq":428,"chapter":"البحر: رمل تام","title":"لا يرعك الحي أن قيل هلك","page":"","text":"لا يرعك الحي أن قيل هلك … أخذ المقدار منا وترك\nانظري ترضى بقايا قومنا … إن جلا اليوم غبار المعترك\nأخذوا الشطر الذي أبقى الردى … ثم قالوا : عن قليل هو لك\nأبتغي عدل زمان قاسط … إنما الناس على دين الملك\nباخل أن ضافه الحق فلا … أعتق المال ولا العرض ملك"},{"id":"diwan-radi:429","bookId":"diwan-radi","type":"poem","seq":429,"chapter":"البحر: كامل تام","title":"أنا للركائب إن عرضت ، بمنزل","page":"","text":"أنا للركائب إن عرضت ، بمنزل … وإذا القنوع أطاعني لم أرحل\nلم أطلب المثري البخيل لحاجة … أبدا واقنع بالجواد المرمل\nوارى المعرض باللئيم كأنه … أعشى اللحاظ يحز غير المفصل\nولرب مولى لا يغض جماحه … طول العتاب ولا عناء العذل\nيطغى عليك ، وأنت تلأم شعبه … كالسيف يأخذ من بنان الصيقل\nأبكي على عمر يجاذبه الردى … جذب الرشاء عن القليب الأطول\nأخلق بحبل مرسل في غمرة … أن سوف يرفعه بنان المرسل\nما كنت أطرب للقاء ولا أرى … قلقا بين الظاعن المتحمل\nألوي عناني عن منازلة الهوى … وأصد عن ذكر الغزال المغزل\nوأزور أطراف الثغور ودونها … طعن يبرح بالوشيج الذبل\nأأنال من عذب الوصال ودونه … مر الإباء ونخوة المتدلل\nما كنت أجرع نطفة معسولة … طوع المنى ، وإناؤها من حنظل\nأعقيلة الحيين دونك فارفعي … ما شئت من عذب القناع المسبل\nهيهات تبلغك اللحاظ ، وبيننا … هضب كخرطوم الغمام المقبل\nأوطان غيرك للضيافة طلقة … وسواك في اللأولاء رحب المنزل\nوإذا أمير المؤمنين أضاف لي … أملي نزلت على الجواد المفضل\nبالطائع الميمون أنجح مطلبي … وعلوت حتى ما يطاول معقلي\nقرم ، إذا عرت الخطوب مراحه … أدمى غواربها بناب أعضل\nمتوغل خلف العدو ، وعلمه … أن الجبان إذا سرى لم يوغل\nوإذا تنافلت الرجال غنيمة … قسم التراث لها بحد المنصل\nثبت لهجهجة الخطوب ، كأنما … جاءت تقعقع بالشنان ليذبل\nرأي الرشيد ، وهيبة المنصور في … حسن الأمين ونعمة المتوكل\nأباؤك الغر الذين إذا انتموا … ذهبوا بكل تطاول وتطول\nدرجوا كما درج القرون وعلمهم … أن سوف يخبر آخر عن أول\nنسب إليك تجاذبت أشياخه … طولا من العباس غير موصل\nهذي الخلافة في يديك زمامها … وسواك يخبط قعر ليل اليل\nأحرزتها دون الأنام ، وإنما … خلع العجاجة سابق لم يذهل\nبحوادر يعنقن من تحت القنا … عنقا يعرد بالذئاب العسل\nغر محجلة إذا احتضر الوغى … نقبنم عن يوم أغر محجل\nدفعت فأي الحزم عنها لم يضق … عرقا ، وأي اللجم لم يتصلصل\nسلخ الظلام أهابه وتهللت … جنبات ذاك العارض المتهلل\nطلعت بوجهك غرة نبوية … كالشمس تملأ ناظر المتأمل\nوإذا نبت بك في مسالمة العدى … أرض وهبت ترابها للقسطل\nوفوارس ما استعصموا بثنية … إلا طلعت عليهم في جحفل\nشردت بنا ذلل الركاب ، كأنما … يذرعن بردة كل قاع ممحل\nوالآل ينهض بالشخوص أمامنا … ويمد أعناق القنان المثل\nمن كل رابية ترفع جيدها … فكأنه هادي حصان مقبل\nومعرس هزج الوحوش كأنما … طرق المسامع عن غماغم مرجل\nعركت جوانبنا الفلاة ، وأسرعت … في العظم واقتاتت شحوم البزل\nوإليك طوح بالمطي مغرر … عصفت به أيدي المطي المضلل\nفأتتك تلتهم الهواجر طلحا … والظل بين خفافها والجرول\nوخفائفا فجعت بكل حقيبة … ملأى وكل مزاد ماء أثجل\nوعلى الرحال عصائب ملتاثة … تلوب بشعر ثم غير مرجل\nعلقت حبلك ثم اقسمت المنى … أن لا لوين بغير حبلك أنملي\nأمل جثا بفناء دارك قاطنا … وكأنه بفناء واد مبقل\nمولاي من لي أن أراك ، وكيف لي … غطاه عرف العارض المتهدل\nأرجوك للأمر الخطير وإنما … يرجى المعظم للعظيم المعضل\nوأروم من غلواء عزك غاية … قعساء ، تستلب النواظر من عل\nكم رامها منك الجبان فراوغت … شقاء يلعب شدقها بالمسحل\nتدمي قلوب الحاسدين وتنثني … فترد عادية الخطوب النزل\nضاق الزمان ، فضاق فيه تقلبي … كالماء يجمع نفسه في الجدول\nهذا الحسين إلى علائك ينتمي … شرفا ، وينسب مجده في المحفل\nأسلفته وعدا عليك تمامه … وسيدرك المطلوب أن لم يعجل\nفاسمح بفعلك بعد قولك إنه … لا يحمد الوسمي إلا بالولي\nفلعلنا نمتاح إن لم نغترف … أن لا ننام عن الرجاء المهمل\nكم وقفة ناجيته في ظلها … والقول يغدر بالخطيب المقول\nثبت فيها وطاءه ، ووراءه … جزع يقلقل من قلوب الجندل\nأيه وكم من نعمة جللته … تضفو كهداب الرداء المخمل\nفسما وحلق كالعقاب إلى العلى … وعدوه يهوي هوي الأجدال\nوبوده لوز كان قرنا سالفا … أو نطفة ذهبت بداء مغيل\nومشمر العرنين خر جبينه … لك غير مقبول ولا مستقبل\nلما رآك تقاصرت خطواته … جزعا وجعجع بالرواق الأول\nلله أنت لقد أثرت صنيعة … بيدي معم في الصنائع مخول\nشرفتنا دون الأنام ، وإنما … بر القريب علاقة المتفضل\nوجذبتنا جذب الجرير إلى العلى … وإذا ارتقى متمطر لم ينزل\nفلأنت أولى بالإمامة والهدى … واذب عن ولد النبي المرسل\nأغبار در من عطائك تفتدى … من در غيرك بالضروع الحفل\nلولا غمام نداك أصبح راكب … يشكو الأوام ، وقد أناخ بمنهل\nوأحق بالأطراء باعث منة … وصلت من الأرحام ما لم يوصل\nأنظر إلي ببعض طرفك نظرة … يسمو لها نظري ويعرب مقولي\nفالآن لا أرضى ، وأنت ممولي … برضى القنوع وعفة المتجمل\nنعمى أمير المؤمنين حرية … أن لا ننام على الرجاء المهمل\nبفم ، إذا رفع الكلام سجافه … أوحى بنائله وأن لم يسئل\nويد إذا استمطرت عابر مزنها … دفقت عليك من الزلال السلسل\nتمحو أساطير الخطوب كما محا … مر الشمال من الغمام المثقل\nلا يحتمي بالرمح باع مؤيد … وشاء طاعن بالسماك الأعزل\nهذا الخليفة لا يغض عن الهدى … أن نام ليل القائم المتبتل\nلما أهبت بنصره لملمة … دفع الزمان وقد أناخ بكلكلي\nوأليت فيه مدائحي فكأنما … أفرغت نبلي كلها في مقتل\nمن كل قافية إذا أطلقتها … عطفت عنان الراكب المستعجل\nوظفرت من نفحاته وجواره … بأجل نعماء وأحرز موئل"},{"id":"diwan-radi:430","bookId":"diwan-radi","type":"poem","seq":430,"chapter":"البحر: كامل تام","title":"أمبلغي ما أطلب الغزل","page":"","text":"أمبلغي ما أطلب الغزل … أم لا فتنجدني القنا الذبل\nوالسيف أولى أن أعوذ به … مما تجر الأعين النجل\nوأنا الذي نفر الزمان به … واستأنست بركابه السبل\nأسري على غرر ، وتصحبني … دون الرجال الأينق الذلل\nلا المال يجذبني إليه ولا … يعتاقها الحوذان والنفل\nعجل بي الشد الحثيث إلى … غايات خراج بي المهل\nفي غلمة تركوا قعودهم … نزعوا وراء الليل وانحفلوا\nوإذا المزاد حمى صلاصله … قنعوا بما تقضي لنا المقل\nومقوم الأذنين تحسبه … طودا أناف بصدره جبل\nمتطاول يوفي مغردة … عنقا تضاءل خلفها الكفل\nأجهدته والكر يعصره … والماء من عطيفه ينهمل\nونجيبة نهض الزمان بها … من بعد ما قعدت بها العقل\nصدعت عرانين الربى ونجت … هوجا ، وينجد وخدها الرمل\nطلبت أمير المؤمنين ولا … أين أطاف بها ولا مهل\nحيث العلى لا يستراب بها … والجود لا يلوي به البخل\nوالطائع المرجو إن حمدت … أيدي الرجال وقل من يسل\nملك إذا حصر السماط به … كثر العثار ، وطبق الزلل\nجلت الأئمة عن مناقبه … واستودعته نورها الرسل\nوإذا العيوب مشت إليه بدا … وجه تخاوص دونه المقل\nفاللحظ محتبس ومنطلق … والقول منقطع ومتصل\nطرب إلى النعماء عاهدها … أن لا يمر بسمعه عذل\nيلقى الخطوب ، ووجهه طلق … ويخوضهن وقلبه جذل\nتخفى بشاشته حميته … كالسم موه طعمه العسل\nمن معشر كانت سيوفهم … حليا لمن ضربوا ، ومن عطلوا\nبالفخر يكسون الذي سلبوا … والذكر يحييون الذي قتلوا\nأنت الجواد ، إذا غلا أمل … والمستجار إذا طغى وجل\nومطاعن بعثت يداك له … طعنا يذل لوقعه البطل\nوعلمت أن السيل يدفعه … لما أطل العارض الهطل\nلله رمحك يوم تورده … والماء لا صرد ولا علل\nخطل المناكب لا يميل به … عوج ومن نعت القنا الخطل\nومطاعنين ، إذا هما اعترضا … يتطاعنان وللقنا زجل\nنزل الهصور على فريسته … ومضى يدحرج نجوه الجعل\nشيخان هذا فارس بطل … أبدا وهذا عاجز مذل\nفإذا الزمان أراد قودهما … حزن الجواد وأصحب الوعل\nأمريد زائدة الأنام أقم … هيهات منك الشد والعجل\nأتريد غايات الفخار ، وما … لك ناقة فيه ، ولا جمل ؟\nفانعق بضأنك عن أناطحه … ودع الغمير تلسه الأبل\nيا قابض الأيام عن وجل … بيمينه عن مسها شلل\nيئل الذي أمنت روعته … والعصم في الأطواد لا يئل\nلوليك الدنيا مزخرفة … ولأم من عاديته الهبل\nأن قال فيك عداك منقصة … قالوا : السماء أديمها نغل\nاحذر عدوك أن تقربه … من قلبك الخدعات والحيل\nلا تخدعن على رقاه ، ولو … أرضاك منه القول والعمل\nففؤاده حنق عليك ، وإن … طاطا ، وذلله لك الوجل\nإن المجرد في هواك فتى … لا اللوام يردعه ولا العذل\nمثل الحسينم فبين أضلعه … قلب بغيرك ما له شغل\nذاك الحسام أطلت جفوته … ولقل ما ظفرت به الخلل\nووعدته وعدا تعلقه … والوعد ملوي به الأمل\nفانهض به في النائبات تجد … عضبا تساقط دونه القلل\nوأسلم أمير المؤمنين إذا … شرع الحمام وصمم الأجل\nمتقلدا بنجاد مملكة … في غمدها الأقدار والدول\nوأنعم بيوم المهرجان ولا … نعم العداة به ، ولا عقلوا\nفلأنت نهاض إذا قعدوا … أبدا وصع اد إذا نزلوا\nيوم تجدده السنون ، وقد … درجت عليه الأعصر الأول\nفالناس فيه معلل طرب … يرجو الأوار وشارب ثمل\nما استجمعت فرق الهموم به … إلا وبدد جمعها الجذل\nهو خطة نزل الشتاء بها … والصيف منطلق ومرحتل\nوأنا الذي أهوى هواك ، ولو … ضربت علي البيض والأسل\nوطئت قبائل غالب عقبي … وتشرفت بمقامي الحلل\nومراغم يغدو على قنصي … فيحوزه ويداي محتبل\nخضت الغمار فجاز جمتها … دوني وطبق ثوبي البلل\nومذكري رحما معنسة … كالشمس أخلق ضؤها الطفل\nرحم تعلق بالعبيد كما … علق الحباء النازح الطول\nإثنان يقتطعان من فرصي … وأنا الذي أرخى واهتبل\nغرضي بمدحك أن يطاوعني … عوج بأيامي ويعتدل\nوأقوم بين يديك مرتجلا … لا ألعي يقطعني ولا الخطل\nولئن نما كل المديح إلى … فلتات قولي وانتمى الغزل\nفالأرض أم الترب أجمعه … وأبو البرية كلها رجل"},{"id":"diwan-radi:431","bookId":"diwan-radi","type":"poem","seq":431,"chapter":"البحر: طويل","title":"مسيري إلى ليل الشباب ضلال","page":"","text":"مسيري إلى ليل الشباب ضلال … وشيبي ضياء في الورى وجمال\nسواد ، ولكن البياض سيادة … وليل ولكن النهار جلال\nوما المرء قبل الشيب إلا مهند … صدي ، وشيب العارضين صقال\nوليس خضاب المرء إلا تعلة … لمن شاب منه عارض وقذال\nوللنفس في عجز الفتى وزماعه … زمام إلى ما يشتهي وعقال\nبلوت وجربت الأخلاء مدة … فأكثر شيء في الصديق ملال\nوما راقني ممن أود تملق … ولا غرني ممن أحب وصال\nوما صحبك الأدنون إلا أباعد … إذا قل مال أو نبت بك حال\nومن لي بخل أرتضيه ، وليت لي … يمينا يعاطيها الوفاء شمال\nتميل بي الدنيا إلى كل شهوة … وأين من النجم البعيد منال\nوتسلبني أيدي النوائب ثروتي … ولي من عفافي والتقنع مال\nإذا عزني ماء وفي القلب غلة … رجعت وصبري للغليل بلال\nأرى كل زاد ما خلا سد جوعة … ترابا وكل الماء عندي آل\nومثلي لا يأسى على ما يقوته … إذا كان عقبى ما ينال زوال\nكأنا خلقنا عرضة لمنية … فنحن إلى داع المنون عجال\nنخف على ظهر الثرى ، وبطونه … علينا ، إذا حل الممات ، ثقال\nوما نوب الأيام إلا أسنة … وما ضرني أني أتيت وزالوا\nوأنعم منا في الحيوة بهائم … وأثبت منا في التراب جبال\nأنا المرء لا عرضي قريب من العدى … ولا في للباغي علي مقال\nوما العرض الأخير عضومن الفتى … يصاب ، وأقوال العداة نبال\nوقور ، فإن لم يرع حقي جاهل … سألت عن العوراء كيف تقال\nإلى كم أمشي العيس غرثى كليلة … وأودع منها ربرب ورئال\nأروغ كأني في الصباح طريدة … وأسري كأني في الظلام خيال\nتمطى بنا أذوادنال مهمة … خفائف تخفيها ربى ورمال\nلطمنا بأيديها الفيافي إليكم … وقد دام إغذاذ ، وطال كلال\n … يد الفجر في سيف جلاه صقال\nتقوم أعناق المطي نجومه … فليس لسار فوقهن ضلال\nوهوجاء قدام الركاب مغذة … لها من جلود الرازحات نعال\nرحلنا بها كالبدر حسنا وشارة … وملنا إلى البيداء ، وهي هلال\nإليك ، أمين الله ، وسمت أرضها … بأخفاقها يدنو بهن نقال\nأيادي أمير المؤمنين كثيرة … ومال أمام المؤمنين مذال\nوأوقاته اللاتي تسوء قصيرة … وأيامه اللاتي تسر طوال\nمن الضاربين الهام والخيل تدعي … وإن غاب أنصار وقل رجال\nهم القوم إن ولى المعاريك أقبلوا … وأن سئلوا بذل النوال أنالوا\nوأن طرق القوم العبوس تهللوا … وإن مالت السمر الذوابل مالوا\nأجيل لحاظي لا أرى غير ناقص … كأن الورى نقص وأنت كمال\n … وفائدة لا تنقضي ونوال\nوأنت الذي بلغتنا كل غاية … لها فوق أعناق النجوم مجال\nفما طرد النعماء وعدك ساعة … ولا غض من جدوى يديك مطال\nإذا قلت كان الفعل ثاني نطقه … وخير مقال ما تلاه فعال\nأزل طمع الأعداء عني بفتكة … فلا سلم إلا أن يطول قتال\nفإن نفوس الناكثين مباحة … وأن دماء الغادرين حلال\nوشمر ، فما للسيف غيرك ناصر … ولا للعوالي أن قعدت مصال\nومن لي بيوم شاحب في عجاجه … أنا بأطراف القنا وأنال\n … لها من غيابات الغبار جلال\nأردني مرادا يقعد الناس دونه … ويغبطني عم عليه وخال\nولا تسمعن من حاسد ما يقوله … فأكثر أقوال العدة محال\nهناء لك الصوم الجديد ، ولا تزل … عليك من العيش الرقيق ظلال\nوجادك منهل الغمام ، وصافحت … حماك جنوب غضة وشمال\nولا زال من آمالنا ورجائنا … عليك ، وإن ساء العدو ، عيال\nوفي كل يوم عندنا منك عارض … وعند الأعادي فيلق ونزال\nأنا القائل المحسود قولي من الورى … علوت ، وما يعلو علي مقال\nولا فرق بيني في الكلام وبينهم … بشيء سوى أني أقول وقالوا\nفلا زال شعري فيك وحدك كله … ولا اضطرني إلا إليك سؤال"},{"id":"diwan-radi:432","bookId":"diwan-radi","type":"poem","seq":432,"chapter":"البحر: بسيط تام","title":"أحظى الملوك من الأيام والدول","page":"","text":"أحظى الملوك من الأيام والدول … من لا ينام غير البيض والأسل\nوأشرف الناس مشغول بهمته … مدفع بين أطراف القنا الذبل\nتطغى على قصب الأبطال نخوته … وقائم السيف مندوب إلى القلل\nما زلت أبحت أمري عن عواقبه … حتى رأيت حلول العز في الحل\nوفي التغرب إلا عنك مغنمة … ومنبت الرزق بين الكور والجمل\nلولا الكرام أصاب الناس كلهم … داء البعاد عن الأوطان والحلل\nنرجو ، وبعض رجاء الناس متعبة … قد ضاع دمعك ياباك على الطلل\nكم اغتربت عن الدنيا وما فطنت … بي المهامه حتى جازني أملي\nفي فتية ركبوا أعراصهم ورموا … بالذل خلف ظهور الخيل والإبل\nوالماء إن صفرت منه مزادهم … شربته من بطون الأينق البزل\nإيه لقد أسر الدنيا بنجدته … أبو الفوارس والإقدام للبطل\nصان الظبى واستلد الرأي وانكشفت … له العواقب بين الهم والجذل\nماض على الهول طلاع بغرته … على الحوادث مقدام على الأجل\nهنئت ، يا ملك الأملاك ، منزلة … ردت عليك بهاء الأعصر الأول\nدعاك رب المعالي زين ملته … وملة أنت فيها أعظم الملل\nصدمت بغداد ، والأيام غافلة … كالسيل يأنف أن يأتي على مهل\nبكل أبلج معروف بطلعته … إذا تناكر ليل الحادث الجلل\nيا قائد الخيل إن كان السنان فما … فإن رمحك مشتاق إلى القبل\nوكم مددت على الأقران من رهج … في ليلة تغدر الألحاظ بالمقل\nومستغرين ما زالت قلوبهم … تبدد الرأي بين الريث والعجل\nحتى أخذت عليهم حتف أنفسهم … ما أظلموا ببروق العارض الهطل\nرأوا مقامك ، فازورت عيونهم … ما كل لحظ إلى الآماق من قبل\nلله زهرة ملك قام حاسدها … وليس يعلم أن الشمس في الحمل\nلا تأسفن من الدنيا على سلف … فاخر الشهد فينا أعذب العسل\nولا تبال بفعل إن هممت به … ولو رمى بك بين العذر والعذل\nلا تمشين إلى أمر تعاب به … فقلما تفطن الأيام بالزلل\nلله أي فتى أمست لبانته … رذية بين أيدي العيس والسبل\nلا ينشد الحب رأيا كان أصلحه … إذا الفتى طرد الآراء بالغزل\nرآك أشرف ممدوح لممتدح … وخير من شرعت فيه يد الأمل\nنحا لنحوك لا يلوي على أحد … أن المقيم عن النزاع في شغل\nوليس يأتلف الإحسان في ملك … حتى يؤلف بين القول والعمل\nفما أمل مديحا أنت سامعه … وعاشق العز لا يؤتى من الملل\nما عذر مثلي في نقص وقولته … إني الرضي وجدي خاتم الرسل\nهذا أبي والذي أرجو النجاح به … أدعوه منك طليق الهم والجذل\nلولاك ما انفسحت في العيش همته … ولا أقر عيون الخيل والخول\nحططته من ذرى صماء شاهقة … من الزمان عليها غير محتفل\nتلعاء عالية الأرداف تحسبها … رشاء عادية مستحصد الطول\nتلقى ذوائبها في الجو ذاهبة … يلفها البرق بالأطواد والقلل\nوأنت طوقته بالمن جامعة … قامت عليه مقام الحلي والحلل\nأوسعته فرأى الآمال واسعة … وكل ساكن ضيق واسع الأمل\nجذبت من لهوات الموت مهجته … وكان يطرف في الدنيا على وجل\nما كان إلا حساما أغمدته يد … ثم انتضته اليد الأخرى على عجل\nفأقذف به ثغر الأهوال منصلتا … واستنصر الليث أن الخيس للوعل\nولا تطيعن فيه قول حاسده … إن العليل ليرمي الناس بالعلل\nأولى بتكرمة من كان يحمدها … والحمد يقطع بين الجود والبخل\nكفاك منظره إيضاح مخبره … في حمرة الخد ما يغني عن الخجل\nتحمل الشرف العالي وكم شرف … غطى عليه رداء العي والخطل\nأويته من نزال المستطيل إلى … مرعى أنيق وظل غير منتقل\nإنا لنرجوك ، والأيام راغمة … والروض يرجو نوال العارض الخضل\nتبلى بدولتك الدنيا ، وحاش لها … أن لا يكون علينا أبرك الدول"},{"id":"diwan-radi:433","bookId":"diwan-radi","type":"poem","seq":433,"chapter":"البحر: منسرح","title":"لا زعزعتك الخطوب يا جبل","page":"","text":"لا زعزعتك الخطوب يا جبل … وبالعدا حل لا بك العلل\nقد يوعك الليث لا لذلته … على الليالي ويسلم الوعل\nلا طرق الداء من بصحته … يصح منا الرجاء والأمل\nحاشاك من عارض تراع به … ذاك فتور النعيم والكسل\nالنجم يخفى وأنت متضح … والشمس تخبو وأنت مشتعل\nوأنت لا مرهق ولا قلق … والبدر مستوفز ومنتقل\nوعك كما يطبع الحسام وفي … جوهره صاقل له عمل\nما ضره ذاك ، وهو منصلت … تسقط منه الرقاب والقلل\nما صرف الدهر عنك أسهمه … فكل جرح يصيبنا جلل\nباق نخطاك كل نائبة … إلى العدا ، والنوازل العضل\nقد ضمن الله أن تدوم لنا … مسلما والزمان والدول\nما قدروا لا علت جدودهم … ولا نجوا بعدها ، ولا وألوا\nلا خوف ، والجد مقبل أبدا … على الليالي وأنت مقتبل\nهل قدم الطود وهي راسخة … يخاف منها العثار والزلل\nفاتفضي أيها الرؤوس لها … واستوثقي للقياد يا إبل\nها الشدة وال … غروض والعقل\nلا ترتعي معشبا ، منابته … بيض الظبى والواسل الذبل\nترعى سوام العبيد هيبته … فكيف يرضى ، وذوده همل\nفقل لغاو مشى الظلام به : … أين إلى أين قادك الخطل\nطمعت أن ترتقي بلا قدم … إلى العلى ، راع أمك الثكل\nحلمت في نومة الغرور بها … شر حلوم وغرك المهل\nفاحذر مرامي الأقدار عن ملك … راها نموم وعرفها ثمل\nأتزحم … أم تتعاطى السيول ، يا وشل\nهيهات أن يسبق الجياد وج … ويطلع الغاد قبلها وجل\nبادرت نهب العلا فرجرجه … بوع طوال وأذرع فتل\nرأى لصابا ، فشارها صبرا … ذق الجنى قد أظلك العسل\nسطو أقام العدا على قدم … وقوم المائلين ، فاعتدلوا\nقد سبق السيف عذل عاذله … لما تجارى الحسام والعذل\nأليس من معشر بنوا شرفا … صعبا وفيهم خلائق ذلل\nقشاعم طارت الجدود بهم … مذ صعدوا في العلاء ما نزلوا\nمدوا علابي مجدهم ، وسمت … بهم رعان الفضائل الطول\nالمبشرات العلى منازلهم … والقمم العاليات والقلل\nكانوا سماء لنا فلا عجب … أن قطروا بالنوال أو هطلوا\nطال لزوم القنا أكفهم … ينآد من طعنهم ويعتدل\nكأن أيديهم نبتن لهم … مع القنا حيث ينبت الأسل\nيستعذب القتل من أكفهم … كأنهم ينشرون من قتلوا\nما أهملوا السائمات حيث رعوا … ولا أضاعوا الأمور حين ولوا\nإذا استهبوا سيوفهم أبدا … فلم أعد الغمود والحلل\nمن كان ممطورة مخالبه … على العدا غير أنه رجل\nيعترف الناس في مطالبه … ويلتقي عند بابه السبل\nيرى جبانا عن رد سائله … وهو إذا اعصوصب الوغى بطل\nبعوده عند ضنه يبس … وفي يديه من الندى بلل\nألبستيها بغيظ طالبها … وغودرت في الأضالع الغلل\nأصبح كيد العدو يجذبها … عني ، لأيدي الجواذب الشلل\nمالي إذا شئت أن أزاد خلى … من غيركم كان حظي العطل\nأرى نهابا تساق حافلة … لا ناقة لي بها ولا جمل\nوشر ما يرجع الغري به … أن عاد يرمي ، وفاته الوعل\nأين ندى كفك الكريم لها … وأين عادات طولك الأول\nبنا الأذى لا بكم ، إذا نزل الخط … ب طروقا ، وصمم الأجل\nودمتم للعلى ، وعيشكم … غض ، وراووق عزكم خضل\nلا عجب إن نقيكم حذرا … نحن جفون وأنتم مقل"},{"id":"diwan-radi:434","bookId":"diwan-radi","type":"poem","seq":434,"chapter":"البحر: مجزوء الرجز","title":"أين الغزال الماطل","page":"","text":"أين الغزال الماطل … بعدك ، يا منازل\nقد بان حالي سربه … فلم أقام العاطل ؟\nمن لقتيل الحب لو … رد عليه القاتل\nشيع بالقطر الروا … ذاك الشباب الراحل\nكل حبيب أبدا … أيامه قلائل\nل غرور باطل … فودك ظل زائل\nفإن وعدن فاعملن … إن الغريم الماطل\nكإنما يمطره … ملك الملوك العادل\nهو الحيا ، وفي الحيا … من جوده شمائل\nغياث كل أزمة … إن عض عام ماحل\nوداعم الدنيا إذا … مادت بها الزلازل\nف الطويل الذابل … دين له أرامل\nوالحامل العب رمى … ن ، ولا الخلاخل\nتنسد فيه الشمس قد … تاهت بها القساطل\nس بها والنائل … إلى الردى قنابل\nكان معروض القنا … في العين عال ، وهو في ال\nيخشى عواليه ورا … عقارب شوائل\nكما تثوب الدبر قد … عاد إليها العاسل\nعناق والكواهل … في الغي رأي قاتل\nإني ارتقيت خطة … أمك فيها هابل\nردك عن صعودها … بالخزي جد نازل\nفات يديك قابها … والقلل الأطاول\nل الأعين القواتل … عن لحظك الأنابل\nيا لك من حاف مشى … حيث ينزل الناعل\nفإن وعدن ، فاعلمن … ثغر العلا مناضل\nيمنع الطود فلا … راق ولا مطاول\nأما رأى ابن واصل … تقنصه الحبائل\nفطار ترقيه الظبا … والأسل الذوابل\nأفلتها منخرق … الجلد له ولاول\nعار على عاتقه … من دمه حمائل\nتقطعت بينهما … قلب مذال سافل\nدلاه فيها مثل ما … ليث هموس الليل ع\nحاول رد غربها … يا بعد ما يحاول\nحتى امتطى راحلة … تنكرها الرواحل\nلا ترد الماء ، ولا … تطوي بها المنازل\nلربها نباهة … في الناس ، وهو خامل\nفاخبط رصيد فتنة … تخشى بها الغوائل\nهناك ضب كدية … ني في البلاد سائل\nفاليوم بكر وغدا … ووعد ذي الشيبة بالوص\nوالله فيه ضامن … لما أردت كافل\nوما على الأكعب أن … فللمنايا قابل\nومن دواء الداء أن … ماطل كي عاجل\nكالغيث ضوء بارق … منه ، وري وابل\nأواخر من منن … يضمها إلا وائل\nإن كان ذا العام له … ونعمت الحوامل\nمقدار عنك غافل … أخرى الليالي ناقل\nطى ربعك النوازل … الآطام والمعاقل\nكالنصل يمضي صاقل … عنه ، ويأتي صاقل\nوهو ، كما ساء العدا … ما ضي الغرار قاصل\nفيكم ينابيع الندى … والدلح الهوامل\nهواجر الأيام في … ظلالكم أصائل\nوالحامل العبء رمى … ولا البقاء طائل"},{"id":"diwan-radi:435","bookId":"diwan-radi","type":"poem","seq":435,"chapter":"البحر: بسيط تام","title":"أهلا بهن على التنويل والبخل","page":"","text":"أهلا بهن على التنويل والبخل … وقربتهن أيدي الخيل والإبل\nالقاتلات بلا عقل ولا قود … والماطلات بلا عذر ولا علل\nكان اللقاء إساءات بذي سلم … إلى القلوب وإحسانا إلى المقل\nكأنما عاذلات الصب بعدهم … يفتلن عقلا لشراد من النزل\nيرمن في السارح المرعي محبسه … وهمه اليوم أن يغدو مع الهمل\nرمين منه وحادي الشوق يحفزه … بقاطع ربق الأقياد والعقل\nيطلبن برئي بأمر زاد في سقمي … إن الأساة لأعوان مع العلل\nحاولن شغل فؤادي من علاقته … بالعقل ، والقلب عند البيض في شغل\nإن الربائب من غزلان أسنمة … أعلقن ذا الشيب أعلاقا من الغزل\nمن كل ريم هوى ألحاظ مقلته … يمسين للعذر أنصارا على العذل\nحليه جيده لا ما يقلده … وكحله ما بعينيه من الكحل\nغاد تلفت والمشتاق يتبعه … صفح الطليق إلى المقصور بالطول\nأما كفاهم لجاج الدمع بعدهم … حتى استعانوا على عيني بالطلل\nيا قاتل الله ريعان الشباب وما … خلى علي من الأشجان والغلل\nورفضة من سواد الليل مطمعة … قد ضل طالب ود البيض بالحيل\nإني أقول لملاق ركائبه : … مهل عليك فليس الرزق بالعجل\nليس المقام بثان عنك وارده … من الحظوظ ولا الأرزاق بالرجل\nأما ترى الرزق في الأوطان يطرقني … ولم أقلقل أصيحابي ولا إبلي\nفي كل يوم قوام الدين ينضحني … بما طر غير منزور ولا وشل\nيروي ولم يتوقع صوب عارضه … ولم يقدم بشير الطارق العمل\nظفرت بالنفل المطلوب في وطني … وإنما يرجع الغازون بالنفل\nمن كل بيضاء لم تخطر على خلدي … من الأيادي ولم تبلغ إلى أملي\nذرت إلي ذرور الشمس طالعة … شروقها أبدا باق بلا أصل\nفي كل يوم جديد من صنائعه … إلي لا ناقتي فيها ولا جملي\nيردني يقنيص ما نصت له … على المطامع أشراكا من الأمل\nوسمت عقلي وأرغمت المعاطس في … من العدا وأقمت الصفو من ميلي\nرفعت ناري على علياء مشرفة … من المعالي وأخفضت النوائب لي\nفهل تركت لذي الأوطار من وطر … يسعى له ولذي الآمال من أمل\nلم يبق طولك في جيدي مكان حلى … وإنما يستعار الحلي للعطل\nأغنت ملابس فخر أنت مسحبها … عن رائع الحلي أو عن رائق الحلل\nأنتم لنا نفس من كل كاربة … وأنجم في ظلام الحادث الجلل\nتنبو إذا لم تكن عنكم ضرائبنا … والسيف أقطع شيء في يد البطل\nالناس ما غبتم سلك بلا درر … ولا نظام وأجفان بلا مقل\nمثل النهار بلا شمس تضيء به … أو الظلام بلا بدر ولا شعل\nمن معشر وردوا العلياء جمعتها … وسابقوا عجل الجارين بالمهل\nلقوا الخطوب بلا خوف ولا ضعف … والرائعات بلا ميل ولا عزل\nطاروا بألباب ذؤبان مسومة … رعين بين مجال البيض والأسل\nفي حجفل كشحاء … مزمجر يضرب العرنين بالجفل\nمجره كمجر السيل ذو لثق … من انبعاق الدم الجاري وذو خضل\nيرمي به ملك الأملاك يعتبه … قطع الدليل بما يعمي من السبل\nأما نهى الناس عنكم صوب بارقة … كان المشيب إليها رائد الأجل\nفي أربق ، وسيوف الموت ماضية … يطعن أمرك في الأعناق والقلل\nقصرت رمحك طولا في صدورهم … ورمح غيرك لم يقصر ولم يطل\nطاشت رؤوسهم حتى جعلت لهم … مناصبا من أنابيب القنا الذبل\nكدأبها يوم يم ، والقنا شرع … كمبرد القين تحاتا من الجبل\nفأين رخم الرقاب الغلب رافعة … دون العلى وقراع الأذرع الفتل\nهيهات ردت إلى الأعناق كانعة … أيد قصرن عن الأطواد والقلل\nكدأبها يوم سيم والقنا شرع … والضرب يبعد بين العنق والكفل\nأسلن بالدم وادي كل غامضة … من العيون كماء المزن لم يسل\nحتى رجعن ولم يتركن فاغرة … من العدو إلى قول ولا عمل\nجرى الثقاف على عوذ مقلقلة … ذودين من أود باد ومن خطل\nقضى لك الله أن يجري بلا أمد … وأن يدوم مع الدنيا بلا أجل\nتوقلا في بناء غير منتقض … من المعالي وظل غير منتقل\nمعطى عنانا من النعمى فقدت به … تغاير الدهر بالأيام والدول\nوكلما جزت عاما أو بلغت مدى … رد الزمان على أيامك الأول"},{"id":"diwan-radi:436","bookId":"diwan-radi","type":"poem","seq":436,"chapter":"البحر: متقارب تام","title":"ذكرت على بعدها من منالي","page":"","text":"ذكرت على بعدها من منالي … منازل بين قبا والمطال\nومبنى قباب بني عامر … على الغور أطنابهن العوالي\nمرابع يشكو بهن الجراح … أسود الشرى من ظباء الرمال\nمضاحكهن عقود العقود … وأجيادهن لآلي اللآلي\nوما طلب البذل من باخل … بميسوره ، غير داء عضال\nوما زال يلوي ديون الهوى … ويؤيسنا من قليل النوال\nإليك ، فقد قلصت شرتي … بعيد البياض ، قلوص الظلال\nسواد يعجل زور البياض … علوق الضرام برأس الذبال\nومر على الرأس مر الغمام … قليل المقام سريع الزيال\nفليس الصبا اليوم من أربتي … ولا ذلك البال ، يا عز ، بالي\nحلفت بهن دوامي الفجاج … إلى الخوف يطلبنه من ألال\nخماصا تساوك بالمجرمين … بعقل الوجا وقيود الكلال\nيماطلن بالوخد عند الجذاب … كان الزمام مكان العقال\nلقد ربنا من غياث الأنام … مقيم الصغا ودليل الضلال\nحمول نهوض بأعبائها … إذا البزل جرجرن تحت الرحال\nفتى في الندى أخرق الراحتين … صناعهما في بناء المعالي\nعقبان يوم ندى أو ظلال … ل ولى ، ومنتص جيد الغزال\nعقائل علمهن العفا … علينا وقيعة ماء زلال\nلئن كنت تاليه في ذا الجلال … فإنك قدامه في الكمال\nولولا الحياء لجاورته … ورب أخير أمام الأوالي\nمقيم بحي على فارس … رقاق البرود رقاق النعال\nأبوا أن يخلوا بنار القرى … ولو وفدوا نارهم بالعوالي\nيفوت مقلده والعذا … سنا المجد أو طيف عرف الخلال\nبنار المقاري ونقع الغبار … تشابه أيامهم والليالي\nلقد نطح الجد أعداءهم … برأس جموح وروق طوال\nلهم صفحات كبيض الصفيح … حلاهن عن جوهر المجد حال\nوأيد سجاح كرام معا … بمجد مصون ومال مذال\nأقول لساع على أثرهم … يطالب شأوا بعيد المنال\nحذار فإن على الجهلتين … هموس الدجى مرصدا للرعال\nله هامة كرحى الطاحنات … تدور على لبدة كالثفال\nينوء تحامل ذي ريثة … ويقعد أقعاء غرثان صال\nوما زال ساعده واللبان … على جزر من لحوم الرجال\nألم ينهكم رش شؤبوبه … بوابل ذي برد وانسجال\nويحمكم عن ورود الحمام … وبدلت مما يروق الحسا\nوقود الجياد على أنها … تصاهل تحت القني الطوال\nتوقع يوم الوغى بالنجيع … وتنعل بين الفنا بالقلال\nسبقن العجاجة يحملنها … أراقم لامظة للنزال\nعليهن كل ابن أم الطعان … ن ، أطر القسي وبري النبال\nإذا ريع شمر للمحفظات … وجر ذيول الحديد المذال\nترى كل مشترف للعوار … ضليع الأضالع سامي القذال\nيفوت مقلده والعذار مرمى يد الشيظمي الطوال … يظمي الطوال\nكأن الطريد إلى ظلة … يمد بعلو لفات الجبال\nينال المدى قبل رشح العذار … وما سوط فارسه غير هال\nإذا حركته عروق السياق بين الحضار وبين الثقال … بين الحضار وبين الثقال\nمضى يثب الدو وثب التمام … وينضو المقاديم نضو التوالي\nمددتم بباعي بعد القصور … وألحقتم عطلي بالحوالي\nوأطلعتموني فوق الرجاء … بعيدا ، وفوق منال الليالي\nوأطلقتم الحد من مضربي … وحادثتم قائمي بالصقال\nوأحذيتم قدمي حذوة … من المجد غير جذيم القبال\nرمى الله دولتكم بالثبات … إذا ما رمى غيرها بالزوال\nلياليه صبح من المغبطات … وأيامه من سكون ليالي"},{"id":"diwan-radi:437","bookId":"diwan-radi","type":"poem","seq":437,"chapter":"البحر: طويل","title":"ردي ، يا جيادي ، وأذني برحيل","page":"","text":"ردي ، يا جيادي ، وأذني برحيل … سترعين أرض الحي بعد قليل\nألا إن في قلبي إلى المجد طربة … وعند القنا يوما شفاء غليلي\nإذا ما اتخذت الليل درعا حصينة … فأهون بخطب للزمان جليل\nعلي دماء البدن إن لم أثر بها … رعيلا يشق الأرض بعد رعيل\nفآخذ حقي أو يثور غبارها … من القاع عن أرض بشر مقيل\nوما حاجتي إلا المعالي وقلما … يضيع رجائي ، والطعان رسولي\nوإني لتراك البلاد إذا نبت … علي ، وما ذو نجدة بذليل\nوإني معير ساعدي من أراده … بأبيض طاغي الشفرتين صقيل\nإلى المجد دون الربع رمت عزائمي … وبالعز دون الغيد بان نحولي\nأسوم الهوى نفسا عزوفا عن الهوى … وقلبا لضيم الحب غير قبول\nوأمنع ودي الناس إلى أقله … لأمن من طاغ علي صؤل\nوأعدو من عقلي خبيئا أصونه … وأفدي كثيري منهم بقليل\nوأحطم سري في الضلوع مخافة … ألم يأن يوما أن أذيع دخيلي\nنديمي على شرب الهموم مهند … إذا شاء أصغى الهم دون مقيلي\nوإني آبى أن أذل وفي يدي … عناني ولم يقطع علي سبيلي\nوكل دم عندي ، إذا ما حملته … وإن أثقل الأقوام ، غير ثقيل\nوإن طريقي بالمناسم فاضحي … إذا لم تسر قيه الصبا بذيول\nوكم من حبيب قد سقاني فراقه … وغالطت عنه القلب غير ملول\nوقد نمنم الوسمي بيني وبينه … ووالى بمغبر الرباب هطول\nوإن طراد النفس عما ترومه … أشد عناء من طراد قتيل\nيرجي عداتي كل يوم ، ويتقى … شذاتي وبعضي في الجدال لقيلي\nيقر بعيني أن أروح محسدا … فما حسد الحساد غير نبيل\nوما صافحت يوما يدي يد غادر … ولا ضاق خلقي عن مقام نزيل\nوأول لؤم المرء لؤم أصوله … وأول غدر المرء غدر خليل\nعذولي من أوطى قرا العجز مركبا … ولكن ظهر العزم غير ذلول\nنسيم من الدنيا يطيب لناشق … وأي أوام بعده وغليل\nتفيء الليالي فيئة الظل للفتى … بنعمى وما إنعامها بجزيل\nتداعت لي الأيام حتى رمينني … بما كنت أخشى من لقاء بخيل\nولا بد لي أن أغسل العار بعده … ويا رب عار دام غير غسيل\nيظن الفتى أن التطاول دائم … وكل صعود معقب بنزول\nأأرجو ذباب السيف ثم أخافه … وأرضى بسخط المجد قول عذول\nوبالضرب ما نال ابن موسى مراده … وحل ذرى العلياء أي حلول\nفتى سوم الآراء مبرمة القوى … ولا رأي إلا الرأي غير سحيل\nتعلم من آبائه وثباتهم … على المجد من عليا قنا ونصول\nوما ضره لو كان كل قبيلة … تطالبه يوم الوغى بدخول\nوقد علم الأعداء أن لا يردهم … بغير زفير خانق وعويل\nإذا طرق الخطب البهيم عياله … وقد مال عنق الرأي كل مميل\nعزيمة لاو مستبد برأيه … وعقل امرء لم يستعن بعقول\nجرور على مر الخدائع ذيله … وأعظم ما يعطى بغير سؤول\nويا رب طاغ من أعاديه طامح … أذال الليالي منه أي مذيل\nأطال عنان الأمن حتى أظله … بأغبر طام من قنا وخيول\nوكم رحم أطت به وهو مغضب … فعاد إلى الإحسان غير مطول\nإذا بعد الأعداء عن سطواته … فلا يأمنوا من بالغ ووصول\nكأني بها بزلاء قد صبحتهم … سميط الذنابى غير ذات حجول\nمذكرة لا تصدم القوم صدمة … فتقلع إلا عن دم وقتيل\nنذار لكم من كيده إن قلبه … ضموم على الأسرار غير مذيل\nورجراجة تلتف أيدي جيادها … وأي ضجاج من وغى وصهيل\nوجرد تمطى في الأعنة شزب … كأن حواميها رقاب وعول\nضوامر من طول الوجيف كأنها … ذوائب نبت طامنت لذبول\nتدافعن في شعواء لا الطود عندها … بعال ولا جلد الربى بحمول\nرعين بها شول الرماح كأنها … غداة الوغى في بارض وجليل\nوكم خاض تأمور الظلام بفتية … يرون وعور الليل مثل سهول\nتنوش أنابيب الرماح وراءهم … كأسد تماشيها جوانب غيل\nسيوف أباء في أكف أبية … وكل طويل في يمين طويل\nتغامر بالآراء قبل جيوشه … وبيض الظبا بيض بغير فلول\nفإن غنم الجيش المغير وراءه … فما غنمه في الحرب غير غلول\nلك الله هذا العيد يحدو طليعة … كغائب عز مؤذن بقفول\nولو لم يكن في عيدنا غير أنه … دليل على السراء أي دليل\nوما زاحم الأيام إلا تطلعا … إليك بيوم في العيون جميل\nومد سماء من علائك ملؤها … نجوم من الاقبال غير أفول\nفنل ما أنال الدهر سعدا وغبطة … فرب زمان حل غير منيل\nبقيت الليالي ما سلبن وهل فتى … يطالب أمرا أن مضى بكفيل\nبقيت وأفنيت الأعادي فإنه … شفاء جوى بين الضلوع دخيل\nوهون تقديم العدو بغصة … ولوج الردى في أسرتي وقبيلي\nولي في عدوي إن مشى الموت نحوه … عزاء إذا أودى الردى بخليل\nعلى أنه ما أخطأتني منية … إذا هي غالت من أود بغول\nولي غرض أن لا تزال قصيدة … تجمجم يوما عن مناي وسولي\nكلام كنظم الدر غير مناهب … وقول كصدر العضب غير مقول\nولست بداع بعد هذه فوقها … ولا مثلها من موجز ومطيل"},{"id":"diwan-radi:438","bookId":"diwan-radi","type":"poem","seq":438,"chapter":"البحر: كامل تام","title":"ما أبيض من لون العوارض أفضل","page":"","text":"ما أبيض من لون العوارض أفضل … وهوى الفتى ذاك البياض الأول\nمثلان : ذا حرب الملام وذا له … سبب يعاون من يلوم ويعذل\nأرنو إلى يقق المشيب فلا أرى … إلا قواضب للرقاب تسلل\nواللمة البيضاء أهون حادث … في الدهر لو أن الردى لا يعجل\nولقد حملت شبابها ومشيبها … فإذا المشيب على الذوائب أثقل\nإني غررت من الهوى فشربته … لم أدر أن عقيب شربي حنظل\nوعلمت أن وراي أطول سكرة … مما أعل من الغرام وأنهل\nعجبا لمن يلقى الهوى بفؤاده … عجلان وهو من التجلد أعزل\nإن لا يعرض للذوابل قلبه … إن الطعان من البلابل أسهل\nالآن جللني الوقار رداءه … وانجاب عن عيني ذاك الغيطل\nونزعت وجدا كان يشمخ كلما … أغرى الملام به ولج العذل\nأنا من علمت وليس يطفئ سطوتي … غلواء من يطغى إلي ويجهل\nيغطى العدو إذا طلعت وقلبه … يغلى عليه من الضغائن مرجل\nويزيغني عما أجن مخاتلا … والأورق العادي لا يتزلزل\nأجلو عليه ناجذي ، ولو اجتلى … ما بين أضلاعي لبات يقلقل\nفعلام أزجر بالوعيد وأجتري … وإلام أطلب بالدخول وأمطل\nمالي قنعت كان ليس مهندي … بيدي ولا جدي النبي المرسل\nفلأخذن من الزمان غلبة … حقي ، وأمنع ما أشاء وأبذل\nولأدخلن على النساء خدورها … واليوم ليل بالعجاجة أليل\nمتضايق يدعو القريب ضجاجه … أبدا ويلمع بالبعيد القسطل\nوعلي أن يطأ العراق وأهلها … يوم أغر من الدماء محجل\nيوم تزل به القلوب من الردى … جزعا وأحرى أن تزل الأرجل\nوعجاجة تلقى السماء بمثلها … عظما ، كما مد الغمام المثقل\nلو شام موسى كفه في ليلها … خفي البياض على الذي يتأمل\nطلب العلى والجد فيه من العلى … وإلى المرام نأى وطال تغلغل\nفاعزم ، فليس عليك إلا عزمة … والعجز عنوان لمن يتوكل\nأو حمل اللوم القضاء فإنه … عود لأثقال الملام مذلل\nويجير من عوراء همك سابح … أو صارم ، أو ذابل ، أو مقول\nلا تحدثن طمعا وجدك مدبر … واطلب مدى الدنيا وجدك مقبل\nواعقل رجاءك بالحسين ، فإنه … حرم يذم من الزمان ومعقل\nجذلان تقطر نعمة أيامه … للطالبين ، فراغب ومؤمل\nماضي المقال يكاد من تطبيقه … يوم الجدال ، يئن منه المفصل\nغير المعاجل بالعقاب إذا هفا … جرم ويسبق بالعطاء ويعجل\nضرغام هيجاء كفاه بأنه … عند القواضب والقنا بي مشبل\nنستعطف الأمر المولى بأسمه … فيعود أو ندعوا العلاء فيقبل\nولرب يوم قد ملأت فروجه … خيلا ، تدرع بالغبار وترقل\nوفوارسا يتزاحمون على الردى … نهلا وقد عز البرود السلسل\nمن كل أروع ماجد في كفه … قلق هتوف بالمنون ومعول\nضربا كأشداق الهجان رواغيا … ووغى كما اضطرم الأباء المشعل\nوعيون طعن كالعيون يمدها … ماء مذانبه العروق الذبل\nمن كل شوهاء الضلوع مثيرها … متعوذ والناظر المتأمل\nشهاقة تدق النجيع ، وتنطوي … فيها المسائل أو تضل الأنمل\nينزو لها علق تمطق خلفه … أو عاند يلقى النواظر شلشل\nولديك أن طمح العدو صوارم … تدمي عرانين العدا وتذلل\nكالنار ما يسألن غير ضريبة … والسيف أعلى من يجود ويسأل\nيستبهم الأمر الفظيع ، فلا ترى … إلا القواضب مطلعا يتقبل\nما بين من يخشى المنية ، والذي … يصلي بها في العمر إلا منزل\nلا تنظر الباغي لقربى ، وارمه … بالذل ، واقطع ما عليه يعول\nهذا الأمين أدال منه شقيقه … ومضى عقيرا بابنه المتوكل\nوالعفو مكرمة فإن أغرى بها … متغافل قال الرجال مغفل\nولقد حضرت وأنت غائب نكبة … فخلاك ما قال العدا وتقولوا\nلا يغررنك أنهم بسهامهم … أشووا ، وما بلغوا مدى ما أملوا\nهيهات لم يرم العدو بسهمه … وإن انزوى إلا ليدمى المقتل\nوأنا المضارب عن علاك بمقول … ماضي الغرار ولا الجراز المصقل\nيدمي الجوارح وهو ساكن غمده … ولقلما يمضي بغمد منصل\nهيهات يلحق بالصميم مدرع … أبدا ويزري بالبحار الجدول\nما صارم كدر الذباب كصارم … خلع الجلاء على ظباه الصيقل\nوسماؤنا الظلماء يكتم شخصها … أنى أضاء العارض المتهلل\nليس التفرد بالعلاء طماعة … إن العلى درج لمن يتوقل\nنظم ونثر قد طمحت إليهما … صعدا ويعنو للأخير الأول\nوحديث فضلي ضارب بعروقه … في الأرض ينقله المطي البزل\nلولاك ما سمحت بقول همتي … قدري أجل من القريض وأفضل\nهذا ، وفي بعض الذي امتلأت به … عني البلاد لقائل متعلل\nلما نظرت إلى علاك غريبة … ومضيع راعي المناقب مهمل\nأحرزتها متوغلا غاياتها … والمجد ملء يد الذي يتوغل\nفي سيرة غراء تستضوى بها الدنيا ويلبسها الزمان الأطول … دنيا ، ويلبسها الزمان الأطول\nملئت بفضلك ، فالولي مكثر … ما شاع عنها والعدو مقلل\nيفتن فيها القائلون كأنما … طلعت كما طلع الكتاب المنزل\nهنأت جدك بالتحلق في العلى … ولأنت نعم المقبل المتقبل\nوطرحت تهنئة بأيام أرى … فيها سواء من يقل وينبل\nوأرى لحاظ الحاسدين مريبة … والغيظ بين ضلوعهم يتغلغل\nما للزمان يعقني بعصابة … تجفو علي من الزمان وتثقل\nيذوي على قدم الليالي عهدها … مثل الأديم على التقادم ينغل\nود الحليم شفاء دائك كله … وصداقة السفهاء داء معضل"},{"id":"diwan-radi:439","bookId":"diwan-radi","type":"poem","seq":439,"chapter":"البحر: طويل","title":"إلى الله إني للعظيم حمول","page":"","text":"إلى الله إني للعظيم حمول … كثير بنفسي ، والعديل قليل\nومن طعمه من سيفه كيف يتقي … ومن يطلب العلياء كيف يقيل\nيقولون : خالل في البلاد ، وإنما … خليلي من لا يطبيه خليل\nوليس طباع الناس وفقا وربما … تفاضل فيهم أنفس وعقول\nولولا نفوس في الأقل عزيزة … لغطى جميع العالمين خمول\nفما تطلب الأيام من متغرب … له كل يوم رحلة ونزول\nرمى مقتل الدنيا بسهم قناعة … فعز لأن غال الرمية غول\nإلا إنما الدنيا إذا ما نظرتها … بقلبك ، أم للبنين ثكول\nوما يثقل الميت الصعيد ، وإنما … على الحي عبء للزمان ثقيل\nوتختلف الأيام حتى ترى العلى … عناء ويغدو ما يروق يهول\nأقول لغر بالمنايا ودونه … لهن خيول جمة وحبول\nستعطى يد العاني إذا ما دنا لها … بغير وغى قرن ألد صؤول\nفلا تعتصم بالبعد عنها ، فإنها … مسرة نقي في العظام دمول\nأرى شيبة في العارضين فيلتوي … بقلبي حداها جوى وغليل\nومن عجب غضي عن الشيب جازعا … وكري إذا لاقى الرعيل رعيل\nولي نفس يطغى إذا ما رددته … فيعرقني عرق المدى ، ويغول\nوما تسع الأضلاع ريعان زفرة … يكاد لها قلب الجليد يزول\nوما ذاك من وجد خلا أن همة … عنائي بها في الواجدين طويل\nبكيت وكان الدمع شيبا مبيضا … عذاري ، لا جاري الغروب هطول\nوشوكة ضغن ما انتقشت شباتها … ذهابا بنفسي أن يقال عجول\nوإني إن أعط المدى متنفسا … نزعت أذاها ، والزمان يديل\nوما أنا إلا الليث لو تعلمونه … وذا الشعر البادي علي قبيل\nوقد عصبت مني الليالي بساعد … تئن الأعادي مرة وتنيل\nإذا سطرت نهرا وراء بيوتها … سطوت وما يعدى علي قبيل\nوزور المآقي من جديل وشدقم … تبلد عنها شدقم وجديل\nشققنا بها قلب الظلام وفوقها … رجال كأطراف الذوابل ميل\nوهبت لأصحابي شمال لطيفة … قريبة عهد بالحبيب بليل\nترانا إذا أنفاسنا مزجت بها … نرنح في أكوارنا ونميل\nولم أر نشوى للشمال عشية … كأن الذي غال الرؤوس شمول\nوبرق يعاطينا الجوى غير أنه … به من عيون الناظرين نحول\nوليل مريض النجم من صحة الدجى … نضونا ولألاء النصول دليل\nوأخضر مستور التراب بروضة … رعينا وقد لبى الرغاء صهيل\nوعدنا بها والليل ينفض طله … سقاط اللآلي والنسيم عليل\nإذا استوحشت آذانها من تنوفة … وحمحم وخد دائب وذميل\nرمت بأناسي الحداق وراعها … أبارق يعرضن الردى وهجول\nولولا رجاء منك رقابها … لما آب إلا ضالع وكليل\nودون رواق المجد منك ممنع … جزيل المعالي والعطاء جزيل\nمرير القوى لا يرأم الضيم أنفه … وأيدي العدا لا عليه نصول\nينهنه بالأعداء وهو مصمم … ويزجر بالعذال ، وهو منيل\nفتى لا يرى الإحسان عبأ يجره … ولكنه لولا الآباء ذلول\nأقر بحق المجد ، وهو مضيع … وعظم قدر الدين وهو ضئيل\nسرى طالبا ما يطلب الناس غيره … وما كل قرن في الرجال رجيل\nفما آب حتى استفرغ المجد كله … شروب على غيظ العدو أكول\nأيرجى مداه بعد ما ضحكت به … أمام المعالي ، غرة وحجول ؟\nأرى كل حي من فضالات سيفه … وها هوذا طاغي الغرار صقيل\nوكم غمرة يعلو الملجم ماؤها … شققت ولو أن الدماء تسيل\nوهول يغيظ الحاسدين ركبته … وحيد العلى ، والهائبون نزول\nبطعنة مياس إلى الموت رمحه … يروم العلى من غاية فيطول\nفداك رجال للمنى في ديارهم … نحيب ، وللظن الجميل عويل\nفواغر عمر الدهر لم يطعموا العلى … إلا قل ما يعطى العلاء بخيل\nأرادوك بالأمر الجليل وإنما … يصادم بالأمر الجليل جليل\nأألآن إن ألقيت ثني زمامها … وعطل أغراض لها وجديل\nوإلا ليال أنت راكب ظهرها … وأمر العلى جمعا إليك يؤل\nوطاغ وعاء الشربين ضلوعه … وداء من الغل القديم دخيل\nرماك وبين العين والعين حاجز … وقال وراء الغيب فيك وقيل\nفما زلت تستوفي مراميه ، والقوى … تقطع ، والإقبال عنه يميل\nإلى أن أطعت الله ثم رميته … فلم تغض إلا والرمي قتيل\nكذلك أعداء الرجال وهذه … لسائر من يطغى عليك سبيل\nوتسمو سمو النار عزا وهمة … ويهوي هوي الأرض ، وهو ذليل\nهنيئا لك العيد الجديد فإنه … بيمنك وضاح الجبين جميل\nولا زالت الأعياد هطلى رخية … يحييك منها زائر ونزيل\nوساق عداك العاصفات وأقبلت … عليك شمال لدنة وقبول\nوقد تعقم الأفهام عن قول قائل … فيوجز بعض القول وهو مطيل\nوما الفضل إلا ما أقول فراعة … وباقي مقامات الأنام فضول"},{"id":"diwan-radi:440","bookId":"diwan-radi","type":"poem","seq":440,"chapter":"البحر: كامل تام","title":"من لي برعبلة من البزل","page":"","text":"من لي برعبلة من البزل … ترمي إليك معاقد الرحل\nعجلى الرواح كأنما لمحت … فيكم غدير الجود من قبلي\nنغرتها ، والبدر مطلع … حتى استجاب لقائد الأفل\nكتبت سطورا من مناسمها … فوق الأباطح والسرى يملي\nإني بها في السير مقترح … عجلا على الإقتاب والجدل\nإن الذي وخدت إليه فتى … يبرا إلى أملي من البخل\nلا تملك العرصات قعدته … وإن استقر ، ففي ذرى الإبل\nلم يستمل بالذل جانبه … مذ شد قبضته على النصل\nتنبيك نفحته إذا فغمت … عن طيب مغرس ذلك الأصل\nولأنت مثل السيف في مضر … عاذت بقائمة من الذل\nوإذا هتفت بهم لنائبة … جذبوا وراءك بالقنا الذبل\nلا يسلمون من اتقى بهم … قرع القنا ومواقع النبل\nعامي وعام المحل في بلد … فاسحب إلي ذؤابة الوبل\nواحصد قواي ، فإنني أبدا … بين القرائن مارج الحبل"},{"id":"diwan-radi:441","bookId":"diwan-radi","type":"poem","seq":441,"chapter":"البحر: طويل","title":"أراقب من طيف الحبيب وصالا","page":"","text":"أراقب من طيف الحبيب وصالا … ويأبى خيال أن يزور خيالا\nوهل أبقت الأشجان إلا ممثلا … تعاوده أيدي الضنا ، ومثالا\nألم بنا ، والليل قد شاب رأسه … وقد ميل الغرب النجوم ومالا\nوإني أهتدي في مدلهم ظلامه … يخوض بحارا ، أو يجوب رمالا\nتأوب من نحو الأحبة طاردا … رقادي ، وما أسدى إلي نوالا\nأوائل مس الغمض أجفان ناظري … كما قارب القوم العطاش صلالا\nوما كان إلا عارضا من طماعة … أزال الكرى عن مقلتي وزالا\nسقى الله أظعانا أجزن على الحمى … خفافا ، كأقواس النصال عجالا\nيغالبن أعناق الربى عجرفية … قراع رجال في اللقاء رجالا\nوجدت اصطباري دونهن سفاهة … وأبصرت رشدي بعدهن ضلالا\nوما ضر من أمسى زمامي بكفه … على النأي لو أرخى لنا وأطالا\nتذكرت أيام القرينة ، والهوى … يجدد أقرانا لنا وحبالا\nمضين بعيش لا يعدن بمثله … وأعقبننا مر الزمان خيالا\nسلي عن فمي فصل الخطاب وعن يدي … رماحا كحيات الرمال طوالا\nوبيضا تروى بالدماء متونها … إذا ما لقين الدارعين نهالا\nفما لي أرضى بالقليل ضراعة … وأوسع دين المشرفي مطالا\nتريد الليالي أن تخف بمقودي … وأي جواد لو أصاب مجالا\nسآخذها إما استلابا وفلتة … وإما طرادا في الوغى وقتالا\nفإن أنا لم أركب إليها مخاطرا … وأعظم قولا دونها وقتالا\nفهذا حسامي لم أرق ذبابه … مضاء ، وهذا ذابلي لم طالا\nوأطلبها بالراقصات ، كأنما … أثور منها ربربا ورئالا\nإذا أسقط السير العنيف نعالها … من الأين أحذتها الدماء نعالا\nوكل غضني ، إذا قلت قد ونى … من الشد جلى في الغبار وجالا\nوأكبر همي أن أولاقي فاضلا … أصادف منه للغليل بلالا\nفدى لأبي الفتح الأفاضل إنه … يبر عليهم ، إن أرم ، وقالا\nإذا جرت الآداب جاء أمامها … قريعا وجاء الطالبون إفالا\nفتى مستعاد القول حسنا ولم يكن … يقول محالا أو يحيل مقالا\nليقري أسماع الرجال فصاحة … ويورد أفهام العقول زلالا\nويجري لنا عذبا نميرا ، وبعضهم … إذا قال ، أجرى للمسامع آلا\nأسفهم إن ميز القوم خلة … وأثقبهم ، يوم الجدال ، نصالا\nوما كان إلا السيف أطلق غربه … وزاد غراري مضربيه صقالا\nولما رأيت الوفر دون محله … جزاء وقد أسدى يدا وأنالا\nبعثت له وفرا من الشعر باقيا … وكنزا من الحمد الجزيل ومالا\nفسم آخرا منه كوسمك أولا … وشن عليه رونقا وجمالا\nومثلك إن أولى الجميل أتمه … وإن بدأ الإحسان زاد ووالى"},{"id":"diwan-radi:442","bookId":"diwan-radi","type":"poem","seq":442,"chapter":"البحر: متقارب تام","title":"أأبقى كذا أبدا مستقلا","page":"","text":"أأبقى كذا أبدا مستقلا … يقلبني الدهر عزا وذلا ؟\nوأقنع بالدون فعل الذليل يخشى الأجل ويرضى الأقلا … ل ، يخشى الأجل ويرضى الأقلا\nوإني رأيت غني الأنام … إذا لم يكن ذا علاء مقلا\nومن دون ضيمي فناء الرماح … وبيض القواضب ذفا وفلا\nفلا زلت كلا على المقربات … إلى أن أنال ذرى المجد كلا\nإذا عز قلبك في دهره … فما عذر وجهك في أن يذلا\nألا فاجهد النفس في نيلها … ولا ترقبن عسى أو لعلا\nوحل حبي العجز عن همة … تؤد الأيانق شدا وحلا\nإلى حيث تومى إليك البنان … وتصبح ثم الأعز المجلا\nقليل المثال وخير البلاد … حمى منزل لا أرى فيه مثلا\nوتعلو المعالي إلى العاجزين … ونحن نرى الذل أعلى وأغلى\nعدتك ، أبا الطيب ، العاديات … \nفلم أر الأك من يصطفى … ثناء ويرعى ذماما وإلا\nوحلت نداي جميع الورى … غداة أعتقدتك عضدا وخلا\nينام عن الخير نوم الضباع … وفي الشر يطلع سمعا أزلا\nطويل اليدين إلى المخزيات … يمد إلى المجد باعا أشلا\nفتى أعلقته عنان الفخار … مكارم جاءت به المجد قبلا\nوأصبح حاسده خابطا … إذا كاد يهدى إلى المجد ضلا\nأشم كعالية السمهري … وهمته منه أغلا وأعلى\nويجمع قلبا جريئا ، ووجها … أتم من البدر نورا وأملا\nمضاء القضيب إذا ما انجلى … وضوء الهلال ، إذا ما تجلى\nوقلب الشجاع حسام فإن … حلا منظرا فحسام محلى\nيغيم يوم الندى المستهل … ويقشع يوم الوغى المصمئلا\nويوسع مادحه بشره … فيوليه أضعاف ما كان أولى\nيشمر للروع عن ساقه … ويسحب للجود ذيلا رفلا\nفيوما يعود بجد علي … ويوما يعود بقدح معلى\nويلقى إليه عظيم الزمان … من المأثرات الأجل الأجلا\nفيمسي لأسرارها حافظا … ويغدو بأعبائها مستقلا\nفدونكها كإضاة الغدير … أو السيف سل أو الروض طلا\nولولاك كانت كأمثالها … تصان عن المدح عزا ونبلا\nفقد كنت حصنت أبكارهن … وعودتهن عن القوم عضلا"},{"id":"diwan-radi:443","bookId":"diwan-radi","type":"poem","seq":443,"chapter":"البحر: رجز تام","title":"أتذكراني طلب الطوائل","page":"","text":"أتذكراني طلب الطوائل … أيقظتما مني غير غافل\nقوما ، فقد مللت من إقامتي … والبيد أولى بين من المعاقل\nشنا بي الغارات كل ليلة … وعوداني طرد الهوامل\nوصيراني سببا إلى العلى … إني عين البطل الحلاحل\nقد حشد الدهر علي كيده … وجاءت الأيام بالزلازل\nومن عجيب ما أرى من صرفه … قد دميت من ناجذي أناملي\nتوكس أحداث الليالي صفقتي … لا در در الدهر من معامل\nلا خطر الجود على بالي ، ولا … سقت يدي يوم الطعان ذابلي\nإن لم أقدها كأضاميم القطا … أو بدد العقارب الشوائل\nطوامح الأبصار يهفو نقعها … على طموح الناظرين بازل\nمستصحبا إلى الوغى فوارسا … يستنزلون الموت بالعوامل\nتحتهم ضوامر كأنها … أجادل تنهض بالأجادل\nغر إذا سدت ثنيات الدجى … طلعنها بالغرر السوائل\nوذي حجول نافض سبيبه … عجبا ، على مثل المهاة الخاذل\nينقض لا تلحق من غباره … إلا بقايا فلق الجراول\nيكرع في غرته من طولها … ويتقي الجندل بالجنادل\nبمثله أبغي العلى ، وأغتدى … أول نزال إلى النوازل\nوذي فلول مرهف ، نجاده … على لموع ذات ذيل ذائل\nإن أمير المؤمنين والدي … حز الرقاب بالقضاء الفاصل\nوجدي النبي في آبائه … علا ذرى العلياء والكواهل\nفمن كأجدادي إذا نسبتني … أم من كأحيائي أو قبائلي\nمن هاشم أكرم من حج ، ومن … جلل بيت الله بالوصائل\nقوم لأيديهم على كل يد … فضل سجال من ردى ونائل\nفوارس الغارات لا يطربهم … إلا نوازي نغم الصواهل\nبالسمر تختب ثعيلباتها … مثل ذئاب الردهة العواسل\nوالبيض قد طلعن من أغمادها … للروع تعلو قمم القبائل\nيخضبن إما من دماء مارق … أو من دماء العوذ والمطافل\nذوو القباب الحمر ينضى سجفها … عن عدد من سامر وجامل\nأرى ملوكا كالبهام غفلة … في مثل طيش النعم الجوافل\nأولى من الذود ، إذا جربتهم … برعي ذي الرياض والخمائل\nإن أنا أعطيتهم مقادتي … فلم إذا أطلق غربي صاقلي\nومقولي كالسيف يحتمي به … أشوس أباء على المقاول\nما لك ترضى أن يقال شاعر ؟ … بعدا لها من عدد الفضائل\nكفاك ما أورق من أغصانه … وطال من أعلامه الأطاول\nفكم تكون ناظما وقائلا … وأنت غب القول غير فاعل\nكم يقتضيني السيف عزمي ويدي … تدفعه دفع الغريم الماطل\nأأرهب القتل حذار ميتة … لا بد ألقاها بغير قاتل\nقد غار قبلي الرمح في عنيبة … تحت العوالي ، وكليب وائل\nهبني شبيبا يوم طاحت عنقه … عن حد مفتوق الغرار قاصل\nلما رأي الموت أو الذل انبرى … إلى الردى مشمر الذلاذل\nأو مصعبا لما دنا ميقاته … وضرب المقدار بالحبائل\nحمى يمين الضيم إن يقوده … وانقاد في حبل الردى المعاجل\nفعل امرء رأي الخمول ذلة … فاختار أن يقبر غير خامل\nإن كان لا بد من الموت فمت … تحت ظلال الأسل الذوابل"},{"id":"diwan-radi:444","bookId":"diwan-radi","type":"poem","seq":444,"chapter":"البحر: وافر تام","title":"لمن دمن بذي سلم وضال","page":"","text":"لمن دمن بذي سلم وضال … بلين ، وكيف بالدمن البوالي ؟\nوقفت بهن لا أصغي لداع … ولا أرجو جوابا عن سؤالي\nأيا دار الألى درجت عليها … حوايا المزن والحجج الخوالي\nفأي حيا بأرضك للغوادي … وأي بلى بربعك لليالي\nوبين ذوائب العقدات ظبي … قصير الخطوفي المرط المذال\nربيب إن أريغ إلى حديث … نوار أن أريد إلى وصال\nفهل لي والمطامع مرديات … دنو من لمى ذاك الغزال ؟\nلقد سلبت ظباء الدار لبي … إلا ما للظباء بها ومالي\nتنغصني بأيام التلاقي … معاجلتي بأيام الزيال\nتحيفني الصدود وكنت دهرا … اروع بالصدود فلا أبالي\nوكيف أفيق لا جسدي بناء … عن البلوى ، ولا قلبي بسالي\nيرنحني إليك الشوق حتى … أميل من اليمين إلى الشمال\nكما مال المعاقر عاودته … حميا الكأس حالا بعد حال\nويأخذني لذكركم ارتياح … كما نشط الأسير من العقال\nوأيسر ما ألاقي أن هما … يغصصني بذا الماء الزلال\nفلولا الشوق ما كثر التفاتي … ولا زمت إلى طلل جمالي\nوإني لا أوامق ثم إني … إذا وامقت يوما لا أقالي\nأنا ابن الفرع من أعلى نزار … ومن يزن الأسافل بالأعالي\nنماني كل ممتعض أبي … جرى طلق الجموح إلى المعالي\nمن القوم الألى ملكوا رقاب الأ … الأواخر واختلوا قمم الأوالي\nإذا بسطوا الخطا سحبوا رقاق … البرود على الرقاق من النعال\nوإن قسمت بيوت المجد حازوا … فناء البيت ذي العمد الطوال\nوإنهم لأعنف بالمذاكي … محاضرة وأقرع بالعوالي\nافظ من الأسود فإن أنالوا … رأيت أرق من بيض الحجال\nيخف عليهم بذل الأيادي … وقد أثقلن أعناق الرجال\nبني عمي وعز على يميني … من الضراء ما لقيت شمالي\nأعود على عقوقكم بحلمي … إذا خطر العقوق لكم ببالي\nأروني من يقوم لكم مقامي … أروني من يقول لكم مقالي\nومن يحمي الحريم من الأعادي … ومن يشفني من الداء العضال\nيشايح دونكم يوم المنايا … ويرمي عنكم يوم النضال\nسأبلغ بالقلى والبعد عنكم … مبالغ ليس تبلغ بالألال\nفمن لا يستقيم على التصافي … جدير أن يقوم بالتقالي\nوأحسب أن سينفعني انتصاري … إذا ما عاد بالضرر احتمالي\nأكيدا بعد أن رفعت منارى … وأرست في مقاعدها جبالي\nوشد المجد أطنابي إليه … ومد على جوانبه حبالي\nوتم علاؤكم بي بعد نقص … تمام الحضرمية بالقبال\nوما فضلي على قومي بخاف … كما فضل القريع على الأفال\nوإني إن لحقت أبي جلالا … فهذي النار من ذاك الذبال\nوأين القطر إلا للغوادي … وأين النور إلا للهلال\nأصون عن الرجال فضول قولي … وأبذل للرجال فضول مالي\nورب قوارص نكتت جناني … أشد علي من صرد النبال\nصبرت لها ، ولم أردد مقالا … فكان جزاء قائلها فعالي\nوجاذبني على العلياء قوم … وما علموا بأن جميعها لي\nلئن نلت الكواكب في علاها … لقد أبقيت فضلا من منالي\nحلفت بها كراكعة الحنايا … خوابط للجنادل والرمال\nمهدمة العرائك من وجاها … تعاض من الغوارب بالرحال\nإلى البلد الحرام معرضات … لإجراء الطلى بدم حلال\nليعتسفن هذا الليل مني … أشيعث ، عاب لمته الغوالي\nخفيف الحاذ يشغله سراه … زمانا ، أن يفكر في الهزال\nوممترق إلى العلياء حتى … يجاوز مد غاية كل عال\nفإن أنا لم أقم فيها فقامت … على قبري النوادب بالمآل"},{"id":"diwan-radi:445","bookId":"diwan-radi","type":"poem","seq":445,"chapter":"البحر: بسيط تام","title":"حب العلى شغل قلب ما له شغل","page":"","text":"حب العلى شغل قلب ما له شغل … وآفة الصب فيه اللوم والعذل\nقالت ضنيت ، فقلت الشوق يجمعنا … ويعرق الوجد ما لا تعرق العلل\nوإن تحون جسمي ما علمت به … فالرمح ينآد طورا ثم يعتدل\nكيف التخلص من عين لها علق … بالظاعنين ومن قلب به خبل\nومن لوجدي أن يقتادني طمع … إلى الحبيب ، وأن يعتاقني طلل\nلا تبعدن مطايانا التي حملت … تلك الظعائن مرخاة لها الجدل\nسير الدموع على آثارها عنق … وسيرها الوخد والتبغيل والرمل\nدون القباب عفاف في جلاببها … والصون يحفظ ما لا تحفظ الكلل\nفلا الحدوج يرى وجه المقيم بها … ولا تحس بصوت الظاعن الإبل\nوفي البراقع غزلان مرببة … يرميننا بعيون نبلها الكحل\nإذا الحسان حملن الحلي أسلحة … فإنما حليها الأجياد والمقل\nألا وصال سوى طيف يؤرقني … ولا رسائل إلا البيض والأسل\nوعادة الشوق عنددي غير غافلة … قلب مروع ودمع واكف هطل\nوللأسنة فيهم أعين نجل … ولا عناق ، ولا ضم ، ولا قبل\nلا ناصر غير دمعي أن هم ظلموا … والدمع عون لمن ضاقت به الحيل\nوالعذل أثقل محمول على أذن … وهو الخفيف على العذال إن عذلوا\nمن لي ببارق وعد خلفه مطر … وكيف لي بعتاب بعده خجل\nالنفس أدنى عدو أنت حاذره … والقلب أعظم ما يبلى به الرجل\nوالحب ما خلصت منها لذاذته … لا ما تكدره الأوجاع والعلل\nقد عود النوم عيني أن تفارقه … وهون السير عندي الأينق الذلل\nفما تشبث بي دار ، ولا بلد … أنا الحسام وما تحظى به الخلل\nالليل أحمل ظهر أنت راكبه … إن الصباح لطرف والدجا جمل\nولى الشباب وهذا الشيب يطرده … يفدي الطريدة ذاك الطارد العجل\nما نازل الشيب في راسي بمرتحل … عني ، وأعلم أني عنه مرتحل\nمن لم يعظه بياض الشعر أدركه … في غرة حتفه المقدور والأجل\nمن أخطأته سهام الموت قيده … طول السنين فلا لهو ولا جذل\nوضاق من نفسه ما كان متسعا … حتى الرجاء ، وحتى العزم والأمل\nما عفتي في الهوى يوما بمانعتي … أن لا تعف بكفي القنا الذبل\nوللرجال أحاديث ، فأحسنها … ما نمق الجود لا ما نمق البخل\nولا اقتحامي على الغارات يعصمني … من المنون ، ولا ريث ، ولا عجل\nوميتتي في النوى والقرب واحدة … إذا تكافأت الغايات والسبل\nيستشعر الطرف زهوا يوم أركبه … كأنه بنجوم الليل منتعل\nوالخيل عالمة ما فوق أظهرها … من الرجال جبان كان أو بطل\nأغر أدهم صبغ الليل صبغته … تضل في خلقه الألحاظ والمقل\nمناقل في عنان الريح جريته … كأنه قبس أو بارق عمل\nقصير ما بين أولاه وآخره … كأنما العنق معقود بها الكفل\nإذا الربيع كسا البيداء بردته … ضاقت ركابي وهاد الأرض والقلل\nوالواردات مياه القاع سانحة … على جوانبها الحوذان والنفل\nوكالثغور أقاحيها ، إذا غربت … شمس النهار والقت صبغها الأصل\nورد ومرعى إذا شاءت مشافرها … مستجمعان ولا كد ولا عمل\nوغافلين عن العلياء قائدهم … في كل غي فتي العقل مكتهل\nشنوا الخضاب حذارا أن يطالبهم … بحلمه الشيب أو يقصيهم الغزل\nعارين إلا من الفحشاء يسترهم … ثوب الخمول وتنبو عنهم الحلل\nقوم بأسماعهم عن منطقي صمم … وفي لواحظهم عن منظري قبل\nيبددون إذا أقبلت لحظهم … شرب المروع لا عل ، ولا نهل\nيبدون ودي ويحموني ثراءهم … لو كان حقا تساوت بيننا الدول\nكفى حسودي كبتا أنه رجل … أغرى به الهم مذ أغرى بي الجذل\nما بال شعري ملوما لا يجانبه … عن كل ما يقتضيه القول والعمل\nلا حاجة بي إلى مال يعبدني … له الرجاء ، ويضنيني به الشغل\nحسبي غنى نفسي الباقي وكل غنى … من المغانم والأموال ينتقل\nتغير الناس في سمع وفي نظر … واستحسن الغدر حتى استقبح الخلل\nفما طلابك إنسانا تصاحبه … كل الأنام كما لا تشتهى همل\nيستبشرون ، إذا صحت جسومهم … وبالعقول إذا فتشتها علل\nما هيجتني العدا ، إلا وكنت لها … سماء كل جواد أرضه القلل\nيمشي الحسام بكفي في رؤوسهم … ويخرق الرمح ما تعيا به الفتل\nقومي هم الناس لا جيل سواسية … الجود عندهم عار إذا سئلوا\nأبي الوصي وأمي خير والدة … بنت الرسول الذي ما بعده رسل\nوأين قوم كقومي إن سألتهم … سوابق الخيل في يوم الوغى نزلوا\nكالصخر إن حلموا والنار إن غضبوا … والأسد إن ركبوا والوبل إن بذلوا\nالطاعنين من الجبار مقتله … والضاربين ، وذيل النقع منسدل\nوالراكبين المطايا والجياد معا … لا الشكل تحسبها يوما ولا العقل\nتغضي عيون الأعادي عن رماحهم … وللأسنة فيهم يمضي به الأجل\nوالله أكرم مولى أنت آمله … يوما وأعظم من يعطى ومن يسل\nعفو ، وحلم ، ونعماء ، ومقدرة … ومستجيب ومعطاء ومحتمل\nوكيف نأمل أن تبقى الحياة لنا … وغير راجعة أيامنا الأول"},{"id":"diwan-radi:446","bookId":"diwan-radi","type":"poem","seq":446,"chapter":"البحر: كامل تام","title":"قلق العدو ، وقد حظيت برتبة","page":"","text":"قلق العدو ، وقد حظيت برتبة … تعلو عن النظراء والأمثال\nلو كنت أقنع بالنقابة وحدها … لغضضت حين بلغتها آمالي\nلكن لي نفس تتوق إلى التي … ما بعد أعلاها مقام عال\nقالوا حجرت على نداك وطالما … أرغمت فيه معاطس العذال\nهيهات قل الحامدون وصار من … أحبوه يحسدني على أموالي\nمن لي بمن تزكو الصنائع عنده … حتى أشاطره كرائم مالي"},{"id":"diwan-radi:447","bookId":"diwan-radi","type":"poem","seq":447,"chapter":"البحر: طويل","title":"أمل من مثانيها ، فهذا مقيلها","page":"","text":"أمل من مثانيها ، فهذا مقيلها … وهذي مغاني دارهم وطلولها\nحرام على عيني تجاوز أرضها … ولم يرو أظماء الديار همولها\nوقد خالطت ذاك الثرى نفحاتها … وجرت على ذاك الصعيد ذيولها\nحفوف رمال ما يخاف انهيالها … وأغصان بان ما يخاف ذبولها\nوثم جياد ما يفل رعيلها … فأعذرها فيمن يحب عذولها\nرضينا ولم نسمح من النيل بالرضا … ولكن كثير لو علمنا قليلها\nشموس قباب قد رأينا شروقها … فيا ليت شعري أين منا أفولها\nتعالين عن بطن العقيق تيامنا … يقومها قصد السرى ويميلها\nفهل من معيري نظرة فأريكها … شريقي نجد يوم زالت حمولها\nكطامية التيار يجري سفينها … \nولم تر إلا ممسكا بيمينه … رواجف صدر ما يبل غليلها\nومختنقا من عبرة ما تزوله … ومختبطا في لوعة ما يزولها\nمحا بعدكم تلك العيون بكاؤها … وغال بكم تلك الأضالع غولها\nفمن ناظر لم تبق إلا دموعه … ومن مهجة لم يبق إلا غليلها\nدعوا لي قلبا بالغرام أذيبه … عليكم ، وعينا في الطلول أجيلها\nسقاها الرباب الجون كل غمامة … يهش لها حزن الملا وسهولها\nإذا ملكت ريح الجنوب عنانها … أحالت عليها بعد لأي قبولها\nوساق إليها مثقلات عشاره … ضوامر ترغو بالضريب فحولها\nنجائب لا يؤدي بإخفافها السرى … وإن طال بالبيد القواء ذميلها\nفكم نفحة من أرضها بردت حشى … وبل غليلا من فؤاد بليلها\nتخطى الرياح الهوج أعناق رملها … فتجبرها جبر القرا ، وتهيلها\nمنازل لا يعطي القياد مقيمها … مغالبة ، ولا يهان نزيلها\nخليلي قد خف الهوى وتراجعت … إلى الحلم نفس لا يعز مذيلها\nفلست ابن أم الخيل أن لم أمل بها … عوابس في دار العدو أبيلها\nإذا انجفلت من غمرة ثاب كرها … وعاد إلى مر المنايا جفولها\nيزعفر من عض الشكيم لعابها … ويرعد من قرع العوالي خصيلها\nوأعطف عن خوض الدماء رؤوسها … فقد فقدت أوضاحها وحجولها\n … إلى كل بيداء يرم دليلها\nتوقر من عنف السياط مراحها … وغاض على طول القياد صهيلها\nونحن القروم الصيدان جاش بأسها … تنودر مرعى ذودها ومقيلها\nبأيماننا بيض الغروب خفائف … نغول بها هام المعدا وتغولها\nتفللن حتى كاد من طول وقعها … بيوم الوغى يقضي عليها فلولها\nقوائم قد جربن كل مجرب … بضرب الطلى حتى تفانت نصولها\nوأودية بين العراق وحاجر … ببيض المواضي والعوالي نسيلها\nيمد بدفاع الدماء غثاؤها … ويجري بأعناق الرجال حميلها\nإذا هاشم العلياء عب عبابها … وسالت بأطناب البيوت سيولها\nمدفعة تحت الرحال ركابها … محفزة تحت اللبود خيولها\nوكل مثنات النسوع مطارة … سواء عليها حلها ورحيلها\nكأن على متن الظليم قتودها … وفي يد علوي الرياح جديلها\nرأيت المساعي كلها وتلاحقت … فروع العلى مجموعة وأصولها\nإذا استبقت يوما تراخى تبيعها … وخلى لها الشأو البعيد رسيلها\nوإما أمالت للطعان رماحها … وشن عليها للقاء شليلها\nفثم عوال ما ترد صدورها … وثم جياد ما يغل رعيلها\nوثم الحماة الذائدون عن الحمى … عشية لا يحمي النساء بعولها\nأبي ما أبي لا تدعون نظيره … رديف العلى من قبلكم وزميلها\nهو الحامل الأعباء كل مطيقها … وعج عجيج الموقرات حمولها\nطويل نجاد يحتبي في عصابة … فيفرعها مستعليا ، ويطولها\nإذا صال قلنا : أجمع الليث وثبة … وإن جاد قلنا : مد من مصر نيلها\nحليم إذا التفت عليه عشيرة … تطاطا له شبانها وكهولها\nوإن نعرة يوما أمالت رؤوسها … أقام على نهج الهدى يستميلها\nوانظرها حتى تعود حلومها … وأمهلها حتى تثوب عقولها\nولم يطوها بالحلم فضل زمامها … فتعثر فيه عثرة لا يقيلها\nفعن بأسه المرهوب يرمى عدوها … ومن ماله المبذول يودى قتيلها\nأكابرنا والسابقون إلى العلى … ألا تلك آساد ونحن شبولها\nوإن أسودا كنت شبلا لبعضها … لمحقوقة أن لا يذل قتيلها"},{"id":"diwan-radi:448","bookId":"diwan-radi","type":"poem","seq":448,"chapter":"البحر: خفيف تام","title":"راحل أنت ، والليالي نزول","page":"","text":"راحل أنت ، والليالي نزول … ومضر بك البقاء الطويل\nلا شجاع يبقى فيعتنق ال … بيض ، ولا آمل ، ولا مأمول\nغاية الناس في الزمان فناء … وكذا غاية الغصون الذبول\nإنما المرء للمنية مخبوء … وللطعن تستجم الخيول\nمن مقيل بين الضلوع إلى طو … ل عناء ، وفي التراب مقيل\nفهو كالغيم ألفته جنوب … يوم دجن ومزقته قبول\nعادة للزمان في كل يوم … يتناىء خل وتبكى طلول\nفالليالي عون عليك مع البي … بين كما ساعد الذوابل طول\nربما وافق الفتى من زمان … فرح ، غيره به متبول\nهي دنيا إن واصلت ذا جفت … هذا ملالا كأنها عطبول\nكل باك يبكى عليه وإن … طال بقاء والثاكل المثكول\nوالأماني حسرة وعناء … للذي ظن أنها تعليل\nما يبالي الحمام أين ترقى … بعد ما غالت ابن فاطم غول\nأي يوم أدمى المدامع فيه … حادث رائع وخطب جليل\nيوم عاشوراء الذي لا أعان ال … صحب فيه ولا أجار القبيل\nيا ابن بنت الرسول ضيعت … العهد رجال والحافظون قليل\nما أطاعوا النبي فيك ، وقد ما … لت بأرماحهم إليك الذحول\nوأحالوا على المقادير في حر … بك لو أن عذرهم مقبول\nواستقالوا من بعد ما أجلبوا في … ها أالآن أيها المستقيل\nإن أمرا قنعت من دونه السي … ن ، وولى ، ونحره مبلول\nيا حساما فلت مضاربه الها … م ، وقد فله الحسام الصقيل\nيا جوادا أدمى الجواد من الطع … يوم يبدو طعن وتخفى حجول\nيوم طاحت أيدي السوابق في النق … ع وفاض الونى وغاض الصهيل\nأتراني أعير وجهي صونا … وعلى وجهه تجول الخيول\nأتراني ألذ ماء ، ولما … يرو من مهجة الإمام الغليل\nقبلته الرماح وانتصلت في … ه المنايا ، وعانقته النصول\nوالسبايا على النجائب تستا … وقد نالت الجيوب الذيول\nمن قلوب يدمى بها ناظر الوج … د ومن أدمع مراها الهمول\nقد سلبن القناع عن كل وجه … فيه للصون من قناع بديل\nوتنقبن بالأنامل ، والدم … ع على كل ذي نقاب دليل\nوتشاكين ، والشكاة بكاء … وتنادين ، والنداء عويل\nلا يغب الحادي العنيف ولا … يفتر عن رنة العديل العديل\nيا غريب الديار صبري غريب … وقتيل الأعداء ، نومي قتيل\nبي نزاع يطغى إليك وشوق … وغرام وزفرة وعويل\nليت أني ضجيع قبرك ، أو أ … ن ثراه بمدمعي مطلول\nلا أغب الطفوف في كل يوم … من طراق الأنواء غيث هطول\nمطر ناعم ، وريح شمال … ونسيمن غض وظل ظليل\nيا بني أحمد إلى كم سناني … غائب عن طعانه ممطول\nوجيادي مربوطة ، والمطايا … ومقامي يروع عنه الدخيل\nكم إلى كم تعلو الطغاة ، وكم يح … كم في كل فاضل مفضول\nقد أذاع الغليل قلبي ، ولكن … غير بدع إن استطب العليل\nليت أني أبقى ، فأمترق النا … س وفي الكف صارم مسلول\nواجر القنا لثارات يوم ال … طف يستلحق الرعيل الرعيل\nصبغ القلب حبكم صبغة الشي … وشيبي لولا الردى لا يحول\nأنا مولاكم وإن كنت منكم … والدي حيدر ، وأمي البتول\nوإذا الناس أدركوا غاية الفخر … ر شآهم من قال جدي الرسول\nيفرح الناس بي لأني فضل … والأنام الذي أراه فضول\nفهم بين منشد ما أقفي … هسرورا وسامع ما أقول\nليت شعري من لائمي في مق … ال ترضيه خواطر وعقول\nأترك الشيء عاذري فيه كل … ناس من أجل أن لحاني عذول\nهو سؤلي أن أسعد الله جدي … ومعالي الأمور للذمر سول"},{"id":"diwan-radi:449","bookId":"diwan-radi","type":"poem","seq":449,"chapter":"البحر: طويل","title":"أيرجع ميتا رنة وعويل","page":"","text":"أيرجع ميتا رنة وعويل … ويشفى بإسراب الدموع غليل\nنطيل غراما ، والسلو موافق … ونبدي بكاء والعزاء جميل\nشباب الفتى ليل مضل لطرقه … وشيب الفتى عضب عليه صقيل\nفما لون ذا قبل المشيب بدائم … ولا عصر ذا بعد الشباب طويل\nوحائل لون الشعر في كل لمة … دليل على أن البقاء يحول\nنؤمل أن نروى من العيش والردى … شروب لأعمار الرجال أكول\nوهيهات ما يغنى العزيز تعزز … فيبقى ولا ينجي الذليل خمول\nنقول مقيل في الكرى لجنوبنا … وهل غير أحشاء القبور مقيل\nدع الفكر في حب البقاء وطوله … فهمك لا العمر القصير يطول\nولا ترج أن تعطى من العيش كثرة … فكل مقام في الزمان قليل\nومن نظر الدنيا بعين حقيقة … درى أن ظلا لم يزل سيزول\nتشيع أظعان إلى غير رجعة … وتبكى ديار بعدهم وطلول\nلماذا تربي المرضعات طماعة … لماذا تخلى بالنساء بعول\nأليس إلى الآجال نهوي ، وخلفنا … من الموت حاد لا يغب عجول ؟\nفمحتضر بين الأقارب أو فتى … تشحط ما بين الرماح قتيل\nإذا لم يكن عقل الفتى عون صبره … فليس إلى حسن العزاء سبيل\nوإن جهل الأقدار والدهر عاقل … فأضيع شيء في الرجال عقول\nتغير ألوان الليالي وتنمحي … به غرر معلومة وحجول\nتعز أمين الله واستأنف الأسى … ففي الأجر من عظم المصاب بديل\nوما هذه الأيام إلا فوارس … تطاردنا ، والنائبات خيول\nوإن زال نجم من ذؤابة هاشم … فلا عجب ، إن النجوم تزول\nمضى والذي يبقى أحب إلى العلى … وأهدى إلى المعروف حين ينيل\nبقاءك نهوى وحده دون غيره … فدع كل نفس ما سواك تسيل\nوموت الفتى خير له من حياته … إذا جاور الأيام وهو ذليل\nتلفت إلى آبائك الغر هل ترى … من القوم باق جاوزته حبول\nوهل نال في العيش الفتى فوق عمره … وهل بل من داء الحمام غليل\nومن مات لم يعلم وقد عانق الثرى … بكاه خليل أم سلاه خليل\nفكفكف عنان الوجد ، إما تعزيا … وإما طلابا أن يقال حمول\nفكل ، وإن لم يعجل الموت ، ذاهب … ألا إن أعمار الأنام شكول\nوللحزن ثورات تجور على الفتى … كما صرعت هام الرجال شمول\nلقد كنت أوصى بالبكاء من الجوى … لو أن غراما بالدموع غسيل\nفأما ، ولا وجد يزول بعبرة … فصبر الفتى عند البلاء جميل\nوكم خالط الباكين من سن ضاحك … وبين رغاء الرازحات صهيل\nوإني أراني لا ألين لحادث … له أبدا وطء علي ثقيل\nوأغضي عن الأقدار ، وهي تنوبني … وما نظري عند الأمور كليل\nيهون عندي الصبر ما وقعت به … صروف الليالي والخطوب نزول\nوما أنا بالمغضي على ما يعيبني … ولا أنا عن ود القريب أحول\nولا قائل ما يعلم الله ضده … ولو نال من جلدي قنا ونصول\nولولا أمير المؤمنين تحضرت … بي البيد هوجاء الزمام ذمول\nوطوح بي ، في كل شرق ومغرب … زمان ضنين بالرجاء بخيل\nولكنه أعلى محلي على العدا … وعلم نطقي فيه كيف يقول\nوعودني من جود كفيه عادة … أعوج إليها بالمنى وأميل\nيقولون : لو أملت في الناس غيره … وهل فوقه للسائلين مسول\nومن يك إقبال الخليفة سيفه … يلاق الليالي وهي عنه نكول\nومن كان يرمي عن تقدم باعه … يصب سهمه أغراضه ويؤل\nفتى تبصر العلياء في كل موقف … به الرمح أعمى والحسام ذليل\nويدخل أطراف القنا كل مهجة … بها أبدا غل عليه دخيل\nإذا لاح يوم الروع في سرج سابح … تناذره بعد الرعيل رعيل\nبقيت ، أمير المؤمنين ، فإنما … بقاؤك بالعز المقيم كفيل\nولا ظفرت منك الليالي بفرصة … ولا غال قلبا بين جنبك غول\nوأعطيت ما لم يعط في الملك مالك … فإنك فضل والأنام فضول"},{"id":"diwan-radi:450","bookId":"diwan-radi","type":"poem","seq":450,"chapter":"البحر: مجزوء الكامل","title":"إن كان ذاك الطود خ","page":"","text":"إن كان ذاك الطود خ … ر ، فبعدما استعلى طويلا\nموف على القلل الذوا … ب في العلى عرضا وطولا\nقرم يسدد لحظه … فترى القروم له مثولا\nويرى عزيزا حيث … ل ، ولا يرى إلا ذليلا\nكالليث ، إلا أنه … م تعود بالليان حولا\nوعلا على الأقران لا … مثلا يعد ولا عديلا\nمن معشر ركبوا العلا … وأبوا عن الكرم النزولا\nغر إذا نسبوا لن … ك على العلى جيلا ، فجيلا\nكرموا فروعا بعد ما … طابوا ، وقد عجموا أصولا\nنسب غدا رواده … يستنجبون لنا الفحولا\nيا ناظر الدين الذي … رجع الزمان به كليلا\nيا صارم المجد الذي … ملئت مضاربه فلولا\nيا كوكب الأحساب أعج … جلك الدجى عنا أفولا\nيا غارب النعم العظام … م غدوت معمورا جزيلا\nيا مصعب العلياء قادت … ك العدا نقضا ذلولا\nلهفي على ماض قضى … ألا ترى منه بديلا\nوزوال ملك لم يكن … يوما يقدر أن يزولا\nومنازل سطر الزمان … على معالمها الحؤولا\nمن بعد ما كانت على الأ … يام مربأة زلولا\nوالأسد ترتكز القنا … فيها وترتبط الخيولا\nمن يسبغ النعم الجسام … ويصطفي المجد الجزيلا\nمن ينتج الآمال يو … تعود الليان حولا\nمن يورد السمر الطوال … ويطعم البيض النصولا\nمن يزجر الدهر الغشوم … ويكشف الخطب الجليلا\nوتراه يمنع دوننا … وادي النوائب أن يسيلا\nهذا ، وكم حرب تب … سد سطوتها الغليلا\nصماء تخرس آلها … إلا قراعا ، أو صهيلا\nوالخيل عابسة تج … من العجاج بها ذيولا\nأجتاب عارضها ، وقد … رحل المنون به همولا\nكالثائر الضرغام أن … لبس الوغى دق الرعيلا\nصانعت يوم فراقه … قلبا ، قد اعتنق الغليلا\nظعن الغنى عني وحو … ول رحله إلا قليلا\nإن عاد يوما عاد وج … ه الدهر مقتبلا جميلا\nولئن مضى طوع المنون … مؤمما تلك السبيلا\nفلقد تخلف مجده … عبأ على الدنيا ثقيلا\nواستذرت الأيام من … نفحاته ظلا ظليلا"},{"id":"diwan-radi:451","bookId":"diwan-radi","type":"poem","seq":451,"chapter":"البحر: رمل تام","title":"أي طود دك من أي جبال","page":"","text":"أي طود دك من أي جبال … لقحت أرض به بعد حيال\nما رأى حي نزار قبلها … جبلا سار على أيدي الرجال\nعجبا أصبحت للضيم وما … نثر الطعن أنابيب العوالي\nفإذا رامي المقادير رمى … فدروع المرء أعوان النصال\nقاده المقدار قسرا بعد ما … أكره السمر على المق الطوال\nوأبال الخيل في كل حمى … يمنع الماطر منهل العزالي\nمثل عقبان الموامي دلحا … راشها قرع الحنايا بالنبال\nحاملا عن قومه العبء ، وما … حمدوا عرعرة العود الجلال\nأيها القبر الذي أمسى به … عاطل الأرض جميعا وهو حالي\nلم يواروا بك ميتا إنما … أفرغوا فيك ذنوبا من نوال\nطال ما لاذ به المال كما … لاذت الإصبع يوما بالقبال\nحملوه بازلا محتقرا … دلج الليل ولزات الحبال\nإن غدا مجدوعة إشرافه … فالبنى وافية ، والمجد عالي\nعقروا ليثا ولو هاهوا به … كان بعد العقر أرجى للصيال\nوكذا الأيام من قارعها … تركت فيه علامات النزال\nعقلوه بعدما جاز المدى … وطوى شأو مساع ومعالي\nوكذا السابق يوما بعنان … يحرز السبق ويوما بعقال\nقمت عنها بعد ما عج بها … ورمى أوسقها بزل الجمال\nوانتزعت النصل من مقلتها … بعد غايات نزاع ومطال\nليتهم أعطوك إن لم يعدلوا … بسلة الراقي من الداء العضال\nنتجوا في المجد ما ألقحته … ربما أوقد نارا غير صالي\nوكأني خلل الغيب أرى … نغرة من جرحها بعد اندمال\nوإذا الأعداء عدوك لها … سلموا فضلك من غير جدال\nلا أضاعوا رابئا في قلة … كلأ المجد ، وقد نام الكوالي\nيوم للشعب دهان من دم … والمواضي للمقاديم فوالي\nفي فتو شيعوا أرماحهم … أمم الموت إلى الطعن عجال\nبخفاف فوق أيمان رجال … وثقال فوق أعناق رجال\nقضب ، يوم صداها في الوغى … بالطلى أطول من يوم الصقال\nلك منها ناحل تعصى به … يوم أبدلن عصيا بعوالي\nتلحم الأعداء منها جازرا … ينقل اللحم إلى غير عيال\nقد قدحت العز زندا غير كاب … ولبست المجد بردا غير بالي\nوإذا أغلى الورى أكرومة … وجدوا عندك أثمان الغوالي\nإن للطائع عندي منة … وحمى قد بلها لي ببلالي\nليس ينسيها وإن طال المدى … مر أيام عليها وليالي\nفاتني منك انتصار بيميني … فتلافيت انتصارا بمقالي\nلا عجيب حفظ كف لبنان … ووفاء من يمين لشمال\nعز من أمسى معدا ظهره … أخذا الأهبة يوما للزيال\nينظر الدنيا بعيني ناهض … مطر ينفض أنداء الطلال\nينشط البلغة من آكلها … نشطة المطرود ولى وهو خالي\nلا يرم قبرك مبراق الذرى … منجد الأعناق غوري التوالي\nكلما عج رمى في عرضه … شعل البرق الرباب المتعالي\nكرهاء الدهم لاقيت به … في رعال يتعدى برعال\nتطلق الصرة من أخلافه … أم أوبين : نعامى وشمال\nألحقت شعاعة الريح كما … جرت الخيل رعابيب الحلال\nلا أرى الدمع كفاء للجوى … ليس إن الدمع من بعدك غالي\nوبرغمي أن كسوناك الثرى … وفرشناك زرابي الرمال\nوهجرناك على ضن الهوى … رب هجران على غير تقالي\nأيها الظاعن لا جاز الحيا … أبدا بعد بالحي الحلال\nكنت في الأحجال أرجوك ، ولا … أرتجي اليوم عظيما في الحجال\nكل مأسور يرجى فكه … غير من أصبح في قيد الليالي\nنسب كالشمس أوفيت به … في المعالي بين نجم وهلال\nزلق المرقى بعيد المنتمى … في قنان للمساعي وقلال\nتقصر الألحاظ عنهن فما … ظن من مد يديه للمنال\nفي الروابي من معد والذرى … نهز المجد بعادي السجال\nوإذا ما الأرض كانت شوكة … خطروا فيها على غير نعال\nكل راق مر بالنجم إلى … قنن السؤدد والمجد الطوال\nمعشر إن غابت الأرض بهم … لم يغيبوا عند مجد وفعال\nكلما ازدادت بلى أعظمهم … نشرتهم سمع غير بوالي\nوالعلى ما لم يربوا دارها … طرق عوج ، وأطلال خوالي\nضمنت منهم قراراتهم … عمد المجد ، وأركان المعالي\nلا تقل تلك قبور إنما … هي أصداف على غير لأل"},{"id":"diwan-radi:452","bookId":"diwan-radi","type":"poem","seq":452,"chapter":"البحر: كامل تام","title":"أكذا المنون تقنطر الأبطالا","page":"","text":"أكذا المنون تقنطر الأبطالا … أكذا الزمان يضعضع الأجبالا\nأكذا تصاب الأسد وهي مذلة … تحمي الشبول ، وتمنع الأغيالا\nأكذا تقام عن الفرائس بعد ما … ملأت هماهمها الورى أوجالا\nأكذا تحط الزاهرات عن العلى … من بعدما شأت العيون منالا ؟\nأكذا تكب البزل وهي مصاعب … تطوي البعيد وتحمل الأثقالا\nأكذا تغاض الزاخرات وقد طغت … لجبا وأردت الظماء زلالا\nيا طالب المعروف حلق نجمه … حط الحمول وعطل الأجمالا !\nوأقم على يأس فقد ذهب الذي … كان الأنام على نداه عيالا\nمن كان يقري الجهل علما ثاقبا … والنقص فضلا والرجاء نوالا\nويجبن الشجعان دون لقائه … يوم الوغى ، ويشجع السؤالا\nخلع الردى ذاك الرداء نفاسة … عنا وقلص ذلك السربالا\nخبر تمخض بالأحبة ذكره … قبل اليقين ، وأسلف البلبالا\nحتى إذا جلى الظنون يقينه … صدع القلوب وأسقط الأحمالا\nالشك أبرد للحشا من مثله … يا ليت شكي فيه دام وطالا\nجبل تسنمت البلاد هضابه … وتخرم الأذواء والأقيالا\nيا طود ! كيف وأنت عادي الذرى … ألقى بجانبك الردى زلزالا\nإن قطع الآمال منك ، فإنه … من بعد يومك قطع الأمالا\nما كنت أول كوكب ترك الدنا … وسما إلى نظرائه فتعالى\nأنفا من الدنيا بتت حبالها … ونزعت عنك قميصها الأسمالا\nذا المنزل المظعان قد فارقته … يا شافي الأدواء كيف جهلته\nداء رماك به الزمان عضالا … وصل الدموع ، وقطع الأوصالا\nيا آمر الأقدار كيف أطعتها … أوما وقاك جلالك الآجالا\nكيف اغتفلت ، ففاجأتك بغرة … أو ليس كنت المخلط المزيالا\nلم تكف يا كافي الكفاة منية … وتصوب الوادي إليك ، فسالا\nألا وقى المجد المؤثل ربه … ألا زوى المقدار ، ألا حالا\nألا أقالتك الليالي عثرة … يا من إذا عثر الزمان أقالا\nإن الذي أنجى إليك بسهمه … قدر ينال ذبابه الريبالا\nلا مسمع الإنباض منه ، فيتقى … يوما ولا مالي الجفير نبالا\nوأرى الليالي طارحات حبالها … تستوثق الأعيان والأرذالا\nيبرين عود النبع غير فوارق … بين النبات كما برين الضالا\nلا تأمن الدنيا عليك فإنها … ذات البعول تبدل الأبدالا\nوتناذر الدهر الذي شرع الردى … وتخرم الأذواد والأقيالا\nواسترجع الأملاك قسرا بعد ما … ركبوا من الشرف المطل جبالا\nوطوى مقاول من نزار ذادة … في الحرب لا كشفا ولا أميالا\nقوم ، إذا وقع الصريخ تناهضوا … بالخيل قبا والقني طوالا\nوترى خفافا في الوغى ، فإذا انتدوا … وتلاغط النادي رأيت ثقالا\nصاحت بهم نوب الليالي صيحة … فتتابعوا لدعائها أرسالا\nيتواكلون الموت جبنا بعدما … كانوا أسود مغاور أبطالا\nنزعوا الحمائل عن عواتق فتية … كانوا لكل عظيمة حمالا\nمن بعد ما دعموا القباب وخيسوا … ذلل المطي ودمنوا الأطلالا\nعرب إذا دفعوا الجياد لغارة … هزوا العباب وخضخضوا الأوشالا\nمن كل منهب ماله سؤاله … أو بالغ بعطائه ما نالا\nأو بائت يرعى النجوم لغارة … ويعد للمغدى قنا ونصالا\nلم ترهب الأقدار عزته ، ولا … اتقت النوائب جمعه العضالا\nوعصائب اليمن الذين تبوأ وأ … قلل الهضاب وشردوا الأوعالا\nكانوا فحول وغى تساند بالقنا … لا كالفحول تساند الأجذالا\nزفر الزمان عليهم ، فتطارحوا … فرقا وطاروا بالمنون جفالا\nوعلى الهباءة آل بدر إنهم … طرحوا له الأسلاب والأنفالا\nمن بعد ما خلطوا العجاج وجلجلوا … تلك الزعازع والقنا العسالا\nوالمنذرون الغر شرد منهم … حيا على لقم العراق حلالا\nوالأزد شيريون أبرز منهم … متفيئين من النعيم ظلالا\nتلوي لهم عنق الفرات بمده … \nمن معشر وردوا المنون ، ومعشر … سلبوا الحجال ، وألبسوا الأحجالا\nقد غادروا الإيوان بعد فراقهم … ينعى القطين ويندب الحلالا\nإن كنت تأمل بعدهم مهلا فقد … منتك نفسك في الزمان ضلالا\nلمن الضوامر عريت أمطاؤها … حول الخيام تنازع الأمطالا\nبدلن من لبس الشكيم مقاودا … مربوطة ، ومن السروج جلالا\nفجعت بمنصلت يعرض للقنا … أعناقها ويحصن الأكفالا\nلمن المطايا غير ذات رحائل … فارقن ذاك السدو والإرقالا\nأمست تمنع بالسقاب وطالما … جعل الظبا لرضاعهن فصالا\nمن كان يحمل فوقهن عصابة … مثل الصقور غرانقا أزوالا\nمن كان يجشمهن كل مفازة … تلد المنون وتنبت الأهوالا\nلمن النصول نشبن في أغمادها … كلف الظبى لا ينتظرن صقالا\nلمن الأسنة قد نصلن عن القنا … وعدمن جرا في الوغى ومجالا\nإن صين سردك في العياب فطالما … أمسى عليك مذيلا ومذالا\nكم حجة في الدين خضت غمارها … هدر الفنيق تخمطا وصيالا\nبسنان رمحك أو لسانك موسعا … طعنا يشق على العدا وجدالا\nإن نكس الإسلام بعدك رأسه … فلقد رزي بك موئلا ومآلا\nواها على الأقلام بعدك إنها … لم ترض غير بنان كفك آلا\nأفقدن منك شجاع كل بلاغة … إن قال جلى في المقال وجالا\nمن لو يشا طعن العدا برؤوسها … وأثار من جريالها قسطالا\nسلطان ملك كنت أنت تعزه … ولرب سلطان أعز رجالا\nإن المشمر ذيله لك خيفة … أرخى وجرر بعدك الأذيالا\nما كنت أخشى أن تزل لحادث … قدم جعلت لها الركاب قبالا\nيا شامتا بالسيف أغمد غربه … كم هب مندلق الغرار وصالا\nإن طوح الفعال دهر ظالم … فلقد أقام وخلد الأفعالا\nطلبوا التراث ، فلم يروا من بعده … إلا علا وفضائلا وجلالا\nهيهات فاتهم تراث مخاطر … حفظ الثناء ، وضيع الأموالا\nقد كان أعرف بالزمان وصرفه … من أن يثمر أو يجمع مالا\nمفتاح كل ندى ورب معاشر … كانوا على أموالهم أقفالا\nكان الغريبة في الأنام فأصبحوا … من بعد غارب نجمه أمثالا\nقرم ، إذا كحلت به ألحاظها … شوس القروم تقطع الأبوالا\nوإذا تجايشت الصدور بموقف … حبس الكلام وقيد الأقوالا\nبصوائب كالشهب تتبع مثلها … ورعال خيل يتبعن رعالا\nمن فاعل من بعده كفعاله … أو قائل من بعده ما قالا\nسمع يرفع للسوال سجوفه … ويحجب الأهزاج والأرمالا\nيا طالبا من ذا الزمان شبيهه … هيهات كلفت الزمان محالا\nإن الزمان أضن بعد وفاته … من إن يعيد لمثله أشكالا\nوأرى الكمال حنى عليه لأنه … غرض النوائب من أعير كمالا\nصلى الإله عليك من متوسد … بعد المهاد ، جنادلا ورمالا\nكسف البلى ذاك الجمال المجتلى … وأجر ذاك المقول الجوالا\nورأيت كل مطية قد بدلت … من بعد يومك بالزمام عقالا\nطرح الرجال لك العمائم حسرة … لما رأوك تسير أو إجلالا\nقالوا ، وقد فجئوا بنعشك سائرا : … من ميل الجبل العظيم فمالا\nوتبادروا عط الجيوب ، وعاجلوا … عض الأنامل يمنة وشمالا\nما شققوا إلا كساك ، وألموا … إلا أنامل نلن منك سجالا\nمن ذا يكون معوضا ما مزقوا … ومعولا لمؤمل وثمالا\nفرغت أكف من نوالك بعدها … وأطال عظم مصابك الأشغالا\nأعزز علي بان يهزك طالب … فتضن ، أو تلوي النوال مطالا\nأو أن تبدل من يؤمك زائرا … بعد التهلل ، عندك استهلالا\nأو أن يناديك الصريخ لكربة … حشدت عليه ، فلا تجيب مقالا\nيا كاشف الأمحال كيف رضيته … لمقيل جنبك منزلا ممحالا\nقد كنت آمل أن أراك ، فأجتني … فضلا ، إذا غيري جنى أفضالا\nوأفيد سمعك مقولي وفضائلي … وتفيدني أيامك الإقبالا\nوأعد منك لريب دهري جنة … تثني جنود خطوبه فلالا\nوطواك دهرك غير طي صيانة … وأعاد أعلام الهدى أغفالا\nقبر بأعلى الري شق ضريحه … لأعز حقره الردى أعجالا\nإن يمس موعظة الرجال فطالما … أمسى مهابا للورى ومهالا\nلتسلب الدنيا عليه فإنها … نزعت به الإحسان والإجمالا\nورعاه من أرعى البرية سيبه … وسقاه من أسقى به الآمالا"},{"id":"diwan-radi:453","bookId":"diwan-radi","type":"poem","seq":453,"chapter":"البحر: كامل تام","title":"إلا يكن نصلا فغمد نصول","page":"","text":"إلا يكن نصلا فغمد نصول … غالته أحداث الزمان بغول\nأو لا يكن بأبي شبول ضيغم … تدمى أظافره فأم شبول\nتلك الغمامة كان بارق خالها … لو أنست الأيام غير مخيل\nكنا نؤمل أن نجلي صوبها … عن أخضر غض الجنى مطلول\nلولا طلاب النصل يورق عوده … بات النساء سدى بغير بعول\nولربما بكي الفقيد لنفسه … أو للمطامع فيه والتأميل\nأترى بما نغتر من أيامنا … ونطيل من أمل لهن طويل\nأبوردها المطروق أو بنعيمها … ممذوق ، أم ميعادها الممطول\nنرجو البقاء ، كأننا لم نختبر … عادات هذا العالم المجبول\nلو أن غير يد الزمان تريعني … وتفل حد معاشري وقبيلي\nللويت من دون المذلة جانبي … وجررت عن دار الهوان ذيولي\nلكن سلطان الليالي غالب … عزمي وقطاع علي سبيلي\nقدرت فذل لها العزيز مهابة … ليس الذليل لقادر بذليل\nوهو الزمان يبيح كل ممنع … ويغض من طمحات كل جليل\nمن بين مجروح بحد نيوبه … يدمى وبين مبضع مأكول\nأعدى جذيمة بالردى وعدا على … ردفي جذيمة مالك وعقيل\nواستنزل الأذواء عن نجواتهم … فغدوا ذوي ضرع وطول خمول\nوحدا بآل المنذرين فودعوا … بالحيرة البيضاء كل مقيل\nوسطا على أبناء قيصر سطوة … أمما فأجلت عن دم مطلول\nوأعاد إيوان المدائن محرما … عريان من برد العلى المسدول\nواستل منه مالكية ودونهم … عدد الدراري من قنا وخيول\nوهوى بتيجان الجبابرة الألى … عن كل مطرور الغرار صقيل\nبلت مفارقهم دما ولطالما … عرفوا بمسك فوقهن بليل\nأو بعد ما رفعوا القباب وخولوا … في ظل ممتنع المقام ظليل\nمن كل أغلب كان يحسب عهده … في العز والعليا غير محيل\nويظن أن لو طاولته منية … لأبى إباء المصعب المعقول\nأو لو طغى غرب الفرات لرده … متقطعا ، وأقام مد النيل\nنزل القضاء به فعاد كأنه … لم يغن أمس بطارق ونزيل\nصبرا جميلا يا علي ، فربما … صبر الفتى والصبر غير جميل\nلو كنت أعلم أن وجدا نافع … لقدحت فيك بزفرة وغليل\nوجعلت تصعيب المصاب معظما … من شأنه بدلا من التسهيل\nلكنها الأقدار يمضي حكمها … أبدا على الأصعوب والأذلول\nولربما ابتسم الفتى وفؤاده … شرق الجنان برنة وعويل\nولربما احتمل اللبيب مموها … عض الزمان ببشره المبذول\nوغطي على تلك الجراح ، كأنه … ما آب منه بغارب مخزول"},{"id":"diwan-radi:454","bookId":"diwan-radi","type":"poem","seq":454,"chapter":"البحر: وافر تام","title":"نغالب ثم تغلبنا الليالي","page":"","text":"نغالب ثم تغلبنا الليالي … وكم يبقى الرمي على النبال\nونطمع أن يمل من التقاضي … غريم ليس يضجر بالمطال\nأتنظر كيف تسفع بالنواصي … ليالينا وتعثر بالجبال\nيحط السيل ذروة كل طود … رهونا بالجنادل والرمال\nهي الأيام جائرة القضايا … وملحقة الأواخر بالأوالي\nيمنين الورود فإن دنونا … ضربن على الموارد بالحبال\nنطنب للمقام قباب حي … ويحفزنا المنون إلى الرحال\nونسرح آمنين ، وللمنايا … شبا بين الأخامص والنعال\nبينا المرء يلبسها نعيما … تهجر ضاحيا بعد الظلال\nنعى الناعون واضحة المحيا … ألوف البيت ذي العمد الطوال\nمن البيض العقائل من معد … بنين قبابهن على الجلال\nنعوا ظبة لأبيض مشرفي … قديم الطبع عادي الصقال\nلسيف الدولة العربي فيها … صنيع القين قام على النصال\nإذا ما الفحل انجب ناتجاه … فقد ضمن النجابة للسخال\nوما طابت غوادي المزن إلا … أطبن وقائع الماء الزلال\nقصاير في بيوت العز تنمى … مناسبها إلى المجد الطوال\nوكل عقيلة للجود تمسي … عطول الجيد حالية الفعال\nكأن خدورها أصداف يم … محصنة ضممن على لآل\nطهرن نباهة وبررن طولا … وهن وراء معدود الحجال\nغلبن على جمال الخلق حتى … تركن الخلق منسي الجمال\nلها نسب العتاق مرددات … إلى الغايات أيام النضال\nتعد النوق من شرف فحولا … إذا انتسبت إلى العود الجلال\nعمائر من ربيعة أنزلتهم … أعالي المجد أطراف العوالي\nهم الرأس الذي رفعت معد … قديما لا يطأطأ للفوالي\nفحول المجد جعجعها المنايا … وأسلمها الزمام إلى العقال\nولم يك عزهم إلا اختلاسا … كصفق باليمين على الشمال\nكقومك لا يعيد الدهر قوما … ومثل أبيك لا تلد الليالي\nأريقت في قبورهم اللواتي … ببطن القاع أذنبة النوال\nلقد رست حفائرهم جميعا … على هام المكارم والمعالي\nسقى تلك القبور فإن فيها … سقاة العاجزين عن البلال\nبأيد تحبس الأوراد عزا … وتأمن من ملاطمة السجال\nغمائم للرعود بها أزيز … رغاء العود رازمت المتالي\nكحمحمة الأداهم أقبلوها … ليالي الورد مائلة الجلال\nفسقى عهد دارهم حياها … وحيا بالنعامى والشمال\nإذا ابتدرت نساؤهم المساعي … فما ظني وظنك بالرجال"},{"id":"diwan-radi:455","bookId":"diwan-radi","type":"poem","seq":455,"chapter":"البحر: بسيط تام","title":"ما بعد يومك ما يسلو به السالي","page":"","text":"ما بعد يومك ما يسلو به السالي … ومثل يومك لم يخطر على بالي\nوكيف يسلو فؤاد هاض جانبه … قوارع من جوى هم وبلبال\nيا قلب صبرا ، فإن الصبر منزلة … بعد الغلو إليها يرجع الغالي\nولا تقل سابق لم يعد غايته … فما المقدم بالناجي ، ولا التالي\nنقص الجديدين من عمري يزيد على … ما ينقصان على الأيام من حالي\nدهر تؤثر في جسمي نوائبه … فما اهتمامي إذا أودى بسربالي\nنغتر بالحفظ منه ، وهو يختلنا … كما يغر ذبول الجمرة الصالي\nمضى الذي كنت في الأيام آمله … من الرجال فيا بعدا لآمالي\nقد كان شغلي من الدنيا فمذ فرغت … منه يدي زاد طول الوجد إشغالي\nتركته لذيول الريح مدرجة … ورحت أسحب عنه فضل أذيالي\nكأنني لم أدع في الأرض ، يوم ثوى … مودعا ، شطر أعضائي وأوصالي\nما بالي اليوم لم ألحق به كمدا … أو أنزع الصبر والسلوان من بالي\nعواطف الهم ما تنفك ترجع لي … من ذاهب وجديد الوجد من بال\nما شئت من والد يودي ومن ولد … يمضى الزمان بآسادي وأشبالي\nبالمال طورا وبالأهلين آونة … ما أضيع المرء بعد الأهل والمال\nاليح منه رويدا أو على عجل … لو كان ينفع أروادي وأعجالي\nما أعجب الدهر ، والأيام دائبة … تسعى على عمد نحوي وتسعى لي\nنحبها ، وعلى رغم نودعها … إلى المنون وداع الصارم القالي\nكم أنزل الدهر من علياء شاعقة … وشال من قعر نأي الغور منهال\nوكم هوى بعظيم في عشيرته … مطعام أندية طعان أبطال\nعال على نظر الأعداء يلحظهم … لواحظ الصقر فوق المربأ العالي\nلئن ترامت بك الأعواد معجلة … عن الديار إلى مزورة الخالي\nفليس حي من الدنيا على ثقة … والدهر أعوج لا يبقى على حال\nفلا يسرك إكثاري ولا جدتي … ولا يغمك اقتاري وإقلالي\nأرى يقين المنى شكا فأرفضه … ما أشبه الماء في عيني بالآل\nقبحت ، يا دار ، من دار نغربها … فأنت أغدر مظعان ومحلال"},{"id":"diwan-radi:456","bookId":"diwan-radi","type":"poem","seq":456,"chapter":"البحر: بسيط تام","title":"نخطو وما خطونا إلا إلى الأجل","page":"","text":"نخطو وما خطونا إلا إلى الأجل … وننقضي وكأن العمر لم يطل\nوالعيش يؤذننا بالموت أوله … ونحن نرغب في الأيام والدول\nيأتي الحمام فينسى المرء منيته … وأعضل الداء ما يلهي عن الأمل\nترخي النوائب من أعمارنا طرفا … فنستعز وقد أمسكن بالطول\nلا تحسب العيش ذا طول فتركبه … يا قرب ما بين عنق اليوم والكفل\nنروغ عن طلب الدنيا وتطلبنا … مدى الزمان بأرماح من الأجل\nسلى عن العيش أنا لا ندوم له … وهون الموت ما نلقى من العلل\nتدعو المنون جبانا لا عناء له … مخلاء عن ظهور الخيل والإبل\nويسلم البطل الموفي بسابحة … مشيا على البيض والأشلاء والقلل\nيقودني الموت من داري فأتبعه … وقد هزمت بأطراف القنا الذبل\nوالمرء يطلبه حتف ، فيدركه … وقد نجا من قراع البيض والأسل\nليس الفناء بمأمون على أحد … ولا البقاء بمقصور على رجل\nيبكي الفتى وكلام الناس يأخذه … والدمع يسرح بين العذر والعذل\nوفي الجفون دموع غير فائضة … وفي القلوب غرام غير متصل\nتعز ما اسطعت فالدنيا مفارقة … والعمر يعنق والمغرور في شغل\nولا تشك زمانا أنت في يده … رهن فما لك بالأقدار من قبل\nعاد الحمام لأخرى بعد ماضية … حتى سقاك الأسى علا على نهل\nمن مات لم يلق من يحيا يلائمه … فكن بكل مصاب غير محتفل\nوكل باك على شيء يفارقه … قسرا ، فيقتص من ضحك ومن جذل\nما أقرب الوجد من قلب ومن كبد … وأبعد الأنس من دار ومن طلل\nالعقل أبلغ من عزاك من جزع … والصبر أذهب بالبلوى من الأجل\nسقى الإله ترابا ضم أعظمها … مجلل الودق جرورا على القلل\nولا يزال على قبر تضمنها … برقا يشق جيوب العارض الهطل\nوكلما اجتاز ريعان النسيم به … لم يوقظ الترب من مشي على مهل\nيا أرض ! ما العذر في شخص عصفت به … بين الأقارب والعواد والخول\nأردت أن تحجب البيداء طلعته … ألم يكن قبل محجوبا عن المقل ؟\nجسم تفرد بالأكفان يجعلها … مذ طلق العمر ابدالا من الحلل\nوغرة كضياء البدر لامعة … صار التراب بها أولى من الكلل\nشر اللباس لباس لا نزوع له … والقبر منزل جار غير منتقل\nللموت من قعدت عنه ركائبه … ومن سرى في ظهور الأينق البزل\nما يدفع الموت عن بخل ولا كرم … ولا جبان ولا غمر ولا بطل\nوما تغافلت الأقدار عن أحد … ولا تشاغلت الأيام عن أجل\nلنا بما ينقضي من عمرنا شغل … وكلنا علق الأحشاء بالغزل\nونستلذ الأماني ، وهي مروية … كشارب السم ممزوجا مع العسل\nنؤمل الخلد والأيام ماضية … وبعض آمالنا ضرب من الخطل\nوحسب مثلي من الدنيا غضارتها … وقد رضينا من الحسناء بالقبل\nهذا العزاء وإن تحزن فلا عجب … إن البكاء بقدر الحادث الجلل\nوكيف نعذل من يبكي لميته … ونحن نبكي على أيامنا الأول"},{"id":"diwan-radi:457","bookId":"diwan-radi","type":"poem","seq":457,"chapter":"البحر: كامل تام","title":"ما التامت الأرض الفضاء على فتى","page":"","text":"ما التامت الأرض الفضاء على فتى … كمحمد من بعده أو قبله\nعمري لقد فنيت محاسن وجهه … فيها وقد بقيت محاسن فعله\nزادت مناقبه انتشارا بعده … وحديثه فكأنه في أهله"},{"id":"diwan-radi:458","bookId":"diwan-radi","type":"poem","seq":458,"chapter":"البحر: سريع","title":"إن أشر الخطب فلا روعة","page":"","text":"إن أشر الخطب فلا روعة … أو عظم الأمر ، فصبر جميل\nليهون المرء بأيامه … إن مقام المرء فيها قليل\nهل نافع نفسك أذللتها … كرامة البيت وعز القبيل\nإنا إلى الله ، وإنا له … وحسبنا الله ونعم الوكيل"},{"id":"diwan-radi:459","bookId":"diwan-radi","type":"poem","seq":459,"chapter":"البحر: طويل","title":"خليلي هل لي لو ظفرت بنية","page":"","text":"خليلي هل لي لو ظفرت بنية … إلى الجزع من وادي الأراك سبيل\nوهل أنا في الركب اليماني دالج … وأيدي المطايا بالرجال تميل\nوفي سرعان الريح لي لو علمتما … شفاء ، ولو أن النسيم عليل\nوفي ذلك السرب الذي تريانه … أحم غضيض الناظرين كحيل\nشهي اللمى عاط إلى الركب جيده … ختول لأي جي القانصين مطول\nوكم فيه من خو اللثاث كأنما … جرى ضرب ما بينها وشمول\nتجللن بالريط اليماني كأنما … ضممن غصونا مسهن دبول\nعلقناك ، يا ظبي الصريم ، طماعة … أعندك من نيل لنا ، فتنيل ؟\nأنل نائلا ، أو لا تثن بنظرة … فإني بالأولى الغداة قتيل\nوإني إذا اصطكت رقاب مطيكم … وثور حاد بالرفاق عجول\nأخالف بين الراحتين على الحشا … وانظر إني ملتم فأميل\nأحن وتجريني على الشوق قسوة … ألا غال ما بيني وبينك غول\nوما ذادني ذكر الأحبة عن كرى … ولكن ليلي بالعراق طويل"},{"id":"diwan-radi:460","bookId":"diwan-radi","type":"poem","seq":460,"chapter":"البحر: بسيط تام","title":"ورب يوم أخذنا فيه لذتنا","page":"","text":"ورب يوم أخذنا فيه لذتنا … من الزمان ، بلا خوف ولا وجل\nكنا نؤمله في الدهر واحدة … فجاءنا بالذي يوفي على الأمل\nورب ليل منعنا من أوائله … إلى الصباح جواز النوم بالمقل\nبتنا ضجيعين في ثوب الظلام كما … لف الغصينين مر الريح الأصل\nطورا عناقا كأن القلب من كثب … يشكو إلى القلب ما فيه من الغلل\nوتارة رشفات لا انقضاء لها … شرب النزيف طوى علا على نهل\nوكم سرقنا ، على الأيام ، من قبل … خوف الرقيب كشرب الطائر الوجل"},{"id":"diwan-radi:461","bookId":"diwan-radi","type":"poem","seq":461,"chapter":"البحر: كامل تام","title":"غيري عن الود الصريح يحول","page":"","text":"غيري عن الود الصريح يحول … عمر الزمان وغيرك المملول\nأتظن أني بالقطيعة راغب … هيهات وجهك بالوفاء كفيل\nوكذا الصديق إذا أراد قطيعتي … ظن الظنون وقال أنت ملول"},{"id":"diwan-radi:462","bookId":"diwan-radi","type":"poem","seq":462,"chapter":"البحر: كامل تام","title":"ومقبل كفي وددت بأنه","page":"","text":"ومقبل كفي وددت بأنه … أومى إلى شفتي بالتقبيل\nجاذبته فضل العتاب وبيننا … كبر الملول ورقة المملول\nولحظت عقد نطاقه فكأنما … عقد الجمال بقرطق محلول\nجذلان ينفض من فروج قميصه … أعطاف غصن البانة المطلول\nمن لي به والدار غير بعيدة … عن داره ، والمال غير قليل"},{"id":"diwan-radi:463","bookId":"diwan-radi","type":"poem","seq":463,"chapter":"البحر: طويل","title":"وقد كنت آبي أن أذل لصبوة","page":"","text":"وقد كنت آبي أن أذل لصبوة … وإن تملك البيض الحسان عقالي\nخميصا من الأشجان لا يوضع الهوى … بقلبي فلا اجتاز الغرام ببالي\nإلى أن تراءى السرب بين غزالة … ترنح في ثوب الصبا وغزال\nفلما التقينا كنت أول واجد … ولما افترقنا كنت أخر سالي\nوليلة وصل بات منجز وعده … حبيبي فيها بعد طول مطال\nشفيت بها قلبا أطيل غليله … زمانا ، فكانت ليلة بليالي\nفيا زائرا ، لو أستطيع فديته … بأهلي على عز القبيل ومالي"},{"id":"diwan-radi:464","bookId":"diwan-radi","type":"poem","seq":464,"chapter":"البحر: سريع","title":"عجلت يا شيب على مفرقي","page":"","text":"عجلت يا شيب على مفرقي … وأي عذر ، لك أن تعجلا\nوكيف أقدمت على عارض … ما استغرق الشعر ولا استكملا\nكنت أرى العشرين لي جنة … من طارق الشيب إذا أقبلا\nفالآن سيان ابن أم الصبا … ومن تسدى العمر الأطولا\nيا زائرا ما جاء حتى مضى … وعارضا ما غام حتى انجلا\nوما رأى الراؤن من قبلها … زرعا ذوى من قبل أن يبقلا\nليت بياضا جاءني آخرا … فدى بياض كان لي أولا\nوليت صبحا ساءني ضوءه … زال ، وأبقى ليله الأليلا\nيا ذابلا صوح فينانه … قد آن للذابل أن يختلى\nحط برأسي يقفا أبيضا … كأنما حط به منصلا\nهذا ، ولم أعد بحال الصبا … فكيف من جاوز أو أوغلا\nمن خوفه كنت أهاب السرى … شحا على وجهي أن يبذلا\nفليتني كنت تسربلته … في طلب العز ونيل العلا\nقالوا دع القاعد يزرى به … من قطع الليل وجاب الفلا\nقد كان شعري ربما يدعي … نزوله بي قبل أن ينزلا\nفالآن يحميني ببيضائه … أن أكذب القول وأن أبطلا\nقل لعذولي اليوم نم صامتا … فقد كفاني الشيب أن أعذلا\nطبت به نفسا ، ومن لم يجد … إلا الردى أذعن واستقبلا\nلم يلق من دوني له مصرفا … ولم أجد من دونه موئلا"},{"id":"diwan-radi:465","bookId":"diwan-radi","type":"poem","seq":465,"chapter":"البحر: طويل","title":"أحبك بالطبع البعيد من الحجى","page":"","text":"أحبك بالطبع البعيد من الحجى … وأقلاك بالعقل البريء من الخبل\nفأنت صديقي إن ذهبت إلى الهوى … وأنت عدوي إن رجعت إلى العقل\nوسيان عندي من طواني على جوى … يعذب قلبي ، أو طواني على دخل\nوما الحب إلا ذلة واستكانة … لمولى أرى إعزازه ، ويرى ذلي\nولو أنني خيرت من أمنح الهوى … لما اخترت أن أهوى هوى ومعي عقلي\nولكنه لا رأي في الحب للفتى … فيعلم يوما ما يمر وما يحلي\nولو كان في العشق اختيار لأقصرت … قلوب عن المحبوب ما ضن بالبذل\nولم يحسن الصب التقاضي ودونه … غريم مسيء لا يمل من المطل"},{"id":"diwan-radi:466","bookId":"diwan-radi","type":"poem","seq":466,"chapter":"البحر: طويل","title":"أيا أثلاث القاع كم نضح عبرة","page":"","text":"أيا أثلاث القاع كم نضح عبرة … لعيني ، إذا مر المطي بذي الأثل\nويا عقدات الرمل كم لي أنة … إذا ما تذكرت الشقيق من الرمل\nويا ظعنات الحي يوم تحملوا … عقرت وأفنى الله نسلك من ابل\nويا ظبيات الجزع يسنحن غدوة … لقد كل من ترشقن بالأعين النجل\nويا بانة الوادي أدمعي في الهوى … ابر حيا أم ما سقاك من الوبل\nعوائد من ذكراك يرقص في الحشا … وأضرمن ما بين الذوآبة والنعل"},{"id":"diwan-radi:467","bookId":"diwan-radi","type":"poem","seq":467,"chapter":"البحر: طويل","title":"أصبت بعيني من أصاب بعينه","page":"","text":"أصبت بعيني من أصاب بعينه … فؤادي ، ولم يعقل دمي يوم طله\nلقد ثأرت عيني بقلبي ولم يكن … حلالا له من مهجتي ما استحله\nفأهلا بعينيه ، وإن طلتا دمي … فكم مالك لم يرزق العبد عدله\nوبعدا لعيني لم أصابته بالأذى … وألا تلقت واقع السوء قبله\nفيا ظالما تستحسن النفس ظلمه … ويا قاتلا يستعذب القلب قتله\nليهنك أن النفس تمنحك الهوى … جميعا وأن القلب عندك كله"},{"id":"diwan-radi:468","bookId":"diwan-radi","type":"poem","seq":468,"chapter":"البحر: سريع","title":"سهمك مدلول على مقتلى","page":"","text":"سهمك مدلول على مقتلى … فمن ترى دلك يا قاتل\nليس لقلبي ثائر يتقى … وليس في سفك دمي طائل\nمطلتني حين ملكت الحشا … ألا وقلبي لي يا ماطل\nقد رضي المقتول كل الرضا … يا عجبا لم غضب القاتل"},{"id":"diwan-radi:469","bookId":"diwan-radi","type":"poem","seq":469,"chapter":"البحر: بسيط تام","title":"وما تلوم جسمي عن لقائكم","page":"","text":"وما تلوم جسمي عن لقائكم … إلا وقلبي إليكم شيق عجل\nوكيف يقعد مشتاق يحركه … إليكم الحافزان الشوق والأمل\nفإن نهضت فما لي غيركم وطر … وإن قعدت فما لي غيركم شغل\nلو كان لي بدل ما اخترت غيركم … فكيف ذاك ، وما لي غيركم بدل\nوكم تعرض لي الأقوام قبلكم … يستأذنون على قلبي فما وصلوا"},{"id":"diwan-radi:470","bookId":"diwan-radi","type":"poem","seq":470,"chapter":"البحر: كامل تام","title":"لا تحسبيه وإن أسأت به","page":"","text":"لا تحسبيه وإن أسأت به … يرضي الوشاة ، ويقبل العذلا\nلو كنت أنت ، وأنت مهجته … واشي هواك إليه ما قبلا"},{"id":"diwan-radi:471","bookId":"diwan-radi","type":"poem","seq":471,"chapter":"البحر: طويل","title":"سليمان ! دلتني يداك على الغنى","page":"","text":"سليمان ! دلتني يداك على الغنى … وأجريت لي عزما أغر محجلا\nمددت بضبعي جاهدا فعقدت لي … مصادا بأعنان السماء ومعقلا\nوعليتني حتى ظننت بأنني … سأعبر من عرض المجرة جدولا\nفكيف ارتحالي عنك غير مزود … ويا رب زاد لا يبلغ منزلا\nولا سير إلا أن أشد حقيبة … أرى ضمنها من ضامر الزاد أبحلا\nوإلا فزودني ودادك إنني … أسل على جيش الطوى منك منصلا\nفما صرت حرب الدهر حتى رأيته … يحارب من أمسى وأصبح مرملا\nوكنت إذا ما ناكرتني بلدة … فزعت إلى الجرد العناجيج والملا\nومن كان مهجورا كما أنا فيكم … فما يستحي الأيام أن تتبدلا"},{"id":"diwan-radi:472","bookId":"diwan-radi","type":"poem","seq":472,"chapter":"البحر: رمل تام","title":"أوعيدا ، يا بني جشم","page":"","text":"أوعيدا ، يا بني جشم … ننقض الأطناب والحللا\nوطرادا في ململمة … تستبيح الخيل والإبلا\nونزاعا لا ورود له … يعجم الحوذان والنفلا\nستراني مسى ثالثة … لا أضيف الهم إن نزلا\nوخفيري في غياهبها … سابح ضمنته الأملا\nطرب للصوت تحسبه … عربيا يعشق الغزلا\nسوف يغشى أرضكم أسد … يفرس الأيام والدولا\nلا ينام السيف في يده … ويرى في بابل رجلا\nإنما الدنيا لمقتدر … أين ألقى قوله فعلا"},{"id":"diwan-radi:473","bookId":"diwan-radi","type":"poem","seq":473,"chapter":"البحر: مجزوء الكامل","title":"لا تعذلني في السكوت","page":"","text":"لا تعذلني في السكوت … ت ، فرب قول لا يقال\nكم صامت متوقع … أنى يعن له المقال\nإن التحمل نطفة … أبدا ، يرنقها السؤال\nما كنت أرغب في الحيا … وليس لي عز ومال\nلي لو علمت إلى ذرى … العلياء آمال طوال"},{"id":"diwan-radi:474","bookId":"diwan-radi","type":"poem","seq":474,"chapter":"البحر: بسيط تام","title":"وقائل لي هذا الطود مرتحل","page":"","text":"وقائل لي هذا الطود مرتحل … وهل يخف على الأيام محمله\nلا يبعد الله من غالت ركائبه … صبري ، وقلقل من دمعي تقلقله\nيطيب النفس أن النفس تتبعه … وكيف يرحل من في القلب منزله"},{"id":"diwan-radi:475","bookId":"diwan-radi","type":"poem","seq":475,"chapter":"البحر: طويل","title":"قصدت العلى والمكرمات سبيل","page":"","text":"قصدت العلى والمكرمات سبيل … وطلابها ، لولا الكرام ، قليل\nوكل فتى لا يطلب المجد أعزل … وكل عزيز لا يجود ذليل\nصبغت الأماني بالمعالي فلم تحل … على أن ألوان الظنون تحول\nفأين كموسى ، والرماح شوارع … إلى الطعن ، والبيض الرقاق تجول\nإذا جر أذيال العوالي لمعرك … فإن جلابيب التراب ذيول\nأخو عزمات لا يكفكف عزمه … حذار الأعادي والدماء تسيل\nولا يستكن الروع في طي قلبه … ولا يصحب الصمصام ، وهو كليل\nفكل فلاة من نوالك لجة … وكل مكان من رماحك غيل"},{"id":"diwan-radi:476","bookId":"diwan-radi","type":"poem","seq":476,"chapter":"البحر: وافر تام","title":"عصينا فيك أحداث الليالي","page":"","text":"عصينا فيك أحداث الليالي … وطاوعنا المكارم والمعالي\nوفيك رجمت أحشاء الأعادي … بأطراف الذوابل والنصال\nوعذت بجانبيك من الرزايا … معاذي في الهواجر بالظلال\nدعوتك يوم دافع عنك نحري … جنايات الصوارم والعوالي\nفما خلب النوائب منك برقا … يدل على الوفاء ، إذا بدا لي\nوما هول الفؤاد من التصافي … بعيد من فؤاد فيه خالي\nولم أعلم كعلم بني زماني … بأن القرب داعية الملال\nوإنك حين تطمع في نضالي … وتعلم أن لي سبق النضال\nكماش في الهياج بلا حسام … وساع في الظلام بلا ذبال\nوإني في زماني من رجال … مزاج ودادهم ماء التقالي\nشمال المال تعلو عن يميني … ويمنى المجد تقصر عن شمالي\nأقول لهمتي لما أبت لي … معاتبة الملول على الوصال\nأعاتبه لعل العتب يشفي … وإن كان الزعيم بكسف بالي\nولو لم يبلغ العتبى بقول … لعاتبناه بالبيض الصقال\nرأى العذال بذل المال طبعي … وأسباب الشجاعة من خلالي\nفلم أعذل على خوض المنايا … ولم أعتب على بذل النوال\nأبت هممي تسيغ الماء صفوا … إذا ما الذل حام على الزلال\nأذم على العلى ظلما لأني … أعل بمائها ظمأ السؤال\nوما زلن العواطل كل يوم … من العلياء يذممن الحوالي\nولما ماطلت بالحرب سعد … سننا الموت فيها بالمطال\nأثرنا في قبائلها عجاجا … تركنا منه أثرا في الهلال\nفمن يهدي لآل تميم عتبي … مقيما في ذرى الأسل الطوال\nمنحتكمو الوداد فلم تودوا … فالقيت الملام على فعالي\nولست بباسط كفي لأني … أرى الأفلاك تقصر عن منالي"},{"id":"diwan-radi:477","bookId":"diwan-radi","type":"poem","seq":477,"chapter":"البحر: كامل تام","title":"إن لم أطع همما ، وأعص عواذلا","page":"","text":"إن لم أطع همما ، وأعص عواذلا … قلبت صوامتها علي مقاولا\nوأجيع أعياسا ، وأشبع صارما … وأعل خرصانا ، وأظمىء صاهلا\nولرب مصحوب شرقت بلؤمه … فلفظته قبل الإساغة عاجلا\nوليته زج القناة موزعا … فكأنما أعملت فيه عاملا\nومنحته أروى القوافي عاتبا … فاكتن في جنبيه سما قاتلا\nوكسوت من مور الملام جنانه … قبل العقاب ، فصار فيه جنادلا\nوهززت أغصان المخاوف دونه … فاجتاز يحسبها ظبى وذوابلا"},{"id":"diwan-radi:478","bookId":"diwan-radi","type":"poem","seq":478,"chapter":"البحر: كامل تام","title":"وجد القريض إلى العتاب سبيلا","page":"","text":"وجد القريض إلى العتاب سبيلا … فثنى معاذرك الوعور سهولا\nما لي أحرك من وفائك ساكنا … وأهز منك إلى الصفاء كليلا\nطال المطال برد ود لم يزل … عندي مصونا فيكم مبذولا\nفإلى متى ينشي عتابك هبوة … وتشنها قالا علي وقيلا\nفي كل يوم غارة ما تنقضي … إلا وتثني سيفه مفلولا\nإن الذي قصد المدائح غلة … أحرى بأن يجد الهجاء غليلا\nكم من نظام قد نثرن هواجسي … حتى نظمت العذر فيه فصولا\nوقصائد سددتهن أسنة … وشهرتهن قواضبا ونصولا\nجعلت لرقراق السرور جداولا … نحو القلوب وللهموم سبيلا"},{"id":"diwan-radi:479","bookId":"diwan-radi","type":"poem","seq":479,"chapter":"البحر: متقارب تام","title":"لعمرك ما جر ذيل الفخا","page":"","text":"لعمرك ما جر ذيل الفخا … ر إلا ابن منجبة باسل\nجريء يشيعه قلبه … كما شيع اللهذم العامل\nينال من الطعن ما يشتهي … ويأخذ منه القنا الذابل\nوها أنا ذا غرض بالزمان … فلا عيش يألفه العاقل\nوكل سرور أرى أنه … خضاب على لمتي ناصل\nإذا أنا أملت قال الزمان … ن : أورق حبلك يا حابل\nولا بد من أمل للفتى … وأم المنى أبدا حامل\nودهر يتابع أحداثه … كما تابع الطلق النابل\nفذاك ، أبا حسن ، في السما … اح من لا يلم به السائل\nلئيم تملس منه العلى … ويأنف من يده النائل\nفمثلك من لا يني وبله … إذا استمطر البلد الماحل\nفما هزئت بقراك الضيوف … ولا ذم منزلك النازل\nوكم لك من همة يستطيل … بها العضب والأزرق العاسل\nووعد تنفره بالعطا … كالعام أزعجه القابل\nوأفوه بادرته بالمقال … وقد لجج الذرب القائل\nفرجع في حلقه غصة … كما رجع الجرة البازل\nلك الخير وعدك لا يقتضى … وإن حال من دونه حائل\nولا ضير بعد مجيء الغما … م إن أبطأ الوابل الهاطل\nومطل الكريم مريع الزوا … ل ، كالظل ريعانه زائل\nوأنت وإن كنت بحر السم … اح فخير مواهبك العاجل\nوما صدق وعدك إلا حلى … مكرمة ، جيدها عاطل"},{"id":"diwan-radi:480","bookId":"diwan-radi","type":"poem","seq":480,"chapter":"البحر: مجزوء الكامل","title":"راح يحول شعاعها","page":"","text":"راح يحول شعاعها … بين الضمائر والعقول\nفكأنها في كأسها … والليل منسحب الذيول\nماء الهجير مرقرقا … في سرة الظل الظليل"},{"id":"diwan-radi:481","bookId":"diwan-radi","type":"poem","seq":481,"chapter":"البحر: طويل","title":"سأبذل دون العز أكرم مهجة","page":"","text":"سأبذل دون العز أكرم مهجة … إذا قامت الحرب العوان على رجل\nوما ذاك إن النفس غير نفيسة … ولكن رأيت الجبن ضربا من البخل\nوما المكرهون السمهرية في الطلى … بأشجع ممن يكره المال في البذل"},{"id":"diwan-radi:482","bookId":"diwan-radi","type":"poem","seq":482,"chapter":"البحر: منسرح","title":"زللت في وقفتي على طلل","page":"","text":"زللت في وقفتي على طلل … بال ، فمن عاذري من الزلل ؟\nلما تأملت قبح صورته … رجعت أبكي دما على أملي\nوجه كظهر المجن مشترق … حسن ، وأنف كغارب الجمل"},{"id":"diwan-radi:483","bookId":"diwan-radi","type":"poem","seq":483,"chapter":"البحر: متقارب تام","title":"أبيعك بيع الأديم النغل","page":"","text":"أبيعك بيع الأديم النغل … وأطوي ودادك طي السجل\nوأنفض ثقلك عن عاتقي … فقد طال ما أدتني يا جبل\nقوارص لفظ كحز المدى … وشذان لحظ كوقع الأسل\nتبدلت مني ولو ساءني … لقلت إذا لا هناك البدل\nفكيف ، وكنت على الساعدي … ين جامعة وعلى الجيد غل\nوما عطل المرء يزري به … إذا كان طوق وريديه صل\nنصبت الحبالة لي طامعا … لقد خاب ظنك يا محتبل\nولم تدر أني جري الوثوب … إذا الحبل مر بجنبي نصل\nوأملت ما عكسته الخطوب … سفاها أجرك هذا الأمل\nلقد كدت أن تستزل الأديب … ولكن تحامل سمع أزل\nأفخرا فحسبي بما قد أطا … ل باعي وأنزلني في القلل\nوإن أذل الأذلين من … يريع ببضع النساء الدول\nحملت بقلبي حمل الجموح … كما قطع الصعب لي الطول\nنجوت ، ومن ينج من مثلها … يعش آمنا بعدها من زلل\nوغادرت غيري تحت الهوان … ن يضرب ضرب عراب الإبل"},{"id":"diwan-radi:484","bookId":"diwan-radi","type":"poem","seq":484,"chapter":"البحر: وافر تام","title":"تطاط لها ، فيوشك أن تجلى","page":"","text":"تطاط لها ، فيوشك أن تجلى … وول جنون دهرك ما تولى\nولا تكل الزمان إلى عتاب … فلا يدري الزمان أساء أم لا\nخبوط باليدين يشت شملا … جميعا ، بالنوى ، ويلم شملا\nيعري الغارب الأعلى ويحذي … عظيم العز والخطر الأظلا\nفقدتك من زمان كل فقد … وفعلك ما أخس وما أذلا\nأمثلي يستضام وما ترى لي … إذا عرض العيان بنيك مثلا\nفحسبك قد حملت على مطيق … شآك تجلدا وشجاك حملا\nمحمد طال ما شمرت فيها … فدونك فاسحب الذيل الرفلا\nونم مستودعا صونا وأمنا … فقد أسلفتها جزعا وذلا\nفإن أتبعت هذا الأمر لهفا … فإنك أعزب الثقلين عقلا\nيراه المستغر علي طوقا … فيغبطني به ، وأراه غلا\nوما حط الأعادي لي مجلا … ولكن حط عني الدهر كلا\nفإن أخذوا الأقل من المعالي … فقد تركوا من الصون الأجلا\nخذوا مني بذي جلب ثقال … بعيد إن يخف وإن يزلا\nهوت أم الخطوب إلى التساقي … وقد ضاءلته حتى اضمحلا\nسجية مستميت لا يبالي … من العليا يعطل أم يحلى\nأنا الرجل الذي علمت نزار … أجل مغارسا وأعز نجلا\nأمر على لهى الأضداد طمعا … وأنفذ في طلى الأعداء نبلا\nأليس أبي أبي حسبا وفخرا … وباعا واسعا ، وعلى ، ونبلا ؟\nوقبلك أوقر الأيام مجدا … وأوضع بالعلى حتى أكلا\nفإن يقعد فقد طلب المعالي … فعلقها ، وأوصلها ، وملا\nونفسي ما علمت ، ولي جنان … أبى لي أن أهان وأن أذلا\nفلم آسي وقد أحرزت مجدا … كفاني ما يبلغني المحلا\nإذا خلت المنازل للمولي … فيا سرعان ما عزل المولى\nوبينا أن يقولوا قد تملى … بها حتى يقولوا ما تملى\nبمالك نلتها ، وكفاك عارا … فألا نلتها بالمجد ألا\nفمن وجد الطريق إلي صعبا … فقد وجد الطريق إليك سهلا\nوهل في ذاك إلا أن يقولوا : … تسبب مكثر غلب المقلا\nوما لك مطعم فيها لأني … تركت عليك فضلا قد أظلا\nتهلل إذ أصبت بها حبيبي … ولو غيري أصيب بها استهلا\nشفى بلباسها غلا قديما … وعدت بنزعها فشفيت غلا\nفإن يك نالها ، فلقد أنفنا … فأرخصنا بقيمتها ، وأغلى\nفلم يك جوده في ذاك جودا … ولم يك بخلنا في ذاك بخلا\nفما المغبون إلا من تولى … وما المغبوط إلا من تخلى"},{"id":"diwan-radi:485","bookId":"diwan-radi","type":"poem","seq":485,"chapter":"البحر: مجزوء الرمل","title":"اشتر العز بما بي","page":"","text":"اشتر العز بما بي … ع فما العز بغال\nبالقصار الصفر ، إن شئ … ت أو السمر الطوال\nليس بالمغبون عقلا … من شرى عزا بمال\nإنما يدخر الما … ل لحاجات الرجال\nوالفتى من جعل الأ … وال أثمان المعالي"},{"id":"diwan-radi:486","bookId":"diwan-radi","type":"poem","seq":486,"chapter":"البحر: هزج","title":"بحيث انعقد الرمل","page":"","text":"بحيث انعقد الرمل … غزال دأبه المطل\nجرور للمواعيد … فلا منع ولا بذل\nولو صرح باليأس … أبى وجدي أن أسلو\nلئن أيسني الصد … لقد أطمعني الدل\nله عينان تبرى من … هما للأعين النبل\nسواء بهما الإحيا … ء للواجد والقتل\nأمنك الظعن الغادو … ون زمت لهم الإبل\nكما أشرقت الدوم … ضحى ، أو طلع الرقل\nجلا عنها طراق اللي … ل ، واقلولى بها الهجل\nوفيها القضب الريا ال … الندى والقضب الجذل\nألا لله كم ترش … فينا الأعين النجل\nوتصبينا ديار الح … ي إن ساروا وإن حلوا\nفذي الدار ، إذا تغنى … وذي الدار ، إذا تخلو\nخلعنا طاعة الحب … فلا عهد ولا إل\nإذا ما نفع الجهل … فإن الضائر العقل\nفأما تريني اليوم … م يبلوني الذي يبلو\nصراعا للزمان العود … د أغلوه كما يغلو\nتقيت الشوك بالنعل … فشاكت قدمي النعل\nفقد انهز بالثقل … إذا ما عظم الثقل\nوانزو نزوة البازل … لا يبركه الحمل\nفقد ينهتك الحي … وفيه البيض والذبل\nوقد ينتصر الواحد … لا مال ولا أهل\nيضام العدد الكثر … ويأبى العدد القل\nأخلائي ببغداد … جنى دونكم الرمل\nوحالت دون لقياكم … زحاليف القنا الزل\nلقد كنت شديد الضن … ن أن ينقطع الحبل\nوأن ينصدع الشع … الذي لوئم والشمل\nولكني رعيت الأر … ض ما طاب لي البقل\nوعجلت النوى لما … فشا اللأواء والأزل\nومن أنزله خصب ال … الربى أظعنه المحل\nولا عار على الماتح … أن يغلبه السجل\nنداماي على الهم … سقى عهدكم الوبل\nوحياكم برياه … جديد النور مخضل\nتذكرتكم ، والدم … ع لا وبل ولا طل\nفما أخلفكم جار … من الماقين منهل\nوفي الأيام ما يسلى … ولكن أين ما يسلو\nأبى لي طاعة الضيم … مضاء القلب والنصل\nوإني من مناجيب … لهم أنف إذا ذلوا\nلئن عدت لي الضيم … فلا رحب ولا سهل\nوإن جزت عن العز … فلا جاوزني الذل\nهي البيداء والظلما … ء والناقة والرحل\nشراء الموت للعز … ببيع الضيم لا يغلو\nوإن الجانب الوعر … علي الجانب السهل"},{"id":"diwan-radi:487","bookId":"diwan-radi","type":"poem","seq":487,"chapter":"البحر: رجز تام","title":"أغر أيامي مني ذا الطلل","page":"","text":"أغر أيامي مني ذا الطلل … وإنها ما حملتني أحتمل\nوأنني بقية البزل الأول … قد يجسر العود على طول العمل\nشيب وما جزت الثلاثين نزل … نزول ضيف ببخيل ذي علل\nيصرف عنه السمع إن رغا الجمل … ولا يقول إن أناخ : حي هل\nكأنه لما طرا على عجل … سواد نبت عمه بياض طل\nيجيء بالهم ويمضى بالأجل … فأوه إن حل ، وواها إن رحل\nأبدل من الشباب لا بدل … سرعان ما رق الأديم ونغل\nهل ينفعني في الوهاد والقلل … مد العلابي من النوق الذلل\nفي فتية عودهم جوب السبل … أن يشربوا ماءهم على المقل\nينضون بالليل غلالات الكسل … ويستسلون الكرى من المقل\nإذا دعوا للطعن والخطب جلل … حسبت أيديهم من القنا الذبل\nيبقون آثارا من الطعن نجل … من كل فوهاء كما ضغ الوعل\nيطمع في حاملها السمع الأزل … يقول من عاينها من الوجل\nكذا الطعان لا عمى ولا شلل … في كل يوم أنا مخماص الأصل\nآكل بالميس غوارب الإبل … أهدم ما يبني السنام والكفل\nبين عجاريف العنيق والرمل … مشتملا برد الجنوب والشمل\nوطالعا مع الشميط ذي الشعل … وغاربا مع الظلام والطفل\nتعرضا للرزق والرزق أشل … وشنج الكف إذا قيل بذل\nرد ما سقاك الدهر علا ونهل … وما حذتك النائبات ، فانتعل\nما دمت جثاما على نضو الإبل … مسوفا في كل يوم بالرحل\nمن لم يعان الغزو لم يعط النفل … قد انقضى العمر وأنت في شغل\nفاجسر على الأهوال إن كنت رجل … ونل بأطراف القنا ما لم ينل\nمن طلب العز بغير السيف ذل … وأمش إلى المجد ولو على الأسل\nوانج من الهون كما ينجو البطل … من لم يئل من بعدها فلا وأل"},{"id":"diwan-radi:488","bookId":"diwan-radi","type":"poem","seq":488,"chapter":"البحر: وافر تام","title":"لحب إلي بالدهناء ملقى","page":"","text":"لحب إلي بالدهناء ملقى … لأيدي العيس واضعة الرحال\nمناخ مطلحين تقاذفتهم … غريب الحاج والهمم العوالي\nأراحوا فوق أعضاد المطايا … قد افترشوا زرابي الرمال\nفبين ممضمض بالنوم ذوقا … وبين مقيد بعرى الكلال\nإلى أن روع الظلماء فتق … أغر كجلحة الرجل البجال\nفقاموا يرتقون على ذراها … سلاليم المعالق والجبال\nوأرقني دعاء الورق فيها … على جرح قريب الإندمال\nتذكرني بسالفة الليالي … وسالفة الغزالة والغزال\nوأيام الشباب مساعفات … جمعن لنا وأيام الوصال\nكأنفاس الشمول كرعت فيها … على ظمإ وإنفاس الشمال\nأقول لها ، وقد رنت مراحا … لبالك يا حمامة غير بالي\nتباعد بيننا من قيل شاك … تعلق بالغرام ، وقيل سالي\nتريع إلى درادق عاطلات … وهن بعيد آونة حوالي\nلها صنع يطول على طلاها … قلائد لا تفصل باللألى\nعوار لا تزال الدهر حتى … تجللها بريط غير بالي\nوكل أزيرق قصرت خطاه … كشيخ الحي طأطأ للعوالي\nمراحك قبل طارقة المنايا … وقبل مرد عادية الليالي"},{"id":"diwan-radi:489","bookId":"diwan-radi","type":"poem","seq":489,"chapter":"البحر: رجز تام","title":"أقول والهم زميل رحلي","page":"","text":"أقول والهم زميل رحلي … يعرقني مطاله ويبلي\nولا أرى من زمني ما يسلي … من يشتري مني جميع فضلي\nبساعة من عيش أهل الجهل … كنت أرى العقل نفاق مثلي\nفصار أدنى ضائر لي عقلي … "},{"id":"diwan-radi:490","bookId":"diwan-radi","type":"poem","seq":490,"chapter":"البحر: طويل","title":"لقد طال هزي من قوائم معشر","page":"","text":"لقد طال هزي من قوائم معشر … كلال الظبا لم أرض من بينها نصلا\nرجال إذا ناديتهم لصنيعة … وجدتهم ميلا عن الجود أو عزلا\nإذا جشموا النزر القليل رأيتهم … يعجون من لؤم وما حملوا ثقلا\nعلى النفس أثني بالملام لأنني … نحلت وسوم الخيل أحمرة غفلا\nوحملت أمطاء البكار مآربي … ولما احملها المصاعب والبزلا\nيشيع لئيم القوم ذو الجهل لؤمه … ويستر بعض اللؤم من صحب العقلا\nألا ربما أرقي اللئيم ، فينثني … وأعضلني من يجمع اللؤم والجهلا\nحبالى بموعود العطاء تجرمت … شهورا وأعواما وما طرقوا حملا\nتواصوا بمطل الوعد ثم تجاسروا … على اللؤم حتى جانبوا الوعد والمطلا\nذنابى قصار لا يزيدون بسطة … وإن ركبوا يوما ظننتهم رجلا\nفشتان أنتم والمسيلون للجدا … إذا عدم العام الندى روضوا المحلا\nيكونون للوبل الغمامي إخوة … فإن ضن عن أوطانه خلفوا الوبلا\nيبيتون غرثى يعلكون سياطهم … وقد طردوا عنا المجاعة والأزلا\nحياض معان الماء غادية الحيا … يدل عليها الخابطان ، إذا ضلا\nيذودون عنها للغريب سوامهم … ولو أنهم شاؤوا القذى وردوا قبلا\nإذا سالموا لم يمنعوا النصف طالبا … وإن طاعنوا الأقران لم يعرفوا العدلا\nإذا فغرت شوهاء من جانب العدا … على غير نذر لقموها القنا الذبلا\nثقال بأيديهم ، خفاف كأنما … أطاروا إلى الأعداء من روسها نخلا\nكأن طروق الحي يخرج منهم … إذا غضبوا ، الداء المجنة والخبلا\nإذا ما دعوا خلت الرياح عواصفا … تهيل ثرى من جانب الغور أو رملا\nينادي الفتى بالليل موقد ناره … حباب القرى ظاهر لها الحطب الجزلا\nويا راعي الكوماء للسيف ظهرها … فضع عن بوانيها الحوية والرحلا\nأولئك قومي لا الذين مقالهم … لباغي الندى أو طارق الليل : لا أهلا"},{"id":"diwan-radi:491","bookId":"diwan-radi","type":"poem","seq":491,"chapter":"البحر: طويل","title":"إذا رابني الأقوام بعد ودادة","page":"","text":"إذا رابني الأقوام بعد ودادة … لبست القلى نعلا بغير قبال\nوأغبطت رحل الهم في ظهر عزمة … مواشكة من عجرف ونقال\nوما كنت أن فارقت حيا ذممته … بطول نزاعي أو تحن جمالي\nإذا علموا مني علاقة وامق … فلا يأمنوا يوما نزاعة سالي\nأأذهب عن قوم كرام أعزة … إلى جذم قوم عاجزين بخال\nكمن بادل الإجلاء في العين بالقذى … وآب بداء لا يطب عضال\nينازعني الأحساب مستضعف القوى … له عن رهان المجد أي عقال\nإذا مغرم غادى اتقاه بعرضه … أمام يديه ، واتقيت بمالي\nيمد يدا مخبولة لينالني … وقد أعجز الأيدي الصحاح منالي\nتعرضت للعريض حتى علقته … بأظفور أقنى ذي ندى وظلال\nومن لم يدع إيقاد نار بقرة … فلا بد يوما أن يجيء بصالي\nوإني على بعد برمي قوارصي … لأرغب جرحا من رمي نبالي\nيشكك في الناظرون : أفله … غرار مقالي أم غرار نصالي\nلئن أطمع الأقوام حلمي ، فربما … أخافهم ، بعد الأمان ، صيالي\nوليس قبوع الصل مانع وثبه … إذا نال منه والغ بمنال"},{"id":"diwan-radi:492","bookId":"diwan-radi","type":"poem","seq":492,"chapter":"البحر: وافر تام","title":"غدت عرسي تجرم لي ذنوبا","page":"","text":"غدت عرسي تجرم لي ذنوبا … وذنبي عندها ذنب المقل\nتريني الدل عمدا وهو فرك … وهيهات الفروك من المدل"},{"id":"diwan-radi:493","bookId":"diwan-radi","type":"poem","seq":493,"chapter":"البحر: طويل","title":"أبى الله أن تأتي بخير فترتجى","page":"","text":"أبى الله أن تأتي بخير فترتجى … فروع لئام قد ذممنا أصولها\nإذا الدار من قبل العفاء نبت بنا … فكيف نرجي للمقام طلولها\nهززت المواضي فانثنت عن ضرائبي … فما أر بي في أن أهز كليلها\nإذا قيل بيت الفخر كنتم ضيوفه … وإن قيل دار اللؤم كنتم حلولها\nوقولة خزي فيكم تستفزني … وأعلم أن لا بد من أن أقولها"},{"id":"diwan-radi:494","bookId":"diwan-radi","type":"poem","seq":494,"chapter":"البحر: طويل","title":"وذي ضغن معسولة كلماته","page":"","text":"وذي ضغن معسولة كلماته … ومسمومة تترى إلى القلب نبله\nعركت بحلمي جهله ، فكددته … عراكا إلى أن مات حلمي وجهله\nركبت ظراب اللابتين على الحفا … وغيرك لم تسلم عليهن نعله\nلقد أوعر النهج الذي أنت خابط … فقف سالما حيث انتهى بك سهله\nلأشفى مريض الود بيني وبينكم … وعاود نكسا بعد برء مبله\nوكان الأذى رشحا فقد صار غمرة … وأول أعداد الكثير أقله\nنهيتك عن شعب عسير ولوجه … بذي الرمث قد أعيا على الناس صله\nوبيت كلصب الأري لا تستطيعه … صدور الطوال الزاعبيات نحله\nفلا تقربن الغاب يحميه ليثه … ودع جانبا وعرا على من يحله\nكأن على الأطواد من نزع بيشة … رصيد طريق ضل من يستدله\nتلفع في ثني عباء مشبرق … أصابيغ ألوان الدماء تبله\nقصاقصة ما بات إلا على دم … تمضمض منه عرسه ثم شبله\nأخو قنص كفاه كفة صيده … إذا جاع يوما والذراعان حبله\nيشقق عن حب القلوب بمخصف … أزل كما جلى عن الرمح نصله\nكخارز مقدود الأديم رأيته … يبين عن الإشفى وطورا يغله\nقليل ادخار الزاد يعلم أنه … متى ما يعاين مطعما فهو أكله\nتصدع عن همهامة الخيل والقنا … صياحك في أعقاب طرد تشله\nله وقفة المجزاع ثم تجيزه … حفيظة مجموع على الروع شمله\nومستوقدات من لظى العار أججت … لها حطبا لا ينقضي الدهر جزله\nتوردها قوم فطاحوا جهالة … وكان عقال المرء عنهن عقله\nوطوق من المخزاة فيكم عقدته … ألا إن عقد العار يعجز حله\nمضغتكم بالذم ثم لفظتكم … وما كل لحم يعجب المرء أكله\nشغلت بكم قولي ، وعندي بقية … وقد يردف الظهر الذي آد حمله\nفلا تفتقد خلا يسؤك بعضه … وإن غاب يوما عنك ساءك كله\nإذا شئت أن تبلو امرأ كيف طبعه … فدعه وسائل قبلها كيف أصله"},{"id":"diwan-radi:495","bookId":"diwan-radi","type":"poem","seq":495,"chapter":"البحر: بسيط تام","title":"تغير القلب عما كنت تعرفه","page":"","text":"تغير القلب عما كنت تعرفه … أيام قلبي دار منك محلال\nوأدبر الود ما بيني وبينكم … وللمودات إدبار وإقبال\nما كنت صبا فما في الناس لي بدل … وإن سلوت فكل الناس أبدال"},{"id":"diwan-radi:496","bookId":"diwan-radi","type":"poem","seq":496,"chapter":"البحر: طويل","title":"ولما بدا لي أن ما كنت أرتجي","page":"","text":"ولما بدا لي أن ما كنت أرتجي … من الأمر ولى ، بعدما قلت أقبلا\nتلومت بين اللوم والعذر ساعة … كذي الورد يرمي قبل أن يتبدلا\nفلما رأيت الحلم قد طار طيرة … ولم أر إلا أن ألوم وأعذلا\nرجعت أولي عاثر الجد لومها … فلا قام بين العاثرين ولا علا\nألعنه مستثنيا من عنانه … كردك في الغمد الكهام المفللا\nوأعفيت من لومي امرأ ما وجدته … مليما ، ولا بابا عن الجود مقفلا\nلجدي إذا باللوم أولى من الحيا … ومن ذا يلوم العارض المتهللا"},{"id":"diwan-radi:497","bookId":"diwan-radi","type":"poem","seq":497,"chapter":"البحر: متقارب تام","title":"أشم ببابل بو الصغار","page":"","text":"أشم ببابل بو الصغار … ولو أنا بالرمل لم أفعل\nوألقى التحيات من معشر … كما ارتجم الحي بالجندل\nوأنزل في القوم اقلالهم … ولولا الحضارة لم أنزل\nولو كنت راكب هذا الجواد … بوادي القرينة لم أرحل\nولو مد لي طنب بالفلا … حماني لداغ القنا الذبل\nوأسرة عز طوال القنا … إذا نزل الذل قالوا ارحل\nمهجنة أصطلي نارها … وعز على الرجل المصطلي\nولو شور السيف في مثلها … لقال : أطعني ولا تقبل\nفلو كنت من شاهديها رأي … ت هوي الروس على الأرجل\nمقام يدنس عرض الأبي … ويلعب بالقلب الحول\nولو كنت ذا همة حرة … لرحلني الضيم عن منزلي\nوكيف تقلب ذي همة … وقد لز بالقرن الأطول\nأءأبى ولا حد اسطوبه … وأين الإباء من الأعزل\nترى الجاهلية أحمى لنا … وأنأى عن الموقف الأرذل\nفلولا الإله وتخوافه … رجعنا إلى الطابع الأول"},{"id":"diwan-radi:498","bookId":"diwan-radi","type":"poem","seq":498,"chapter":"البحر: سريع","title":"إياك عنه عذل العاذل","page":"","text":"إياك عنه عذل العاذل … قلب الفتى في شغل شاغل\nدعني ومن يسلبني مهجتي … ما أطلب العون على قاتلي\nويا غريمي بعقيق الحمى … حصلت من حقي على الباطل\nيعجبني مطل غريم الهوى … لطول تردادي إلى الماطل\nوطارق لشيب حييته … سلام لا الراضي ولا الجاذل\nأجرى على عودي ثقاف الهوى … جري الثقافين على الذابل\nواعدني عقر مراحي له … لا در در الشيب من نازل\nفاليوم لا زور ولا طربة … نام رقيبي وصحا عاذلي\nيا راكب الوجناء مصبوبة … على الملا كالصدع العاقل\nكأنما يرمي جلاد الصفا … بأوب رجلي ذرع جافل\nراعت حصى نجد فإخفافها … بعد التزامي بثرى بابل\nأبلغ قويما كثروا قلة … بعد مضي السلف الراحل\nكانوا صفاء الكأس ثم انجلوا … من البواقي عن قذى ثافل\nزال نجوم ، عرفوا بعدهم … وفي التفاني نبه الخامل\nضرورة حمت على وردكم … لما خطاني مطر الوابل\nلا يركب الناهق ذو أربة … إلا إذا رد عن الصاهل\nأغمدتموني بعد صقل الشبا … إغماد لا الماضي ولا القاصل\nوحاجة السيف إلى ضارب … يوم المنايا ، لا إلى صاقل\nلا تحسن النيقة في قاطع … من ليس للقاطع بالحامل\nآليت أن أحدو بأعراضكم … حدو أبي عروة بالجامل\nوسوف أحمي لكم ميسما … ينبش منه وبر البازل\nإذا انبرى للجلد أبقى له … علطا من الزور إلى الكاهل\nأطواق عار إن تقلدتها … حسدت منها عنق العاطل\nأرسلها هزلا وأرمي بها … ما بلغ الجد من الهازل\nيعشو إليها كل ذي ناظر … قول كأنياب صلال التقا\n … تشاك منه قدم الناعل\nأسرع في الناس إذا قلته … من خبر السوء إلى الناقل\nلا تنكروا السيل إذا كنتم … على طريق اللجب الهاطل\nقل لأبي العوام مستدفعا … به جماح القدر النازل\nيا نجوة الخائف من دهره … ويا ثقاف الخطل المائل\nجذبت حبلي من يدي قاطع … فامدد له منك يدي واصل\nهيهات ما غيمك بالمنجلي … يوما ولا ظلك بالزائل\nولا خضاب العهد أعطيته … أن نصل الأقوام بالناصل\nما كنت لما طلبت دعوتي … سمعك بالواني ، ولا الغافل\nقمت قيام الرمح في نصرتي … مرافد اللهذم بالعامل\nهبني خسأت الخطب عني ، وما … قدرت إلا أنه آكلي\nكم غرني غيرك من ناصر … أبطأ والمبطئ كالخاذل\nأطمعني ، حتى إذا جئته … كان سراب البلد الماحل\nتعذب الآمال في ظله … وتنثني عنه بلا طائل\nمن كل ملبوس على غرة … لبس مطال السقم الآزل\nمموج الأخلاق لا محسن … رب يد الجود ، ولا باخل\nكالعير في عانة ذي طخفة … لا طالب النسل ولا عازل\nواند ما إن لم أكن سامعا … مشورة الصل أبي وائل\nقالوا : ورأي المرء من عقله … ويذهب الرأي عن العاقل\nأغلوطة لا نهض من عثرها … قد سبق السهم يد النابل"},{"id":"diwan-radi:499","bookId":"diwan-radi","type":"poem","seq":499,"chapter":"البحر: كامل تام","title":"جمحت بك الجاهات في غلوائها","page":"","text":"جمحت بك الجاهات في غلوائها … سفها ، فغض من العنان قليلا\nواحذر لواذع قائل متغطرف … أمسى يسن لسانه ليقولا\nبفواقر تدع الرؤس أميمة … وقوارع تدع العزيز ذليلا\nقد كان عرضك في الصوان بطيئة … فلئن أبيت ليغدون مبذولا\nإن العباب إذا تغطغط أو طمى … جعل الجبال وإن علون مسيلا"},{"id":"diwan-radi:500","bookId":"diwan-radi","type":"poem","seq":500,"chapter":"البحر: طويل","title":"وقالوا : أسغها ! إنما هي مضغة","page":"","text":"وقالوا : أسغها ! إنما هي مضغة … بفيك أبا الغيداق ترب وجندل\nصدفت بوجهي لا بقلبي عنكم … ويصدف قلب المرء والوجه مقبل\nرجعنا على الأعقاب فيما يسرنا … نجر إلى ما لا نود ونعتل\nصحاح أديم الود لا عيب فيهم … سوى ما يقول الجادب المتعلل\nفزعت إلى الإبدال بعد فراقهم … فاعوذني يا عمرو من اتبدل"},{"id":"diwan-radi:501","bookId":"diwan-radi","type":"poem","seq":501,"chapter":"البحر: رجز تام","title":"لباك مشزور القوى ذيال","page":"","text":"لباك مشزور القوى ذيال … أغلب قوال الندي فعال\nمن قبل أن تدعو به الآمال … إن قال لم تقعد به الفعال\nينيل جودا فوق ما ينال … خلق رقيق ماؤه زلال\nكالخمر إلا أنه حلال … المال يفنى والثناء المال\nتبقى العلى ، وتذهب الرجال … "},{"id":"diwan-radi:502","bookId":"diwan-radi","type":"poem","seq":502,"chapter":"البحر: رمل تام","title":"إن غرب الدهر مصقول","page":"","text":"إن غرب الدهر مصقول … وغرار الجد مسلول\nورداء الفجر منسحب … ونطاق الليل مسدول\nوحواشي الجو ناصلة … والدجا بالصبح مطلول\nوثنايا اليوم يضحكها … من قدوم العيد تقبيل\nشهدت فينا ، مخائله : … إن هذا الصوم مقبول\nفأطع حكم السرور ، وإن … زخرفت فيه الأضاليل\nوتعلل بالمدام له … إنما الدنيا تعاليل"},{"id":"diwan-radi:503","bookId":"diwan-radi","type":"poem","seq":503,"chapter":"البحر: طويل","title":"سل الهضب ما بين الهضاب الأطاول :","page":"","text":"سل الهضب ما بين الهضاب الأطاول : … متى ريع يوما قبلها بالزلازل\nوهل خضدت تلك الرماح لغامز … وهل أكثبت تلك النجوم لنائل\nمضى النجباء الأطولون وخلفوا … قصار الخطا عن كل مجد ونائل"},{"id":"diwan-radi:504","bookId":"diwan-radi","type":"poem","seq":504,"chapter":"البحر: مجزوء الكامل","title":"رست قبورهم على","page":"","text":"رست قبورهم على … هام المكارم والمعالي\nفكأنما هرق الندى … فيهن ، أذنبة النوال\nمنهم وراء الترب أم … ثال الصوارم والعوالي\nأترى المنايا كيف جل … بذلك الحي الحلال"},{"id":"diwan-radi:505","bookId":"diwan-radi","type":"poem","seq":505,"chapter":"البحر: طويل","title":"تكلفني عذر البخيل ، ولي مال","page":"","text":"تكلفني عذر البخيل ، ولي مال … ملامك لا يذهب بك القيل والقال\nفعندك إكثاري إذا كنت مكثرا … وعندي إقلالي ، إذا كان إقلال\nوإني لأرمي بالنوال مسافة … من الجود لا يسطيعها الرجل النال"},{"id":"diwan-radi:506","bookId":"diwan-radi","type":"poem","seq":506,"chapter":"البحر: وافر تام","title":"تقارعنا على الأحساب حتى","page":"","text":"تقارعنا على الأحساب حتى … توادعنا ، فكل غير آل\nفكانت بين قومكم وبيني … خماشات بأطراف العوالي"},{"id":"diwan-radi:507","bookId":"diwan-radi","type":"poem","seq":507,"chapter":"البحر: كامل تام","title":"يا سعد سعد الخيل والإبل","page":"","text":"يا سعد سعد الخيل والإبل … إدفع صدور الأينق البزل\nأو ما رأيت العيس آخذة … لك أهبة الإدلاج والعمل"},{"id":"diwan-radi:508","bookId":"diwan-radi","type":"poem","seq":508,"chapter":"البحر: طويل","title":"ألا حي ضيف الشيب إن طروقه","page":"","text":"ألا حي ضيف الشيب إن طروقه … رسول الردى قدامه ، ودليله\nوقد كان يبكيني لشعري نزوله … فقد صار يبكيني لعمري رحيله"},{"id":"diwan-radi:509","bookId":"diwan-radi","type":"poem","seq":509,"chapter":"البحر: وافر تام","title":"وقد تركت صوارمهم بحجر","page":"","text":"وقد تركت صوارمهم بحجر … وقائع من دماء بني عقال\nوما ضلت ضلالهم بحجر … سقيطة جندل بين الرجال"},{"id":"diwan-radi:510","bookId":"diwan-radi","type":"poem","seq":510,"chapter":"البحر: طويل","title":"ومعترك للوصل يجلى عجاجه","page":"","text":"ومعترك للوصل يجلى عجاجه … ببطحاء قوم عن قتيل وقاتل\nوأكثر ما يلقى به غب نومه … سقاط اللألي أو فصوم الخلاخل"},{"id":"diwan-radi:511","bookId":"diwan-radi","type":"poem","seq":511,"chapter":"البحر: خفيف تام","title":"وإذا ما دعوا وقد نشط الرو","page":"","text":"وإذا ما دعوا وقد نشط الرو … ع ، خيول العدا من الأجلال\nشمروا يطلبون ناشئة الصو … ت خناذيذ كالجذوع الطوال"},{"id":"diwan-radi:512","bookId":"diwan-radi","type":"poem","seq":512,"chapter":"البحر: سريع","title":"أصبحت لا أرجو ولا أبتغي","page":"","text":"أصبحت لا أرجو ولا أبتغي … فضلا ولي فضل هو الفضل\nجدي نبي وإمامي أبي … ورايتي التوحيد والعدل\nيا عاذلان أسأتما العذلا … لا مرحبا بكما ولا أهلا\nأعذلتما من لم يمل هوى … وتركتما عذل الذي ملا\nولحوتما المقتول من كمد … وعذلتما من طرق القتلا\nلو أن غير دمي ذهبت به … لم تسألي قودا ولا عقلا"},{"id":"diwan-radi:513","bookId":"diwan-radi","type":"poem","seq":513,"chapter":"البحر: خفيف تام","title":"رائعات أخفهن ثقيل","page":"","text":"رائعات أخفهن ثقيل … وخطوب أدقهن جليل\nورزايا تهفو لهن حلوم … راسيات وتستزل عقول"},{"id":"diwan-radi:514","bookId":"diwan-radi","type":"poem","seq":514,"chapter":"البحر: طويل","title":"تذارعن بالأيدي من الغور بعدما","page":"","text":"تذارعن بالأيدي من الغور بعدما … تقدم عرنين من الليل مائل\nفما عممتها الشمس حتى رأيتها … بنجد تساميها النجاد القوابل"},{"id":"diwan-radi:515","bookId":"diwan-radi","type":"poem","seq":515,"chapter":"البحر: طويل","title":"تذكرت ، بين المأزمين إلى منى","page":"","text":"تذكرت ، بين المأزمين إلى منى … غزالا رمى قلبي وراح سليما\nلئن كنت أستحلي مواقع نبله … فإني ألاقي غبهن اليما\nأصاب حراما ينشد الأجر غدوة … فما عاد مأجورا وعاد أثيما\nفلو كان قلبي باريأ ما ألمته … ولكن أسقاما أصبن سقيما\nإذا بل من داء أعادت له المها … نكاسا ، إذا ما عاد عاد مقيما\nبظنونني استطرفت داء من الهوى … وهيهات داء الحب كان قديما\nقنصت بجمع شادنا فرحمته … وأخفض قناص يكون رحيما\nأأغدو مهينا بالحبائل ساعة … غزالا على قلبي الغداة كريما\nولم أر مثل الماطلات عشية … ذوات يسار ما قضين غريما\nفلا يبعد الله الذي كان بيننا … من العهد إلا أن يكون ذميما"},{"id":"diwan-radi:516","bookId":"diwan-radi","type":"poem","seq":516,"chapter":"البحر: طويل","title":"حبيبي ما أزرى بحبك في الحشا","page":"","text":"حبيبي ما أزرى بحبك في الحشا … ولا غض عندي منك إنك أعجم\nوعابك عندي العائبات ظوالما … وإني إذا طاوعتهن لأظلم\nبنفسي من يستدرج اللفظ عجمة … كما يمضغ الظبي الأراك ويبغم"},{"id":"diwan-radi:517","bookId":"diwan-radi","type":"poem","seq":517,"chapter":"البحر: بسيط تام","title":"يا ليلة السفح ألا عدت ثانية","page":"","text":"يا ليلة السفح ألا عدت ثانية … سقى زمانك هطال من الديم\nماض من العيش لو يفدى بذلت له … كرائم المال من خيل ومن نعم\nلم أقض منك لبانات ظفرت بها … فهل لي اليوم إلا زفرة الندم\nفليت عهدك ، إذ لم يبق لي أبدا … لم يبق عندي عقابيلا من السقم\nتعجبوا من تمني القلب مؤلمه … وما دروا أنه خلو من الألم\nردوا علي ليالي التي سلفت … لم أنسهن ولا بالعهد من قدم\nأقول للائم المهدي ملامته … ذق الهوى وإن اسطعت الملام لم\nوظبية من ظباء الأنس عاطلة … تستوقف العين بين الخمص والهضم\nلو أنها بفناء البيت سانحة … لصدتها وابتدعت الصيد في الحرم\nقدرت منها بلا رقبى ولا حذر … على الذي نام عن ليلي ، ولم أنم\nبتنا ضجيعن في ثوبي هوى وتقى … يلفنا الشوق من فرع الى قدم\nوأمست الريح كالغيرى تجاذبنا … على الكثيب فضول الريض واللم\nيشي بنا الطب أحيانا وآونة … يضيئنا البرق مجتازا على أضم\nوبات بارق ذاك الثغر يوضح لي … مواقع اللثم في داج من الظلم\nوبيننا عفة بايعتها بيدي … على الوفاء بها والرعي للذمم\nيولع الطل بردينا وقد نسمت … رويحة الفجربين الضال والسلم\nوأكتم الصبح عنها ، وهي غافلة … حتى تكلم عصفور على علم\nفقمت أنفض بردا ما تعلقه … غير العفاف وراء الغيب والكرم\nوألمستني وقد جد الوداع بنا … كفا تشير بقضبان من العنم\nوألثمتني ثغرا ما عدلت به … أري الجنى ببنات الوابل الرذم\nثم انثنينا وقد رابت ظواهرنا … وفي بواطننا بعد من التهم\nيا حبذا لمة بالرمل ثانية … ووقفة ببيوت الحي من أمم\nوحبذا نهلة من فيك باردة … يعدي على حر قلبي بردها بفمي\nدين عليك ، فإن تقضيه أحي به … وإن أبيت تقاضينا إلى حكم\nعجبت من باخل عني بريقته … وقد بذلت له دون الأنام دمي\nما ساعفتني الليالي بعد بينهم … إلا بكيت ليالينا بذي سلم\nولا استجد فؤادي في الزمان هوى … إلا ذكرت هوى أيامنا القدم\nلا تطلبن لي الإبدال بعدهم … فإن قلبي لا يرضى بغيرهم"},{"id":"diwan-radi:518","bookId":"diwan-radi","type":"poem","seq":518,"chapter":"البحر: طويل","title":"نظمنا نظام العقد ودا وألفة","page":"","text":"نظمنا نظام العقد ودا وألفة … وكان لنا البتي سلك نظام\nأخي وابن عمي وابن حمد فإنه … تباريح قلبي خاليا وغرامي\nوسادسنا الأزدي ما شئت من أب … جواد ومن جد أغر همام\nأحاديث تستدعي الوقور إلى الصبا … وتكسو حليم القوم ثوب عرام\nفنضحي لها طربى بغير ترنم … ونمسي لها سكرى بغير مدام\nتعالوا نول اللائمين تصامما … ونعص على الأيام كل ملام\nونغتنم الأوقات إن بقاءها … كمر غمام أو كحلم منام\nمن الله أستبقي صفاء يضمنا … وطاعة أيام ودار مقام\nواستصرف الأعداء عنا فإننا … مذ اليوم أغراض لكل مرام"},{"id":"diwan-radi:519","bookId":"diwan-radi","type":"poem","seq":519,"chapter":"البحر: مجزوء الرجز","title":"ألمع برق أم ضرم","page":"","text":"ألمع برق أم ضرم … بين الحرار والعلم\nتضحك عن وميضه … لماعة من الديم\nكما استشب ناره … قين بضال وسلم\nقد هدلت شفاهها … على القنان والأكم\nتهدر عن رعودها … هدر الفنيق ذي القطم\nلها فساطيط على … ذرى الروابي وخيم\nأشيمة لفتية … تضرعوا على اللمم\nقد سوروا أكفهم … بلي أطراف الخطم\nوجللوا ميس الرحا … محتمل الأعباء لا\nأوقظهم وللكرى … فيهم خبال ولمم\nكأنما يجذبهم … من الرقاب والقمم\nمن كل معروق العظا … م أملس ولى الزلم\nيلوك فوه مضغة … ضعيفة عن الكلم\nإذا أراد قول لا … من سكره قال : نعم\nوالركب في مضلة … لا نضد ، ولا علم\nما انتعلت بإرضها … خف بعير أو قدم\nأقول لما أن دنا … من المصاب وعزم\nيا برق إن صبت الحمى … فلا تصب إلا بدم\nعلى ديار معشر … خانوا العهود والذمم\nتجهموا ضيف العلى … وامتهنوا زور النعم\nمن كل راعي أمة … أجهل من راعي غنم\nما بينهم في المكرما … ت نسب ولا رحم\nوما بهم إلى الندى … لا ظمأ ولا قرم\nكم أذكروني معشرا … كانوا قرارات الكرم\nما حملت أمثالهم … يوما غوارب النعم\nكم فيهم لمطرد … من وزر ومعتصم\nكانوا ، إذا الخطب دجا … وجلجلت إحدى الغمم\nمأمنة من الردى … ونجوة من العدم\nإذا هم تيقظوا … فيها فقل للجار نم\nهم وسموا ما أغفل الن … اس على طول القدم\nإذا أذموا ضمنوا … على الزمان ما اجترم\nوأمنوا حتى على القل … قلوب من طارق هم\nأهل النصول والقنا … والمعطيات في اللجم\nوالسامر الهبهاب في … الظلماء والشرب العمم\nجن ، إذا تعانق الأ … بطال بالبيض الخذم\nفي حيث لا يلذنا … معتنق وملتزم\nمن كل مطوي على … عظيمة من الهمم\nمن عشقه يوم الوغى … يرى الطعان في الحلم\nمحمل الأعباء لا … يجرها من السأم\nعف ، فإن لم يحمه ال … ضيم سوى الظلم ظلم\nصاحت بهم على الردى … مسمعة على الصمم\nوانتزعت من عزهم … تلك العماد والدعم\nباطشة بلا يد … واعظة بغير فم\nوقبل ما كبت لها … قباب عاد وأرم\nفاليوم مرمى دارهم … لا كثب ولا أمم\nقل للعدو هربا … قد زخر الوادي وطم\nوشافهت أمواجه … ذرى القلال والأطم\nومن يكن تحت مجر … ر السيل يوما لا يقم\nتسومني الضيم ، لقد … نفخت في غير ضرم\nأما علمت أنه … من كان حرا لم يضم\nأبالمخازي أبدا … مدرع وملتثم\nثياب عار أبدا … فضفاضة على القدم\nتجزيك في الصبح وتس … تغني بها عن الظلم\nقبحت من خلائق … لئيمة ومن شيم\nيريد جهلا أن يسي … ء عامدا ولا يذم\nهيهات أعيا ما يري … د قبله على الأمم\nسيان من قبل عض … وا منكم ومن عذم\nومن سما بهامكم … إلى العلى ومن وقم\nجوامحا في العار لا … بنت عناق والرقم\nوالليث لا يخرج إ … لا محرجا من الأجم\nكلذعة الميسم في … شواظ نار وضرم\nوالحية الرقطاء تر … دي أبدا بغير سم\nحقا على أعراضكم … تعطها عط الأدم\nفاستنشقوها نفحة … تجدع مارن الأشم\nتقرض من جنوبكم … طم اللمام بالجلم\nكأنما تضرب في العر … ض الأعز بالقدم\nمذكورة ما بقيت … من غير عقد لرتم\nترى على عاري العظا … م وسمها وهي رمم\nفلو نزعت الجلد كا … ن رقمها كما رقم\nكم جردت شفارها … لحم فتى بلا وضم\nخابطة لا تتقي … صدم أخ ولا ابن عم\nتبيت من سماعها … تئن من غير ألم\nلتندمن بعدها … هيهات ، حين لا ندم\nكم سقم منك أتى … على عقابيل سقم\nسلكت في محجة … لا نهجا ولا لقم\nصلعاء لا يعطى الهدى … دليلها ، فلا جرم"},{"id":"diwan-radi:520","bookId":"diwan-radi","type":"poem","seq":520,"chapter":"البحر: مجزوء الرمل","title":"زار والركب حرام","page":"","text":"زار والركب حرام … أوداع أم سلام\nطارقا والبدر لا … يحفزه إلا الظلام\nبين جمع والمصلى … ريم سرب لا يرام\nوحلول ما قرى نا … زلهم إلا الغرام\nبدلوا الدور ، فلما … نزلوا القلب أقاموا\nيا خليلي اسقياني … زمن الوجد سقام\nوصفا لي قلعة الرك … ب ولليل مقام\nمن ألال حفزوا العي … العيس كما ريع النعام\nفزفير ونشيج … وعجيج ، وبغام\nومنى أين منى … ني ، لقد شط المرام\nهل على جمع نزول … وعلى الخيف خيام\nيا غزال الجزع لو كا … ن على الجزع لمام\nأحسد الطوق على … جيدك والطوق لزام\nوأعض الكف إن نا … ل ثناياك البشام\nوأغار اليوم إن … مر على فيك اللثام\nأنا عرضت فؤادي … أول الحرب كلام\nأن جعلت القلب مرمى … كثرت فيه السهام\nمن يداوي داء … ئك ، والداء عقام\nيا غياث الخلق ! أيا … مك في الأيام شام\nغرر واضحة الأع … لام والدهر ظلام\nأنت للدنيا وللدي … مساك ونظام\nوبهاء وضياء … وغياث ، وقوام\nإن أعداءك لما … قادهم ذاك الزمام\nورأوا أن طريق ال … مجد وعر وإكام\nواستطالوا الغاي حتى … جرجر الثلب العبام\nسلموا الثقل إلى العو … د فما ناء وقاموا\nمقرم إن قيد للور … د ، وقد حر اللطام\nحبس الأوراد بالغ … لة والحي قيام\nليس بدر إن بغى … أول من عز الحمام\nجامح أقعصه من … قائم العضب لجام\nكان ممن أسكرته … أمس ، هاتيك المدام\nونجا من زحمة المو … ت وللموت زحام\nطافيا تقذفه الغم … رة والماء جمام\nمنزع النبلة قد طا … ر بها الريش اللوأم\nعجمة طوحها المر … ضاخ ، والعجم رمام\nوإلى اليوم قذى نا … ظره ذاك القتام\nقدر العاجز أن … ل يخليه الهمام\nكان في معطسه ال … رغم وفى فيه الرغام\nأترى لم يكفه ما … لقي الخيل الطغام\nلا حديث القوم منس … ي ولا العهد قدام\nجاش واديك فسال … سيل ، والقوم نيام\nراكبا ظهرا من … ي ، مسيم ومسام\nخطم الأول والآ … خر يبغيه الخطام\nشمه رئبال غاب … أول الفرس شمام\nيا دليل المجد إن ض … ضل عن المجد الكرام\nوالذي يرعي بدار ال … عز ، والناس بهام\nلي مواعيد ، ووعد ال … غيب عقد وزمام\nلويت عني ، فيا لل … س هل ضن الغمام\nحبس القطر بأرضي … وأرى الجو يغام\nإنما اللوم لجدي … ما على الغيث ملام\nقد تيقظتم لأمري … لكن الجد ينام\nوعتاب القوم ألا … بالمعاريض خصام\nعجبا كيف نبا اليو … م بكفتي الحسام\nلا ذراعي رخوة الحب … ولا السيف كهام\nموضع الذم زماني … وخلاك اليوم ذام\nأيها الزارع سقيا … فبذا الزرع أوام\nإنما غرسك نبع … ومن الغرس ثمام\nعد بما عودتني … منك أياديك الجسام\nثم دم ما حسن العي … ش وما طاب الدوام\nآمرا تخدمك الأ … يام طوعا والأنام\nإنما الأقدار جند … لك والدهر غلام"},{"id":"diwan-radi:521","bookId":"diwan-radi","type":"poem","seq":521,"chapter":"البحر: وافر تام","title":"لهان الغمد ما بقي الحسام","page":"","text":"لهان الغمد ما بقي الحسام … وبعض النقص ، آونة ، تمام\nإذا سلك العلى سلمت قواه … فلا جزع ، إذا انتقص النظام\nوأهون بالمناكب يوم يبقى … لنا الرأس المقدم والسنام\nوما شكوى المناهل حين تمسى … مغيضة ، إذا بقي الغمام\nوهل هو غير فذ أخلفته … لك العلياء ، والنعم التؤام\nوما شرر تطاوح عن زناد … بمفتقد ، إذا بقي الضرام\nأفق يا دهر من أمسيت تحدو … وقد منع الخزامة والزمام\nقدعت مبرز الحلبات يغدو … جموحا ، لا ينهنهه اللجام\nولودا مثل ما خالست منه … وأنت بمثله أبدا عقام\nمن القوم الذين أقام فيهم … عداد المجد والعدد اللهام\nإذا سلموا فقد سلم البرايا … وإن نقدوا ، فقد فقد الأنام\nلهم كرم تزيده المعالي … إذا لؤم المعاشر ، أو ألاموا\nوأيام من الإحسان بيض … لهم نسب إلى العليا قدام\nمراجحة وأصبية ملوك … إليهم يعقد النادي الكرام\nوكل معمم بالمجد قضى … به ذمم العلاء أب همام\nربا بين الصوارم والعوالي … فجاء كأن توأمه الحسام\nيروع سوامه بالسيف حتى … تمنى أن اسرتها اللئام\nمعاشر للسوائم في ذراهم … أمان الطير آمنها الحرام\nيذم اللؤم عندهم عليها … وليس لجارهم أبدا ذمام\nوحادثة لها في العظم وقر … كفض السن ليس له التئام\nكفى بعتاتها ، والموت دان … وقد قعد الرجال بها وقاموا\nفقل للحائن المغرور أمسى … بمارنك الرغامة والرغام\nأتعلم من تخاطر ، أو تسامي … غرورا ما أراك به المنام\nفخل عن الطريق لسيل طود … تحدر لا يخاض ولا يعام\nألم يقنعك بالأهواز منه … قطار غيم عارضه القتام\nبأربق حط عارضه وأجلى … عن الأعداء والأعداء هام\nوأرسلها تخب بدار زين … عباب اليم لج به التطام\nيملن من اللغوب كما تهادى … نساء الحي يثقلها الخدام\nوكن ، إذا رمين إلى عدو … طلبن أمام حتى لا أمام\nولست لحاصن إن لم تروها … مواقر حملها بيض ولام\nتوقص تحتها القلل الروابي … وتجدع من حوافرها الإكام\nبنقع يظلم الإصباح منه … على بيض يضيء بها الظلام\nتفارط بالقنا متمطرات … كما فاجاك بالدو النعام\nحذار له فبعد اليوم يوم … له شرر ، وبعد العام عام\nوما ترك الرماء قصور باع … ولكن كي تراش له السهام\nفمنه البيض ماضية ، ومنكم … يد الدهر ، المفارق واللمام\nلنا تحت الصفائح كل يوم … مقيم لا يريم ولا يرام\nكرائم من قلوب أو عيون … عليهن الجنادل والرجام\nصموت لا يجاب لهن داع … أرن ولا يرد له سلام\nفدم ما طاب للباقي بقاء … وما حسن التلوم ، والدوام\nفلا كشف الضياء على الليالي … ولا عدم الغياث ولا القوام\nيكون لك التقدم في المعالي … وفي الأجل التأخر والمقام\nوكان لنا أمامك كل نقص … يكون من الردى ولك التمام"},{"id":"diwan-radi:522","bookId":"diwan-radi","type":"poem","seq":522,"chapter":"البحر: كامل تام","title":"وسمتك حالية الربيع المرهم","page":"","text":"وسمتك حالية الربيع المرهم … وسقتك ساقية الغمام المرزم\nوغدت عليك من الحيا بمودع … لا عن قلى ومن الندى بمسلم\nقد كنت أعذل قبل موتك من بكى … فاليوم لي عجب من المتبسم\nوأذود دمعي أن يبل محاجري … فاليوم أعلمه بما لم يعلم\nلا قلت بعدك للمدامع كفكفي … من عبرة ولو أن دمعي من دمي\nإن ابن موسى والبقاء إلى مدى … أعطى القياد بمارن لم يخطم\nومضى رحيض الثوب غير مدنس … وقضى نقي العود غير موصم\nوحماه أبيض عرضه وثنائه … ضم اليدين إلى بياض الدرهم\nوغنى عن الدنيا وكان شجى لها … إن الغني قذى لطرف المعدم\nملأ الزمان منائحا وجرائحا … خبطا ببؤسى في الرجل وأنعم\nواستخدم الأيام في أوطاره … فبلغن أبعد غاية المستخدم\nاليوم أغمدت المهند في الثرى … ودفنت هضب متالع ويلملم\nوغدت عرانين العلى واكفها … من بين أجدع بعده أو أجذم\nمتبلج كرما إذا سئل الجدا … مطر الندى أمما ، ولم يتغيم\nجذلان تطلع منه أندية العلى … وجها كريم الخد غير ملطم\nيرمي المغارم بالتلاد وينثني … ثلج الضمير ، كأنه لم يغرم\nالواهب النعم الجراجر عادة … من ذي يدين إذا سخا لم يندم\nجاءت بها حمر الربيع مشيدة … حمراء تحسبها عروق العندم\nمتبقلات باللديد ورامة … بين القنا المنزوع والمتلهذم\nبيدي أغر يرد ألوية القنا … غب الوقائع ، يعتصرن من الدم\nويقول للنفس الكريمة سلمي … يوم اللقاء ولا يقول لها أسلمي\nهتف الحمام به فكان وصاته … بذل الرغائب واحتمال المغرم\nهل يورث الرجل الكريم إذا مضى … إلا بواقي من على وتكرم\nيأبى الندى ترك الثراء على الفتى … ويقل ميراث الجواد المنعم\nملأت فضائلك البلاد ونقبت … في الأرض يقذفها الخبير إلى العمي\nفكأن مجدك بارق في مزنة … قبل العيون ، وغرة في أدهم\nأنعاك للخيل المغيرة شزبا … خبط المغار بهن من لم يجرم\nكالسرب أوجس نبأة من قانص … فمضى يلف مؤخرا بمقدم\nواليوم مقذ للعيون بنقعه … لا يهتدي فيه البنان إلى الفم\nلم يبق غير شفافة من شمسه … كمضيق وجه الفارس المتلثم\nمن خائض غمر الدماء يبله … بل الندى مطر القنا المتحطم\nأو ناقش من جلده شوك القنا … عن كل فاغرة كشدق الأعلم\nأو مفلت حمة السنان نجت به … روعاء لا تدع العذار لملجم\nينزو به الفرع الكذوب ويتقي … مر الحديث بكل يوم أيوم\nويروعه وصف الشجاع لطعنة … من ذابل أو ضربة من مخذم\nحتى يظن الصبح سيفا منتضى … أهوى إليه مع الكمي المعلم\nومقاوم عرض الكلام بروده … فيهن بين معضد ومسهم\nأغضى لها المتشدقون وسلموا … لهدير شقشقة الفنيق المقرم\nبالرأي تقبله العقول ضرورة … عند النوائب لا بكيف ولا لم\nحمل العظائم والمغارم ناهضا … ومضى على وضح الطريق الأقوم\nحتى إذا أرمى الجذاب ملاطه … وأوى الزمام لأنفه والملطم\nطرح الوسوق فلم يدع من بعده … عند العظيمة حاملا للمعظم\nكالنقض قد عرك الدؤوب صفاحه … عرك الضباع من العنان المؤدم\nرقد الملوك بحزم أبلج رأيه … فلق لعاشية العقول النوم\nتنفض عنه النائبات كأنها … وبر الموقع نش تحت الميسم\nكانوا إذا قعد البكار بثقلهم … قالوا لذا العود الجلال : تقدم\nعمري لقد قذفوا الكروب بفارج … منه وقد رجموا الخطوب بمرجم\nفكأنما قرعوا القنا بعتيبة … ولقوا العدا بربيعة بن مكدم\nرقاء أضغان يسل شباتها … حتى يغير طبع سم الأرقم\nسبع وتسعون اهتبلن لك العدا … حتى مضوا وغبرت غير مذمم\nلم يلحقوا فيها بشأوك بعد ما … أملوا ، فعاقهم اعتراض الأزلم\nإلا بقايا من غبارك أصبحت … غصصا وإقذاء لعين أو فم\nإن يتبعوا عقبيك في طلب العلى … فالذئب يعسل في طريق الضيغم\nهل من أب كأبي لجرح ملمة … أعيا ، وشعب عظيمة لم يلأم\nإن الخطوب الطارقات فجعننا … بحمى الأبي وجنة المستلئم\nبممهل في الغابرين مؤخر … ومحفز في السابقين مقدم\nالطاهر ابن الطاهرين ومن يكن … لأب إلى جذم النبوة يعظم\nمن معشر اتخذوا المكارم طعمة … ورووا من الشرف الأعز الأقدم\nمن جائد أو ذائد أو عاقر … أو ماطر أو منعم أو مرغم\nوفروا على المجد المشيد همومهم … وتهاونوا بالنائل المتهدم\nعيص ألف تقابلت شعباته … في المجد ، شجر مقوم لمقوم\nيتعاورون المكرمات ولادة … من بين جد في المكارم وابنم\nقد قلت للحساد حين تقارضوا … حرق القلوب جوى وحرق الأرم\nلا تحسدوا المترادفين على العلى … والغالبين على السنام الأكوم\nوالطاعنين بكل جد مدعس … والماطرين بكل نيل مرزم\nلكم الفضول إذا تكون وقيعة … أو غارة ، ولهم صفي المغنم\nعطرون ما لأنوفكم من طيبهم … بين المجامع غير شم المرغم\nيتساندون إلى على عادية … ومكارم قدم ومجد قشعم\nمتزيدين إلى السؤال ، وعندكم … أم العظاء ، مفذة لم تتئم\nفتعلقوا عجب المذلة واتركوا … رفع العيون إلى البناء الأعظم\nتلك الأسود فمن يجر فريسها … أم من يمر بغابها المتأجم\nحطت بأطراف البلاد قبورهم … رقم النجوم سقوف ليل مظلم\nوكفاك من شرف القبيل بأن ترى … بدد القبور لمنجد أو متهم\nعدوا جبالا للعلاء ، وإن غدوا … أمشاج مجد في رمائم أعظم\nوضعت بتلك صفايحا وضرايحا … أثقال أوطف بالرعود مزمزم\nوسقت ثراهن الدموع مرشة … فغنين عن قطر الغمائم والسمي\nجدث ببابل أشرجت رجماته … طبقا على مطر الندى المتهزم\nضمن السماحة في ملاث أزاره … والمجد في نواره المتكمم\nلا تحسبن جدثا طواه ضريحه … قبرا ، فذاك مغار بعض الأنجم\nأعريت ظهري للعدا ولو اتقى … بزهاء مزدحم العديد عرمرم\nوكشفت للأيام عورة مقتلي … حتى رددن علي بعدك أسهمي\nقد كنت ما بيني وبين سهامها … فاليوم لا يخبطن شاكلة الرمي\nهل تسمعن من الزمان ظلامتي … فيما جنى ، وإلى الزمان تظلمي\nقل للنوائب لا أقيلك عثرة … فتشزني لوقائعي واستسلمي\nلا تصفحن عن الملم إذا جنى … وإذا المضارب أمكنتك فصمم\nفالغمر من ترك الجزاء على الأذى … وأقام ينظر عذرة من مجرم\nومحوكة كالدرع أحكم سردها … صنع فافصح في الزمان الأعجم\nعضلتها زمنا لأطلب كفؤها … وزففتها لك نعم بعل الأيم\nإني نزلت وكنت غير مذلل … بيت المهان وأنت عين المكرم"},{"id":"diwan-radi:523","bookId":"diwan-radi","type":"poem","seq":523,"chapter":"البحر: رمل تام","title":"أعلى الغور تعرفت الخياما","page":"","text":"أعلى الغور تعرفت الخياما … ولدار الحي ملهى ومقاما\nمنزل من آل ليلى لم يدع … ولع الدهر به إلا رماما\nحبذا الدار وإن لم يلقنا … قاطن الدار بها إلا لماما\nمن رأى البارق في مجنوبة … هبة البارق قد راع الظلاما\nكلما أومض من نحو الحمى … أقعد القلب من الشوق وقاما\nما على ذي لوعة نبهه … بارق من قبل الغور فشاما\nيا خليلي انظرا عني الحمى … إن طرف العين بالدمع أغاما\nطال ما استسقوا لعيني دمعها … أينما استسقيت للدار الغماما\nأخلق الربع ، وأثواب الهوى … مستجدات ولوعا وغراما\nآه من برق على ذي بقر … نبه الشوق على القلب وناما\nكم رعينا العيش فيه ناضرا … ووردنا أول الحب جماما\nوغريمي صبوة قد قضيا … بعض دين الشوق ضما ولزاما\nيا قوام الدين قدها صعبة … لم تكن تتبع من قبل الزماما\nأنت فينا هضبة الله التي … زادها قرع المقادير التئاما\nويد للدهر موهوب لها … إن أساء الدهر يوما وألاما\nما يضر القوم أوقظت لهم … أن يكونوا عن حمى العز نياما\nمنبت تحرز عن أعراقه … حسب لا يقبل العار قداما\nإرث آباء علوا ، فاقتعدوا … عجز المجد ، وأعطوك السناما\nأمطروا الجود مضيئا بشرهم … فرأيناهم شوسا وغماما\nشغلوا قدما عن الناس العلى … ورموا عن ثغر المجد الأناما\nمعشر تموا فلم ينثلموا … ثلم الأقمار ينظرن التماما\nكحميا الطود رأيا وحجا … ورماح الخط غربا وقياما\nافرج المجد لهم عن بابه … ولقى الأعداء ضعفا وزحاما\nغائب مثلك من شهاده … ما قضى العمر ولا ذاق الحماما\nلم يعش من عاش مذموما ولا … مات أقوام إذا ماتوا كراما\nيعظم الناس ، فإن جئنا بكم … كنتم الراعين والناس سواما\nأو لم ينه العدا في أربق … لجب قاد الجماهير العظاما\nلججا يلغط فيهن القنا … لغط الأوراد دفعا ولطاما\nيوم ولى قومه في هوة … مستغر دمر الجيل الطغاما\nمستعيرا هامهم يحسبها … جفنات الحي ينقلن الطعاما\nشهد الروع فلم يعط القنا … نهز الطعن ولم يرض الحساما\nونجا الغاوي يفدي مهره … خزي الموقف قد ليم ولاما\nطرح الدرع ذميما واتقى … بمطاه الطعن شما وعراما\nيستزيد الطرف حتى لو رأى … مهلة الواقف قد ألقى اللجاما\nخلفة وطفاء يمريها الردى … مطر الطعن رذاذا ورهاما\nدأبها في دار زين تنتحى … شلة الطارد بالدو النعاما\nبتن بالشد يخرقن الثرى … دلج الليل ويرقعن القتاما\nخلت أيديهن في معزائها … أنمل الولدان يفلين اللماما\nجاذبت فرسانها أعناقها … كلما نهنهن طالبن أماما\nوليالي السوس صبحت بها … صائحا يسقي دم الطعن مداما\nتضمن الأعناق للسيف ، إذا … أخفر السيف على الدرع الذماما\nرشتم سهمي ، وضاعفتم له … عقب النعماء والريش ، اللواما\nكل يوم نعم مشفوعة … لاحقات وتوال وقداما\nأصبحت عندي ولودا ناتجا … يوم تغدو نعم القوم عقاما\nمثل رشق النبل إلا جرحها … تبرد الغل وتستل الأواما\nكلما شيخ عندي ضيفها … رجعته جدد الطول غلاما\nيا جزت عني الجوازي معشرا … ملكوا الورد ، فأعطوني الجماما\nجئتهم في جفوة الدهر فلا … أوصدوا الباب ولا لطوا القراما\nضرب العز عليهم بيته … ثم ألقى الرحل فيهم ، وأقاما\nوعمرتم آمني ريب الردى … يمطل الخطب بكم عاما فعاما\nكلما خف إليكم حادث … غلط النهج ولم يعط المراما\nما رأينا سلكها من غيركم … جمع النشر ، ولا ضم النظاما\nلا طوت عنا الليالي من غدا … للورى غيثا وللدين قواما\nكلما رحلت اليوم فتى … نوب الأيام زادتك مقاما"},{"id":"diwan-radi:524","bookId":"diwan-radi","type":"poem","seq":524,"chapter":"البحر: سريع","title":"يا من رأى البرق على الأنعم","page":"","text":"يا من رأى البرق على الأنعم … يطوي بساط الغسق المظلم\nمحمرة منه كفاف الدجى … نضح جراح الفرس الأدهم\nقام نساء الحي يقبسنه … نارا من الإيماض لم تضرم\nتطاول المنجد ضنا به … وقد عطا للبلد المتهم\nحتى رمى الإصباح في ليلة … لفت إزار الرجل المحرم\nلا جاز مغناهم بذات النقا … قطر الغوادي وطلال السمي\nولوا على قلبي عنيف الجوى … يعاقب القلب ، ولم يجرم\nالله في طرف بكم دامع … دام ، وقلب بكم مغرم\nلا يتعب العاذل في حبهم … قد ذهب السهم بقلب الرمي\nعيني مع اليقظى غراما بهم … وعين من يلحى مع النوم\nلولا قوام الدين ما استوسقت … أعناقها في السنن الأقوم\nولا أينا النجم ذا خفية … من قارع الحافر والمنسم\nيغير للمجد إذا غيره … أغار للسلة والمغنم\nلا يصحب الأغماد من لم تزل … سيوفه في حلل من دم\nلله نعل حذيت في العلى … أخمص ذاك العارض المرزم\nيود لو أصبح شعسا لها … نجاد عنق الملك الأعظم\nأغر من غر ربوا في العلى … وأفصحوا بالكرم الأعجم\nبنوا على مضطربات القنا … بناء عز غير مستهدم\nتشب بالمندل نيرانهم … لطارق الليل ، ولم يظلم\nلا يدفع الأضياف منهم إلى … ممنون زاد وقرى معتم\nقلت عيون الناس عن نيلهم … فعوذوا من أعين الأنجم\nأساود تنتجها في العلى … أسد إلى أمثالها تنتمي\nفيخرج الأرقم من ضيغم … ويخرج الضيغم من أرقم\nسميت الغبراء في عهدهم … حمراء من طول قطار الدم\nتحمر منها كل مخضرة … كأن لا نبت سوى العندم\nكل فتى يفضح أطواقه … وجه مضيء الجيد والملطم\nللبشر في ديباجه لامع … طراز عصب اليمن المعلم\nقوم رباط الخيل في دورهم … كالبهم في غامد أو يقدم\nمن كل محبوك القرا محصف … أمر فتل الرسن المبرم\nكأنه ينظر مستوجسا … ربيئة قام على مخرم\nمتى أراها كذئاب الغضا … تحرض الهائب بالمقدم\nأعنة الفرسان أعرافها … عجلى عن المسرج والملجم\nمن فارس يحمل أسد الشرى … لملتقى يوم ردى أيوم\nترمي جبال لثلج من قدحها … نار الوغى بالشرر المضرم\nأرعن قد كدر ماء الحيا … في مزنه بالرهج الأقتم\nيوم يود القرن لو أنه … يزيد في الرمح من المعصم\nكم قلة ممتنع طودها … إلا على ذي الجدد الأعصم\nقد أمست الخيل ضيوفا بها … للوعل العاقل والقشعم\nثلمتها كيدا ، وكم شابكت … أيدي المقادير ولم تثلم\nيخال باقي روق أطوادها … باقي أنياب فم الأهتم\nقد ينفذ الحلم على غرزة … بمحفظات الغادر المجرم\nوطول نزف النغب يفنى به … غمر جمام الغدق المفعم\nأقدم للحين ويا ربما … أجلى الوغى ، والغنم للمحجم\nيسلم كعب الرمح مستأخرا … ويوقع الأقدام باللهذم\nما كان إقداما ولكنه … تسرع العير على الضيغم\nولى ، وقد أردف هدارة … يقظى على الليل لغوط الفم\nلا يؤمنن ، بعد كلال الشبا … كم صائل بالساعد الأجذم\nقد يهلك النسر وفي ريشه … عون الردى الجاري مع الأسهم\nيثمر المال ويأبى الغنى … إلا من الذابل والمخذم\nلا يدخر الضيغم من قوته … ما يدخر النمل من المطعم\nلا تستشر غيرك في كيها … قد بلغ الداء إلى الميسم\nواخطب على سيفك بكر العلى … فقد تملأت من الأيم\nحسامك النصر ، فصمم به … ودرعك الإقبال ، فاستلئم\nلا يصلح الناس لأربابهم … غير بياض السيف والدرهم\nيا ملبسي النعمى التي أورقت … عودي مرارا وكست أعظمي\nومطلعي في رأس عادية … تخسأ طرف الجذع الأزلم\nنزع العلى عني كإلباسها … والغنم بالبذلة كالمغرم\nأكرم عنها ، وبها مرة … كلاهما عندي من الأنعم\nوكيف نوم المرء من تحته … دون الكرى مضطرب الأرقم\nبين خصافي نعله شوكة … إن شدد الوطء عليها دمي\nفأملك بها رقي وحرر بها … عنقي ، ورق الحر للمنعم\nوحز بها ما بقي العمر لي … صفاء قلبي ، وصفايا فمي\nغوثك منها ياغياث الورى … قد ثقل العبء على المهرم\nصونوا بها عرضي ووجهي معا … صونهما في الزمن الأقدم\nلا تحسبوا أني على جرأتي … أحجمت حتى ضاق لي مقدمي\nما لان عودي في يدي غيرها … يوما ولا خار على معجم\nعطفا علينا أن يقول امرؤ : … إن علوق المجد لم ترأم\nيخدع بالشهد مذاق الفتى … وربما آل إلى العلقم\nعظيمة ناديت من ثقلها … بالبازل الناهض بالمعظم\nعادات إحسانك أمثالها … قد لؤم الدهر بها ، فاكرم\nوطل وصل واعف وهب وانتقم … وابق ودم واعل وثب واسلم"},{"id":"diwan-radi:525","bookId":"diwan-radi","type":"poem","seq":525,"chapter":"البحر: بسيط تام","title":"أحق من كانت النعماء سابغة","page":"","text":"أحق من كانت النعماء سابغة … عليه من أسبغ النعمى على الأمم\nواجدر الناس أن تعنوا الرقاب له … من استرق رقاب الناس بالنعم\nإذا سما فإلى العلياء نهضته … وإن مشى فعلى الأعناق والقمم\nلله أم تلقته براحتها … ماذا تلقت إلى الدنيا من الكرم\nفي صبية للمعالي كان أولعهم … بالمكرمات ، وألقاهم إلى الديم\nكم غبت عنه ، وما غابت مكارمه … ونمت عنه بآمالي ولم ينم\nلا يتبع المال أنفاسا مصاعدة … ولا يعير العطايا زفرة الندم\nيا ممرضا بالمساعي قلب حاسده … على العلا ومداوي الفقر والعدم\nأقبلتها بسياط العزم تحفزها … للطعن ، لا بعراك العذر واللجم\nمن دومة بجبال الغور حاملة … حقائب الموت للأعداء والنقم\nعلى قطاهن صدارون عن نهل … من القواضب ورادون للقحم\nطريدة للعلى جلى فادركها … بعد المطال ، جناح الأجدل الضرم\nأقام سوق المساعي وهي بائرة … مجال عزمك بين السيف والقلم\nففي النزال يد حمراء من علق … وفي النوال يد بيضاء من كرم\nأعيا الرجال وإن عزوا وأن كرموا … مكان كفيك فيها من ندى ودم"},{"id":"diwan-radi:526","bookId":"diwan-radi","type":"poem","seq":526,"chapter":"البحر: طويل","title":"لكم حرم الله المعظم لا لنا","page":"","text":"لكم حرم الله المعظم لا لنا … وبطحاؤه والأخشبان وزمزم\nوما رد شعب المأزمين على منى … وجمع وما وارى الستار المحرم\nلئن لم تصبحكم با مستغيرة … كصكة أنف المرء يتبعها الدم"},{"id":"diwan-radi:527","bookId":"diwan-radi","type":"poem","seq":527,"chapter":"البحر: رجز تام","title":"ثورتها تنتعل الظلاما","page":"","text":"ثورتها تنتعل الظلاما … لا نقو أبقين ولا سلامى\nقودا ، إذا الليل بها ترامى … مرقن من ظلمائه سهاما\nترجع الحنين والبغاما … شكوى المريض ماطل السقاما\nأعلقتها من الندى زماما … لا واهن العقد ولا رماما\nأي غياث الخلق والقواما … إن بأرجان لنا غماما\nها أوشكي أن تردي الحماما … غمرا يزيد لجه التطاما\nإن ناطح الأكراد والأرواما … يروح الإحسان والإنعاما\nإذا الرجال روحوا الأنعاما … قوم درء الدين فاستقاما\nقد ولد المجد له تماما … إذا رأينا الملك الهماما\nنرى سريرا يحمل الأناما … والسؤدد القدامس القداما\nإن على أعواده الضرغاما … تخدج من هيبته السلاما\nتعنو الملوك حوله إعظاما … نستكثر اليوم له القياما\nأسدا تراها عنده بهاما … شلت يد الجاذب ماذا راما\nمن بازل قد منع الخطاما … وأعجز الوراك والزماما\nلا يعرف الرحل له سناما … ولى الأعادي منكبا حطاما\nيوم الضغاط يأمن الزحاما … من معشر تفرعوا الأعلاما\nمطاولا مجدهم الأياما … حلوا القصور البيض والأطاما\nيخالطون الشرب والمداما … والعازفات الغر والندامى\nكرائما لاقينهم كراما … حتى إذا يوم الردى أغاما\nمحتزما قد لبس القتاما … رأيتهم ضراغما تسامى\nعلى الجياد تعلف الإلجاما … في البيد لا ظل ولا خياما\nغدوا يبارون بها النعاما … مرابعين الحامل الهمهاما\nمن كل أقنى ينفض اللجاما … كالنصل إلا الفوق واللؤاما\nإن قعد الخطب إليه قاما … حتى يروي الرمح والحساما\nيقظان مذ ذم الكرى ما ناما … قد بعثوه شائما ، فشاما\nمن مقبس المجد لهم ضراما … جاء به يضطرم اضطراما\nحلوا الحبى بلغتم المراما … سعي كفى الآباء والأعماما\nكم قلدوني النعم الجساما … سوابغا ترفع لي الأعلاما\nأمطوني الغارب والسناما … وطال ما غاظوا بي الأقواما\nوجددوا الأحقاد والأوغاما … هم قدموني في العلى اماما\nوأخروا عن غايتي الإقداما … فذا من النعماء أو توآما\nكالسلك ضاعفت به النظاما … إلى م مد بحركم إلى ما\nملئتم النعماء والدواما … عاما على رغم العدا ، فعاما\nتماطلون القدر والحماما … شمل الثريا ضمن المقاما\nطوق الهلال لا يرى انفصاما … لا روع الدهر لكم سواما\nيوما ولا فض لكم نظاما … حتى يلاقي يذبل شماما"},{"id":"diwan-radi:528","bookId":"diwan-radi","type":"poem","seq":528,"chapter":"البحر: منسرح","title":"يا دهر ماذا الطروق بالألم","page":"","text":"يا دهر ماذا الطروق بالألم … حام لنا عن بقية الكرم\nإن كنت لا بد آخذا عوضا … فخذ حياتي ودع حيا الأمم\nلا در در السقام كيف رمى … طبيب آمالنا من السقم"},{"id":"diwan-radi:529","bookId":"diwan-radi","type":"poem","seq":529,"chapter":"البحر: طويل","title":"ولا مثل ليلي بالشقيقة والهوى","page":"","text":"ولا مثل ليلي بالشقيقة والهوى … يضم إلى نحري غزالا منعما\nخلوت بكالغصن المرنح فتحت … أعليه غب القطر نورا مكمما\nوأبيض براق النظام كأنه … حصى برد لو أنه نقع الظما\nفسقيا لألمى ذي غروب تخاله … غزالا رعى بالني مردا وعظلما\nولا نعم الحمر الشفاه كأنما … تبطن داء أو ولغن بها دما\nأحبك يا لون الشباب ، لأنني … رأيتكما في القلب والعين تؤأما\nسواد يود البدر لو كان رقعة … بجلدته ، أو شق في وجهه فما\nلبغض عندي الصبح ما كان مشرقا … وحبب عندي الليل ما كان مظلما\nسكنت سواد القلب إذ كنت شبهه … فلم أدر من عز من القلب منكما\nوما كان سهم الطرف لولا سواده … ليبلغ حبات القلوب إذا رمى\nإذا كنت تهوى الظبي المى فلا تعب … جنوني على الظبي الذي كله لمى"},{"id":"diwan-radi:530","bookId":"diwan-radi","type":"poem","seq":530,"chapter":"البحر: سريع","title":"يا قلب ما أطول هذا الغرام","page":"","text":"يا قلب ما أطول هذا الغرام … يوم نوى الحي ويوم المقام\nفي القرب ليان ديون الهوى … وفي نوى الدار رجيع السقام\nمقيمة عندك أشجانهم … ولا يلاقونك إلا لمام\nلم ينقعوا الظمآن من غلة … ولم يبالوا طرب المستهام\nمتى تفيق اليوم من لوعة … وأنت نشوان بغير المدام\nصبابة ، والحي قد قوضوا … عن جانب الغور عماد الخيام\nسقى المغاني بجنوب النقا … ماء المآقي ثم ماء الغمام\nوزائر زار على نايه … بعد الأسى عاد بعيد الغرام\nأمنزل عند عقيق الحمى … ومضجع عندي بأعلى الشآم ؟\nزيارة زورها خاطري … ما أقنع النفس بزور المنام\nخدائع أغضي على علمها … لعلها تنقع هذا الأوام\nيا قاتل الله الغواني لقد … سقينني الطرق بعيد الجمام\nأعرضن عني حين ولى الصبا … واختلج الهم بقايا العرام\nوشاعت البيضاء في مفرقي … شعشعة الصبح وراء الظلام\nسيان عندي أبدت شيبة … في الفوج أو طبق عضب حسام\nألقى بذل الشيب من بعدها … من كنت ألقاه بدل الغلام\nترى جميم الشيب لما ذوى … يراجع العظلم بعد الثغام\nكم جدن بالأجياد لي والطلى … فاليوم يبخلن برد السلام\nوكنت إن أقبلت اسمعنني … قعاقع الحلى وراء القرام\nأيام أغدو والصبا مقودي … أسلس للقائد طوع الزمام\nفي فتية تحسبهم لثموا … على العرانين بدور التمام\nتخال أثوابهم في القنا … من شطط الخلق ومط القوام\nإذا دعوا والورد مستوبل … دفوا إلى الطعن دفيف النعام\nوظاهروا النقع على زغفهم … ورجلوا بالدم سود الجمام\nوصاحب في الحي جثامة … معانق الخفض بطيء القيام\nلباسة للعار لا يأنف ال … ل ولا يألم حر اللطام\nقد عاقد العجز على أنه … يهون في الضيم بطول الملام\nلا يعقد المئزر في حادث … ولا يرى النصر ولو بالكلام\nناب إذا جربته في العدا … وهو على عنقي ماض هذام\nإذا رأى وطفاء علوية … أيقظني شائم برق ونام\nمن معشر شبوا على إحنتي … وأوجروا بغضي عند الفطام\nأقارب إن وجدوا غمرة … راشوا إلى قلبي مرط السهام\nويعرقوني بالأذى كلما … لان لهم مسي عرق العظام\nجوارهم مثل نسيم الصبا … وغيبهم مثل أجيج الضرام\nسماؤهم تشمس بي كلما … أظلم جو ، وبجودي تغام\nسيذكروني إن نبا جانب … من العدا وانحل عقد الزمام\nوأصحرت أعراضهم للأذى … تصرد فيهن نبال المرام\nمن لهم مثلي ، إذا استزلقت … أقدامهم يوم ذليل المقام\nمن لهم مثلي ، إذا أصبحوا … بعارض يهضب بيضا ولام\nوشلت الأرماح من أرضهم … طرد الغواني بعد طرد السوام\nوالخيل تستلدغ شوك القنا … في يوم لا ظل بغير القتام\nكأنها سيل مضيق له … دون الثنايا زجل وازدحام\nلأطعمن الليل عيدية … ضابعة تكسو البرى باللغام\nمثل نعام الدو هاها به … مع الدجا بارق حي ركام\nآليت لا أحفل في نصها … إن مرج الغرض ورث الخطام\nفوق ذراها كصدور القنا … مخلصة من كل عاب وذام\nعلي ألاقي بعد إطراده … حظي أو أبلغ بعض المرام\nيا دهر كم تحدو بذي نقبة … معترق الني أجب السنام\nبصفحتيه جلب قرفت … من الليالي وكلوم دوام\nقد أغبط الميس على عقره … مع نقب المنسم عاما ، فعام\nفي كل يوم ناشد همة … أضلها العاجز في ذا الأنام\nيعض كفيه على حظه … ويسأل الدهر حظوظ اللئام\nيجر طمري عدم فيهما … معذل يفعل فعل الكرام\nلا ضائع في الدهر من ذلة … ولا خذول الرجل يوم الزحام\nلو أنصف الدهر لأوفى به … على رقاب من رجال وهام\nوما انتفاع المرء يمسي له … جد وراء ، وطلاب أمام\nوكان راعي كل ترعية … في الناس ، أو كان إمام الإمام"},{"id":"diwan-radi:531","bookId":"diwan-radi","type":"poem","seq":531,"chapter":"البحر: وافر تام","title":"لعمر الطير يوم ثوى ابن ليلى","page":"","text":"لعمر الطير يوم ثوى ابن ليلى … لقد عكفت على لحم كريم\nوإن قنا العدا ليردن منه … دما لم يجر في عرق لئيم\nكأن الرمح يصدر منه عدوا … عن الأجمي ذي اللبد الكليم\nوأقسم أن ثوبك ، يا ابن ليلى … لمجموع على عرض سليم\nرزئتك كالوذيلة لم تمتع … بها ، بعد الوجود ، يد العديم\nتنام ، وتترك الأضغان يقظى … خماشات الذوابل في تميم\nإذا نزعوا الملابس أذكرتهم … دخول يديه آثار الكلوم\nومن مطل الديون أعد صبرا … على عنت المطالب والغريم\nتداعت لي بمصرعه الليالي … وأوعبت النوائب في أديمي\nونابت رأسي الوفرات حتى … تطأطأ ، حنوة الرجل الأميم\nوتقترن القوارع في جناني … قران النبل في الغرض الرجيم\nأأجزع إن حطمن حجاز أنفي … وهن يقصن أعناق القروم\nوما لي أراع ، وقد رمتني … يد الجلى بقارعة التميمي\nأحن إليه ، واللقيا ضمار … حنين العود للوطن القديم\nوأنشده ، وأعلم أين أمسى … مطالا للبلابل والهموم\nكأدماء القرا نشدت طلاها … وما وجدان جازية بغوم\nتطيع اليأس ثم تعود وجدا … إليه بالمقصة والشميم\nيعارضني بذكرك كل شيء … عداد الداء غب على السليم\nأجدك أن ترى بعد ابن ليلى … طعانا بين رامة والغميم\nولا نقعا يثور على مغير … ولا بيتا يظل على مقيم\nولا لج الصهيل مسومات … مججن دما على علك الشكيم\nجعلن ثياب بذلتها الدياجي … وقسطلها غمادا للنجوم\nولا أسلا إسنتها ظماء … منعن منابت الكلإ العميم\nولا عودا من الأحساب يمسي … نقي الليط من عقد الوصوم\nفكان كلبدة الضرغام عزا … إذا ذل الموقع للخصوم\nإذا أرعى بأرض لم تجده … يشارك في الجمام وفي الجميم\nأأرجو للحواضن كابن ليلى … أحلت ، إذا ، على بطن عقيم"},{"id":"diwan-radi:532","bookId":"diwan-radi","type":"poem","seq":532,"chapter":"البحر: متقارب تام","title":"ضربن إلينا خدودا وساما","page":"","text":"ضربن إلينا خدودا وساما … وقلن لنا اليوم موتوا كراما\nولا تبركوا بمناخ الذليل … يرحله الضيم عاما ، فعاما\nإلى كم خضوع لريب الزمان … قعودا ، ألا طال هذا مناما\nولا أنف تحمي لهذا الهوان … ولا قلب يأنف هذا المقاما\nفإن رابكم ما يقول النصيح … فسالوا القنا واستشيروا الحساما\nوأدنوا العليق إلى المقربات … تقل لكم ليس إلا اللجاما\nتيقظتم لدفاع الخطوب … فلم تتركون الأعادي نياما\nألسنا بني البيض من هاشم … أعز جنابا وأوفى ذماما\nوما تفتلينا المنايا غلاما … يؤمل إلا افتلينا غلاما\nلنا كل مغترب في العلا … ء لا يطرق الحي إلا لماما\nوقد كان إن شم ضيما أبى … فمن أين علم هذا الشماما\nإلى الطائع العدل أعملته … سوم القطا يدرعن الظلاما\nكأني أروع بها جنة … إذا التبست بالدجا أو نعاما\nيقول الرفاق ، إذا رجعت … من الأين جرجرة أو بغاما\nلك الله جعجع بإنضائهن … تعف السنام وتنق السلامى\nإلى أين خلفي أثني العنان … إذا ما وجدت أمامي إماما\nإذا ما أنخنا إلى ابن المطيع … حمدنا السرى وأطلنا المقاما\nإمام ترى سلك آبائه … بعيد الرسول ، إماما إماما\nيعد لعليائه هاشما … إذا ما الأذلاء عدوا هشاما\nمن الراكزين كالرماح الطوا … ل ، والرافعين العماد العظاما\nإذا ما بنوا بيت أكرومة … أطالوا السموك ومدوا الدعاما\nمع الشمس قد فرشوه نجوما … من العز أو ظللوه غماما\nكأنك تلقى بدورا تضيء … إذا طلعوا أو قروما تسامى\nهم استيقظوا وحدهم للخطوب … فقاموا بها ، وأناموا الأناما\nلهم نسب كاشتباك النجوم … ترى للمناقب فيه ازدحاما\nمضيء كشعشعة المشرفي … ينفي الظلام ويأبى الظلاما\nيزر السماح عليه الشفوف … ويلبسه العز بيضا ولاما\nعليه من الصطفى لامع … يميط الأذى ويجلي القتاما\nإذا أنشأوا للعدا عارضا … أسال بواديهم أو أغاما\nوباتوا قد اكتحلوا بالطعان … وقد رجلوا بالنجيع الجماما\nوطارت بقلبهم المقربا … ت تركب أعقابهن القداما\nوقد طوح الألمعي العنان … من الروع ، والأعوجي الحزاما\nكأن الرماح بأعجازها … يمانية تستهل الغماما\nشواح من الطعن أفواهها … كما جرت الناصحون الجلاما\nرموا في بيوتهم جمرة … أطالوا القعود لها والقياما\nإذا ذكروا الوتر حزوا الرقاب … وإن ذكروا العفو جزوا اللماما\nعلاؤك أعظم من أن يرام … ومجدك أمنع من أن يضاما\nوأنت المعظم في هاشم … إذا ما بدا بادؤوه قياما\nوأخلوا له معشبات العلا … ء يرعى الجميم ويسقى الجماما\nمشيت الراح وراح الذليل … ل يوصد بابا ، ويرخي قراما\nوما كنتم ، الدهر ، إلا الرعاة … ولا سائر الخلق إلا السواما\nحلفت بها كقسي النبا … ع تحسب أعناقهن السهاما\nكحافلة المزن آنستها … مسمحة في قياد النعامى\nوكل فنيق إلى ناقة … يساقطها زبدا أولغاما\nوكل ابن ليل على مقرم … إذا ما ونى زاغ منه الزماما\nوللرحل لحيان في دفه … إذا اجلوذ الليل لاك السناما\nيبيت كأن به أولقا … من السير ، أو خابلا ، أو عداما\nيؤدي أشيعث جم الهموم … حراما يزاول أرضا حراما\nكنصل اليماني أبلى القراب … وما أضمر الغمد منه كهاما\nيبين للمجد في وجهه … سفورا ، ولم ينض عنه اللثاما\nوكب الهدي لأذقانه … يؤم به زمزما والمقاما\nتخال النجيع لهذا صدارا … إذا ما جرى ولهذا زماما\nلأنتم أعز على مهجتي … من الماء ينقع منه الأواما\nوإني ، وإن كنتم في البلا … د أنأى ديارا وأبدى خياما\nأليس أبوكم أبي ، والعروق … تخلط لحمي بكم والعظاما\nنبتنا معا ، فالتقينا عروقا … بارض العلى واختلطنا رغاما\nإذا عمم المجد هاماتكم … كفاني لوثا به واعتماما\nلئن كان شخصي في غيركم … فإن لقلبي فيكم مقاما\nوإن لساني لكم والثناء … وإن ولوعي بكم والغراما\nوكنت زمانا أذود الملوك … عن السلك رقرقت فيه النظاما\nأريد الكرامة لا المكرمات … ونيل العلى لا العطايا الجساما\nفحوزوا العقائل عن خاطري … إلى م أماطل عنها إلى ما\nلقد طال عتبي على ناظر … رأى بارقا غير دان فشاما\nإلى كم أجدد وجدي بكم … وأعلق منكم حبالا رماما\nأزيد معاقدها مرة … وتأبى العلائق إلا انجذاما\nوإني أعوذ بكم أن يعود … حبابي قلى وثنائي ملاما\nفهل صافق ، فأبيع العرا … ق غير غبين وأشري الشآما ؟\nإذا لم أزر مطلع المكرما … ت قد أخذ البدر فيه التماما\nفألبس عطفي ذاك الجلال … وأورد عيني ذاك الهماما\nفما أحفل الخطب من بعدها … إذا جل بل لأ أبالي الحماما\nأتروى الغرائب من وردكم … وذودي على جانبيه يظامى\nفلا تنكروا قلعة من فتى … أقام على مطلكم ما أقاما\n … وإن يدا إن تردوا السلاما"},{"id":"diwan-radi:533","bookId":"diwan-radi","type":"poem","seq":533,"chapter":"البحر: رجز تام","title":"رب أخ لي لم تلده أمي","page":"","text":"رب أخ لي لم تلده أمي … ينفي الأذى عني ويجلو همي\nويصطلي دوني بالملم … إذا دعيت اشتد ماضي العزم\nكأن ما قال مناد باسمي … "},{"id":"diwan-radi:534","bookId":"diwan-radi","type":"poem","seq":534,"chapter":"البحر: مجزوء الرجز","title":"لا أشتكي ضري من ال","page":"","text":"لا أشتكي ضري من ال … ناس ، وهم من أعلم\nإن إلها مس بال … جواد منعم\nأشكو الذي يرحمني … إلى الذي لا يرحم"},{"id":"diwan-radi:535","bookId":"diwan-radi","type":"poem","seq":535,"chapter":"البحر: كامل تام","title":"قد يبلغ الرجل الجبان بماله قد يبلغ الرجل الجبان بماله","page":"","text":"قد يبلغ الرجل الجبان بماله قد يبلغ الرجل الجبان بماله … ما ليس يبلغه الشجاع المعدم\nلا تخدعن عنه فرب ضريبة … ينبو الحسام بها ويمضي الدرهم"},{"id":"diwan-radi:536","bookId":"diwan-radi","type":"poem","seq":536,"chapter":"البحر: طويل","title":"ولي كبد من حب ظمياء أصبحت","page":"","text":"ولي كبد من حب ظمياء أصبحت … كذي الجرح ينكي بعدما رقأ الدم\nأصاب الهوى قلبا بعيدا من الهوى … وما كل من يبغي السلامة يسلم\nأجمجم عن عواد قومي علتي … وحبكم ذاك الدخيل المجمجم"},{"id":"diwan-radi:537","bookId":"diwan-radi","type":"poem","seq":537,"chapter":"البحر: رجز تام","title":"أبا نزار تفسد القوم النعم","page":"","text":"أبا نزار تفسد القوم النعم … غفلك الوجد وكاني العدم\nترمم المال ، وبالعرض ثلم … إني ، إذا راحت على الحي النعم\nراح على بيتي الثناء والكرم … لا سلم المال إذا العرض سلم\nقد كنت ناديتك ، والأمر أمم … أما ترى خلف عقابيل الظلم\nلوث خمار الصبح في راس العلم … نفسك إن الخيل بالقوم زيم\nانج فعن لفتتك الرمح الأصم … ناشدتك الله وتحنان الرحم\nوقلت حد عن منهج غير لقم … فلم تطعني رب رأي متهم\nسمعك واع ، وبعقلك الصمم … حتى لقيت خطفة البازي الضرم\nأم الدهيم حاملا بنت الرقم … أمرها المقدار إمرار الوذم\nأفلت منها بعد انشاب القدم … وبعد ما ضاق عليك المزدحم\nمنفلت الأظفور من شق الجلم … أقسمت بالبيت الحرام والحرم\nوبالملبين غدوا شعث اللمم … على رذايا من وجى ومن سأم\nيطلعن من أجبال رضوى وخيم … بها وقار بعد ما كان لمم\nوما جرى بالخيف من دمع ودم … يوم يطير الناس غربان الجمم\nحيث ترى تلك المجالي والقمم … يمسين غربانا ، ويغدون رخم\nوالمستجار بعد ذا والملتزم … تلقى به لأمم بعد أمم\nمفترقا لا عن قلى ومصطدم … صك المجيل زلما بعد زلم\nلأصدعن عرضك صدعا لا يلم … عطا كما عط الفزاري الأدم\nدبيب نار القين طارت في الفحم … أقرع فيه بشبا طعن وذم\nنهز الدلاء تلتقي ، والماء جم … ويل إذا ، يوم النطاح ، للأجم\nكم يلبث الأصل على ضرب القدم … عرضت مني لبصير بالقيم\nحامي الأوار منضج إذا وسم … آسي الحفيظات إذا الداء ألم\nعاجل أدواء العروق ، فحسم … حثحثة الذئب عوى من القرم\nآنس وهنا نسم ريح ، فنسم … ماض على الليل ، إذا لم ير شم\nمن أسقم الناس رموه بالسقم … ومن رمي بالموقظات لم ينم\nكم ضاف رحلي منكم طارق هم … بت له أخطم دائي وأزم\nتوجس الليث استراب بالأجم … أهدر عن شقشقة العود القطم\nحتى رميت ، رب نبل عن كلم … إن هموم القلب أعوان الهمم\nقد يقدع المرء وإن كان ابن عم … ويقطع العضو الكريم للألم\nلألزمن ، إن لم يغيبك الرجم … لهزمتيك عاقرا من اللجم\nيسيل ذفراك دما ، وما ظلم … موارد الجهل مصادر الندم\nنفحة عار مثلها نفثة سم … تشمها بمارن غير أشم\nإذا وعاها ضاحك القوم وجم … يخافها وما جنى ولا جرم\nخذها حروبا كأهاضيب الديم … لا عزمنا اليوم من ألقى السلم\nإن كنت حرا غير مغموز الشيم … فقل لنا من العبيد والقزم\nجاءت به مخداجة غير متم … لها الرزايا ، ولبطنها العقم"},{"id":"diwan-radi:538","bookId":"diwan-radi","type":"poem","seq":538,"chapter":"البحر: طويل","title":"وكم صاحب كالرمح زاغت كعوبه","page":"","text":"وكم صاحب كالرمح زاغت كعوبه … أبى بعد طول الغمز أن يتقوما\nتقلبت منه ظاهرا متبلجا … وأدمج دوني باطنا متجهما\nفأبدى كروض الحزن رقت فروعه … وأضمر كالليل الخداري مظلما\nولو أنني كشفته عن ضميره … أقمت على ما بيننا اليوم مأتما\nفلا باسطا بالسوء إن ساءني يدا … ولا فاغرا بالذم إن رابني فما\nكعضو رمت فيه الليالي بفادح … ومن حمل العضو الأليم تألما\nإذا أمر الطب اللبيب بقطعه … أقول عسى ضنا به ولعلما\nصبرت على إيلامه خوف نقصه … ومن لام من لا يرعوي كان ألوما\nهي الكف مض تركها بعد دائها … وإن قطعت شانت ذراعا ومعصما\nأراك على قلبي ، وإن كنت عاصيا … أعز من القلب المطيع وأكرما\nحملتك حمل العين لج بها القذى … ولا تنجلي يوما ولا تبلغ العمى\nدع المرء مطويا على ذممته … ولا تنشر الداء العضال فتندما\nإذا العضو لم يؤلمك إلا قطعته … على مضض لم تبق لحما ولا دما\nومن لم يوطن للصغير من الأذى … تعرض أن يلقى أجل وأعظما"},{"id":"diwan-radi:539","bookId":"diwan-radi","type":"poem","seq":539,"chapter":"البحر: خفيف تام","title":"يا عذولي قد غضضت جماحي","page":"","text":"يا عذولي قد غضضت جماحي … فاذهبا حيث شئتما بزمامي\nبعد لوثي عمامة الشيب اختا … ل ببردي بطالة وعرام\nخفضت نزوة الشباب وحال … هم بين الحشا وبين الغرام\nغالطوني عن المشيب ، وقالوا : … لا ترع ! إنه جلاء الحسام\nأيها الصبح زل ذميما فما … لم يومي من بعد ذاك الظلام\nأرمضت شمسك المنيرة فود … ي ، فمن لي بظل ذاك الغمام\nقلت : ما أمن من على الرأس منه … صارم الجد في يد الأيام\nإن ذنبي إن الغواني ، بشيبي … ذنب ذئب الغضا إلى الآرام\nكن يبكين قبله من وداعي … فبكاهن بعده من سلامي"},{"id":"diwan-radi:540","bookId":"diwan-radi","type":"poem","seq":540,"chapter":"البحر: طويل","title":"تألق نجدي كأن وميضه","page":"","text":"تألق نجدي كأن وميضه … قواعد رضوى أو مناكب ريم\nأقول له لما تفارط صوبه … وراءك قد ألقحت كل عقيم\nتبعق حتى خلت إن بعاقه … على عدم الجدوى أكف تميم\nأتيتهم والجدب قد عضد القرا … ولا عهد للباغي الندى بكريم\nفما استحضروا العلات وهي كريمة … ولا اطرقوا من روعة ووجوم\nهم ضمنوا اللأواء ، والأزل راكد … على مقعد من عسرهم ومقيم\nفما ولدت أم المكارم مثلهم … كراما ولم تغلط لهم بلئيم"},{"id":"diwan-radi:541","bookId":"diwan-radi","type":"poem","seq":541,"chapter":"البحر: طويل","title":"عطون بأعناق الظباء وأشرقت","page":"","text":"عطون بأعناق الظباء وأشرقت … وجوه عليها نضرة ونعيم\nأمطن سجوفا عن خدود نقية … صفا بشر منها ورق أديم\nشفوف على أجسادهن رقيقة … ودر على لباتهن نظيم\nيجلن خلاخيل النضار وملؤها … بوادي غيل بينهن عميم\nتأطر أغصان الأراك أمالها … وقد رق جلباب الظلام ، نسيم\nغرامي جديد بالديار وأهلها … وعهدي بهاتيك الطلول قديم\nيقولون ما أبقيت للعين عبرة … فقلت جوى لو تعلمون اليم\nايسمح جفني بالدموع وأغتدي … ضنينا بها إني إذا للئيم\nولو بخلت عيني إذا لعسفتها … فكيف ودمع الناظرين كريم"},{"id":"diwan-radi:542","bookId":"diwan-radi","type":"poem","seq":542,"chapter":"البحر: كامل تام","title":"هي سلوة ذهبت بكل غرام","page":"","text":"هي سلوة ذهبت بكل غرام … والحب نهب تطاول الأيام\nولقد نضحت من السلو وبرده … حر الجوى فبردت أي ضرام\nمن بعد ما أظمى الغليل جوانحي … وأطال من ملل الزلال أوامي\nنشز الجنيب على ثنيات الهوى … ونجوت مرميا إلي زمامي\nسلوان لا أعطي الجآذر لفتة … أو نظرة إلا بعين لمام\nنفض الصبابة خاطري وجوانحي … وأبى المذلة منزلي ومقامي\nوالحب داء يضمحل كأنما … ترغو روازحه بغير لغام\nلا يدع العذال نزع صبابتي … بيدي حسرت عن الغرام لثامي\nقد كانت الصبوات تعسف مقودي … فالآن سوف أطيل من إجمامي\nهيهات يخفضني الزمان وإنما … بيني وبين الذل حد حسامي\nلا أرتضي بالماء إلا جمة … ولرب طافحة بغير جمام\nوأصد عن ماء القليب وماؤه … في حيز الإكراب والأوذام\nولقد لبست من القناعة جبة … تضفو علي ولا تبين لذام\nكم ذلل العدم العزيز ، وعظمت … نفحات هذا المال غير عظام\nما هم من حرم الثراء إذا سما … وأحظ من شرف ومن إعظام\nشحب الزمان علي بعده غضارة … وإذا نقضت فقد قضيت تمامي\nوجرى الثقاف على أوائل صعدتي … فأقتص من طربي وفضل عرامي\nعني إليك فما الوصال بنافع … من لا يعذب قلبه بغرام\nما كنت أسمح بالسلام لمعرض … وعلى أمير المؤمنين سلامي\nملك سما حتى تحلق في العلى … وأذل عرنين الزمان السامي\nيا ابن القماقم والغطارفة الألى … قمم العلى ودعائم الإسلام\nالطود أيهم والسماء عريضة … واليوم أيوم ، والقلمس طام\nسيماء مشتهر ، وقلب مشيع … وأناة مقتدر ، ورأي إمام\nأمر الخلافة في يديك ، وإنما … هي عقبة تقضى بكل همام\nقد كان جدك عصمة العرب الألى … والآن أنت لهم من الإعدام\nحفظوا أياديك الجسام وإنما … وصوا بحفظ الخيل والأنعام\nبالطائع الهادي الإمام أطاعني … أملي وسهل لي الزمان مرامي\nمن معشر ما فيهم إلا فتى … أو جائد أو ذائد أو حامي\nقوم إذا عزموا الغوار تراجعوا … يتقاسمون ضراغم الآجام\nلا يستقر المال فوق أكفهم … كالسيل يزلق عن ذرى الأعلام\nالبيت ذو العمد الطوال يظلهم … بين القنا ، والحامل الهمهام\nيفديك كل مزند ومعرد … يوم الوغى ، ومطاول ومسام\nومبخل أعطى القليل ، وربما … سمحت حروف التاء للتمتام\nأثر الندوب بصفحتيه ونحره … لصفا مراد أو سهام مرام\nطلب الغنى لا للحباء ولا الندى … ما كل عار جاء للأحرام\nأحسود ذي النور المبين على العلى … أربع على ظلع وانفك دام\nأما تنازعه العلاء فإنه … قرم يخاطره بويزل عام\nولرب قرن فات أطراف القنا … حتى أخذت عليه بالأقلام\nوولعت في جد الحديث وهزله … ولع القواضب بالطلى والهام\nفي فيلق جم الذوابل والظبى … مثر من الأسراج والألجام\nمتدفق القطرين يرجف نقعه … بعصائب الرايات والأعلام\nفكأنه والنقع فوق رواقه … سيل يساير مستطيل غمام\nما زلت تكشفه بمصقول القرا … والخيل بين مغيرة وصيام\nقلقلت من أعطافه ، فكأنما … \nطرف يتيه على اللجام تكبرا … فتكاد تركبه بغير لجام\nويد تصيول على الحسام شجاعة … فتكاد تبسطها بغير حسام\nوالطعن يرجع بالقنا وصدورها … خطاطة خلف الجياد دوام\nحمر الكعوب كأنما ألوى بها … نضخ من الشيان والعلام\nإيها ، وأنت حيا إلى أوطانه … دفع الزمان بمعرق وشآم\nهذا الحسين ، وقد جذبت بضبعه … جذبا يمر قرائن الأرحام\nأعطيته محض المودة والهوى … وغرائب الأعزاز والإكرام\nورددته بالقول ليس بخلب … في عقبه والوعد غير جهام\nمتناولا طرف الفخار يجره … ويقود مصعبه بغير زمام\nلما رآك رأى النبي محمدا … في بردة الإجلال والإعظام\nورأى بمجلسك المعرق في العلى … حرم الرجاء وقبة الإسلام\nأوسعت من خطواته في موقف … متغلغل بتضايق الأقدام\nورفعت ناظره إليك مسلما … في أي أبهة وأي مقام\nومن القلوب سواكن وخوافق … ومن العيون غوامض وسوام\nقربت من فمه أنامل راحة … معروفة بالنقض والإبرام\nوحصصته بالبشر منك وإنما … بشر الإمام قرابة الأنعام\nبر الأقارب والأباعد واجب … وأحق بالنعمى بنو الأعمام\nلا تشمتن به الأعادي بعدما … عرضوا من الأحقاد والأوغام\nهي قولة لا يستطاع رجوعها … كالسهم يخرج عن بنان الرامي\nوالقول يعرض كالهلال فإن مشى … فيه الفعال ، فذاك بدر تمام\nولرب فاعل فعلة لا تنثني … لو رام رجعتها بكل مرام\nوكذا الملوك تقوضوا واستصعبوا … تقويض ما رفعوا من الآطام\nوغدا سنان ابن المشلل عاجزا … عن نقض ما على من الأهرام\nوكذاك عمر وذو المعابل فاته … بعد اضطراب النزع رد سهام\nويل لمغرور عصاك فإنه … متعرض لمخالب الضرغام\nهيهات طاعتك النجاة وحبك … تقوى وشكرك أفضل الأقسام\nفاسلم أمير المؤمنين لغبطة … معقودة بذوائب الأعوام\nوتمل أيام البقاء ، ولا تزل … تطغى بشكرك ألسن الأقوام\nنفس يحرمها الحمام مهابة … ليس النفوس على الردى بحرام\nفالله يعلم أن نورك لم يزل … مستهزئا بالظلم والإظلام\nوالمجد يخبر عن فعالك أنه … يدلى إليه بحرمة وذمام\nفاسمع ، أمير المؤمنين ، فإنما الأ … سماع أبواب إلى الأفهام\nالقول في الإطراء غير مبلد … والشكر للنعماء غير عقام\nجاءتك محصدة القوى حبارة … تستعبد الأرواح في الأجسام\nمن لي بإنشاديكها في موقف … اعتده شرفا مدى أيامي\nلا أدعي فيه الغلو ، وإنما … يوفي على قلل الرجال كلامي"},{"id":"diwan-radi:543","bookId":"diwan-radi","type":"poem","seq":543,"chapter":"البحر: وافر تام","title":"أمير المؤمنين بثثت فينا","page":"","text":"أمير المؤمنين بثثت فينا … صنائع بعضها خطر عظيم\nوما اقتعد العلى إلا شجاع … ولا بلغ المنى إلا كريم\nلمثلك تحرز المال الليالي … وأولى الناس بالعدم اللئيم\nوأنت حميتنا من كل ضيم … وقد ضريت على الطمع الخصوم\nأنفت بنا على قمم الأعادي … وكاد الجد يدرك ما يروم\nخلائق منك نعرفها يقينا … وكل فتى بشيمته عليم\nفداؤك كل منتحل المعالي … يقطع دونه النسب الصميم\nبأخلاق كما دجت الليالي … وأحساب كما نغل الأديم\nوآخر هز عطفيه اغترارا … بحلمك يوم يفتقد الحليم\nتبلج فيه وسمك ، والمطايا … تغلغل في حواركها الوسوم\nوكم فوق البسيطة من شريف … أغر الوجه شيمته بهيم\nلك الجبل الممنع إن تسامى … عدو لا ينام ولا ينيم\nجذبت عن المطيع زمام عز … أطاع الوخد منه والرسيم\nسما بك خير آباء ، ولكن … مضوا طلقا ، ومجدهم مقيم\nدعوتك ، يا إمام ، ومن ورائي … سفيه الرأي يعذل أو يلوم\nوحسبي أن تعيش على الليالي … سليما ، لا يطلقك النعيم\nفإن العيش ، ما جردت منه … حمام والصحيح به سقيم\nرجوتك والرجاء يمد باعي … وأنت لكل مكرمة حميم\nوإني ، إن دعوتك للمعالي … لأعلم أي بارقة أشيم\nوقبلك ضاع حقي في الليالي … كما ضاع الغريب ، أو اليتيم\nونعماء شقيت بها ولكن … غدا حظي من الريح السموم\nومن لي أن أراك ، ولي مقام … بدارك لا أزول ولا أريم\nومالير أصول على الأعادي … وأعلم أن دارك لي حريم\nتداركني صنيعك ، والأماني … تفلل من جوانبها الهموم\nولولا ما أنلت مشت برحلي … نقيب الخف حليتها الكلوم\nوإلطاف تساقط منك وهنا … علي كما تهورت النجوم\nأعدت سواد أيامي بياضا … وأيام الورى بيض وشيم\nوقد عطفت علي بنات دهري … كما عطفت على السقب الرؤوم\nومنك تولت الأنواء ريي … وطبق أرضي الكلأ العميم\nفلا غرضت سنوك من الليالي … وعمر عدو مجدك لا يدوم\nتدوب على منازلك الغوادي … ويركض في حدائقك النسيم"},{"id":"diwan-radi:544","bookId":"diwan-radi","type":"poem","seq":544,"chapter":"البحر: كامل تام","title":"لله ثم لك المحل الأعظم","page":"","text":"لله ثم لك المحل الأعظم … وإليك ينتسب العلاء الأقدم\nولك التراث من النبي محمد … والبيت والحجر العظيم وزمزم\nما ناقلت ركب الركاب إلى منى … وأراق من علق الدماء الموسم\nخطر من الدنيا يجل وسورة … تعلو وقدر زائد يتقدم\nتمضي الملوك وأنت طود ثابت … ينجاب عنك متوج ومعمم\nما ذاك إلا أن غربك منهم … أمضى وإن علو مجدك أعظم\nإن الخلافة مذ نهضت بعبئها … هدأ الضمير بها ونام النوم\nقد كان منبرها تضاءل خيفة … واستل منه الهزبري الأعظم\nحتى تخمط منك فوق سراته … والأرض راجفة ، فنيق مقرم\nلله أي مقام دين قمته … والأمر مردود القضية مبرم\nفكأنما كنت النبي مناجزا … بالقول ، أو بلسانه تتكلم\nفمضى ، وأعقب بعده متيقظا … سجلاه بوسى في الزمان وأنعم\nكالغيث يخلفه الربيع وبعضهم … كالنار يخلفها الرماد المظلم\nلا تهتدي نوب الزمان لدولة … الله فيها والنبي وأنتم\nشرفا بني العباس مد رواقه … وعلى تساندها القنا والأنجم\nكم مهمه لبست إليك ركابنا … والأرض برد بالمنون مسهم\nحتى تراعفت المناسم والذرى … فسواء الأعلى دما والمنسم\nهن القسي من النحول فإن سما … طلب ، فهن من النجاء الأسهم\nيضمن لا ورد العطاء مصرد … أبدا ولا فعل الزمان مذمم\nوأنا النذير لمارق يممته … من ضوء نار للطغاة مضرم\nحمراء جاهلة الشرار مهولة … للناظرين لها دخان أدهم\nوململم يرمي العدو بركنه … ماض كفهر المنجنيق ململم\nفي معرك فقد التكلم تحته … للروع ، إلا أزمل وتغمغم\nكثر الحديد به ، فبعض يتقي … كلم الطعان بها وبعض يكلم\nمن كل ضاحكة القتير كأنها … برد أعاركه الشجاع الأرقم\nوطويل سالفة السنان يؤده … خطل الكعوب وفي الضلوع يقوم\nومرقرق الغربين ، إلا كلفة … مما يطبق دائما ويصمم\nفي فتية ركبوا العلى من هاشم … يرمون أقطار العدو كما رموا\nيجري الحياء الغض في قسماتهم … في حين يجري في أكفهم الدم\nفإذا غضبت فأنت أنت شجاعة … توفي على عضب الردى وهم هم\nبحمائل الملك الجليل مقلد … وبخاتم النبأ العظيم مختم\nوعظمت قدرا إن يروقك مغنم … أو أن يصر على بنانك درهم\nهي راحة ما تستفيق من الندى … أبد الزمان ، وبدرة لا تختم\nملك تلاعب بالهوى عزماته … بعدا به عما يقول اللوم\nبينا يضيء على الزمان ، فينجلي … حتى يغير على الضياء فيظلم\nالنفع والإضرار شغل لسانه … ليراش عاف ، أو يضعضع مجرم\nويروح عنه وليه وعدوه : … هذا يزيد غنى وهذا يعدم\nفعلى المقارب مطلع متبلج … وعلى المجانب عارض متجهم\nفي كل يوم خالع متأخر … يردى وجد غالب متقدم\nوفتوح أمصار تروح وتغتدي … عفوا إليك ، وغيرها يتجشم\nلولاك لم يك مثلها ما يرتقى … علوا ، ولم يك مثلها ما يغنم\nما كان يومي دون مدحك أنني … صب بغير جلال وجهك مغرم\nلكنها نفس تصان لتنتضى … وتجم من طول المقال فتفعم\nأنت العلى فلقصدها ما أقتني … من جوهر ولمدحها ما أنظم\nما حق مثلي إن يضاع وقوله … باقي العماد على الزمان مخيم\nوأجل ما أبقى الرجال فضيلة … تمتاحها أذن ، ويودقها فم\nوأنا القريب قرابة معلومة … والعرق يضرب والقرائب تلحم\nإني لأرجو منك أن سيكون لي … يوم أغيظ به الأعادي أيوم\nوأنال عندك رتبة مصقولة … إن عاين الأعداء رونقها عموا\nإني ، وإن ضرب الحجاب بطوده … أو حال دونك يذبل ويلملم\nلأراك في مرآة جودك مثلما … يلقى العيان الناظر المتوسم\nولقد أطاعك من علي ناصح … ماضي الجنان إذا أظلك مغرم\nيرضيك ظاهره ، وبين ضلوعه … قلب بما يدني إليك متيم\nفاشدد يديك به يدم لك ناقض … فيما يؤد من الأمور ومبرم\nعلما أقول بديهة وروية … ويضل عندك قائل لا يعلم\nشعرا أثير به العجاج بسالة … كالطعن يدمي والقنا يتحطم\nوفصاحة ، لولا الحياء لهجنت … أعلام ما قال الوليد ومسلم\nوخطابة للسمع في جنباتها … شغل يعوق عن الذي يترنم\nفعلى م يطلب غايتي متسرعا … غلق الجنان أقول ما لا يفهم\nهيهات أقعدك الحضيض مؤخرا … عني ، وجاورني السها والمرزم\nأزداد فكرا في الزمان ، فإصبعي … لنواجذي أبد الليالي ترأم\nوأرى الحليم ينال من إعراضه … ويسل مقوله السفيه فيعظم\nيقتاد مخشي الرجال مراده … عفوا ، ويظلم كل من لا يظلم\nقلب يسيغ الحادثات وعنده … عزم على نوب الزمان مصمم\nيا دهر ! دونك قد تماثل مدنف … واقتص مهتضم ، وأورق معدم\nإني عليك إذا امتلأت حمية … بندى أمير المؤمنين محرم\nومذ ادرعت عطاءه وفناءه … أرمي ويرميني الزمان ، فأسلم\nوإذا الإمام أعار قلبي همة … فالأمر أمري والمعاطس ترغم"},{"id":"diwan-radi:545","bookId":"diwan-radi","type":"poem","seq":545,"chapter":"البحر: مجزوء الكامل","title":"أترى ديار الحي بال","page":"","text":"أترى ديار الحي بال … عين باقية الخيام\nأم فرقتهم خلفة الأ … يام أو نجع الغمام\nماذا على الركبان لو … حيوا طلولك بالسلام\nأو بلغوا عن واجد … لف الضلوع على الغرام\nدار وصلت بها الهوى … وقطعت أقران الملام\nوبلوت من سكر الشبا … باب أجن من سكر المدام\nأيام أنظر في معا … طف شملتي نظر القطامي\nوأروح قائد فتية … سود الغدائر والجمام\nسقيا لأزمان بها … كنت الملقب بالغلام\nقد قلت للركب الهجو … د على الأماعز والإكام\nهبوا فقد تتيقظ الأج … جداد للقوم النيام\nزموا المطي وأحلسوا … منها على الدبر الدوامي\nودعوا نواظرها من الإ … رقال تعمى باللغام\nحتى تنيخوا في حمى … صعب المراقي والمرامي\nملك الملوك به يرا … وح بين عفو وانتقام\nما إن أبالي من ورا … ئي بعد أن يضحي أمامي\nكالليث يقتنص الرجا … ل ولا يغير على السوام\nيظمي الرواة إذا سطا … وإذا سخا أروى الظوامي\nالقائد الجرد العتا … ق يجلن في بيض ولام\nمن كل ذي خصل مراح … ح السوط مكدود اللجام\nومسوم الرايات يخفق … في الجماهير العظام\nومخول النعم الجسا … م ونازع النعم الجسام\nإن الجياد على المرا … بط تشتكي طول الجمام\nترمي بأعينها إلى … البلد اليماني والشآم\nيصهلن من شوق إلى … قطع المفاوز والموامي\nومصرة الآذان تر … قب وثبة بعد القيام\nفاصدم بها ثغر العدا … بجوانب اللجب اللهام\nيحملن أسد الغاب قد … عقدوا الدوابر باللمام\nمستلئمين بها كأن … رؤسهم بيض النعام\nمن كل هفاف القمي … أشم معروق العظام\nماض كأن ذراعه … من قائم العضب الحسام\nيغدون في فيح الفلا … متجارحين من الزحام\nيتفيؤون عجاجة … كجآجيء الغيم الركام\nحتى تقود من المطا … لب كل ممنوع الزمام\nلا تغررنك من عدوك … رمية من غير رام\nأشلى بها الضرغام حتى … تى هب من طيب المنام\nهي عنده سبب الشبا … ب ، وعندنا سبب الفطام\nأني يقرطس ذو العمى … غرض المرامي بالسهام\n … ب مرابض الليث الهمام\nأين النجوم من الحصى … أين النضار من الرغام\nغلبت على كرم المعا … رق فيه أخلاق اللئام\nفذوت نضارته غص … نك دونه ريان نام\nطلب العلى خبطا فضل … ضلال عاشية الظلام\nيحدو بها سفها وقد … علقت يمينك بالخطام\nيا كاشف الكرب المل … م ، وكافي الداء العقام\nبلغت غايات المنى … \nمتمليا بالعمر يع … طيك الردى عقد الذمام\nلا زلت تلبس كل عا … م واعد ببلوغ عام\nلو كان شيء دائما … بشرت ملكك بالدوام"},{"id":"diwan-radi:546","bookId":"diwan-radi","type":"poem","seq":546,"chapter":"البحر: مخلع البسيط","title":"ولية ما خلصت منها","page":"","text":"ولية ما خلصت منها … إلي خفوق ولا منام\nيفعل فيها ضياء وجهي … ما يفعل البدر في الظلام\nعفت بها الخمر وهي تجلى … والكأس محطوطة اللثام\nوحاش للبدر وهو وجهي … يخطب شمسا من المدام\nغيري من الخمر في رضاع … أرغب عنه إلى الفطام"},{"id":"diwan-radi:547","bookId":"diwan-radi","type":"poem","seq":547,"chapter":"البحر: متقارب تام","title":"أبا هرم أنحها إنني","page":"","text":"أبا هرم أنحها إنني … سأمطرها عن قليل دما\nولا تشمخن بأنف الأبي … فأولى لأنفك أن يرغما\nوإنك يوم تنزى علي … وتبغي لي المؤيد الصيلما\nكمن صارع الأسد المستغير في … الغاب أو ساور الأرقما\nبدأت ، فعقبت في المعضلات … وكنت أرى البادىء الأظلما\nوما كنت أرمي بسهم العقو … ق إلا امرأ صابني إذ رمى\nقذفتك في التيه من بعدما … سلكت بك السنن الأقوما\nوقد كان أشرق جوي عليك … ولكن لظلمك ما أظلما\nفقف حيث أنت فما كل من … بغى أن يطول ويسمو سما\nولا من تقدم نال العلى … رخيصا ، ولكن من قدما\nسأبعثها ظبة تختلي ال … خصائل ، أو تعرق الأعظما\nفدونكها قاصفا عاصفا … من الشر ، أو عارضا مرزما\nقوارص تنثر نظم الدروع … وتستنزل البطل المعلما\nفمن كان يسقيك ري الجنى … فإني سألعقك العلقما\nومن كان يلقاك مستسلما … فإني ألاقيك مستلئما"},{"id":"diwan-radi:548","bookId":"diwan-radi","type":"poem","seq":548,"chapter":"البحر: طويل","title":"أتطمع أن ألقي إليك مقادتي","page":"","text":"أتطمع أن ألقي إليك مقادتي … ولي مارن ما مرنته الخزائم\nوتكثر بالأمر العظيم تهددي … ومني تنفض الأمور العظائم\nوقد عجم الأقوام بعدك صعدتي … فما أثرت فيها النيوب العواجم"},{"id":"diwan-radi:549","bookId":"diwan-radi","type":"poem","seq":549,"chapter":"البحر: طويل","title":"أأبقى على نضو الهموم كأنما","page":"","text":"أأبقى على نضو الهموم كأنما … سقتني الليالي من عقابيلها سما\nوأكبر آمالي من الدهر أنني … أكون خليا لا سرورا ولا هما\nأكر أحاديث المطامع ضلة … وألقح من هذي المنى أبطنا عقما\nفلا جامعا مالا ولا مدركا على … ولا محرزا أجرا ولا طالبا علما\nبأرجوحة بين الخصاصة والغنى … ومنزلة بين الشقاوة والنعمى"},{"id":"diwan-radi:550","bookId":"diwan-radi","type":"poem","seq":550,"chapter":"البحر: وافر تام","title":"أبا مطر وجذمك من معد","page":"","text":"أبا مطر وجذمك من معد … كذات العر في السرح السليم\nسراة أديم هذا الحي فهر … وبعض القوم زعنفة الأديم\nقناة نحن أملسها ، وأنتم … مكان العاب منها والوصوم\nوما وضعتك حاضنة ولكن … تمطق فوك من لبن لئيم\nإذا المنتاج لم ينجب فتاها … فليس الفضل إلا للعقيم"},{"id":"diwan-radi:551","bookId":"diwan-radi","type":"poem","seq":551,"chapter":"البحر: بسيط تام","title":"قالوا رجوت الندى منه بلا سبب","page":"","text":"قالوا رجوت الندى منه بلا سبب … فقلت : هل سبب أقوى من الكرم\nوسيلتي إنه غيث ولي ظمأ … وإن ظمئنا توسلنا إلى الديم\nقرعت بابك لا أخشى تمنعه … فإن تمنع لم أعذل ولم ألم\nلم أرم بالظن إلا من يصدقه … ولا توخيت إلا موضع النعم\nما الذنب للمزن جازتني مواطره … وإنما الذنب للأرزاق والقسم"},{"id":"diwan-radi:552","bookId":"diwan-radi","type":"poem","seq":552,"chapter":"البحر: طويل","title":"إذا أرعدوا يوما لنا بوعيدهم","page":"","text":"إذا أرعدوا يوما لنا بوعيدهم … على النأي أبرقنا لهم بالصوارم\nويوما على الأهواز كانت جياده … تودج في لباتها باللهاذم\nقضى وطرا منها الحمام ، وما اشتفى … حسامك فيه من قراع الجماجم"},{"id":"diwan-radi:553","bookId":"diwan-radi","type":"poem","seq":553,"chapter":"البحر: بسيط تام","title":"في كل يوم أنوف المجد تصطلم","page":"","text":"في كل يوم أنوف المجد تصطلم … وتستزل لأركان العلى قدم\nطود تصدع من صماء شاهقة … تنبو من العز عن أقطاره القدم\nجوائف من جراح الدهر بالغة … إلى القلوب ولا يجري لهن دم"},{"id":"diwan-radi:554","bookId":"diwan-radi","type":"poem","seq":554,"chapter":"البحر: كامل تام","title":"وكأنما أولى الصباح وقد بدا","page":"","text":"وكأنما أولى الصباح وقد بدا … فوق الطويلع راكب متلثم\nوأذاع بالظلماء فتق واضح … كالطعنة النجلاء يتبعها الدم"},{"id":"diwan-radi:555","bookId":"diwan-radi","type":"poem","seq":555,"chapter":"البحر: طويل","title":"ترحلنا الأيام وهي تقيم","page":"","text":"ترحلنا الأيام وهي تقيم … ويجرح فينا الخطب وهو سليم\nويبقى على ريب الزمان لهنه … على ذي الليالي هينا لكريم"},{"id":"diwan-radi:556","bookId":"diwan-radi","type":"poem","seq":556,"chapter":"البحر: وافر تام","title":"بعثت بها معرقة الهوادي","page":"","text":"بعثت بها معرقة الهوادي … وقعن إلى المدى وقع السهام\nفمن شهب كغران المساعي … من دهم كأخلاق اللئام"},{"id":"diwan-radi:557","bookId":"diwan-radi","type":"poem","seq":557,"chapter":"البحر: بسيط تام","title":"أعقل قلوصك بالأجراع من أضم","page":"","text":"أعقل قلوصك بالأجراع من أضم … حيث استسيغ الندى واستلفظ اللوم\nتلقى على الماء بيضا من بني ثعل … ديباج أوجههم بالبشر مرقوم\nعماد أبياتهم سمر الرماح ومن … أطنابها الخيل تعطو والأناعيم"},{"id":"diwan-radi:558","bookId":"diwan-radi","type":"poem","seq":558,"chapter":"البحر: رجز تام","title":"كأن أيديها بوادي الرمام","page":"","text":"كأن أيديها بوادي الرمام … بين جفافي جندل أو أرام\nأنامل الولدان يفلين الهام … "},{"id":"diwan-radi:559","bookId":"diwan-radi","type":"poem","seq":559,"chapter":"البحر: متقارب تام","title":"وسود النواظر حمر الشفا","page":"","text":"وسود النواظر حمر الشفا … هتحسبهن ولغن الدما\nقريب لألوانهن الشقي … مفتضح عندهن اللمى"},{"id":"diwan-radi:560","bookId":"diwan-radi","type":"poem","seq":560,"chapter":"البحر: خفيف تام","title":"ربما رد عنك سهم المرامي","page":"","text":"ربما رد عنك سهم المرامي … عاكس من عوائق الأيام\nحابس الفيل بالمغمس ، والأح … وش يزجرنه قدام قدام"},{"id":"diwan-radi:561","bookId":"diwan-radi","type":"poem","seq":561,"chapter":"البحر: خفيف تام","title":"كل يوم يجب مني سنام","page":"","text":"كل يوم يجب مني سنام … وتداعى لثلمي الأيام\nواقفا كل موقف تتهاوى … دونه أو تزلزل الأقدام"},{"id":"diwan-radi:562","bookId":"diwan-radi","type":"poem","seq":562,"chapter":"البحر: خفيف تام","title":"اتقوا بذلة العيون فغابوا","page":"","text":"اتقوا بذلة العيون فغابوا … وبآرائهم يرب الأنام\nإن من خاضت النواظر فيه … لحر إن تخوضه الأقدام"},{"id":"diwan-radi:563","bookId":"diwan-radi","type":"poem","seq":563,"chapter":"البحر: خفيف تام","title":"يعلم الجد أنني لا أضام","page":"","text":"يعلم الجد أنني لا أضام … ومجيري من الزمان همام\nلحماني أغر شمته الكر … ونصل حليه الأحرام\nرب قول نمي إلي وعزمي … غافل ، والهموم عني نيام\nوتعرفت قائليه ، ولكن … آه لو كان في يميني حسام\nكيف تخدي إليهم الذبل السم … وتعدي عليهم الأقلام\nدون أن أقبل المذلة للعز … ز إباء ونخوة وعرام\nوطعان تندق فيه العوالي … وضراب يزور منه الحمام\nلست أدري ماذا يقول لساني … وفمي للمقال فيه ازدحام\nوكأن الحمام فينا جنيب … يتبع العيش والزمان زمام\nفاصرف الهم إنما العيش يوم … ودع القول إنما الدهر عام\nأيها العاجز المكدر وردي … ربما عرفتك تلك الجمام\nفانتفق في الوجار ، واقعد ذليلا … قد كفاك الجلى رجال قيام"},{"id":"diwan-radi:564","bookId":"diwan-radi","type":"poem","seq":564,"chapter":"البحر: منسرح","title":"بيني وبين الصوارم الهمم","page":"","text":"بيني وبين الصوارم الهمم … لا ساعد في الوغى ولا قدم\nلا تسبريني بغرب عذلك لي … فما لجرحي من الندى ألم\nوخائف في حماي قلت له … كل ديار وطئتها حرم\nيعجبني كل حازم الرأي لا … يطمع في قرع سنه الندم\nإن قام خفت به شمائله … أو سار حفت بوطئه القدم\nولا أحب الغلام متهما … يشق جلباب سره الكلم\nصدر كصدر الحسام ليس له … سر بنضح الدماء منكتم\nصفت نطاف المنى فقلت لها … ما أجنت في ديارنا النعم\nتجري الليالي على حكومتنا … وفي الزمان النعيم والنقم\nتلعب بالنائبات أنفسنا … كأنها في أكفنا زلم\nوليلة خضتها على عجل … وصبحها بالظلام معتصم\nتطلع الفجر من جوانبها … وانفلتت من عقالها الظلم\nكأنما الدجن في تزاحمه … خيل لها من بروقه لجم\nما زالت العيس تستهل بنا … والليل في غرة الضحى غمم\nفاض على صبغة الظلام بنا … شيب من الصبح والربى لمم\nيا زهرة الغوطتين تبخل بالبشر … وما مس أرضك العدم\nكم فيك من مهجة معذبة … هجيرها بالنسيم يلتطم\nومن غصون على ذوائبها … يزلق طل الرياض والديم\nوفتية علموا القنا كرما … فأصبحت من ضيوفها الرخم\nتكاد إن أشرفت جباههم … تضيء منها الشعور واللمم\nوكيف يخفيهم الظلام ، وفي … جحافل الليل منهم رتم\nإن يمين الحسين تنصفني … إن جار أعداؤها وإن ظلموا\nلا يطمع الذل في جوار فتى … تلمع فيه الصوارم الخذم\nيثبت في كفه الحسام كما … يعثر في غير كفه الكرم\nإذا تخطى عجاجة زحفا … آراؤه ، والرماح تنهزم\nتضحك عن وجهه غياهبها … كأنه بالهلال ملتثم\nفشقها والحديد مطرد … وخاضها والضراب مضطرم\nواستل أسيافه محرشة … فاستلبتها الرقاب والقمم\nإذا المذاكي باحت محازمها … واضطرمت في شدوقها اللجم\nوقرها والرماح طائشة … وكفها والسيوف تزدحم\nإذا ذبول الشفاه شمرها … في الغمرات الحفاظ والسأم\nقلص عن ثغره مضاحكه … كأنه في العبوس مبتسم\nإذا خمار الظلام لثمه … تساقطت عن قميصه التهم\nكأنه من سرور يقظته … بشره بالمدائح الحلم\nإذا استطالت همومه سكرت … في كفه البيض وانتشى القلم\nوإن سرى أسفرت صوارمه … والتثمت بالحوافر الأكم\nما ضج من طول مطله أمل … ولا اشتكته العهود والذمم\nلو فطنت بالقرى سوائمه … لما مشت تحت وفده النعم\nيعارض الخيل ، في عرضنتها … قرم إلى نهب لحمها قرم\nواسع خرق الضمير حيث سرى … تبحبحت في مراده الهمم\nكأنما بيضه ضراغمة … غمودها في الكتائب الأجم\nلارتشف الخمر ، وهو يلفظها … لو أن ما تضمر الكؤوس دم\nإن العدا عن غروبه طلعوا … وبعد ما غار سيفه نجموا\nما ألموا للوعيد فيك شبا … الطعن وقد المصائب الألم\nيا مخرس الدهر عن مقالته … كل زمان عليك متهم\nشخصك ، في وجه كل داجية … ضحى ، وفي كل مجهل علم\nإلى أبي أحمد صدعت بها … قلب الدجا والضمير يضطرم\nبز زهيرا شعري ، وها أنا ذا … لم أرض في المجد إنه هرم"},{"id":"diwan-radi:565","bookId":"diwan-radi","type":"poem","seq":565,"chapter":"البحر: سريع","title":"لا عادت الكأس عليل النسيم","page":"","text":"لا عادت الكأس عليل النسيم … بعدي ، ولا فضت ختام الهموم\nفي ليلة غاب معي بدرها … وحاربتها في الظلام النجوم\nلا سحب النشوان من ذيله … فيها ولا درت عليها الكروم\nغبت ، وشوقي عندها حاضر … شيعه القلب وراء الحريم\nجاء وجلباب الدجا شاحب … وعاد والجو صقيل الأديم\nلو أن قلبي مطلق في الحشا … جرى إليها في عنان النسيم\nيا ليلة تكسر ألحاظها … كأنها مكحولة بالغيوم\nكم ليلة مثلك انضيتها … والراح تزجى من إزار النديم\nيكاد من حسن ، إذا زرتها … تحدث برأ في الهلال السقيم\nفي مجلس قوم أعطافه … تقارب الوصل وقرب النعيم\nيجلو علي الكأس من خدرها … أبيض سامي الفرع نامي الأروم\nتعلق الحسن بأطرافه … فمال ، والأعصان لا تستقيم\nموقر الشيمة إن جاذبت … مقاله ، يوم الجدال ، الخصوم\nفي حيث تنزو عذبات الحبا … بالقوم ، حتى تستطير الحلوم\nيقرضني الود على نأيه … وعند قرب الدار نعم الحميم\nحلأني الأعداء عن ورده … وبي إلى الماء نزاع مقيم\nأذاد أن أرفل في أرضه … ويرتعي ذاك الجناب العميم\nإن دفعوا ظمئي ، فيا ربما … ذادت عن الماء الحقاق القروم\nمن بعد ما مدت حيازيمهم … على قلوب داميات الكلوم\nفي كل يوم تنتضى منهم … قوارص تعقر حلم الحليم\nأحيت شآبيب الحيا منزلا … مات لنا فيه الزمان القديم\nأيام يغدو الروض مستبشرا … ونجتلي تلك الربى والرسوم\nكم صبغ الدهر قميص الثرى … وعاد رق الأرض ضاحي الوشوم\nوالدهر في أبياتنا جؤذر … فالآن أضحى وهو ليث شتيم\nأيام نزجي من مواعيدنا … ضراغما تفرس عدم العديم\nتنظر في أثناء أوطاننا … لقاح جود للرجاء العقيم\nلي في حواشي البرق أنس فلا … أدري أأغضي دونه أم أشيم\nأخاف من سطوة شؤبوبه … وبيننا من دجنه هضب ريم\nأجفو مغانيه ، وما بيننا … لا يغضب الناقة فيه الرسيم\nوكنت لا أبرح أوطانه … مطنبا بين الضحى والصريم\nأسلب في الجري إلى ربعه … سنطلة الذئب وشأو والظليم\nيا دين قلبي لك من لوعة … تعاود القلب عداد السليم\nقل لغريمي بديون الهوى … يا حبذا منك مطال الغريم\nذممت دهرا لم يزل صرفه … يطرقني ، وفد الفعال الذميم\nأرى الأسى إن جل خطب الأسى … أسمح من طبع العزاء اللئيم\nوالقرب في الود على نأينا … أحسن من قرب العدا بالجسوم\nأكرم ودي دون خطابه … أن يصل الحبل بغير الكريم"},{"id":"diwan-radi:566","bookId":"diwan-radi","type":"poem","seq":566,"chapter":"البحر: طويل","title":"بني عامر ما العز إلا لقادر","page":"","text":"بني عامر ما العز إلا لقادر … على السيف لا تخطو إليه المظالم\nضجيع الهوينا يغلب الخصم رأيه … وأكبر سلطان الرجال الخصائم\nأرى إبل العوام تحدى على الطوى … وتأكل حوذان الطريق المناسم\nوتظمى على الإغذاذ أشداق خيله … وتشرب من أفواههن الشكائم\nيحاول أمرا يرمق الموت دونه … لقد زل عنه ما تروم المراوم\nأقام يرى شم النسيم غنيمة … ولا بد يوما أن ترد الغنائم\nوتعجبه غر البروق يشيمها … سراعا إذا مرت عليها الغمائم\nأمسح عرنين الظلام بعرعر … ومن دونه خد من الليل ساهم\nولي بين أخفاف المراسيل حاجة … ستصحب ، والأيام بيض نواعم\nتحاربني في كل شرق ومغرب … وأكبر ظني أنها لا تسالم\nأقول ، إذا سالت مع الليل رفقة … تقاذفها حتى الصباح المخارم\nدعي جنبات الواديين فدونها … أشم طويل الساعدين ضبارم\nإذا هم لم تقعد به عزماته … وإن ثار لا تعيا عليه المطاعم\nكأن على شدقيه ثغرا وراءه … ذوابل من أنيابه وصوارم\nفما جذب الأقران منه فريسة … ولا عاد يوما أنفه وهو راغم\nيرى راكب الظلماء في مستقره … وتستن منه في العرين الغماغم\nنمر وراء الليل نكتمه السرى … وقد فضحتنا بالبغام الرواسم\nله كل يوم غارة في عدوه … تشاركه فيها النسور القشاعم\nكأن المنايا إن توسد باعه … تيقظ في أنيابه وهو نائم\nوما الليث إلا من يدل بنفسه … ويمضي ، إذا ما بادهته العظائم\nوما كل ليث يغنم القوم زاده … إذا خفقت تحت الظلام الضراغم"},{"id":"diwan-radi:567","bookId":"diwan-radi","type":"poem","seq":567,"chapter":"البحر: كامل تام","title":"شوق يعرض لا إلى الآرام","page":"","text":"شوق يعرض لا إلى الآرام … وجوى يخادعني عن الأحلام\nومقيل صبر شذبته يد الهوى … في غير ما طرب ولا استغرام\nبل في انتزاع المجد من سكناته … بمطالب تسطو على الأيام\nومناقب تبقى ويفنى أهلها … إذ كل عيش فرصة لحمام\nلعذرت من في المجد يمرض فكره … وتكن فيه بواطن الآلام\nيا راكبا تخدي به عيرانة … سرح تشق جلابب الآكام\nخوضاء تحسب عينها ماوية … نظرت بها الفلوات شخص غمام\nجار كأن ربابه متعلم … شيم الرياح الهوج في الأقدام\nأقر السلام فتى تخاوص هيبة … عنه عيون تحيتي وسلامي\nسيف صقيل أغمدته عداته … فاستل وهو من الأعادي دام\nما ضره من أن يشام وما اقتنى … صدأ يشبه نصله بكهام\nإن غبت عنا فالقلوب حواضر … في حيث أنت ، نوازع الأوهام\nونفوسنا مرضى تشبث منكم … بثنا يطهرها من الأسقام\nيا أيها ذا الندب دعوة مدنف … علقت ضمائره بكل غرام\nلما ذكرتك عاد قلبي شوقه … فبكين عنه مدامع الأقلام\nخلفتني زرعا فطلت وإنما … ذاك الغرار نمي إلى الصمصام\nكم مدحة لي في علاك كأنما … تفتر عن خلق الغمام الهامي\nأكدت علي الأرض من أطرافها … وتدرعت بمدارع الإظلام\nوعهدتها خضراء كيف لقيتها … أبصرت فيها مسرحا لسوامي\nأشكو وأكتم بعض ما أنا واجد … فأعاف أن أشكو من الإعدام\nوإذا ظفرت من المناقب بالمنى … أهونت بالأرزاق والأقسام\nجاءتك تحدوها يدا ذي فاقة … وهي السفين له إلى الأنعام\nفاعرف له ما مت من شعري به … فلقد أتاك بحرمة وذمام"},{"id":"diwan-radi:568","bookId":"diwan-radi","type":"poem","seq":568,"chapter":"البحر: متقارب تام","title":"هو الدهر فينا خليع اللجام","page":"","text":"هو الدهر فينا خليع اللجام … فطورا يغير ، وطورا يحامي\nوإني أروعه بالودا … ع ، حتى يخادعني بالسلام\nفمن عرف العيش خبت به … عزائمه في طريق الحمام\nأريد من الدهر حظ الجبا … ن لا قدر حظ الشجاع الهمام\nفأي منى لم يسمها نوالي … وأي على لم يطأها اعتزامي\nقطعت مفازة هذا الرجاء … ولكن جدي بعيد المرام\nأخفض عزمي عن رتبة … أبلغها بالحظوظ السوامي\nلعا لمناي وإن لم تصب … فما عثرت برجاء اللئام\nوما احتشمت من يدي النصو … ل إلا مهزة نصل كهام\nألم يشرب الصبر قلبي ، ولا ان … انثني مرحا والعوالي ظوامي\nألم أسر في ليلها والعجا … ج يلحم بين الرعيل اللهام\nأكلل بالطعن يوم النزال … خدودا تشف لغير اللطام\nإذا عصفر الخوف ماء الوجوه … رآها من الدم حمر الوسام\nعدوي اقع على ذلة … فكم زل من أخمص عن مقامي\nشمخت علي بأنف رأي … ت معطسه داميا من زمامي\nوأصبحت تعطو بعين الأبي … وذفراك مقروحة من لجامي\nتروم ابتزازي فضلي ، وذاك … إذا فك أطواق ورق الحمام\nأما يحلم الدهر في فتية … أماتوا الملام بجهل المدام\nعقار يلاحظ منها الكؤو … س أفواهنا بجفون دوام\nوأيامنا من خمار الشباب … نشاوى تجر ذيول العرام\nأعيذك من خجلات الهوى … إذا رمقته عيون الملام\nوإن يرشف الهجر ماء الوصال … وأن يهتك العذر سجف الذمام\nمنحتك صدق وداد يتوق … إلى رنقه كل هذا الأنام\nوكم ليلة قبل أثكلتها … وأثكلتها في طيف المنام\nإلى أن بدا فجرها مسفرا … يمزق عنها فضول اللثام\nتخادعنا نفحات النسيم … إذا عبقت بحواشي الظلام\nوقد شملته شفوف الشمال … ورصع قطريه قطر الرهام\nتثور إليه سوام اللحاظ … وتسرح من حسنه في مسام\nولو وجد الزهر وجدي عليك … لاصفر فيه خدود الثغام\nذعرت الهموم بخطارة … تسيل بها في قلوب الإكام\nتلثم منسمها في الثرى … على الركض ميسم أيدي النعام\nوأنكحت أخفافها سيرها … لعزم ولود وأمر عقام\nتخايل بين غريرية … زوافر تكسو الثرى باللغام\nوماء وردت على كروها … وعرجت عنه قتيل الأوام\nمريض المشارع مما تريق … عليه الرياح دموع الغمام\nيخيل لي أن نجم السما … ء يرعد في صفو تلك الجمام\nوطفل الدجى في حجور البلا … د يطعم بالفجر مر الفطام\nتزاحم أنجمه للأفو … ل ، والبدر في إثر ذاك الزحام\nويهماء بالقيظ محجوبة … تطالعنا في هبوب السهام\nتعقل شارد وهج الهجير في … في جوها بخيوط السهام\nوبكر من القطر حتى كأن ما … افتضها غير غيم جهام\nمماطلة ركبها بالورو … د إلا أذا حان ورد القطامي\nقطعت ، وكالئتي همة … إذا أسمع الرعب قالت : صمام\nوملتهب السرد عاري الرما … ح مرتعد البيض دامي الحوامي\nقليل حيا الرمح عند الطعان … وقور الجواد سفيه الحسام\nتطرز شمس الضحى بيضه … إذا انفرجت عنه سجف القتام\nإذا سار فالشمس مستورة … ووجه الثرى بارز الخد دام\nحللت حبى نقعه بالطرا … د لما احتبى فرسي بالحزام\nوإني شقيق الوغى والندى … رضيع لبان المعالي الجسام\nإذا مضر ظللتني القنا … وسالت قبائليها من أمامي\nلبست بها جنة لا يف … ض مسرودها بنبال المرامي"},{"id":"diwan-radi:569","bookId":"diwan-radi","type":"poem","seq":569,"chapter":"البحر: مجزوء الوافر","title":"لأمر يا بني جشم","page":"","text":"لأمر يا بني جشم … حبست الماء في الأدم\nوقلقلت الجياد دوا … مي الأشداق باللجم\nوأزعجت القطا الوسنا … ن بالمخطومة الرسم\nتفلت في الدياجي عن … عقال الأين والسأم\nوتقرو كل مجهلة … بلا نضد ولا علم\nوكم ليل رقدت به … خليا من يد السقم\nونار بت أرمقها … كلي الريح بالعلم\nألمت بها ، وموقدها … شفاء الداء من ألمي\nوأين ضرامها مما … بأحشائي من الضرم\nقرير العين بالأحبا … ب أرعى روضة الحلم\nوإما إن يراني العزم … م بين ضمائر الخيم\nوإما شاردا في البيد … حشو حيازم الظلم\nفدى عزمي وصدقي ك … كل معتزم ومتهم\nوكل مشيع يصبو … إلى المأثورة الخذم\nإذا بعد الكلام دنت … علي مسافة الكلم\nولي خلقان ما صلحا … لغير السيف والقلم\nوأي خميلة شرقت … على الأيام من شيمي\nأزاهير ترفع عن … قبول مواهب الديم\nنسيم نشره عبق … يجر سوالف النعم\nأنا ابن البيض والبيض … الظبى والخيل والنعم\nوكل مطهم تنبو … حوافره من الأكم\nوكل مثقف يحتل … حيث مواطن الهمم\nوكل مهند يست … ن في الأعناق والقمم\nوكل أغر قد شرقت … خلائقه من الكرم\nضروب حيث تعثر شف … رة الصمصام باللمم\nوطعان إذا ما النق … ع عصفر ثوبه بدم\nوقومي الضامنون الأم … من إن هجموا على حرم\nإذا ما خائف غلبت … عليه سطوة العدم\nقروه بعد ما عقدوا … عليه تمائم الذمم\nإلى أن تكشف المكتو … م عن خداعة التهم\nوأصبح من أسر الغي … ي معتذرا من الجرم\nوصارت غاية المغت … ر جانحة إلى الندم\nوصرح كل قول عن … غرور الحلف والقسم\nأماني استركت كل … ل صبار على الألم\nكفاك بأن عرضك من … طروق العار في ذممي\nوذلك عصمة مني … بحبل غير منجذم\nوحسبك أن يفل شبا … هجوك أشعر الأمم"},{"id":"diwan-radi:570","bookId":"diwan-radi","type":"poem","seq":570,"chapter":"البحر: متقارب تام","title":"أما آن للدمع أن يستجم","page":"","text":"أما آن للدمع أن يستجم … ولا للبلابل أن لا تلم\nفتلهو عزائمنا بالخطوب … وتهزأ أجفاننا بالحلم\nفإنا بنو الدهر ما نستفي … من نشوة الهم حتى نهم\nولا نصحب الليل حتى نخال … كواكبه في الفيافي بهم\nولا بد من زلة للفتى … تعرفه كيف قدر النعم\nفحسن العلى بعد حال الخضوع … وطيب الغنى بعد حال العدم\nأأرجو المعالي بغير الطلاب … ومن أين يحلم من لم ينم\nإذا صال بالجهل قلب الجهو … ل فاعذر فما كل جهل لمم\nرأى الدهر يعصف بالفاضلين … فحب من النقض أن يغتنم\nستقبرني الطير كيلا أكون … سواء وأمواته في الرجم\nذم رجالا بترك المديح … وبعض السكوت عن المدح ذم\nصل اليأس وانهض بعبء الخطوب … فما يثقل الظهر إلا الهرم\nولا تهجر العزم عند المشيب … فليس عجيبا بهم يهم\nومني في ثوب هذا الزما … ن عضب ، إذا ما سطا أو عزم\nوما حلية البيض صوغ اللجين … ولكن حلاها دماء القمم\nأمرخي ذؤابة ذاك الهجير … على منكبي مجهل أو علم\nأرحنا نرح وترات المطي … فإن بها ما بنا من ألم\nويا أهيفا رمقته العيون … ورفت عليه قلوب الأمم\nتضرم خداه حتى عجبت … لعارضه كيف لم يضطرم\nلئن لم تجد طائعا بالنوال … لقد جاد عنك الخيال الملم\nومثلك ظالمة المقلتين … تلاقى الجمال عليها وتم\nلها في الحشا حافز كلما … جرى الدمع دل عليه ونم\nأقول لها ، والقنا شرع … ويرغم من قومها من رغم\nلنا دون خدرك نجوى الزفير … ومجرى الدموع وشكوى الألم\nوإلا فقرع صدور القنا … ووقع الظبى وصليل اللجم\nونقبلها كذئاب الردا … ه ، تمري علالتهن الجذم\nدفعن على غفلات الظنو … ن يمضغن مضغ العليق الحكم\nإلى أن تلطمهن النسا … ء بالخمر دون طريق الحرم\nأجب أيها الربع تسآلنا … فلست على بعدهم متهم\nفكيف وأنت مريض الطلول … ضجيع البلا ونجي السقم\nكأنك لم يعتنقك النسيم … ولا مال نحوك قطر بفم\nولا نشرت فيك تلك الرياح … غدائر من مزنة أو جمم\nتنثر فيك سحاب الحيا … فطوق جيدك لما انتظم\nودرت عليك ثدي الغمام … كأن رباك سقاب الديم\nثرى يرمق الغيث عن مقلة … بها رمد من رماد الحمم\nومن أين تعرفك اليعملا … ت والدمع في خدها مزدحم\nولكن أحست بأعطانها … وأوطانها في الليالي القدم\nأحن إليك ، وتأبى المطي … بخد ترابك إن يلتطم\nوخرق تدافعه المقربا … ت خوفا وتنفر منه الرسم\nتجللت فيه رداء الظلام … وسرت ، وحاشيتاه الهمم\nعلى كل خطارة لم تزل … تجاذبنا السير حتى انفصم\nخرقنا مع الشمس تلك الفلاة … وجبنا مع الليل تلك الأكم\nصلينا بجمرة ذاك الهجير … وعدنا بفحمة هذي العتم\nكأن مناسمها في السرى … تلاعب بين الحصى بالزلم\nومال النهار بأخفافها … إلى أدعج بالدجا مدلهم\nزحمن بنا الليل في ثوبه … فكادت مناكبه تنحطم\nنعانق بيضا كأن الصدا … بأطرافها شحبة ، أو غمم\nوقد لمعت من حواشي الغمود … كما نصلت أنمل من عنم\nوقلص عنا قميص الظلام … فكان بأنف الدياجي شمم\nويوم يرف عليه الردى … بأجنحة المصلتات الخذم\nمتى انسل لحظ ذكاء به … فأجفانه قادمات الرخم\nعلي طعان يرد الجوا … د بالدم ألمى مكان الرثم\nوأيد تجيل قداح الرماح … وباع المعرد عنها برم\nقلوب كأسد الشرى الضاريات … وأحشاوهم دونها كالأجم\nفما ترشف الماء إلا اعتلالا … ولا تجرع الماء إلا قرم\nإذا حسروا قال سيف الحمام … وأعطافه علقا تنسجم\nأللطعن تهتك هذي النحور … وللضرب تكشف هذي القمم\nإذا صحبوا الدم في الباترات … فلا صحبوا ماءهم في الأدم\nمضوا ما طوى العذل من جودهم … ولا أتبعوا المال عض الندم\nوسالت لمجدهم غرة … تكاد تكون حجال القدم\nقد استحيت السمر من طعنهم … فكادت لإفراطه تحتشم\nهو الطعن يفتر منه الجواد … ولو كان ذا مرح لابتسم\nردي أحمر الماء ، قب الجياد … فأبيض غدرانه للنعم\nغناء ظبانا عويل النساء … وقرع قنانا لطام اللمم\nأليس أبونا أعز الورى … جنابا ، وأكرم خالا وعم\nكأنك تلقى به السمهري … إذا مد يوم وغى ، أو أتم\nيقد ، إذا ما نبا العاجزون … وضرب الظبى غير ضرب القدم\nأسرة كفيه عمر الزمان … جداول ماء الردى والكرم\nفإما تفيض بغمر النوال … على المعتفين ، وإما بدم\nتعوذ من خوفه العاصفات … إذا عصفت في حماه الأشم\nوكان إذا رام خدع العلى … تقنصها ، والعوالي خطم\nيقي كل شيء ، فلو يستطي … غدا لخدود الأعادي لثم\nويرضى إذا قيل يا ابن النجاد … ويدعو الجياد بنات الحزم\nفتى لو أذم على صبحه … لما جاز في الضوء أمر الظلم\nوأهيف إن زعزعته البنا … ن أمطر في الطرس ليلا أحم\nيشيب إذا حذفته المدى … وتخضب لمته لا هرم\nوتنطف عن فمه ريقة … سويداء تقتل من غير سم\nله شفتان فلو كانتا … لسانا لما بان عنه الكلم\nوربتما ظنها الخائفون … لسان فم الأرقم بن الرقم\nله سبتة بين لهبي صفا … يقولون نام ولما ينم\nوأنت ابنة الفكر قابلتنا … بعقد لجيد العلا منتظم\nتروقين أسماعنا في النشيد … كأنك من كل لفظ نغم"},{"id":"diwan-radi:571","bookId":"diwan-radi","type":"poem","seq":571,"chapter":"البحر: طويل","title":"ألا خبر عن جانب الغور وارد","page":"","text":"ألا خبر عن جانب الغور وارد … ترامى به أيدي المطي الرواسم\nوإني لأرجو خطوة لوذعية … تجيب بنا داعي العلى والمكارم\nنداوي بها من زفرة الشوق أنفسا … تطلع ما بين اللهى والحيازم\nوإني ، على ما يوجب الدهر للفتى … ولو سامه حمل الأمور العظائم\nمقيم بأطراف الثنايا صبابة … أسائل عن أظعانكم كل قادم\nوأرقب خفاق النسيم ، إذا حدا … من الغرب أعناق الرياح الهواجم\nبنات السرى هذا الذي كان قلبه … يسومك إن تصلي بنار العزائم\nومن كل وضاح الحسام مشمرا … إذا شحبت فينا وجوه المظالم\nيمسح أضغان العدو وإنما … يقبل ثغرا من ثغور الأراقم\nإذا شهد الحرب العوان تدافعت … صدور المواضي في الطلى والجماجم\nوعفر فرسان العدا ، ودماؤهم … جوامد ما بين اللحى والعمائم\nحدا فقده كل العيون إلى البكا … فقطع أرسان الدموع السواجم\nوما خطرت منه على المجد زلة … فيقرع في آثارها سن نادم\nألا ليت شعري هل أبيتن ليلة … ألاطم أعناق الربى بالمناسم\nوهل تقذف البيداء رحلي إليكم … تنفس عن ليلي أنوف المخارم\nولا بد أن ألقى العدا في خميلة … من الخيل تولى بالقنا والصوارم"},{"id":"diwan-radi:572","bookId":"diwan-radi","type":"poem","seq":572,"chapter":"البحر: طويل","title":"ألا ليت أذيال الغيوث السواجم","page":"","text":"ألا ليت أذيال الغيوث السواجم … تجر على تلك الربى والمعالم\nولولاك ما استسقيت مزنا لمنزل … فأحمل فيه منة للغمائم\nويا رب أرض قد قطعت تشق بي … جيوب الملا أيدي المطي الرواسم\nوليل طويل الباع قصرت طوله … إليك ، وقد ألقى يدا في المخارم\nوعيس خطت عرض الفلا برحالنا … تزعزع في الأعناق رقش التمائم\nإذا فاح ريعان النسيم رأيتها … إلى الجانب الغربي عوج الخياشم\nيسير بنا مستنجد بعصابة … أناملها ملوية بالقوائم\nتباري نجوم الليل بالبيض والقنا … وضوء بدور هامها في العمائم\nحقيق بان لا يهتك الدهر ثوبه … عن العار كأس من عجاج الملاحم\nفأين من الدهر استماع ظلامتي … إذا نظرت أيامه في المظالم\nفهل نافعي أن ينصر المجد عزمتي … على هذه العلياء ، والمال ظالمي\nأنا الأسد الماضي على كل فعلة … تمشي شفار البيض فوق الجماجم\nوفي مثلها أرضيت عن عزمي المنى … وصافحت أطراف القنا والصوارم\nولم أدر أن الدهر يخفض أهله … إذا سكنت فيهم نفوس الضراغم\nوما العيش إلا فرحة إن هجرتها … سطوت على الدنيا بسطوة حازم\nسأصبر حتى يعلم الصبر أنني … ملكت به دفع الخطوب الهواجم\nآخذ ثاري من زمان تعرضت … مغارمه بيني وبين المغانم\nوما نام إغضاء عن الدهر صرمي … ولكنن أبقي على غير راحم\nوإن أنا أهلكت الزمان فما الذي … يصدع عزمي في صدور العظائم\nوركب سروا والليل ملق جرانه … على كل مغبر المطالع قاتم\nحدوا عزمات ضاعت الأرض بينها … فصار سراهم في صدور العزائم\nتريهم نجوم الليل ما يبتغونه … على عاتق الشعرى وهام النعائم\nوغطى على الأرض الدجى فكأننا … نفتش عن أعلامها بالمناسم\nوفتية صدق من قريش ، إذا انتدوا … أروك عطاء المال ضربة لازم\nإذا طردوا في معرك المجد قصفوا … رماح العطايا في صدور المكارم\nوإن سحبوا خرصانهم لكريهة … تصدع صدر الأرض عن قلب واجم\nوتثبت في عليا معد غصونهم … ثبات بنان في قلوب البراجم\nأيسمح لي هذا الزمان بصاحب … طويل نجاد السيف من آل هاشم\nإذا أنا شيعت الحسام بكفه … مضى عزم مشبوح الذراع ضبارم\nوإن ضافه الهم النزيع رمى بها … نزائع لا يعلفن غير الشكائم\nولست بمستصف سوى كل خائض … إلى كل بحر بالقنا متلاطم\nأنامله في الحرب عشر أسنة … ولكنها في الجود عشر غمائم\nطموح ، إذا غض الشجاع لحاظه … وأطرق عن برق الظبى كل شائم\nأعاذل ما سمعي للومك مرتعا … إذا كان مصروفا إلى غير لائم\nأبثك عن ليل تعسفت متنه … كأني أمشي في متون الأراقم\nيخيل لي أن النجوم ضمائر … تقلقل فيه خشية من عزائمي\nلقيت ظلام الليل في لون مفرقي … وفارقته والصبح في لون صارمي\nأجوب آجام المنايا وأسدها … تروعني من بينها بالهماهم\nوبيني وبين القوم من آل يعرب … ضغائن تثنيني زهيد المطاعم\nإذا ما جنوا من مالهم ثمر العلى … جنيت المعالي من غصون اللهاذم\nأغر بني فهر وعيد مشاجع … وأي وعيد بعد وقع الصوارم\nأيوعدنا من عطل البيض والقنا … وأقسم لا ينجو بغير الهزائم\nعشية خضنا بالضوامر ليلهم … وفي كل جفن منهم طيف حالم\nنريهم صدور السمر بين نحورهم … فما استيقظوا إلا بقرع الحلاقم\nكأن الكرى يقتص من طول نومهم … فيسهر منه بالقنا كل نائم\nوكل غلام خالط البأس قلبه … يقطع أقران الأمور الغواشم\nونحن دلفنا للأراقم فتية … يضيفون أطراف القنا في الحيازم\nتطلع من خلف العجاج كأنما … تطالعهم منها عيون القشاعم\nإذا اشتجر الضرب الدراك تمطقت … إلى الطعن أفواه النسور الحوائم\nوولوا على الخيل العتاق كأنهم … تزاحم غيم العارض المتراكم\nتفيض عيون الطعن بالدم منهم … ويغلبها فيض العيون السواجم"},{"id":"diwan-radi:573","bookId":"diwan-radi","type":"poem","seq":573,"chapter":"البحر: بسيط تام","title":"هذي الرماح عصي الضال والسلم","page":"","text":"هذي الرماح عصي الضال والسلم … لولا مطاعنة الآراء والهمم\nإن الذوابل والأقلام أرشية … إلى العلى ، لملوك العرب والعجم\nليس السيوف عن الأقلام مغنية … الفري للسيف والتقدير للقلم\nكالكوكب انتشرت منه ذوائبه … وموقد النار يذكيها على أضم\nأو كالشجاع تمطى بعد هجعته … يرخي لسانا كغرب اللهذم الخذم\nغران ما اجتمعا إلا لمنصلت … على الحوادث صبار على الألم\nلهاشم غرر تلقى لسائلها … طلاعة من ثنايا البأس والكرم\nوخضخض السجل في قعر القليب فلم … ينزح له غير مكتوم من الوذم\nوأصبح البرق يخفى حر صفحته … عن المرابع ، أو يبرا من الديم\nوأجدب القوم واضطرت أكفهم … وإن تطهرن من إثم إلى الزلم\nوقل عند كرام الحي نائلهم … حتى جلا يوم نحر منزل البرم\nوكل سائمة باتت تمسحها … كف المسيم غدت لحما على وضم\nوصوح النبت حتى كاد من سغب … فيهم يصوح نبت الهام واللمم\nكانوا السحائب ترمي من كنائنها … مقاتل المحل كالمثعنجر الرذم\nأرغت معد وأثغى من يناضلها … ومن يقايس بين الشاء والنعم\nدنيا ترشف عيشي وهي كالحة … غضبى وأبسم فيها بادي الكظم\nكالخمر يعبس حاسيها على مقة … والكأس تجلو عليه ثغر مبتسم\nالجد لا يقتضي إسماع ملهية … والهزل يكمن في الأوتار والنغم\nوما ابن غيل تذيع الموت طلعته … إذا تطلع غضبانا من الأجم\nيجلو دجا شدقه عن صبح عاصلة … مطرورة كشبا المطرورة الخذم\nيوما بأقدم مني في ململمة … شعواء تعرف بالعقبان والرخم\nواليوم قطع قرع البيض حبوته … عن العجاج وخيل الله في الحرم\nإذا العوالي على أشداقها هجمت … أعدى اللمى بالدم الجاري على الرثم\nوالطعن ينتجع الأجساد أنفسها … والضرب يبخل بالبقيا على القمم\nورب ليل كأن النار مقلته … والكلب يسمعه النائي عن الصمم\nسهرته ، والأماني ترتقي فكري … حتى تطلع من همي إلى هممي\nأراقب الضيف إن يرعى مطيته … وبيننا منكب عال من الظلم\nأوحى الظلام إلى الإصباح إن فتى … أسرى وما خدعته لذة الحلم\nعلى جمالية توفي الزمام خطا … تكاد تسبقه من خفة القدم\nخراجة الصدر إن صاح المهيب بها … على الوجى من صدور الأينق الرسم\nحرف تبوع بي في كل مجهلة … كأنني راكب منها على علم\nتلقي الأجنة قتلى في مسالكها … دياتها في رقاب القصد والأمم\nمتى تنسم مس السوط جلدتها … زافت كما زاف عنق المصعب القطم\nتطغى الخطام إذا ما البر صافحه … تيار بحر بأيدي العيس ملتطم\nهوجاء ما التفتت يوما على ألم … من السياط ولا حنت إلى قرم\nإذا جذبت لذكر السير مقودها … كأنما جذبتها سورة اللمم\nما يطلب الدهر والأيام من رجل … يعوذ بالحمد اشفاقا على النعم\nإذا اقتضته الأماني بعض موعده … غطى بستر العطايا عورة العدم\nمن مد معصمه مستعصما بيدي … عصمته بإخاء غير منجذم\nومن اشيعه يأمن من لوائمه … ولو رموه بجراح من الكلم\nولو هتكت حجاب الغيب لافتضحت … أجفان كل مريب اللحظ متهم\nكفى الذي سبني أني صبرت له … فاستنصر العذر واستحيا من الحرم\nبردي عفيف إذا غيري لفجرته … كانت مناسج برديه على التهم\nأنا زهير فمن لي في رمانك ذا … ببعض ما افترقت عنه يدا هرم\nإذا العدو عصاني خاف حديدي … وعرضه آمن من هاجرات فمي\nجعلت سمعي على قول الخنا حرما … فاي فاحشة تدنو إلى حرم\nيكاد أنفي إذا ما استاف مرتبة … من التواضع ينضو خلعة الشمم\nجدي النبي ، وأمي بنته ، وأبي … وصيه وجدودي خيرة الأمم\nلقصدنا تتمطى كل راقصة … هوجاء تخبط هام الصخر والرجم\nبكل أشعث منقد القميص ، إذا … جد النجاء به عن أطيب الشيم\nلنا المقام ، وبيت الله حجرته … في المجد ثابتة الأطناب والدعم\nومولدي طاهر الأثواب تحسبني … ولدت في حجر ذاك الحجر والحرم"},{"id":"diwan-radi:574","bookId":"diwan-radi","type":"poem","seq":574,"chapter":"البحر: مجزوء الكامل","title":"قال الضمير بما علم","page":"","text":"قال الضمير بما علم … أنت المحكم فاحتكم\nخجل ينمق عذره … والعذر شاهد من ندم\nلا تلزمني زلة … سفهت علي بها القدم\nفلقلما غضبت على … أشبالها أسد الأجم\nهل أنت إلا البدر يط … رف ضوءه مقل الظلم\nصافحت راحته ، وحش … وبنانها عبق الكرم\nفكأنما جذبت يدي … بذؤابتي سيل العرم\nجاءت كأن بعطفها … خجل المحول من الديم\nحطت إليك من الضما … ئر في رشاء من ندم"},{"id":"diwan-radi:575","bookId":"diwan-radi","type":"poem","seq":575,"chapter":"البحر: وافر تام","title":"عجزنا عن مراغمة الحمام","page":"","text":"عجزنا عن مراغمة الحمام … وداء الموت مغرى بالأنام\nوما جزع الجزوع وإن تناهى … بمنتصف من الداء العقام\nوأين نحور عن طرق المنايا … وفي أيدي الردى طرف الزمام\nنوائب ما أصخن إلى عتاب … يطول ولا خدرن على ملام\nهي الأيام تأكل كل حي … وتعصف بالكرام وباللئام\nوكل مفارق للعيش يلقى … كما لقي الرضيع من الفطام\nوكم ليد النوائب من صريع … بداء السيف أو داء السقام\nفمن ورد المنية عن وفاة … كآخر عاثر العرنين دام\nولو أمن الجبان من المنايا … لأغمد سيفه البطل المحامي\nوما يغتر بالدنيا لبيب … يفر من الحياة إلى الحمام\nتنافر ثم ترجع بعد وهن … رجوع القوس ترمح بالسهام\nخطوب لا أجم لها جوادي … وعزم لا أحط له لثامي\nرأيت الموت يبلغ كل نفس … على بعد المسافة والمرام\nسواء إن شددت له حزيمي … زماعا ، أو حللت له حزامي\nعزاءك ما استطعت ، فكل حزن … يؤول به الغلو إلى الأثام\nوعمر المرء ينقص كل يوم … ولا عمر يقر على التمام\nوما تنجي الدموع من المنايا … فترسلها بأربعة سجام\nوكنا عند مختلف الليالي … وكر الدهر عاما بعد عام\nإذا أخذ الردى منا رجعنا … إلى صبر يشرد بالغرام\nوكان الصبر يقبض كل وجد … كما قبض الصباح من الظلام\nوفي حسن العزاء لنا مجير … يخلصنا من الكرب العظام\nأساكنة التراب وكل حي … جدير أن يغيب في الرجام\nتقنصك الردى عرضا وأمسى … يجاذبك المسير عن المقام\nولجلج من نعاك ، وكل ناع … يجمجم أو يلجلج في الكلام\nوكل حشى عليك كأن فيه … سنان الرمح أو طرف الحسام\nأيا قبرا تقسم كل صبر … وقلقل عبرة المقل الدوامي\nأقامت فيك ، ماجدة حصان … كماء المزن من بيض الخيام\nتطرقك النسيم من الخزامى … ودرت فيك أنواء الغمام\nوأصبحت الشفاه عليك فوضى … تهافت بالتحية والسلام\nفما بكت الحمام عليك إلا … كما غنتك أصوات الحمام\nألا لله كل فتى أبي … عزيز الأنف يغضب للذمام\nيجير من الزمان ، إذا تغاوى … بصبر للنوائب واعتزام\nوأيام تفلل من غروبي … على مضض وتنقص من عرامي\nتلاعب بي أماما أو وراء … طارد الشيخ يلعب بالغلام\nبراني الدهر سهما ثم ولى … فجردني من الريش اللؤام\nوها أنا ذا أبثك كل بيت … رقيق النسج رقراق النظام"},{"id":"diwan-radi:576","bookId":"diwan-radi","type":"poem","seq":576,"chapter":"البحر: مجزوء الكامل","title":"لله جيد ما تم","page":"","text":"لله جيد ما تم … غير أحشاء المكارم\nفتطوق العلياء ، وه … وقريب عهد بالتمائم\nينطت بعطفيه حما … ت المغانم والمغارم"},{"id":"diwan-radi:577","bookId":"diwan-radi","type":"poem","seq":577,"chapter":"قصائد","title":"ألبستني نعما على نعم","page":"","text":"ألبستني نعما على نعم … ورفعت لي علما على علم\nوعلوت بي حتى مشيت على … بسط من الأعناق والقمم\nفلأشكرن نداك ما شكرت … خضر الرياض صنائع الديم\nفالحمد يبقى ذكر كل فتى … ويبين قدر مواقع الكرم\nوالشكر مهر للصنيعة إن … طلبت مهور عقائل النعم"},{"id":"diwan-radi:578","bookId":"diwan-radi","type":"poem","seq":578,"chapter":"البحر: بسيط تام","title":"نهنه عتابك إلا أن هفا جرم","page":"","text":"نهنه عتابك إلا أن هفا جرم … بعض العتاب على الإخلاص متهم\nمالي أقول فلا تصغي بسامعة … تصامم بك عن ذا القول أم صمم\nر رفقا بأنفك لا تشمخ على مضر … وانظر بعينك من زموا ومن خطموا\nفلست أول من راقت له حلل … ولست أول من راحت له نعم\nمن أضمر الصد عمن ليس يضمره … بغيا ، مشى في نواحي سره الندم\nمن أنهضته لقطع الود عذرته … كان المذمم منه الكف والقدم\nمن ساء ظنا بمن يهواه فارقه … وحرضته على إبعاده التهم\nمتى تهجم غدرا سر عهدكم … فإن عهدي على غدر بكم حرم\nيصد عني من ودي له صدد … ولا أؤم الذي ودي له أمم"},{"id":"diwan-radi:579","bookId":"diwan-radi","type":"poem","seq":579,"chapter":"البحر: طويل","title":"قليل من الخلان من لا تذمه","page":"","text":"قليل من الخلان من لا تذمه … وكثر من الأعداء من أنت همه\nوغير بعيد منك ناء تزوره … وغير قريب قاطن لا تؤمه\nمصافيك في الأيام أنفك أنفه … إذا جل ما تلقى ، ورغمك رغمه\nألا ليت بين الحي لم يقض يومه … وليت ظليع الذود لم يبر سقمه\nوليت أديم الأرض يعرى كما اكتسى … من الناس أو يعفو كما بان رسمه\nفماذا الورى ممن يراد بقاؤه … ولا الموت معذول إذا جار حكمه\nتباشر عيني فيهم ما سوءها … ويلقى جناني منهم ما يغمه\nسقى الله قلبا بين جنبي ريه … وما نافع قلبي من الماء جمه\nولكن مشتاقا إذا بلغ المنى … تقضى أوام القلب أو زال وغمه\nأما علم الغادون والقلب خلفهم … يضم زفيرا يصدع الصلد ضمه\nبأن وميض البرق ما لا أشيمه … وأن نسيم الروض ما لا أشمه\nورب وميض نبه الشوق ومضه … ورب نسيم جدد الوجد نسمه\nأضعت الهوى حفظا لحزمي ، وإنما … يصان الهوى في قلب من ضاع حزمه\nوطيف حبيب راع نومي خياله … وعرفني طول الليالي ملمه\nوما زارني إلا ليخجل طيبه … نسيم الصبا أو يفضح الليل ظلمه\nتطلع من أرجاء عيني دمعها … وما كاد لولا الوجد ينقاد سجمه\nألا هل لحب فات أولاه رجعة … وإن زاد عندي أو تضاعف اسمه\nليالي أسري في أصيحاب لذة … ومخ الدجا رار وقد دق عظمه\nوأغدوا على ريعان خيل تلفها … صدور القنا والنقع عال احمه\nرأيت الفتى يهوى الثراء ، وعمره … يرى كل يوم زائدا منه عدمه\nعقيب شباب المرء شيب يخصه … إذا طال عمر أو فناء يعمه\nطليعة شيب بعدها فيلق الردى … برأسي له نقع وبالقلب كلمه\nأغالط عن نفسي حمامي ، وإنما … أداري عدوا مارقا في سهمه\nوليس يقوم المرء يوما بحجة … إذا حضر المقدار والموت خصمه\nوأولى بمن يستخلف الدهر بعده … على صرمه أن يودع الأرض صرمه\nفوا عجبا للمرء ، والداء خلفه … ومن حوله الأقدار والموت أمه\nيسر بماضي يومه ، وهو حتفه … ويلتذ ما يغذى به ، وهو سمه\nورود من لآجال لا يستجمنا … وورد من الآمال لا نستجمه\nإلى كم أذود السيف عن هام عصبة … أما فيهم من يطعم السيف لحمه\nوعندي عال من دم الجوف شربه … وماضي الظبا من أسود القلب طعمه\nأقول لغر بي : لففت بضيغم … يؤد الأعادي خطفه ثم حطمه\nفدع هضبة منا بنى الله سمكها … فإن بناء الله يعييك هدمه\nومن عجب الأيام إني محسد … أعادى على ما يوجب الود حكمه\nوليس الفتى من يعجب الناس ماله … ولكنه من يعجب الناس علمه\nتشف خلال المرء لي قبل نطقه … وقبل سؤالي عنه في القوم ما اسمه\nأرى آخر الخلان ودا يسوءني … إذا هم واطى بين رأييه همه\nولو غير قلبي ضم ذا العزم شقه … ولكنه لا يقتل الصل سمه\nوأبلج لا يرضى عن العجز رأيه … تمد على أضوى من البدر لثمه\nإذا خلع الليل النهار سمت به … مآرب مضاء على ما يهمه\nوكم في نزار من نهيض نجيبة … إذا سل عضبا سابق الضرب عزمه\nأنيس بلقيان الحروب كأنما … تمطت به في ناشر النقع أمه\nإذا ضرع الأقوام من سوء نكبة … جلاها قويم الأنف فيها أشمه\nرفيع بيوت المجد كالجد جده … فخارا وفي العلياء كالخال عمه\nمهيب وقار الجانبين أبيه … ومخول مجد الوالدين معمه\nفمن خائف عند الليالي نجيره … ومن شعث بين المعالي نلمه\nوإني لدفاع بي العزم والمنى … إلى كل ليل يعقد الطرف نجمه\nوما تستدل النجم عيناي في الدجا … ضلالا ولكن مثل عيني جرمه\nشددنا بأيدي العيس كل ثنية … ومن دونها جون القرا مدلهمه\nومنخرق لا يقطع الطرف عرضه … ولا ينزوي عن أعين الركب خرمه\nتوهمت عصف الريح بين فروجه … يسر إلى سمعي مقالا يصمه\nوجيش يسامي كل طود عجاجه … ويفتر عنه كل واد يضمه\nتخطف أبصار الأعادي سيوفه … وتملأ أسماع القبائل لجمه\nإذا سار صبحا طارد الشمس نقعه … وإن سار ليلا طبق الأرض دهمه\nتراجع حمرا من دم الضرب بيضه … وتنجاب شقرا من دم الطعن دهمه\nصدمنا به الجبار في أم رأسه … وكان شفاء الرأس ذي الداء صدمه\nوما ضاقت الأقطار من دون فوته … ظبانا ولكن أوبق العبد ظلمه\nعذيري ممن ذم عهدي ، وقد نبا … مرارا ، وقلبي وادع لا يذمه\nتجرم لما لم يجد لي زلة … وأقصدني باللوم والجرم جرمه\nتعمدت بعدي عنه من غير سلوة … ليعلمني يوم النوى كيف طعمه\nوأجممته لا عن غناء ، وإنما … لأشربه في حر خطب أجمه\nوإني ، وإن والى على القلب حربه … لمنتظر أن يعقب الحرب سلمه\nولا تيأسن من عفو حر ، فإنما … تحلمه باق ، إذا ضاع حلمه\nأأطمع أن أنساك يوما ، وإنما … هواك ضجيع القلب مني وحلمه\nيقر بعيني منظر أنت قيده … \nوأنت الفتى لا عاجز عن فضيلة … وغير قليل من معاليه قسمه\nتجاوز بعمد واعف ، فالعتب إن يدم … على الخل يفسد ظن قلب ووهمه\nأرى آخر الخلان ودا يسؤني … ويمدح عندي أولا طال ذمه\nعلى أنني راض بما جر هجره … وهل أنا إلا القلب يلتاث جسمه"},{"id":"diwan-radi:580","bookId":"diwan-radi","type":"poem","seq":580,"chapter":"البحر: طويل","title":"بعادا لمن صاحبت غير المقوم","page":"","text":"بعادا لمن صاحبت غير المقوم … وبعدا لكل الري إلا من الدم\nإذا ظلم لم أمض فيها عزيمة … فساعة ليلي مثل حول مجرم\nومن شغفي بالطعن أغدو وذابلي … إذا قل جرم مال بي في التجرم\nوما أنا ممن يقبل الطعم قلبا … ولم تعلم الأرماح من أين مطعمي\nسأقدم لا مستعظما ما لقيته … توسع لي في الروع أو ضاق مقدمي\nفقد فجع الماضي لبيدا بأربد … وعزي قبلي مالك من متمم\nوعزم أعاطيه العوالي وحاجة … رميت بها ما بين أرض ومنسم\nوليس الفتى إلا الذي إن رأيته … رأيت غني النفس في ثوب معدم\nقليل مقام بين أهل وثروة … كثير طلوع بين واد ومخرم\nأمطلع يومي علي ولم أخض … دماء الأعادي بالوشيج المقوم\nولم أجهد السيف الطويل نجاده … أمام الظبى ، والنقع بالنقع يرتمي\nوليس شفاء النفس إلا مثقف … يعد ليوم بالغبار ملثم\nوكم لي من رماحة تزعج الحصى … بوابلها في معلم بعد معلم\nإذا الله لم ينصر حسامي على العدا … فما أنا إلا عرضة المتهضم\nوإن هو نجى من فم الموت مهجتي … نجوت ، وإلا كنت أول مطعم\nأبيت ولي في كل أرض عزيمة … تزعزع أعناق المطي المحزم\nومستوصيات بالذميل كأنما … يدارس إذآب الجديل وشدقم\nترى كل حمراء الملاط كأنما … تخلج في آماقها عرق عندم\nبخف كشدق الأعلم استصعبت به … على ظل عنق ذي عثانين مرجم\nكان الغلام الضرب في الرحل ريشة … خفت فوق زور من ظليم مصلم\nإذا أوجست حس القطيع وراءها … ألاحت بخيشوم كريم وملطم\nتخيل من فضل الزمام ابن رملة … له نهشات في مكان المخطم\nطلعن على ليل بنا ووصلنه … بأبلج لماع الجواشن معلم\nومن جعل القلب الجري دليله … فكل ظلام عنده غير مظلم\nبليت وأبلاني زماني بعصبة … يخوضون بي في كل غيب مرجم\nمذاييع للسر المصون ، وليتهم … أذاعوه طلق البرد لما ينمنم\nقليل حديث مارق غير مكثر … وبدء مقال وارد من متمم\nزمان الأذى عش فيه تشج بأهله … وتغض على ذل ومت فيه تعظم\nعلى أنني لا غالب الرأي بالهوى … ولا قائل للشوق إن ضل يمم\nولا قاطع بالظن ما كنت واصلا … ورب مغيظ قاطع بالتوهم\nوإني مماآلف بالجد باخل … بثغري فما يدري امرؤ أين مبسمي\nفراق من الأحباب أمضى من الردى … وأقطع للأقران من غرب مخذم\nلك الله من واد توركن عرضه … ونقبن فيه عن عرار وعظلم\nيبارين نفاح الخزامى عشية … بأطيب من ريح الخزامى وأنعم\nأغالب دمعي ثم يغلب جاريا … ومن لم يسل دمعا على الحب يظلم\nوما ذكرتك النفس إلا وضمها … إلى القلب باع الموجع المتألم\nخليلي ليس الدمع عني بدافع … ولوع غرام كالحريق المضرم\nوهل أنا إلا رب نفس معارة … وقلب معار للجوى والتألم\nإذا ما جوادي مر بي في ديارها … تقاضى زفيري دائبا بالتحمحم\nأحن ، ولا يرمى حنيني بتهمة … وأدنو ولا يعزى دنوي بمأثم\nوما منظر الحسناء عندي برائق … ولا نيلها والقرب عندي بمغنم\nإلى كم تصباني الغواني ، وبينها … وبيني عفاف مثل طود يلملم\nوإني لمأمون على كل خلوة … أمين الهوى والقلب والعين والفم\nوغيري إلى الفحشاء إن عرضت له … أشد من الذؤبان عدوا على الدم\nومن كان إنعام الوزير حبيبه … أغار الغواني بين بكر وأيم\nأبيت بها هادي الحشا في نوائب … يبيت لها غير بقلب مقسم\nوحيد العلى لا ينتجي غير نفسه … إذا عن خطب أو دنا يوم مغرم\nومنتصر يرعى بحلم حقوده … ويطرد أضغان العدا بالتكرم\nإذا عظم الطلاب لم يثن كفه … وإن طال نطق القوم لم يتجهم\nيزم إلى العافين أعناق ماله … ومال رجال مقرم لم يخطم\nكثير ارتياح القلب في عقب جوده … إذا جائد ألقى يدا في التندم\nسريع ، إذا داعي الطعان دعا به … غدا طاعنا قبل العدا في التلوم\nوما هم إلا قعقع البيض بالظبا … ورد القنا يجري على كل معصم\nولا ركز إلا أن تمير زجاجها … عواملها فضل النجيع المحرم\nوكل صباح شاحب من عجاجة … وشائع برد بالعوالي مسهم\nإذا عن جود قيل دفاع وابل … وإن عن روع قيل : تقحيم ضيغم\nيشن وجوه البيد في كل مسلك … بجر العوالي والرعيل المسوم\nفعال جري لا يزال مدافعا … إلى المجد طلاعا إلى كل معظم\nولكنه بالعز والمجد والعلى … أحق وأولى من سماء بأنجم\nأتته ولم يمدد يدا في طلابها … وما انقاد من قاد العوالي بمخطم\nولو لم يقر الغابطون بمجده … أقروا على رغم بفضل التقدم\nوما كذب الحساد للبدر ضائرا … وليس يضر الذم غير المذمم\nوحي حلال قد ذعرت بكبة … من الخيل لا ترعى ذماما لمحرم\nعلى حين حاصرت الظلام إليهم … بأرعن يردي في الحديد المنظم\nوما افتر يوم قط إلا لقيته … بوجه جلي ، أو بكف مغيم\nإذا مارق لاقاك غض عنانه … ورد أظافير القنا لم تقلم\nورب نسيب للرماح مغامر … حفيف الشوى عاري الجناحين أعلم\nذا هز يوما للغوار رأيته … أنم إلى الأرواح من كل لهذم\nيسرك في فل الصوارم والقنا … ويرضيك في رد اللهام العرمرم\nله ريقة تجري بما شاء ربه … كما حال سم بين أنياب أرقم\nأماليء أيام الندى كل عارض … وماليء أيام الوغى كل ملجم\nتهن قدوم المهرجان ، فإنه … إليك على الأيام ينمى وينتمي\nوما زار هذا العيد إلا صبابة … إليك بقلب طامح الوجد مغرم\nأتى يستفيد الجود منك ويجتلي … محاسنه من ثغرك المتبسم\nفلا عار أن تستنجد الكأس راحة … أضر بها حمل الجراز المصمم\nأراك بعين لا يسوءك لحظها … وأرعاك بالود الذي لم يذمم\nوفي نظري عنوان ما بين أضلعي … ورب لحاظ نائب عن تكلم\nوكم نظرة تستوهب القول من فمي … تكلف نطقي في جواب المكلم\nولست ولو خادعتني عن مطالبي … مطاوع عذالي عليك ولومي\nوأكرم مأمول وأشرف ماجد … جواد متى يندب إلى الجود يقدم\nأعيذك أن تظمي فتى كان طرفه … عقيدا لبرق العارض المترنم\nومن غره مال رضي ببشاشة … وعادم ماء قانع بالتيمم\nألا إن شعري فيك يبقى وغيره … تطير به أيدي الليالي وترتمي\nوتعقد طرفي منك في كل نظرة … طلاقة بدر بالمعالي معمم\nولولاك ما فاقت ببغداد ناقتي … ولا كنت إلا لاحقا بالمقطم\nوأولى بلاد بالمقام من الدنا … بلاد متى ينزل بها الحر يغنيم\nمدحت أمير المؤمنين ، وإنه … لأشرف مأمول وأعلى مؤمم\nفأوسعني قبل العطاء كرامة … ولا مرحبا بالمال إن لم أكرم\nوإني إذا ما قلت في غير ماجد … مديحا كأني لائك طعم علقم\nوإن رجائي زين ملة هاشم … لنعمى ، وحسبي من جواد ومنعم\nفكن شافعي يوما إليه لعله … يريش العواري من نبالي وأسهمي\nأغار على عليائه من مقصر … يقول ولم يرزق مقالي ولا فمي\nفإن شاء فالوسم الذي قد عرفته … مبين لعين الناظر المتوسم"},{"id":"diwan-radi:581","bookId":"diwan-radi","type":"poem","seq":581,"chapter":"البحر: وافر تام","title":"أرى نفسي تتوق إلى النجوم","page":"","text":"أرى نفسي تتوق إلى النجوم … سأحملها على الخطر العظيم\nوإن أذى الهموم على فؤادي … أضر من النصول على أديمي\nوإني ، إن صبرت ثنيت قلبي … على طرف من البلوى اليم\nولي أمل كصدر الرمح ماض … سوى أن الليالي من خصومي\nويمنعني المدام طروق همي … فما يحظى بها إلا نديمي\nوما أوفت على العشرين سني … وقد أوفى على الدنيا غريمي\nونجوى قد شهدت وعدت ألقي … عنان فمي إلى قلب كتوم\nوهول يرعد النسيان منه … ركبت معارض الجد المروم\nإذا ما حاجة قضيت بسيفي … شكرت لها يد الليل البهيم\nويعرفني العدو بوقع رمحي … إذا ما الوجه موه بالسهوم\nوما لي همة إلا المعالي … وذب الضيم عن نسب صميم\nوقود الخيل تركع من وجاها … وقد غلب النجيع على الكلوم\nتصبح في الطلى بدراك طعن … كرمح الشول زغن عن المسيم\nويذهلها إذا التقت العوالي … ضرام الطعن عن مضغ الشكيم\nوكل نحيلة كالسهم تصمي … عرانين الأماعز والخروم\nتريني الشمس أول من يراها … وآخر شأوها طلق الظليم\nوحث العيس تستلب الفيافي … بإملاء الذميل على الرسيم\nجزعن الليل ، والآفاق خلس … كأن نجومها نغل الأديم\nوأبلج مثل فرق الرأس نهج … قطعن وما قلقن من السؤوم\nوماء قد تخفر بالدياجي … عن الطراق والسلم المقيم\nوردن ولا دلاء لهن إلا … مشافرهن في الورد الجموم\nوعدن ، وقد وهى سلك الثريا … وكر الصبح في طلب النجوم\nوقد لاحت لأعيننا ذكاء … وراء الفجر كالخد اللطيم\nومختلط الندى أرج الخزامى … رطيب ذوائب الكلإ العميم\nأبحت حريمه إبلي ، فأمست … تغير شفاههن على الجميم\nألا هل أطرق السمرات يوما … بريء القلب من عنت الهموم\nوألصق عقلها بربى تراها … من الأنواء ضاحكة الوشوم\nأرى الأيام عادية علينا … ببيض من نوائبها وشيم\nيضل نفوسنا داء عقام … فيسلمنا إلى أرض عقيم\nونتبع بالدموع ، وأي دمع … يجير ، ولو أقام على السجوم\nويفردنا الزمان ، بلا قريب … يذم من الزمان ولا حميم\nونلقى قبل لقيان المنايا … رماح الداء تطعن في الجسوم\nفلو كانت خصوصا سر قوم … ولكن العناء على العموم\nويكثر مطلي الغرماء ، إلا … إذا راح الردى ، وغدا غريمي\nرأيت المال يرفع من سفيه … وعدم المال ينقص من حليم\nفليت كريم قوم نال عرضي … ولم يدنس بذم من لئيم\nيلوم وقد ألام وشر شيء … إذا لاقاك لوم من مليم\nأشب ، لأحرق الأعداء ، لحظي … فيرجعني إلى الإغضاء خيمي\nأبى لي الدم آباء تساموا … إلى عنقاء طيبة الأروم\nإذا اشتملوا على الأعداء عادوا … وقد غمروا الضغائن بالحلوم\nألا من مبلغ الأحياء أني … قطعت قرائن الزمن القديم\nوأني قد أبيت مقام رحلي … بوادي الرمث أو جبل الغميم\nوعن قرب سيشغلني زماني … برعي الناس عن رعي القروم\nوما لي من لقاء الموت بد … فمالي لا أشد له حزيمي\nسألتمس العلى إما بعرب … يروون اللهاذم أو بروم\nولو أني أعنت بآل عكل … رغبت عن الذوائب من تميم\nحذاركم بني الضحاك إني … إلى الأمر الذي تومون أومي\nفلا تتعرضوا بذراع عاد … مدل عند خيسته شتيم\nفإن تك مدحة سبقت فإني … بضد نظامها عين الزعيم\nوقافية تخضخض ما ترامت … به الأيام في عرض اللئيم\nتردد ما لها ممن يعيها … سوى الإطراق منها والوجوم\nلها في الرأس سورات يطاطي … لها الإنسان كالرجل الأميم\nليعلم من أناضل أن شعري … يطالع بالشقاء وبالنعيم"},{"id":"diwan-radi:582","bookId":"diwan-radi","type":"poem","seq":582,"chapter":"البحر: طويل","title":"رأت شعرات في عذاري طلقة","page":"","text":"رأت شعرات في عذاري طلقة … كما افتر طفل الروض عن أول الوسم\nفقلت لها : ما الشعر سال بعارضي … ولكنه نبت السيادة والحلم\nيزيد به وجهي ضياء وبهجة … وما تنقص الظلماء من بهجة النجم"},{"id":"diwan-radi:583","bookId":"diwan-radi","type":"poem","seq":583,"chapter":"البحر: بسيط تام","title":"هل كان يومك إلا بعد أيام","page":"","text":"هل كان يومك إلا بعد أيام … سبقت فيها بإنعام وإرغام\nوهل أزالك عن هذا سوى قدر … تناول الأسد من غيل وآجام\nإن المنايا مغرات لأنفسنا … وإن أمدت بأعوام وأعوام\nنسعى بأقدامنا عنها فتدركنا … سبق الجياد وما تسعى باقدام\nمالي بطي الليالي غير مكترث … وما ورائي منها كان قدامي\nأظن شخص الردى فردا فأحذره … والموت أكبر من ظني وأوهامي\nإن الحياة ، وإن غرت مخائلها … ظل وإن المنى أضغاث أحلام\nتامي البقاء إلى الذاوي تراجعه … كلا ولا يرجع الذاوي إلى النامي\nأبا الفوارس ما أعلى يدا عصفت … من المنون بأعلى عزك السامي\nإن المنية ما زالت مفوقة … حتى رمتك ، ولا عدوى على الرامي\nكرت ، فلم تثنها بالسمر مشرعة … ولم ترعها بإسراج وإلجام\nإلا اتقيت بما سومت من عدد … وما تعلمت من نقض وإبرام\nهيهات ألقى حمام كل مارنة … تدمى وأبطل موت كل إقدام\nتملي المقادير أعمارا ، وتنسخها … ويضرب الدهر أياما بأيام\nفمن كمين ردى تسري عقاربه … ومن طلوع برايات وأعلام\nأين السرير وقد قام السماط له … إجلال أروع عالي القد بسام\nأين الجياد تنزى في أعنتها … يطلبن يوما قطوبا وجهه دام\nأين الفيول كأن الممتطين لها … على ذوائب أطواد وأعلام\nأين الوفود على الأبواب مذكرة … بالفرط من مجد أخوال وأعمام\nأين المراتب والدنيا على قدم … موقوفة بين أرماح وأقلام\nمضى ولم يغن ما عددت عنه ، ولا … كسب العلى واجتناب اللوم والذام\nوعاد أعظم من في جيشه جرة … وليس يملك إلا عض إبهام\nوكان أقطع من صمصامة ظبة … فينا وأمضى مضاء منه في الهام\nلم يجر يوما بأطراف العراق دما … إلا وراع دماء القوم بالشام\nوكان أن حاف عدم ثم عذت به … ملأت أرضك من خيل وأنعام\nيحنو على رحم مجفوة ويرى … قطع الرقاب ولا قطعا لأرحام\nتبكي الركاب وقد ردت أزمتها … فالركب ما بين أعوال وأرزام\nاليوم يرتاح من كانت أضالعه … على قوادم أحقاد وأوغام\nيموت قوم ، فلا يأسى لهم أحد … وواحد موته حزن لأقوام\nسقى الحيا منك أوصالا مفرقة … فيها مجامع إجلال وإعظام\nغيثان : ذا جامد تخفى مخائله … عن العيون وذا بادي الذرى هامي\nلله درك من غراء أحرزها … موسومة قلب ضرغام لضرغام\nقد كدت أعقلها لولا محافظة … على يد سلفت منه وإنعام\nأعاد عز أبي غضا وخوله … ما شاء من بذل إعزاز وإكرام\nوكنت أجممته للعز أطلبه … وإنما كان للمقدور إجمامي\nودون ما تشتهيه النفس متعبة … إن اللألي وارء الأخضر الطامي\nفاذهب كما ذهب البدر استبد به … برغم أعيننا جلباب إظلام\nفما لدارك منا غير مقلية … ولا لقربك منا غير إلمام"},{"id":"diwan-radi:584","bookId":"diwan-radi","type":"poem","seq":584,"chapter":"البحر: وافر تام","title":"متى أنا قائم أعلى مقام","page":"","text":"متى أنا قائم أعلى مقام … ولاق نور وجهك بالسلام\nومنصرف وقد أثقلت عطفي … من النعماء والمنن الجسام\nولي أمل أطلت الصبر فيه … لو أن الصبر ينقع من أوامي\nوما خفت النوائب ترتمي بي … وقد أقعى بجامحها لجامي\nأيعرقني الطوى والروض حال … ويغلبني الظما و\nولي قربى رؤوم كنت أرجو … يمينك أن تقرب لي مرامي\nوباب الإذن مني كل يوم … يقعقع بالقوافي والنظام\nلكم أرجاء زمزم والمصلى … وبطحاء المشاعر والمقام\nوأنتم أطول العظماء طولا … وأندى في المحول من الغمام\nوأبعد موطنا من كل عار … وأمنع جانبا من كل ذام\nوأجرى عند مختلف العوالي … وأفلج عند معترك الخصام\nبآباء مضوا ، وهم عوار … من القول المهجن والملام\nوأمات درجن على الليالي … وهن أصح من بيض النعام\nوعز لا يزعزع بالرزايا … وطود لا يضعضع بالزحام\nوفخر شامخ العرنين عال … ومجد طائر العزبات سام\nتسيل إليهم أيدي المطايا … بكل أشم معروق العظام\nيغلبن البعاد على التداني … ويؤثرن المسير على المقام\nويعلفن الذميل ولا سبيل … إلى الغدران والنطف الطوامي\nوينصل ليلها عن كل عنس … غضيض الطرف فاترة البغام\nأحفت من جوانبها الفيافي … وساقط نحضها خوض الظلام\nتناخ بمالئ الدنيا نوالا … وصادع بيضة الملك الهمام\nببأس مثل غرب السيف ماض … وجود مثل ماء المزن هام\nوصولات أمر من المنايا … على بشر ألذ من المدام\nأمير المؤمنين ، وأنت أولى … بغايات الفخار من الأنام\nوأنت مملك شرقا وغربا … حريم الأرض والبلد الحرام\nأجب صوتي إليك فكل ملك … يلذ على مسامعه كلامي\nوجردني تلاق الدهر مني … بمسموم مضاربه حسام\nولا تتغاضين عن القوافي … فقد أربت على طول الجمام\nوإني نعم دامغ كل قرن … يرادي بالعداوة ، أو يرامي\nودافع كل داهية نآد … وقائد كل ذي لجب لهام\nلعلي بالغ أمري ولاق … منى نفسي من النعم العظام\nوأمرا منك يحذره الأعادي … فيلحظه بأجفان دوام\nفأعينهم لبغضته غواض … وهن لعظم منظره سوام\nتهن قدوم صومك ، يا إماما … يصوم على الزمان من الأثام\nإذا ما المرء صام من الدنايا … فكل شهوره شهر الصيام\nألان جذبت من أيدي الليالي … عناني واشتملت على زمامي\nفما أخشى الزمان ولو تلاقت … يداه من ورائي أو أمامي\nولا سيما وقد أمسى علي … ظهيري والسفير إلى إمامي"},{"id":"diwan-radi:585","bookId":"diwan-radi","type":"poem","seq":585,"chapter":"البحر: طويل","title":"حلفت بها صيد الرؤوس سوام","page":"","text":"حلفت بها صيد الرؤوس سوام … طوال الذرى يمددن كل زمام\nبكل غلام حرم النوم هزة … إلى بلد نائي المزار حرام\nلأستمطرن العزنفا مريغة … ورود علاء أو ورود حمام\nوأستنزلن المجد من قذفاته … ولو كان أعلى يذبل وشمام\nمللت مقامي غير شكوى خصاصة … وإني لأمر ما أمل مقامي\nنزاعا عن الدار التي أنا عندها … كثير لبانات طويل غرام\nصريع هموم يحسب الناس أنني … لما أخذت مني صريع مدام\nنوائب أيام نسرن خصائلي … مغالبة ، حتى عرقن عظامي\nودون ولوج الضيم في ذوابلي … طوال بأيدي منجبين كرام\nوإن زماني يوم يحرق نابه … أعاذمه حتى يمد عذامي\nوكم يستفز الذل قلب ابن همة … له أمل نائي المدى مترام\nيذاد عن الماء الذي فيه ريه … ويرمي إلى الغدران مقلة ظامي\nوتعرض غرات العلى وهو كانع … فيلحظها شزرا بعين قطامي\nولست براض عن منازل جمة … أمر بها في الأرض مر لمام\nسوى منزل حصباء أرضي بجوه … نجوم وأظلال الغمام خيامي\nفذاك مكاني إن أقمت بمنزل … وإلا ففي أيدي الطلاب زمامي\nخفيف على ظهر الجواد تسرعي … ثقيل على هام الرجال قيامي\nخليلي رودا باليفاع ، فأشرفا … على قلل بالأبرقين سوام\nلبرق كتلويح الرداء يشبه … تضايق مرنان الرعود ركام\nتربص إن يلقى بنجد بعاعه … وساق إلى البيضاء عير غمام\nزفته النعامى ، فاستمر جمامه … تجفل سربي ربرب ونعام\nيضيء إلى الربع الذي كنت آلفا … به برء أسقامي وبل أوامي\nمنازل كان الطرف يرتاح بينها … لخضر جميم أو لزرق جمام\nسقى تربها حتى استثار خبيئه … سقيط رذاذ دائم ورهام\nوراقت بها الأنواء كل صبيحة … ورقت بها الأرواح كل ظلام\nتضم رجالا كالرماح ، إذا دعوا … إلى الحرب لفوا نارها بضرام\nلهم عدد جم من البيض والقنا … وذافرة بالليل ذات بغام\nإذا غضبوا جاشت ربى الأرض منهم … ببيض وبيض كالنجوم ولام\nبأي سراة أحمل الخطب إن عرا … وقد جب منهم غاربي وسنامي\nوكانوا دروعي إن رمتني ملمة … ونبلي إن رامى العدا وسهامي\nولولا ابن موسى ما اعتصمت بجنة … ولا علقت كفي بعقد ذمام\nملاذي إن أعطي الرمان مقادتي … معاذي إن جر العدو خطامي\nمن القوم ما زروا الجيوب على الخنا … ولا قرعت أسماعهم بملام\nسريعون إن نودوا ليوم كريهة … جريئون إن قيدوا ليوم خصام\nلهم شرف آب على الناس اقعس … وفضل عديد للعدو لهام\nنجومهم في العز غير غوارب … وأجدادهم في المجد غير نيام\nيهاب بهم مستلئمين إلى الردى … على عارفات بالطعان دوام\nعناجيج قد طوحن كل حقيبة … من الركض واستهلكن كل لجام\nنزائع ما تنفك تفرى صدورها … جيوب ظلام ، أو ذيول قتام\nيخالطن بالفرسان كل طريدة … ويبلغن بالأرماح كل مرام\nأحاسد ذا الضرغام دونك فاجتنب … بوادر مقدام الجنان محامي\nحذارك من ليث ترى حول غيله … سواقط أيد للرجال ، وهام\nله العدوة الأولى التي تحطم القنا … وتجلي الأعادي كل يوم مقام\nهنيئا لك العيد الجديد ولا تزل … تخلص من عام يمر وعام\nتلثمت من فضل العفاف عن الهوى … نجاء من الدنيا أعز لثام\nوخالفت في ذا لصوم سنة معشر … صيام ، عن العوراء غير صيام\nألا إنني غرب الحسام الذي ترى … وغارب هذا الأرعن المتسامي\nكلانا له السبق المبر إلى العلى … وإن كان في نيل العلاء إمامي\nوما بيننا يوم الجزاء تفاوت … سوى انه خاض الطريق أمامي"},{"id":"diwan-radi:586","bookId":"diwan-radi","type":"poem","seq":586,"chapter":"البحر: كامل تام","title":"ما إن رأيت كمعشر صبروا","page":"","text":"ما إن رأيت كمعشر صبروا … لقوارع اللزبات والأزم\nبسطوا الوجوه وفي ضلوعهم … حرق الجوى ومآلم الكلم\nجمحت بهم خيل الأسى فتنوا … أعناقها بأعنة الحزم"},{"id":"diwan-radi:587","bookId":"diwan-radi","type":"poem","seq":587,"chapter":"البحر: رمل تام","title":"قعد الراضون بالذل فقم","page":"","text":"قعد الراضون بالذل فقم … إنما الماضي إذا هم عزم\nما مقامي غير ممضي نية … دائبا أهدر كالفحل السدم\nأعرض الآمال مشغوفا بها … ثم انساها إذا الخطب ألم\nطال لبثي سادرا في غمة … وقديما كنت فراج الغمم\nلا ألوم الهم إن لازمني … فهموم المرء يبعثن الهمم\nلست بالواني ولكني فتى … ظلمته نائبات فانظلم\nوزمان شرع أنيابه … أبدا ، يعرقنا عرق السلم\nالمعازيل كرام عنده … والمناجيب كملفوظ العجم\nخضع الدهر لنا ثم نبا … وكذا الدهر إذا ساف عذم\nأنا من أبنائه في معشر … يتواصون بإخفار الذمم\nإن طواني الغيب عن ألحاظهم … مزقوا عرضي تمزيق الأدم\nلا يلاقوني إلا خائضا … أخطم الأقوال منهم وأزم\nإن تراني مطرقا عن سورة … كقبوع الصل أغضي وأرم\nفهمومي ساعيات جهدها … ليس كل السعي يوما بالقدم\nقد يجيب العز من أقعده … عن طلاب العز خوف وعدم\nويجيب الطالب المثري وقد … يدرك الشأو أخو العجز الهرم\nأبقت الأيام مني صعدة … تذبن العاجم عنها إن عجم\nوإذا زعزعها الدهر سمت … لدنة تنمى على طول القدم\nلست للزهراء إن لم ترها … كوعول الهضب يعجمن اللجم\nتستجن البيد من فرسانها … بين بغداد إلى أرض الحرام\nبعجاج يملأ الأفق دجى … وطعان يخضب الأرض بدم\nشرعا تفتر عن أعناقها … قلل القور وغيطان الأكم\nكالردى أقدم والغيث همى … والدجا طبق والسيل هجم\nحاملات كل غضبان به … من لمام الغيظ مس ولمم\nكالصقور الغلب ألحاظهم … كالجذى يلمعن من خلف اللثم\nبددوا ما جمع البأس لهم … بأنابيب العوالي في الكرم\nلست بالعاذر جدي إن هوى … وجدودي في العلى أعلى الأمم\nوبناني خلقت أطرافها … عقبا للرمح ، طورا ، والقلم\nيرى مثلي إلا طالبا … ذروة المنبر أو قعر الرجم\nطامح الرأس على أعواده … أو على عالية الرمح الأصم\nخطة : إما علاء ، أو ردى … معجليأ أقرع السن الندم\nبن من الناس بعز وعلى … ستساويهم غدا بين الرمم\nهبني الرمح بكفي فارس … بطل أكرهه حتى انحطم\nهبني العضب ذليقا حده … ثلم البيض ضرابا وانثلم\nأتراني دون من رام العلى … في الليالي منذ عاد وإرم\nودني ضارع عن أمره … أخذ العرب بتيجان العجم\nكم أب لي جد في إحرازها … يحرق الناب عليها وابن عم\nطلبوها فهوى بعضهم … ورمى بعض إليها فغنم\nصبروا فيها على كل أذى … ولقوا من دونها كل ألم\nإن يكن ملك ، فمثلي ناله … أو يكن حتف ، فإني لم ألم\nإنما يهلك مني ماجد … يولغ السيف عراقيب النعم\nناقص الأموال في بذل الندى … زائد الخطو إلى ضرب القمم\nنحن قوم قسم الله لنا … بالرزايا ورضينا بالقسم\nإنما قصر من آجالنا … إننا نأنف من موت الهرم\nنصف عيش المرء حلم ، والذي … يعقل العاقل منه كالحلم"},{"id":"diwan-radi:588","bookId":"diwan-radi","type":"poem","seq":588,"chapter":"البحر: مجزوء الكامل","title":"تأبى الليالي أن تديما","page":"","text":"تأبى الليالي أن تديما … بؤسا لخلق أو نعيما\nونوائب الأيام يطرق … الورى بيضا وشيما\nوالدهر يوجف فيه معو … الطريق ومستقيما\nوالمرء بالإقبال يبلغ … وادعا خطرا جسيما\nوينال بغيته وما … أنضى الذميل ولا الرسيما\nوإذا انقضى إقباله … رجع الشفيع له خصيما\nبينا يسيغ شرابه … حتى يغص به وجوما\nوهو الزمان إذا نبا … سلب الذي أعطى قديما\nكالريح ترجع عاصفا … من بعد ما بدأت نسيما\nيستهكم العضب القطو … ع ويزلق الرمح القويما\nويعود بالرأس الطمو … ح العين مطراقا أميما\nكم ذابل قاد الجيا … د القب يعلكن الشكيما\nكعواسل الذؤبان يذرعن … الأماعز والخروما\nومجمر للجيش قد … نسيت ضوامره الجموما\nقلق على الأنماط ح … تى يدرك الثار المنيما\nلا يصدر الرايات حتى … \nعصف الحمام به وفرق … رق ذلك الجمع العميما\nورمى به غرض الردى … عريان قد خلع النعيما\nزال الوزير وكان لي … وزرا أجر به الخصوما\nفالآن أغدو للعدا … ونبالها غرضا رجيما\nسد العلى ، وأنار لا … فظ القضاء ولا ظلوما\nحتى ، إذا لم يبق إ … يلام وأن يليما\nطرح العناء على اللئا … م مجانبا ومضى كريما\nأفنى العدا ، وقضى المنى … وبنى العلى ، ونجا سليما\nالحامل العبء الذي … أعيا المصاعب والقروما\nسئموه ، فاحتمل المغا … رم لا ألف ولا سؤما\nأنقاهم جيبا إذا … عدوا وأملسهم أديما\nوجه كأن البدر شا … طره الضياء أو النجوما\nلو قابل الليل البهي … لمزق الليل البهيما\nيجلو الهموم ورب وجه … إن بدا جلب الهموما\nخلص النجي مشاورا … قلبا على النجوى كتوما\nومنبها عزما إذا … ما هز لم يوجد نؤما\n … عليه والخل الحميما\nحتى سما ، فحدا بها … بزلاء ناجية سعوما\nكان العظيم وغير بد … ع منه إن ركب العظيما\nخطط يجبن المشجع … أو يسفهن الحليما\nوالحر من حذر الهوا … ن يزايل الأمر الجسيما\nويليح من خوف الأذى … فرقا ، ويدرع الكلوما\nوالضيم أروح منه مط … الظبى بلغ الصميما\nبعثوا سواك لها فكا … ن مبلدا عنها مليما\nوالعاجز المأفون أقعد … ما يكون إذا أقيما\nفسقى بلادك حيث كن … المزن منبعقا هزيما\nفلقد سقى خدي ذك … دمع عيني السجوما\nورعتك عين الله مقلاق … لاق الركائب ، أو مقيما"},{"id":"diwan-radi:589","bookId":"diwan-radi","type":"poem","seq":589,"chapter":"البحر: طويل","title":"من الركب ما بين النقا والأناعم","page":"","text":"من الركب ما بين النقا والأناعم … نشاوى من الإدلاج ميل العمائم\nوجوه كتخطيط الدنانير لاحها … مع البيد أضباب الهموم اللوازم\nكأن القطاميات فوق رحالهم … سوى أنها تأبى دني المطاعم\nعلى مصغيات للأزمة ساقطت … من الني ما بين الذرى والمناسم\nذكرناكم ، والعيس تهوي رقابها … وأيماننا مبلولة بالقوائم\nفأضعفنا عن حمل أسيافنا الهوى … ونقض منا مبرمات العزائم\nإذا هزنا الشوق اضطربنا لهزه … على شعب الرحل اضطراب الأراقم\nوخفت قلوب من رجال كما هفت … نزائع طير غدوة بالقوادم\nفمن صبوات تستقيم لمائل … ومن أريحيات تهب بنائم\nوفي الجيرة الغادين كل ممنع … يشير إلينا عن بروق المباسم\nويجلو لنا لمع الغمام وبشره … وأين لنا منه بجود الغمائم\nصفحن إلينا عن خدود أسيلة … دنو العواطي من ظباء الصرائم\nورفعن أطراف السجوف فصرحت … عن الوجد أدواء القلوب الكواتم\nوكيف تراهن العيون ، وإنما … شغلن المأقي بالدموع السواجم\nيعاطين إعطاء الذلول طماعة … ويصددن صدات الجياد القوادم\nزودن منا كل قلب ومهجة … وزودننا للوجد عض الأباهم\nخليلي هل زال الأراك وقد عفت … مغارز أعناق اللوى والمخارم\nوكيف أعالي الرمل منذ تحدبت … عليها الزباني بالغمام الروائم\nأحب ثرى أرض أقام بجوها … حبيب إلى قلبي ، وإن لم يلائم\nوأستشرف الأعلام حتى تدلني … على طيبها مر الرياح الهواجم\nوما أنسم الأرواح إلا لأنها … تجوز على تلك الربى والمعالم\nبرغمي أنزلت الهوى عند مانع … ودمت على عهد امرىء غير دائم\nكأني أداري مهرة عربية … تحايد عني من مناط الشكائم\nوهذا ، وما ابيض السواد ، فكيف بي … إذا الشيب أمسى ليلة من عمائمي\nوكنت أرى أن الشباب وسيلة … لمثلى إلى بيض الخدود النواعم\nأنا ابن الألى إن ما دعوا يوم معرك … أمدوا أنابيب القنا بالمعاصم\nمن القوم تعلو في المجامع منهم … مناصب أعناق رزان الجماجم\nمليئون في يوم القضاء إذا انتدوا … بجدع القضايا من أنوف المظالم\nوإن منعوا النصف اقتضوه وأفضلوا … على النصف بالأيدي الطوال الغواشم\nإذا نزلوا بالماحل استنبتوا الربى … وكانوا نتاجا للبطون العقائم\nقروا في حياض المجد واستدرعوا القنا … إلى نيل أعناق الملوك القماقم\nيسيرون بالمسعاة لا السعي بالخطى … ويرقون بالعلياء لا بالسلالم\nوما منهم إلا امرؤ شب ناشئا … على نمطي بيضاء من آل هاشم\nفتى لم توركه الإماء لوم تكن … أعاريبه مدخولة بالأعاجم\nإذا هم أعطى نفسه كل منية … وقعقع أبواب الأمور العظائم\nوما اتخذوا إلا الرماح سرادقا … ولا استنوروا إلا بضوء اللهاذم\nوما فيهم من يقسم القوم أمره … ولا ضارع ينقاد طوع الخزائم\nولا واهن إن عضه الأمر هابه … وألقى مقاليد الذليل المسالم\nيبيت على خور الحشايا وغيره … على ظهر جماح من الليل عارم\nلنا عفوات الماء من كل منهل … موارد آساد العرين الضراغم\nأبى العزم إلا وثبة في ظهورها … إذا أثقلت أعناقها بالمغارم\nعوابس إن قلقن يوما لغاية … هتمن بنا روق الربى والمخارم\nوكيف أخاف الليل أنى ركبته … وبيني وبين الليل بيض الصوارم\nوجمع إذا هزوا اللواء تجاوبت … جوانبه من أزمل وزمازم\nله لغط من اصطكاك رماحه … تنق عواليها نقيق العلاجم\nوتحسبه مما تضايق واقفا … وما رد من غرب الجياد الصلادم\nبه كل هفاف القميص شمردل … تفرج عن وجه نقي المقادم\nبطعن كما انعط الأديم أرقه … تعاور أيدي الخارزات الخوازم\nوتعرف في عرنينه المجد ساهما … على عقب الإدلاج ، أو غير ساهم\nلويت إلى ود العشيرة جانبي … على عظم داء بيننا متفاقم\nونمت عن الأضغان حتى تلاحمت … جوائف هاتيك الندوب القدائم\nوقلمت أظفاري ، وكنت أعدها … لتمزيق قربى بيننا والمحارم\nوروحت حلمي بعدما غربت به … ذنوب بني عمي غروب السوائم\nوأوطأت أقوال الوشاة أخامصي … وقد كان سمعي مدرجا للنمائم\nوسالمت لما طالت الحرب بيننا … إذا لم تظفرك الحروب فسالم\nوقد كنت أصميهم بعور نوافذ … تئن لها الأعراض يوم الخصائم\nصوائب من نبل العداوة لم تزل … تعط قلوبا من وراء الحيازم\nسيرضون مني عن إياد كوامل … ومن قبل ما نيلوا بأيد كوالم\nقضيت بهم حق الحفائظ مدة … ولا بد أن أقضي حقوق المكارم\nفإن عاودوا رجمي بغيب فإنها … جنادل عندي ملء كف المراجم\nوكم عجموني ، فانسللت مهذبا … أثر عودي في النيوب العواجم\nوبي يستسيغ الريق قوم وإنني … إذا شئت ، من قوم شجا في الحلاقم\nإذا لم يكن إلا الحمام فإنني … سأكرم سمعي عن مقال اللوائم\nوألبسها حمراء تضفو ذيولها … من الدم بعدا عن لباس الملاوم\nفمن قبل ما اختار ابن الأشعث عيشه … على شرف باق رفيع الدعائم\nفطار ذميما قد تقلد عارها … بشر جناح يوم دير الجماجم\nوجاءهم يجري البريد برأسه … ولم يغن إيغال به في الهزائم\nوقد حاص من خوف الردى كل حيصة … فلم ينج والأقدار ضربة لازم\nوهذا يزيد بن المهلب نافرت … به الذل أعراق الجدود الأكارم\nوقال ، وقد عن الفرار أو الردى … لحى الله أخزى ذكرة في المواسم\nوما غمرات الموت إلا انغماسة … ولا ذي المنايا غير تهويم نائم\nرأى أن هذا السيف أهون محملا … من العار يبقى وسمه في المخاطم\nوما قلد البيض المباتير عنقه … سوى الخوف من تقليدها بالأداهم\nفعاف الدنايا وامتطى الموت شامخا … بمارن عز لا يذل لخاطم\nوقد حلقت خوف الهوان بمصعب … قوادم أباء كريم المقاوم\nعلى حين أعطوه الأمان ، فعافه … وخير فاختار الردى غير نادم\nوفي خدره غراء من آل طلحة … علاقة قلب للنديم المخالم\nتحسب أيام الحياة ، وإنها … لأعذب من طعم الخلود لطاعم\nففارقها والملك لما رآهما … يجران إذلال النفوس الكرائم\nولما ألاح الحوفزان من الردى … حداه المخازي رمح قيس ابن عاصم\nوغادرها شنعاء إن ذكرت له … من العار طاطا رأس خزيان واجم\nلذاك مني بعد الفرار أمية … بشقشقة لوثاء من آل دارم\nوسل لها سل الحسام ابن معمر … فكر على أعقاب ناب بصارم\nتورد ذكري كل نجد وغائر … والجم خوفي كل باغ وظالم\nوهدد بي الأعداء في المهد لم يحن … نهوضي ، ولم أقطع عقود تمائمي\nوعندي يوم لو يزيد ومسلم … بدا لهما لاستصغرا يوم واقم\nعلى العز مت لا ميتة مستكينة … تزيل عن الدنيا بشم المراغم\nوخاطر على الجلى خطار ابن حرة … وإن زاحم الأمر العظيم ، فزاحم"},{"id":"diwan-radi:590","bookId":"diwan-radi","type":"poem","seq":590,"chapter":"البحر: رجز تام","title":"تأمل أن تفرح في دار الحزن","page":"","text":"تأمل أن تفرح في دار الحزن … وتوطن المنزل في دار الظعن\nهيهات يأبى لك جوال الردى … لبث المقيمين وخوان الزمن\nلا تصحبن دهرك ، إلا خائفا … فراق ألف ونبوا عن وطن\nوكن إلى نبأة كل حادث … كالفرس الأروع صرار الأذن\nقام به الخوف ولم يرض بأن … قام على أربعة حتى صفن\nخف شرها آمن ما كنت لها … إن الضنين لمكان للظنن\nنحن مع الأيام في وقائع … من المقادير وغارات تشن\nإن رماح الدهر يلقين الفتى … بغير عرفان الدروع والجنن\nداخلة بين القرينين ، وإن … لزا على الدهر بإمرار القرن\nما استأخرت شداتها عن معشر … بعد قطين الله ، أو آل قطن\nولا نبت أطرافها عن حجر … من مضر ذات القوى ولا اليمن\nرمت بني ساسان عن مربعهم … رمي المغالي أمن الطير الثكن\nواستلبت تاج بني محرق … بعد قياد الصعب من آل يزن\nوصدعت غمدان عن مرضومة … جوبك بالمقراض أثواب الردن\nوآل مروان غطاهم موجها … لما نزت بآل مراوان البطن\nثم بنو القرم العتيكي ، وقد … ردوا يزيد العار مخلوع الرسن\nلاقى خبيب ويزيد روقها … من غيبة ماطرها القنا اللدن\nأبوا إباء البزل فاقتادتهم … من المقادير مطاعات الشطن\nألا ذكرت ، إن طلبت أسوة … ما يضمن الأسوة للقلب الضمن\nيوم بني الصمة في عرض اللوى … ويوم بسطام بن قيس بالحسن\nويوم خو أسلمت عتيبة … خصاصة الدرع الذي كان أمن\nأوجره رمح ذؤاب طعنة … تلغط لغط الأعجمي لم يبن\nوبالكديد ملتقى ربيعة … تحمي بعيد الموت آبار الظعن\nكأنني لم تبك قبلي فارسا … عين ، ولا حن فتى قبلي وأن\nهل كان كل الناس إلا هكذا … ذو شجن باك لباك ذو شجن\nسائل بقومي لم نبا الدهر بهم … عن غير ضغن ورماهم عن شزن\nلم راشهم ريش السهام للعدا … ثم براهم بالردى بري السفن\nوكيف أمسوا حفنات من ثرى … من بعد ما كانوا رعانا وقنن\nسوم السفا طاحت به في مرها … زفازف الريح وبوغاء الدمن\nهم أجلسوا على الصفاح والذرى … إذ رضي القوم بما تحت الثفن\nلهم على الناس ، وما زال لهم … مشارف الرأس على جمع البدن\nعما عم لما تزل أسيافهم … عمائم الصيد وأقياد البدن\nبالقدم الأولى إلى شأو العلى … والأذرع الطولى إلى عقد المنن\nكيف أماني للمرامي بعدهم … من نوب الدهر ، وقد زال المجن\nالداخلين البيت باباه القنا … على الخناذيذ الطوال والحصن\nوالفالقين الصبح عن مغيرة … لها من النقع ظلام مرجحن\nوالضاربين الهام في مشعلة … لها بلا نار ضرام ودخن\nكم فاض في أبياتهم منتجع … يقرن بالنعمى وقرن في قرن\nإذا تنادوا للقاء فيلق … تداولوا الأعناق من أسر ومن\nما درنت أعراضهم من الخنا … ولا انجلت أسيافهم من الدرن\nكل عظيم منهم معجب … تأذن أبواب الغنى إذا أذن\nذو نسب تستخجل الشمس به … أصفى على السائغ من ماء المزن\nله القدور الضامنات للقرى … مبارك البزل الجرار بالعطن\nمن كل دهماء لها هماهم … تلقم البازل جمعا كالفدن\nإن العشار لا تقي من سيفه … دماءها عام الجدوب باللبن\nأما ترى هذا الصفيح المجتلى … يدرجنا درج الرميل الممتهن\nكأنما الناس به من ذاهب … وواهب يجري على ذاك السنن\nمزبورة تطوى على أشطارها … يبطن باديها ويبدو ما بطن\nما أعجب الناس الذي نسكنه … يجمع ما بين الوهاد والقنن\nبين عظامي ملك وسوقة … لم يدر ما العز ونام ويفن\nلو علم الناظر يوما ما هما … أفظعه الخطب ، وقال : من ومن\nأقسمت لا أنساهم ما طلعت … حمراء من خدر ظلام ودجن\nأما بكاء بالدموع ما جرت … أو بالفؤاد إن أبى الدمع وضن\nأنكرت أفراح الزمان بعدهم … من طول بلواي بروعات الحزن\nزدن الرزايا فنقصن دفعة … ووطن القلب عليها ، فاطمأن\nقل للزمان : ارحل بهم من بازل … واحمل على غاربه فقد مرن"},{"id":"diwan-radi:591","bookId":"diwan-radi","type":"poem","seq":591,"chapter":"البحر: متقارب تام","title":"نعوه على ضن قلبي به","page":"","text":"نعوه على ضن قلبي به … فلله ماذا نعى الناعيان\nرضيع ولاء له شعبة … من القلب فوق رضيع اللبان\nبكيتك للشرد السائرا … ت تعبق ألفاظها بالمعاني\nمواسم تعلط منها الجباه … بأشهر من مطلع الزبرقان\nجوائف تبقى أخاديدها … عماقا وتعفو ندوب الطعان\nتبض إلى اليوم آثارها … بأحمر من عاند الطعن قاني\nقعاقعهن تشن الحتوف … إذا هن أوعدن لا بالشنان\nوما كنت أحسب أن المنون … تفل مضارب ذاك اللسان\nلسان هو الأزرق القعضبي … تمضمض من ريقة الأفعوان\nله شفتا مبرد الهالكي … أنجى بجانبه غير واني\nإذا لز بالعرض مبراته … تصدع صدع الرداء اليماني\nيرى الموت أن قد طوى مضغة … ولم يطو إلا غراري سنان\nفأين تسرعه للنضال … وهباته للطوال اللدان\nيشل الجوائح شل السياط … ويلوي الجوانح لي العنان\nفإن شاء كان حران الجماح … وإن شاء كان جماح الحران\nيهاب الشجاع غذاميره … على البعد منه مهاب الجبان\nوتعنو الملوك له خيفة … إذا راع قبل اللظى بالدخان\nوكم صاحب كمناط الفؤاد … عناني من يومه ما عناني\nقد انتزعت من يدي المنون … ولم يغن ضمي عليه بناني\nفزل كزيال الشباب الرطي … ب خانك يوم لقاء الغواني\nليبك الزمان طويلا عليك … فقد كنت خفة روح الزمان"},{"id":"diwan-radi:592","bookId":"diwan-radi","type":"poem","seq":592,"chapter":"البحر: رجز تام","title":"أقول والأقدار ترتمينا","page":"","text":"أقول والأقدار ترتمينا … والدهر لا يحفل ما لقينا\nما بال قلبي يطلب الحنينا … وجد القرين افتقد القرينا\nوما لدمعي يقرب الشؤونا … قد كاد أن يطلع الجفونا\nمن خبر لا جاءنا يقينا … بأن عين الكرم اليمينا\nتقذى وقد أقرت العيونا … قلوبنا أسمعننا الأنينا\nوقمن يا آمالنا ، فابكينا … هيهات يلقى من زمان لينا\nلا نهضت عن مثله السنونا … أعيا العقيم أن ترى البنينا\nيا من لنا اليوم نلاقي الهونا … يؤمنا بعدك أو يأبونا\nأم من على أيامنا يعدينا … ويعكس السهم إلى رامينا\nأم من يعيد النعم العزينا … جوافلا تشجر بالقنينا\nشجر المداري القطط الدهينا … الله يا ريب الزمان فينا\nابق على الدنيا وحاب الدينا … ما لك لا تنظرنا الديونا\nتأتخذ منا كل ما تعطينا … لا غضت ذاك الثغب المعينا\nيا ليته يوقى ، ولا وقينا … بين يديه نرد المنونا\nلا كان ما نحذر أن يكونا … "},{"id":"diwan-radi:593","bookId":"diwan-radi","type":"poem","seq":593,"chapter":"البحر: بسيط تام","title":"لواعج الشوق تخطيهم وتصميني","page":"","text":"لواعج الشوق تخطيهم وتصميني … واللوم في الحب ينهاهم ويغريني\nولو لقوا بعض ما ألقى نعمت بهم … لكنهم سلموا مما يعنيني\nوبالكثيب إلى الأجزاع نازلة … علقت منها بوعد غير مضمون\nما سوغوني برد الماء مذ حظروا … علي برد اللمى والشوق يظميني\nيا منشظ الشيح والحوذان من يمن … حييت فيك غزالا لا يحييني\nترى الغريم الذي طال اللزوم له … في الحي مول من بعدي فيقضيني\nإن الخلي ، غداة الجزع ، عيد به … إلى ضمير معنى اللب مفتون\nلولا ظباء معاطيل سنحن لنا … ما كان يذهل عن عقل وعن دين\nقد كاد ينجو بجد من عزيمته … فعارضته عيون الربرب العين\nماء النقيب ، ولو مقدار مضمضة … شفاء وجدي ، وغير الماء يشفيني\nونشقة من نسيم البان فاح بها … جنح من الليل تجري في العرانين\nأسقى دموعي إذا ما بات في سدف … صرير أثل بداريا يغنيني\nوصاحب وقذ التهويم هامته … ناديته ورواق الليل يؤويني\nفقام قد غرغرت في رأسه شده … يمضي على الكره أمري أو يلبيني\nلا غر قومك ، كم نوم على ضمد … سقما ولو بطرير الغرب مسنون\nوضاربات بلحييها على أضم … من اللغوب نحاف كالعراجين\nأبلى أزمتها بعد المدى ، وغدت … من الوجى بين معقول ومرسون\nمغرورقات المآقي كلما نظرت … برقا يضيء كفاف الغر والجون\nهيهات بابل من نجد لقد بعدت … على المطي ، مرامي ذلك البين\nسلني عن الوجد إني ، كل شارقة … يريشني الوجد ، والأيام تبريني\nمن لي ببلغة عيش غير فاضلة … تكفني عن قذى الدنيا وتكفيني\nأخي ، من باع دنياه وزخرفها … بصونه ، كان عندي غير مغبون\nقالوا : أتقنع بالدون الخسيس ، وما … قنعت بالدون بل قنعت بالدون\nإذا ظننا وقدرنا جرى قدر … بنازل غير موهوم ومظنون\nأعجب لمسكة نفس بعدما رميت … من النوائب بالأبكار والعون\nومن نجائي ، يوم الدار ، حين هوى … غيري ولم أخل من حزم ينجيني\nمرقت منها مروق النجم منكدرا … وقد تلاقت مصاريع الردى دوني\nوكنت أول طلاع ثنيتها … ومن ورائي شر غير مأمون\nمن بعد ما كان رب الملك مبتسما … إلي ادنوه في النجوى ويدنيني\nأمسيت أرحم من أصبحت أغبطه … لقد تقارب بين العز والهون\nومنظر كان بالسراء يضحكني … يا قرب ما عاد بالضراء يبكيني\nهيهات أغتر بالسلطان ثانية … قد ضل ولاج أبواب السلاطين\nما للحمام غدا ، فاعتام زافرتي … واختار ما كان يعطيني ويمطيني\nخلى علي مرارات الحيا ومضت … أحداثه بالمطاعيم المطاعين\nيشجعون علي الدهر إن جبنت … خطوبه ، وتوقى أن يناديني\nإذا رأوا مده نحوي يدا وضعوا … فيها عظام جلاميد لترميني\nأقارب لم يزل بي شر عرقهم … عرق من اللؤم يعديهم ويعدوني\nتملحوا بي كأني حمضة قطعت … لا بد بعد مدى أن يستمروني\nعزوا إلي نصابا بعد تشظية … وألصقوا بي أديما بعد تعييني\nهبوا أصولكم أصلي على مضض … ما تصنعون بأخلاق تنافيني\nأعطاكم السجل قبل النهر غرفته … فارضوا بروق جمامي واستجموني\nكم الهوان كأني بينكم جمل … في كل يوم قطيع الذل يحدوني\nلا تأمنن عدوا لان جانبه … خشونة الصل عقبى ذلك اللين\nواحذر شرارة من أطفأت جمرته … فالثار غض ، وإن بقي إلى حين\nأنى تهيب بي البقيا وأتبعها … فلم أباق بها من لا يباقيني\nتوقعوها ، فقد شبت بوارقها … بعارض كصريم الليل مدجون\nإذا غدا الأفق الغربي مختمرا … من الغبار فظنوا بي وظنوني\nلتنظرني مشيحا في أوائلها … يغيب بي النقع أحيانا ويبديني\nلا تعرفوني إلا بالطعان إذا … أضحى لثامي معصوبا بعرنيني\nأقدام غضبان كظته ضغائنه … فمال يخلط مضروبا بمطعون\nفإن أصب فمقادير محجزة … وإن أصب ، فعلى الطير الميامين"},{"id":"diwan-radi:594","bookId":"diwan-radi","type":"poem","seq":594,"chapter":"البحر: بسيط تام","title":"أسل بدمعك وادي الحي ، إن بانوا","page":"","text":"أسل بدمعك وادي الحي ، إن بانوا … إن الدموع على الأحزان أعوان\nلا عذر بعد تنائي الدار من سكن … لمدعي الوجد لم يدمع له شان\nحي الطوالع من نجد تصونهم … عن النواظر ، أنماط وكيران\nرموا جيوب المطالي عن ميامنهم … وشيحة الحزن يسراهم ونجران\nسارت بقلبك في الأحشاء زفرته … واستوقفتك بأعلى الرمل أظعان\nلما مررنا على تلك السروب ضحى … نضت إلى الربع أجياد وأعيان\nمن كل غيداء قد مال النعيم بها … كما تخايل بالبردين نشوان\nكأنما انفرجت عنهم قبابهم … يوم الأنيعم آجال وصيران\nمستشرفات يعرضن الخدود لنا … كما تشوف صوب المزن غزلان\nلا يذكر الرمل إلا حن مغترب … له بذي الرمل أوطار وأوطان\nتهفو إلى البان من قلبي نوازعه … وما بي البان بل من داره البان\nأسد سمعي إذا غنى الحمام به … ألا يبين سر الوجد إعلان\nورب دار أوليها مجانبة … وبي إلى الدار أطراب وأشجان\nإذا تلفت في أطلالها ابتدرت … للعين والقلب أمواه ونيران\nكلم بقلبي أداويه ويقرفه … طول ادكاري لمن لي منه نسيان\nلا للوائم إقصار بلائمة … عن العميد ولا للقلب سلوان\nعلى مواعيدهم خلف ، إذا وعدوا … وفي ديونهم مطل وليان\nهم عرضوا بووفاء العهد آونة … حتى إذا عذبوني بالمنى خانوا\nلا تخلدن إلى أرض تهون بها … بالدار دار ، وبالجيران جيران\nأقول للركب ، قد خوت ركابهم … من الكلال ومر الليل عجلان\nمدوا علابيها . واستعجلوا طلبا … إذا رضي بالهوينا معشر هانوا\nنرجو الخلود ، وباقينا على ظعن … والدار قاذفة بالزور مظعان\nإن قلص الدهر ما أضفاه من جدة … فصنعة الدهر إعطاء وحرمان\nكم من غلام ترى أطماره مزقا … والعرض أملس والأحساب غران\nإذا الفتى كان في أفعاله شوه … لم يغن إن قيل : إن الوجه حسان\nلا تطلب الغاية القصوى فتحرمها … فإن بعض طلاب الربح خسران\nوالعزم في غير وقت العزم معجزة … والازدياد بغير العقل نقصان\nواجعل يديك مجاز المال تحظ به … إن الإشحاء للوارث خزان\nسيرعب القوم مني سطو ذي لبد … له بعثر أعراس وولدان\nلا يطعم الطعم إلا من فريسته … إن يعدم القرن يوما فهو طيان\nماشى الرفاق يراعي أين مسقطهم … والسمع منتصب والقلب يقظان\nيستعجل الليلة القمراء أوبتها … إذا بنو الليل من طول السرى لانوا\nحتى إذا عرسوا في حيث تفرشهم … نمارق الرمل انقاء وكثبان\nدنا كما اعتس وطمرين لمظه … من فضلة الزاد ، بالبيداء ، ركبان\nثم استقرت به نفس مشيعة … لها من القدر المجلوب معوان\nفعاث ما عاث واستبلى عقيرته … يجرها مطعم للصيد جذلان\nقرن إذا طلب الأوتار عن عرض … لم تفد منه دماء القوم ألبان\nوغلمة أخذوا للروع أهبته … لف البطون على الأعواد خمصان\nطارت بأشباحهم جرد مسومة … كأنما خطفت بالقوم عقبان\nمن كل أعنق ملطوم بغرته … كأنه من تمام الخلق بنيان\nيمد للجرس مثل الآستين ، إذا … خان التوجس أبصار وآذان\nفاستمسكوا بنواصيها وقد سقطت … من غائر الجري ألباب وأرسان\nكأنما النخل تزفيه يمانية … فاهت به ثم أعقاب وعيران\nكعمت فاغرة الثغر المخوف بهم … يهفو بأيمانهم نبع ومران\nكأن غر المعالي في بيوتهم … بيض عقائل يحميهن غيران\nيا فاقد الله بين الحي من يمن … أنساهم الحلم أحقاد وأضغان\nإلى كم الرحم البلهاء شاكية … لها من النعي إعوال وإرنان\nحيرى يضلونها ما بيننا ولها … منا على عدواء الدار نشدان\nالنجر متفق والرأي مختلف … فالدار ووعاء الشر ملآن\nأنا نجرهم أعراضنا طمعا … في أن يعودوا إلى البقيا كما كانوا\nأنى يتاه بكم في كل مظلمة … وللرشاد أمارات وعنوان\nميلوا إلى السلم إن السلم واسعة … واستوضحوا الحق ، إن الحق عريان\nيا راكبا ذرعت ثوب الظلام به … هوجاء ، مائلة الضبعين مذعان\nأبلغ على النأي قومي إن حللت بهم … إني عميد بما يلقون أسوان\nيا قوم إن طويل الحلم مفسدة … وربما ضر إبقاء وإحسان\nمالي أرى حوضكم تعفو نصائبه … وذودكم ليلة الأوراد ظمآن\nمدفعين عن الأحواض من ضرع … ينضو بهامكم ظلم وعدوان\nلا يرهب المرء منكم عند حفظته … ولا يراقب يوما وهو غضبان\nإن الألى لا يعز الجار بينهم … ولا تهاب عواليهم لذلان\nكم اصطبار على ضيم ومنقصة … وكم على الذل إقرار وإذعان\nوفيكم الحامل الهمهام مسرحه … داج ومن حلق الماذي أبدان\nوالخيل مخطفة الأوساط ضامرة … كأنهن على الأطواد ذؤبان\nالله الله أن يبتز أمركم … راع ، رعيته المعزي والضان\nثوروا لها ، ولتهن فيها نفوسكم … إن المناقب للأرواح أثمان\nفمن إباء الأذى حلت جماجمها … على مناصلها عبس وذبيان\nوعن سيوف إباء الضيم حين سطوا … مضى بغصته الجعدي مروان\nفإن تنالوا فقد طالت رماحكم … وإن تنالوا فللأقران أقران"},{"id":"diwan-radi:595","bookId":"diwan-radi","type":"poem","seq":595,"chapter":"البحر: كامل تام","title":"ملك الملوك نداء ذي شجن","page":"","text":"ملك الملوك نداء ذي شجن … لو شئت لم يعتب على الزمن\nالخطب هين مع صفائك لي … وإذا كدرت علي لم يهن\nألقى زماني بالليان ويلقا … قاني الزمان بجانب خشن\nعدة على الأيام أطلبها … والدهر يفتلني ويمطلني\nما لي رأيت الدهر ينصبني … ولغير وجد ما يؤرقني\nوأبيت كالملسوع ، في كبدي … من شدة الإقلاق ، لا بدني\nإني أتاني عنك ، آونة … لذع يضيق بوقعه عطني\nوتنكر بدرت بوادره … من غير ذنب كان من لدني\nأهدى إلى قلبي لواذعه … وأطار عني واقع الوسن\nإني ، وما رفع الحجيج له … عند الجمار ، شعائر البدن\nوالبيت ذي الأستار يمسحه … النزاع من شام ومن يمن\nما زلت عن سنن الحفاظ ، وكم … زال المعادي لي عن السنن\nستر الذي أظهرت من كرم … وطوى الذي أبديت من حسن\nلم أوت من نصح ولا شفق … فالشر والأعداء في قرن\nإحباط أجري ، مع زكا عملي … طرف من الخسران والغبن\nإن كان لي ذنب فلا نظرت … عيني ولا سمعت إذا أذني\nأنسى بأي يد رددت يدي … لما نزعت إليك من وطني\nألبستني النعماء في قفلي … وأنلتني العلياء في ظعني\nومن العجائب أنت بالإحسان تب … تبنيني والإعراض تهدمني\nأنا عبد أنعمك التي نشطت … أملي وأنهض عزها منني\nوالحر ، إما شئت تملكه … بالمن يملك ليس بالثمن\nوغرستني بندى يديك ، فلا … تدع الزمان يعيث في غصني\nأيدرني عن رعي أنعمه … من كان قبل أجره رسني\nلا أتقي طعن الخطوب ، إذا … لاقيتها ، ورضاك من جنني\nلو رمت لي الجيد عنك لقد … عطفته أطواق من المنن\nلا تسمعن قول الوشاة ومن … غرس الأضالع لي على الإحن\nيتطلبون لي العيوب وير … موني بافراد من الظنن\nالنقص أخرهم على ظلع … من غايتي والفضل قدمني\nفالفرق ما بيني وبينهم … كالفرق بين العي واللسن\nإني أرى الأيام مومضة … لك عن بوارق عارض هتن\nفكأنني بعداك قد حبطوا … حبطا لما شبوا من الفتن\nوكأنني بالهام قد جعلت … منهم عمائم للقنا اللدن\nتبكي ديارهم كما بكيت … مطموسة الأطلال والدمن\nفاسلم بهاء الملك ما سلمت … عادية الأطواد والقنن\nالوجه طلق والبنان ند … والوعد نقد والعطاء هني\nسترى مخالصتي ، وتخبرني … طبعا على غير النفاق بني\nوإذا الزمان رمى بنائبة … ونأى الأقارب فالتفت ترني"},{"id":"diwan-radi:596","bookId":"diwan-radi","type":"poem","seq":596,"chapter":"البحر: هزج","title":"أما كنت مع الحي","page":"","text":"أما كنت مع الحي … صباحا ، حين ولينا\nوقد صاح بنا المجد : … إلى أين ، إلى أينا\nإلى أن أدرك العرق … فثبنا ، ثم لاقينا\nحمينا بالحفيظات … فقارعنا وحامينا\nفلا تسأل عن الكا … س التي فيها تساقينا\nتناكينا فلما غلب … الأمر تباكينا\nعن الحلم تحاجزنا … وبالضغن تلاقينا\nولولا أطة الأرحا … م أعذرنا وأبلينا\nإذا ناشدت القربى … تباقينا ، وأبقينا\nبني أعمامنا ! مهلا … سينأى بين دارينا\nويغدو رهج الروع … لحاما بين غارينا\nإذا ما ضرب النقع … على الحرب رواقينا\nعسى الأرحام تثنينا … إذا نحن تباغينا\nتبالوا لتلاقونا … فإنا قد تبالينا\nفلم يلق لنا العا … جم رعديدا ولا هينا\nلنا كل غلام هم … مه أن يرد الحينا\nيخال موفيا نذرا … به ، أو قاضيا دينا\nحديد السمع في حيث … تكون الأذن العينا\nغرار النوم يجلو عن … لحاظ الضرم الرينا\nإذا السير حذا أيدي … ركاب الدم والأينا\nاذات الطوق ! تجلو في … براق الطلى لينا\nقفي أخبرك عن صبري … إذا أوعدتني البينا\nسلي عن هيئة السيف … شجاع القوم لا القينا\nلنا السبق بأقدام … إلى المجد تساعينا\nتري زمجرة الآسا … د همسا بين غابينا\nإذا ساومنا الضيم … على الأعراض غالينا\nوإن نازعنا الحق … عنان المال ألقينا\nإذا ما روح الرعيا … ن ، أعطينا وأمطينا\nيظن المجتدى أنا … على الجود تواطينا\nملكنا مقطع الرزق … فأفقرنا ، وأغنينا\nوحزنا طاعة الدهر … فأغضبنا وأرضينا\nمتى لم يطع الجود … سخونا ، أو تساخينا\nسراعا فتفاقدنا … جميعا وتناعينا\nإذا ما ثوب الداعي … إلى الموت تداعينا\nوما ينفعنا يوما … إذا نحن تفادينا\nوما أعلمنا أنا … إلى الغاية أجرينا"},{"id":"diwan-radi:597","bookId":"diwan-radi","type":"poem","seq":597,"chapter":"البحر: خفيف تام","title":"ما أقل اعتبارنا بالزمان","page":"","text":"ما أقل اعتبارنا بالزمان … وأشد اغترارنا بالأماني\nوقفات على غرور وأقدا … م على مزلق من الحدثان\nفي حروب على الردى ، وكأ … نا اليوم في هدنة مع الأزمان\nوكفانا مذكرا بالمنايا … علمنا أننا من الحيوان\nكل يوم رزيئة في فلان … ووقوع من الردى بفلان\nكم تراني أضل نفسا والهو … فكأني وثقت بالوخدان\nقل لهذي الهوامل : استوثقي لل … سير واستنشزي عن الأعطان\nواستقيمي قد ضمك اللقم الن … هج وغنى وراءك الحاديان\nكم محيد عن الطريق وقد صر … ح خلج البرى وجذب العران\nننثني جازعين من عدوة الده … هر ونرتاع للمنايا الدواني\nجفلة السرب في الظلام وقد زع … زع روعا من عدوة الذؤبان\nثم ننسى جرح الحمام ، وإن كا … ن رغيبا ، يا قرب ذا النسيان\nكل يوم تزايل من خليط … بالردى أو تباعد من دان\nوسواء مضى بنا القدر الج … د عجولا أو ماطل العصران\nيا لقومي لهذه الصيلم الص … ماء عنت ، والنازل الأرونان\nهل مجير بذابل أو حسام … أو معين بساعد أو بنان\nمضرب من مضاربي فله الد … هر وغصن أبين من أغصاني\nنسب ضارب إلى هاشم الجو … د ، وفرع نام إلى عدنان\nحفرة أطبقت على واضح الأث … اب في المجد طيب الأردان\nخلق كالربيع روضه القطر … وصدر صاف من الأضغان\nوجنان ماض على روعة الخط … ب ونفس كثيرة النزوان\nلازم شرعة الوفاء يرى حف … ظ التصافي دينا من الأديان\nشيعوه بالدمع يجري كما … شيع غدوا بواكر الأظعان\nكل عين قريحة تتلقا … هبواد من دمعها ملآن\nقد مررنا على الديار خشوعا … ورأينا البنى ، فأين الباني\nوجهلنا الرسوم ثم عرفنا … فذكرنا الأوطار بالأوطان\nجمحت زفرة بغير لجام … وجرت دمعة بغير عنان\nفالتفاتا إلى القرون الخوالي … هل ترى اليوم غير قرن فاني ؟\nأين رب السدير والحيرة البي … ضاء ، أم أين صاحب الإيوان ؟\nوالسيوف الحداد من آل بدر … والقنا الصم من بني الديان\nطردتهم وقائع الدهر عن لع … لعلع طرد السفار عن نجران\nوالمواضي من آل جفنة أرسى … طنبا ملكهم على الجولان\nلم يكن غير قبسة الفرق العج … كرع الظماء في الغدران\nمن أباة اللعن الذين يحيو … بها في معاقد التيجان\nتتراءاهم الوفود بعيدا … ضاربين الصدور بالأذقان\nفي رياض من السماح حوال … وجبال من الحلوم رزان\nوهم الماء لذ للناهل الظم … بردا والنار للحيران\nكل مستيقظ الجنان إذا … لم ليل النوامة المبطان\nيغتدي في السباب غير شجاع … ويرى في النزال غير جبان\nما ثنت عنهم المنون يد شو … كاء أطرافها من المران\nعطف الدهر فرعهم ، فرآه … بعد بعد الذرى قريب المجاني\nوثنتهم بعد الجماح المنايا … في عنان التسليم والإذعان\nعطلت منهم المقاري وباخت … في حماهم مواقد النيران\nليس يبقى على الزمان جريء … في إباء ، وعاجز في هوان\nلا شبوب من الصوار ، ولا أع … ق يرعى منابت العلجمان\nلا ولا خاضب من الربد يختا … ل بريط أحم غير يمان\nيرتمي وجهة الرئال ، إذا آ … نس ولن الإظلام والإدجان\nنابلا في مطامح الجو هاتيك … وذا في مهابط الغيطان\nلو لوى عنك رائع الخطب ذب … أو رمت دونك الحمام يدان\nلوقتك الردى نفوس عزيزا … ت وأيد مليئة بالطعان\nورجال إذا دعوا غدوة الروع … ع ، وقد خف جانب الأقران\nشمروا يطلبون ناشئة الصو … ت ، خناذيذ كالقني اللدان\nلا أغب الربيع تربك من نو … ر هجان ومنظر أضحيان\nوحدا البرق كل يوم إليه … عجل القطر بالنسيم الواني\nفي جبال من الغمام كأن الليل … يرمي رعانها برعان\nهزجات من البروق كأن ال … البلق فيها مجرورة الأرسان\nبعد ما كن كالشفوف تراهن … ن خفيات نقية الألوان\nنشوء مزن كأن في الأفق منه … نفس القين في الحسام اليماني\nأو كماوية الصناع علاها … صدأ اللون بعد طول صيان\nلاحمت بينه الرياح فأوفى … كمجر الأنقاء والكثبان\nتمتريه هوجاء من قبل الغو … رين ، نزع الدلاء بالأشطان\nتحفز القطر كلما جلجل الرا … عد حفز الحنية المرنان\nكعياب الدروع أسمع ركض الخيل … خيل فيها خشاخش الأبدان\nلو تراخت تلك الرياح لأرسل … ت رياح الزفير والإرنان\nلو ونى ذلك الغمام لأطلق … مزاد الدموع من أجفاني\nفعليك السلام من خاشع النا … ظر مستسلم لريب الزمان\nينظر الدهر بعد يومك والنا … س بعين وحشية الإنسان\nويرى الأنس لست من حاضريه … وحشة ، والجميع كالوحدان\nمعطيا للعدا به الواهن الضا … رع بعد الأنصار والأعوان\nاذكرته أيام هذا التنائي … مامضى من أيام ذاك التداني\nأصدقائي أقاربي وأخلا … ئي قبيلي وأخوتي أخواني\nفامض لا غرني الزمان بعهد … في خليل ولا بعقد ضمان\nقد تخلى النفس الحبيبة بالرغ … بالرغم وقد يبعد القريب الداني\nصرف الطرف عنك لا عن تقال … وأقل اللقاء لا عن تواني"},{"id":"diwan-radi:598","bookId":"diwan-radi","type":"poem","seq":598,"chapter":"البحر: هزج","title":"غزال ماطل ديني","page":"","text":"غزال ماطل ديني … بأجزاع الغديرين\nرهوني عندها تغلق … ق بين الهجر والبين\nألا ، لا شللا يا را … مي القلب بنصلين\nطريرين وما مرا … على مطرقة القين\nألا يا نظرة أرسل … تها بين الغبيطين\nأسأت اليوم للقلب … وأحسنت إلى العين\nفعاد الطرف بالفوز … وولى القلب بالحين\nفيا لله ! كم تجر … ح يا قلبي من عيني\nومن لوم الرفيقين … ومن بين الخليطين\nصغا قلبي إلى الحلم … بلا قول العذولين\nوخلفت الصبا … خلفي منقاد القرينين\nوما جزت الثلاثين … بعام أو بعامين\nفقل لي اليوم ما عذر … ك يا شيب العذارين\nسلي بي جولة الخيل … وملتف العجاجين\nوخطار القنا ، والمو … ت مضروب الرواقين\nتري عزمي مثل السي … ف مشحوذ الغرارين\nأجلي النقع قد صار … لحاما بين غارين\nوأثني سنن الخيل … بهبهاب السرى لين\nبحيث تقطع القربى … على أيدي القريبين\nويشتق القنا الذا … ما بين الشقيقين\nترى فيه القريبين … من البغضا قرينين\nرمت عندي يد الدهر … بخطب ليس بالهين\nأرى الأيام تحدو … ني في شر الطريقين\nكما أوضع ، تحت المي … الميس موار الملاطين\nأزجي الحظ كاللاعب … زحافا على الأين\nكما زجيت الرجزاء … زحفا بعقالين\nوهذا الدهر يثنيني … بالليان عن ديني\nويغدو ماتحا للض … رع الواني بسجلين\nله نضح بروقيه … ولي نطح بروقين\nترى صرف المقادير … متى يصحو من الأين\nوهيهات لقد أغلق … دون الرزق بابين\nفلا تطلب دواء … الحظ قد أعيا الطبيين\nوإن عاتبت هذا الده … صار الذنب ذنبين\nوقد طل دم تطل … به عند الجديدين"},{"id":"diwan-radi:599","bookId":"diwan-radi","type":"poem","seq":599,"chapter":"البحر: رمل تام","title":"فخرت قحطان أن كان لها","page":"","text":"فخرت قحطان أن كان لها … ذو نواس وكلاع ورعين\nشرف الأذواء فيها قبلنا … كل رحب الباع هطال اليدين\nثم ساوتها فخارا مضر … بعلي الطاهر المنقبتين\nشيمتا عز ومجد أغنتا … عن أبي أحمد فينا والحسين\nهل ترى جدا كجدي وأبي … أي مجد وثناء بعد ذين ؟\nنسب كالنضر أمسى واسطا … كل أنف من بني النضر ، وعين\nنير الأقطار قد ضوأ ما … بين جدي الكريمين وبيني\nثابت في طينة المجد إذا … منصب أمسى زليق القدمين\nبمناط النجم يجري دونه … بارق الأفق وضوء القمرين\nزينت أفعالنا أحسابنا … زينة اللهذم أنبوب الرديني\nحسب ضاربة أعراقه … بقرارات منى والمأزمين\nشامخ الأعناق عادي الذرى … ناضر العرق نضار الطرفين\nوبمجد النفس فخري سابقا … فضلة الفخر بمجد الوالدين"},{"id":"diwan-radi:600","bookId":"diwan-radi","type":"poem","seq":600,"chapter":"البحر: كامل تام","title":"ما زلت أطرق المنازل بالنوى","page":"","text":"ما زلت أطرق المنازل بالنوى … حتى نزلت منازل النعمان\nبالحيرة البيضاء حيث تقابلت … شم العماد ، عريضة الأعطان\nشهدت بفضل الرافعين قبابها … وتبين بالبنيان فضل الباني\nما ينفع الماضين إن بقيت لهم … خطط معمرة بعمر فان\nورأيت عجماء الطلول من البلى … عن منطق عربية التبيان\nباق بها حظ العيون وإنما … لا حظ فيها اليوم للآذن\nوعرفت بين بيوت آل محرق … مأوى القرى ومواقد النيران\nومناط ما اعتقلوا من البيض الظبا … ومجر ما سحبوا من المران\nورأيت مرتبط السوابق للمها … ومعاقل الآساد للذؤبان\nالهاجمين على الملوك قبابهم … والضاربين معاقد التيجان\nوكأن يوم الإذن يبرز منهم … أسد الشرى وأساود الغيطان\nولقد رأيت بدير هند منزلا … ألما من الضراء والحدثان\nأغضى كمستمع الهوان تغيبت … أنصاره ، وخلا من الأعوان\nبالي المعالم أطرقت شرفاته … إطراق منجذب القرينة عان\nأو كالوقود رأوا سماط خليفة … فرموا على الأعناق بالأذقان\nوذكرت مسحبها الرياط بجوه … من قبل بيع زمانها بزمان\nوبما ترد على المغيرة دهيه … نزع النوار بطيئة الإذعان\nأمقاصر الغزلان غيرك البلى … حتى غدوت مرابض الغزلان\nوملاعب الأنس الجميع طوى الردى … منهم ، فصرت ملاعب الجنان\nمن كل دار تستظل رواقها … أدماء ، غانية عن الجيران\nولقد تكون محلة وقرارة … لأغر من ولد الملوك هجان\nيطأ الفرات فناءها بعبابه … ولها السلافة منه والروقان\nووقفت أسأل بعضها عن بعضها … وتجيبني عبر بغير لسان\nقدحت زفيري فاعتصرت مدامعي … لو لم يؤل جزعي إلى السلوان\nترقى الدموع ويرعوي جزع الفتى … وينام بعد تفرق الأقران\nمسكية النفحات تحسب تربها … برد الخليع معطر الأردان\nوكأنما نشر التجار لطيمة … جرت الرياح بها على العقيان\nماء كجيب الدرع تصقله الصبا … ونقا يدرجه النسيم الواني\nحلل الملوك رمى جذيمة بينها … والمنذرين ، تغاير الأزمان\nطردا ، كدأب الدهر في طرد الألى … والى الحفائظ في بني الديان\nنعق الزمان بجمعهم عن لعلع … وأقض منزلهم على نجران\nوكآل جفنة أزعجتهم نبوة … نقلت قبابهم عن الجولان\nوعلى المدائن جلجلت برعادها … عركا لكلكلها على الإيوان\nوإلى ابن ذي يزن غدت مرحولة … نفضت حويتها على غمدان\nقصفت قنا جدل الطعان وثورت … بعد الأمان بعامر الضحيان\nزفر الزمان عليهم ، فتفرقوا … وجلوا عن الأوطار والأوطان"},{"id":"diwan-radi:601","bookId":"diwan-radi","type":"poem","seq":601,"chapter":"البحر: كامل تام","title":"يا مسقط العلمين من رمل الحمى","page":"","text":"يا مسقط العلمين من رمل الحمى … لي عند ظبيتك النوار ديون\nشرت الفؤاد رخيصة أعلاقه … ومضى يعض بنانه المغبون\nهيهات يتبعني إلى سلوانه … قلب أصاب به الظباء العين\nسنحت لنا في المشرقات عشية … ومن السهام محاجر وعيون\nلا العف عف حين يملك لبه … تلك اللحاظ ولا الأمين أمين\nلو أن قومك نصلوا أرماحهم … بعيون سربك ما أبل طعين"},{"id":"diwan-radi:602","bookId":"diwan-radi","type":"poem","seq":602,"chapter":"البحر: وافر تام","title":"أذات الطوق لم أقرضك قلبي","page":"","text":"أذات الطوق لم أقرضك قلبي … على ضني به ليضيع ديني\nكفاك حلي جيدك أن تحلي … بأطواق النضار ، أو اللجين\nسكنت القلب حيث خلقت منه … فأنت من الحشى والناظرين\nأحبك أن لونك لون قلبي … وإن ألبست لونا غير لوني\nعديني وامطلي ، وعدي ، فحسبي … وصالا أن أراك وأن تريني\nولا تستهلكي بيديك قلبي … فإن القلب بينكم وبيني\nسمعت لها حوارا كان فيه … رجوع بلابلي ودنو حيني\nفيا لك منطقا لو كان هجرا … لسامعه تلقي باليدين\nكأن الظبية الأدماء حارت … إلي بناعم العذبات لين\nنظرتك نظرة لما التقينا … على وجلين من هجر وبين\nكأني قد نظرت سواد قلبي … بوجهك ظاهرا لسواد عيني"},{"id":"diwan-radi:603","bookId":"diwan-radi","type":"poem","seq":603,"chapter":"البحر: متقارب تام","title":"ذكرتك ذكرة لا ذاهل","page":"","text":"ذكرتك ذكرة لا ذاهل … ولا نازع قلبه والجنان\nأعاود منك عداد السليم … فيادين قلبي ماذا يدان\nعواطف من مقلقات الغرا … م يوم دموعي بها أرونان\nويأبى الجوى أن أسر الجوى … إذا ملئ القلب فاض اللسان\nوما خير عين خبا نورها … ويمنى يد جذ منها البنان\nفيا أثر الحب أنى بقيت … وقد بان ممن أحب العيان\nوقالوا : تسل بأترابها … فأين الشباب ، وأين الزمان ؟"},{"id":"diwan-radi:604","bookId":"diwan-radi","type":"poem","seq":604,"chapter":"البحر: بسيط تام","title":"يا روض ذي الأثل من شرقي كاظمة","page":"","text":"يا روض ذي الأثل من شرقي كاظمة … قد عاود القلب من ذكراك أديانا\nأمر بالركب مجتازا بذي سلم … لو ما شريتك بالأوطان أوطانا\nشغلت عيني دموعا والحشى حرقا … فكيف ألفت أمواها ونيرانا\nأشم منك نسيما لست أعرفه … أظن ظمياء جرت فيك أردانا\nأشبهت أظعان ذاك الحي من يمن … طيبا وحسنا وأغصانا وكثبانا\nلو أستطيع لما سافتك سائفة … ولا جناك فتى رندا ولا بانا\nألقاك والقلب صاف من رجيع هوى … وأنثني عنك بالأشواق نشوانا\nولا تداويت من قرح فرى كبدي … ولا سقاني راقي الحي سلوانا\nيقول صحبي ، وقد أعياهم طربي : … بعض الأسى إنما أحببت إنسانا\nأين الخيام التي كنا نلوذ بها … بالابرقين وأين الحي مذ بانا\nلا هجت لي قنصا من بعد بينهم … ولا ذعرت عن الأطلاء غزلانا\nأنسيتني الناس إذ أذكرتني بهم … يا مهديا لي تذكارا ونسيانا"},{"id":"diwan-radi:605","bookId":"diwan-radi","type":"poem","seq":605,"chapter":"البحر: بسيط تام","title":"يا طائر البان غريدا على فنن","page":"","text":"يا طائر البان غريدا على فنن … ما هاج نوحك لي يا طائر البان\nهل أنت مبلغ من هام الفؤاد به … إن الطيلق يؤدي حاجة العاني\nضمانة ما جناها ، غير مقلته … يوم الوداع فيا شوقي إلى الجاني\nمغفل عن همومي في بلهنية … أرعى النجوم ، وطرفاه قريران\nينأى ويدنو على خضراء مورقة … لعب النعامى بأوراق وأغصان\nكالقرط علق في ذفرى مبتلة … بين العقائل قرطاها قليقان\nهيهات ما أنت من وجدي ولا طربي … ولا لقلبك أشجاني وأحزاني\nولا نظرت إلى ماء على ظمأ … تبغي الورود وليس الورد بالداني\nولا فجعت وقد سارت ركائبهم … يوم الغميم بغزلان كغزلاني\nلو لا تذكر أيامي بذي سلم … وعند رامة أوطاري وأوطاني\nلما قدحت بنار الوجد في كبدي … ولا بللت بماء الدمع أجفاني"},{"id":"diwan-radi:606","bookId":"diwan-radi","type":"poem","seq":606,"chapter":"البحر: متقارب تام","title":"أذاع بذي العهد عرفانه","page":"","text":"أذاع بذي العهد عرفانه … وعاود للقلب أديانه\nوأضرب سمع عن العاذلات … لها شانها وله شانه\nوما طل قلبا بإبلاله … مطال الغريم وليانه\nأهاجك ذا الحي من وائل … تحمل للبين أظعانه\nنأى السرب عنك وعهدي به … تكنس في القلب غزلانه\nلئن أوحش الربع حلا له … لقد عمر القلب سكانه\nمررن غدوا بروض الصري … راق من النور ظهرانه\nفحن لإلمامهم أثله … ومال إلى قربهم بانه\nوما حملت مثل تلك البدو … ر بين الذوائب أغصانه\nولي ناظر بعد بين الخلي … ط مات من الدمع إنسانه\nرواء من الماء آماقه … ظماء من النوم أجفانه\nيروح بهم ساهرا طرفه … ويغدو لهم دامعا شانه\nيراخي الهوى ، فأريغ السلو … قليلا ، وتجذب أشطانه\nفأين من الداء إفراقه … وأين من القلب سلوانه\nفيا ظالما طيبا ظلمه … كثيرا على القلب أعوانه\nتبعت فؤادي إلى حبه … مطيعا ، وإن لج عصيانه\nيباع بسومك حب القلوب … وتغلق عندك أثمانه\nوشر الإساءة من مالك … أساء ، وما نيل إحسانه\nوقد كنت أشفق من ذا الصدو … د ، مذ أودع القلب خوانه\nويا ركبا لجلجت نضوه … ثنايا الغوير ، ونجرانه\nيروعه الصبح أسفاره … ويؤنسه الليل إدجانه\nإذا منزل آن تعريسه … طواه على الأين ظعانه\nتحمل ألوكة حامي الضلو … ع ، طال من البين إرنانه\nإلى الحي من يمن أنهم … ودائع قلبي وخلصانه\nلنالوا من القلب ما لم ينل … زعازع حي وشيحانه\nلأنتم أسنة يوم الطعان … إذا أسلم السرح فرسانه\nكأن الجياد ، تسامى بكم … قنان الشريف وعقبانه\nوهل زان تيجانه أسرة … جباههم الغر تيجانه\nوإن رباط بني مالك … تقاد إلى الموت أرسانه\nإذا الفيلق المجر أدلى له … إلى قلب الذمر مرانه\nيكون سواكم عقابيله … وأنتم إلى الطعن سرعانه\nوما كل أصل كريم العرو … ق تأبى على الغمز عيدانه\nلكم كل جمع كما أقبلت … تموج بالنحل غيرانه\nكأن أسنته في القنا … شرار ظبا البيض نيرانه\nهل الموت إلا إذا استجمعت … كعوب القني وإيمانه\nإذا دبر الطعن أوهمته … تنم إلى النجم خرصانه\nلقد ضل عهدكم باللوى … وطال بدمعي نشدانه\nأناقشكم ، ووراء النقا … ش أنف العلوق ورئمانه\nوأهجركم هجر مستعتب … وكم وامق طال هجرانه\nفأنأى وأقرب أوب الظليم … ينتظر الط عم رئلانه\nسيبعد عنكم على حسرة … طويل جوى القلب أسوانه\nتبدل بالمرء أحبابه … وتنبو على المرء أوطانه\nإذا منزل راب سكانه … من الأرض حرم أيطانه\nإذا كان صعبا تناسي الحنين … إليكم فهيهات نسيانه\nوشيبني والصبا وارق … علي ، وما انجاب ريعانه\nحميم تقلب أخلاقه … ومولى تلون ألوانه"},{"id":"diwan-radi:607","bookId":"diwan-radi","type":"poem","seq":607,"chapter":"البحر: كامل تام","title":"يا ظالمي ، والقلب ناصره","page":"","text":"يا ظالمي ، والقلب ناصره … يجني علي له كما يجني\nأجمعت هجري ، والفراق معا … أوما اشتفيت بواحد مني\nلم أنس موقفنا وقد طلعت … كالشمس تحت حواجب الدجن\nترنو إلي بعين مطفلة … رعت النوى ومساقط المزن\nسهم وجدت له على كبدي … ألما ، وآلم صرفه عني\nسمحت بكم نفسي على مضض … ولرب سامحة على ضن\nهيهات يعدل في قضيته … قمر يدل بدولة الحسن"},{"id":"diwan-radi:608","bookId":"diwan-radi","type":"poem","seq":608,"chapter":"البحر: مجزوء الرجز","title":"أعاد لي عيد الضنى","page":"","text":"أعاد لي عيد الضنى … جيراننا على منى\nمواقف تبدل ذا الشي … الشيب شطاطا بحنا\nيقول من عاين ها … تيك الطلى والأعينا\nهذا غزال قد عطا … وذاك ظبي قد رنا\nوالهفتا من واجد … على الشباب والغنى\nمن أجلها يرضى الغري … يب بالبوادي وطنا\nأنسى قنا مرانها … موارن ذات قنا\nيلقى بها فوارس … لا يحفلون الجبنا\nمجتمرات رحن عن … رمي الجمار موهنا\nتروح السرب عن ال … رد إذا الليل دنا\nكم كبد معقورة … للعاقرين البدنا\nبأعين تركنها … على القلوب أعينا\nوإنما جعلنها … لرد قول السنا\nيورق منهن الحصى … حتى يكاد يجتنى\nليهن من لم يفتتن … إنا لقينا الفتنا\nيخفي تباريح الهوى … وقد عنانا ما عنا\nكما النزوع عندكم … كذا النزاع عندنا\nيا صاحبي رحلي : قفا … فسائلا لي الدمنا\nبالغمر قد غيرها … صوب الغمام مدجنا\nوأمطرا دمعيكما … ذاك الكثيب الأيمنا\nالدار عندي سكن … إذا عدمت السكنا\nقالا : ومن أين رما … الشوق قلت من هنا\nوصاحب نبهته … بعد اللغوب والونى\nرمى الكرى في سمعه … فبعد لأي أذنا\nوقام كالمصعب ذي … روق يجر الرسنا\nفقلت من معاقدي … على الردى قال أنا\nاتق ما بي تتقى … ولو أنابيب القنا\nكل الظبى حدائد … وقل منها المقتنى\nوإنما الصون على … قدر المضاء والغنا\nوبارق أشيمه … كالطرف أغضى ورنا\nأو رمح محبوك القرا … بات شموعا أرنا\nأيقظت عنه صاحبا … ينجاب علوي السنا\nفقلت إيه نظرا … أما قضيت الوسنا\nأين تقول صوبه … فقال لي دون قنى\nذكرني الأحباب ، وال … والذكرى تهيج الحزنا\nأضامن أن لا يني … يشوق قلبا ضمنا\nمن بطن مر والسرى … تؤم عسفان بنا\nوبالعراق وطري … يا بعد ما لاح لنا\nأشتاقهم ومربخ … إلى زرود بيننا\nيا ويح لي من شجني … أما مللت الشجنا\nرحلني عن وطني … إني ذممت الوطنا\nما رابني من أبعدي … ما رابني من الدنى\nولو وجدت مرقعا … لبست ثوبي زمنا\nإني ومن يغلب با … لرقع أديما لخنا\nأقسمت بالمحجوج مرف … وع العماد والبنا\nمثل سنام العود قد … عالوا عليه الظعنا\nموضوعة صفاحه … وضع المطي الثفنا\nوالأسود الملموس قد … جابوا عليه الركنا\nيلقى عليه مضر … بعد الصفاء اليمنا\nتحكك الجرب على الأ … جذال من مض الهنا\nلأقبلن معشرا … تلك الطوال اللدنا\nتلمظ الأصلال لج … لجن إلينا الألسنا\nيطلبن وردي ظمأ … إما الردى ، أو المنى\nيصبح في أطرافها … للقوم فقر وغنى\nلقد أنى أن أحم … ضيم بها لقد أنى"},{"id":"diwan-radi:609","bookId":"diwan-radi","type":"poem","seq":609,"chapter":"البحر: طويل","title":"تضاجعني الحسناء والسيف دونها","page":"","text":"تضاجعني الحسناء والسيف دونها … ضجيعان لي والسيف أدناهما مني\nإذا دنت البيضاء مني لحاجة … أبى الأبيض الماضي فأبعدها عني\nوإن نام لي في الجفن انسان ناظر … تيقظ عني ناظر لي في الجفن\nأغرت فتاة الحي مما ألفته … أغلغله دون الشعار من الضن\nوقالت هبوه ليلة الخوف ضمه … فما عذره في ضمه ليلة الأمن"},{"id":"diwan-radi:610","bookId":"diwan-radi","type":"poem","seq":610,"chapter":"البحر: طويل","title":"وما كنت أدري الحب حتى تعرضت","page":"","text":"وما كنت أدري الحب حتى تعرضت … عيون ظباء بالمدينة عين\nفوالله ما أدري الغداة رميننا … عن النبع أم عن أعين وجفون\nبكل حشى منا رمية نابل … قوي على الأحشاء غير أمين\nفررت بطرفي من سهام لحاظها … وهل تتلقى أسهم بعيون\nوقالوا : انتجع رعي الهوى من بلاده … فهذا معاذ من جوى وحنين\nفيا بانتي بطن العقيق سقيتما … بماء الغوادي بعد ماء شؤون\nأحبكما ، والمستجن بطيبة … محبة ذخر بات عند ضنين\nجلون الحداق النجل وهي سقامنا … لكل لبان واضح ، وجبين\nيلجلجن قضبان البشام عشية … على ثغب من ريقهن معين\nترى بردا يعدي إلى القلب برده … فينقع من قبل المذاق بحين\nتماسكت لما خالط اللب لحظها … وقد جن منه القلب أي جنون\nوما كان إلا وقفة ثم لم تدع … دواعي النوى منهن غير ظنون\nنصصت المطايا أبتغي رشد مذهبي … فأقلعن عني ، والغواية دوني"},{"id":"diwan-radi:611","bookId":"diwan-radi","type":"poem","seq":611,"chapter":"البحر: بسيط تام","title":"وصاحب في أصيحاب أنخت به","page":"","text":"وصاحب في أصيحاب أنخت به … على زرود ، وموج الليل يغشانا\nثنى الذراع ، وألقى فضل لمته … على الكثيب خميص البطن طيانا\nناديته بعد ما مال الجنوب به … أبا نعامة أبردنا قم الآنا\nفقام ، والنوم طرح في محاجره … لا يرسل الطرف إلا عاد وسنانا\nمستأخر ، ومطايا الركب سائرة … أحموقة إن عقل المرء قد رانا\nيهوى الرقاد كأن الرمل أفرشه … نمارق ابنة منظور ابن زبانا"},{"id":"diwan-radi:612","bookId":"diwan-radi","type":"poem","seq":612,"chapter":"البحر: وافر تام","title":"وليس من الفراغ يثرن عني","page":"","text":"وليس من الفراغ يثرن عني … نفاثات يجيش بها الجنان\nولكن مهجة ملئت ففاضت … وضاق القلب ، واتسع اللسان"},{"id":"diwan-radi:613","bookId":"diwan-radi","type":"poem","seq":613,"chapter":"البحر: رمل تام","title":"يا رفيقي قفا نضويكما","page":"","text":"يا رفيقي قفا نضويكما … بين أعلام النقا والمنحنى\nوانشدا قلبي فقد ضيعته … باختياري بين جمع ومنى\nعارضا السرب فان كان فتى … بالعيون النجل يقضي ، فأنا\nإن من شاط على ألحاظها … ضعف من شاط على طول القنا\nتجرح الأعين فينا والطلى … قاتل الله الطلى والأعينا\nثم كانت ، بقباء ، وقفة … ضمنت للشوق قلبا ضمنا\nوحديث كان من لذته … أحد يصغي إلينا أذنا\nغادروني جسدا تظهره … لهم الشكوى ويخفيه الضنى\nحبذا منكم خيال طارق … مر بالحي ولم يلمم بنا\nباخل بخل الذي أرسله … سئل النيل وما جاد لنا\nسرحة أعجلها البين وما … لبس الظل ، ولا ذيق الجنى\nما رأت عيني مذ فارقتكم … يا نزول الحي شيئا حسنا"},{"id":"diwan-radi:614","bookId":"diwan-radi","type":"poem","seq":614,"chapter":"البحر: سريع","title":"ما أسرع الأيام في طينا","page":"","text":"ما أسرع الأيام في طينا … تمضي علينا ثم تمضي بنا\nفي كل يوم أمل قد نأى … مرامه عن أجل قد دنا\nأنذرنا الدهر وما نرعوي … كأنما الدهر سوانا عنى\nتعاشيا ، والموت في جده … ما أوضح الأمر وما أبينا\nوالناس كالأجمال قد قربت … تنتظر الحي ، لأن يظعنا\nتدنو إلى الشعب ومن خلفها … مغامر يطردها بالقنا\nإن الألى شادوا مبانيهم … تهدموا قبل انهدام البنا\nلا معدم يحميه إعدامه … ولا يقي نفس الغني الغنى\nكيف دفاع المرء أحداثها … فردا وأقران الليالي ثنى\nحط رجال ، وركبنا الذرى … وعقبة السير لمن بعدنا\nكم من حبيب هان من فقده … ما كنت أن أحسبه هينا\nأنفقت دمع العين من بعده … وقل دمع العين إن يخزنا\nكنت أوقيه فأسكنته … بعد الليان المنزل الأخشنا\nدفنته والحزن من بعده … يأبى على الأيام أن يدفنا\nيا أرض ! فاشدتك أن تحفظي … تلك الوجوه الغر والأعينا\nيا ذل ما عندك من أوجه … كن كراما أبدا عندنا\nوالحازم الرأي الذي يغتدي … مستقلعا ينذر مستوطنا\nلا يأمن الدهر على غرة … وعز ليث الغاب أن يؤمنا\nكأنما يجفل من غارة … ملتفتا يحذر أن يطعنا\nأخي جبرا لك من عثرة … لا بد للعاثر أن يوهنا\nإن التي آذتك من ثقلها … هلمها ، نحملها بيننا\nساقيتك الحلو فلا بدعة … إن أنا طاعمتك مر الجنى\nواصبر على ضرائها ، إنما … في قوة السالب عذر لنا\nجناية الدهر له عادة … فما لنا نعجب لما جنى\nمن كان حرمان المنى دأبه … فالفضل إن بلغ بعض المنى\nكم غارس أمل في غرسه … فأعجل المقدار أن يجتنى\nما الثلم في حدك نقصا له … قد يثلم العضب ، وقد يقتنى\nيأبى لك الحزن أصيل الحجا … ويقتضيك الرزء أن تحزنا\nوالأجر في الأولى وإن أقلقت … وربما نستقبح الأحسنا\nذا الخلق الأعلى فخذ نهجه … واترك إليه الخلق الأدونا\nأبا علي هل لأمثالها … غيرك إن خطب زمان عنى\nفانهض بها إنك من معشر … إن جشموا الأمر أبانوا الغنى\nواصبر على ضراتها إنما … نغالب القرن إذا أمكنا"},{"id":"diwan-radi:615","bookId":"diwan-radi","type":"poem","seq":615,"chapter":"البحر: كامل تام","title":"يا صاحبي تروحا بمطيتي","page":"","text":"يا صاحبي تروحا بمطيتي … إن الظباء بذي الإدراك سلبنني\nسيرا فقد وقف الطعين لما به … مستسلما ونجا الذي لم يطعن\nما سرني ، وقنا اللحاظ تنوشني … إني هناك قتيل غير الأعين"},{"id":"diwan-radi:616","bookId":"diwan-radi","type":"poem","seq":616,"chapter":"البحر: كامل تام","title":"قد قلت للرجل المقسم أمره","page":"","text":"قد قلت للرجل المقسم أمره … فوض إليه تنم قرير العين\nرد الأمور إلى العليم بغبها … وتلق ما يعطيكه بيدين\nالله أنظر لي من النفس التي … تغوى وأرأف بي من الأبوين"},{"id":"diwan-radi:617","bookId":"diwan-radi","type":"poem","seq":617,"chapter":"البحر: متقارب تام","title":"ضلالا لسائل هذي المغاني","page":"","text":"ضلالا لسائل هذي المغاني … وغيا لطالب تلك الغواني\nوما أربي بسؤال الطلو … ل إلا تذكر ماضي زماني\nخليلي إن جزتما ضارجا … فكرا المطي ، وردا المثاني\nوعوجا علي أحي الديار … فإن الديار لمن تعلمان\nسقاك ولو بظما مهجتي … نجوم السماك ، أو المرزمان\nولا زال جوك في ناضر … من النور يحمده الرائدان\nليالي بين برود الشبا … ب مني غصن رطيب المجاني\nوقد رجل البيض من لمثي … بطفل الأنامل بض البنان\nأفالآن لما أضاء المشيب … وأمسى الصبا ثانيا من عناني\nوقد صقل السيف بعد الصدا … وبان لظى النار بعد الدخان\nيرد الزمان علي الهوى … ويطمع في هفوة من جناني\nفقل لليالي : ألا فاقصري … كفاني ما عند قلبي كفاني\nفإن الموفق لي جنة … أرد بها كل رام رماني\nأغر هجان ، وما المكرمات … بطوعى لغير الأغر الهجان\nأيا عمدة الملك لا استهدمت … ذراه وأنت لها اليوم باني\nوكيف يني الملك عما تروم … وسعيك من دونه غيرواني\nشددت قواه إلى هضبة … أواخيها كل عضب يماني\nمآثر ثبت أطنابها … على النجم والقمر الأضحيان\nحدوت إلى فارس بالرماح … بكر الردى يوم حرب عوان\nوجردا تفالت أرسانها … ليوم النزال ويوم الرهان\nوأقبلتها كذئاب الغضى … تعاسل في الفيلق الأرجوان\nتلمظ ألسنة السمهر … ما بين آذانها للطعان\nبأيدي جريين لاكوا الحرو … ب وارتضعوها ارتضاع اللبان\nبحيث ترى العزام الشجاع … وتقنع بالذل أم الجبان\nعلى كل معط علي السيا … ط لا يسترد بغير العنان\nيكر إلى الطعن سامي اللبان … ويثنى عن الطعن دامي البنان\nسرى يعجز النجم عن طرقه … طويل إذا نام ليل الهدان\nوعزم يشاور حد الحسام … \nمواقف يذهل فيها الشجاع … فما الظن بالعاجز الهيبان\nنشرت العدا بددا بعدما … نظمت الممالك نظم الجمان\nوكم عصبة أوضعت في الضلال … تنقب عن يومها الأرونان\nجذبت عن الغي أرسانها … وقد شافهتها المنايا الدواني\nوأرسلتها بغرار الحسام … وخاطبتها بلسان السنان\nفأعطتك آبي أعناقها … تطيع المقاود بعد الحران\nتشكى مورنها في يديك … مس الخشاش وجذب العران\nفضائل ألفت أشتاتها … ولم تك موجودة بالعيان\nفما القلم اللدن في راحتيك … بأولى من الأسلات اللدان\nنهنك نعماء سربلتها … تقطع عنها العيون الرواني\nعلى لقب بينت صدقه … مناقبك الغر كل البيان\nوالقاب قوم إذا برتها … تباين ألفاظها والمعاني\nفلا ارتجع العز معطيكه … ولا زلت من عشرة في أمان\nولازم ثوبيك صبغ العلى … كما لزمت صبغة الزبرقان\nفما دمت فالملك واري الزنا … د ، صافي الموارد ، عالي المباني\nلقد نال من عزك الأبعدون … وقرب من شأنه غير شاني\nفرشني أكن لك سهم النضال … واغصب علي يدي من براني\nوحك لي برد العلى ضافيا … أحك لك أمثاله من لساني\nإذا كنت عوني فمن ذا الذي … يثبطني عن بلوغ الأماني\nوأنت الزمان ، وأنى يخي … من كان مستشفعا بالزمان"},{"id":"diwan-radi:618","bookId":"diwan-radi","type":"poem","seq":618,"chapter":"البحر: طويل","title":"زمان الهوى ما أنت لي بزمان","page":"","text":"زمان الهوى ما أنت لي بزمان … ولا لك من قلبي أعز مكان\nابعد القباب اللاء زلن عن الحمى … أراعي الهوى في أربع ومغان\nوسيري أمام الحي والليل حابس … على الظعن من جدل لنا ومثاني\nوملتبس بالركب بادرت خلفه … ألوح بالأردان وهو يراني\nوآخر هزتني إليه ارتياحة … ومن دونه ذو صفصف ورعان\nتحملت سهما أولا من فراقه … فلما رآني لا أخور رماني\nأقول له والدمع يأخذ ناظري … بأبيض من ماء الشؤون ، وقاني :\nأترضى عن الدنيا ومولاك ساخط … وتمضي طليقا وابن عمك عاني ؟\nوفي ذلك الوادي الذي أنبت الهوى … جنابان من نواره ، أرجان\nوماء تشيه الريح كل عشية … كما رقم البرد الصبيغ يماني\nمررت بغزلان على جنباته … فأطلقن دمعي واختبلن جناني\nوعاجلني يوم الرفيقين في الهوى … عشية مالي بالفراق يدان\nوكم غادر البين المفرق من فتى … يمسح قلبا دائم الخفقان\nومنتزع من بين جنبيه زفرة … تخلي دموع العين في الهملان\nوما الحب إلا فرقة بعد ألفة … وإلا حذار بعد طول أمان\nهو الشغل استولى على كل مهجة … وألقى ذراعيه بكل جنان\nسلوت الهوى والشوق الا ذؤابة … تراجع قلبي من نوى وتداني\nوصرت أرى أن الشجون علاقة … تليق بقلب العاجز المتواني\nفها أنا ذا لا أمتع العين بالكرى … وتأمل قود النوم بعد حران\nتقلص عن مس النعاس جفونها … كما قلصت للبارد الشفتان\nتجمجم للأطماع في كل ليلة … وتقلع عن قلبي بغير بيان\nغرضت من العلياء وهي تطول بي … كما غرض المقصوص بالطيران\nولو شئت جلى بي إلى غاية العلى … جوادي ولكني أرد عناني\nومولى دعا غيري إلى ما يريده … ولو أنني ممن يجيب دعاني\nوحاول أمرا يصعب الريق دونه … بناجد مزؤد الفؤاد جبان\nينازعني الشحناء أني لقيته … ولو أنني يوما حذرت رقاني\nوعوراء لم أنصت إليها ولم أرد … جوابا لها ، والقول ليس بوان\nولكنني أغضيت عنها كأنما … أقول بسمعي ، أو أعي بلساني\nأرى السرح أولى بي من الكور في الوغى … وما ناقتي إلا فداء حصاني\nولما تعاطينا النزال انبرى لنا … ملب على أعواده بلبان\nفسدد رمحا لم يكن بمثقف … وجرد عضبا لم يكن بيماني\nحذار بني العنقاء من متطاول … إلى الحرب لا يخشى جناية جان\nوداهية تصمي القلوب كأنما … تمطر عن قوس من الشريان\nفهذا وعيد سطوتي من ورائه … وعنوان ناري إن يبين دخاني\nفلا يحسب الأعداء كيدي غنيمة … ولا أنني في الشر غير معان\nفإني بحمد الله أقوى على الأذى … وأنمى على البغضاء والشنآن\nوابيض من عليا معد كأنما … تلاقى على عرنينه القمران\nإذا رمت طعنا بالقريض حميته … وإن رمت طعنا بالرماح حماني\nيجود ، إذا ضن الجبان ، بنفسه … ويمضي ، إذا ما زلت القدمان\nبصير بتصريف الأعنة إن سرى … ليوم نزال ، أو ليوم رهان\nترامى به الأيام ، وهو مصمم … كما يرتمي بالماتح الرجوان\nإذا ما احتبى يوم الخصام كأنما … يحدثنا عن يذبل وأبان\nأبا أحمد ! أنت الشجاع ، وإنما … تجر العوالي عرضة لطعان\nولما غوى الغاوون فيك وفرجت … ضلوع على الغل القديم حواني\nنجوت عن الغماء ، وهي قريبة … نجاء الثريا من يد الدبران\nوغيرك غض الذل من نجواته … وطامن للأيام شخص مهان\nوحال الأذى بين المراد وبينه … كما حيل بين العير والنزوان\nوكان كفحل البيت يطمح رأسه … فألقى على حكم الردى بجران\nوآخر راخى من قواك ببدعة … ستشرد في الدنيا بغير عنان\nفأشهد أن ما عرقت فيه هاشم … ولا عل يوما من لبان حصان\nإذا المرء لم يحفظ ذماما لقومه … فأحج به أن لا يفي بضمان\nونازعك العلياء من آل غالب … شعوب ، ومن أد ، ومن غطفان\nفوارس يلقون الردى بنفوسهم … سراعا ولا يدعون يال فلان\nولو شئت لما طالعتك رماحهم … وأطرافها عوج إليك دواني\nهرقت دماء ما لها ، الدهر ، طالب … كما هرقت خرقاء قعب لبان\nوحي بثثت الخيل بين بيوتهم … وكانوا على أمن من الحدثان\nأقمتهم من روعة عن شوائهم … يمشون بالأعراف كل بنان\nأأغضي على ضيم ، وعزك ناصري … وباعي طويل من وراء سناني ؟\nإذا فعداني الضيف في كل ليلة … وكبت بإعجاز البيوت جفاني\nوما ارتاع مطلوب يكون وراءه … بأغلب من آل النبي هجان\nلك الخير لا أرضى بغيرك حاكما … علي ، ولا أعطي القياد زماني\nوإن أطلب الضخم اللغاديد غايتي … فرب جماد عد في الحيوان"},{"id":"diwan-radi:619","bookId":"diwan-radi","type":"poem","seq":619,"chapter":"البحر: وافر تام","title":"أمن شوق تعانقني الأماني","page":"","text":"أمن شوق تعانقني الأماني … وعن ود يخادعني زماني\nوما أهوى مصافحة الغواني … إذا اشتغلت بناني بالعنان\nعدمت الدهر كيف يصون وجها … يعرض للضراب وللطعان\nوأسفع لثمته الشمس ندب … أبينا إن يلقب بالهجان\nوكم متضرم الوجنات حسنا … إذا جربته نابي الجنان\nتعرفني بأنفسها الليالي … وآنف أن أعرفها مكاني\nأنا ابن مفرج الغمرات سودا … تلاقى تحتها حلق البطان\nوجدي خابط البيداء حتى … تبدى الماء من ثغب الرعان\nقضى ، وجياده حول العوالي … ووفد ضيوفه حول الجفان\nتكفنه ظبى البيض المواضي … ويغسله دم السمر اللدان\nنشرت على الزمان وشاح عز … ترنح دونه المقل الرواني\nخفيري في الظلام أقب نهد … يساعدني على ذم الزمان\nجوادي ترعد الأبصار فيه … إذا هزأت برجليه اليدان\nكأني منه في جاري غدير … ألاعب من عناني غصن بان\nحيي الطرف إلا من مكر … يبين من خلائقه الحسان\nإذا استطلعته من سجف بيت … ظننت بأنه بعض الغواني\nسأطلع من ثنايا الدهر عزما … يسيل بهمة الحرب العوان\nولا أنسى المسير إلى المعالي … ولو نسيته أخفاف الحواني\nوألطاف السحاب لكل دار … صحبنا ربعها خضل المغاني\nوكنا لا يروعنا زمان … بما يعدي البعاد على التداني\nونأنف أن تشبهنا الليالي … بشمس أو سنا قمر هجان\nفها أنا والحبيب نود أنا … تدانينا ونحن الفرقدان\nوليل أدهم قلق النواصي … جعلت بياض غرته سناني\nوصبح تطلق الآجال فيه … وناظر شمسه في النقع عاني\nعقدت ذوائب الأبطال منه … بأطراف المثقفة الدواني\nوشعث فلهم طلب المعالي … وفلوا كل منجرد حصان\nأقول لهم ثقوا بالله فيها … ففضل يد المعين على المعان\nولا تتعرضوا بالعز ، إني … رأيت العز خوار العنان\nفما ركب العلى إلا علي … ومسح عطفها بعد الحران\nسعى والشمس ترقى في أناة … فجاز وسيرها في الجو وان\nرموا منك المدى ، والخيل شعث … بمصقول العوارض واللبان\nيد لم تخل من قصب العوالي … تزعزعهن ، أو قصب الرهان\nتركت لهم عيون الطعن تدمى … بمنخرط من التأمور قان\nوقد نصل الدجى عن صدر يوم … من الخرصان مخضوب البنان\nوأجساد تشاطرها المنايا … نفوسا في ضراب أو طعان\nهو الغمر الرداء لعزمتيه … بكل دفاع نائبة يدان\nوما نهض امرؤ بالحزم إلا … وصادف حلمه ملقى الجران\nيضم الخائف الظمآن منه … حمى يفتر من برد الأماني\nوتضحك ناره وضحا ، إذا ما … رغت نار القبائل بالدخان\nويوم مثل شدق الليث جهم … يفل عن الجدال ظبى اللسان\nسددت فروجه بالقول حتى … مددت مشيعا باع البنان\nوغيرك من تروعه المعالي … وتخدعه أغاني القيان\nإذا ذكر الصوارم والعوالي … تعوذ بالمثالث والمثاني\nوإن طلب الذحول تهضمته … وباع دم الفوارس باللبان\nأبا سعد دعاء لو تراخت … أوائله لعاقبها لساني\nظفرت بما اشتهيت من الليالي … وأعطيت المراد من الأماني\nلكفك فوزة القدح المعلى … ومنها صولة العضب اليماني\nولما خرق الإظلام جبنا … خلعت عليه ثوب المهرجان\nإذا طردت رماح اللهو فيه … أرقن على الكؤوس دم القنان\nوشرب قد نحرت لهم عقارا … كحاشية الرداء الأرجواني\nكأن الشمس مال بها غروب … فأهوت في حيازيم الدنان\nفصل بدم العقار دم الأعادي … وأصوات العوالي بالأغاني\nفيوم أنت غرته جواد … يبذ بشأوه طلق القران\nجعلت هديتي فيه نظاما … صقيلا مثل قادمة السنان\nبلفظ فاسق اللحظات تنمى … محاسنه إلى معنى حصان\nوصلت جواهر الألفاظ فيه … بأعراض المقاصد والمعاني\nفجاءت غضة الأطراف بكرا … تخير جيدها نظم الجمان\nكأن أبا عبادة شق فاها … وقبل ثغرها الحسن بن هاني"},{"id":"diwan-radi:620","bookId":"diwan-radi","type":"poem","seq":620,"chapter":"البحر: مجزوء الرمل","title":"اسقني فاليوم نشوان","page":"","text":"اسقني فاليوم نشوان … والربى صاد وريان\nكفلت باللهو وافية … لك نايات وعيدان\nحاز وفد الريح ، فالتطمت … منه أوراق وأغصان\nكل فرع مال جانبه … فكأن الأصل سكران\nوكأن الغصن مكتسيا … من رياض الطل عريان\nكلما قبلت زهرتها … خلت أن القطر غيران\nومقيل بين أخبية … قلته ، والحي قد بانوا\nفي أصيحاب مفارشهم … ثم انقاء وكثبان\nعسكرت فيها السحاب كما … حط بالبيداء ركبان\nفارتشفنا ريق سارية … حيث كل الأرض غدران\nفاسقني فالوصل يألفني … إن يوم البين قرحان\nقهوة ما زال يقلق من … مجتناها المسك والبان\nغير سمعي للملام ، إذا … ضج ساجي الصوت مرنان\nرب بدر بت ألثمه … صاحيا ، والبدر نشوان\nقدت خيل اللثم أصرفها … حيث ذاك الخد ميدان\nلي غدير من مقبله … ومن الصدغين بستان\nفي قميص الليل عبقة من … ظن أن الوصل كتمان\nكيف لا تبلى غلائله … وهو بدر ، وهي كتان\nوندامي كالنجوم سطوا … بالمنى والدهر جذلان\nكم تخلت من ضمائرهم … ثم ، ألباب وأذهان\nخطروا والخمر تنفضهم … وذيول القوم أردان\nكل عقل ضاع من يقظ … فهو في الكاسات حيران\nإنما ضلت عقولهم … حيث يعييهن وجدان\nفاختلس طعن الزمان بها … إنما الأيام أقران"},{"id":"diwan-radi:621","bookId":"diwan-radi","type":"poem","seq":621,"chapter":"البحر: وافر تام","title":"حبيبي هل شهود الحب إلا","page":"","text":"حبيبي هل شهود الحب إلا … اشتياق أو نزاع أو حنين\nلقد آوى محلك من فؤادي … مكان لو علمت به مكين\nإذا قدرت أني عنك سال … فذاك اليوم أعشق ما أكون\nفلا تخش القطيعة إن قلبي … عليك اليوم مأمون أمين"},{"id":"diwan-radi:622","bookId":"diwan-radi","type":"poem","seq":622,"chapter":"البحر: طويل","title":"جنى وتجنى والفؤاد يطيعه","page":"","text":"جنى وتجنى والفؤاد يطيعه … فيأمن أن يجنى عليه كما يجني\nإلى كم تسيء الظن بي متجرما … وأنسب سوء الظن منك إلى الضن\nووالله لا أحببت غيرك واحدا … ألية بر لا تخاف ، فنستثني\nفإن لم تكن عندي كسمعي وناظري … فلا نظرت عيني ، ولا سمعت أذني\nوإنك أحلى في جفوني من الكرى … وأعذب طعما في فؤادي من الأمن"},{"id":"diwan-radi:623","bookId":"diwan-radi","type":"poem","seq":623,"chapter":"البحر: كامل تام","title":"صبرا غريم الثار من عدنان","page":"","text":"صبرا غريم الثار من عدنان … حتى تقر البيض في الأجفان\nأوما اتقيت ، وقد كفيت فوارسا … يتجاذبون عوالي المران\nمن كل ميال العمامة ، كفه … يلوي الرداء على أغر هجان\nفي كل يوم أو بكل مقامة … يتذاكرون مقاتل الفرسان\nإذ لا يضيفون المعائب بينهم … وبيوتهم وقف على الضيفان\nالضامنين لطيرهم مهج العدا … عن كل ضرب صادق وطعان\nالراكبين الخيل تعرفها بهم … تحت العجاج إذا التقى الخيلان\nقوم إذا هطلت سحاب أكفهم … هطل الحيا ، فتعانق القطران\nوإذا حووا سبق القبائل خلقوا … غرر السوابق بالنجيع القاني\nوإذا رأيتهم على سرواتها … أبصرت عقبانا على عقبان\nأساد حرب لا ينهنهها الردى … تحت الظبا وأسنة المران\nيطأون خد الترب وهو مضرج … من طعنهم بدم القلوب الآني\nيا آل عدنان الذين تبوأوا … في المجد كل ممنع الآركان\nأيديكم أري العباد وشريها … ومفاتح الأرزاق والحرمان\nوإليك عط بي الظلام عذافر … متجلبب بالنص والذملان\nوإذا ترشفه السرى في جريه … لفظت يديه مكامن الغيطان\nوكأن نورا منك عاق لحاظه … فأتاك لا يرنو إلى الغدران\nكفاك في اللأواء ينقع فيهما … ظمأ المطامع ، أو صدا الخرصان\nفي ضمر يخرجن من حلل الدجى … كالغضف خارجة من الأرسان\nقدم السرور بقدمة لك بشرت … غرر العلى وعوالي التيجان\nفلقت ظبى الأسياف منك بعرجة … فيكاد ينهضها من الأجفان\nوأتى الزمان مهنئا يحدو به … غل المشوق وغلة اللهفان\nقد كان هذا الدهر يلحظ جانبي … عن طرف ليث ساغب ظمآن\nفالآن حين قدمت عدن صروفه … يرمقنني بنواظر الغزلان\nيا منتهي الآمال بل يا محتوي … الآجال بل يا أشجع الشجعان\nيا أفضل الفضلاء بل يا أعلم ال … العلماء بل يا أطعن الأقران\nيا قائد الجرد العتاق بهيبة … تغنيه عن لجم وعن أرسان\nيا ضارب الهامات ، وهي نوافر … تشكو تفرقها إلى الأبدان\nيا طاعنا بالرمح يرعف زجه … علقا ، بمجة عامل وسنان\nهذي القوافي واثقات أنها … من رحب جودك في أعز مكان\nتاهت إليك على القريض فردها … بنداك تائهة على الأزمان"},{"id":"diwan-radi:624","bookId":"diwan-radi","type":"poem","seq":624,"chapter":"البحر: بسيط تام","title":"ورب يوم صقيل الوجه تحسبه","page":"","text":"ورب يوم صقيل الوجه تحسبه … مرصعا بجباه الخرد العين\nأتاك يقتاد عيدا في حقائبه … زاد السرور على الطير الميامين\nفالبس جلابيبه البيض التي شرفت … واخرج عن الصوم من أثوابه الجون\nإليك يستن والأحشاء يتبعها … عن غرب فكر بغرب الشوق مقرون\nجاءت تهنيك بالود الذي علقت … منا الضمائر لا يوم الشعانين"},{"id":"diwan-radi:625","bookId":"diwan-radi","type":"poem","seq":625,"chapter":"البحر: بسيط تام","title":"الليل ينصل بين الحوض والعطن","page":"","text":"الليل ينصل بين الحوض والعطن … والبرق يسدي برود العارض الهتن\nوالجفن يفتر عن طرف صحبت به … إنسانه مثقل العطفين بالوسن\nفي ليلة أوعدت بالبين ، فاختلست … من العيون نقايا غبر الوسن\nحتى نظرت ، ولي عين مؤرقة … تقسم الدمع بين الربع والظعن"},{"id":"diwan-radi:626","bookId":"diwan-radi","type":"poem","seq":626,"chapter":"البحر: طويل","title":"قنا آل فهر لا قنا غطفان","page":"","text":"قنا آل فهر لا قنا غطفان … حمت أهلها من طارق الحدثان\nبني عامر ! ما لي وللدهر بعدما … يشتت بي عن صعدتي وحصاني\nوقد كنت لا أصغى إلى السلم ساعة … وأتبع داعي الحرب أين دعاني\nدعوا صهوات الخيل تدمى وفرقوا … رجالا عن البغضاء والشنان\nفكم صاحب تدمى علي بنانه … ويظهر أن العز لثم بناني\nيضم حشى البغضاء عند تغيبي … ويجلو جبين الود حين يراني\nمسحت بحلمي ضغنه عن جنانه … فلما أبى مسحته بسناني\nسبقت برميي قلبه ، فأصبته … ولو لم أصبه عاجلا لرماني"},{"id":"diwan-radi:627","bookId":"diwan-radi","type":"poem","seq":627,"chapter":"البحر: كامل تام","title":"يا صاحب الجدث الذي نفثت به","page":"","text":"يا صاحب الجدث الذي نفثت به … فاسترجعته برغمنا الأزمان\nنبكيك لو يثنى بأدمعنا الردى … أو يرعوي لبكائنا الحدثان\nأنزلت أقرب منزل منا فلم … بعد المدى وتعذر اللقيان\nلولا هجير الدمع ، بل هجر الكرى … دفنتك في أحشائها الأجفان"},{"id":"diwan-radi:628","bookId":"diwan-radi","type":"poem","seq":628,"chapter":"البحر: كامل تام","title":"بمجال عزمي يملأ الملوان","page":"","text":"بمجال عزمي يملأ الملوان … وتضل فيه بوائق الأزمان\nعزم رضيع لبان أطراف القنا … في حيث يرضع من نجيع لبان\nكم من حشى خطب شققت ضميره … وأرقت في دمه دم الأضغان\nوالليل منخرق القميص عن الضحى … قد كدت أرقعه بنقع حصاني\nوكأن أنجمه وجوه خرائد … سترت من القسطال بالأردان\nوخرجت عن أعجازه من بعد ما … جذب النعاس عمائم الركبان\nفي مهمه صقل المحول متونه … لم يصد قط بوابل هتان\nأرض حصان من ملامسة الحيا … والأرض تحمد منه غير حصان\nثم ارتمت بالغيث فيه غمامة … وسقت غليل الجدب بالتهتان\nفطوى الحيا برد النحول ونشرت … رمم الصعيد غدائر الأغصان\nوكأن أنفاس الصبا في حجرها … يسفحن دمع المزن في الحجران\nدمعا ، إذا ما فاض صور أعينا … حيث استقر به من الغدران\nوتريك من أوراقهن أهلة … تحت الغزالة ، شرد الغزلان\nولكم عقدت عرى الخطاب بخطبة … حلت بفيصلها عرى الحدثان\nلي همة أقطعتها قصد القنا … في قصد يومي معرك ورهان\nلو حاربت أفق السماء لفرقت … بين الثريا فيه والدبران\nعنوان بأسي أن يصول مهندي … وردى عدوي أن يطول لساني\nلا تجمعني والزمان ، فإنه … عود يحك جرانه بجراني\nإني لألحظ ذا الأنام مجانبا … عن مقلة وحشية الإنسان\nأسطو بجأش فتى يفرق سيفه … جيش الحمام إذا التقى الجمعان\nمن آل عدنان الذين كفاهم … إن ابن موسى من بني عدنان\nالنازلين ، إذا تقارعت القنا … والبيض خارجة عن الأجفان\nيحشون أحشاء الوفاض إذا هم … تزموا بفضل ذوائب الشجعان\nلبسوا العمائم مذ رأوا أسيافهم … أبدا تذل معاقد التيجان\nوإذا الحسين دعاهم بجيادهم … حشدت إليه مصرة الآذان\nمتواترات في الطلوع مغيرة … لفظ السواغب من نوى قران\nليث به سفك الطعان دم القنا … بدماء أهل الشرك والطغيان\nلما فزعن من التحطم في الطلى … جعل القلوب تمائم الخرصان\nلولاه ما طبعت ظبا لتقارع … أبدا ولا قطعت قنا لطعان\nلله يومك في غويث إنه … يوم به يشجى بنو غيلان\nبالحصن ، إذ دعت القنا خرصانها … وتحصنت في أنفس الفرسان\nغاضت مياه وجوههم خوف الردى … فكأنها فاضت إلى الأجفان\nصبحتهم بيد تطوح بالظبى … ويد تدق عوالي المران\nلدنا تهز طعينها فتخاله … في الطعن وثابا إلى الأقران\nقطعت أنفاس الحمام بجريها … حتى كبا في الهام والأبدان\nفكأنما الأرماح ضلت في الوغى … حتى انثنت تستاف كل جنان\nوالخيل تعثر بين أطراف القنا … مصبوغة بدم القلوب الآني\nستر السهام فروجها فكأنما … درعت إليك مدارع الظلمان\nلو أن أنفاس الرياح تصاعدت … في نقعها طارت مع العقبان\nخضت الظلام إليهم بسنابك … خاضت قلوب مواقد النيران\nوفريت وفرة ليلهم بصوارم … وصلت عرى الإصباح باللمعان\nحسر الدجى فنصبت أعناق العدا … قبلا لنيل رواكع الشريان\nفتركتهم صرعى بكل مفازة … وكأنما صعقوا على الأذقان\nتخفى النسور بزفها أجسادهم … عن ناظر الريبال والسرحان\nنبثت مناسرها الجراح ، كأنها … بالنبث تسبر وقع كل سنان\nحتى رجعت بفتية قصفوا القنا … ورموا بكل حنية مرنان\nلو أمكنوا وصلوا بكل مثقف … يسم الطلى في الطعن كل بنان\nأسد برى الإسئاد نحض جيادهم … بالكر والتضراب والتطعان\nلو عقدت بعضا ببعض في السرى … كانت له بدلا من الأرسان\nيهني بني عدنان وقعتك التي … جذبت بضبع الدين والإيمان\nلو لم تحل طلى الأعادي عقدوا … بعرى القلوب سبائب الأحزان\nقدها فغرتها من الكلم الجنى … وحجولها من صنعة ومعان\nهي نطفة رقرقتها من خاطري … بيضاء تنقع غلة الظمآن"},{"id":"diwan-radi:629","bookId":"diwan-radi","type":"poem","seq":629,"chapter":"البحر: كامل تام","title":"لون الشبيبة أنصل الألوان","page":"","text":"لون الشبيبة أنصل الألوان … والشيب جل عمائم الفتيان\nنبت بأعلى الرأس يرعاه الردى … رعي المطي منابت الغيطان\nالشيب أحسن غير أن غضارة … للمرء في ورق الشباب الآني\nوكذا بياض الناظرين وإنما … بسوادها تتأمل العينان\nلهفي على زمن مضى وكأنني … من بعده كل على الأزمان\nأفنيته طاغي العرام كأنما … في أم رأسي نخوة السكران\nيرجو الفتى خلس البقاء وإنما … جارا حياة العمر مفترقان\nمتعرض إما للون حائل … بين الذوائب ، أو لعمر فان\nمالي وما للدهر قلقل صرفه … عزمي وقطع بينه أقراني\nورمى تشخصي حر كل مفازة … لا يستقل بها مطي جبان\nمتغربا لا أستجير بمنزل … فإذا نزلت فعقلة الضيفان\nسيفي رفيقي في البلاد وهمتي … متعللي وجوانحي خلاني\nيشكو الحبيب إلي شدة شوقه … وأنا المشوق وما يبين جناني\nوإذا هممت بمن أحب أمالني … حصر يعوق وعفة تنهاني\nلله ما أغضت عليه جوانحي … والشوق تحت حجاب قلبي عان\nما مر برق في فروج غمامة … إلا وأعدى القلب بالخفقان\nوإذا تحركت الرياح تحركت … بين الضلوع غوامض الأشجان\nأجممت لحظي عفة وسجية … إن لا أجم البيض في الأجفان\nغيران دون العرض لا أسخو به … والعرض خير عقيلة الإنسان\nوأذود عن سمعي الملام كأنه … عضو أخاف عليه حد سنان\nلي يقظة الذئب الخبيث ، فإن جرى … سفه ، فعندي نومة الظربان\nحدث على الأحباب لا أشكو الذي … ويسومني لقيا ذوي الشنآن\nأشكو النوائب ، ثم أشكر فعلها … لعظيم ما ألقى من الخلان\nوإذا أمنت من الزمان فلا تكن … إلا على حذر من الإخوان\nكم من أخ تدعوه عند ملمة … فيكون أعظم من يد الحدثان\nلولا يقين القلب أنك حبسه … لعصى وهم عليك بالعدوان\nكم عممتني بالظلام مطية … بعد اعوجاج عمائم الركبان\nوالليل أعمى دون كل ثنية … والدهر غير مغمض الأجفان\nوكأن أنجمه أسنة فيلق … طلعت بها صم الكعوب دواني\nبطل يعمم بالحسام من الأذى … إن السيوف عمائم الشجعان\n … بعض التوكل في الأمور توان\nميت يهون على الفوارس فقده … من لا يرق عوالي المران\nما ضاق هما كالشجاع ولا خلا … بمسرة ، كالعاجز المتواني\nيا راكب الهوجاء تغترف الخطى … طلق الظليم ، وغاية السرحان\nأبلغ أمير المؤمنين رسالة … روعاء نافرة عن الأقران\nأجزلت عارفتي وعودت العطا … عقبي ، ووليت اليراع بناني\nما ضرني أن لو بعدت عن الغنى … أبدا وأني من لقائك دان\nويسرني أن لا يراني دائل … ومعظم يوما وأنت تراني\nذكراك آخر ما يفارق خاطري … ونداك أول وارد يلقاني\nوإذا حططت عليك أقسمت المنى … أن لا أميل ذوائب الكيران\nوتركت أيدي العيس غير مروعة … من صفصف متعرض ورعان\nوإذا الفتى بلغ المنى من دهره … عاف المسير ولذ بالأوطان\nأنت المعين على مآرب جمة … وجماح حادثة وريب زمان\nوالمستجار إذا تصافحت القنا … بصدورها والتفت الفئتان\nمتيقظ لا القلب يفتر همه … يوما ولا الجفنان ينقعدان\nوكأنما صرف الزمان أعاره … عيني قطامي برأس قنان\nلا يصحب الأيام إلا راغبا … في وصلتي ، أو سائلا عن شاني\nفي كل يوم يستثير عجاجة … هوجاء راغبة على القيعان\nفي فيلق تعمى الغزالة دونه … وتكوس خابطة بغير طعان\nمتضايق غصت به فيح الفلا … ضيق القلائد في رقاب غوان\nوفوارسا يتسمعون إلى العلى … نغمات كل حنية مرنان\nمشقوا بأطراف القنا قمم العدا … إن الرماح مخاصر الفرسان\nوإذا الغبار نهى العيون تدافعوا … في الروع واتكلوا على الآذان\nأسد كأن على سنابك خيلهم … يوم اللقاء مسفة العقبان\nترعى الجماجم والجميم إزاءها … ودم الطلى بدلا من الغدران\nلو شئت شتت الثريا شملها … جزعا هم النسر بالطيران\nليس الحمائم بالبطاح ، وحجرها … بأعز مما نلته بأمان\nعجبا لنار جاورتك خديعة … في أي ناحية وأي مغاني\nما كان ذا إلا تخمط غارة … بدلت من هبواتها بدخان\nما ضر ليث الغاب نار أضرمت … في غابه ، ونجا بغير هوان\nومتى تهضم ضيغم ، وتولعت … بحيا الغيوث أنامل النيران\n … عمر الزمان ومن رماك رماني\nماذا ، فليس بضائري أن لم أكن … لك جار بيت أو رضيع لبان\nولأنت حسرة ذي الخمول ومادرى … أن الثريا حسرة الدبران\nأنا حرب ضدك فارضني حربا له … وارض السنان مصمما لطعان\nوكفاك شكري إن برك ظاهر … عندي وما يخفى على الأعيان\nوإذا سكت ، فإن أنطق من فمي … عني فم المعروف والإحسان\nفاكفف سماحك واثن من غلوائه … إن الغنى في بعض ما أعطاني\nفليشكرنك ما شكرتك غالب … وذوائب الآباء من عدنان\nما مات من كثر الثناء وراءه … إن المذمم ميت الحيوان\nهذا الإمام يذودني عن وجهه … \nمتكلفا اقتات بشر معاشر … لهم إلي تشازر الغيران\nتتناتج الأحقاد بين ضلوعهم … ويزملون أجنة الأضغان\nوأنا الفقير على غزارة جوده … فإذا أراد بي الغنى أدناني\nلم آل جهدا في الثناء وإنما … غطى بعرض نداه طول لساني\nطمع المعادي أن يقربه ، ومن … صافى عدوا لي ، فقد عاداني\nطلب العلى وأبوه غير مهذب … بين الورى والأم غير حصان\nولأنت أولى إن ترب صنائعا … كثرت بهن مطامع وأماني\nوإذا بقيت فقد شفيت من العدا … قلبي ، وأعطيت الأمان زماني"},{"id":"diwan-radi:630","bookId":"diwan-radi","type":"poem","seq":630,"chapter":"البحر: كامل تام","title":"ونمى إلي من العجائب أنه","page":"","text":"ونمى إلي من العجائب أنه … لعبت بعقلك حيلة الخوان\nوتملكتك خديعة من قولة … غرارة الأقسام والأيمان\nحقا سمعت ، ورب عيني ناظر … يقظ تقوم مقامها الأذنان\nأين الذي أضمرته من بغضه … وعقدته بالسر والإعلان\nأم أين ذاك الرأي في إبعاده … حنقا وأين حمية الغضبان\nسبحان خالق كل شيء معجب … ما فيكم من كثرة الألوان\nيوم لذا ، وغد لذاك ، وهذه … شيم مقطعة قوى الأقران\nفالآن منك اليأس ينقع غلتي … واليأس يقطع غلة الظمآن\nفاذهب كما ذهب الغمام رجوته … فطوى البروق ، وضن بالهتان\nأو بعد أن أدمى مديحك خاطري … بصقال لفظ ، أو طلاب معاني\nلا بارك الرحمن في مال به … يعدى البعيد على القريب الداني\nلي مثل ملكك لو أطعت تقنعي … وذوو العمائم من ذوي التيجان\nولعل حالي إن يصير إلى على … فالدوح منبتها من القضبان\nفاحذر عواقب ما جنيت فربما … رمت الجناية عرض قلب الجاني\nأعطيتك الرأي الصريح ، وغيره … تنساب رغوته بغير بيان\nوعرضت نصحي ، والقبول إجازة … فإذا أبيت لويت عنك عناني\nولقد يطول عليك أن أصغي إلى … ذكراك أو يثني عليك لساني"},{"id":"diwan-radi:631","bookId":"diwan-radi","type":"poem","seq":631,"chapter":"البحر: طويل","title":"أيا جبلي نجد أبينا سقيتما","page":"","text":"أيا جبلي نجد أبينا سقيتما … متى زالت الأظعان يا جبلان\nأناديكما شوقا وأعلم أنه … وإن طال رجع القول ، لا تعيان\nأقول ، وقد مد الظلام رواقه … وألقى على هام الربى بجران\nنشدتكما أن تضمراني ساعة … لعلي أرى النار التي تريان\nوألقى ، على بعد من الدار ، نفحة … تذم على عيني من الهملان\nقفا صاحبي ايوم أسأل ساعة … ولا ترجعا سمعي بغير بيان\nهل الربع بعد الظاعنين كعهده … وهل راجع فيه علي زماني\nوهل مس ذاك الشيح عرنين ناشق … وهل ذاق ماء باللوى شفتان\nلقد غدر الأظعان يوم سويقة … ويدمى لذكر الغادرين بناني\nولا عجب ، قلبي ، كما هن ، غادر … على أن أضلاعي عليه حواني\nلك الله هل بعد الصدود تعطف … وهل بعد ريعان البعاد تداني\nوما غرضي أني أسومك خطة … كفاني قليل من رضاك كفاني\nوعاذلة قرط لأذني عذلها … تلوم ، وما لي بالسلو يدان\nأعاذلتي لو أن قلبك كان لي … سلوت ولكن غير قلبك عاني\nألا ليت لي من ماء يبرين شربة … ألذ لقلبي من غيرض لبان\nأداوي بها قلبا على النأي لم تدع … به فتكات الشوق غير حنان\nولولا الجوى لم أبغ إلا مدامة … بطعن القنا إبريقها الودجان\nإذا سكر العسال من قطراتها … سقيت حمياها أغر يماني\nولي أمل لا بد أحمل عبئه … على الجرد من خيفانة وحصان\nوكل رعود الشفرتين ، كأنه … سنى البرق أما جد في اللمعان\nوأسمر هزهاز الكعوب ، كأنه … قرا الذئب مجبول على العسلان\nفإن أنا لم أركب عظيما فلا مضى … حسامي ولا روى الطعان سناني"},{"id":"diwan-radi:632","bookId":"diwan-radi","type":"poem","seq":632,"chapter":"البحر: مجزوء الكامل","title":"الآن أعربت الظنون","page":"","text":"الآن أعربت الظنون … وعلا على الشك اليقين\nوارتاحت الآمال في … أطرافها جذل ولين\nفي غمة كالليل شا … ب لها الذوائب والقرون\nواليوم بان لناظري … ماأثمرت تلك الغصون\nوتمطت العشراء نا … هضة وقد علم الجنين\nألآن لما امتد بي … طوبى وأصحب لي القرين\nوعضضت من نابي على … جذم ونجذني الشؤون\nأغضي على خدع النوا … طتها جبان ، أو ظنين\nوعلى أمير المؤمني … ن لموئلي جبل حصين\nإنتاشني شلو النوا … زل والنوائب لي شجون\nوسطا بأيامي فقد … جعلت عرائكها تلين\nوأضاء لي زمني ، وأ … يام الفتى بيض وجون\nملكا بني العباس ، فالرا … مقامكم غبين\nما فيكم إلا الد … د على عظائمها مرون\nحتى يزول فحولها … منكم وقد دانوا ودينوا\nعكفوا على العلياء ما … فيهم على مجد ضنين\nينفون شائبها كما … عكفت على البيض القيون\nلهم الجياد مغذة … ينتابها الحرب الزبون\nوقنيصها لهم قرى … وظهورها لهم حصون\nمعتادة شرب الدما … ء ، وعندها الماء المعين\nغضبي إذا لم يلق أعي … نها ضريب أو طعين\nيا من له الرأي الزني … ق ومن له الحلم الرزين\nومروح الإبل الطلا … ح رمت بهن نوى شطون\nمن بعد ما خشعت غوا … ربها وقد قلق الوضين\nلك ذروة البيت المع … والأباطح والحجون\nأترى أمين الله إلا … لا من له البلد الأمين\nلله درك حيث لا … تسطو الشمال ولا اليمين\nوالأمر أمرك لا فم … يوحي ولا قول يبين\nلما رأيتك في مقا … م يستطار به الركين\nواليوم أبلج تستضي … ء له ظهور أو بطون\nورأيت ليث الغاب معتر … ضا له الدنيا عرين\nأقدمت إقدام الذي … يدنو وشافعه مكين\nفلذاك ما ارتعد الجنا … ن حيا ولا عرق الجبين\nوسمت بفضلك غرة … تغضي لهيبتها الجفون\nوامتد من نور النب … ي عليك عنوان مبين\nوجمال وجهك لي بنيل … جميع ما أرجو ضمين\nفأفيضت الخلع السوا … د علي ترشقها العيون\nشرف خصصت به وقد … درجت بغصته القرون\nوخرجت أسحبها ولي … فوق العلى والنجم دون\nجذلا ، وللحساد من … أسف زفير أو أنين\nوحملت من نعماك ما … لا تحمل الأجد الأمون\nوكففتني عن معشر … خطط المنى فيهم حزون\nمن كل جهم الصفح … ن كأن وجنته وجين\nهناك عيدك ، سعده … ما كان منه وما يكون\nوالعيد أن تبقى لك العلي … اء والحسب المصون\nعز بلا كدر من الدنيا … يا ، وبعض العز هون\nوأرى العلى جداء ، إ … أنها لكم لبون\nحمدا لما تولي فإن ال … د للنعماء دين\nوبقيت طول الدهر لا … يجتاحك الأجل الخؤون\nوعلي منك ضافيا … وعلى أعاديك المنون"},{"id":"diwan-radi:633","bookId":"diwan-radi","type":"poem","seq":633,"chapter":"البحر: طويل","title":"ألا مخبر ، فيما يقول ، جلية","page":"","text":"ألا مخبر ، فيما يقول ، جلية … يزيل بها الشك المريب يقين\nأسائله عن غائب كيف حاله … ومن نزل الغبراء كيف يكون\nوما كنت أخشى من زماني أنني … أرق على ضرائه وألين\nإلى أن رماني بالتي لا شوى لها … فأعقب من بعد الرنين أنين\nمعيني على الأيام فجعنني به … فما لي على أحداثهن معين\nغلبن على علقي النفيس فحزنه … وفارقني علق علي ثمين\nسمحت به إذ لم أجد عنه مدفعا … وإني على عذري به لضنين\nوإن أحق المجهشين لعبرة … ووجد قرين بان عنه قرين\nوما تنفع المرء الشمال وحيدة … إذا فارقتها بالمنون يمين\nتجرم عام لم أنل منك نظرة … وحان ولم يقدر لقاؤك حين\nوكيف وقد قطعن منك علائقي … وسدت شعوب بيننا ومنون\nأضب جديد الأرض دونك والتقت … عليك رجام كالغياطل جون\nتجاور فيها هامدين تعطلوا … ومن قبل دانوا في الزمان ودينوا\nمقيمين منها في بطون ضرائح … حوامل لا يبدو لهن جنين\nأمر بقبر قد طواك صعيده … فأبلس حتى ما أكاد أبين\nوتنفض بالوجد الأليم أضالع … وترفض بالدمع الغزيز شؤون\nفالأيكن عقر فقد عقرت له … خدود ، بأسراب الدموع عيون\nولا عجب أن تمطر العين فوقه … فإن سواد العين فيه دفين"},{"id":"diwan-radi:634","bookId":"diwan-radi","type":"poem","seq":634,"chapter":"البحر: منسرح","title":"توقعي أن يقال قد ظعنا","page":"","text":"توقعي أن يقال قد ظعنا … ما أنت لي منزلا ولا سكنا\nيا دار قل الصديق فيك ، فما … أحس ودا ، ولا أرى سكنا\nمالي مثل المذود عن أربي … ولي عرام يجرني الرسنا\nألين عن ذلة ، ومثلي من … ولى المقادير جانبا خشنا\nمعطلا ، بعد طول ملبثه … منازلا قد عمرتها زمنا\nتلعب بي النائبات واغلة … كما تهز الزعازع الغصنا\nأيقظن مني مهندا ذكرا … إلى المعالي وسائقا أرنا\nكيف يهاب الحمام منصلت … مذ خاف غدر الزمان ما أمنا\nلم يلبث الثوب من توقعه … الأمر إلا وظنه كفنا\nأعطشه الدهر من مطالبه … فراح يستمطر القنا اللدنا\nلي مهجة لا أرى لها عوضا … غير بلوغ العلى ولا ثمنا\nوكيف ترجو البقاء نفس فتى … ودأبها أن تضعضع البدنا\nفيما مقامي على معطلة … رنق لي ماؤها وقد أجنا\nأكر طرفي فلا أرى أحدا … إلا مغيظا علي مضطغنا\nينبض لي من لسانه أبدا … نصال ذم تمزق الجننا\nوكل مستنفر ترائبه … تحمل ضبا علي قد كمنا\nإن مر بي لم أعج به بصرا … أو قال لي لم أمل له أذنا\nمن معشر أظهروا الشجاعة في … الشجاعة في البخ\nل ، وعند المكارم الجبنا … قد شغلوا بالمعايب الفطنا\nيستحقبون الملام إن ركبوا … ويحملون الظنون والظننا\nنحن أسود الوغى إذا قصفت الط … ن قنا الخط في جوانبنا\nملتف أعياصنا إلى مضر … أمر عيداننا لعاجمنا\nنجر ما شئت من لسان فتى … إن هدرت ساعة شقاشقنا\nإن أبانا الذي سمعت به … أسس في هضبة العلى وبنى\nما ضرنا أننا بلا جدة … والبيت والركن والمقام لنا\nوهمة في العلاء لازمة … تلزم صم الرماح أيدينا\nطلابنا المجد من ذوائبه … روحنا بعد أن أضربنا\nنأخذ من جمة العلى أبدا … ما أخذ الضرب من جماجمنا\nسوف ترى أن نيل آخرنا … من العلى فوق نيل أولنا\nوأن ما بز من مقادمنا … يخلفه الله في عقائلنا\nذلك ورد قذى لسابقنا … والآن يجلى القذى للاحقنا\nدين على الله لا نماطله ال … الشكر عليه ولا يماطلنا\nلأوقرن الركاب سائرة … عزما يكد الأبدان والبدنا\nحتى تهاوى من اللغوب وتستن … تنجد بعد المناسم الثفنا\nحزا إلى المجد من أزمتها … ليس كحز الأعاجز الظعنا\nلأبلغ العز أو يقال فتى … جنت عليه يد الردى وجنى"},{"id":"diwan-radi:635","bookId":"diwan-radi","type":"poem","seq":635,"chapter":"البحر: رجز تام","title":"ستعلمون ما يكون مني","page":"","text":"ستعلمون ما يكون مني … إن مد من ضبعي طول سني\nأأدع الدنيا ولم تدعني … يلعب بي عناؤها المعني\nناطحة بالجم هام القرن … نطاح روق الجازي الأغن\nوسعت أيامي ، ولم تسعني … أفضل عنها وتضيق عني\nلم أنا مثل القاطن المبن … أسحب بردي ضرع وأفن\nولي مضاء قط لم يخني … ضمير قلبي وضمير جفني\nأحصل من عزمي على التمني … ليتني أفعل أو لواني\nراض بما يضوي الفتى ويضني … أسس آبائي وسوف أبني\nقد عز أصلي ، ويعز غصني … غنيت بالمجد ولم أستغن\nإن الغنى مجلبة للضن … وللقعود والرضا بالوهن\nالفقر ينئي والثراء يدني … والحرص يشقي ، والقنوع يغني\nإن كنت غير قارح ، فإني … أبذ جري القارح المسن\nجننت بأسا ، والشجاع جني … أثار طعن الدهر في مجني\nيشهد لي أن الزمان قرني … سوف ترى غبارها كالدجن\nقساطلا مثل غوادي المزن … تجري بضرب صادق وطعن\nجري عزالي المطر المستن … إن غبت يوما عنك فاطلبني\nبين المواضي والقنا تجدني … أمام جيش كجنوب الرعن\nجون الذرى أقود مرجحن … انفض عنه نقعه بردني\nلتعرفني ، ولتعرفني … أيام أقني بالقنا ، وأغني\nأقر عين الفاقد المرن … عساي أنفي الضيم ، أو لعني\nكم صبر خافي الشخص مستجن … منطمر من الأذى في سجن\nمرتهن بهمة تعني … يا ليتها بنهضة فدتني\nمن قبل أن يغلق يوما رهني … متى تراني والجواد خدني\nوالنصل عيني والسنان أذني … وأمي الدرع ولم تلدني\nأجر فضل ذيلها الرفن … ما احتبس الرزق فساء ظني\nولا قرعت من قنوط سني … يا أيها المغرور لا تهجني\nوعذ بإغضائي واستعذني … واحذر عداء قاطع في ضمني\nينطق عني بلسان ضغني … نبهت يقظان قليل الأمن\nمخرق الثوب بطعن اللدن … يا دهر سيفي معقلي وحصني\nوالخوف يغري طلبي فخفني … يا ليت مقدورك لم يؤمني\nجنيت من قبل وسوف أجني … أثني يدي والعزم أن أثني"},{"id":"diwan-radi:636","bookId":"diwan-radi","type":"poem","seq":636,"chapter":"البحر: وافر تام","title":"حقيق أن تكاثرك التهاني","page":"","text":"حقيق أن تكاثرك التهاني … بأيمن أول وأعز ثاني\nأرى بدرا أضاء بعقب شمس … مباركة الطلوع على القران\nوقال الناس من عجب وعجب : … تلاقى في السماء النيران\nهو الذكر المرشح للمعالي … وللبيض القواضب واللدان\nستنظره إذا اتسعت سنوه … وأخرجه زمان عن زمان\nربيبا للصوارم والعوالي … وتربا للمفاوز والرعان\nطليق الكف في يوم العطايا … جري الرمح في يوم الطعان\nربيط الجأش طلاع الثنايا … إلى الغايات رواغ العنان\nمقارعة الذوابل في الهوادي … أخف عليه من نغم القيان\nوأحسن عنده من كل ثغر … مضيء ، رونق العضب اليماني\nتراه أين خيم في الليالي … عزيز الجار مورود الجفان\nينال المجد من عنق المذاكي … ويجني العز من طرف السنان\nوليس جواده في النقع إلا … طليعة كل يوم أرونان\nيربى بين أحشاء المعالي … ويودع بين أجفان الأماني\nوعاد حماك من ولع الغوادي … عميم النبت مغمور المغاني\nيشيعني بوصفك كل نطق … ويعرفني بمدحك من رآني\nوليس الوصف إلا بالتناهي … وليس القول إلا بالبيان"},{"id":"diwan-radi:637","bookId":"diwan-radi","type":"poem","seq":637,"chapter":"البحر: طويل","title":"سقاها ، وإن لم يرو قلبي بيانها","page":"","text":"سقاها ، وإن لم يرو قلبي بيانها … وهل تنطق العجماء أقوى معانها\nضمان على قلبي الوفاء لأهلها … وثم ظباء لا يصح ضمانها\nعرضن بما روى الغليل اعتراضها … ولا قطع الجمع اللجوج اعتنانها\nوهل نافع أن يملأ العين حسنها … إذاهي لم تحسن إلينا حسانها\nتذكرت أياما بذي الأثل بعدما … تقضى أواني في الصبا وأوانها\nيطيب أنفاس الرياح ترابها … ويخضل من دمع الغمائم بانها\nولما عطفت الناظرين بلفتة … إلى الدار خلى عبرة العين شانها\nليالي تثنيني عواطف صبوتي … إلى بدويات تثنى لدانها\nولا لذة إلا الحديث كأنه … لآل على جيداء واه جمانها\nعفاف كما شاء الإله يسرني … وإن سيء منه بكرها وعرانها\nأألآن لما اعتم بالشيب مفرقي … وجلى الدجى عن لمتي لمعانها\nونجذني صرف الزمان ووقرت … على الحلم نفسي وانقضى نزوانها\nتروم العدا أن تستلان حميتي … وقبلهم أعدى علي حرانها\nأنا الرجل الألوى الذي تعرفونه … إذا نوب الأيام ألقي جرانها\nإذا كان غيري من قريش هجينها … فإني على رغم العدو هجانها\nوإن يك فخر أو نضال فإنني … لها يدها طورا ، وطورا لسانها\nوإني من القوم الذين ببأسهم … يذلل من أيامهم حدثانها\nإذا غبروا في الجو ضاق فضاؤه … وإن نزلوا البيداء غمت رعانها\nفوارس تجري بالدماء رماحها … وتفهق بالني الغريض جفانها\nيثور إذا أوفى الصباح عجاجها … ويعلو إذا جن الظلام دخانها\nوإني لوثاب على كل فرصة … تخيل على الرائي ، ويخفى مكانها\nسبقت وقفيتم بكل طليعة … على عقبي يلوي بها هدجانها\nوما كنت إلا كالثريا تحلقا … يدف على آثارها دبرانها\nعصائب ما استام الفخار وضيعها … ولا استأنف العز الجديد مهانها\nإذا لحظتني أمسكت بأكفها … علي ، قلوبا دائما خفقانها\nفلا هي يوما في ينفذ كيدها … ولا ينجلي من غيها شنآنها\nيريد المعالي عاطل من أداتها … وهيهات من محصوصة طيرانها\nدعوها لمن رباه مذ كان حجرها … وأرضعه حتى استقل لبانها\nولا تخطبوها بالرجاء ، فما أرى … تدنس بالبعل الدني حصانها\nرآني بهاء الملك سيفا عليكم … جريء الظبا لا ينثني صلتانها\nفجردني من بعد طول صيانة … وإن مضرا بالسيوف صيانها\nأفاض ، بلا من ، علي كرامة … ونقص الأيادي إن يزيد امتنانها\nخرجت أجر الذيل منها وقد نزت … قلوب العدا مني ، وجن جنانها\nوليس على زهر الكواكب سبة … إذا غض من أنوارها زبرقانها\nوقرب لي وافي العذار تلبست … به خيلاء ما يزول افتنانها\nألا إن أصناف السيوف كثيرة … وأقطعها هنديها ويمانها\nوكل أنابيب القناة شريفة … وأشرفها ، لو تعلمون ، سنانها\nفكيف وأنتم وثبة الليث إذ رمى … تخمطها في جمعكم واستنانها\nوكان يسوء السامعين سماعها … فصار يهول الناظرين عيانها\nفمن مبلغ عني الجبان بأنني … أنا المورد الشقراء يدمى لبانها\nولو لم تعن كفي قناة قويمة … لأجرى ينابيع الدماء بنانها\nبلينا ونحن الناهضون إلى العلى … بزمنى يمنيها الغرور زمانها\nذئاب أرادت أن تعازز ضيغما … فطال على مر الزمان هوانها\nرأوا فترة منا فظنوا ضراعة … وتلك بروق غرهم شولانها\nفكيف تعرضتم بغير نباهة … لصعبة عز في يدي عنانها\nفإن تعتطل يوما من الدهر صعدتي … فقد طال في نحر العدو طعانها\nوإن تستجم النائبات سوابقي … فمن قبل ما بذ الجياد رهانها"},{"id":"diwan-radi:638","bookId":"diwan-radi","type":"poem","seq":638,"chapter":"البحر: طويل","title":"ظمائي إلى من لو أراد سقاني","page":"","text":"ظمائي إلى من لو أراد سقاني … وديني على من لو يشاء قضاني\nولو كان عندي معسرا لعذرته … ولكنه ، وهو المليء ، لواني\nرمى مقتلي واسترجع السهم داميا … غزال بنجلاوين تنتضلان\nأأرجو شفاء منه وهو الذي جنى … على بدني داء الضنى وشجاني\nأبيت ، فلم أستسق من كان غلتي … ولم استرش من كان قبل براني\nمررت على تلك الديار ، ووحشها … دوان ، ومن يحكين غير دواني\nفأنكرت العينان والقلب عارف … قليلا ، ولجا بعد في الهملان\nعشية بلتني الدموع كأنما … رداواي بردا ماتح خضلان\nضمن وصالي ثم ماطلن دونه … وإن ضمان البيض شر ضمان\nأمنك طروق الزور أية ساعة … وعيد خيال عاد أي أوان ؟\nألم بعوج كالحنايا مناخة … على جزع واد ذي ربى ومجاني\nوميل كخيطان الأراك ترنحوا … فمن ذقن مستقبل بلسان\nومالوا على البوغاء من كل جانب … عواطف أيدي توأم وثوان\nيقودهم مني غلام غشمشم … معين على البأساء غير معان\nإذا انفرجت منه السجوف لناظر … تألق نور من أغر هجان\nوإني لآوي من أعز قبيلة … إلى نضد ، أو جامل عكنان\nوإن قعودي أرقب اليوم أو غدا … لعجز ، فما الإبطاء بالنهضان\nسأترك في سمع الزمان دويها … بقرعي ضراب صادق وطعان\nوأخصف أخفافا بوقع حوافر … إلى غاية تقضي منى وأماني\nفإن أسر ، فالعلياء همي ، وإن أقم … فإني على بكر المكارم باني\nوإن امض أترك كل حي من العدا … يقول ألا لله نفس فلان\nأكرر في الإخوان عينا صحيحة … على أعين مرضى من الشنآن\nفلولا أبو إسحق قل تشبثي … بخل ، وضربي عنده بجران\nهو اللافتي عن ذا الزمان وأهله … بشيمة لا وان ، ولا متوان\nإخاء تساوى فيه أنسا وألفة … رضيع صفاء أو رضيع لبان\nتمازج قلبانا مزاج أخوة … وكل طلوبي غاية إخوان\nوغيرك ينبو عنه طرفي مجانبا … وإن كان مني الأقرب المتداني\nورب قريب بالعداوة شاحط … ورب بعيد بالمودة داني\nلئن رام قبضا من بنانك حادث … لقد عاضنا منك انبساط جنان\nوإن بز من ذاك الجناح مطاره … فرب مقال منك ذي طيران\nوإن أقعدتك النائبات ، فطالما … سرى موقرا من مجدك الملوان\nوإن هدمت منك الخطوب بمرها … فثم لسان للمناقب باني\nمآثر تبقى ما رأى الشمس ناظر … وما سمعت من سامع أذنان\nوموسومة مقطوعة العقل لم تزل … شوارد قد بالغن في الجولان\nوما زل منك الرأي والحزم والحجى … فنأسى إذا ما زلت القدمان\nولو أن لي ، يوما ، على الدهر إمرة … وكان لي العدوى علي الحدثان\nخلعت على عطفيك برد شبيبتي … جوادا بعمري واقتبال زماني\nوحملت ثقل الشيب عنك مفارقي … وإن فل من غربي وغض عناني\nونابت طويلا عنك في كل عارض … بخط وخطو أخمصي وبناني\nعلى أنه ما انفل من كان دونه … حميم يرامي عن يد ولسان\nوما كل من لم يعط نهضا بعاجز … ولا كل ليث خادر بجبان\nوإنك ما استرعيت مني سوى فتى … ضموم على رعي الأمانة حان\nحفيظ إذا ما صيع المرء قومه … وفي ، إذا ما خون العضدان\nمن الله أستهدي بقاءك أن ترى … محلا لأسباب العلى بمكان\nوأسأله إن لا تزال مخلدا … بملقى سماع بيننا وعيان\nإذا ما رعاك الله يوما ، فقد قضى … مآرب قلبي كلها ورعاني"},{"id":"diwan-radi:639","bookId":"diwan-radi","type":"poem","seq":639,"chapter":"البحر: بسيط تام","title":"دع من دموعك بعد البين للدمن","page":"","text":"دع من دموعك بعد البين للدمن … غدا لدارهم واليوم للظعن\nهل وقفة بلوى خبت مؤلفة … بين الخليطين من شام ومن يمن\nعجنا على الركب أنضاء محزمة … أثقالها الشوق من باد ومكتمن\nموسومة بالهوى يدرى برؤيتها … إن المطايا مضمري شجن\nثم انثنينا على يأس وقد وجلت … نواظر بمجاري دمعها الهتن\nتروم رد نفوس بعد طيرتها … على قوادم من وجد ومن حزن\nتعريسة بين رملي عالج ضمنت … بل الغليل لقلب الموجع الضمن\nبتنا سجودا على الأكوار يحملنا … لواغب قد لطمن الأرض بالثفن\nأهفو إلى الريح إن هبت يمانية … تحدو زعازعها عيرا من المزن\nأبى ضميري إلا ذكره ، وأبى … تعرض البرق إلا أن يؤرقني\nشوق ألم وما شوقي إلى أحد … سوى الذي نام عن ليلي وأيقظني\nإن زاغ قلبي ، فإن الهجر أحرجني … وإن صبرت فإن اليأس صبرني\nوكم رمتني من الأقدار منبضة … لم تثن باعي ولم يحرج لها عطني\nما كنت أعلم والأيام عالمة … إن الليالي تقاعيني لتنهشني\nقد أدمج الهم في عنقي حبائله … ولزة الهم تنسي لزة القرن\nإن يبل ثوبي ، فإني أكتسي حسبي … أو تود خيلي فإني أمتطي منني\nوأدخل البيت لم تأذن قعائده … على الحصان أمام القوم والحصن\nلا أطلب المال إلا من مطالبه … ولا يفي لي بذل المال بالمنن\nإن البخيل الذي قد بات يؤنسني … مثل الجواد الذي قد بات يمطلني\nلقد تقدم بي فضلي بلا قدم … أعظم بأمر على ذي السن قدمني\nلا يبرح المجد مرفوعا دعائمه … ما دام معتمدا منا على ركن\nمن أسرة تنبت التيجان هامهم … منابت النبع في الأطواد والقنن\nالمجد أنوط من كف إلى عضد … فيهم ، وأقوم من رأس على بدن\nمن مبلغ لي أبا اسحق مألكة … عن حنو قلب سليم السر والعلن\nجرى الوداد له مني ، وإن بعدت … منا العلائق مجرى الماء في الغصن\nلقد توامق قلبانا كأنهما … تراضعا بدم الأحشاء لا اللبن\nمسود قصب الأقلام نال بها … نيل المحمر أطراف القنا اللدن\nإن لم تكن تورد الأرماح موردها … فما عدلت إلى الأقلام عن جبن\nوالطاعن الطعنة النجلاء عن جلد … كالقائل القولة الغراء عن لسن\nحار المجارون إذ جاروك في طلق … وأجفلوا عن طريق السابق الأرن\nضلوا وراءك حتى قال قائلهم : … ماذا الضلال وذا يجري على السنن\nما قدر فضلك ما أصبحت ترزقه … ليس الحظوظ على الأقدار والمهن\nقد كنت قبلك من دهري على حنق … فزاد ما بك من غيظي على الزمن\nكم راشنا وبرانا ، غير مكترث … بما نعالج ، بري القدح بالسفن\nألقى على آل وضاح حويته … وحك بركا على سيف بن ذي يزن\nومثلها أنشب الأظفار في مضر … ومر يحرق بالأنياب لليمن\nإن يدن قوم إلى داري فألفهم … وتنأ عني فأنت الروح في البدن\nفالمرء يسرح في الآفاق مضطربا … ونفسه أبدا تهفو إلى الوطن\nوالبعد عنك بلاني باستكانهم … إن الغريب لمضطر إلى السكن\nأنت الكرى مؤنسا طرفي وبعضهم … مثل القذى مانع عيني من الوسن\nكم من قريب يرى أني كلفت به … يمسى شجاي وتضحى دونه شجني\nوصاحب طال ما ضرت صحابته … عكفت منه على اطغى من الوثن\nمستهدف لمرامي العيب جانبه … يكاد ينعط برداه من الظنن\nذي سؤة إن ثناها محفل كثرت … لها المضارب فوق الصدر بالذقن\nإذا احتميت به أحمي على كبدي … كيف اجتناني إذا أسلمنني جنني\nلا تجعلن دليل المرء صورته … كم مخبر سمج عن منظر حسن\nإن الصحائف لا يقريك باطنها … نفس الطوابع موسوما على الطين\nأشتاقكم ودواعي الشوق تنهضني … إليكم وعوادي الدهر تقعدني\nوأعرض الود أحيانا فيؤنسني … وأذكر البعد أطوارا فيوحشني\nهذا ، ودجلة ما بيني وبينكم … وجانب العبر غير الجانب الخشن\nومشرف كسنام العود ملتبس … كالماء لز بأضلاع من السفن\nكالخيل ربطن دهما في مواقفها … والبزل قطرن بين الحوض والعطن\nقد جاءت النفثة الغراء ضامنة … ما يوبق النفس من عجب ومن درن\nأنبطت من حسنها ماء بلا نصب … وحزت من نظمها درا بلا ثمن\nأنشدتها فحدا سمعي غرائبها … إلى الضمير حداء الركب للبدن\nجازت إلى خاطري عفوا وخيل لي … مما استبت أذني ، أن لم تجز أذني\nفاقتد إليك أبا اسحق قافية … قود الجواد ، بلا جل ولا رسن\nكادت تقاعس لو ما كنت قائدها … تقاعس البازل المجنوب في الشطن\nتستوقف الركب إن مرت معارضة … تهدي عقيلتها العذراء من يمن"},{"id":"diwan-radi:640","bookId":"diwan-radi","type":"poem","seq":640,"chapter":"البحر: وافر تام","title":"تواعد ذا الخليط لأن يبينا","page":"","text":"تواعد ذا الخليط لأن يبينا … وزايلنا القطين ، فلا قطينا\nوإني ، والمواعد كاذبات … ليطمعنا خلاب الواعدينا\nنعنى بالمطال من الغواني … وهان على المواطل ما لقينا\nونظمأ والموارد معرضات … فنرجع بالغليل ، وما سقينا\nلهن الله كيف أصبن منا … نفوسا ما عقلنا وما ودينا\nلقين قلوبنا بجنود حرب … تطاعن بالدمالج والبرينا\nجلون لنا لآليء واضحات … أضأن بها الذوائب والقرونا\nعهدنا الدر مسكنه أجاج … فكيف تبدل الثغب المعينا\nجنون المرشقات غداة جمع … بأقتل من نبالك ما رمينا\nولم نر كالعيون ظبا سيوف … أرقن دما ، وما رمن الجفونا\nعوائد من تذكر آل ليلى … كأن لها على قلبي ديونا\nأكاتمها ففي الأحشاء منها … مضيض بعدما بلغ الحنينا\nفيا حادي السنين قف المطايا … وعز على العقائل أن يهونا\nوإن الرأس بعدك صوحته … بوارح شيبة فغدا جبينا\nوكان سواده عيد الغواني … يعدن إلى مطالعة العيونا\nأتاجرها ، فأربح في التصابي … وبعض القوم يحسبني غبينا\nأهان الشيب ما أعززن منه … \nجنون شبيبة ووقار شيب … خذا عني النهى ودعا الجنونا\nنرى الأيام وهي غدا سنون … وبالآحاد يبلغن المئينا\nستنبئنا النوائب ما أرتنا … من العجب العجيب بما ترينا\nحلفت بملقيات التي عوج … خوابط تطلب البلد الأمينا\nحوامل ناحلين على ذراها … حواني ينجذبن بمنحنينا\nيسقين الهجير على التظامي … وينعلن الحرار إذا وجينا\nكأن سياطها ولها هباب … قلوع اليم زعزعت السفينا\nبكل معبد القطرين ينضي … مطال طريقه الأجد الأمينا\nلقد أرضى قوام الدين فينا … وصاة الله والدين اليقينا\nرعانا بالقنا ، ولقد ترانا … وأضبع ما نكون إذا رعينا\nأعاد ثقافنا حتى استقمنا … ودل بنوره اللقم المبينا\nتيقظ والعيون مغمضات … وقلقل والرعية وادعونا\nنماه أب ولود للمعالي … وفي خرق الوليد ولا جنينا\nمن القوم الألى تبعوا المعالي … قران العود يتبع القرينا\nأقاموا عن فرائسها الليالي … وردوا عن موادرها المنونا\nهم رفعوا كما رفعت نزار … قباب على على كرم بنينا\nنبقي سائرات الدهر فيهم … ويبقون اليد البيضاء فينا\nفإن نثمر لهم شكرا طويلا … فهم غرسوا ، وكانوا المورقينا\nفقل للمصحرين دعوا الضواحي … فإن الليث قد نزع العرينا\nولا تتغنموا منه قعودا … يقيم لكم به الحرب الزبونا\nففي أغماده ورق قديم … يزيد علي قراع الصيد لينا\nقواضب لا يغب بها الهوادي … فيعطيها الصياقل والقيونا\nأليس وقاعه بالأمس فيكم … سقى غلل الرماح وما روينا\nبأربق قد أدار لكم رحاها … مدار الطود مرداة طحونا\nوجلجلها على الأهواز حتى … أعاد زئير أسدكم أنينا\nوساخ ، تقصع اليربوع ، غاو … أثار بطعنها ، فنجا طعينا\nأشيعث ، رأسه بالبيض يفلى … ويغدو بالدم الجاري دهينا\nيذود رقابها هيهات منها … وقد غلبت عصي الذائدينا\nتولع بالقنا فتطاوحته … لداغ الدبر ، أيدي الغاسلينا\nغدا يمري عفافتها ، فأمسى … يرى بالطعن لقحتها لبونا\nومن شرعت رماح الله فيه … درى أن السوابغ لا يقينا\nوبتن على المطالع ملجمات … علائقها أنابيب القنينا\nعلى صهواتها أبناء موت … حواسر للردى ومقنعينا\nمجاذبة أعنتها جماحا … هبطن قرارة وطلعن بينا\nوقعن بغارة ، وطلبن أخرى … يماطلن الإقامة والصفونا\nتكفكف وهي في الغلواء تلقي … إلى أرض العدا نظرا شفونا\nتلفت جوع الآساد فاتت … فرائسها النيوب وقد دمينا\nتحاذر في مرابطها وقوفا … وإن بلغ العدا أمدا شطونا\nفلو ألجمن لا لغوار حرب … لقد ظن العدو بها الظنونا\nومنشرها على هضبات بم … رياطا للعجاجة ما طوينا\nإذا رجع الغزي بهن حسرى … أعدن إلى الطعان كما بدينا\nلحقن طريدة لولا قناها … لطال رواغها للطاردينا\nوعدن ، وفي حقائبهن هام … لقين من الصوارم ما لقينا\nبقناص أصاب وفي يديه … حبائل قد مددن لآخرينا\nنوائب ألقت الجلى عليه … فقام بعبئهن وما أعينا\n … وحنظلة الذي قطع الوضينا\nوهل يرضى المطول وفي الأعادي … ديون للصوارم ما قضينا\nإلا جزت الجوازي اليوم عني … جوادا لا أغم ولا هجينا\nنماه أب ولوج للمعالي … وأم أراقم تدهي البنينا\nمن العظماء أطولهم عمادا … وأنداهم إذا مطروا يمينا\nتبوع بي إلى قلل المعالي … وخيرني المعاقل والحصونا\nفأرغم بي على رغم أنوفا … مضاغنة ، وأقذى بي عيونا\nتهن بمطلع النيروز وابلغ … مطالع مثله حينا فحينا\nمرحل كل نائبة مقيما … مذيلا للعدا ، أبدا مصونا\nتظفر بالمآرب طيعات … وبالآمال أبكارا وعونا\nوإن أحق منك بأن يهنى … إذا مد البقاء لك ، السنونا"},{"id":"diwan-radi:641","bookId":"diwan-radi","type":"poem","seq":641,"chapter":"البحر: طويل","title":"جناني شجاع إن مدحت وإنما","page":"","text":"جناني شجاع إن مدحت وإنما … لساني إن سيم النشيد جبان\nوما ضر قوالا أطاع جنانه … إذا خانه عند الملوك لسان\nورب حيي في السلام وقلبه … وقاح ، إذا لف الجياد طعان\nورب وقاح الوجه يحمل كفه … أنامل لم يعرق بهن عنان\nوفخر الفتى بالقول لا بنشيده … ويروي فلان مرة وفلان"},{"id":"diwan-radi:642","bookId":"diwan-radi","type":"poem","seq":642,"chapter":"البحر: طويل","title":"دعا بالوحاف السود من جانب الحمى","page":"","text":"دعا بالوحاف السود من جانب الحمى … نزيع هوى ، لبيت حين دعاني\nتعجب صحبي من بكائي وأنكروا … جوابي لما لم تسمع الأذنان\nفقلت نعم لم تسمع الأذن دعوة … بلى إن قلبي سامع وجناني\nويا أيها الركب اليمانون خبروا … طليقا بأعلى الخيف أني عاني\nعدوه لقائي أوعدوني لقاءه … إلا ربما دانيت غير مداني\nوما حائمات يلتقين من الصدى … إلى الماء قد موطلن بالرشفان\nيزيد لها بالخمس بين ضلوعها … تنسم ريح الشيح والعلجان\nإذا قيل هذا الماء لم يملكوا لها … معاجا بأقران ولا بمثان\nبأظمى إلى الأحباب مني وفيهم … غريم ، إذا رمت الديون لواني\nفيا صاحبي رحلي أقلا فإنني … رأيت بليلى غير ما تريان\nويا مزجي النضو الطليح عشية … تراك ببطن المأزمين تراني\nوهل أنا غاد أنشد النبلة التي … بها عرضا ذاك الغزال رماني\nفلم يبق من أيام جمع إلى منى … إلى موقف التجمير غير أماني\nيعلل دائي بالعراق طماعة … وكيف شفائي والطبيب يماني"},{"id":"diwan-radi:643","bookId":"diwan-radi","type":"poem","seq":643,"chapter":"البحر: طويل","title":"أفي كل يوم لي عشار تسوقها","page":"","text":"أفي كل يوم لي عشار تسوقها … رماح بني الغبراء سوق الظعائن\nأحالوا عليها عاكسين رقابها … وطوا بهواديها مكان الفراسن\nإذا جزت في أبيات آل محلم … تراغين نحوي من وراء المعاطن\nتحن إلى ترعية لم يرد بها … وبيء المراعي والنطاف الأواجن\nوخالسنيها كل أطلس خاتل … خفي المرامي عن قسي الضغائن\nوشر الأذى ما جاء من غير حسبة … وكيد المبادي دون كيد المداهن\nوإن بلوغ الخوف من قلب خائف … لدون بلوغ الخوف من قلب آمن\nوخيل جررن النقع في كل بلدة … وناقلن فيها بالطوال الموارن\nحواها العدا عني ، فأصبحن بالحمى … عواطل من آبي عليق وصافن\nوثلة حي قد أضب بأرضها … ذؤالة أضباب الغريم المداين\nولولا ذئاب العامري لشابهت … بمكة أسراب الحمام القواطن\nلنا كل يوم منه ذئب عمرد … دم الشعر في أنيابه والبراثن\nمتى تطلعوا نجدا أو الغور تفضحوا … بوسم فشت نيرانه في المواطن\nخطبتم إلى شمس الخدود فوارك … طوالق من حبل اللئام بوائن\nعذارى بغت فيكم بغاء نسائكم … وقد كن عندي في ثياب الحواضن\nخذوها فلو قرنتموها ببرقة … قطعن إلى داري وثاق القرائن"},{"id":"diwan-radi:644","bookId":"diwan-radi","type":"poem","seq":644,"chapter":"البحر: سريع","title":"ومستهلات كصوب الحيا","page":"","text":"ومستهلات كصوب الحيا … تبقى ، وأقوال الفتى تفنى\nمنتصبات كالقنا لا نرى … عيا من القول ولا أفنا\nقد حرم الناظر من حسنها … قائلها ما رزق الأذنا\nلا يفضل المعنى على لفظه … شيئا ، ولا اللفظ على المعنى"},{"id":"diwan-radi:645","bookId":"diwan-radi","type":"poem","seq":645,"chapter":"البحر: كامل تام","title":"ووصية خلفت لنا من حازم","page":"","text":"ووصية خلفت لنا من حازم … وطئ الزمان سهولة وحزونا\nلما تعذر أن يبقي نفسه … بقى ، علينا رأيه المأمونا"},{"id":"diwan-radi:646","bookId":"diwan-radi","type":"poem","seq":646,"chapter":"البحر: بسيط تام","title":"أي المنازل نرضى بعدكم وطنا","page":"","text":"أي المنازل نرضى بعدكم وطنا … هان الفراق فما نعني بمن ظعنا\nلقد سقوك بأطباء ملعنة … كأنما كنت تسقى السم لا اللبنا"},{"id":"diwan-radi:647","bookId":"diwan-radi","type":"poem","seq":647,"chapter":"البحر: كامل تام","title":"هذي المنازل فاضربي بجران","page":"","text":"هذي المنازل فاضربي بجران … وتذكري الأوطار بالأوطان\nحي الطلول كما تحيي أهلها … إن الطلول وأهلها سيان"},{"id":"diwan-radi:648","bookId":"diwan-radi","type":"poem","seq":648,"chapter":"البحر: وافر تام","title":"قصور الجد مع طول المساعي","page":"","text":"قصور الجد مع طول المساعي … وقول الناس لم ينجح فلان\nأحب إلي من سعي هجين … وإن بلغ العلى جد هجان\nيذم لي الزمان إذا الامت … يداه ولا يذم بي الزمان"},{"id":"diwan-radi:649","bookId":"diwan-radi","type":"poem","seq":649,"chapter":"البحر: خفيف تام","title":"سبق الدهر جدكم في الرهان","page":"","text":"سبق الدهر جدكم في الرهان … وعلت ناركم على النيران\nوجرى في عنانكم جامح الج … د ، مطولا يلوي بكل عنان"},{"id":"diwan-radi:650","bookId":"diwan-radi","type":"poem","seq":650,"chapter":"البحر: وافر تام","title":"هبي لي ني زورك والبواني","page":"","text":"هبي لي ني زورك والبواني … وأمي مسقط النجم اليماني\nفإنك ما رعيت من الفيافي … طويلا ما رعيت من الأماني"},{"id":"diwan-radi:651","bookId":"diwan-radi","type":"poem","seq":651,"chapter":"البحر: كامل تام","title":"بئس التحية بيننا المران","page":"","text":"بئس التحية بيننا المران … وضراب يوم وقيعة وطعان\nبسطوا إلي أناملا مغروسة … في اللؤم لم يعرق لهن عنان"},{"id":"diwan-radi:652","bookId":"diwan-radi","type":"poem","seq":652,"chapter":"البحر: متقارب تام","title":"وبرق حدا المزن حدو الثقال","page":"","text":"وبرق حدا المزن حدو الثقال … يزجي على الأين حينا فحينا\nكراعي العشار أحس الظلام … فساق الهجائن بيضا وجونا"},{"id":"diwan-radi:653","bookId":"diwan-radi","type":"poem","seq":653,"chapter":"البحر: طويل","title":"إلى أين مرمى قصدها وسراها","page":"","text":"إلى أين مرمى قصدها وسراها … رمى الله من أخفافها بوجاها\nهو اليأس فليحبس هباب رقابها … كما كان مغرور الرجاء حداها\nرأت لامعا ، فاستشرقت لمضائه … ولو كان من مزن الندى لشفاها\nتدافعها الحي اللئيم عماية … وأعرض طوع اللؤم وهو يراها\nفماطل أصحاب الحياض ورودها … وأعتم أرباب المبيت قراها\nتلطمها الأيدي القصار عن الرقى … وخير من الري الذليل صداها\nترى كل ميلاء السنام كأنما … من الطود إلا زجوها وخطاها\nمناقلة تنجو بزجرة غيرها … وترهب سوط المرء راع سواها\nتكاد من الإسراع تسبق أمها … بمنتجها قبل اللقاح أباها\nتعود ولم تشرع بحوض ابن حرة … ولا عريت عند الكرام ذراها\nرأين ديارا بين بصرى وجاسم … مراعي ليوم لا تلس خلاها\nنفوس لئام لا تحل عقودها … وأيدي جمود لا ينض صفاها\nألا ! لا تلوموا ظاعنا قذفت به … بنات السرى عن أرضكم ونواها\nرعت ذروة فيكم ضحى جاشرية … فأجشرت في أوطانكم ، وأعاها\nتحمل عنها شر دار إقامة … إذا قيل أي الأرض قال خلاها\nفكم موحشات بالرفاق أزاحها … ولمة ليل بالمطي فلاها\nكان حماكم خطة الخسف للفتى … إذا سيمها الحر الكريم أباها\nولو بابن ليلى كان ملقى رحالها … لطرق من حر النضار ثراها\nتباينتها فعلا ، فكم من عظيمة … أتيت بها مرحولة وكفاها\nحماك ملما منتضى لك حده … وداهية تشحو لضغنك فاها\nغداة أغامت بالعجاج سماؤها … ودارت على قطب الطعان رحاها\nإذا السيل والى في الركاء سجاله … وأنبط ، أنقوت الندى ، وأماها\nأرى شجرا طالت وقصر ظلها … فلا أورقت يوما وطال ذواها\nولو جمعت لونين بذل شباكها … لطالبها الراجي بمنع جناها\nأضرا ولؤما لا أبا لأبيكم … سفاها لرأي العاجزين سفاها\nنلوم أكف المحسنين إذا جنت … فكيف بأيد لا ينال جداها\nضلالا لراجي نشطة من ربيعكم … رمى الداء في أكلائكم فحماها\nوعين رجتكم أن تكونوا جلاءها … فكنتم على عكس الرجاء قذاها\nطلبتم ثنائي ثم عفتم سماعه … كمن خطب العذراء ، ثم قلاها\nوما كل جيد موضع لقلائدي … ولا قمن من صوغها وحلاها\nفلا تغررن عينيك يا خابط الدجى … قباب بناها اللؤم حيث بناها\nودار لئام إن رأى الركب سمتها … تحايد عنها عامدا ، وطواها\nمساو كنيران البقاع مضيئة … ونار ظلام لا يضيء سناها\nألا غنياني بالديار ، فإنني … أحب زرودا ما أقام ثراها\nوبين النقا والأنعمين محلة … حبيب لقلبي قاعها ورباها\nونعمان يا سقيا لنعمان ما جرت … عليه النعامى بعدنا وصباها\nوللقلب عند المأزمين وجمعها … ديون ومضى خيفها ومناها\nوظبي بأطوار الجمار إذا غدا … رمى كبدا مقروحة ورماها\nوغيداء لم تصحب سوى الشمس أختها … ولا جاورت إلا الغزال أخاها\nوخلة فرسان عيون ظبائها … أمض جراحا من طعان قناها\nهي الدار لا دار بأكناف بابل … جدير بضيم النازلين حماها\nمنازل ممنون على الركب زادها … نزور على كد المطال جداها\nفلا سقيت إلا الصوارم والقنا … ولا صاب إلا بالدماء حياها"},{"id":"diwan-radi:654","bookId":"diwan-radi","type":"poem","seq":654,"chapter":"البحر: متقارب تام","title":"تلفت ، والرمل ما بيننا","page":"","text":"تلفت ، والرمل ما بيننا … وأعلام ذي بقر أو رباه\nفقلت على طربات الهوى : … عسى الطرف يبلغهم أو كراه\nفما لقي الحب إلا الجوى … ولا بلغ الطرف إلا قذاه\nبذكري أشم ثرى أرضه … على نأيه ، وبقلبي أراه\nعسى من رمى بالمحب الغري … ب مرمى بعيدا يقضي نواه\nوتدنو الديار بسكانها … تمني امرىء ما عراكم عراه\nأصاح ترى البرق في لمعه … تخلج أيم يلوي مطاه\nوقالوا : سناه على رامة … ويا بعد موقفنا من سناه\nدع القلب يأرق من ذكرهم … فقد ذاق من بينهم ما كفاه\nفلا حط إلا بهم رحله … ولا جاد إلا عليهم حياه"},{"id":"diwan-radi:655","bookId":"diwan-radi","type":"poem","seq":655,"chapter":"البحر: وافر تام","title":"أحبك ما أقام منى وجمع","page":"","text":"أحبك ما أقام منى وجمع … وما أرسى بمكة أخشباها\nوما رفع الحجيج إلى المصلى … يجرون المطي على وجاها\nوما نحروا بخيف منى وكبوا … على الأذقان مشعرة ذراها\nنظرتك نظرة بالخيف كانت … جلاء العين مني بل قذاها\nولم يك غير موقفنا فطارت … بكل قبيلة منا نواها\nفواها كيف تجمعنا الليالي … وآها من تفرقنا ، وآها\nفأقسم بالوقوف على آلال … ومن شهد الجمار ومن رماها\nوأركان العتيق وبانييها … وزمزم والمقام ومن سقاها\nلأنت النفس خالصة ، فإن لم … تكونيها ، فأنت إذا مناها\nنظرت ببطن مكة أم خشف … تبغم ، وهي ناشدة طلاها\nوأعجبني ملامح منك فيها … فقلت أخا القرينة أم تراها ؟\nفلولا أنني رجل حرام … ضممت قرونها ولثمت فاها"},{"id":"diwan-radi:656","bookId":"diwan-radi","type":"poem","seq":656,"chapter":"البحر: رجز تام","title":"يا طالبا ملك بني بويه","page":"","text":"يا طالبا ملك بني بويه … ما أنت من ذاك ولا إليه\nإرث قوام الدين عن أبيه … خل عنان الملك في يديه\nمناضلا يذب عن ثغريه … بديهة الصل جلا نابيه\nيلجلج الموت بماضغيه … يكتلئ الدين بناظريه\nكالمقضب اضطر إلى حديه … نجا الذي فاز بحجزتيه\nوضل مغرور بما لديه … يحتك بالعضب ومضربيه\nشتان من ينفض مذروبه … مخايلا ، ينظر في عطفيه\nما نقل الذابل في كفيه … ومن طوى المجد على غربيه\nمرتقيا إلى ذؤابتيه … إذا المقام لم يقم حوليه\nقام به يركد في حاليه … لا يطرف الهول به جفنيه\nشوك القنا يلدغ أخمصيه … قد قلت للطالب غايتيه\nأقع ، فما غورك من نجديه … ما أنت والطول إلى فرعيه\nسقط شرار طار عن زنديه … من يطلع اليوم ثنيتيه\nقد سبق الناس إلى مجديه … سبق الجواد بقلادتيه\nفي فلك العز إلى قطبيه … يمسي به ثالث نيريه\nأي فتى ينزع في سجليه … قد ورد الماء بجمتيه\nأما ترى الضرغام في غابيه … مزمجرا يفتل ساعديه\nقد أنشب الفريس في ظفريه … هيهات من يغلبه عليه\nأقسمت بالبيت وبانييه … عظم ما عظم من ركنيه\nرب منى ورب مأزميه … ورب من عج بوقفتيه\nعريان إلا معقدي برديه … لقد وسمت الدهر صفحتيه\nيقوده يوضع في عرضيه … قود الضليع مل جاذبيه\nقد أغبط الرحل على دفيه … حتى رأينا نضح ذفرتيه\nيا نفس ضني بك أن تلقيه … عساه يدعوك لأن تريه\nلبيه من داع دعا لبيه … "},{"id":"diwan-radi:657","bookId":"diwan-radi","type":"poem","seq":657,"chapter":"البحر: مجزوء الكامل","title":"عاد الهوى بظباء مك","page":"","text":"عاد الهوى بظباء مك … ة للقلوب كما بداها\nوخبت عليك منى تبا … ريح الغرام وما زهاها\nطربا على طرب بها … يا دين قلبك من جواها\nإني علقت على منى … لمياء يقتلني لماها\nراحت مع الغزلان قد … لعبت بقلبي ، ما كفاها\nتبغي الثواب ، فمهجتي … هذي القريحة من رماها\nتزهو على تلك الظبا … ء فليت شعري من أباها\nوقف الهوى بي عندها … وسرت بقلبي مقلتاها\nبردت علي كأنما … طل الغمامة عارضاها\nشمس أقبل جيدها … يوم النوى ، وأجل فاها\nوأذود قلبا ظامئا … لو قيل : وردك ما عداها\nولو استطاع لقد جرى … مجرى الوشاح على حشاها\nيا يوم مفترق الرفا … ق ترى تعود لملتقاها\nقالت : سيطرقك الخيا … ل من العقيق على نواها\nفعدي بطيفك مقلة … إن غبت تطمع في كراها\nإني شربت من الهوى … حمراء صرف ساقياها\nيا سرحة بالقاع لم … يبلل بغير دمي ثراها\nممنوعة ، لا ظلها … يدنو إلي ولا جناها\nأكذا تذوب عليكم … نفسي ، وما بلغت مناها\nجسد يقلب للضنى … بيدي طبيبة سواها\nأين الوجوه أحبها … وأود لو أني فداها\nأمسى لها متفقدا … في العائدين ولا أراها\nواها ولولا أن يلو … م اللائمون ، لقلت : آها"},{"id":"diwan-radi:658","bookId":"diwan-radi","type":"poem","seq":658,"chapter":"البحر: مجزوء الخفيف","title":"اكبح النفس إن جم","page":"","text":"اكبح النفس إن جم … حت إلى غاية بها\nأنا مولى لشهوتي … وسواي عبد لها\nلا يذل العزيز إلا … لا إذا رام مسها\nلو رأى المستغر ما … ضرر اللهو ما لها"},{"id":"diwan-radi:659","bookId":"diwan-radi","type":"poem","seq":659,"chapter":"البحر: طويل","title":"لمن بعده أسيافه وقناه","page":"","text":"لمن بعده أسيافه وقناه … ومن يولع البيض الرقاق سواه\nفقد كان يرجو أن ينال مناه … فخلفني فردا ، ونال رداه"},{"id":"diwan-radi:660","bookId":"diwan-radi","type":"poem","seq":660,"chapter":"البحر: خفيف تام","title":"علق القلب من أطال عذابي","page":"","text":"علق القلب من أطال عذابي … ورواحي على الجوى وغدوي\nوافترقنا في مذهب الحب شتى … بين تقصيره وبين غلوي\nكان عندي أن الحبيب شقيقي … في التصافي فكان عين عدوي\nساءني ، مذ نأيت ، نسيان ذكري … فاذكروني ولو ذكرت بسو"},{"id":"diwan-radi:661","bookId":"diwan-radi","type":"poem","seq":661,"chapter":"البحر: طويل","title":"أقول لركب رائحين لعلكم","page":"","text":"أقول لركب رائحين لعلكم … تحلون من بعدي العقيق اليمانيا\nخذوا نظرة مني فلاقوا بها الحمى … ونجدا وكثبان اللوى والمطاليا\nومروا على أبيات حي برامة … فقولوا : لديغ يبتغي اليوم راقيا\nعدمت دوائي بالعراق فربما … وجدتم بنجد لي طبيبا مداويا\nوقولوا لجيران على الخيف من منى … تراكم من استبدلتم بجواريا\nومن حل ذاك الشعب بعدي وراشقت … لواحظه تلك الظباء الجوازيا\nومن ورد الماء الذي كنت واردا … به ورعى الروض الذي كنت راعيا\nفوالهفتي كم لي على الخيف شهقة … تذوب عليها قطعة من فؤاديا\nصفا العيش من بعدي لحي على النقا … حلفت لهم لا أقرب الماء صافيا\nفيا جبل الريان إن تعر منهم … فإني سأكسوك الدموع الجواريا\nويا قرب ما أنكرتم العهد بيننا … نسيتم وما استودعتم الود ناسيا\nأأنكرتم تسليمنا ليلة النقا … وموقفنا نرمي الجمار لياليا\nعشية جاراني بعينيه شادن … حديث النوى حتي رمى بي المراميا\nرمى مقتلي من بين سجفي عبيطه … فيا راميا لا مسك السوء راميا\nفيا ليتني لم أعل نشزا إليكم … حراما ولو أهبط من الأرض واديا\nولم أدر ما جمع وما جمرنا منى … ولم ألق في اللاقين حيا يمانيا\nويا ويح قلبي كيف زايدت في منى … بذي البان لا يشرين إلا غواليا\nترحلت عنكم لي أمامي نظرة … وعشر وعشر نحوكم لي ورائيا\nومن حذر لا أسأل الركب عنكم … وأعلاق وجدي باقيات كما هيا\nومن يسأل الركبان عن كل غائب … فلا بد أن يلقى بشيرا وناعيا\nوما مغزل أدماء تزجي بروضة … طلا قاصرا عن غاية السرب وانيا\nلها بغمات خلفه تزعج الحشى … كجس العذارى يختبرن الملاهيا\nيحور إليها بالبغام فتنثني … كما التفت المطلوب يخشى الأعاديا\nبأروع من ظمياء قلبا ومهجة … غداة سمعنا للتفرق داعيا\nتودعنا ما بين شكوى وعبرة … وقد أصبح الركب العراقي غاديا\nفلم أر يوم النفر أكثر ضاحكا … ولم أر يوم النفر أكثر باكيا"},{"id":"diwan-radi:662","bookId":"diwan-radi","type":"poem","seq":662,"chapter":"البحر: مجزوء الخفيف","title":"من رأى أعينا حذ","page":"","text":"من رأى أعينا حذ … ن الدموع الجواريا\nقد عرفن السهاد … تى نكرن اللياليا\nتتبع النجم نظرة … والوميض اليمانيا\nكل يوم يجدن رب … عا من الحي خاليا\nبدموع روائحا … ودماء غواديا\nإن تر الطرف دامعا … فاعلم القلب داميا\nقل لواد على الثو … ية : حييت واديا\nأين قوم عهدتهم … يملؤون المقاريا\nلا يخلى غديرهم … عن حيا الماء ظاميا\nلحبوا المجد وابتنوا … في المعالي مبانيا\nوثبوها ، وغيرهم … صعدوها مراقيا\nمعشر إن بلوتهم … غيبهم والمباديا\nكرموا أنفسا عظا … ما ، وراقوا مجاليا\nوملوك قادوا الرؤ … س مطيعا وآبيا\nلا يبالون في القيا … د الرقاب العواصيا\nوإذا اليوم قربوا … للطعان المذاكيا\nاعجلوا الملجمات أو … ركبوها عواريا\nوسوا في ظهورها … يعلقون النواصيا\nكأسود الشرى ركب … ن الظباء العواطيا\nوإذا ما غدا فم الش … س بالنقع راغيا\nحفظوا عورة العلى … ورقوا للعواليا\nكم رموا بالمطي تلك … ك الحزون الفيافيا\nيعسفون الذرى ويع … تسفون المواميا\nجملوا شحمة السنا … م ، وقد كان واريا\nكل صل يبيت في … مربأ النجم رابيا\nزحمت منهم المنو … ن الجبال الرواسيا\nلم تخف منهم القنا … والدروع الأواقيا\nقلل للعلاء عا … دت ترابا وسافيا\nوعظام البلاء صا … روا عظاما بواليا\nومضوا معقبين إر … ثا من المجد باقيا\nكلما أحرزوا المكا … رم شادوا المعاليا\nفهم اليوم جيرة … لا يجيبون داعيا\nقرع الذل منهم … مارنا كان حاميا\nوأناخوا مناخ من … لم ير الدهر ساريا\nطوحتهم أيدي المنو … ن الغيوب الأقاصيا\nكنبال القاري ير … مي بهن المراميا\nكنت من مجدهم … ل الذرى والروابيا\nوإذا شئت زاحموا … بالقنا من ورائيا\nأقرضوني ، من عزهم … وازن القدر وافيا\nفجزوا إن قضيتهم … من يدي أو لسانيا\nوإذا أعوز الجزا … ء جزيت القوافيا\nوأرى بعدهم موا … مق قومي مراميا\nورجالا قد أعبقوا … بالبرود المخازيا\nإن لقوني أصادقا … فارقوني ، أعاديا\nما ترى الناس كالبها … م يوقعن ضاريا\nكل يوم يجهزو … ن إلى الله غازيا\nويقودون ساليا … عن قليل وناسيا\nريعة الذود قد أم … ن على القرب حاديا\nقد رجعنا ضواحكا … ومضينا بواكيا\nوترى المرء إن رأى … عارض الخطب رانيا\nخافق الجأش ناظرا … من يجيب الدواعيا\nفإذا انجاب ليله … وانجلى عنه ناجيا\nطرح الهم جانبا … وتمنى الأمانيا\nما لهذا الزمان يلقي … قي علينا المراسيا\nكل يوم يجلو علي … خطوبا عودايا\nكم طوى بالردى … صفيا لقلبي مصافيا\nثالث الناظرين … عزا وللنفس ثانيا\nصار بالدمع آمرا … فيه من كان ناهيا\nأغتدي منه عاطلا … بعد ما كنت حاليا\nعطل الكأس لا تح … س النديم المعاطيا\nإن تفض عبرتي تجد … كمد القلب باقيا\nربما تعرف الجوى … وترى الدمع غاليا"},{"id":"diwan-radi:663","bookId":"diwan-radi","type":"poem","seq":663,"chapter":"البحر: خفيف تام","title":"ما مقامي على الهوان وعندي","page":"","text":"ما مقامي على الهوان وعندي … مقول صارم وأنف حمي\nوإباء محلق بي عن الضيم … كما راغ طائر وحشي\nأي عذر له إلى المجد إن ذ … ل غلام في غمده المشرفي\nألبس الذل في ديار الأعادي … وبمصر الخليفة العلوي\nمن أبوه أبي ومولاه مولا … ي إذا ضامني البعيد القصي\nلف عرقي بعرقه سيد النا … س جميعا محمد وعلي\nإن ذلي بذلك الجو عز … وأوامي بذلك النقع ري\nقد يذل العزيز ما لم يشمر … لانطلاق وقد يضام الأبي\nإن شرا علي إسراع عزمي … في طلاب العلى وحظي بطي\nأرتضي بالأذى ولم يقف العز … م قصورا ولم تعز المطي\nكالذي يخبط الظلام وقد أق … مر من خلفه النهار المضي"},{"id":"diwan-radi:664","bookId":"diwan-radi","type":"poem","seq":664,"chapter":"البحر: وافر تام","title":"أتذهل بعد إنذار المنايا","page":"","text":"أتذهل بعد إنذار المنايا … وقبل النزع أنبضت الحنايا\nرويدك لا يغرك كيد دنيا … هي المرنان مصمية الرمايا\nفإنك سالك منها طريقا … تقطع فيه أرقاب المطايا\nأترجو الخلد في دار التفاني … وأمن السرب في خطط البلايا\nوتغلق دون ريب الدهر بابا … كأنك آمن قرع الرزايا ؟\nوإن الموت لازمة قراه … لزوم العهد أعناق البرايا\nلنا في كل يوم منه غاز … له المرباع منا والصفايا\nبجيش لا غبار لحجرتيه … قليل الرزء غرار السرايا\nمغير لا يفادي بالأسارى … وساب لا يمن على السبايا\nإذا قلنا أغب رأيت منه … كميش الذيل يطلع الثنايا\nغشوم الناب تصرف ناجذاه … إذا أبقى أحال على البقايا\nيطيل غرورنا مهل الأماني … وننسى بعده عجل المنايا\nوهذا الدهر تحدوني يداه … حداء الطلح بالإبل الرذايا\nإذا ما قلت روح عقر ظهري … من الإدلاج أغبط بالحوايا\nوإن النائبات لها حماة … وإن كثر الرقاب والربايا\nإذا أبطأن بالغدوات فاعبأ … قرى لضيوفهن مع العشايا\nومن عجب صدود الحظ عنا … إلى المتعممين على الخزايا\nأسف بمن يطير إلى المعالي … وطار بمن يسف إلى الدنايا\nترى لهم المزايا إن أرموا … وإن نطقوا رأيت لنا المزايا\nغباوة هاجر الدنيا ، وكيد … ولا كيد الفواجر والبغايا\nوإن ظهورهم لو كان نصف … من الأنعام أولى بالولايا\nجرت بهم الحظوظ مع القدامى … وأسقطنا الزمان مع الردايا\nففاقوا في المراتب والمعالي … وفقنا في الضرائب والسجايا\nلهم عن مالهم نفحات كيد … قراع الدبر ذاد عن الخلايا\nذممنا كل مرتجع عطاء … ولم يعطوا ، فيرتجعوا العطايا\nفلولا الله لارتابت قلوب … بقاض لا يجور في القضايا"},{"id":"diwan-radi:665","bookId":"diwan-radi","type":"poem","seq":665,"chapter":"البحر: وافر تام","title":"مضى حسب من الدنيا ودين","page":"","text":"مضى حسب من الدنيا ودين … وأعقب منهما عار وغي\nفذاك الطي للماضين نشر … وهذا النشر للباقين طي\nتقدمت الذوائب والقدامى … وخلد بعدها هي وبي\nيعز علي أن يمضى وتبقى … وإن يرد المنون وأنت حي"},{"id":"diwan-radi:666","bookId":"diwan-radi","type":"poem","seq":666,"chapter":"البحر: طويل","title":"أيعلم قبر بالجنينة أننا","page":"","text":"أيعلم قبر بالجنينة أننا … أقمنا به ننعي الندى والمعاليا\nحططنا ، فحيينا مساعيه أنها … عظام المساعي لا العظام البواليا\nمررنا به ، فاستشرفتنا رسومه … كما استشرف الروض الظباء الجوازيا\nوما لاح ذاك الترب حتى تحلبت … من الدمع أوشال ملأن المآقيا\nنزلنا إليه عن ظهور جيادنا … نكفكف بالأيدي الدموع الجواريا\nولما تجاهشنا البكاء ولم نطق … عن الوجد أقلاعا عذرنا البواكيا\nأقول لركب رائحين تعرجوا … أريكم به فرعا من المجد ذاويا\nالموا عليه عاقرين فإننا … إذا لم نجد عقرا عقرنا القوافيا\nوحطوا به رحل المكارم والعلى … وكبوا الجفان عنده والمقاريا\nولو أنصفوا شقوا عليه ضمائرا … وجزوا رقابا بالظبى لا نواصيا\nوقفنا ، فأرخصنا الدموع ، وربما … تكون على سوم الغرام غواليا\nألا أيها القبر الذي ضم لحده … قضيبا على هام النوائب ماضيا\nهل ابن هلال منذ أودى كعهدنا … هلالا على ضوء المطالع باقيا\nوتلك البنان المورقات من الندى … نواضب ماء أو بواق كما هيا\nفإن يبل من ذاك اللسان مضاؤه … فإن به عضوا من المجد باقيا\nيجيب الدواعي جائدا ومدافعا … هناك مرم لا يجيب الدواعيا\nوما كنت آبى طول لبث بقبره … لو أني ، إذا استعديته ، كان عاديا\nترى الكلم الغرات من بعد موته … نوافر عمن رامهن ، نوائيا\nهو الخاضب الأقلام نال بها على … تقاصر عنها الخاضبون العواليا\nمعيد ضراب باللسان لو أنه … بيوم وغى فل الجراز اليمانيا\nمرير القوى نال المعالي واثبا … إذا غيره نال المعالي حابيا\nمضى لم يمانع عنه قلب مشيع … إذا هم لم يرجع عن الهم نابيا\nولا مسندوه بالأكف عن الحشى … على جزع والمفرشوه التراقيا\nولا رد في صدر المنون براحة … يرد بها سمر القنا والمواضيا\nخلا بعدك الوادي الذي كنت أنسه … وأصبح تعروه النوائب واديا\nأراحت علينا ثلة الوجد ترتعي … ضمائرنا أيامها واللياليا\nولولاك كان الصبر منك سجية … تراثا ورثناه الجدود الأواليا\nرضيت بحكم الدهر فيك ضرورة … ومن ذا الذي يغدو بما ساء راضيا\nوطاوعت من رام انتزاعك من يدي … ولو أجد الأعوان أصبحت عاصيا\nوطأمنت كيما يعبر الخطب جانبي … فألقى على ظهري وجر زماميا\nملأت بمحياك البلاد فضائلا … ويملأ مثواك البلاد مناعيا\nكما صم عالي ذكرك الخلق كله … كذاك أقمت العالمين نواعيا\nرثيتك كي أسلوك فازددت لوعة … لأن المراثي لا تسد المرازيا\nوأعلم أن ليس البكاء بنافع … عليك ولكني أمني الأمانيا"},{"id":"diwan-radi:667","bookId":"diwan-radi","type":"poem","seq":667,"chapter":"البحر: طويل","title":"أملتمسا مني صديقا لنوبة","page":"","text":"أملتمسا مني صديقا لنوبة … وأنت صديقي لا أرى لك ثانيا\nلحا الله دهرا خانني فيه أهله … وأحشمني حتى احتشمت الأدانيا\nفلست أرى إلا عدوا مكاشفا … ولست أرى إلا صديقا مداجيا"},{"id":"diwan-radi:668","bookId":"diwan-radi","type":"poem","seq":668,"chapter":"البحر: متقارب تام","title":"أأنكر والمجد عنوانيه","page":"","text":"أأنكر والمجد عنوانيه … ومخبرتي عند أقرانيه\nويعرف غيري بلا ميسم … مبين ، ولا غرة ضاحيه\nألا قاتل الله هذا الأنام … وقاتل ظني وآماليه\nودهرا يمول ذلاته … ولا يدخر العدم إلا ليه\nإذا ما تماثلت من غصة … أعاد المرار فسقانيه\nفيا ليت حظي من ذا الزما … ن رد نوائبه الجاريه\nزمان عدا العي أبناءه … فأفصح من ناطق راغيه\nسؤالا فهل يخبرن سالف … من العيش قطع أقرانيه\nألا أين ذاك الشباب الرطي … ب ، أم أين لي بيض أياميه\nمشى الدهر بيني وبين النعي … م ظلما ، وغير من حاليه\nنظرت وويل أمها نظرة … ببيضاء في عارضي باديه\nيقولون : داعية الشباب … فقلت : ولكنها ناعيه\nألا قطع الناس حبل الوفاء … وأولع بالغدر خلانيه\nوصرت أعدد في ذا الزمان … صديقي أول أعدائيه\nأضر الأنام لي الأقربون … وأعدى الورى لي جيرانيه\nإلى كم أخفض من عزمتي … وكم يأكل العضب أغماديه\nفلله عزمي لو أنه … على قدر عزمي سلطانيه\nستسمع بي شاردا في البلاد … لأمر أغير انسانيه\nوقد أغتدي غرض النائبا … ت ، لا يتقى الروع إلا بيه\nنديما جذيمة لي في البلاد … نديمان والظلمة الداجية\nعليق جيادي شم النسي … والظمء سائق أذواديه\nدفعن فمن مقلة بالدمو … ع ريا ومن مهجة صاديه\nيطرن سوابك جعد اللغام … على القور والقلل السامية\nوفي كل يوم بلا غاية … تقعقع للبين أعماديه\nوأزرق ماء كلون الزجا … ج بالرمل جمته طاميه\nسبقت إليه وفود القطا … فلله سيري وإغذاذيه\nوقد مال جل الدجا والصباح … كشقراء في جدد عاديه\nأرى غمرة يتقيها الرجا … ل محفوفة بالقنا طاغيه\nسألقى بنفسي أهوالها … فإما العلاء أو الداهيه\nأنوما ألذ على ذلة … ويعرى من الذل أضداديه\nوأرعى المنى دون أن أستشير … قنا خالقا وظبى فاريه\nوأعزل ناء عن المكرمات … يرى الموت من دون لقيانيه\nمدحت فكان جزاء المديح … قبول نظامي وأشعاريه\nفصرحت بالذم حتى ترك … ت شنعاء من عرضه داميه\nولم أهجه بهجائي له … ولكن هجوت به القافيه\nألا ما أفيصح هذا الكلام … لو أن له أذنا واعيه\nفلا يذمم الأمل المستغر … ألا ربما ضلت الهاديه\nوقد ينكل المستغير الشجا … ع حينا وتخطي اليد الداميه"},{"id":"diwan-radi:669","bookId":"diwan-radi","type":"poem","seq":669,"chapter":"البحر: مجزوء الكامل","title":"ودجا هتكت قناعه","page":"","text":"ودجا هتكت قناعه … عن وجه طامسة خفيه\nتسري كواكبه إلى الإ … صباح ، والليل المطيه\nوالنجم وجه مقبل … والبدر مرآة صديه"},{"id":"diwan-radi:670","bookId":"diwan-radi","type":"poem","seq":670,"chapter":"البحر: طويل","title":"أراعي بلوغ الشيب والشيب دائيا","page":"","text":"أراعي بلوغ الشيب والشيب دائيا … وأفني الليالي والليالي فنائيا\nوما أدعي أني برىء من الهوى … ولكنني لا يعلم القوم ما بيا\nتلون رأسي ، والرجاء بحاله … وفي كل حال لا تغب الأمانيا\nخليلي هل تثني من الوجد عبرة … وهل ترجع الأيام ما كان ماضيا\nإذا شئت أن تسلى الحبيب فخله … وراءك أياما وجر اللياليا\nأعف وفي قلبي من الحب لوعة … وليس عفيفا تارك الحب ساليا\nإذا عطفتني للحبيب عواطف … أبيت وفات الذل من كان آبيا\nوغيري يستنشي الرياح صبابة … وينشي على طول الغرام القوافيا\nوألقى من الأحباب ما لو لقيته … من الناس سلطت الظبا والعواليا\nفلا تحسبوا أني رضيت بذلة … ولكن حبا غادر القلب راضيا\nرعى الله من ودعته يوم دابق … ووليت أنهى الدمع ما كان جاريا\nوأكتم أنفاسي ، إذا ما ذكرته … وما كل ما تخفيه ، يا قلب ، خافيا\nفعندي زفير ما ترقى من الحشى … وعندي دموع ما طلعن المآقيا\nمضى ما مضى ممن كرهت فراقه … وقد قل عندي الدمع إن كنت باكيا\nولا خير في الدنيا إذا كنت حاضرا … وكان الذي يغرى به القلب نائيا\nإذا الليل واراني خفيت عن الكرى … وأيدي المطايا جنح ليلي إزائيا\nوما طال ليلي غير أن علاقة … بقلبي تستقري بعيني الدراريا\nألا ليت شعري هل أرى غير موجع … وهل ألقين قلبا من الوجد خاليا\nبأي جنان قارح أطلب العلى … وأطمع سيفي أن يبيد الأعاديا\nإذا كنت أعطي النفس في الحب حمها … وأودع قلبي والفؤاد الغوانيا\nولم أدن من ود وقد غاض وده … وإني ، إذا أبدى العدو سفاهة\nتعمدني بالضيم حتى شكوته … ومن يشك لا يعدم من الناس شاكيا\nوإني إذا التاث الصديق قطعته … وإن كان يوما رائحا كنت غاديا\nسجية مضاء على ما يريده … مقض على الأيام ما كان قاضيا\nأرى الماء أحلى من رضاب أذوقه … وأحسن من بيض الثغور الأقاحيا\nوأطيب من داري بلادا أجوبها … إلى العز جوبي بالبنان ردائيا\nورب منى سددت فيه مطالبي … وأي سهام لو بلغن المراميا\nوهم سقيت القلب منه ، وحاجة … ركبت إليها غارب الليل عاريا\nوعارية الأيام عندي نسيئة … أسأت لها قبل الأوان التقاضيا\nأرى الدهر غصابا لما ليس حقه … فلا عجب أن يسترد العواريا\nوما شبت من طول السنين ، وإنما … غبار حروب الدهر غطى سواديا\nوما انحط أولى الشعر حتى نعيته … فبيض هم القلب باقي عذاريا\nأرى الموت داء لا يبل عليله … وما اعتل من لاقى من الدهر شافيا\nفما لي وقرنا لا يغالب كلما … منعت أمامي جاءني من ورائيا\nيحركني من مات لي بسكونه … وتجديد دهري أن أرى الدهر باكيا\nوأبعد شيء منك ما فات عصره … وأقرب شيء منك ما كان جائيا\nولست بخزان لمال وإنما … تراث العلى والفضل والمجد ماليا\nوإتلاف مالي عن حياتي الذلي … ولا خير أن يبقى وأصبح فانيا\nوإني لألقى راحتي في تقنعي … وفي طلب الإثراء طول عنائيا\nوإني إن ألقى صديقا موافقا … وذلك شيء عازب عن رجائيا\nوإن غريب القوم من عاش فيهم … وليس يرى إلا عدوا مداجيا\nوأكثر من تلقاه كالسيف مرهفا … عليك وإن جربته كان نابيا\nوما أنا إلا غمد قلبي فإن مضى … مضيت ، وما لي منة في مضائيا\nوما حملتني العيس إلا مشمرا … لأخرق ليلا أو لأقطع واديا\nطوارح أيد في الليالي كأنها … تجاري إلى الصبح النجوم الجواريا\nإذا ما رحلناها من الصيف ليلة … فلا حل حتى ينظر النجم رائيا\nطواهن طي السير في كل مهمه … ورحن خماصا قد طوين المواميا\nمررن بمياس الثمام وحزنه … خفافا كأطراف العوالي نواجيا\nوكم جاوزت من رملة ثم عاقر … وأخرى يضف الروض فيها الغواديا\nومن نفر لا يعرف الضيف كلبهم … ويسغب حتى يقطع الليل عاويا\nتهاب الندى أيديهم فكأنما … تلاطم من بذل النوال الأثافيا\nوأعلى الورى من وافق الرمح باعه … وكان له في كبة الخيل ساقيا\nوأشرفهم من يطلق الكف بالندى … سخيا ، ببذل المال ، أو متساخيا\nوإن أمير المؤمنين لحابس … ركابي أن أرمي بها ما أماميا\nمعيني على الأيام إن غالبت يدي … وإن كنت معدوا علي وعاديا\nإذا شئت عنه رحلة حط جوده … حقائب أذوادي ورد المثانيا\nولولاه ما انصانت لوجهي طلاوة … ولا كنت إلا شاحب اللون طاويا\nجريأ أروع الوحش في كل ظلمة … وأخلط بالنقع المثار الدياجيا\nهو السيف إن أغمدته كان حازما … وقورا ، وإن جردته كان عاديا\nله كل يوم معرك إن شهدته … ترى قضبا عونا وهاما عذاريا\nيضم عليها جانب النقع بالقنا … يبادرن قدام السيوف التراقيا\nويرسل في الأقران كن خفية … تخال بها طيرا من الريح هافيا\nويثني جوادا من دم الطعن ناعلا … ويزجي نجيبا من وجى السير حافيا\nتسافه في الغارات أشداق خيلها … على اللجم حتى تكرع الماء دميا\nعظيم على غيظ الرجال محسد … غلوب إذا ما جاذبوه المعاليا\nتغاديه إلا في حرام مغامرا … وتلقاه إلا عن نوال محاميا\nوما قصبات السبق إلا لماجد … سعى فاحتوى دون الرجال المساعيا\nأيا علم الإسلام والمجد والعلا … رضيناك مهديا لدين وهاديا\nوما حملتك الخيل إلا رددتها … عن الروع حمرا بالدماء قوانيا\nوشعث النواصي يتخذن دم الطلى … دهانا وأطراف العوالي مداريا\nوغيرك يقتاد الجياد لغارة … ويرجعها ملس الجلود كما هيا\nوما الخيل إلا أن تكون سوابقا … وما الأسد إلا أن تكون ضواريا\nوتترك صبح الجهل يغبر ضوءه … ونقعك أخاذ عليه الضواحيا\nبيوم طراد يصطلي القوم تحته … بنار الحنايا والقنا والمواضيا\nوجرد يناقلن الرماح عوابسا … ويرمين بالعدو القطا والحواميا\nخوارج من ذيل الغبار كأنها … أنامل مقرور دنا النار صاليا\nبكل سنان لا يرى الدرع جنة … وكل حسام لا يرى البيض واقيا\nولا سلم حتى يخضب الحرب أرضها … ويغدو فم البيداء بالنقع راغيا\nإذا ما لقيت الجيش أفنيت جله … ردى ورددت القافلين نواعيا\nوما كل من أومى إلى العز ناله … ودون العلى ضرب يدمي النواصيا\nإلى كم أمني النفس يوما وليلة … وتعلمني الأيام أن لا تلاقيا\nوكم أنا موقوف على كل زفرة … عليل جوى لو أن ناسا دوائيا\nأيسنح لي روضا وأصبح عازبا … ويعرض لي ماء وأصبح صاديا\nوما أنا إلا أن أراك بقانع … وإن كنت جرارا إلي الأعاديا\nتركت إليك الناس طرا وكلهم … يتوق إلى قربي ويهوى مقاميا\nوفارقت أقواما كراما أكفهم … وما ضقت عنهم في البلاد ملاقيا\nويمنعني من عادة الشعر أنني … رأيت لباس الذل بالمال غاليا\nإذا لم أجد بدا من السيف شمته … وفقد ذلول أركب الصعب ماشيا\nفإن كنت لا أعلو على عود منبر … فلست ألاقي غير مجدي عاليا\nعليك سلام الله إني لنازع … إليك ، وإن لم أعط منك مراديا\nودمت دوام الشمس والبدر في الدنا … يجدد أياما وينضو لياليا"},{"id":"diwan-radi:671","bookId":"diwan-radi","type":"poem","seq":671,"chapter":"البحر: طويل","title":"سأصبر إن الصبر مر صدوره","page":"","text":"سأصبر إن الصبر مر صدوره … ألا ربما لذت لقلبي عواقبه\nولا بد أن يعطي على البعد دولة … فنأمنن بينا أو رقيبا نراقبه\nوأرى المعرض باللئيم ، كأنه … \nوأرجع ليس في كفي منه … \nفلا قلب لي إلا وأنت حجابه … ولا سر لي إلا وذكرك حاجبه\nكاينا للأنوف جدعا ورغما … \nأعطش الله كل فرع بنعما … كالسيف يأخذ من بنان الصيقل\nم ودارت على الأعادي رحاكا … جذب الرشاء عن القليب الأطول\nحك رعي الحمى وملوا قراكا … \n … إليها ، ولا دمعي عليها بجامد\nلو حيث يستمع السرار وقفتما … \nحامل بزه على ربذ التق … بأروى وأسنى ما يجود ربيع\nكاد الرجال ، ولا دعي ثقيف … "},{"id":"diwan-radi:672","bookId":"diwan-radi","type":"poem","seq":672,"chapter":"البحر: طويل","title":"خليلي ! هل لي لو ظفرت بنية","page":"","text":"خليلي ! هل لي لو ظفرت بنية … إلى الجزع من وادي الأراك سبيل\nوفي سرعان الريح لي لو علمتما … لا سفير إليك إلا معالي"},{"id":"diwan-radi:673","bookId":"diwan-radi","type":"poem","seq":673,"chapter":"البحر: طويل","title":"نلت ما نلته انفرادا وزاحم","page":"","text":"نلت ما نلته انفرادا وزاحم … غزالا رمى قلبي وراح سليما\nهل أولاك الذين عهدي بهم في … \nلم أجد صانعا سواك ، ولا أع … غزالا على قلبي ، الغداة ، كريها\nتكاد من الإسراع تسبق أمها … بمنتجها ، قبل اللقاح ، أباها\n … سرت عنك إلا عبقة ونسيما\nبعجاج يملأ الأفق دجى ، … وطعان يخضب الأرض بدم"}]};